//! AST → DNIR lowering for typed native programs (no lua_Value, no C-string codegen).
//!
//! Produces graph-observed `native_ir.Module` input for physical realizers. Direct
//! remains canonical; the orthogonal C99 realizer consumes the same DNIR only when
//! explicitly selected and is never an auto, fallback, self-host, or release path.
//!
//! Entry points: Idol modules export functions at file scope (file-as-M). There is no
//! Python/Lua-style mandatory `main()` or special entry typing — any eligible function
//! lowers the same way; linker entry is `@export` / CLI target, not a magic name.
const std = @import("std");
const ast = @import("../ast.zig");
const Expr = ast.Expr;
const types = @import("../types.zig");
const comptime_eval = @import("../comptime.zig");
const decimal = @import("../decimal.zig");
const subject_home = @import("../subject_home.zig");
const dnir = @import("../native/ir.zig");
const dnir_hardware = @import("../dnir_hardware.zig");
const semantic_graph = @import("../graph.zig");
const place = @import("../place.zig");
const home_resolve = @import("../home_resolve.zig");
const tail_result_demand = @import("../tail_result_demand.zig");
const table_facts = @import("../table_facts.zig");
const collection_relation = @import("../collection_relation.zig");
const fieldindex = @import("field.zig");
const summary = @import("../speed/summary.zig");
const RT = types.ResolvedType;

// DNIR only needs the machine class of a pointer. Its exact pointee descriptor
// remains on the semantic graph and on checked application instructions.
var pointer_pointee: RT = .void;
const physical_pointer: RT = .{ .pointer = &pointer_pointee };

pub const Error = error{
    UnsupportedConstruct,
    GraphFactsInvalid,
    OutOfMemory,
};

/// Caller-owned physical evidence for one lowering attempt.
///
/// The fixed buffer keeps refusal reporting allocation-free. A caller may run
/// several lowerings concurrently or sequentially because no evidence lives in
/// process-global state.
pub const Diagnostic = struct {
    site: ?std.builtin.SourceLocation = null,
    note_buffer: [96]u8 = undefined,
    note_len: u8 = 0,
    /// Exact application id when the refusal is about one occurrence.
    /// Null is unknown — never a sentinel zero.
    application: ?semantic_graph.id = null,
    /// Diagnostic projection of the occurrence's relation/method face.
    /// Borrowed from the resident graph or AST; not a second identity.
    relation: ?[]const u8 = null,

    pub fn reset(self: *Diagnostic) void {
        self.site = null;
        self.note_len = 0;
        self.application = null;
        self.relation = null;
    }

    pub fn note(self: *const Diagnostic) ?[]const u8 {
        if (self.note_len == 0) return null;
        return self.note_buffer[0..self.note_len];
    }

    fn record(self: *Diagnostic, site: std.builtin.SourceLocation, detail: ?[]const u8) void {
        self.site = site;
        const text = detail orelse {
            self.note_len = 0;
            return;
        };
        const len = @min(text.len, self.note_buffer.len);
        @memcpy(self.note_buffer[0..len], text[0..len]);
        self.note_len = @intCast(len);
    }
};

fn bail(diagnostic: *Diagnostic, site: std.builtin.SourceLocation) Error {
    diagnostic.record(site, null);
    return error.UnsupportedConstruct;
}

/// The identity-first note: `cause:name`. `gate/realize/census.sh` measured
/// eleven refusal sites handing `bailWith` a bare name — a binding's ident, a
/// record field key, an AST tag — so the note carried provenance where a cause
/// belongs and no reader could group it. The tree already had the correct form
/// on display (`mod-global-written:{s}`, pinned by gate/narrow.sh): identity
/// first, colon, then the name, so a prefix groups and the provenance
/// survives. On overflow the identity survives and the name is dropped, which
/// is the right half to lose.
fn bailNamed(
    diagnostic: *Diagnostic,
    site: std.builtin.SourceLocation,
    cause: []const u8,
    name: []const u8,
) Error {
    var buf: [96]u8 = undefined;
    const note = std.fmt.bufPrint(&buf, "{s}:{s}", .{ cause, name }) catch cause;
    return bailWith(diagnostic, site, note);
}

fn bailWith(diagnostic: *Diagnostic, site: std.builtin.SourceLocation, note: []const u8) Error {
    diagnostic.record(site, note);
    return error.UnsupportedConstruct;
}

fn invalidGraphFacts(diagnostic: *Diagnostic, site: std.builtin.SourceLocation, note: []const u8) Error {
    diagnostic.record(site, note);
    return error.GraphFactsInvalid;
}

fn applicationFace(graph: *const semantic_graph.SemanticGraph, entity: semantic_graph.id) ?[]const u8 {
    const node = graph.get(entity) orelse return null;
    // THE GRAPH IS ASKED FIRST. This read the SPELLING out of `ast_ref` and
    // only consulted the relation when there was no AST pointer, which inverts
    // the one law this whole file is enforcing: the graph knows which relation
    // an occurrence denotes, and the syntax only knows what was typed. They
    // differ exactly where it matters — `tokenizer = rule` then
    // `tokenizer(source)` resolves to relation `token`, and the spelling says
    // `tokenizer`, which `ApplicationFact.applied` exists to keep apart. A
    // refusal that names the applied binding instead of the relation sends the
    // reader to the wrong declaration.
    //
    // The syntax face remains, below, for the occurrence the graph could NOT
    // resolve — which is most of what this projection is asked about, and the
    // only case where a spelling is the best answer available.
    if (graph.applicationRelation(entity)) |relation_id| {
        if (graph.get(relation_id)) |relation| {
            if (relation.name) |name| return name;
        }
    }
    if (node.ast_ref) |raw| {
        const expr: *const Expr = @ptrCast(@alignCast(raw));
        // The chain head, for the reason spelled out on `exprFace`: a curried
        // `f(a)(b)` is a `.call` whose callee is a `.call`, and answering
        // `node.name` for it answered null, because an indirect-callee node
        // carries no name. `exprFace` walks to the head and this defers to it,
        // so the two projections cannot disagree about one occurrence.
        return switch (expr.*) {
            .call => |c| switch (c.func.*) {
                .name => |n| n.ident,
                .field => |f| f.field,
                .call, .method_call => exprFace(expr) orelse node.name,
                else => node.name,
            },
            .method_call => |mc| mc.method,
            else => node.name,
        };
    }
    return node.name;
}

fn bindOccurrence(
    diagnostic: *Diagnostic,
    graph: *const semantic_graph.SemanticGraph,
    occurrence: semantic_graph.id,
) void {
    diagnostic.application = occurrence;
    diagnostic.relation = applicationFace(graph, occurrence);
}

fn refuseApplication(
    diagnostic: *Diagnostic,
    graph: *const semantic_graph.SemanticGraph,
    site: std.builtin.SourceLocation,
    note: []const u8,
    application: semantic_graph.id,
) Error {
    bindOccurrence(diagnostic, graph, application);
    return invalidGraphFacts(diagnostic, site, note);
}

/// THE HEAD OF AN APPLICATION CHAIN, not just its outermost callee.
///
/// A curried application `f(a)(b)` is a `.call` whose `func` is another `.call`,
/// and the two arms below answer only `.name` and `.field`. Everything else fell
/// to null, so `to(str)(x)` — the operation-first face `CLAUDE.md` records as
/// migratable debt, and 17 of the 20 unnamed refusals in `examples/` — refused
/// with no face at all. Measured: 20 of the 141 `missing-application-id`
/// refusals bound no relation, and every one of them was this shape.
///
/// Walking `func` to the head answers `to`, `greet`, `concat` for those sites.
/// That is a SPELLING and this returns it only where the graph already declined
/// — see the note in `applicationFace`, which reserves the syntax face for "the
/// occurrence the graph could NOT resolve". Bounded by construction: each step
/// strictly descends one `func` edge of a finite expression.
fn exprFace(expr: *const Expr) ?[]const u8 {
    return switch (expr.*) {
        .call => |c| switch (c.func.*) {
            .name => |n| n.ident,
            .field => |f| f.field,
            .call, .method_call => exprFace(c.func),
            else => null,
        },
        .method_call => |mc| mc.method,
        else => null,
    };
}

fn refuseMissingApplication(
    ctx: *LowerCtx,
    site: std.builtin.SourceLocation,
    expr: *const Expr,
) Error {
    if (ctx.occurrences.get(expr)) |application| {
        bindOccurrence(ctx.diagnostic, ctx.graph, application.application);
    } else if (ctx.diagnostic.relation == null) {
        ctx.diagnostic.relation = exprFace(expr);
    }
    return invalidGraphFacts(ctx.diagnostic, site, "missing-application-id");
}

/// Module-level compile-time bindings, split by the DNIR value they fold to.
///
/// `ints` came first and was the whole table; a module-level STRING constant
/// had nowhere to live, so `return SEMANTIC_OWNER` fell through the `.name`
/// arm's integer lookup and bailed. `dnir.Value` has carried a `.str` variant
/// all along — a string literal already lowers to one — so the gap was the
/// constant table, not the value representation.
///
/// Two maps rather than a tagged union because every consumer knows which kind
/// it wants: `exprIsStr` asks only `strs`, the numeric-for step asks only
/// `ints`, and a union would make each of them re-check a tag they can't act on.
///
/// String VALUES are not duped: they point into the AST, exactly like the
/// `.quoted` arm's `s.val`, and the AST outlives lowering. Keys are duped
/// because the `Name.field` spelling is formatted, not borrowed.
const ModuleConsts = struct {
    ints: std.StringHashMapUnmanaged(i64) = .empty,
    strs: std.StringHashMapUnmanaged([]const u8) = .empty,
    /// Stable module-level numeric bindings, in the one producer's carrier.
    /// `ma = 0.1` records one tenth exactly; `fa: f64 = 0.1` records the f64
    /// nearest it -- the binding's own float contract is applied at
    /// population, so the fold in lowerBinop never re-derives it. This table
    /// is a stability-checked cache, not a second numeric law: the values
    /// come from comptime_eval and the comparisons are answered by it.
    /// Keys are duped like the other tables; values are plain structs.
    nums: std.StringHashMapUnmanaged(comptime_eval.Value) = .empty,
    /// Module-level positional tables whose every element is text. The function
    /// path carries this in `LowerCtx.str_tables` via `noteStrTable`; a module
    /// binding has no `LowerCtx`, so it is recorded here and read at the same
    /// two places, so both classifiers agree on one read.
    str_tables: std.StringHashMapUnmanaged(void) = .empty,
    /// Single-name module relations, for the compile-stage world. `@(tri(100))`
    /// is evaluation under a stage-delta world (`law.stage.world`), and the
    /// evaluator has been ABLE to run a relation body — `evalWhile`,
    /// `callFunctionValue`, a step budget — the whole time; what it lacked was
    /// any binding for `tri`, because `compileStageValue` hands it an EMPTY
    /// evaluator. This is the same fact channel the comment above describes:
    /// module-level knowledge a `LowerCtx` consumer needs, collected in the one
    /// walk that has the module. Bodies are borrowed from the AST, which
    /// outlives lowering.
    funcs: std.StringHashMapUnmanaged(*const ast.FuncBody) = .empty,
    /// Spellings declared MORE THAN ONCE at module scope. A name-keyed map
    /// would silently keep the last body, and the stage evaluator does no
    /// overload resolution — so `@(pick(1))` could execute a `pick` selected
    /// by collection order rather than by the argument, which is the silent
    /// wrong answer class. A duplicated spelling is removed from `funcs` and
    /// recorded here, so the stage world REFUSES it (`compile-stage-absent`)
    /// instead of guessing; carrying the resolved application identity into
    /// the fold is the correct future, not a spelling coin-flip now.
    func_dups: std.StringHashMapUnmanaged(void) = .empty,

    fn deinit(self: *ModuleConsts, alloc: std.mem.Allocator) void {
        var it = self.ints.iterator();
        while (it.next()) |e| alloc.free(e.key_ptr.*);
        self.ints.deinit(alloc);
        var sit = self.strs.iterator();
        while (sit.next()) |e| alloc.free(e.key_ptr.*);
        self.strs.deinit(alloc);
        var numit = self.nums.iterator();
        while (numit.next()) |e| alloc.free(e.key_ptr.*);
        self.nums.deinit(alloc);
        var tit = self.str_tables.iterator();
        while (tit.next()) |e| alloc.free(e.key_ptr.*);
        self.str_tables.deinit(alloc);
        var fit = self.funcs.iterator();
        while (fit.next()) |e| alloc.free(e.key_ptr.*);
        self.funcs.deinit(alloc);
        var dit = self.func_dups.iterator();
        while (dit.next()) |e| alloc.free(e.key_ptr.*);
        self.func_dups.deinit(alloc);
    }
};

const empty_module_consts: ModuleConsts = .{};
const empty_fp_params: std.StringHashMapUnmanaged([]bool) = .empty;
const empty_relation_edges: std.StringHashMapUnmanaged([]const u8) = .empty;

fn deinitRecord(alloc: std.mem.Allocator, record: dnir.RecordDesc) void {
    alloc.free(record.name);
    for (record.fields) |field| alloc.free(field);
    alloc.free(record.fields);
    alloc.free(record.kinds);
    alloc.free(record.widths);
}

fn deinitFunction(alloc: std.mem.Allocator, function: dnir.Function) void {
    alloc.free(function.name);
    for (function.params) |param| {
        alloc.free(param.name);
        if (param.record) |record| alloc.free(record);
    }
    alloc.free(function.params);
    if (function.ret_pack.len > 0) alloc.free(function.ret_pack);
    if (function.ret_record) |record| alloc.free(record);
    for (function.blocks) |block| {
        for (block.instrs) |instruction| dnir.deinitInstr(alloc, instruction);
        alloc.free(block.instrs);
    }
    alloc.free(function.blocks);
    if (function.absent_applications.len > 0) alloc.free(function.absent_applications);
    if (function.summary_folded_applications.len > 0) alloc.free(function.summary_folded_applications);
}

fn deinitExtern(alloc: std.mem.Allocator, external: dnir.Extern) void {
    alloc.free(external.duo_name);
    alloc.free(external.symbol);
}

fn deinitParam(alloc: std.mem.Allocator, param: dnir.Param) void {
    alloc.free(param.name);
    if (param.record) |record| alloc.free(record);
}

/// Temporary occurrence bridge for the AST-driven realization walker. It
/// carries only the exact graph id already published by semantic resolution;
/// all application facts and packed values remain graph-owned. Delete this
/// bridge when resolver/lowering work items carry the application id directly.
const OccurrenceBridge = struct {
    alloc: std.mem.Allocator,
    graph: *const semantic_graph.SemanticGraph,
    diagnostic: *Diagnostic,
    by_expression: std.AutoHashMapUnmanaged(*const Expr, semantic_graph.id) = .empty,
    unresolved: usize = 0,
    /// The first occurrence this scan found without a published application.
    ///
    /// HELD, NOT REPORTED. This used to be written straight into the shared
    /// `Diagnostic` during the scan, and the scan does not refuse — a
    /// gate-transport module carries unresolved occurrences and keeps lowering.
    /// So the bind outlived its cause, and the next unrelated refusal, which
    /// binds no occurrence of its own, inherited it: a DNB011 naming a call
    /// that had nothing to do with the failure. The id lives here until a
    /// consumer decides to refuse ON it.
    first_unresolved: ?semantic_graph.id = null,
    /// The first unresolved aggregate projection, kept separately so a later
    /// consumer can attribute the aggregate-specific refusal to that exact
    /// occurrence rather than to an unrelated earlier call.
    first_unresolved_aggregate: ?semantic_graph.id = null,

    fn init(
        alloc: std.mem.Allocator,
        graph: *const semantic_graph.SemanticGraph,
        diagnostic: *Diagnostic,
    ) Error!OccurrenceBridge {
        var index: OccurrenceBridge = .{
            .alloc = alloc,
            .graph = graph,
            .diagnostic = diagnostic,
        };
        errdefer index.deinit();

        for (graph.nodes.items, 0..) |node, coordinate| {
            if (node.kind != .call) continue;
            const application: semantic_graph.id = @intCast(coordinate);
            if (graph.application(application) == null) {
                if (graph.isBootstrapApplicationNode(application)) continue;
                index.unresolved += 1;
                if (index.first_unresolved == null) index.first_unresolved = application;
                // Retain the exact producer occurrence for damage handling.
                // `get()` still returns null because the strict application is
                // invalid; `id()` lets the expression walker refuse this graph-
                // owned projection before the legacy place fold can answer it.
                if (graph.isAggregateAccessApplication(application)) {
                    if (index.first_unresolved_aggregate == null)
                        index.first_unresolved_aggregate = application;
                    const expression_raw = node.ast_ref orelse
                        return refuseApplication(diagnostic, graph, @src(), "application-provenance", application);
                    const expression: *const Expr = @ptrCast(@alignCast(expression_raw));
                    const slot = try index.by_expression.getOrPut(alloc, expression);
                    if (slot.found_existing)
                        return refuseApplication(diagnostic, graph, @src(), "application-provenance-collision", application);
                    slot.value_ptr.* = application;
                }
                continue;
            }
            _ = graph.applicationResults(application) orelse
                return refuseApplication(diagnostic, graph, @src(), "application-result-pack", application);
            const expression_raw = node.ast_ref orelse
                return refuseApplication(diagnostic, graph, @src(), "application-provenance", application);
            const expression: *const Expr = @ptrCast(@alignCast(expression_raw));
            const slot = try index.by_expression.getOrPut(alloc, expression);
            if (slot.found_existing)
                return refuseApplication(diagnostic, graph, @src(), "application-provenance-collision", application);
            slot.value_ptr.* = application;
        }
        // A THIRD STORE of occurrence -> value stood here: a rescan of
        // `graph.nodes` reconstructing, in this file, the correspondence the
        // graph already keeps on `Node.ast_ref`. `law.fact.producer.one`:
        // "consumers must not reconstruct facts already owned upstream".
        // `graph.valueByAst` is that same answer asked of its owner.
        return index;
    }

    fn deinit(self: *OccurrenceBridge) void {
        self.by_expression.deinit(self.alloc);
    }

    fn get(self: *const OccurrenceBridge, expression: *const Expr) ?*const semantic_graph.ApplicationFact {
        const application = self.by_expression.get(expression) orelse return null;
        return self.graph.application(application);
    }

    fn id(self: *const OccurrenceBridge, expression: *const Expr) ?semantic_graph.id {
        return self.by_expression.get(expression);
    }

    fn exactValue(self: *const OccurrenceBridge, expression: *const Expr) ?semantic_graph.id {
        return self.graph.valueByAst(expression);
    }
};

const GraphNameDescriptor = union(enum) {
    /// The checked-name producer did not claim this occurrence.
    unvisited,
    /// It visited the occurrence and resolved its binding, but Sema's
    /// descriptor is explicitly unknown. Transitional consumers may ask the
    /// physical module census while this producer domain is being completed.
    unknown,
    known: types.ResolvedType,
};

/// Descriptor of this exact name occurrence through the graph's value and
/// binding facts. Only an exact value -> binding route enters this consumer;
/// edge-less values remain unvisited until the graph publishes a producer-domain
/// completeness certificate that can distinguish refusal from damage.
/// A pre-existing local physical slot remains a transitional realization fact
/// outside this slice; its deletion requires graph-owned place residency.
fn graphNameDescriptor(ctx: *const LowerCtx, expr: *const Expr) GraphNameDescriptor {
    if (expr.* != .name) return .unvisited;
    const value = ctx.occurrences.exactValue(expr) orelse return .unvisited;
    switch (ctx.graph.valueOrigin(value)) {
        .one => {},
        .none, .unknown => return .unvisited,
    }
    const node = ctx.graph.get(value) orelse return .unvisited;
    const descriptor = node.descriptor orelse return .unknown;
    // `.any` is Sema's explicit unknown descriptor, not a proof that the value
    // is non-text/non-numeric. Keep the visited state, but let transitional
    // local residency answer until its own graph place route exists.
    if (descriptor == .any) return .unknown;
    return .{ .known = descriptor };
}

/// Collect top-level constant bindings so a function body can fold them.
///
/// `n = 3` and the literal enum form `kind = { eof = 0, ident = 1 }` are
/// module-level values; nothing registered them as locals, so `Kind.ident`
/// inside a function resolved to a runtime field load and failed with DNB007.
/// Both spellings are compile-time constants and belong as immediates.
/// The module-scope bindings that need REAL STORAGE, and their initializers.
///
/// A file-scope binding nothing writes is correctly folded to its initializer —
/// that is what `ModuleConsts` does and it stays. A binding a FUNCTION writes is
/// one storage location shared by every reader, and folding it is a wrong
/// answer: measured on `examples/native_differential/unsupported/`, `total` read
/// 0 where C read 6, and 5 where C read 8, with exit 0 and no diagnostic.
///
/// The set used to be kept arm-for-arm with `codegen.zig`'s
/// `module_top_level_written_binding`, because that predicate refused these
/// programs while this type had no storage behind it. The storage landed and
/// the refusal is deleted (2026-08-18), so THIS type is now the sole owner of
/// the written-binding set: a name it registers gets a `__bss` word and
/// prologue-store initializer, and every read answers through the map.
const ModuleGlobals = struct {
    /// Name -> the DNIR type its word holds.
    types: std.StringHashMapUnmanaged(RT) = .empty,
    /// Declaration order, so the entry's prologue runs initializers in source
    /// order. A `__bss` word starts zeroed, so only a non-zero initializer
    /// costs an instruction — but the store is emitted for all of them, because
    /// "the zero case happens to need no code" is not a rule anyone can read
    /// off the emitted text later.
    order: std.ArrayListUnmanaged(GlobalInit) = .empty,
    /// THE KEYS THIS TYPE COMPOSED RATHER THAN BORROWED.
    ///
    /// Every scalar key above is an AST identifier, which outlives the compile,
    /// so `Global.name` may borrow it (`native_ir.deinitModule` says so). A
    /// module-scope TABLE FIELD's storage is named `M.x` — a string no AST node
    /// holds — so this type owns it, and the ownership is why a field key is
    /// never published as a `dnir.Global`: that name would escape into the
    /// backend and this list frees it at the end of lowering. A field's initial
    /// content is carried by the module body's own store instead, which is why
    /// only a module WITH a body to run gets field storage at all.
    owned_keys: std.ArrayListUnmanaged([]u8) = .empty,

    fn deinit(self: *ModuleGlobals, alloc: std.mem.Allocator) void {
        for (self.owned_keys.items) |key| alloc.free(key);
        self.owned_keys.deinit(alloc);
        self.types.deinit(alloc);
        self.order.deinit(alloc);
    }

    /// The stored key, so an emitted `Instr.field` points at a string that
    /// outlives the statement composing it. Borrowing a `defer`-freed temporary
    /// here would hand `internInstrStrings` a dangling slice.
    fn storageKey(self: *const ModuleGlobals, name: []const u8) ?[]const u8 {
        return self.types.getKey(name);
    }

    fn has(self: *const ModuleGlobals, name: []const u8) bool {
        return self.types.contains(name);
    }
};

const GlobalInit = struct { name: []const u8, init: ?*const Expr };

const empty_module_globals: ModuleGlobals = .{};

/// Does any FUNCTION in this module assign `name`? Module-level code alone does
/// not force storage: those statements run in order in one entry frame, where a
/// register-resident binding is already correct.
// `moduleFunctionsAssignName` and `stmtsAssignName` STOOD HERE.
//
// They walked every relation body in the module looking for a bare-name
// assignment to a module-scope spelling, with their own shadow rule
// ("a `local`/parameter of the same name SHADOWS the global"), to answer one
// question: does a relation write this module binding. The graph publishes
// exactly that answer now — `SemanticGraph.binding_mutations` names the exact
// BINDING ENTITY the lift resolved the assignment to, and
// `moduleBindingWritten` is
// the query. `law.fact.producer.one`: once a fact is published, a downstream
// phase does not reconstruct it from syntax.
//
// The two answers were compared before the walk was deleted: every `--emit
// asm` output over `examples` and `lib` is byte-identical across the swap,
// with the source path held fixed.

/// HOW MANY TIMES `name` IS ASSIGNED ANYWHERE IN THE MODULE.
///
/// Top-level statements, every nested block, and every relation body. The
/// shadowing rule is the lift's: a `local` of the same name shadows
/// the module binding for the rest of that block, so writes after it are not
/// writes to this name.
fn assignCountInStmts(stmts: []const ast.Stmt, name: []const u8) usize {
    var n: usize = 0;
    for (stmts) |*st| {
        switch (st.*) {
            .assign => |a| for (a.targets) |t| {
                if (t.* == .name and std.mem.eql(u8, t.name.ident, name)) n += 1;
            },
            .local_decl => |ld| for (ld.names) |x| {
                if (std.mem.eql(u8, x.ident, name)) return n;
            },
            .do_block => |b| n += assignCountInStmts(b.body.stmts, name),
            .while_loop => |w| n += assignCountInStmts(w.body.stmts, name),
            .repeat_loop => |r| n += assignCountInStmts(r.body.stmts, name),
            .num_for => |f| n += assignCountInStmts(f.body.stmts, name),
            .gen_for => |f| n += assignCountInStmts(f.body.stmts, name),
            .if_stmt => |is| {
                n += assignCountInStmts(is.then.stmts, name);
                for (is.elseifs) |ei| n += assignCountInStmts(ei.body.stmts, name);
                if (is.else_body) |eb| n += assignCountInStmts(eb.stmts, name);
            },
            .func_decl => |fd| n += assignCountInStmts(fd.func.body.stmts, name),
            else => {},
        }
    }
    return n;
}

/// gap[209]: `collectModuleConsts` recorded a name's DECLARED initializer and
/// never invalidated it, so
///
///     s: i64 = 0 ; k: i64 = 41 ; peek: i64 = () s + 1 ; s = k + 1
///
/// answered `1` where the oracle answers `43` -- compile 0, run 0, no
/// diagnostic. The walk saw one statement form and the language admits four:
/// `s = k + 1` is not an int literal so it never overwrote, and a write nested
/// in a `while` body was never seen at all. `s = 41` "worked" only by accident,
/// because it happens to be a literal.
///
/// A recorded constant is now dropped unless the module writes the name exactly
/// as many times as the recording statement itself accounts for. A bare
/// `name = <literal>` accounts for its own write; a declared binding accounts
/// for none. Anything beyond that -- a later non-literal assignment, a nested
/// write, a write from a relation body -- makes the recorded value stale, and a
/// stale constant is a wrong answer that still compiles.
///
/// `literalBindingOf` already refused to read this map for the same reason, in
/// a different consumer, and wrote down why. This makes the map answer what
/// that comment says it should.
/// Writes to `name` at MODULE scope.
///
/// `assignCountInStmts` carries the nested shadowing rule, which stops
/// counting at a `local_decl` of the name because inside a relation body such a
/// declaration SHADOWS the module binding. At module scope that is exactly
/// wrong: the declaration IS the binding, not a shadow of it. Applying the
/// nested rule here made the count stop at `s: i64 = 0` and never reach
/// `s = k + 1`, so the predicate answered "stable" for the one program gap[209]
/// is about. The declaring statement is skipped; every nested block still keeps
/// the shadow rule, because inside a block it is a shadow again.
fn moduleAssignCount(mod: *const ast.Module, name: []const u8) usize {
    var n: usize = 0;
    for (mod.body.stmts) |*st| {
        switch (st.*) {
            .assign => |a| for (a.targets) |t| {
                if (t.* == .name and std.mem.eql(u8, t.name.ident, name)) n += 1;
            },
            .local_decl, .const_decl, .global_decl => {},
            else => n += assignCountInStmts(st[0..1], name),
        }
    }
    return n;
}

fn moduleConstIsStable(mod: *const ast.Module, name: []const u8, recorded_by_assign: bool) bool {
    const writes = moduleAssignCount(mod, name);
    const owned: usize = if (recorded_by_assign) 1 else 0;
    return writes <= owned;
}

fn typeOfGlobal(t: ast.TypeExpr, init: ?*const Expr) RT {
    // THE FULL WIDTH TABLE, not the shared `resolveType` shortcut: a declared
    // width is a property of the PLACE (gate/narrow.sh), and the shortcut
    // erases i8/i16/u8/u16/u32 to `.any` — which `typeOfGlobal` then defaulted
    // to `.i64`, so `g: i8 = 0` registered as a full-width global and the
    // narrow-width store refusal never fired. Measured: GLOBAL g ty=i64 for a
    // declared i8.
    if (t == .named) {
        const n = t.named;
        if (std.mem.eql(u8, n, "i8")) return .i8;
        if (std.mem.eql(u8, n, "i16")) return .i16;
        if (std.mem.eql(u8, n, "i32")) return .i32;
        if (std.mem.eql(u8, n, "u8")) return .u8;
        if (std.mem.eql(u8, n, "u16")) return .u16;
        if (std.mem.eql(u8, n, "u32")) return .u32;
    }
    const declared = resolveType(t);
    if (declared != .any) return declared;
    const e = init orelse return .i64;
    return switch (e.*) {
        // GAP-145 (`law.text.byte`): the producer quote identity selects the
        // descriptor. A byte-sequence face is not text, so it must not collapse
        // onto `.str` here the way sema/codegen were already forbidden to.
        .quoted => |lit| types.quotedLiteralType(lit.quote),
        .float_lit => .f64,
        else => .i64,
    };
}

/// §18 RESIDENCY, ASKED BY THE STORAGE DECISION ITSELF.
///
/// `ModuleGlobals` registers ONE `__DATA` word per name. That is the right
/// shape for a scalar and no shape at all for a COLLECTION: one word cannot
/// hold three elements, so `constGlobalInit` has nothing to compute and the
/// whole module was refused `global-init-not-constant:<name>` — a refusal whose
/// NAME is not its reason, because `(10, 20, 30)` is as constant as `7`.
///
/// The census already answers the real question. `residencyRefusal(p) == .none`
/// is the proof that the aggregate needs no location anywhere: bound once,
/// never mutated, never aliased, never escaped, every access at a determined
/// index, contents the literal (`place.zig:230`). A binding with that proof is
/// read as an IMMEDIATE per element — by `ModuleConsts` for the folded keys and
/// by `placeElement` for the residency route — and registering a word for it is
/// wrong in both directions: the word cannot be initialized, and
/// `absentModulePlace` declines any name `ModuleGlobals` has taken, so the very
/// fact that says the storage is unnecessary becomes unreachable from the read
/// site.
///
/// FAIL-CLOSED IS PRESERVED BECAUSE THE PROOF IS. `place.analyzeModule` walks
/// relation bodies too (`place.zig:614` -> `walkForeignBody`), so a module
/// table any relation writes — `M = { A = 3 }` with `M.A = 9` — carries
/// `mutation != .no`, earns `Refusal.mutated`, keeps its word, and keeps
/// refusing. This admits only what §18 has already proved absent.
///
/// `init` extends the answer for a SECOND, INDEPENDENT reason a positional
/// aggregate takes no `__DATA` word: every element is a literal of one kind
/// and nothing in the module writes, rebinds or aliases the binding. That is
/// `moduleConstTableKindGraph`'s verdict, and it is what the lowering already
/// records the elements under — without it, `global NAMES = { ... 37 text
/// rows ... }` would still register the binding as a global and the publish
/// step would refuse `global-init-not-constant:NAMES` because
/// `constGlobalInit` cannot fold a table literal into one i64 word.
///
/// The two reasons answer the SAME storage question and stay fail-closed:
/// residencyRefusal is the OLD gate (determinacy must be exact, no alias, no
/// escape), moduleConstTableKindGraph is the NEW gate (every element is a
/// literal of one kind, use is at most `dyn_read`). Either admit is enough;
/// either refuse keeps the word.
fn moduleBindingIsAbsentAggregate(
    alloc: std.mem.Allocator,
    graph: *const semantic_graph.SemanticGraph,
    mod: *const ast.Module,
    name: []const u8,
    init: ?*const Expr,
) Error!bool {
    const p = graph.placeNamed(name) orelse return false;
    if (place.residencyRefusal(p) == .none) return true;
    if (init) |v| {
        if (moduleConstTableKindGraph(graph, true, mod, name, v) != null) return true;
    }
    // A RECORD GLOBAL WITH ALL-CONSTANT NAMED FIELDS TAKES NO WORD. The
    // reads already fold through the "name.field" keys collectModuleConsts
    // records; the word the publish step would register for it exists only
    // to fail `global-init-not-constant` in constGlobalInit, which cannot
    // fold a record literal into one i64. The admission is the record mirror
    // of the positional arm above: every named field is an exact i64 or text
    // constant — the same verdict the const walk records — the census sees
    // no write, rebind, alias or escape, determinacy is exact, and no
    // relation writes a field. Anything else keeps the word.
    const binds_once = switch (p.bindCount()) {
        .exact => |n| n == 1,
        else => false,
    };
    if (p.shape == .record and
        p.facts.mutation == .no and p.facts.immutability == .yes and
        binds_once and
        p.facts.alias == .no and p.facts.escape == .no and
        p.facts.determinacy == .exact and
        !(try moduleHasFieldWrite(alloc, &mod.body, p.binding, name)))
    {
        if (init) |v| {
            if (v.* == .table) {
                var all_const = true;
                for (v.table.fields) |fld| {
                    const nf = switch (fld) {
                        .named => |x| x,
                        else => {
                            all_const = false;
                            break;
                        },
                    };
                    if (graph.exactI64OfExpr(nf.val) == null and !graphTextConst(graph, nf.val)) {
                        all_const = false;
                        break;
                    }
                }
                if (all_const) return true;
            }
        }
    }
    return false;
}

fn collectModuleGlobals(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    graph: *const semantic_graph.SemanticGraph,
) Error!ModuleGlobals {
    var out: ModuleGlobals = .{};
    errdefer out.deinit(alloc);
    for (mod.body.stmts) |*stmt| {
        switch (stmt.*) {
            .local_decl => |ld| for (ld.names, 0..) |n, i| {
                // gap[209]. A MODULE-SCOPE write needs storage exactly as much
                // as a write from a relation body: the name outlives the
                // statement that wrote it and a relation reads it later. The
                // predicate looked only inside relation bodies, so
                // `s: i64 = 0 ... s = k + 1` got neither storage nor a
                // trustworthy constant, and every reader answered the declared
                // initializer.
                if (moduleAssignCount(mod, n.ident) == 0) continue;
                const init: ?*const Expr = if (i < ld.inits.len) ld.inits[i] else null;
                try out.types.put(alloc, n.ident, typeOfGlobal(n.typ, init));
                try out.order.append(alloc, .{ .name = n.ident, .init = init });
            },
            .global_decl => |gd| for (gd.names, 0..) |n, i| {
                // Explicit `global` declarations always get module storage.
                // Function-body assigns to the same name are `store_global`, not
                // a reason to drop the binding — asm_for resetting `_p2` must
                // not erase `global _p2` from the map other functions read.
                //
                // EXCEPT WHERE §18 RULES THE BINDING PHYSICALLY ABSENT, OR
                // THE BINDING IS A POSITIONAL CONSTANT TABLE OF ONE KIND —
                // two independent reasons no `__DATA` word is needed.
                const init: ?*const Expr = if (i < gd.inits.len) gd.inits[i] else null;
                if (try moduleBindingIsAbsentAggregate(alloc, graph, mod, n.ident, init)) continue;
                try out.types.put(alloc, n.ident, typeOfGlobal(n.typ, init));
                try out.order.append(alloc, .{ .name = n.ident, .init = init });
            },
            // gap[108]. `total = 5` with no annotation is not a declaration at
            // all — idol has no `local` keyword, so module scope gets an
            // `.assign`, the same node a function body produces. Missing this
            // arm is what let the untyped spelling run natively and answer
            // wrongly while the annotated one was refused.
            .assign => |as| for (as.targets, 0..) |t, i| {
                if (t.* != .name) continue;
                const name = t.name.ident;
                if (out.types.contains(name)) continue;
                // THE GRAPH'S ANSWER, not a second walk of the same bodies.
                // A relation body that assigns this module binding is a
                // `SemanticGraph.Write` row naming the exact binding entity,
                // and the shadow adjudication that used to live in
                // `stmtsAssignName` lives at the lift where the entity is
                // resolved (gaps/GAP-225.md).
                if (!graph.moduleBindingWritten(name)) continue;
                const init: ?*const Expr = if (i < as.values.len) as.values[i] else null;
                try out.types.put(alloc, name, typeOfGlobal(.inferred, init));
                try out.order.append(alloc, .{ .name = name, .init = init });
            },
            else => {},
        }
    }
    try collectModuleTableFieldGlobals(alloc, mod, &out);
    return out;
}

/// A MODULE-SCOPE TABLE FIELD IS ONE STORAGE LOCATION, exactly as a written
/// module-scope scalar is — this is `ModuleGlobals`' rule one level down.
///
/// `M = {}` / `M.x = 1` / a relation reading `M.x` was the shape the
/// `keyed-table-export` precheck refused. The refusal was honest: the field
/// writes were exploded into keyed LOCALS of whichever body lowered them, so a
/// relation reading `M.x` named a slot the module body had filled in a
/// different frame — measured as `DNB007 fp stack slot 'M.x' has no register`
/// the moment the precheck was lifted. One `__DATA,__bss` word per written
/// field key is the storage that refusal was standing in for.
///
/// WHAT IS REGISTERED, AND WHY EACH CONDITION IS LOAD-BEARING:
///
///   THE MODULE HAS A BODY TO RUN (`program()`, the same predicate that decides
///   whether `root` is emitted at all). A source relation named `main` is an
///   ordinary home-owned relation and cannot replace that body. A field's initial content
///   is a STORE the module body executes, not a load-time word — see
///   `owned_keys`. A library module has no body to run, so registering its
///   fields would give every reader a zero that nothing ever wrote. Those keep
///   today's answer: folded when constant, refused otherwise.
///
///   SOMETHING WRITES THE FIELD after the literal that created it. A field
///   nothing writes is a constant and `ModuleConsts` already folds it correctly
///   everywhere, including inside relation bodies — that is why `M = { A = 3 }`
///   read from a relation was already correct and the precheck was refusing it
///   for a hazard that was not its own.
///
///   THE BINDING IS NOT REBOUND, NOT ITSELF THE TAIL, AND NEVER WRITTEN THROUGH
///   A SUBSCRIPT. `M = other` later, `M` as the module's exported value, or
///   `M["x"] = 1` alongside `M.x` each name the table as a WHOLE, and this pass
///   only ever names its fields. Declining the whole binding keeps the two from
///   describing one table differently.
///
///   EVERY WRITE AGREES ON WHAT THE WORD HOLDS, and it holds `i64` or `f64`. A
///   `str` in this backend is an ADDRESS, and a word whose holding depends on
///   which write ran last is the confident-wrong-number class this project
///   refuses; those fields are declined and refuse at their read site instead.
fn collectModuleTableFieldGlobals(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    out: *ModuleGlobals,
) Error!void {
    if (!mod.program()) return;
    for (mod.body.stmts) |*stmt| {
        switch (stmt.*) {
            .assign => |as| for (as.targets, 0..) |t, i| {
                if (t.* != .name or i >= as.values.len) continue;
                try registerTableFieldGlobals(alloc, mod, out, stmt, t.name.ident, as.values[i]);
            },
            .global_decl => |gd| for (gd.names, 0..) |n, i| {
                if (i >= gd.inits.len) continue;
                try registerTableFieldGlobals(alloc, mod, out, stmt, n.ident, gd.inits[i]);
            },
            .local_decl => |ld| for (ld.names, 0..) |n, i| {
                if (i >= ld.inits.len) continue;
                try registerTableFieldGlobals(alloc, mod, out, stmt, n.ident, ld.inits[i]);
            },
            else => {},
        }
    }
}

/// The module word behind `<base>.<field>`, or null when this body declares its
/// own `base`.
///
/// DELETION WITNESS FOR GAP-221: this function MUST use binding identity from
/// the semantic graph, not spelling-based lookups with a shadow guard. The
/// two-store shape (shadow check followed by spelling lookup) is the defect, not
/// the repair.
///
/// The correct approach: resolve the exact binding the current body sees for
/// `base`, then check if that binding is at module scope. Only when the binding
/// identity is the module-level binding does module storage apply.
/// The binding `name` denotes from the body being lowered, or null when no
/// binding is visible. Relation bodies resolve through their callable; the
/// module body IS module scope, and the module entity is not a callable, so
/// `bindingNamedIn` (which requires one) answers null for every name there.
/// Without this arm the module body's own field writes never reached the
/// `__DATA` word the relation bodies read (GAP-221).
fn baseBindingInBody(ctx: *const LowerCtx, name: []const u8) ?semantic_graph.id {
    if (ctx.module_root) {
        const mod_root = ctx.graph.module_root orelse return null;
        return ctx.graph.resolveBindingInScope(mod_root, name);
    }
    const relation = ctx.function orelse return null;
    return ctx.graph.bindingNamedIn(relation, name);
}

fn moduleFieldWord(ctx: *const LowerCtx, base: []const u8, key: []const u8) ?struct { RT, []const u8 } {
    const base_binding = baseBindingInBody(ctx, base) orelse return null;
    const base_node = ctx.graph.get(base_binding) orelse return null;

    // Only use module storage when the binding is at module scope
    if (base_node.scope != ctx.graph.module_root) return null;

    const gty = ctx.module_globals.types.get(key) orelse return null;
    const storage_key = ctx.module_globals.storageKey(key) orelse return null;
    return .{ gty, storage_key };
}

/// Does `name` own module-scope FIELD storage — i.e. is there any `name.f`
/// word? Asked at every bare mention of the name, because the fields being
/// storage is exactly what leaves the whole table without a value.
///
/// DELETION WITNESS FOR GAP-221: uses binding identity from the semantic graph,
/// not spelling-based lookups with a shadow guard.
fn moduleFieldStorageBase(ctx: *const LowerCtx, name: []const u8) bool {
    const binding = baseBindingInBody(ctx, name) orelse return false;
    const node = ctx.graph.get(binding) orelse return false;

    // Only use module storage when the binding is at module scope
    if (node.scope != ctx.graph.module_root) return false;

    var it = ctx.module_globals.types.keyIterator();
    while (it.next()) |k| {
        const key = k.*;
        if (key.len <= name.len + 1) continue;
        if (key[name.len] != '.') continue;
        if (std.mem.eql(u8, key[0..name.len], name)) return true;
    }
    return false;
}

// ════════════════════════════════════════════════════════════════════════════
// MODULE-BINDING REGISTER PROMOTION ACROSS A LOOP
//
// A module-scope binding is ONE `__DATA,__bss` word (`ModuleGlobals`), so every
// read is `adrp`+`add`+`ldr` and every write `adrp`+`add`+`str`. Inside a loop
// that is per ITERATION: the integer-mix kernel spelled at file scope reloads
// its induction variable three times and its accumulator twice per trip, 24 of
// 37 loop-body instructions being global address arithmetic, against 16 for the
// identical program written inside a relation.
//
// This pass keeps such a binding in a register FOR THE LENGTH OF ONE LOOP:
// one `load_global` before the head, one `store_global` after the exit, and
// nothing in between. It is implemented by putting the name into `ctx.locals`
// for the duration of the loop, because `ctx.locals` is consulted BEFORE
// `ctx.module_globals` at every one of the six sites that decide storage
// (`lowerAssignTarget`, the `.name` read arm, `storePackName`,
// `tryEmitTailAssignStorageReturn`, and the two compound-target arms). There is
// therefore no second decision site to keep in agreement with the first.
//
// ═══ WHY IT IS LAWFUL, AND WHERE EACH OBLIGATION IS DISCHARGED ══════════════
//
// Promotion claims: for every entry state, the promoted loop and the original
// agree on (a) the binding's value everywhere anything can read it, (b) every
// observable effect and its order, (c) termination, (d) traps, and (e) the
// BLOCK VALUE of the statement, which is what the process exit status is made
// of.
//
//   P1 NOTHING ELSE RUNS DURING THE LOOP. `promotableStmt`/`promotableExpr`
//      admit only integer arithmetic, comparison, `if`, nested `while`,
//      `break`, `continue`, and assignment to a bare name. No call, no method
//      call, no `print`, no field, no index, no table, no string, no `req`.
//      So the ONLY code that can read or write the word between the preload
//      and the write-back is the loop body itself, and every one of its reads
//      and writes is redirected to the register. This is what stands in for an
//      escape/alias fact — see the note below on why no such fact exists.
//
//   P2 NO EXIT SKIPS THE WRITE-BACK. `return` is not admitted, so the only
//      ways out of the region are the head's failing test and `break`, and
//      BOTH are patched to `end_idx`, which is the index the write-back is
//      emitted at. `continue` targets `head_idx`, which is inside.
//
//   P3 THE RING IS THE RING. Only a binding whose `ModuleGlobals` type is
//      exactly `.i64` is promoted. `typeOfGlobal` publishes `.i8`/`.u8`/… for
//      a declared narrow width, and a narrow word truncates on every store,
//      so a register-resident copy would run a different machine. Same
//      obligation as `loop_closure`'s L2, and refused the same way.
//
//   P4 NO SHADOW. `local_decl`/`const_decl`/`global_decl` are not admitted in
//      the region, so nothing can rebind the name to a different slot while
//      the promotion is live and leave the write-back describing a stale one.
//      A name already in `ctx.locals` is not a module binding here at all and
//      is never considered (`promotableBindingName`).
//
//   P5 THE TABLE IS NOT ITS FIELDS. A name that also owns module-scope field
//      storage (`M` where `M.x` has a word) is refused: this pass names whole
//      bindings and that one is named one level down.
//
//   P6 THE BLOCK'S VALUE DOES NOT MOVE. The `while` statement is still a
//      `while`; nothing is replaced and no store is written in its slot. This
//      is the GAP-215 obligation (`ast.Stmt.assign.closed_loop`) and the
//      reason this pass discharges it trivially where `loop_closure` had to
//      carry a fact for it.
//
//   P7 A TRAP OR A DIVERGENCE EXPOSES NOTHING. A division trap ends the
//      process before any observer runs, and a loop that does not terminate
//      has no exit at which the word could be read. Neither is a state this
//      pass has to publish, and both are checked as controls rather than
//      assumed.
//
// ═══ THE FACT THAT WAS MISSING, AND WHAT IT DOES AND DOES NOT BUY ══════════
//
// P1 SHOULD have been a published place fact, and until `place.zig` learned to
// mint scalar rows it was not one: `bindPlace` returned early on
// `candidateShape(...) == .unknown` and that function answered
// `.collection`/`.record` only, so a SCALAR module binding had no place row at
// all and `idol graph` printed `"places":[]` for exactly the kernels that carry
// this cost. It now publishes one, with the same six decision facts a
// collection carries. `i` and `acc` in the measured kernel read
// `escape:"no" alias:"no" mutation:"yes" immutability:"no"
// contents_known:"no" bind_origin:"declaration"`.
//
// THAT DOES NOT LET THIS PASS DELETE ITS SYNTACTIC GUARD, and saying otherwise
// would be the wrong answer in the dangerous direction. P1 is a CONJUNCTION:
//
//   (a) nothing else RUNS between the preload and the write-back, and
//   (b) nothing else can REACH the word.
//
// The published `escape`/`alias` answer (b) and only (b). The admitted region
// answers (a) — by refusing every construct that could transfer control. Adding
// the fact consult on top of the region would only NARROW the admitted set
// (a module counter a relation also reads publishes `escape:"yes"` and would be
// refused, while the region already makes the promotion sound for it), which is
// why this pass consults the facts through `probeVerdict` — a measurement that
// changes no lowering — instead of as a second admission clause.
//
// The widening the facts DO license is: admit constructs that transfer control
// (a call, a `print`) inside the region, for bindings whose place row says
// `escape:"no"` — no relation body can name the word, so no callee can observe
// or store the register-resident copy. `DUO_MODULE_PROMOTE_PROBE=1` reports,
// per loop, exactly which loops that reaches. IT IS STILL NOT DONE HERE, AND
// THE REASON IS NOW A COUNT RATHER THAN A CAUTION: it reaches nothing.
//
// ═══ THE FACT-LICENSED WIDENING REACHES ZERO LOOPS. MEASURED ═══════════════
//
// `find examples lib scripts -name '*.id' | grep -v /compile_fail/` — 921
// files, each compiled cold under `DUO_MODULE_PROMOTE_DIAG=1
// DUO_MODULE_PROMOTE_PROBE=1`, from a binary built out of a clean
// `git archive HEAD` tree so a neighbouring lane's working copy could not move
// under the count, and with a private `TMPDIR` so no arm read another's cache.
//
//   132  `while` statements reach this pass at all
//     0  the SHIPPED region admits        (119 `region_shape`, 13 `no_module_binding`)
//     0  the FACT-WIDENED region would admit
//
// The widened region's 132 refusals are the whole answer, and only four of them
// are about a fact:
//
//    87  `probe_no_binding`  no name in the loop is a full-ring module binding
//                            WITH STORAGE. There is nothing to promote: a
//                            module name with no `__bss` word is already
//                            register-resident. No place fact bears on this.
//    41  `probe_shape`       outside even the widened region — `return`, a
//                            declaration, a lambda, `match`, `try`. P2 and P4,
//                            which no place fact answers.
//     3  `probe_no_place`    `examples/boring/{caesar,calculator,palindrome}.id`
//     1  `probe_escape`      `scripts/boring_corpus.id:157`
//
// THE CEILING IS NOT THIS REGION AND NOT A FACT. The corpus spells 1546 `while`
// statements across 303 files; 132 of them reach this pass because only 231 of
// the 921 files reach `ok compile` at all — the other 690 are refused earlier
// (`param-type:any`, `print-arg:any`, `mod-top-stmt:if_stmt`, or the front end).
// Widening this region cannot reach a loop inside a program the direct backend
// declines to lower.
//
// ═══ THE TWO FACTS THAT ARE ACTUALLY MISSING, AND WHAT THEY WOULD BUY ══════
//
// Named exactly, because "consult the facts harder" is not one of them.
//
//   M1 A PLACE ROW FOR A MODULE SCALAR WITH A DERIVED INITIALIZER. The three
//      `probe_no_place` loops share one shape: `b = eval("3*4")` at module
//      scope. `candidateShape` answers `.unknown` for a call initializer, and
//      correctly — `place.zig` is an AST census with no types, a call may
//      return a table, and minting `scalar` there would publish `alias:"no"`
//      off the copy rule for something that is not a scalar. The word IS known
//      to be `.i64` here, but by `ModuleGlobals`, not by the census. The
//      missing fact is a row minted from the graph's TYPE for the binding
//      instead of from its initializer's SYNTAX.
//
//   M2 AN ESCAPE FACT SCOPED TO WHAT THE LOOP CAN CALL. `ForeignReach` takes
//      the union over every relation and alias method in the module and
//      discards which body each mention came from, so `escape:"yes"` means
//      "somebody names the word", never "somebody THIS LOOP CAN REACH names
//      it". The single `probe_escape` loop is precisely that gap:
//      `scripts/boring_corpus.id:157` increments `boringtotal` in a loop whose
//      only calls are `cap` and `runone`, neither of which names it — the
//      mention that sets the fact is in the module's own report code, which
//      does not run during the loop.
//
// AND BOTH TOGETHER MOVE REACH FROM 0 TO 1. M1 alone converts three UNKNOWNs
// into three REFUSALS, not three admissions: `caesar`'s `b`, `calculator`'s `b`
// and `palindrome`'s `a` are each also assigned inside the very relation the
// loop lives in, so a row for them answers `escape:"yes"`. M2 alone admits
// `boringtotal`, whose loop spawns a process per iteration and cannot show a
// register's worth of difference. That is the whole prize, it is measured
// rather than estimated, and it is why the widening is still not taken.

/// SEVERING CONTROL. `true` is the shipped behaviour; `DUO_NO_MODULE_PROMOTE`
/// restores the previous lowering exactly, which is what makes the negative
/// control a control rather than a second measurement.
pub var module_promote_enabled: bool = true;

/// ADMISSION DIAGNOSTIC (`DUO_MODULE_PROMOTE_DIAG`). One line per `while` this
/// pass looks at, naming what it kept or why it kept nothing.
///
/// IT EXISTS BECAUSE THE ALTERNATIVE WAS A BINARY DIFF. Without it the only way
/// to see whether the pass fired on a given program was to compile the program
/// twice and compare the emitted bytes — and that answer is wrong in both
/// directions. It reports a difference where there is none (two arms written to
/// DIFFERENT output names differ in the Mach-O UUID alone, measured: 308 bytes,
/// zero of them in `__text`), and it reports NO difference for three separate
/// reasons that are not each other: the loop was folded away before this pass
/// ran, the names never had `__DATA,__bss` words to begin with, or the region
/// was refused. A transform whose firing can only be inferred from a byte
/// comparison cannot be kept honest, so the reason is published instead.
pub var module_promote_diag: bool = false;

/// WIDENING PROBE (`DUO_MODULE_PROMOTE_PROBE`). MEASUREMENT ONLY: nothing this
/// flag reaches is read by lowering, and `planPromotionsInner` returns the same
/// count with it set as without. It answers one question the header poses and
/// declines to act on — how many loops a fact-licensed widening would reach —
/// with the pass's own predicates, so the number cannot drift from the pass the
/// way a script re-implementing them would.
pub var module_promote_probe: bool = false;

/// Why one `while` kept nothing, or that it kept something. The diagnostic's
/// vocabulary; also the exhaustive list of ways `planPromotions` answers zero.
const PromotionVerdict = enum {
    /// `DUO_NO_MODULE_PROMOTE` — the pass is severed.
    severed,
    /// The loop's condition or body contains a construct outside the admitted
    /// region: a call, a `return`, a declaration, a field, an index, a string.
    region_shape,
    /// The region is admitted, but no name in it is a full-ring module binding
    /// with storage. THE COMMON CASE, and the one that looks like a failure and
    /// is not: a module-scope binding gets a `__bss` word only when it is
    /// declared WITH A TYPE (`collectModuleGlobals`' `.local_decl` arm) or when
    /// a RELATION in the module also assigns it (the `.assign` arm, via the
    /// graph's `moduleBindingWritten`). A bare `i = 0` at module scope in a file
    /// with no relations is neither, so it is already register-resident and
    /// there is nothing here to promote.
    no_module_binding,
    /// More distinct bindings than `max_promoted_bindings`.
    budget,
    admitted,
};
/// Bindings kept in registers for ONE loop. The direct backend gives a
/// loop-carried slot a callee-saved home (`native_backend.planGpStackLocals`
/// pass 1) and has a finite number of them; promoting without a bound would
/// push the rest of the loop onto the frame and trade one memory form for
/// another.
const max_promoted_bindings = 6;

const Promotion = struct {
    /// The `ModuleGlobals` storage key, not the AST spelling — the same string
    /// every other `store_global` site uses, so it outlives lowering.
    name: []const u8,
    slot: u32,
    written: bool,
};

/// THE ADMITTED REGION SHAPE — see P1. Anything not named here refuses the
/// whole loop, so the pass fails closed on every construct it has not been
/// reasoned about.
fn promotableExpr(e: *const ast.Expr) bool {
    return switch (e.*) {
        .int_lit, .true_lit, .false_lit, .name => true,
        .binop => |b| switch (b.op) {
            // `pow` and `concat` reach a runtime helper; `matmul`, `pipeline`
            // and `contains` are applications. None of them is arithmetic that
            // cannot call.
            .add,
            .sub,
            .mul,
            .div,
            .idiv,
            .mod,
            .band,
            .bor,
            .bxor,
            .lshift,
            .rshift,
            .eq,
            .neq,
            .lt,
            .gt,
            .leq,
            .geq,
            .@"and",
            .@"or",
            => promotableExpr(b.lhs) and promotableExpr(b.rhs),
            else => false,
        },
        .unop => |u| switch (u.op) {
            .neg, .not, .bnot => promotableExpr(u.operand),
            // `len` is `s:len()` and `compile` is a meta application.
            else => false,
        },
        else => false,
    };
}

fn promotableBlock(b: *const ast.Block) bool {
    // A tail expression is the block's VALUE. A loop body's tail is lowered by
    // a different path than its statements, and P6 is about not moving values
    // around, so it is refused rather than reasoned about.
    if (b.tail_expr != null) return false;
    for (b.stmts) |*s| {
        if (!promotableStmt(s)) return false;
    }
    return true;
}

fn promotableStmt(s: *const ast.Stmt) bool {
    return switch (s.*) {
        .assign => |a| blk: {
            // A closed loop's residue is value-less (GAP-215) and is not a
            // source assignment; this pass runs before any such rewrite and
            // should never see one.
            if (a.closed_loop) break :blk false;
            if (a.targets.len != a.values.len) break :blk false;
            for (a.targets) |t| {
                if (t.* != .name) break :blk false;
            }
            for (a.values) |v| {
                if (!promotableExpr(v)) break :blk false;
            }
            break :blk true;
        },
        .if_stmt => |f| blk: {
            // `if name = expr` binds a name — P4.
            if (f.binding != null) break :blk false;
            if (!promotableExpr(f.cond)) break :blk false;
            if (!promotableBlock(&f.then)) break :blk false;
            for (f.elseifs) |ei| {
                if (!promotableExpr(ei.cond)) break :blk false;
                if (!promotableBlock(&ei.body)) break :blk false;
            }
            if (f.else_body) |eb| {
                if (!promotableBlock(&eb)) break :blk false;
            }
            break :blk true;
        },
        .while_loop => |w| promotableExpr(w.cond) and promotableBlock(&w.body),
        .brk, .cont => true,
        else => false,
    };
}

/// A name this pass may keep in a register: a module binding with storage, of
/// the full ring (P3), not shadowed by a local (P4), and not the base of
/// module-scope field storage (P5).
fn promotableBindingName(ctx: *const LowerCtx, name: []const u8) bool {
    if (ctx.locals.get(name) != null) return false;
    if (ctx.fused_literals.get(name) != null) return false;
    if (moduleFieldStorageBase(ctx, name)) return false;
    const ty = ctx.module_globals.types.get(name) orelse return false;
    return ty == .i64;
}

const PromoScan = struct {
    found: [max_promoted_bindings][]const u8 = undefined,
    written: [max_promoted_bindings]bool = @splat(false),
    len: usize = 0,
    /// More distinct bindings than the budget. The loop keeps NONE of them —
    /// an arbitrary four out of six is a decision nobody can read off the
    /// emitted text later.
    overflow: bool = false,

    fn note(self: *PromoScan, name: []const u8, is_write: bool) void {
        for (self.found[0..self.len], 0..) |n, i| {
            if (std.mem.eql(u8, n, name)) {
                if (is_write) self.written[i] = true;
                return;
            }
        }
        if (self.len == self.found.len) {
            self.overflow = true;
            return;
        }
        self.found[self.len] = name;
        self.written[self.len] = is_write;
        self.len += 1;
    }
};

fn scanPromotableExpr(ctx: *const LowerCtx, e: *const ast.Expr, scan: *PromoScan) void {
    switch (e.*) {
        .name => |n| if (promotableBindingName(ctx, n.ident)) scan.note(n.ident, false),
        .binop => |b| {
            scanPromotableExpr(ctx, b.lhs, scan);
            scanPromotableExpr(ctx, b.rhs, scan);
        },
        .unop => |u| scanPromotableExpr(ctx, u.operand, scan),
        else => {},
    }
}

fn scanPromotableBlock(ctx: *const LowerCtx, b: *const ast.Block, scan: *PromoScan) void {
    for (b.stmts) |*s| scanPromotableStmt(ctx, s, scan);
}

fn scanPromotableStmt(ctx: *const LowerCtx, s: *const ast.Stmt, scan: *PromoScan) void {
    switch (s.*) {
        .assign => |a| {
            for (a.values) |v| scanPromotableExpr(ctx, v, scan);
            for (a.targets) |t| {
                if (t.* == .name and promotableBindingName(ctx, t.name.ident))
                    scan.note(t.name.ident, true);
            }
        },
        .if_stmt => |f| {
            scanPromotableExpr(ctx, f.cond, scan);
            scanPromotableBlock(ctx, &f.then, scan);
            for (f.elseifs) |ei| {
                scanPromotableExpr(ctx, ei.cond, scan);
                scanPromotableBlock(ctx, &ei.body, scan);
            }
            if (f.else_body) |eb| scanPromotableBlock(ctx, &eb, scan);
        },
        .while_loop => |w| {
            scanPromotableExpr(ctx, w.cond, scan);
            scanPromotableBlock(ctx, &w.body, scan);
        },
        else => {},
    }
}

// ════════════════════════════════════════════════════════════════════════════
// THE WIDENING PROBE — WHAT THE PUBLISHED PLACE FACTS WOULD ADMIT
//
// Everything from here to `planPromotions` is measurement. It is reached only
// under `module_promote_probe`, it returns nothing lowering reads, and it is
// called AFTER `planPromotionsInner` has already decided, so it cannot move a
// decision even by accident.
//
// WHAT IT MODELS. A region widened by exactly the obligations the place facts
// discharge, and by nothing else:
//
//   ADMITTED IN ADDITION to the shipped region — constructs that transfer
//   control or touch memory this pass does not name: calls, method calls,
//   `print` and other effect statements, indexed and field reads and writes,
//   text, `do` blocks, `for` loops. Each is sound for a promoted word ONLY
//   because `escape:"no"` says no relation body can name that word, so no
//   callee reads or stores it.
//
//   STILL REFUSED, because no place fact answers them: `return` (P2 — an exit
//   that skips the write-back), any declaration (P4 — a shadow rebinding the
//   name mid-region), a lambda or macro (the region becomes unbounded), and a
//   `goto`/`match`/`try`/`defer` control shape this pass has never reasoned
//   about.
//
// The verdict is deliberately conservative in the same direction as the pass:
// anything it has not enumerated refuses the loop.
// ════════════════════════════════════════════════════════════════════════════

const ProbeVerdict = enum {
    /// The facts license this loop; the shipped region is what refuses it.
    would_admit,
    /// Outside even the widened region — the facts are not what stands in the
    /// way, so widening on them reaches nothing here.
    probe_shape,
    /// No full-ring module binding to promote (the `no_module_binding` case).
    probe_no_binding,
    /// A named binding has no place row AT ALL. `place.Census` publishes rows
    /// for module scalars; a name with storage and no row is a producer gap,
    /// and `null` means UNKNOWN, never "no place".
    ///
    /// KEPT APART FROM `probe_row_not_module_scalar` BECAUSE THEY NAME
    /// DIFFERENT MISSING THINGS, and the corpus census in this file's header
    /// turns on which one a loop reports. This one says the producer minted
    /// nothing, so the question was never asked; the other says the producer
    /// answered and the answer was about a different kind of location.
    /// Reporting both as "no place" would have read as one gap where there are
    /// two.
    probe_no_place,
    /// A row exists for the name and is not a module scalar — a collection, a
    /// record, or a scalar in some function's region. Not a producer gap: the
    /// census answered, and the answer refuses.
    probe_row_not_module_scalar,
    /// The place row exists and REFUSES: a relation body can reach the word, so
    /// a callee inside the loop could observe the stale `__DATA` copy.
    probe_escape,
    /// The place row exists and cannot rule out a second name for the word.
    probe_alias,
    /// More distinct bindings than the budget.
    probe_budget,
};

fn probeExpr(e: *const ast.Expr) bool {
    return switch (e.*) {
        .int_lit, .float_lit, .true_lit, .false_lit, .nil, .quoted, .name => true,
        .binop => |b| probeExpr(b.lhs) and probeExpr(b.rhs),
        .unop => |u| probeExpr(u.operand),
        .index => |ix| probeExpr(ix.obj) and probeExpr(ix.key),
        .field => |f| probeExpr(f.obj),
        .call => |c| blk: {
            if (!probeExpr(c.func)) break :blk false;
            for (c.args) |a| if (!probeExpr(a)) break :blk false;
            break :blk true;
        },
        .method_call => |m| blk: {
            if (!probeExpr(m.obj)) break :blk false;
            for (m.args) |a| if (!probeExpr(a)) break :blk false;
            break :blk true;
        },
        .if_expr => |i| probeExpr(i.cond) and probeExpr(i.then_expr) and probeExpr(i.else_expr),
        .contains_expr => |v| probeExpr(v.lhs) and probeExpr(v.rhs),
        .range => |r| blk: {
            if (!probeExpr(r.start) or !probeExpr(r.end)) break :blk false;
            if (r.step) |st| if (!probeExpr(st)) break :blk false;
            break :blk true;
        },
        .sequence => |sq| blk: {
            for (sq.exprs) |v| if (!probeExpr(v)) break :blk false;
            break :blk true;
        },
        .table => |t| blk: {
            for (t.fields) |field| {
                const ok = switch (field) {
                    .indexed => |v| probeExpr(v.key) and probeExpr(v.val),
                    .named => |v| probeExpr(v.val),
                    .positional => |v| probeExpr(v),
                    .spread => |v| probeExpr(v),
                    .semantic => |v| probeExpr(v.val),
                };
                if (!ok) break :blk false;
            }
            break :blk true;
        },
        // An early exit is an exit that skips the write-back — P2, which no
        // place fact answers.
        .try_expr, .unwrap_expr => false,
        else => false,
    };
}

fn probeBlock(b: *const ast.Block) bool {
    if (b.tail_expr != null) return false;
    for (b.stmts) |*st| if (!probeStmt(st)) return false;
    return true;
}

fn probeStmt(s: *const ast.Stmt) bool {
    return switch (s.*) {
        .assign => |a| blk: {
            if (a.closed_loop) break :blk false;
            if (a.targets.len != a.values.len) break :blk false;
            for (a.targets) |t| if (!probeExpr(t)) break :blk false;
            for (a.values) |v| if (!probeExpr(v)) break :blk false;
            break :blk true;
        },
        .if_stmt => |f| blk: {
            // `if name = expr` binds a name — P4, unanswered by any place fact.
            if (f.binding != null) break :blk false;
            if (!probeExpr(f.cond)) break :blk false;
            if (!probeBlock(&f.then)) break :blk false;
            for (f.elseifs) |ei| {
                if (!probeExpr(ei.cond)) break :blk false;
                if (!probeBlock(&ei.body)) break :blk false;
            }
            if (f.else_body) |eb| if (!probeBlock(&eb)) break :blk false;
            break :blk true;
        },
        .while_loop => |w| probeExpr(w.cond) and probeBlock(&w.body),
        .repeat_loop => |r| probeBlock(&r.body) and probeExpr(r.cond),
        .do_block => |d| probeBlock(&d.body),
        .num_for => |f| blk: {
            if (!probeExpr(f.start) or !probeExpr(f.stop)) break :blk false;
            if (f.step) |st| if (!probeExpr(st)) break :blk false;
            break :blk probeBlock(&f.body);
        },
        .gen_for => |f| blk: {
            for (f.iters) |it| if (!probeExpr(it)) break :blk false;
            break :blk probeBlock(&f.body);
        },
        .call_stmt => |c| probeExpr(c.expr),
        .expr_stmt => |e| probeExpr(e.expr),
        .brk, .cont => true,
        else => false,
    };
}

fn scanProbeExpr(ctx: *const LowerCtx, e: *const ast.Expr, scan: *PromoScan) void {
    switch (e.*) {
        .name => |n| if (promotableBindingName(ctx, n.ident)) scan.note(n.ident, false),
        .binop => |b| {
            scanProbeExpr(ctx, b.lhs, scan);
            scanProbeExpr(ctx, b.rhs, scan);
        },
        .unop => |u| scanProbeExpr(ctx, u.operand, scan),
        .index => |ix| {
            scanProbeExpr(ctx, ix.obj, scan);
            scanProbeExpr(ctx, ix.key, scan);
        },
        .field => |f| scanProbeExpr(ctx, f.obj, scan),
        .call => |c| {
            scanProbeExpr(ctx, c.func, scan);
            for (c.args) |a| scanProbeExpr(ctx, a, scan);
        },
        .method_call => |m| {
            scanProbeExpr(ctx, m.obj, scan);
            for (m.args) |a| scanProbeExpr(ctx, a, scan);
        },
        .if_expr => |i| {
            scanProbeExpr(ctx, i.cond, scan);
            scanProbeExpr(ctx, i.then_expr, scan);
            scanProbeExpr(ctx, i.else_expr, scan);
        },
        .contains_expr => |v| {
            scanProbeExpr(ctx, v.lhs, scan);
            scanProbeExpr(ctx, v.rhs, scan);
        },
        .range => |r| {
            scanProbeExpr(ctx, r.start, scan);
            scanProbeExpr(ctx, r.end, scan);
            if (r.step) |st| scanProbeExpr(ctx, st, scan);
        },
        .sequence => |sq| for (sq.exprs) |v| scanProbeExpr(ctx, v, scan),
        .table => |t| for (t.fields) |field| switch (field) {
            .indexed => |v| {
                scanProbeExpr(ctx, v.key, scan);
                scanProbeExpr(ctx, v.val, scan);
            },
            .named => |v| scanProbeExpr(ctx, v.val, scan),
            .positional => |v| scanProbeExpr(ctx, v, scan),
            .spread => |v| scanProbeExpr(ctx, v, scan),
            .semantic => |v| scanProbeExpr(ctx, v.val, scan),
        },
        else => {},
    }
}

fn scanProbeBlock(ctx: *const LowerCtx, b: *const ast.Block, scan: *PromoScan) void {
    for (b.stmts) |*st| scanProbeStmt(ctx, st, scan);
}

fn scanProbeStmt(ctx: *const LowerCtx, s: *const ast.Stmt, scan: *PromoScan) void {
    switch (s.*) {
        .assign => |a| {
            for (a.values) |v| scanProbeExpr(ctx, v, scan);
            for (a.targets) |t| {
                if (t.* == .name) {
                    if (promotableBindingName(ctx, t.name.ident)) scan.note(t.name.ident, true);
                } else scanProbeExpr(ctx, t, scan);
            }
        },
        .if_stmt => |f| {
            scanProbeExpr(ctx, f.cond, scan);
            scanProbeBlock(ctx, &f.then, scan);
            for (f.elseifs) |ei| {
                scanProbeExpr(ctx, ei.cond, scan);
                scanProbeBlock(ctx, &ei.body, scan);
            }
            if (f.else_body) |eb| scanProbeBlock(ctx, &eb, scan);
        },
        .while_loop => |w| {
            scanProbeExpr(ctx, w.cond, scan);
            scanProbeBlock(ctx, &w.body, scan);
        },
        .repeat_loop => |r| {
            scanProbeBlock(ctx, &r.body, scan);
            scanProbeExpr(ctx, r.cond, scan);
        },
        .do_block => |d| scanProbeBlock(ctx, &d.body, scan),
        .num_for => |f| {
            scanProbeExpr(ctx, f.start, scan);
            scanProbeExpr(ctx, f.stop, scan);
            if (f.step) |st| scanProbeExpr(ctx, st, scan);
            scanProbeBlock(ctx, &f.body, scan);
        },
        .gen_for => |f| {
            for (f.iters) |it| scanProbeExpr(ctx, it, scan);
            scanProbeBlock(ctx, &f.body, scan);
        },
        .call_stmt => |c| scanProbeExpr(ctx, c.expr, scan),
        .expr_stmt => |e| scanProbeExpr(ctx, e.expr, scan),
        else => {},
    }
}

/// THE CONSULT ITSELF. One module scalar's place row, read for the two facts
/// that answer P1(b).
fn probeOneBinding(ctx: *const LowerCtx, name: []const u8) ProbeVerdict {
    const key = ctx.module_globals.storageKey(name) orelse return .probe_no_binding;
    // `placeNamed` documents `null` as UNKNOWN, never "no place", so it refuses.
    const p = ctx.graph.placeNamed(key) orelse return .probe_no_place;
    if (p.shape != .scalar or p.region != .module) return .probe_row_not_module_scalar;
    if (p.facts.escape != .no) return .probe_escape;
    if (p.facts.alias != .no) return .probe_alias;
    return .would_admit;
}

const ProbeReport = struct { verdict: ProbeVerdict, name: []const u8 = "" };

fn probeVerdict(ctx: *const LowerCtx, ws: anytype) ProbeReport {
    if (!probeExpr(ws.cond) or !probeBlock(&ws.body)) return .{ .verdict = .probe_shape };
    var scan: PromoScan = .{};
    scanProbeExpr(ctx, ws.cond, &scan);
    scanProbeBlock(ctx, &ws.body, &scan);
    if (scan.overflow) return .{ .verdict = .probe_budget };
    if (scan.len == 0) return .{ .verdict = .probe_no_binding };
    for (scan.found[0..scan.len]) |name| {
        const v = probeOneBinding(ctx, name);
        // The NAME is reported, not just the verdict: a count of refusals with
        // no subject cannot be audited, and every refusal here is a claim about
        // one specific word.
        if (v != .would_admit) return .{ .verdict = v, .name = name };
    }
    return .{ .verdict = .would_admit, .name = scan.found[0] };
}

fn reportProbe(ctx: *const LowerCtx, ws: anytype, admitted: usize, line: u32) void {
    if (!module_promote_probe) return;
    // A loop the shipped pass already keeps is not a widening candidate.
    if (admitted > 0) {
        std.debug.print("[module-promote-probe] line {d}: already_admitted\n", .{line});
        return;
    }
    const r = probeVerdict(ctx, ws);
    std.debug.print("[module-promote-probe] line {d}: {s} {s}\n", .{ line, @tagName(r.verdict), r.name });
}

/// Decide the promotions for one `while`. Returns how many entries of `out`
/// were filled; the caller emits the preloads and installs the shadows.
fn planPromotions(ctx: *LowerCtx, ws: anytype, out: *[max_promoted_bindings]Promotion) usize {
    const n = planPromotionsInner(ctx, ws, out);
    // AFTER the decision, and it reads nothing the decision wrote.
    reportProbe(ctx, ws, n, ws.cond.loc().line);
    return n;
}

fn reportVerdict(verdict: PromotionVerdict, out: []const Promotion, line: u32) void {
    if (!module_promote_diag) return;
    if (verdict != .admitted) {
        std.debug.print("[module-promote] line {d}: kept 0 — {s}\n", .{ line, @tagName(verdict) });
        return;
    }
    std.debug.print("[module-promote] line {d}: kept {d}", .{ line, out.len });
    for (out) |p| std.debug.print(" {s}{s}", .{ p.name, if (p.written) "(rw)" else "(r)" });
    std.debug.print("\n", .{});
}

fn planPromotionsInner(ctx: *LowerCtx, ws: anytype, out: *[max_promoted_bindings]Promotion) usize {
    const line: u32 = ws.cond.loc().line;
    if (!module_promote_enabled) {
        reportVerdict(.severed, out[0..0], line);
        return 0;
    }
    if (!promotableExpr(ws.cond) or !promotableBlock(&ws.body)) {
        reportVerdict(.region_shape, out[0..0], line);
        return 0;
    }
    var scan: PromoScan = .{};
    scanPromotableExpr(ctx, ws.cond, &scan);
    scanPromotableBlock(ctx, &ws.body, &scan);
    if (scan.overflow) {
        reportVerdict(.budget, out[0..0], line);
        return 0;
    }
    var n: usize = 0;
    for (scan.found[0..scan.len], 0..) |name, i| {
        const key = ctx.module_globals.storageKey(name) orelse continue;
        out[n] = .{ .name = key, .slot = ctx.freshTemp(), .written = scan.written[i] };
        n += 1;
    }
    reportVerdict(if (n == 0) .no_module_binding else .admitted, out[0..n], line);
    return n;
}

fn registerTableFieldGlobals(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    out: *ModuleGlobals,
    owner: *const ast.Stmt,
    name: []const u8,
    value: *const Expr,
) Error!void {
    if (value.* != .table) return;
    // The whole table named as one value — see the header. Any of these and the
    // binding is left exactly as it is today.
    if (out.types.contains(name)) return;
    if (moduleAssignCount(mod, name) > 1) return;
    if (mod.body.tail_expr) |tail| {
        if (tail.* == .name and std.mem.eql(u8, tail.name.ident, name)) return;
    }
    if (try moduleWritesNameBySubscript(&mod.body, owner, name)) return;

    var fields: std.StringArrayHashMapUnmanaged(RT) = .{};
    defer fields.deinit(alloc);

    // The literal's own fields: the first write, and the one that fixes the
    // holding every later write must agree with.
    for (value.table.fields) |fld| {
        const nf = switch (fld) {
            .named => |x| x,
            else => return, // positional element: not a keyed field at all
        };
        if (nf.val.* == .table) return; // nested table: its leaves, not this key
        const gop = try fields.getOrPut(alloc, nf.key);
        gop.value_ptr.* = typeOfGlobal(.inferred, nf.val);
    }
    // Every write anywhere this binding is still the one `name` reaches —
    // module scope and relation bodies alike, and no scope that rebound it.
    if (!try collectFieldWriteTypes(alloc, &mod.body, owner, name, &fields)) return;

    if (fields.count() == 0) return;
    // A field nothing writes after its literal is a constant `ModuleConsts`
    // already folds. Storage is owed only when a write exists.
    if (!try moduleHasFieldWrite(alloc, &mod.body, owner, name)) return;

    var it = fields.iterator();
    while (it.next()) |entry| {
        switch (entry.value_ptr.*) {
            .i64, .f64 => {},
            else => return,
        }
    }
    it = fields.iterator();
    while (it.next()) |entry| {
        const composed = try std.fmt.allocPrint(alloc, "{s}.{s}", .{ name, entry.key_ptr.* });
        errdefer alloc.free(composed);
        try out.owned_keys.append(alloc, composed);
        try out.types.put(alloc, composed, entry.value_ptr.*);
    }
}

/// SPELLING IS NOT IDENTITY, AND THESE SCANS ONCE DECIDED THAT IT WAS.
///
/// Every scan below asks one question about ONE binding: the module-scope table
/// spelled `name` and declared by the statement `owner`. A relation that
/// declares its own `name` — a parameter, a typed local, a loop variable, an
/// `if name = …` binding — names a DIFFERENT binding, so a write it performs is
/// not a write to the module's table. Matching by spelling counted it as one.
///
/// MEASURED at f5d87d40, with no walker and a plain recursive descent:
///
///     cell: { x: i64 }
///     M = { x = 1 }
///     bump: i64 = ()
///       M: cell = { x = 5 }
///       M.x = 99
///       M.x
///     read: i64 = ()
///       M.x
///
/// `read()` answered 99. The SAME program with the relation's local spelled `N`
/// answered 1, and 1 is the answer: nothing ever writes the module's `M.x`. The
/// shadow's store had reached the module's word. That is the confident wrong
/// number, not the incidental refusal the finding predicted — a bare
/// `M = { x = 5 }` inside the relation is an assignment to the module binding,
/// not a shadow of it, and it is declined earlier by `moduleAssignCount`.
///
/// So the walk stops at the first statement that REBINDS `name` — every later
/// statement in that block reaches the new binding, not this one — and declines
/// to enter a nested scope that binds `name` on entry. `owner` is exempt: at
/// module scope the declaration of the table IS this binding, not a shadow.
///
/// It walks in SOURCE ORDER for the same reason: a write standing before the
/// rebinding statement still names the module's table.
fn walkBindingAssigns(
    block: *const ast.Block,
    owner: *const ast.Stmt,
    name: []const u8,
    visitor: anytype,
) Error!void {
    for (block.stmts) |*st| {
        if (st != owner and stmtRebindsName(st, name)) return;
        switch (st.*) {
            .assign => |a| try visitor.assign(a),
            .do_block => |b| try walkBindingAssigns(&b.body, owner, name, visitor),
            .while_loop => |w| try walkBindingAssigns(&w.body, owner, name, visitor),
            .repeat_loop => |r| try walkBindingAssigns(&r.body, owner, name, visitor),
            .num_for => |f| {
                if (std.mem.eql(u8, f.var_name, name)) continue;
                try walkBindingAssigns(&f.body, owner, name, visitor);
            },
            .gen_for => |f| {
                if (identsBindName(f.vars, name)) continue;
                try walkBindingAssigns(&f.body, owner, name, visitor);
            },
            .func_decl => |fd| {
                if (paramsBindName(fd.func.params, name)) continue;
                try walkBindingAssigns(&fd.func.body, owner, name, visitor);
            },
            .if_stmt => |is| {
                if (is.binding) |b| {
                    if (std.mem.eql(u8, b.name, name)) continue;
                }
                try walkBindingAssigns(&is.then, owner, name, visitor);
                for (is.elseifs) |ei| try walkBindingAssigns(&ei.body, owner, name, visitor);
                if (is.else_body) |eb| try walkBindingAssigns(&eb, owner, name, visitor);
            },
            else => {},
        }
    }
}

/// Does this statement give `name` a NEW binding for the rest of its block? A
/// bare `name = value` does not: it is an assignment, and it was measured to
/// write the enclosing binding (`g = 1` at module scope, `g = 5` in a relation,
/// a second relation reading `g` answered 5). A DECLARATION does.
///
/// `global_decl` is absent deliberately: it names the module global itself.
fn stmtRebindsName(st: *const ast.Stmt, name: []const u8) bool {
    return switch (st.*) {
        .local_decl => |ld| localNamesBind(ld.names, name),
        .const_decl => |cd| std.mem.eql(u8, cd.ident, name),
        .func_decl => |fd| fd.path.len == 1 and std.mem.eql(u8, fd.path[0], name),
        else => false,
    };
}

fn localNamesBind(names: []const ast.LocalName, name: []const u8) bool {
    for (names) |n| {
        if (std.mem.eql(u8, n.ident, name)) return true;
    }
    return false;
}

fn paramsBindName(params: []const ast.FuncParam, name: []const u8) bool {
    for (params) |p| {
        if (std.mem.eql(u8, p.name, name)) return true;
    }
    return false;
}

fn identsBindName(idents: []const []const u8, name: []const u8) bool {
    for (idents) |i| {
        if (std.mem.eql(u8, i, name)) return true;
    }
    return false;
}

/// Does any write name `name` through a SUBSCRIPT (`M["x"] = 1`, `M[i] = 1`)?
/// A subscript write is a write to the table as a whole from this pass's point
/// of view: it names a place these field words do not, and admitting the
/// binding anyway would leave the two spellings writing different storage.
fn moduleWritesNameBySubscript(
    block: *const ast.Block,
    owner: *const ast.Stmt,
    name: []const u8,
) Error!bool {
    var scan = SubscriptWriteScan{ .name = name };
    try walkBindingAssigns(block, owner, name, &scan);
    return scan.found;
}

const SubscriptWriteScan = struct {
    name: []const u8,
    found: bool = false,

    fn assign(self: *SubscriptWriteScan, a: anytype) Error!void {
        for (a.targets) |t| {
            if (t.* != .index) continue;
            if (t.index.obj.* != .name) continue;
            if (std.mem.eql(u8, t.index.obj.name.ident, self.name)) self.found = true;
        }
    }
};

fn moduleHasFieldWrite(
    alloc: std.mem.Allocator,
    block: *const ast.Block,
    owner: *const ast.Stmt,
    name: []const u8,
) Error!bool {
    var writes: std.ArrayListUnmanaged(fieldindex.Write) = .empty;
    defer writes.deinit(alloc);
    var collect = FieldWriteCollector{ .name = name, .writes = &writes, .alloc = alloc };
    try walkBindingAssigns(block, owner, name, &collect);
    if (writes.items.len == 0) return false;
    return try fieldWriteExists(alloc, writes.items, name, writes.items[0].field);
}

const FieldWriteCollector = struct {
    name: []const u8,
    writes: *std.ArrayListUnmanaged(fieldindex.Write),
    alloc: std.mem.Allocator,

    fn assign(self: *FieldWriteCollector, a: anytype) Error!void {
        for (a.targets) |t| {
            if (t.* != .field) continue;
            if (t.field.obj.* != .name) continue;
            if (!std.mem.eql(u8, t.field.obj.name.ident, self.name)) continue;
            try self.writes.append(self.alloc, .{ .owner = 0, .name = self.name, .field = t.field.field, .kind = 0, .shadowed = false });
        }
    }
};

fn fieldWriteExists(alloc: std.mem.Allocator, writes: []const fieldindex.Write, name: []const u8, fld: []const u8) Error!bool {
    var index = try fieldindex.build(alloc, writes);
    defer index.deinit(alloc);
    return fieldindex.hasWrite(&index, writes, 0, name, fld) catch return error.GraphFactsInvalid;
}

fn collectFieldWriteTypes(
    alloc: std.mem.Allocator,
    block: *const ast.Block,
    owner: *const ast.Stmt,
    name: []const u8,
    fields: *std.StringArrayHashMapUnmanaged(RT),
) Error!bool {
    var writes: std.ArrayListUnmanaged(fieldindex.Write) = .empty;
    defer writes.deinit(alloc);
    var collect = FieldTypeCollector{ .name = name, .writes = &writes, .alloc = alloc };
    try walkBindingAssigns(block, owner, name, &collect);
    if (collect.missing) return false;
    if (writes.items.len == 0) return true;
    var index = try fieldindex.build(alloc, writes.items);
    defer index.deinit(alloc);
    var done: usize = 0;
    while (done < writes.items.len) {
        const fld = writes.items[done].field;
        var seen = false;
        var j: usize = 0;
        while (j < done) {
            if (std.mem.eql(u8, writes.items[j].field, fld)) seen = true;
            j += 1;
        }
        done += 1;
        if (seen) continue;
        const agreed = fieldindex.writeKind(&index, writes.items, 0, name, fld) catch return error.GraphFactsInvalid;
        const kind = agreed orelse return false;
        const gop = try fields.getOrPut(alloc, fld);
        if (gop.found_existing) {
            if (fieldTypeKind(gop.value_ptr.*) != kind) return false;
        } else {
            gop.value_ptr.* = switch (kind) {
                1 => .i64,
                2 => .f64,
                else => .str,
            };
        }
    }
    return true;
}

fn fieldTypeKind(ty: RT) u8 {
    return switch (ty) {
        .i64 => 1,
        .f64 => 2,
        .str => 3,
        .array => 4,
        else => 0,
    };
}

const FieldTypeCollector = struct {
    name: []const u8,
    writes: *std.ArrayListUnmanaged(fieldindex.Write),
    alloc: std.mem.Allocator,
    missing: bool = false,

    fn assign(self: *FieldTypeCollector, a: anytype) Error!void {
        for (a.targets, 0..) |t, i| {
            if (t.* != .field) continue;
            if (t.field.obj.* != .name) continue;
            if (!std.mem.eql(u8, t.field.obj.name.ident, self.name)) continue;
            if (i >= a.values.len) {
                self.missing = true;
                continue;
            }
            const ty = typeOfGlobal(.inferred, a.values[i]);
            try self.writes.append(self.alloc, .{ .owner = 0, .name = self.name, .field = t.field.field, .kind = fieldTypeKind(ty), .shadowed = false });
        }
    }
};

/// THE INITIAL CONTENT OF A MODULE GLOBAL'S WORD, AS A LOAD-TIME FACT.
///
/// A module-scope initializer that the compile-time evaluator can run is not an
/// instruction: it is what the storage HOLDS before anything executes. Returning
/// it here is what lets `__DATA,__data` carry it, which is the only realization
/// that is correct in an object, a dylib and an executable at once — the entry
/// prologue that used to carry it existed only when a `main` did.
///
/// FAILS CLOSED, and the caller REFUSES on null rather than emitting a store: an
/// initializer nobody can evaluate at compile time has no load-time image, and a
/// wrong answer outranks a refusal (`law.fallback.zero`).
///
/// `str` is NOT admitted, and that is a REFUSAL rather than an omission. A `str`
/// value in this backend is an ADDRESS into `__cstring`, so its data word needs
/// a relocation in `__DATA`, which the object writer does not emit for that
/// section. Admitting it would put a link-time-unresolved pointer in a word the
/// program dereferences — the confident-wrong-number class this whole change is
/// about. It refuses until the relocation exists.
fn globalInitIsSubjectBinding(init: *const Expr) bool {
    return switch (init.*) {
        .name => true,
        .field => |f| globalInitIsSubjectBinding(f.obj),
        else => false,
    };
}

fn constGlobalInit(init: *const Expr, ty: RT) ?dnir.Value {
    const v = comptime_eval.eval(init) catch return null;
    return switch (v) {
        .int => |n| if (ty == .f64)
            dnir.Value{ .f64 = @floatFromInt(n) }
        else
            dnir.Value{ .i64 = n },
        .decimal => |d| if (ty == .f64)
            dnir.Value{ .f64 = d.toFloat() }
        else
            null,
        .float => |f| if (ty == .f64) dnir.Value{ .f64 = f } else null,
        .bool => |b| if (ty == .f64) null else dnir.Value{ .i64 = @intFromBool(b) },
        .nil => dnir.Value{ .i64 = 0 },
        else => null,
    };
}

/// THE VALUE THE COMPILE-STAGE WORLD HAS FOR THIS EXPRESSION, or null.
///
/// `@(expr)` is `expr` resolved under the current world at the stage that world
/// carries (`law.stage.world`, C0 §52) — equivalently `expr@{ stage = compile }`.
/// So the question this answers is a WORLD LOOKUP, not a peephole: does the
/// compile-stage world hold a value for this expression? A derived world does
/// not fall through to facts absent at formation (`docs/spec/world.md`), and a
/// runtime binding is exactly such a fact, so `null` here is that rule and not
/// an unimplemented case.
///
/// `comptime_eval` IS THE PRODUCER and there is no second one. A local folder
/// over literals would be a second authority for one fact — `constGlobalInit`
/// twenty lines up already asks this same evaluator for the module-init form —
/// and two folders that disagree is the confident-wrong-number class this
/// backend keeps meeting. `eval` takes no bindings, which is precisely why it
/// answers this question correctly: a name bound at run time cannot resolve
/// through it.
///
/// BOTH PASSES CALL THIS ONE. `codegen`'s native-scalar precheck decides
/// ADMISSION and this file decides CAPABILITY; while they were separate rules
/// for the `.compile` unop they disagreed, and the disagreement was a whole
/// face: the precheck rejected every `.compile` over a non-table outright, so
/// `print(@(1 + 2))` — a spelling the evaluator has always been able to fold —
/// refused with `DNB001 compile-nontable` on every program in the corpus that
/// used it.
pub fn compileStageValue(operand: *const Expr) ?dnir.Value {
    const v = comptime_eval.eval(operand) catch return null;
    return switch (v) {
        .int => |n| dnir.Value{ .i64 = n },
        .bool => |b| dnir.Value{ .i64 = @intFromBool(b) },
        .float => |f| dnir.Value{ .f64 = f },
        // A `str` is an address into `__cstring` and a table is a shape, not a
        // scalar. Both are real compile-stage values and neither has a scalar
        // realization here, so they stay with the paths that own them
        // (`moduleConstTableKind` for the descriptor table) rather than being
        // approximated.
        else => null,
    };
}

/// Compile-stage evaluation with the MODULE in scope, which is what makes
/// `@(tri(100))` a value rather than a refusal.
///
/// `compileStageValue` above hands the evaluator an EMPTY environment, so any
/// operand naming a module relation or const failed its first lookup and the
/// whole face refused `compile-stage-absent` — while `evalWhile`,
/// `callFunctionValue` and the `Options.step_limit` fuel have been in the
/// evaluator all along. REALIZATION-CONTRACT (§108) calls lawful nonexecution
/// the ultimate realization; this is that contract executed: the value the
/// stage world holds is what the program contains, and there is no residual
/// operation to realize. C has no spelling for this — a C11 program cannot ask
/// its compiler to run an arbitrary function at build time — so this is
/// exactly the semantic-knowledge frontier `law.ftcftw.dominance` names.
///
/// Scratch lives in an arena and dies here: relation values, captures, locals,
/// and any intermediate the evaluator allocates are freed together, and only
/// the scalar leaves. Nontermination is bounded by the evaluator's own step
/// budget, which `evalWhile` charges per iteration — a compile-stage loop that
/// exceeds it returns null and the face refuses with the honest note.
///
/// THE RETIRED EMITTER'S PRECHECK KEEPS THE NARROWER RULE. `src/codegen.zig`'s
/// native-scalar precheck admits `@( … )` iff the bare `compileStageValue`
/// folds, so on the direct path an operand only THIS function can fold refuses
/// at admission. That disagreement is fail-closed — an honest refusal, never a
/// wrong answer — and widening the retired emitter would be work spent on the
/// side of the seam that `law.bridge.death` deletes.
pub fn compileStageValueInModule(
    alloc: std.mem.Allocator,
    consts: *const ModuleConsts,
    operand: *const Expr,
) ?dnir.Value {
    if (consts.funcs.count() == 0 and consts.ints.count() == 0) return null;
    var arena = std.heap.ArenaAllocator.init(alloc);
    defer arena.deinit();
    const aa = arena.allocator();
    // THE STAGE WORLD GETS A LARGER FUEL BUDGET THAN INCIDENTAL FOLDING. The
    // default `step_limit` exists so that folding the compiler chose to attempt
    // cannot hang a compile the author never asked to wait for. `@( … )` is the
    // opposite situation: the author WROTE "evaluate this at the compile
    // stage", so the budget prices the request rather than the accident —
    // bounded still, because a nonterminating loop must refuse rather than
    // hang, but sized to real work. 200M steps is a few seconds of tree-walk
    // on commodity hardware; past it, the face refuses with the honest note
    // and the program still has the runtime spelling available.
    // `native_fold` is NOT optional here, and the evaluator's own doc block is
    // the reason: admitting relation application without it is a MEASURED
    // silent wrong answer three ways — `/` on two ints routed to the float
    // path (`7 / 2 == 3` folding false), `//` flooring where the backend
    // truncates, `%` taking the divisor's sign where the backend keeps the
    // dividend's, and one flat `locals` stack giving a callee write-through
    // access to same-spelled caller bindings. The switch turns on frames and
    // the backend's integer laws together because they are not independently
    // safe.
    const options: comptime_eval.Options = .{
        .alloc = aa,
        .step_limit = 200_000_000,
        .native_fold = true,
    };

    var scope: std.StringHashMapUnmanaged(comptime_eval.Value) = .empty;
    var fit = consts.funcs.iterator();
    while (fit.next()) |e| {
        // Empty bindings on purpose: captures snapshot nothing, and the call
        // resolves sibling relations through the evaluator's own bindings at
        // application time — which is also what makes recursion work.
        const fv = comptime_eval.funcValue(e.value_ptr.*, .{}, options) catch continue;
        scope.put(aa, e.key_ptr.*, fv) catch return null;
    }
    var cit = consts.ints.iterator();
    while (cit.next()) |e|
        scope.put(aa, e.key_ptr.*, .{ .int = e.value_ptr.* }) catch return null;

    const scopes = [_]std.StringHashMapUnmanaged(comptime_eval.Value){scope};
    const v = comptime_eval.evalWithBindings(
        operand,
        .{ .scopes = &scopes },
        options,
    ) catch return null;
    return switch (v) {
        .int => |n| dnir.Value{ .i64 = n },
        .bool => |b| dnir.Value{ .i64 = @intFromBool(b) },
        .float => |f| dnir.Value{ .f64 = f },
        else => null,
    };
}

fn compileStageAbsentWorld(ctx: *const LowerCtx, operand: *const Expr) ?[]const u8 {
    const scoped: struct { member: []const u8, scope: []const u8 } = switch (operand.*) {
        .call => |c| switch (c.func.*) {
            .field => |f| switch (f.obj.*) {
                .name => |o| .{ .member = f.field, .scope = o.ident },
                else => return null,
            },
            else => return null,
        },
        .index => |ix| switch (ix.obj.*) {
            .field => |f| switch (f.obj.*) {
                .name => |o| .{ .member = f.field, .scope = o.ident },
                else => return null,
            },
            else => return null,
        },
        .field => |f| switch (f.obj.*) {
            .name => |o| .{ .member = f.field, .scope = o.ident },
            else => return null,
        },
        else => return null,
    };
    if (ctx.graph.findFunc(scoped.scope) != null) return null;
    for (ctx.graph.worlds.items) |fact| {
        if (!std.mem.eql(u8, subject_home.homeName(fact.home), scoped.scope)) continue;
        if (!subject_home.homeProvides(fact.home, scoped.member)) continue;
        return subject_home.homeName(fact.home);
    }
    return null;
}

/// THE ONE FACT BOTH PASSES READ.
///
/// `codegen`'s native-scalar precheck decides ADMISSION and this file decides
/// CAPABILITY, in different passes over different state. While they were two
/// separate rules they could disagree, and the disagreement was silent: a table
/// admitted here and unlowerable there fell through to a read that emitted a
/// POINTER, nondeterministically, exit 0. So the rule lives once and both sides
/// call it.
///
/// Answers: is `name`, bound to `value` at module level, a positional table of
/// constants of ONE kind that nothing mutates? Returns the element kind, or
/// null when the shape must not be assumed constant.
/// GAP-145 (`law.text.byte`): a module constant enters `ModuleConsts.strs` only
/// when the producer quote identity is a TEXT face.
///
/// `strs` is the retired unified string identity's last module-level home —
/// `exprIsStr` answers `.str` from it. The byte face carries no text law, so it
/// is not a member.
///
/// MEASURED before this guard. `typeOfGlobal` already routed the same literal
/// through `types.quotedLiteralType`, so ONE literal had TWO answers depending
/// only on which module-binding keyword was written:
///
///     const  j = '{"a":1}' ; j .. "b"   ->  ok, {"a":1}b
///     local  j = '{"a":1}' ; j .. "b"   ->  ok, {"a":1}b
///     global j = '{"a":1}' ; j .. "b"   ->  DNB001 lowerBinop() — concat
///
/// Three spellings of one fact must give one answer.
fn quotedIsModuleTextConst(expr: *const Expr) bool {
    return expr.* == .quoted and !ast.quotedLiteralIsByteSequence(expr.quoted.quote);
}

/// THE SAME QUESTION, ASKED OF THE PRODUCER.
///
/// `quotedIsModuleTextConst` above reads `expr.quoted.quote` off the AST, which
/// makes this file a second authority on text-vs-bytes beside
/// `semantic_graph.publishSourceQuote` — the exact reconstruction `law.md` §1
/// forbids, and the one GAP-207 measured printing a pointer through `%lld` at
/// exit 0. This face reads the DESCRIPTOR the graph already resolved for that
/// literal, so no quote-face rule is spelled here at all.
///
/// It replaces the AST reader at every site that has a graph in scope.
/// `moduleConstTableKind` still calls the AST form because its other caller is
/// `codegen.zig:3722`, and `codegen.zig` imports `semantic_graph` ZERO times
/// (measured at b64dc075) — see the deletion witness in the gap.
fn graphTextConst(graph: *const semantic_graph.SemanticGraph, expr: *const Expr) bool {
    const value = graph.sourceQuoteValue(expr) orelse return false;
    const node = graph.get(value) orelse return false;
    const descriptor = node.descriptor orelse return false;
    return std.meta.activeTag(descriptor) == .str;
}

/// THE BYTE FACE OF THE SAME QUESTION (GAP-145 `law.text.byte`, GAP-207).
///
/// `graphTextConst` answers "is this literal TEXT"; a consumer that reads its
/// negation as "then it is a number" has invented a third face nobody
/// published. This asks the producer the positive question instead, through the
/// same descriptor route, and `types.isQuotedByteSequence` owns the shape.
fn graphByteSequenceConst(graph: *const semantic_graph.SemanticGraph, expr: *const Expr) bool {
    const value = graph.sourceQuoteValue(expr) orelse return false;
    const node = graph.get(value) orelse return false;
    const descriptor = node.descriptor orelse return false;
    return types.isQuotedByteSequence(descriptor);
}

/// The expression produces a BYTE SEQUENCE — a value with element descriptor
/// `byte`, which carries none of the textual law `str` does and is not a
/// number.
///
/// Two routes, both the producer's: the graph descriptor where the occurrence
/// has one, and `byteseq_slots` residency where it does not. The second exists
/// because a NAME occurrence carries no value node of its own — measured on
/// `s = 'abc' ; print(s .. "Z")`, where `graphNameDescriptor` answers
/// `.unvisited` and the physical slot is the only surviving record of what the
/// binding holds.
fn exprIsByteSequence(ctx: *const LowerCtx, expr: *const ast.Expr) bool {
    return switch (expr.*) {
        .quoted => graphByteSequenceConst(ctx.graph, expr),
        .name => |n| blk: {
            switch (graphNameDescriptor(ctx, expr)) {
                .known => |descriptor| break :blk types.isQuotedByteSequence(descriptor),
                .unknown, .unvisited => {},
            }
            const slot = ctx.locals.get(n.ident) orelse break :blk false;
            break :blk ctx.byteseq_slots.contains(slot);
        },
        else => false,
    };
}

pub const ModuleTableKind = enum { int, text };

/// Graph-backed form used by lowering.  The public wrapper below is retained
/// for the codegen admission call, which has no graph handle yet.  Integer
/// content is a graph fact: an absent fact is not permission to fall back to
/// the mutable AST spelling.
fn moduleConstTableKindGraph(
    graph: *const semantic_graph.SemanticGraph,
    require_graph_facts: bool,
    mod: *const ast.Module,
    name: []const u8,
    value: *const Expr,
) ?ModuleTableKind {
    const tbl = switch (value.*) {
        .table => value,
        .unop => |u| if (u.op == .compile and u.operand.* == .table) u.operand else return null,
        else => return null,
    };
    if (tbl.table.fields.len == 0) return null;
    for (tbl.table.fields) |fld| if (fld != .positional) return null;
    var all_int = true;
    var all_text = true;
    for (tbl.table.fields) |fld| {
        if (constIndexOf(graph, require_graph_facts, fld.positional) == null) all_int = false;
        if (!graphTextConst(graph, fld.positional)) all_text = false;
    }
    if (all_int == all_text) return null;
    if (@backingInt(tableUseInBlock(graph, require_graph_facts, &mod.body, name, tbl)) > @backingInt(TableUse.dyn_read)) return null;
    return if (all_int) .int else .text;
}

pub fn moduleConstTableKind(
    mod: *const ast.Module,
    name: []const u8,
    value: *const Expr,
) ?ModuleTableKind {
    // `@({ … })` — comptime eval of a pack — arrives as `.compile` wrapping
    // the table; unwrap before reading. A descriptor is the bare table.
    const tbl = switch (value.*) {
        .table => value,
        .unop => |u| if (u.op == .compile and u.operand.* == .table) u.operand else return null,
        else => return null,
    };
    if (tbl.table.fields.len == 0) return null;
    for (tbl.table.fields) |fld| {
        if (fld != .positional) return null;
    }
    var all_int = true;
    var all_text = true;
    for (tbl.table.fields) |fld| {
        if (ast.intLiteralValue(fld.positional) == null) all_int = false;
        if (!quotedIsModuleTextConst(fld.positional)) all_text = false;
    }
    // One kind or the other, never a mixture: a slot whose holding depends on
    // the index is what no consumer downstream can read correctly.
    if (all_int == all_text) return null;
    // Written, rebound, shadowed or passed on -> nothing may be assumed.
    if (@backingInt(tableUseInBlock(null, false, &mod.body, name, tbl)) > @backingInt(TableUse.dyn_read)) return null;
    return if (all_int) .int else .text;
}

/// Names bound as loop variables by a `for`/`gen for` at module root, outside
/// any relation body. A loop variable reuses the slot of a same-named module
/// binding (the first arm of lowerAssignTarget takes the existing slot), so
/// once the loop runs the slot no longer holds the binding initializer --
/// but moduleConstIsStable counts only syntactic writes and never sees the
/// loop-variable write. Recording such a name as an exact decimal would fold
/// reads after the loop to the stale initializer. Function bodies are not
/// descended into: there comparisonNameShadowed already declines shadowed
/// names.
fn collectModuleForVarNames(alloc: std.mem.Allocator, mod: *const ast.Module) Error!std.StringHashMapUnmanaged(void) {
    var out: std.StringHashMapUnmanaged(void) = .empty;
    errdefer {
        var it = out.iterator();
        while (it.next()) |e| alloc.free(e.key_ptr.*);
        out.deinit(alloc);
    }
    try forVarNamesInStmts(alloc, mod.body.stmts, &out);
    return out;
}

fn forVarNamesInStmts(
    alloc: std.mem.Allocator,
    stmts: []const ast.Stmt,
    out: *std.StringHashMapUnmanaged(void),
) Error!void {
    for (stmts) |*st| {
        switch (st.*) {
            .num_for => |f| {
                {
                    if (out.contains(f.var_name)) break;
                    const key = try alloc.dupe(u8, f.var_name);
                    errdefer alloc.free(key);
                    try out.put(alloc, key, {});
                }
                try forVarNamesInStmts(alloc, f.body.stmts, out);
            },
            .gen_for => |g| {
                for (g.vars) |v| {
                    if (out.contains(v)) continue;
                    const key = try alloc.dupe(u8, v);
                    errdefer alloc.free(key);
                    try out.put(alloc, key, {});
                }
                try forVarNamesInStmts(alloc, g.body.stmts, out);
            },
            .do_block => |d| try forVarNamesInStmts(alloc, d.body.stmts, out),
            .while_loop => |w| try forVarNamesInStmts(alloc, w.body.stmts, out),
            .repeat_loop => |r| try forVarNamesInStmts(alloc, r.body.stmts, out),
            .if_stmt => |s| {
                try forVarNamesInStmts(alloc, s.then.stmts, out);
                for (s.elseifs) |ei| try forVarNamesInStmts(alloc, ei.body.stmts, out);
                if (s.else_body) |eb| try forVarNamesInStmts(alloc, eb.stmts, out);
            },
            .match_stmt => |m| for (m.arms) |arm| try forVarNamesInStmts(alloc, arm.body.stmts, out),
            .try_stmt => |t| {
                try forVarNamesInStmts(alloc, t.body.stmts, out);
                for (t.catches) |c| try forVarNamesInStmts(alloc, c.body.stmts, out);
                for (t.defers) |d| try forVarNamesInStmts(alloc, d.body.stmts, out);
            },
            .defer_stmt => |d| try forVarNamesInStmts(alloc, d.body.stmts, out),
            else => {},
        }
    }
}

/// A stable module binding's numeric value in the producer's carrier, or
/// null when the initializer is not an exact-decimal fact. Names chain on the
/// tables built so far, so `b = a` sees an earlier binding; an integer
/// constant chains as its exact decimal, the way the old init scope did.
/// Anything else -- a rounded float, a string, a call the empty scope cannot
/// answer -- declines, and the binding simply is not recorded.
fn moduleConstNumeric(
    alloc: std.mem.Allocator,
    init: *const Expr,
    nums: *const std.StringHashMapUnmanaged(comptime_eval.Value),
    ints: *const std.StringHashMapUnmanaged(i64),
) ?comptime_eval.Value {
    var scope: std.StringHashMapUnmanaged(comptime_eval.Value) = .empty;
    defer scope.deinit(alloc);
    var nit = nums.iterator();
    while (nit.next()) |e| scope.put(alloc, e.key_ptr.*, e.value_ptr.*) catch return null;
    var iit = ints.iterator();
    while (iit.next()) |e| scope.put(alloc, e.key_ptr.*, .{ .int = e.value_ptr.* }) catch return null;
    const scopes = [_]std.StringHashMapUnmanaged(comptime_eval.Value){scope};
    const v = comptime_eval.evalWithBindings(init, .{ .scopes = &scopes }, .{
        .step_limit = 10_000,
        .alloc = alloc,
    }) catch return null;
    return switch (v) {
        .decimal => v,
        .int => |n| .{ .decimal = decimal.fromInt(n) },
        else => null,
    };
}

fn collectModuleConsts(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    graph: *const semantic_graph.SemanticGraph,
    require_graph_facts: bool,
) Error!ModuleConsts {
    var out: ModuleConsts = .{};
    errdefer out.deinit(alloc);
    const map = &out.ints;
    // Loop variables at module root reuse a same-named binding slot (see
    // collectModuleForVarNames); exclude them before any recording.
    var for_var_names = try collectModuleForVarNames(alloc, mod);
    defer {
        var fvit = for_var_names.iterator();
        while (fvit.next()) |e| alloc.free(e.key_ptr.*);
        for_var_names.deinit(alloc);
    }
    for (mod.body.stmts) |*stmt| {
        var name: ?[]const u8 = null;
        var val: ?*const Expr = null;
        var typ: ?ast.TypeExpr = null;
        switch (stmt.*) {
            .assign => |as| {
                if (as.targets.len == 1 and as.values.len == 1 and as.targets[0].* == .name) {
                    name = as.targets[0].name.ident;
                    val = as.values[0];
                }
            },
            .local_decl => |ld| {
                if (ld.names.len == 1 and ld.inits.len == 1) {
                    name = ld.names[0].ident;
                    val = ld.inits[0];
                    typ = ld.names[0].typ;
                }
            },
            // `const WIDTH: i64 = 80` — the DECLARED form of the same thing
            // `WIDTH = 80` says, and the only one of the three that was not
            // collected. So a module using the explicit spelling had every
            // reference to it fail to resolve in lowering (mandelbrot bailed on
            // `HEIGHT`), while the bare assignment folded fine.
            .const_decl => |cd| {
                name = cd.ident;
                val = cd.val;
                typ = cd.typ;
            },
            .global_decl => |gd| {
                if (gd.names.len == 1 and gd.inits.len == 1) {
                    name = gd.names[0].ident;
                    val = gd.inits[0];
                    typ = gd.names[0].typ;
                }
            },
            .enum_def => |ed| {
                for (ed.variants, 0..) |v, i| {
                    const key = try std.fmt.allocPrint(alloc, "{s}.{s}", .{ ed.name, v.name });
                    try map.put(alloc, key, @intCast(i));
                }
                continue;
            },
            // The single-name relations, for compile-stage evaluation. Dotted
            // paths stay out: a home-qualified relation is a cross-partition
            // question and the stage world answers module-local ones.
            .func_decl => |*fd| {
                if (fd.path.len == 1) {
                    const spelled = fd.path[0];
                    if (out.func_dups.contains(spelled)) continue;
                    if (out.funcs.fetchRemove(spelled)) |prev| {
                        // Second declaration under one spelling: poison it.
                        // See `func_dups` — a name-keyed map kept the LAST
                        // body, and last-wins is a coin-flip, not resolution.
                        alloc.free(prev.key);
                        const dup = try alloc.dupe(u8, spelled);
                        errdefer alloc.free(dup);
                        try out.func_dups.put(alloc, dup, {});
                        continue;
                    }
                    const key = try alloc.dupe(u8, spelled);
                    errdefer alloc.free(key);
                    try out.funcs.put(alloc, key, &fd.func);
                }
                continue;
            },
            else => {},
        }
        const n = name orelse continue;
        const v = val orelse continue;
        // gap[209]. A recorded value that the module later overwrites is a
        // wrong answer that still compiles; refusing to record it makes the
        // reference resolve through storage instead.
        if (!moduleConstIsStable(mod, n, stmt.* == .assign)) continue;
        if (graph.exactI64OfExpr(v)) |iv| {
            try map.put(alloc, try alloc.dupe(u8, n), iv);
            continue;
        }
        if (graphTextConst(graph, v)) {
            try out.strs.put(alloc, try alloc.dupe(u8, n), v.quoted.val);
            continue;
        }
        // Exact numeric constants, valued by the one producer. The guards are
        // unchanged: moduleConstIsStable counts syntactic writes; the graph
        // fact catches what it cannot see; loop variables are excluded
        // outright (see collectModuleForVarNames). A name that survives all
        // three names one value for the whole module, so the fold in
        // lowerBinop may answer comparisons from it. The binding's own float
        // contract is applied here: `fa: f64 = 0.1` records the f64 nearest
        // one tenth, unqualified `ma = 0.1` records one tenth exactly.
        if (!for_var_names.contains(n) and graph.moduleBindingConstant(n)) {
            if (moduleConstNumeric(alloc, v, &out.nums, &out.ints)) |num| {
                if (num == .decimal) {
                    const contracted = if (typ) |t|
                        comptime_eval.Evaluator.applyFloatContract(
                            num,
                            comptime_eval.Evaluator.floatContractOfType(t),
                        )
                    else
                        num;
                    try out.nums.put(alloc, try alloc.dupe(u8, n), contracted);
                    continue;
                }
            }
        }
        // A descriptor is a bare `{ ... }`. `@({ ... })` is comptime eval of a
        // pack and parses as a `.compile` unop wrapping the table, so unwrap
        // before reading fields. The sigil was the descriptor spelling until
        // `law.injection.only` retired it (fd85e7b8); it no longer parses.
        const tbl = switch (v.*) {
            .table => v,
            .unop => |u| if (u.op == .compile and u.operand.* == .table) u.operand else continue,
            else => continue,
        };
        // A FIELD SOMETHING WRITES IS NOT A CONSTANT.
        //
        // `moduleConstIsStable` above counts writes to the BINDING (`M = …`);
        // it cannot see `M.A = 9`, so a table whose fields a relation writes
        // still had every field folded to its literal. That was masked for as
        // long as such a table also got FIELD STORAGE, because the
        // reconciliation in `lowerModuleFromGraph` deletes a const whose key
        // owns a word. `registerTableFieldGlobals` only registers fields for a
        // module with a body to run, so a module of bindings plus relations —
        // the shape `Module.program()` now classifies correctly — got no
        // storage and answered the stale literal instead. Measured: `M = { A =
        // 3 }`, a relation writing `M.A = 9`, and a later read answering 3.
        //
        // Declining to record it is the fail-closed half: where storage exists
        // the read resolves through the word, and where it does not the read
        // has no fact to answer from and refuses.
        if (try moduleHasFieldWrite(alloc, &mod.body, stmt, n)) continue;
        for (tbl.table.fields) |fld| {
            const nf = switch (fld) {
                .named => |x| x,
                else => continue,
            };
            if (graph.exactI64OfExpr(nf.val)) |fv| {
                const key = try std.fmt.allocPrint(alloc, "{s}.{s}", .{ n, nf.key });
                try map.put(alloc, key, fv);
                continue;
            }
            if (graphTextConst(graph, nf.val)) {
                const key = try std.fmt.allocPrint(alloc, "{s}.{s}", .{ n, nf.key });
                try out.strs.put(alloc, key, nf.val.quoted.val);
            }
        }
        // Positional elements recorded under exactly the keys
        // `lowerDynamicIndex` spells. The VERDICT is the shared one, so what is
        // recorded here and what the precheck admits cannot drift apart.
        if (moduleConstTableKindGraph(graph, require_graph_facts, mod, n, v)) |kind| {
            var pos: i64 = 0;
            for (tbl.table.fields) |fld| {
                pos += 1;
                const key = try std.fmt.allocPrint(alloc, "{s}.{d}", .{ n, pos });
                switch (kind) {
                    .int => try map.put(alloc, key, constIndexOf(graph, require_graph_facts, fld.positional) orelse return error.UnsupportedConstruct),
                    .text => try out.strs.put(alloc, key, fld.positional.quoted.val),
                }
            }
            try map.put(alloc, try std.fmt.allocPrint(alloc, "{s}.len", .{n}), pos);
            if (kind == .text) try out.str_tables.put(alloc, try alloc.dupe(u8, n), {});
        }
    }
    return out;
}

fn qualifiedExportNameFromExpr(
    alloc: std.mem.Allocator,
    expr: *const ast.Expr,
) Error!?[]const u8 {
    return switch (expr.*) {
        .call => |c| switch (c.func.*) {
            .name => |n| try alloc.dupe(u8, n.ident),
            .field => |f| {
                if (f.obj.* != .name) return null;
                return try std.fmt.allocPrint(alloc, "{s}.{s}", .{ f.obj.name.ident, f.field });
            },
            else => null,
        },
        .method_call => |m| {
            if (m.obj.* != .name) return null;
            return try std.fmt.allocPrint(alloc, "{s}.{s}", .{ m.obj.name.ident, m.method });
        },
        else => null,
    };
}

fn recordExportMapAssignable(ctx: *const LowerCtx, value: *const ast.Expr) bool {
    if (ctx.require_graph_facts) return false;
    const export_name = qualifiedExportNameFromExpr(ctx.alloc, value) catch return false;
    defer if (export_name) |n| ctx.alloc.free(n);
    if (export_name) |n| return ctx.func_record_returns.contains(n);
    return false;
}

pub fn lowerModule(alloc: std.mem.Allocator, mod: *const ast.Module) Error!dnir.Module {
    var diagnostic: Diagnostic = .{};
    return lowerModuleObserved(alloc, mod, &diagnostic);
}

pub fn lowerModuleObserved(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    diagnostic: *Diagnostic,
) Error!dnir.Module {
    diagnostic.reset();
    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    _ = graph.liftModuleWithCalls(mod, mod.file) catch return error.OutOfMemory;
    var occurrences = try OccurrenceBridge.init(alloc, &graph, diagnostic);
    defer occurrences.deinit();
    const module = try lowerModuleFromGraph(alloc, mod, &graph, &occurrences, diagnostic, false);
    errdefer dnir.deinitModule(alloc, module);
    var detached = module;
    detached.graph = null;

    // This convenience path does not return the graph owner. Any handles it
    // used while lowering are therefore intentionally erased before that
    // owner is destroyed. Checked consumers must use
    // `lowerModuleWithGraph` and retain the graph for the module's lifetime.
    const functions: []dnir.Function = @constCast(detached.functions);
    for (functions) |*function| {
        function.id = null;
        for (function.blocks) |block| {
            const instructions: []dnir.Instr = @constCast(block.instrs);
            for (instructions) |*instruction| {
                instruction.relation = null;
                instruction.application = null;
                instruction.value = null;
                instruction.subject = null;
                instruction.realization_start = null;
            }
        }
    }
    return detached;
}

/// relation level edge `len(path) = (min) …` → symbol `len__path`.
fn relationEdgeLevel(symbol: []const u8) ?[]const u8 {
    if (std.mem.indexOf(u8, symbol, "__")) |sep| {
        if (sep + 2 < symbol.len) return symbol[sep + 2 ..];
    }
    return null;
}

/// True when `expr` may evaluate a call or method call. The loopselect
/// defining-RHS scan refuses any intervening statement whose value may call:
/// a call can rebind a module binding, which would break the "bound at the
/// loop IS the RHS value" claim. Unhandled composite shapes answer true --
/// fail closed; only pure leaves and call-free composites answer false.
fn exprHasCall(expr: *const ast.Expr) bool {
    return switch (expr.*) {
        .call, .method_call => true,
        .index => |x| exprHasCall(x.obj) or exprHasCall(x.key),
        .field => |x| exprHasCall(x.obj),
        .binop => |b| exprHasCall(b.lhs) or exprHasCall(b.rhs),
        .unop => |u| exprHasCall(u.operand),
        .if_expr => |ie| exprHasCall(ie.cond) or exprHasCall(ie.then_expr) or exprHasCall(ie.else_expr),
        .try_expr => |x| exprHasCall(x.operand),
        .unwrap_expr => |x| exprHasCall(x.operand),
        .await_expr => |x| exprHasCall(x.operand),
        .contains_expr => |x| exprHasCall(x.lhs) or exprHasCall(x.rhs),
        .sequence => |s| blk: {
            for (s.exprs) |e| if (exprHasCall(e)) break :blk true;
            break :blk false;
        },
        .range => |r| exprHasCall(r.start) or exprHasCall(r.end) or
            (if (r.step) |st| exprHasCall(st) else false),
        .quote => |q| exprHasCall(q.expr),
        .unquote => |u| exprHasCall(u.expr),
        .int_lit, .float_lit, .true_lit, .false_lit, .nil, .quoted, .vararg, .func_expr => false,
        .name => false,
        else => true,
    };
}

fn collectRelationEdges(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
) Error!std.StringHashMapUnmanaged([]const u8) {
    var edges: std.StringHashMapUnmanaged([]const u8) = .empty;
    for (mod.body.stmts) |*stmt| {
        if (stmt.* != .func_decl) continue;
        const fd = &stmt.func_decl;
        if (fd.path.len != 1) continue;
        const sym = fd.path[0];
        if (relationEdgeLevel(sym)) |level| {
            _ = level;
            if (std.mem.indexOf(u8, sym, "__")) |sep| {
                const family = try alloc.dupe(u8, sym[0..sep]);
                errdefer alloc.free(family);
                const gop = try edges.getOrPut(alloc, family);
                if (gop.found_existing) {
                    alloc.free(family);
                } else {
                    gop.value_ptr.* = sym;
                }
            }
        }
    }
    return edges;
}

/// ONE READER OF ONE PREDICATE. The graph owns the aggregate fact and the place
/// fact this asks about, so it owns the question too — see
/// `SemanticGraph.aggregateIsSoleImmutableBinding`. This name is kept because
/// the loading realization below reads it in four places.
fn immutableAggregate(graph: *const semantic_graph.SemanticGraph, aggregate: semantic_graph.id) bool {
    return graph.aggregateIsSoleImmutableBinding(aggregate);
}

fn hasDirectAggregateAccess(
    graph: *const semantic_graph.SemanticGraph,
    aggregate: semantic_graph.id,
) bool {
    for (graph.applications()) |application| {
        if (graph.aggregateAccess(application.application) == null) continue;
        if (graph.applicationSubject(application.application) == aggregate) return true;
    }
    return false;
}

/// Whether the exact graph place named by this transitional AST binding already
/// has a selected static aggregate realization. The name is only the current
/// walker's bridge to the graph place; aggregate identity, contents, legality,
/// and physical selection all come from graph facts. Delete the name bridge
/// when parser work items carry place ids directly.
fn skipStaticAggregateBinding(ctx: *LowerCtx, binding_name: []const u8) Error!bool {
    const owner = ctx.function orelse return false;
    const owner_node = ctx.graph.get(owner) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-owner");
    const bound_place = if (owner_node.scope == null)
        ctx.graph.placeNamed(binding_name)
    else if (ctx.graph.bodyOf(owner)) |body|
        body.places.find(binding_name)
    else
        null;
    const site = (bound_place orelse return false).id;
    const aggregate = ctx.graph.boundAggregateAtPlace(owner, site) orelse return false;
    if (ctx.graph.aggregateProducer(aggregate) != null) return false;
    const fact = ctx.graph.aggregate(aggregate) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-member-pack");
    const node = ctx.graph.get(aggregate) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-root");
    const descriptor = node.descriptor orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-root-descriptor");
    if (descriptor != .array) return false;
    // A flat immutable aggregate can disappear only when the graph owns at
    // least one direct projection from it. Otherwise another still-migrating
    // consumer may need the ordinary binding initialization. Nested aggregate
    // access already has such a direct first edge by construction.
    if (!hasDirectAggregateAccess(ctx.graph, aggregate)) return false;
    if (fact.contents_known != .yes or ctx.graph.aggregatePlace(aggregate) == null)
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-static-place");
    return immutableAggregate(ctx.graph, aggregate);
}

fn appendAggregateWords(
    graph: *const semantic_graph.SemanticGraph,
    aggregate: semantic_graph.id,
    words: *std.ArrayListUnmanaged(i64),
    stack: *std.AutoHashMapUnmanaged(semantic_graph.id, void),
    alloc: std.mem.Allocator,
) Error!void {
    const entry = try stack.getOrPut(alloc, aggregate);
    if (entry.found_existing) return error.GraphFactsInvalid;
    defer _ = stack.remove(aggregate);

    const fact = graph.aggregate(aggregate) orelse return error.GraphFactsInvalid;
    if (fact.contents_known != .yes) return error.GraphFactsInvalid;
    const members = graph.aggregateMembers(aggregate) orelse return error.GraphFactsInvalid;
    for (members) |member| {
        const node = graph.get(member) orelse return error.GraphFactsInvalid;
        const descriptor = node.descriptor orelse return error.GraphFactsInvalid;
        switch (descriptor) {
            .i64 => try words.append(alloc, graph.exactI64(member) orelse return error.GraphFactsInvalid),
            .array => try appendAggregateWords(graph, member, words, stack, alloc),
            else => return error.GraphFactsInvalid,
        }
    }
}

/// True when the relation this application lives in was evaluated whole at
/// compile time and therefore realizes none of its own applications.
///
/// LAWFUL NONEXECUTION IS A FACT ABOUT THE READER, and the dense table's
/// existence is a question about readers. `native_backend.unrealizedApplicationCount`
/// already subtracts these applications from the realization count; without the
/// same subtraction here a folded relation left behind a `__TEXT,__const` row
/// with no `load_index` reading it, and `realization_validate` refused the
/// module with `aggregate-dense-table-unused` — correctly, since an emitted
/// table nothing reads is exactly what that check is for.
fn applicationCallerFolded(
    functions: []const dnir.Function,
    graph: *const semantic_graph.SemanticGraph,
    application: semantic_graph.id,
) bool {
    const caller = graph.applicationCaller(application) orelse return false;
    for (functions) |function| {
        const id = function.id orelse continue;
        if (id != caller) continue;
        return function.folded_to_constant;
    }
    return false;
}

fn collectDenseTables(
    alloc: std.mem.Allocator,
    graph: *const semantic_graph.SemanticGraph,
    functions: []const dnir.Function,
    diagnostic: *Diagnostic,
) Error![]const dnir.DenseTable {
    var tables: std.ArrayListUnmanaged(dnir.DenseTable) = .empty;
    errdefer {
        for (tables.items) |table| alloc.free(table.values);
        tables.deinit(alloc);
    }
    var stack: std.AutoHashMapUnmanaged(semantic_graph.id, void) = .empty;
    defer stack.deinit(alloc);
    var row: usize = 0;
    while (row < graph.aggregateCount()) : (row += 1) {
        const fact = graph.aggregateAt(row) orelse
            return invalidGraphFacts(diagnostic, @src(), "aggregate-member-pack");
        if (graph.aggregateProducer(fact.aggregate) != null) continue;
        if (!immutableAggregate(graph, fact.aggregate)) continue;
        const descriptor = (graph.get(fact.aggregate) orelse
            return invalidGraphFacts(diagnostic, @src(), "aggregate-root")).descriptor orelse
            return invalidGraphFacts(diagnostic, @src(), "aggregate-root-descriptor");
        // A flat exact-only projection disappears to its exact result and does
        // not retain a dense object. A dynamic flat projection does. Nested
        // aggregates keep the existing materialization until their complete
        // access chain can be contracted.
        if (descriptor == .array and descriptor.array.elem.* != .array) {
            var runtime_access = false;
            for (graph.applications()) |application| {
                if (graph.aggregateAccess(application.application) == null) continue;
                if (graph.applicationSubject(application.application) != fact.aggregate) continue;
                const results = graph.applicationResults(application.application) orelse
                    return invalidGraphFacts(diagnostic, @src(), "aggregate-result-pack");
                if (results.len != 1)
                    return invalidGraphFacts(diagnostic, @src(), "aggregate-access-pack-arity");
                if (applicationCallerFolded(functions, graph, application.application)) continue;
                if (graph.exactI64(results[0]) == null) {
                    runtime_access = true;
                    break;
                }
            }
            if (!runtime_access) continue;
        }
        var words: std.ArrayListUnmanaged(i64) = .empty;
        errdefer words.deinit(alloc);
        appendAggregateWords(graph, fact.aggregate, &words, &stack, alloc) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            else => return invalidGraphFacts(diagnostic, @src(), "aggregate-member-pack"),
        };
        if (words.items.len == 0) {
            words.deinit(alloc);
            return invalidGraphFacts(diagnostic, @src(), "aggregate-member-pack");
        }
        const values = try words.toOwnedSlice(alloc);
        errdefer alloc.free(values);
        try tables.append(alloc, .{
            .value = fact.aggregate,
            .elem_ty = .i64,
            .values = values,
        });
    }
    return try tables.toOwnedSlice(alloc);
}

fn validateAggregateFacts(
    graph: *const semantic_graph.SemanticGraph,
    diagnostic: *Diagnostic,
) Error!void {
    var row: usize = 0;
    while (row < graph.aggregateCount()) : (row += 1) {
        const fact = graph.aggregateAt(row) orelse
            return invalidGraphFacts(diagnostic, @src(), "aggregate-member-pack");
        const descriptor = (graph.get(fact.aggregate) orelse
            return invalidGraphFacts(diagnostic, @src(), "aggregate-member-pack")).descriptor orelse
            return invalidGraphFacts(diagnostic, @src(), "aggregate-member-pack");
        if (descriptor != .array) continue;
        const extent = descriptor.array.size orelse
            return invalidGraphFacts(diagnostic, @src(), "aggregate-member-pack");
        const members = graph.aggregateMembers(fact.aggregate) orelse
            return invalidGraphFacts(diagnostic, @src(), "aggregate-member-pack");
        if (members.len != extent)
            return invalidGraphFacts(diagnostic, @src(), "aggregate-member-pack");
        for (members) |member| {
            const member_descriptor = (graph.get(member) orelse
                return invalidGraphFacts(diagnostic, @src(), "aggregate-member-pack")).descriptor orelse
                return invalidGraphFacts(diagnostic, @src(), "aggregate-member-pack");
            if (!member_descriptor.eql(descriptor.array.elem.*))
                return invalidGraphFacts(diagnostic, @src(), "aggregate-member-pack");
        }
    }
}

fn lowerModuleFromGraph(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    graph: *const semantic_graph.SemanticGraph,
    occurrences: *const OccurrenceBridge,
    diagnostic: *Diagnostic,
    require_graph_facts: bool,
) Error!dnir.Module {
    try validateAggregateFacts(graph, diagnostic);
    const self_home = graph.selfHome();
    // ORDER MATTERS. The globals are collected FIRST and then removed from the
    // constant pool: a name that is written is not a constant, and leaving it in
    // both would let a read fold to the initializer while a write went to
    // storage — the two halves of the same binding disagreeing, which is worse
    // than either the old folding or the new storage alone.
    var module_globals = try collectModuleGlobals(alloc, mod, graph);
    defer module_globals.deinit(alloc);
    {
        // A DECLARED WIDTH IS A PROPERTY OF THE PLACE and applies at EVERY
        // WRITE (gate/narrow.sh). The `__DATA,__bss` word behind a written
        // module global is a full i64 slot and the store path does not yet
        // mask to the declared width, so a written global narrower than the
        // word would accept out-of-width values silently. Those stay REFUSED
        // with the refusal narrow.sh pins as OWED (`mod-global-written:`),
        // while full-width written globals keep the storage that landed with
        // g066/g108. Deleting this check admits 36 oracle rows that answer
        // wrong — measured when the guard was first removed.
        var it = module_globals.types.iterator();
        while (it.next()) |entry| {
            // DERIVED, NOT TABULATED. "Narrower than the i64 word" is exactly a
            // NARROW INTEGRAL SCALAR, which the numeric owner already answers:
            // `narrowFit` is non-null only for an integral, single-lane
            // descriptor of width < 64, so `i64`/`u64` (register width),
            // `f32`/`f64` (reals — a store to a real slot is not a masked
            // integer write) and the vectors all return null and keep their
            // storage. `scalarRepr` gates the nominal exactly as the retired
            // bare-tag switch did: it listed only `.i8..u32`, so a
            // nominal-over-`i32` (a `.struct` tag) fell to `else` and was NOT
            // refused, and `scalarRepr` withholds the nominal (`law.nominal`
            // §46) so the composed predicate declines it identically. A scalar
            // identity added to the union gains this refusal by its own facts
            // rather than staying silently unrefused in a hand-list — the wrong
            // answer in the safe-looking direction, an out-of-width store that
            // the mask path does not yet cover admitted by absence.
            const t = entry.value_ptr.*;
            if (types.scalarRepr(t) and t.narrowFit() != null) {
                var name_buf: [64]u8 = undefined;
                const note = std.fmt.bufPrint(&name_buf, "mod-global-written:{s}", .{entry.key_ptr.*}) catch
                    "mod-global-written:<name>";
                return bailWith(diagnostic, @src(), note);
            }
        }
    }
    var module_consts = try collectModuleConsts(alloc, mod, graph, require_graph_facts);
    defer module_consts.deinit(alloc);
    {
        var it = module_globals.types.keyIterator();
        while (it.next()) |name| {
            if (module_consts.ints.fetchRemove(name.*)) |e| alloc.free(e.key);
            if (module_consts.strs.fetchRemove(name.*)) |e| alloc.free(e.key);
            if (module_consts.nums.fetchRemove(name.*)) |e| alloc.free(e.key);
        }
    }
    var records: std.ArrayList(dnir.RecordDesc) = .empty;
    errdefer {
        for (records.items) |record| deinitRecord(alloc, record);
        records.deinit(alloc);
    }
    try collectRecordsFromGraph(alloc, &records, graph);
    try collectRecordsFromModuleAliases(alloc, &records, mod);
    var relation_edges = try collectRelationEdges(alloc, mod);
    defer {
        var edge_it = relation_edges.iterator();
        while (edge_it.next()) |entry| alloc.free(entry.key_ptr.*);
        relation_edges.deinit(alloc);
    }

    // Join declarations to graph ids by exact provenance.
    var declarations: std.AutoHashMapUnmanaged(*const ast.FuncDecl, semantic_graph.id) = .empty;
    defer declarations.deinit(alloc);
    var entity_linkage: std.AutoHashMapUnmanaged(semantic_graph.id, []const u8) = .empty;
    defer {
        var linkage_it = entity_linkage.iterator();
        while (linkage_it.next()) |entry| alloc.free(entry.value_ptr.*);
        entity_linkage.deinit(alloc);
    }
    for (graph.nodes.items, 0..) |node, i| {
        const entity: semantic_graph.id = @intCast(i);
        if (node.kind != .func or !graph.callable(entity)) continue;
        const raw = node.ast_ref orelse continue;
        const declaration: *const ast.FuncDecl = @ptrCast(@alignCast(raw));
        const slot = try declarations.getOrPut(alloc, declaration);
        if (slot.found_existing) return invalidGraphFacts(diagnostic, @src(), "function-provenance-collision");
        slot.value_ptr.* = entity;
    }
    try Parameter.admit(alloc, graph, &declarations, diagnostic);
    var decl_it = declarations.iterator();
    while (decl_it.next()) |entry| {
        const fd = entry.key_ptr.*;
        const entity_id = entry.value_ptr.*;
        const export_name = if (graph.callableLinkage(entity_id)) |linkage|
            try alloc.dupe(u8, linkage.symbol)
        else if (graph.requiresCallableLinkage())
            return invalidGraphFacts(diagnostic, @src(), "missing-callable-linkage")
        else if (graph.foreignHome(entity_id)) |foreign_home|
            if (std.mem.eql(u8, foreign_home, "c"))
                try alloc.dupe(u8, fd.path[0])
            else
                try home_resolve.homeSymbol(alloc, foreign_home, fd.path[0])
        else
            try funcExportName(alloc, self_home, fd);
        errdefer alloc.free(export_name);
        const slot = try entity_linkage.getOrPut(alloc, entity_id);
        if (slot.found_existing) {
            alloc.free(export_name);
            return invalidGraphFacts(diagnostic, @src(), "function-linkage-collision");
        }
        slot.value_ptr.* = export_name;
    }

    // GAP-056: which ABI slots each callee expects in v0..v7, so the CALLER
    // marshals into the register file the CALLEE reads from. Keyed by
    // `funcExportName` — the same string `lowerCall` emits as the callee — so a
    // spliced `T.count` resolves as readily as a bare `count`.
    var fp_params: std.StringHashMapUnmanaged([]bool) = .empty;
    defer {
        var fp_it = fp_params.iterator();
        while (fp_it.next()) |e| {
            alloc.free(e.key_ptr.*);
            alloc.free(e.value_ptr.*);
        }
        fp_params.deinit(alloc);
    }
    for (mod.body.stmts) |*stmt| {
        if (stmt.* != .func_decl) continue;
        const fd = &stmt.func_decl;
        if (!shouldIncludeFuncDecl(fd, graph)) continue;
        if (functionEligibleReason(fd, records.items, graph, mod)) |reason| {
            if (std.mem.eql(u8, reason, "record-parameter-overflows-16-gp-slots")) return error.UnsupportedConstruct;
            continue;
        }
        const slots = f64AbiParamSlots(fd, records.items) orelse continue;
        if (slots == 0 or slots > 8) continue;
        const entity = declarations.get(fd) orelse
            return invalidGraphFacts(diagnostic, @src(), "missing-function-id");
        const key = if (graph.callableLinkage(entity)) |linkage|
            try alloc.dupe(u8, linkage.symbol)
        else if (graph.requiresCallableLinkage())
            return invalidGraphFacts(diagnostic, @src(), "missing-callable-linkage")
        else
            try funcExportName(alloc, self_home, fd);
        if (fp_params.contains(key)) {
            alloc.free(key);
            continue;
        }
        const slots_are_fp = paramSlotIsFp(alloc, fd, records.items) catch |err| {
            alloc.free(key);
            return err;
        };
        fp_params.put(alloc, key, slots_are_fp) catch |err| {
            alloc.free(key);
            alloc.free(slots_are_fp);
            return err;
        };
    }

    var functions: std.ArrayList(dnir.Function) = .empty;
    errdefer {
        for (functions.items) |function| deinitFunction(alloc, function);
        functions.deinit(alloc);
    }
    var externs: std.ArrayList(dnir.Extern) = .empty;
    errdefer {
        for (externs.items) |external| deinitExtern(alloc, external);
        externs.deinit(alloc);
    }
    var signature: Parameter.Map = .empty;
    defer {
        var it = signature.valueIterator();
        while (it.next()) |layout| {
            for (layout.params) |parameter| deinitParam(alloc, parameter);
            alloc.free(layout.params);
        }
        signature.deinit(alloc);
    }
    var func_record_returns: std.StringHashMapUnmanaged([]const u8) = .empty;
    defer {
        var returns = func_record_returns.iterator();
        while (returns.next()) |entry| {
            alloc.free(entry.key_ptr.*);
            alloc.free(entry.value_ptr.*);
        }
        func_record_returns.deinit(alloc);
    }

    // Register every record-returning function BEFORE lowering any body.
    //
    // This map was populated as each function finished lowering, so a forward
    // reference could not see it: in a recursive-descent parser `parse_factor`
    // calls `parse_expr` for a parenthesised group, and `parse_expr` had not
    // been lowered yet, so the call was not recognised as record-returning and
    // failed with DNB007. Mutual recursion is the normal shape of a parser, not
    // an edge case, so the map has to be complete up front.
    for (mod.body.stmts) |*stmt| {
        if (stmt.* != .func_decl) continue;
        const fd = &stmt.func_decl;
        if (!shouldIncludeFuncDecl(fd, graph)) continue;
        if (functionEligibleReason(fd, records.items, graph, mod)) |reason| {
            if (std.mem.eql(u8, reason, "record-parameter-overflows-16-gp-slots")) return error.UnsupportedConstruct;
            continue;
        }
        if (require_graph_facts and !graph.gateTransportModule()) {
            const entity = declarations.get(fd) orelse
                return invalidGraphFacts(diagnostic, @src(), "missing-function-id");
            const layout = try signature.getOrPut(alloc, entity);
            if (layout.found_existing) return invalidGraphFacts(diagnostic, @src(), "duplicate-function-id");
            layout.value_ptr.* = .{ .params = &.{} };
            layout.value_ptr.params = try Parameter.demand(alloc, fd, records.items, graph, entity);
        }
        const rec_name = recordReturnNameForDecl(records.items, graph, fd) orelse continue;
        const entity = declarations.get(fd) orelse
            return invalidGraphFacts(diagnostic, @src(), "missing-function-id");
        const linkage_symbol = if (graph.callableLinkage(entity)) |linkage|
            linkage.symbol
        else if (graph.requiresCallableLinkage())
            return invalidGraphFacts(diagnostic, @src(), "missing-callable-linkage")
        else
            null;
        const fallback_name = if (linkage_symbol == null)
            try funcExportName(alloc, self_home, fd)
        else
            null;
        defer if (fallback_name) |name| alloc.free(name);
        const symbol = linkage_symbol orelse fallback_name.?;
        if (func_record_returns.contains(symbol)) continue;
        const key = try alloc.dupe(u8, symbol);
        const value = alloc.dupe(u8, rec_name) catch |err| {
            alloc.free(key);
            return err;
        };
        func_record_returns.put(alloc, key, value) catch |err| {
            alloc.free(key);
            alloc.free(value);
            return err;
        };
    }
    try residency(graph, &signature, diagnostic);
    var skipped: ?[]const u8 = null;
    defer if (skipped) |name| alloc.free(name);
    var summary_cache = summary.Cache.init(alloc);
    defer summary_cache.deinit();
    for (mod.body.stmts) |*stmt| {
        if (stmt.* != .func_decl) continue;
        const fd = &stmt.func_decl;
        if (!shouldIncludeFuncDecl(fd, graph)) continue;
        // Name the function that was refused. "the counts do not match" is a
        // true statement about a module and a useless one about a fix: every
        // one of these bails means exactly one declaration was ineligible, and
        // which one is the entire finding.
        if (functionEligibleReason(fd, records.items, graph, mod)) |reason| {
            // The WHOLE path, not `path[0]`. A spliced `req` module contributes
            // `os.exit`, `os.clock`, `os.time` … and every one of them reported
            // as plain `os`, so the row named a module where the finding is one
            // declaration inside it.
            //
            // AND THE REASON, IDENTITY FIRST. The predicate knows exactly
            // which ABI or subset limit refused the declaration; reporting
            // only the name made the reader rediscover it by bisecting the
            // subject by hand. The reason is the kebab CAUSE and leads; the
            // declaration path is provenance and follows the colon, the same
            // `cause:name` shape `bailNamed` emits, so a census groups these
            // rows by cause instead of minting one row per refused name.
            if (skipped == null) {
                const path = if (fd.path.len > 0)
                    try std.mem.join(alloc, ".", fd.path)
                else
                    try alloc.dupe(u8, "?");
                defer alloc.free(path);
                skipped = try std.fmt.allocPrint(alloc, "{s}:{s}", .{ reason, path });
            }
            continue;
        }
        const function = declarations.get(fd) orelse if (require_graph_facts)
            return invalidGraphFacts(diagnostic, @src(), "missing-function-id")
        else
            null;
        const f = try lowerFunction(
            alloc,
            fd,
            function,
            records.items,
            graph,
            occurrences,
            diagnostic,
            require_graph_facts,
            &externs,
            &func_record_returns,
            &fp_params,
            &module_consts,
            &module_globals,
            &entity_linkage,
            &relation_edges,
            &signature,
            &summary_cache,
        );
        functions.append(alloc, f) catch |err| {
            deinitFunction(alloc, f);
            return err;
        };
    }
    const want = mod.program();
    if (want) {
        const module_id = if (require_graph_facts)
            (home(graph) orelse return invalidGraphFacts(diagnostic, @src(), "missing-function-id"))
        else
            null;
        const body = try root(
            alloc,
            mod,
            module_id,
            records.items,
            graph,
            occurrences,
            diagnostic,
            require_graph_facts,
            &externs,
            &func_record_returns,
            &fp_params,
            &module_consts,
            &module_globals,
            &entity_linkage,
            &relation_edges,
            &signature,
        );
        functions.append(alloc, body) catch |err| {
            deinitFunction(alloc, body);
            return err;
        };
    }
    // THE MODULE SYSTEM'S BASE CASE. A module that DECLARES nothing lowers to
    // a module that CONTAINS nothing — an object with no text symbols, which is
    // exactly what it means. `if (functions.items.len == 0) return bail(…)` used
    // to sit here and refused that module with `DNB001 lowerModuleFromGraph()`,
    // so `lib/compiler/application.id` — 29 lines of fact-closure documentation
    // and zero lines of code — could not be built by the compiler it documents.
    //
    // The guard was also REDUNDANT for the case it was defending. Zero functions
    // has two causes and the line below already separates them: nothing was
    // declared (`expected == 0`, legal, an empty object) versus everything
    // declared was refused (`expected > 0`, a bail that NAMES the declaration in
    // `skipped`). The deleted line answered both with one unattributed refusal,
    // so it destroyed the better diagnostic in the failing case and forbade the
    // legal one. HPLS §99: consumed but no candidate generated — the empty
    // module reached lowering and no realization was ever proposed for it.
    const expected = countModuleFunctions(mod, graph) + @as(usize, @intFromBool(want));
    if (functions.items.len != expected)
        return bailWith(diagnostic, @src(), skipped orelse "function-count-mismatch");

    const owned_functions = try functions.toOwnedSlice(alloc);
    errdefer {
        for (owned_functions) |function| deinitFunction(alloc, function);
        alloc.free(owned_functions);
    }
    const owned_records = try records.toOwnedSlice(alloc);
    errdefer {
        for (owned_records) |record| deinitRecord(alloc, record);
        alloc.free(owned_records);
    }
    const owned_externs = try externs.toOwnedSlice(alloc);
    errdefer {
        for (owned_externs) |external| deinitExtern(alloc, external);
        alloc.free(owned_externs);
    }

    // THE INITIALIZERS, AS LOAD-TIME CONTENT OF THE STORAGE.
    //
    // `dnir.Module.globals` existed with zero producers and zero consumers —
    // scenery under `AGENTS.md`'s standing rule. It gains both here, because it
    // is exactly the fact the backend was missing: WHAT EACH WORD HOLDS BEFORE
    // ANYTHING RUNS. Publishing it is what lets `__DATA,__data` answer, and what
    // deleted the `main`-only prologue store that made a library object wrong.
    //
    // A global with no initializer is not published: its word is zero, and a
    // zero word is `__DATA,__bss` — no file bytes, no relocation, nothing. That
    // is the same rule `has_cstring`/`has_const` follow, and it is why this
    // change costs a module with no non-zero initializer literally nothing.
    var globals: std.ArrayListUnmanaged(dnir.Global) = .empty;
    errdefer globals.deinit(alloc);
    for (module_globals.order.items) |g| {
        const init = g.init orelse continue;
        const ty = module_globals.types.get(g.name) orelse continue;
        // A string-typed global with a string-literal initializer publishes
        // the literal content. The word holds the string's address — a
        // link-time fact — so the backend interns the literal and resolves
        // the address with a data-section relocation. Dropping the
        // initializer here left a zero word that a later write made
        // observable, and reads before the write dereferenced null.
        if (ty == .str and init.* == .quoted) {
            const v = comptime_eval.eval(init) catch null;
            if (v) |val| {
                if (val == .string) {
                    try globals.append(alloc, .{ .name = g.name, .ty = ty, .init = .{ .str = val.string } });
                    continue;
                }
            }
            // The literal did not fold to a string; fall through to the
            // constant path below, which bails with a diagnostic.
        }
        const value = constGlobalInit(init, ty) orelse {
            // A module-home alias (`global A = compiler.arm64`) is a subject
            // binding, not a load-time word. Calls resolve through graph
            // application facts; the initializer has no `__DATA` image.
            if (globalInitIsSubjectBinding(init)) continue;
            var buf: [96]u8 = undefined;
            const note = std.fmt.bufPrint(&buf, "global-init-not-constant:{s}", .{g.name}) catch
                "global-init-not-constant";
            return bailWith(diagnostic, @src(), note);
        };
        const zero = switch (value) {
            .i64 => |n| n == 0,
            .f64 => |f| @as(u64, @bitCast(f)) == 0,
            else => false,
        };
        if (zero) continue;
        try globals.append(alloc, .{ .name = g.name, .ty = ty, .init = value });
    }
    const owned_globals = try globals.toOwnedSlice(alloc);
    errdefer alloc.free(owned_globals);

    const owned_dense_tables = try collectDenseTables(alloc, graph, owned_functions, diagnostic);
    errdefer {
        for (owned_dense_tables) |table| alloc.free(table.values);
        alloc.free(owned_dense_tables);
    }

    const result = dnir.Module{
        .graph = graph,
        .functions = owned_functions,
        .records = owned_records,
        .globals = owned_globals,
        .dense_tables = owned_dense_tables,
        .externs = owned_externs,
    };
    if (require_graph_facts and !graph.gateTransportModule())
        try Parameter.verify(graph, &result, &signature, diagnostic);
    return .{
        .graph = graph,
        .functions = result.functions,
        .records = result.records,
        .globals = result.globals,
        .dense_tables = result.dense_tables,
        .externs = result.externs,
        .hardware_tier = dnir.moduleHardwareTier(result),
    };
}

/// Graph facts control checked call ordering and provenance.
pub fn lowerModuleWithGraph(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    graph: *const semantic_graph.SemanticGraph,
) Error!dnir.Module {
    var diagnostic: Diagnostic = .{};
    return lowerModuleWithGraphObserved(alloc, mod, graph, &diagnostic);
}

pub fn lowerModuleWithGraphObserved(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    graph: *const semantic_graph.SemanticGraph,
    diagnostic: *Diagnostic,
) Error!dnir.Module {
    diagnostic.reset();
    var occurrences = try OccurrenceBridge.init(alloc, graph, diagnostic);
    defer occurrences.deinit();
    if (!graph.gateTransportModule() and occurrences.unresolved != 0) {
        // The occurrence is bound HERE, by the consumer that is refusing, so
        // the id and the note are one cause. When the module is gate transport
        // this branch does not run and nothing is bound — the scan's finding
        // has no refusal to belong to.
        if (occurrences.first_unresolved_aggregate) |application|
            return refuseApplication(diagnostic, graph, @src(), "aggregate-access-fact", application);
        if (occurrences.first_unresolved) |application|
            return refuseApplication(diagnostic, graph, @src(), "missing-application-id", application);
        return invalidGraphFacts(diagnostic, @src(), "missing-application-id");
    }
    const require_graph_facts = !graph.gateTransportModule();
    var m = try lowerModuleFromGraph(alloc, mod, graph, &occurrences, diagnostic, require_graph_facts);
    errdefer dnir.deinitModule(alloc, m);
    try applyGraphToModule(alloc, graph, &m, diagnostic);
    return m;
}

/// Test-only construction seam for backend controls that must consume the same
/// checked graph and DNIR without importing parser or semantic-stage modules
/// into a physical realizer. The caller owns `graph` and the allocator-backed
/// source lifetime; production compilation continues through the APIs above.
pub fn lowerTestSourceWithGraph(
    alloc: std.mem.Allocator,
    source: []const u8,
    file: []const u8,
    graph: *semantic_graph.SemanticGraph,
) !dnir.Module {
    const Lexer = @import("../lexer.zig").Lexer;
    const Parser = @import("../parser.zig").Parser;
    const Sema = @import("../sema.zig").Sema;
    const table_apply = @import("../table_apply.zig");

    var lexer = Lexer.init(source, file);
    var parser = Parser.init(&lexer, alloc);
    parser.idol_mode = true;
    var module = try parser.parse_module();
    var checked = Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    try checked.check_module(&module);
    try std.testing.expectEqual(@as(u32, 0), checked.errors);
    table_apply.normalizeModule(alloc, &module, &checked.type_map);
    _ = try graph.liftModuleWithCheckedCalls(&module, &checked, file);
    var diagnostic: Diagnostic = .{};
    return lowerModuleWithGraphObserved(alloc, &module, graph, &diagnostic) catch |err| {
        std.debug.print("{s}: {s}\n", .{ file, diagnostic.note() orelse @errorName(err) });
        return err;
    };
}

fn applyGraphToModule(
    alloc: std.mem.Allocator,
    graph: *const semantic_graph.SemanticGraph,
    m: *dnir.Module,
    diagnostic: *Diagnostic,
) Error!void {
    if (graph.gateTransportModule()) return;
    try reorderFunctionsByGraphFacts(alloc, graph, m, diagnostic);
}

/// Place checked callees before callers using graph facts only.
fn reorderFunctionsByGraphFacts(
    alloc: std.mem.Allocator,
    graph: *const semantic_graph.SemanticGraph,
    m: *dnir.Module,
    diagnostic: *Diagnostic,
) Error!void {
    if (m.functions.len <= 1) return;

    const function_ids = try alloc.alloc(semantic_graph.id, m.functions.len);
    defer alloc.free(function_ids);
    var functions: std.AutoHashMapUnmanaged(semantic_graph.id, usize) = .empty;
    defer functions.deinit(alloc);
    for (m.functions, 0..) |entry, i| {
        const function = entry.id orelse
            return invalidGraphFacts(diagnostic, @src(), "missing-function-id");
        function_ids[i] = function;
        const slot = try functions.getOrPut(alloc, function);
        if (slot.found_existing) return invalidGraphFacts(diagnostic, @src(), "duplicate-function-id");
        slot.value_ptr.* = i;
    }

    const order = graph.moduleFunctionEmitOrder(alloc, function_ids) catch |err| switch (err) {
        error.OutOfMemory => return error.OutOfMemory,
        error.DuplicateFunctionEntity => return invalidGraphFacts(diagnostic, @src(), "duplicate-function-id"),
        error.InvalidFunctionEntity => return invalidGraphFacts(diagnostic, @src(), "invalid-function-id"),
        error.UnresolvedApplication => return invalidGraphFacts(diagnostic, @src(), "unresolved-application"),
    };
    defer alloc.free(order);

    var changed = false;
    for (order, function_ids) |ordered_id, current_id| {
        if (ordered_id != current_id) {
            changed = true;
            break;
        }
    }
    if (!changed) return;

    const ordered = try alloc.alloc(dnir.Function, m.functions.len);
    defer alloc.free(ordered);
    for (order, 0..) |function, destination_index| {
        const source_index = functions.get(function) orelse
            return invalidGraphFacts(diagnostic, @src(), "function-order-id");
        ordered[destination_index] = m.functions[source_index];
    }
    @memcpy(@constCast(m.functions), ordered);
}

fn funcFfiName(attrs: []const ast.Attribute) ?[]const u8 {
    for (attrs) |attr| {
        if (!std.mem.eql(u8, attr.name, "ffi")) continue;
        const raw = attr.args orelse return null;
        if (raw.len >= 2 and raw[0] == '"' and raw[raw.len - 1] == '"') return raw[1 .. raw.len - 1];
        return raw;
    }
    return null;
}

/// The name a FOREIGN BOUNDARY declares for itself: `@ffi("n")`,
/// `@c.export("n")` or its canonical spelling `@comp.c.export("n")`. Null when
/// the relation has no foreign boundary and is therefore ours to name.
///
/// `@export` with no argument is here too, and it means "this bare spelling is
/// the boundary" — the same claim `@c.export("x")` makes about `x`.
/// `native_backend.funcExportName` reads the identical three attributes when it
/// picks a process entry; the two agree because they read the same declaration.
fn foreignBoundaryName(fd: *const ast.FuncDecl) ?[]const u8 {
    for (fd.attributes) |attr| {
        const is_boundary = std.mem.eql(u8, attr.name, "ffi") or
            std.mem.eql(u8, attr.name, "export") or
            std.mem.eql(u8, attr.name, "c.export") or
            std.mem.eql(u8, attr.name, "comp.c.export");
        if (!is_boundary) continue;
        const raw = attr.args orelse return fd.path[0];
        if (raw.len >= 2 and raw[0] == '"' and raw[raw.len - 1] == '"') return raw[1 .. raw.len - 1];
        return raw;
    }
    return null;
}

/// THE SYMBOL A RELATION IS REALIZED AS — a function of its IDENTITY, and its
/// identity is `(home, name)`.
///
/// This returned `fd.path[0]` — the BARE name — for as long as the direct
/// backend has existed, and the direct backend is the only backend there is. It
/// is not merely inelegant. MEASURED, 2026-08-15: `lib/compiler/record.id`
/// exports `_field`; an ordinary second module that names one relation `field`
/// exports `_field`; and `xcrun ld -r` over the two objects answers `duplicate
/// symbol '_field'`. Across this corpus, 411 of 652 non-`main` exported symbols
/// (63%) sit in a class where two or more homes export the same spelling. Self
/// hosting REQUIRES linking the eighteen `lib/compiler` modules into one image,
/// so under home-blind symbols that link could not exist — independently of
/// every sema and graph question in front of it.
///
/// ONE AUTHORITY, TWO SIDES. `home_resolve.relationSymbol` decides; the CALLER
/// side (`entity_linkage` for a foreign target, below) and the DEFINER side
/// (this, for everything else) both go through it, so they agree by
/// construction rather than by test. Only a declared foreign boundary escapes
/// home identity. The physical process root is synthesized separately and a
/// source relation named `main` remains ordinary.
///
/// The dotted spelling for a method (`Vec.xplus`) is the NAME half, unchanged;
/// `native_backend.linkerSymbolName` still folds its dot to an underscore.
pub fn funcExportName(
    alloc: std.mem.Allocator,
    self_home: ?[]const u8,
    fd: *const ast.FuncDecl,
) Error![]const u8 {
    const name = if (fd.path.len == 1)
        try alloc.dupe(u8, fd.path[0])
    else
        try std.fmt.allocPrint(alloc, "{s}.{s}", .{ fd.path[0], fd.path[fd.path.len - 1] });
    defer alloc.free(name);
    return home_resolve.relationSymbol(alloc, self_home, name, foreignBoundaryName(fd));
}

fn declarationLinkage(
    graph: *const semantic_graph.SemanticGraph,
    fd: *const ast.FuncDecl,
) ?*const semantic_graph.CallableLinkage {
    const relation = graph.relationForDeclaration(fd) orelse return null;
    return graph.callableLinkage(relation);
}

fn declarationIsForeignBoundary(
    graph: *const semantic_graph.SemanticGraph,
    fd: *const ast.FuncDecl,
) bool {
    if (declarationLinkage(graph, fd)) |linkage| return linkage.exposure != .internal;
    if (graph.requiresCallableLinkage()) return false;
    return foreignBoundaryName(fd) != null;
}

fn shouldIncludeFuncDecl(fd: *const ast.FuncDecl, graph: *const semantic_graph.SemanticGraph) bool {
    if (declarationLinkage(graph, fd)) |linkage| {
        // The graph published this callable's linkage, so the graph owns the
        // definer set. `is_local` is a source scoping face — Lua's
        // `local function` — and scope is already a graph fact; letting the
        // spelling remove the definer here left every call site holding an
        // internal symbol no function defines (GAP-238: hello.lua refused
        // `call_direct/call-target-unknown` on wasm32-wasi while the same
        // program spelled in .id compiled).
        if (linkage.exposure == .c_import) return false;
    } else if (graph.requiresCallableLinkage()) {
        // The entity-linkage preflight refuses the missing row before this
        // predicate is consumed. Do not let the source attribute decide that a
        // damaged checked declaration should disappear from the denominator.
        return true;
    } else {
        // No graph-owned linkage: the legacy source-face reading remains.
        if (fd.is_local) return false;
        if (funcFfiName(fd.attributes) != null) return false;
    }
    if (fd.path.len == 1 and !fd.method) return true;
    if (fd.method and fd.path.len >= 2) return true;
    // §3 — math.add = (a, b) … static module members (dot, not colon).
    if (fd.path.len >= 2 and !fd.method) return true;
    return false;
}

fn countModuleFunctions(mod: *const ast.Module, graph: *const semantic_graph.SemanticGraph) usize {
    var n: usize = 0;
    for (mod.body.stmts) |*stmt| {
        if (stmt.* != .func_decl) continue;
        if (shouldIncludeFuncDecl(&stmt.func_decl, graph)) n += 1;
    }
    return n;
}

fn home(graph: *const semantic_graph.SemanticGraph) ?semantic_graph.id {
    for (graph.nodes.items, 0..) |node, i| {
        if (node.scope == null) return @intCast(i);
    }
    return null;
}

fn isFloatType(t: ast.TypeExpr) bool {
    return t == .named and std.mem.eql(u8, t.named, "f64");
}

fn isF64Record(recs: []const dnir.RecordDesc, t: ast.TypeExpr) ?dnir.RecordDesc {
    const r = findRecordName(recs, t) orelse return null;
    if (r.fields.len == 0) return null;
    for (r.kinds) |k| {
        if (k != .f64) return null;
    }
    return r;
}

fn recordKindsMixed(record: dnir.RecordDesc) bool {
    var saw_fp = false;
    var saw_gp = false;
    for (record.kinds) |kind| {
        if (kind == .f64) saw_fp = true else saw_gp = true;
    }
    return saw_fp and saw_gp;
}

/// One entry per ABI argument SLOT: true when the slot travels in v0..v7.
///
/// GAP-056. `emitScalarCallArgs` marshalled every argument with `mov_arg`, which
/// writes x0..x7, no matter what the callee declared. `p(x: f64, y: f64): i64`
/// compiled to a flawless callee (`fcmp d0, d1`) fed by a caller that had put
/// both doubles in x0/x1, so the comparison read whatever d0/d1 happened to
/// hold: `p(3.5, 1.5)` answered 1 where C answered 9. It compiled, ran, and
/// exited cleanly with the wrong number.
///
/// The deleted caller-side f64 result map additionally required an f64 return,
/// while the callee-side `is_float_kernel` flag does not. Parameter placement
/// remains this separate ABI fact; result descriptors now come from the graph.
///
/// Per-SLOT rather than a single all-or-nothing answer because AAPCS64 counts
/// the two register files separately: `f(a: i64, b: f64, c: i64)` is x0, d0, x1
/// — not x0, d1, x2. A shared counter is right for uniform signatures and
/// quietly wrong for every mixture. Mixed signatures are refused by
/// `functionEligible` today, so this is correct by construction rather than by
/// an invariant that has to hold somewhere else.
///
fn paramSlotIsFp(
    alloc: std.mem.Allocator,
    fd: *const ast.FuncDecl,
    recs: []const dnir.RecordDesc,
) Error![]bool {
    var list: std.ArrayListUnmanaged(bool) = .empty;
    errdefer list.deinit(alloc);
    for (fd.func.params) |p| {
        if (isFloatType(p.typ)) {
            try list.append(alloc, true);
        } else if (findRecordName(recs, p.typ) != null) {
            try list.append(alloc, false);
        } else {
            try list.append(alloc, false);
        }
    }
    return list.toOwnedSlice(alloc);
}

fn f64AbiParamSlots(fd: *const ast.FuncDecl, recs: []const dnir.RecordDesc) ?usize {
    var slots: usize = 0;
    for (fd.func.params) |p| {
        if (isFloatType(p.typ)) {
            slots += 1;
        } else if (isF64Record(recs, p.typ)) |r| {
            slots += r.fields.len;
        } else return null;
    }
    return slots;
}

pub const max_reg_record_fields = 8;

/// Past `max_reg_record_fields` a record return uses the AAPCS64 indirect-result
/// convention: the CALLER reserves the buffer and passes its address in x8, and
/// the callee writes the fields through it. Bounded so the caller's frame
/// reservation stays a small `sub sp` immediate.
pub const max_record_fields = 32;

/// AAPCS64 passes the first eight general-purpose scalar arguments in x0..x7;
/// arguments past the eighth travel on the stack at [sp,#(i-8)*8] (see
/// `emitPushVarargs` on the caller and the callee prologue's stack-arg load).
/// Sixteen is the total the backend's stack-arg block (`pending_varargs[8]`)
/// can carry: eight registers plus eight stack slots. This retires the
/// application-argument-pack refusal for wide integer relations (e.g. a general
/// order-k linear recurrence passing k coefficients + k seeds + N) — no packing.
/// Floating-point and record arguments stay capped at the eight-register file.
pub const max_direct_scalar_args = 16;

fn gpPackType(t: ast.TypeExpr) ?RT {
    const resolved = resolveType(t);
    return switch (resolved) {
        .i8,
        .i16,
        .i32,
        .i64,
        .u8,
        .u16,
        .u32,
        .u64,
        .bool,
        .str,
        .pointer,
        => resolved,
        else => null,
    };
}

fn resultPackTypes(alloc: std.mem.Allocator, t: ast.TypeExpr) Error![]const RT {
    if (t != .tuple) return &.{};
    if (t.tuple.len == 0 or t.tuple.len > max_reg_record_fields) return error.UnsupportedConstruct;
    const out = try alloc.alloc(RT, t.tuple.len);
    errdefer alloc.free(out);
    for (t.tuple, 0..) |item, i| {
        out[i] = gpPackType(item) orelse return error.UnsupportedConstruct;
    }
    return out;
}

/// AAPCS64 §6.9: a composite RESULT larger than 16 bytes is returned through a
/// caller-allocated buffer whose address the caller passes in x8. At or under 16
/// bytes it comes back in x0/x1. Every field this backend puts in a scalar record
/// occupies 8 bytes — i64, str-as-address, and f64 materialized as its bit
/// pattern all store at an 8-byte stride — so the size test is a field count.
pub const foreign_reg_record_bytes = 16;

/// True when a record return must use the x8 indirect-result convention rather
/// than the x0..x7 explosion.
///
/// THE THRESHOLD IS A PROPERTY OF THE BOUNDARY, NOT OF THE RECORD, and that is
/// the whole content of this function. Two conventions meet here:
///
///     internal (foreign = false)   > max_reg_record_fields, i.e. > 64 bytes
///     foreign  (foreign = true)    > foreign_reg_record_bytes, i.e. > 16 bytes
///
/// Idol's own convention is the wider one ON PURPOSE: a 24-byte result stays in
/// x0..x2 with no buffer, no stores and no reload, which is strictly cheaper
/// than C's, and `AGENTS.md` forbids the C ABI from becoming the internal
/// application ABI. But a relation that declares `@comp.c.export("n")` has told
/// a C compiler what convention to expect, and C's answer is 16.
///
/// MEASURED, and this is why the parameter exists rather than a constant. A
/// relation exporting a 3..8-field record answered a C caller with GARBAGE —
/// `ok compile`, exit 0, no diagnostic:
///
///     fields  bytes   before            after
///     1..2     8..16  correct           correct   (x0/x1 either way)
///     3..8    24..64  SILENT GARBAGE    correct   (x8 indirect)
///     9..    72..     correct           correct   (x8 either way)
///
/// The window is exactly the span where the two conventions disagree, which is
/// what a single hardcoded threshold read at a boundary must produce.
///
/// ONE FUNCTION, TWO READERS, BY CONSTRUCTION. This predicate had ZERO consumers
/// while `native_backend` compared against `max_reg_record_fields` inline in
/// three places — a fact with no consumer beside three copies of itself, which
/// is how the callee and the caller are able to disagree at all. The callee
/// prologue and `indirectResultBuffer` both read it now, so the convention
/// cannot fork again without editing the sentence that defines it.
pub fn recordReturnIsIndirectFields(fields: usize, foreign: bool) bool {
    if (foreign) return fields * 8 > foreign_reg_record_bytes;
    return fields > max_reg_record_fields;
}

pub fn recordReturnIsIndirect(rec: dnir.RecordDesc, foreign: bool) bool {
    return recordReturnIsIndirectFields(rec.fields.len, foreign);
}

/// A payload-free case-set used as a type: ABI-identical to an integer, because
/// its values ARE the module constants `Home.case` folds to. A case-set with
/// payloads carries content and has no scalar ABI here, so it stays ineligible
/// rather than being silently truncated to its tag.
fn typeIsScalarCaseSet(mod: *const ast.Module, typ: ast.TypeExpr) bool {
    const name = switch (typ) {
        .named => |n| n,
        else => return false,
    };
    for (mod.body.stmts) |*st| {
        if (st.* != .enum_def) continue;
        if (!std.mem.eql(u8, st.enum_def.name, name)) continue;
        for (st.enum_def.variants) |v| if (v.payload != null) return false;
        return true;
    }
    return false;
}

/// WHY a declaration was refused, not merely THAT it was.
///
/// `functionEligible` answered a bare bool, so `lowerModuleFromGraph`'s
/// count check could only name the skipped relation — the reason was computed
/// here and thrown away, and recovering it cost a manual bisection of the
/// subject down to the one declaration this predicate had already identified.
/// Returns `null` when the declaration is lowerable; otherwise a stable phrase
/// naming the specific ABI or subset limit that refused it.
fn functionEligibleReason(
    fd: *const ast.FuncDecl,
    recs: []const dnir.RecordDesc,
    graph: *const semantic_graph.SemanticGraph,
    mod: *const ast.Module,
) ?[]const u8 {
    if (fd.func.vararg or fd.func.vararg_name != null) return "vararg-relation";
    if (recordForTypeExpr(recs, fd.func.ret_type, graph)) |rec| {
        if (rec.fields.len == 0) return "record-return-no-fields";
        if (rec.fields.len > max_record_fields) return "record-return-wider-than-32-fields";
        // The caller-side indirect buffer understands a mixed exact shape, but
        // this backend does not yet have mixed GP/FP stores for an INDIRECT
        // callee return. Keep only that case refused. A two-word C result and
        // an up-to-eight-word internal result already travel in registers and
        // are pinned by recordabi's mixed-result controls.
        // Mixed GP/FP indirect returns are lowered through x8 + per-field
        // stores (see native_backend ret_record indirect arm). Foreign-boundary
        // mixed indirect shapes stay refused until the C ABI path exists.
        if (declarationIsForeignBoundary(graph, fd) and recordKindsMixed(rec) and
            recordReturnIsIndirectFields(rec.fields.len, true))
            return "foreign-mixed-indirect-record-return";
        // An f64 record rides v0..v7 as a homogeneous float aggregate; there is
        // no indirect form for it here, so its own eight stays a hard limit.
        if (isF64Record(recs, fd.func.ret_type)) |_| {
            if (rec.fields.len > max_reg_record_fields)
                return "f64-record-return-wider-than-8-registers";
        }
        for (fd.func.params) |p| {
            if (recordForTypeExpr(recs, p.typ, graph) != null) continue;
            if (isFloatType(p.typ)) continue;
            if (p.typ == .named) continue;
            if (!isIntType(p.typ) and !isBoolType(p.typ) and !isStrType(p.typ) and !typeIsPtr(p.typ) and
                !typeIsScalarCaseSet(mod, p.typ)) return "record-return-parameter-unsupported";
        }
        return null;
    }
    if (fd.func.ret_type == .tuple) {
        if (declarationIsForeignBoundary(graph, fd)) return "tuple-return-foreign-boundary";
        if (fd.func.ret_type.tuple.len == 0) return "tuple-return-no-elements";
        if (fd.func.ret_type.tuple.len > max_reg_record_fields)
            return "tuple-return-wider-than-8-registers";
        for (fd.func.ret_type.tuple) |item| if (gpPackType(item) == null)
            return "tuple-return-element-not-gp-word";
    } else if (!isFloatType(fd.func.ret_type) and !isIntType(fd.func.ret_type) and !isBoolType(fd.func.ret_type) and
        !isStrType(fd.func.ret_type) and !isVoidType(fd.func.ret_type) and !isAnyType(fd.func.ret_type) and !typeIsPtr(fd.func.ret_type) and
        !typeIsScalarCaseSet(mod, fd.func.ret_type) and
        fd.func.ret_type != .inferred) return "result-type-unsupported";
    // AAPCS64 assigns the result and argument register classes independently.
    // Determine the parameter file from parameter descriptors, never from the
    // result descriptor.
    if (f64AbiParamSlots(fd, recs)) |slots| {
        if (slots > 0) return if (slots <= 8)
            null
        else
            "f64-parameter-file-wider-than-8-registers";
    }
    var gp_slots: usize = 0;
    for (fd.func.params) |p| {
        if (isFloatType(p.typ)) return "f64-parameter-mixed-with-gp";
        if (recordForTypeExpr(recs, p.typ, graph)) |rec| {
            gp_slots += rec.fields.len;
            if (gp_slots > max_direct_scalar_args)
                return "record-parameter-overflows-16-gp-slots";
            continue;
        }
        // A SCALAR IS A SCALAR WHATEVER ITS SPELLING. `i64`, `bool`, `str`,
        // `ptr` and a payload-free case set are all `.named` type expressions,
        // so the `p.typ == .named` catch-all that used to stand FIRST here
        // swallowed every one of them and capped them at `max_reg_record_fields`
        // — the eight ARGUMENT REGISTERS — before the `max_direct_scalar_args`
        // line below could ever be reached. `max_direct_scalar_args` was raised
        // to sixteen precisely to admit "a general order-k linear recurrence
        // passing k coefficients + k seeds + N" (see its doc comment), and that
        // relation takes ten `i64` parameters, so the limit it was written for
        // was the one shape it could not reach: the ninth `i64` parameter was
        // refused as an "opaque handle" and the whole module went with it.
        //
        // `ptr` rides x0..x7 like an i64 — it is the base address of a
        // memory-backed positional table (SH-04) — and, like an i64, it rides
        // a stack slot past the eighth. `.pointer` already took this path, so
        // `ptr` and `*T` had different argument budgets for the same word.
        if (isIntType(p.typ) or isBoolType(p.typ) or isStrType(p.typ) or typeIsPtr(p.typ) or
            isAnyType(p.typ) or (p.typ == .inferred and resolveType(p.typ) == .any) or
            typeIsScalarCaseSet(mod, p.typ))
        {
            gp_slots += 1;
            if (gp_slots > max_direct_scalar_args) return "more-than-16-gp-arguments";
            continue;
        }
        // What is left is a named type this backend does not model as a word:
        // a module table or other opaque handle. It crosses in a register only.
        if (p.typ == .named) {
            gp_slots += 1;
            if (gp_slots > max_reg_record_fields)
                return "opaque-handle-overflows-8-registers";
            continue;
        }
        return "parameter-type-unsupported";
    }
    return null;
}

fn functionEligible(
    fd: *const ast.FuncDecl,
    recs: []const dnir.RecordDesc,
    graph: *const semantic_graph.SemanticGraph,
    mod: *const ast.Module,
) bool {
    return functionEligibleReason(fd, recs, graph, mod) == null;
}

const GraphFieldFact = struct {
    kind: dnir.FieldKind,
    width: ?RT,
};

/// Rename the owned scalar-cell class to the native-IR carrier's `FieldKind`
/// at this one seam. The two enums are the same three identities; mapping by
/// NAME rather than ordinal keeps the correspondence explicit and refuses to
/// silently agree by shared integer tag (`law.magic.code.zero`).
fn fieldKindOf(cell: types.ScalarFieldCell) dnir.FieldKind {
    return switch (cell) {
        .i64 => .i64,
        .str => .str,
        .f64 => .f64,
    };
}

/// DERIVED, NOT TABULATED — the FIELD-CELL FACE of the scalar roster. The
/// per-tag switch this replaced was one of two statements of which cell each
/// scalar materialises in; `types.scalarFieldCell` owns the partition, and the
/// sub-register store width is exactly the descriptor when `narrowFit` gives it
/// one (the narrow integrals), null otherwise (`i64`/`u64`/`bool`, already the
/// register width). A scalar identity added to the union now gains its field
/// cell here rather than falling to `else` and being declared not-a-field.
fn graphFieldFact(descriptor: RT) ?GraphFieldFact {
    const cell = types.scalarFieldCell(descriptor) orelse return null;
    const width: ?RT = if (descriptor.narrowFit() != null) descriptor else null;
    return .{ .kind = fieldKindOf(cell), .width = width };
}

fn shapeOnStack(stack: []const semantic_graph.id, shape: semantic_graph.id) bool {
    for (stack) |candidate| if (candidate == shape) return true;
    return false;
}

fn appendGraphRecordFields(
    alloc: std.mem.Allocator,
    graph: *const semantic_graph.SemanticGraph,
    shape: semantic_graph.id,
    prefix: []const u8,
    stack: *std.ArrayListUnmanaged(semantic_graph.id),
    names: *std.ArrayListUnmanaged([]const u8),
    kinds: *std.ArrayListUnmanaged(dnir.FieldKind),
    widths: *std.ArrayListUnmanaged(?RT),
) Error!bool {
    if (shapeOnStack(stack.items, shape)) return false;
    try stack.append(alloc, shape);
    defer _ = stack.pop();
    const members = try graph.membersOf(shape, alloc);
    defer alloc.free(members);
    if (members.len == 0) return false;
    for (members) |member| {
        const node = graph.get(member) orelse return false;
        const member_name = node.name orelse return false;
        const path = if (prefix.len == 0)
            try alloc.dupe(u8, member_name)
        else
            try std.fmt.allocPrint(alloc, "{s}.{s}", .{ prefix, member_name });
        if (graph.descriptorShape(member, 0)) |nested| {
            defer alloc.free(path);
            if (!try appendGraphRecordFields(alloc, graph, nested, path, stack, names, kinds, widths)) return false;
            continue;
        }
        // NO AST FALLBACK. `memberDescriptorFromShapeAst` stood here: when the
        // graph had no descriptor on a shape member, this cast the shape's
        // `ast_ref` back to an `ast.AliasDef` and re-ran `types.resolve` on the
        // syntax — a consumer re-deriving, from the source text, a fact whose
        // producer is the shape lift (`law.fallback.zero`, `law.md` §1: "once
        // known, a fact is carried forward; downstream phases never reconstruct
        // it from syntax or representation").
        //
        // Absence is now what it is. A member with no published descriptor
        // refuses the record projection by name instead of answering from the
        // spelling, which is the same refusal this loop already makes when the
        // descriptor is present but not a field fact.
        const descriptor = node.descriptor orelse {
            alloc.free(path);
            return false;
        };
        const fact = graphFieldFact(descriptor) orelse {
            alloc.free(path);
            return false;
        };
        names.append(alloc, path) catch |err| {
            alloc.free(path);
            return err;
        };
        try kinds.append(alloc, fact.kind);
        try widths.append(alloc, fact.width);
        if (names.items.len > max_record_fields) return false;
    }
    return true;
}

fn moduleAliasByName(mod: *const ast.Module, name: []const u8) ?*const ast.AliasDef {
    for (mod.body.stmts) |*stmt| {
        if (stmt.* != .alias_def) continue;
        if (std.mem.eql(u8, stmt.alias_def.name, name)) return &stmt.alias_def;
    }
    return null;
}

fn astFieldFact(typ: ast.TypeExpr) ?GraphFieldFact {
    return switch (typ) {
        .named => |n| blk: {
            if (std.mem.eql(u8, n, "str")) break :blk .{ .kind = .str, .width = null };
            if (std.mem.eql(u8, n, "f64")) break :blk .{ .kind = .f64, .width = null };
            if (isIntType(typ) or isBoolType(typ)) break :blk .{ .kind = .i64, .width = null };
            break :blk null;
        },
        .array, .pointer => .{ .kind = .i64, .width = null },
        else => null,
    };
}

fn aliasNameOnStack(stack: []const []const u8, name: []const u8) bool {
    for (stack) |candidate| if (std.mem.eql(u8, candidate, name)) return true;
    return false;
}

fn appendModuleAliasFields(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    alias: *const ast.AliasDef,
    prefix: []const u8,
    stack: *std.ArrayListUnmanaged([]const u8),
    names: *std.ArrayListUnmanaged([]const u8),
    kinds: *std.ArrayListUnmanaged(dnir.FieldKind),
    widths: *std.ArrayListUnmanaged(?RT),
) Error!bool {
    if (aliasNameOnStack(stack.items, alias.name)) return false;
    try stack.append(alloc, alias.name);
    defer _ = stack.pop();
    for (alias.fields) |field| {
        if (field.is_private) continue;
        const path = if (prefix.len == 0)
            try alloc.dupe(u8, field.name)
        else
            try std.fmt.allocPrint(alloc, "{s}.{s}", .{ prefix, field.name });
        if (field.typ == .named) {
            if (moduleAliasByName(mod, field.typ.named)) |nested| {
                if (!try appendModuleAliasFields(alloc, mod, nested, path, stack, names, kinds, widths)) {
                    alloc.free(path);
                    return false;
                }
                continue;
            }
        }
        const fact = astFieldFact(field.typ) orelse {
            alloc.free(path);
            return false;
        };
        try names.append(alloc, path);
        try kinds.append(alloc, fact.kind);
        try widths.append(alloc, fact.width);
        if (names.items.len > max_record_fields) return false;
    }
    return true;
}

fn appendModuleRecordTypeFields(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    prefix: []const u8,
    stack: *std.ArrayListUnmanaged([]const u8),
    fields: []const ast.RecordField,
    names: *std.ArrayListUnmanaged([]const u8),
    kinds: *std.ArrayListUnmanaged(dnir.FieldKind),
    widths: *std.ArrayListUnmanaged(?RT),
) Error!bool {
    for (fields) |field| {
        const path = if (prefix.len == 0)
            try alloc.dupe(u8, field.name)
        else
            try std.fmt.allocPrint(alloc, "{s}.{s}", .{ prefix, field.name });
        if (field.typ == .named) {
            if (moduleAliasByName(mod, field.typ.named)) |nested| {
                if (!try appendModuleAliasFields(alloc, mod, nested, path, stack, names, kinds, widths)) {
                    alloc.free(path);
                    return false;
                }
                continue;
            }
        }
        const fact = astFieldFact(field.typ) orelse {
            alloc.free(path);
            return false;
        };
        try names.append(alloc, path);
        try kinds.append(alloc, fact.kind);
        try widths.append(alloc, fact.width);
        if (names.items.len > max_record_fields) return false;
    }
    return true;
}

/// File-level `alias` tables (`pack`, `token`, `lexer`, …) are physical layouts
/// even when sema did not publish a graph table shape for them. Graph shapes win
/// on name collision; aliases fill the gap for module-local record params/returns.
fn collectRecordsFromModuleAliases(
    alloc: std.mem.Allocator,
    out: *std.ArrayList(dnir.RecordDesc),
    mod: *const ast.Module,
) Error!void {
    for (mod.body.stmts) |*stmt| {
        if (stmt.* != .alias_def) continue;
        const ad = &stmt.alias_def;
        if (findRecordName(out.items, .{ .named = ad.name }) != null) continue;
        var names: std.ArrayListUnmanaged([]const u8) = .empty;
        defer {
            for (names.items) |name| alloc.free(name);
            names.deinit(alloc);
        }
        var kinds: std.ArrayListUnmanaged(dnir.FieldKind) = .empty;
        defer kinds.deinit(alloc);
        var widths: std.ArrayListUnmanaged(?RT) = .empty;
        defer widths.deinit(alloc);
        var stack: std.ArrayListUnmanaged([]const u8) = .empty;
        defer stack.deinit(alloc);
        const appended = if (ad.fields.len > 0)
            try appendModuleAliasFields(alloc, mod, ad, "", &stack, &names, &kinds, &widths)
        else if (ad.target) |target|
            target == .record and try appendModuleRecordTypeFields(
                alloc,
                mod,
                "",
                &stack,
                target.record.fields,
                &names,
                &kinds,
                &widths,
            )
        else
            false;
        if (!appended) continue;
        const owned_fields = try names.toOwnedSlice(alloc);
        errdefer {
            for (owned_fields) |name| alloc.free(name);
            alloc.free(owned_fields);
        }
        const owned_kinds = try kinds.toOwnedSlice(alloc);
        errdefer alloc.free(owned_kinds);
        const owned_widths = try widths.toOwnedSlice(alloc);
        errdefer alloc.free(owned_widths);
        const name = try alloc.dupe(u8, ad.name);
        const record: dnir.RecordDesc = .{
            .name = name,
            .fields = owned_fields,
            .kinds = owned_kinds,
            .widths = owned_widths,
        };
        out.append(alloc, record) catch |err| {
            deinitRecord(alloc, record);
            return err;
        };
    }
}

/// Physical record layouts are a projection of exact graph descriptor edges.
/// The retired implementation walked local alias AST and then matched result
/// descriptor names downstream; that made imported and nested result shapes
/// unknowable even though sema had already resolved their homes.
fn collectRecordsFromGraph(
    alloc: std.mem.Allocator,
    out: *std.ArrayList(dnir.RecordDesc),
    graph: *const semantic_graph.SemanticGraph,
) Error!void {
    const shapes = try graph.tableDescriptorHomes(alloc);
    defer alloc.free(shapes);
    for (shapes) |shape| {
        const node = graph.tableShapeEntity(shape) orelse continue;
        const semantic_name = node.name;
        var names: std.ArrayListUnmanaged([]const u8) = .empty;
        defer {
            for (names.items) |name| alloc.free(name);
            names.deinit(alloc);
        }
        var kinds: std.ArrayListUnmanaged(dnir.FieldKind) = .empty;
        defer kinds.deinit(alloc);
        var widths: std.ArrayListUnmanaged(?RT) = .empty;
        defer widths.deinit(alloc);
        var stack: std.ArrayListUnmanaged(semantic_graph.id) = .empty;
        defer stack.deinit(alloc);
        if (!try appendGraphRecordFields(alloc, graph, shape, "", &stack, &names, &kinds, &widths)) continue;
        const owned_fields = try names.toOwnedSlice(alloc);
        errdefer {
            for (owned_fields) |name| alloc.free(name);
            alloc.free(owned_fields);
        }
        const owned_kinds = try kinds.toOwnedSlice(alloc);
        errdefer alloc.free(owned_kinds);
        const owned_widths = try widths.toOwnedSlice(alloc);
        errdefer alloc.free(owned_widths);
        const name = if (node.foreign_home != null or semantic_name == null)
            try std.fmt.allocPrint(alloc, "$shape.{d}", .{shape})
        else
            try alloc.dupe(u8, semantic_name.?);
        const record: dnir.RecordDesc = .{
            .semantic_shape = shape,
            .name = name,
            .fields = owned_fields,
            .kinds = owned_kinds,
            .widths = owned_widths,
        };
        out.append(alloc, record) catch |err| {
            deinitRecord(alloc, record);
            return err;
        };
    }
}

/// Colon-method declarations park result type in `path[1]` while ret stays inferred.
fn recordReturnNameForDecl(
    records: []const dnir.RecordDesc,
    graph: *const semantic_graph.SemanticGraph,
    fd: *const ast.FuncDecl,
) ?[]const u8 {
    if (findRecordName(records, fd.func.ret_type)) |rec| return rec.name;
    if (fd.func.ret_type == .named) {
        if (findRecordByNominal(records, fd.func.ret_type.named, graph)) |rec| return rec.name;
    }
    if (fd.method and fd.path.len >= 2 and fd.func.ret_type == .inferred) {
        const parked: ast.TypeExpr = .{ .named = fd.path[1] };
        if (findRecordName(records, parked)) |rec| return rec.name;
        if (findRecordByNominal(records, fd.path[1], graph)) |rec| return rec.name;
    }
    return null;
}

fn findRecordName(recs: []const dnir.RecordDesc, t: ast.TypeExpr) ?dnir.RecordDesc {
    if (t != .named) return null;
    for (recs) |r| {
        if (std.mem.eql(u8, r.name, t.named)) return r;
    }
    return null;
}

fn findRecordByNominal(
    recs: []const dnir.RecordDesc,
    name: []const u8,
    graph: ?*const semantic_graph.SemanticGraph,
) ?dnir.RecordDesc {
    for (recs) |r| {
        if (std.mem.eql(u8, r.name, name)) return r;
    }
    if (graph) |g| {
        for (recs) |record| {
            const shape = record.semantic_shape orelse continue;
            const shape_node = g.get(shape) orelse continue;
            if (shape_node.name) |n| {
                if (std.mem.eql(u8, n, name) and checkedRecordResultSupported(record)) return record;
            }
        }
    }
    return null;
}

fn recordForTypeExpr(
    recs: []const dnir.RecordDesc,
    t: ast.TypeExpr,
    graph: *const semantic_graph.SemanticGraph,
) ?dnir.RecordDesc {
    if (findRecordName(recs, t)) |rec| return rec;
    if (t == .named) {
        if (findRecordByNominal(recs, t.named, graph)) |rec| return rec;
    }
    return null;
}

fn recordFieldKindForParam(
    ctx: *const LowerCtx,
    obj_name: []const u8,
    field_name: []const u8,
) ?dnir.FieldKind {
    if (ctx.param_record_types.get(obj_name)) |rec_name| {
        const rec = blk: {
            for (ctx.records) |r| {
                if (std.mem.eql(u8, r.name, rec_name)) break :blk r;
            }
            if (findRecordByNominal(ctx.records, rec_name, ctx.graph)) |r| break :blk r;
            break :blk null;
        } orelse return null;
        for (rec.fields, rec.kinds) |fname, kind| {
            if (std.mem.eql(u8, fname, field_name)) return kind;
        }
    }
    return null;
}

/// DERIVED, NOT TABULATED — the same FIELD-CELL FACE, kind only. This was the
/// second statement of the partition `graphFieldFact` carried, dropping the
/// store width because a table row cell does not narrow. It now reads the one
/// owner too, so the two cannot drift apart.
fn tableFieldKind(field: types.FieldType) ?dnir.FieldKind {
    const cell = types.scalarFieldCell(field.typ) orelse return null;
    return fieldKindOf(cell);
}

fn recordFieldPrefixPresent(record: dnir.RecordDesc, prefix: []const u8) bool {
    if (prefix.len == 0) return false;
    var dotted: [512]u8 = undefined;
    const pat = std.fmt.bufPrint(&dotted, "{s}.", .{prefix}) catch return false;
    for (record.fields) |name| {
        if (std.mem.eql(u8, name, prefix)) return true;
        if (std.mem.startsWith(u8, name, pat)) return true;
    }
    return false;
}

fn recordCoversTableFields(record: dnir.RecordDesc, fields: []const types.FieldType) bool {
    if (!checkedRecordResultSupported(record)) return false;
    for (fields) |field| {
        if (tableFieldKind(field)) |want_kind| {
            var found = false;
            for (record.fields, record.kinds) |name, kind| {
                if (!std.mem.eql(u8, name, field.name)) continue;
                if (kind != want_kind) return false;
                found = true;
                break;
            }
            if (!found) return false;
        } else if (!recordFieldPrefixPresent(record, field.name)) {
            return false;
        }
    }
    return true;
}

/// One frame of the enclosing-block stack: the block and the index of the
/// statement currently being lowered within it. The counted-loop fold
/// consults the stack to prove an induction variable is dead after the
/// folded loop (no read can observe the write-back), which lets it drop the
/// write-back and its cold guard. Frames are pushed by `lowerBlock`,
/// `lowerBlockReturns`, and the module root loop, and popped by defer, so
/// every statement lowered through those paths is covered.
const BlockFrame = struct {
    block: *const ast.Block,
    idx: usize,
};

/// The liveness verdict for a fired nested counted-loop fold: which
/// induction-variable write-backs are dead and may be dropped.
const NestedFoldLiveness = struct {
    /// The outer induction variable is never read after the folded loop.
    iv_dead: bool,
    /// The inner induction variable is never read after the folded loop, so
    /// both its write-back and the cold guard around it are dead.
    inner_dead: bool,
};

/// Block-scoped value numbering for pure binary operations.
///
/// A `dnir.Value` operand that is a temp is write-once, and a slot is written
/// only by an instruction that passes through `LowerCtx.emit`, so the triple
/// (op, lhs, rhs) names a value that is stable until something redefines one
/// of its local operands. `emit` retracts every entry that mentions a stored
/// local, and any call or heap write retracts the whole table, so a hit can
/// only reuse a temp whose operands still hold the same values. Block entry
/// clears the table: no fact crosses a control-flow edge, which keeps every
/// reuse inside straight-line code where domination is textual.
///
/// Admitted only when the operation cannot fault: arithmetic and logic ops,
/// plus division-family ops with a statically nonzero literal divisor (the
/// zero trap is then not emitted at all) or on the float path (IEEE defines
/// division by zero, so there is no trap to preserve). Comparisons are
/// excluded — their C-unsigned refits rewrite the operands, which would make
/// the key lie about what was computed.
const CseKey = struct {
    op: dnir.BinOpTag,
    lhs: CseOperand,
    rhs: CseOperand,
    f64: bool,
};

const CseOperand = struct {
    kind: u8, // 0=i64, 1=temp, 2=local, 3=f64, 4=f32
    bits: u64,
};

fn cseOperand(v: dnir.Value) ?CseOperand {
    return switch (v) {
        .i64 => |x| .{ .kind = 0, .bits = @bitCast(x) },
        .temp => |t| .{ .kind = 1, .bits = t },
        .local => |s| .{ .kind = 2, .bits = s },
        .f64 => |x| .{ .kind = 3, .bits = @bitCast(x) },
        .f32 => |x| .{ .kind = 4, .bits = @as(u64, @as(u32, @bitCast(x))) },
        else => null,
    };
}

fn cseAdmits(tag: dnir.BinOpTag, f64_op: bool, rhs: dnir.Value) bool {
    switch (tag) {
        .add, .sub, .mul, .band, .bor, .bxor, .shl, .shr => return true,
        .div, .idiv, .mod => {
            if (f64_op) return true;
            return rhs == .i64 and rhs.i64 != 0;
        },
        else => return false,
    }
}

pub const LowerCtx = struct {
    alloc: std.mem.Allocator,
    diagnostic: *Diagnostic,
    records: []const dnir.RecordDesc,
    graph: *const semantic_graph.SemanticGraph,
    occurrences: *const OccurrenceBridge,
    require_graph_facts: bool,
    signature: ?*const Parameter.Map = null,
    /// Some table in this function is too wide for a select chain, so EVERY
    /// positional table here is materialized into frame memory. See
    /// `stmtsBindWideTable` for why the choice is per-function, not per-table.
    tables_in_memory: bool = false,
    externs: *std.ArrayList(dnir.Extern),
    func_record_returns: *std.StringHashMapUnmanaged([]const u8),
    /// GAP-056: per-callee ABI slot classes, so a caller marshals f64 arguments
    /// into v0..v7 instead of x0..x7. Empty means no callee needs FP slots.
    fp_params: *const std.StringHashMapUnmanaged([]bool) = &empty_fp_params,
    /// GAP-056: this function's own f64 parameters are homed in d0..d7, so
    /// staging an outgoing f64 argument would overwrite one of them.
    self_fp_params: bool = false,
    /// Whether the block currently being lowered is a return context — i.e. its
    /// value is the function's answer. A guard `if` in NON-tail position uses
    /// this to know its value-carrying branches are function exits (guard
    /// clauses) that must early-return, without disturbing the tail-slot rule
    /// that keeps trailing assignments/effects falling through.
    block_answering: bool = false,
    /// When set, tail/table returns lower to `ret_record` for this record name.
    ret_record: ?[]const u8 = null,
    /// Ordered physical classes for a graph-owned multi-result pack. Empty for
    /// scalar/void functions; no tuple representation is introduced.
    ret_pack: []const RT = &.{},
    /// Local slots that hold f64 values inside integer kernels.
    f64_slots: std.AutoHashMapUnmanaged(u32, void) = .empty,
    /// Local slots holding `str` (a `const char*`), so `#s` can lower to strlen.
    str_slots: std.AutoHashMapUnmanaged(u32, void) = .empty,
    /// Local slots holding a `*HashTable` — the binding produced by `t = {}`.
    /// `lowerIndexAssignTarget` and `lowerDynamicIndex` consult this set first
    /// so a string-keyed store/load goes through `duo_hash_store`/`duo_hash_load`
    /// instead of the positional `store_index` / select-chain path.
    hash_slots: std.AutoHashMapUnmanaged(u32, void) = .empty,
    /// How many leading slots are this relation's operands. `determinedTextLen`
    /// needs it because its safety comes from a scan of THE BODY, and an
    /// operand is bound by the CALLER, where the body cannot see it.
    param_slots: u32 = 0,
    /// Enclosing-block stack for liveness-gated write-back elimination; see
    /// `BlockFrame`. Pushed by `lowerBlock`, `lowerBlockReturns`, and the
    /// module root loop.
    enclosing: std.ArrayListUnmanaged(BlockFrame) = .empty,
    /// Positional tables whose every element is text — `{ "M", "CM", … }` —
    /// and which the rest of the body only READS. `t(k)` on one of these is a
    /// `str` at every index, constant or not.
    ///
    /// Without this set the ELEMENT lowered correctly and its TYPE was lost:
    /// `exprIsStr` had no arm for a table read, so `g = glyph(i)` never entered
    /// `str_slots`, `planConcat` chose `%lld` for `"{out}{g}"`, and printf
    /// printed the literal's ADDRESS. `examples/boring/roman.id` therefore
    /// printed a different answer on every run — the address moves with ASLR —
    /// which is the same defect class as the `v = "set" or "FB"` note on
    /// `exprIsStr` below, reached through the table surface instead.
    str_tables: std.StringHashMapUnmanaged(void) = .empty,
    /// Local slots holding `bool`. A bool rides an integer register, so nothing
    /// downstream can tell one from an i64 by its representation — only this
    /// set can, and `..` needs the answer to choose between `true` and `1`.
    bool_slots: std.AutoHashMapUnmanaged(u32, void) = .empty,
    /// Local slots whose DECLARED type is narrower than the register that holds
    /// them, keyed slot -> declared width. Set at the declaration and NEVER
    /// cleared: unlike `bool_slots`, which tracks what a slot currently holds,
    /// this is what the source said the binding IS, and a later assignment does
    /// not retype a C `uint32_t`. Every store into one of these carries the
    /// width so the backend can refit — that store is the exact place
    /// `--backend=c` writes `((uint32_t)(...))`.
    narrow_slots: std.AutoHashMapUnmanaged(u32, RT) = .empty,
    /// Slots holding a pointer value — pointer parameters/results and locals
    /// materialized by `materializeTableSlots`. `t[i]` on one of these is a
    /// scaled 8-byte load, not a select-chain.
    ptr_slots: std.AutoHashMapUnmanaged(u32, void) = .empty,
    directory: std.AutoHashMapUnmanaged(u32, void) = .empty,
    /// Slots bound to the BYTE-SEQUENCE face (GAP-145 `law.text.byte`,
    /// GAP-207). A byte sequence is not text and it is not an integer, and
    /// `dnir.Value` has no member that carries one, so this pass cannot render
    /// it. What it must not do is GUESS.
    ///
    /// `exprIsStr` answering false for the byte face left `concatOperandOk`
    /// asking `exprIsIntegral`, whose `.name` arm admits any slot that is not
    /// f64/str/ptr — a NEGATIVE test wearing the clothes of the positive one
    /// documented above it. `planConcat` then chose `%lld` for a
    /// `const char*`. Measured: `s = 'abc' ; print(s .. "Z")` printed
    /// `4370531440Z`, exit 0, no diagnostic, a different address every run.
    ///
    /// This set is the third arm. Membership is the producer's fact, read
    /// through the descriptor the semantic graph published for the quote
    /// (`publishSourceQuote` -> `types.quotedLiteralType`), never off
    /// `expr.quoted.quote`. Its only consumers are the two predicates that were
    /// answering by elimination: `exprIsIntegral` and `concatOperandOk`.
    byteseq_slots: std.AutoHashMapUnmanaged(u32, void) = .empty,
    /// Wide/opaque record parameters keyed by the parameter name.
    param_record_types: std.StringHashMapUnmanaged([]const u8) = .empty,
    /// Graph aggregate identity to the one physical base temp selected for this
    /// function. The identity and contents stay graph-owned; this map only
    /// avoids emitting a second address materialization for another access.
    aggregate_bases: std.AutoHashMapUnmanaged(semantic_graph.id, u32) = .empty,
    /// Applications this lowering answered from the graph and realized NOWHERE.
    /// Producer: `foldAggregateAccess`. Consumer: `native_backend`'s
    /// realization-count checks, through `Function.absent_applications`.
    absent_applications: std.ArrayListUnmanaged(semantic_graph.id) = .empty,
    /// Applications this lowering folded via function summaries and realized
    /// NOWHERE. Producer: `lowerExprCons` summary hook. Consumer:
    /// realization validation, through `Function.summary_folded_applications`.
    summary_folded: std.ArrayListUnmanaged(semantic_graph.id) = .empty,
    /// Static element count of a positional table, keyed by its `.len` slot, so
    /// `t[i]` with a non-constant `i` knows how many slots to select over.
    table_lens: std.AutoHashMapUnmanaged(u32, i64) = .empty,
    /// Positional tables this function proved DETERMINED: every element is an
    /// integer literal, and the whole body neither writes the name nor lets it
    /// escape. `t(k)` on one of these with a compile-time `k` is the literal,
    /// AT ANY EXTENT — see `noteConstTable`. Owns both key and value.
    const_tables: std.StringHashMapUnmanaged([]i64) = .empty,
    /// Function-body numeric constants, keyed by name. The function-body
    /// analogue of `module_consts.nums`: names bound exactly once at the
    /// body top level to a constant numeric initializer. Values come from
    /// `comptime_eval` (the producer); a `: f64`/`: f32` annotation projects
    /// through `applyFloatContract` at record time -- the annotation is the
    /// sole projection site. Consumed by `foldNumericComparison`. Owns keys.
    const_nums: std.StringHashMapUnmanaged(comptime_eval.Value) = .empty,
    /// The body being lowered, so a binding can ask what the REST of the
    /// function does with the name it is about to bind. `tables_in_memory`
    /// already establishes that a realization choice is allowed to read the
    /// whole body; this makes the same body reachable from the binding site,
    /// which is the only place a representation decision may be taken.
    body: ?*const ast.Block = null,
    /// Module-level integer constants, keyed `Name` or `Name.field`. Populated
    /// from top-level `n = <int>` and `n = { f = <int>, ... }` bindings, which
    /// are otherwise invisible inside a function body.
    module_consts: *const ModuleConsts = &empty_module_consts,
    module_globals: *const ModuleGlobals = &empty_module_globals,
    /// Root lowering owns module-scope declarations; function lowering owns
    /// lexical locals. The two scopes may share spelling, but never storage.
    module_root: bool = false,
    /// Names bound to compile-time-known i64 literals (for numeric for step, etc.).
    const_ints: std.StringHashMapUnmanaged(i64) = .empty,
    /// THE RESULT NAME OF A FUSED BODY RELATION, WHEN THE ELEMENT IT NAMES IS A
    /// LITERAL. Non-empty only while a collection relation is being lowered.
    ///
    /// It exists because a SLOT is not a VALUE to the folder. `xs(1) == 7` on a
    /// determined table folds to two instructions (`constTableRead` answers
    /// `.i64 = 7`, and `binop` over two immediates settles), while the same
    /// comparison against a slot that was just stored `7` does not — measured,
    /// `a = 7 · if a == 7` is 12 instructions today. Storing the element and
    /// binding the name to the slot would therefore have made `xs:any(…)` the
    /// SLOWER way to ask a question with a compile-time answer.
    ///
    /// Consulted BEFORE `locals` in the `.name` arm, which is what makes it a
    /// SHADOW: the element name wins for the length of the body relation, and
    /// an outer binding of the same name means exactly what it meant before and
    /// after. `gate/collection.sh`'s shadow row is the check.
    fused_literals: std.StringHashMapUnmanaged(i64) = .empty,
    /// SLOTS PROVED NON-ZERO ON EVERY PATH REACHING THE CURRENT LOWERING POINT.
    ///
    /// The only consumer is `emitDivisorZeroTrap`, and it exists because the
    /// guard that function emits was being emitted TWICE against the same
    /// register and the same zero. `while b != 0` already tests `b`, branches
    /// out of the loop when it is zero, and reaches the body only when it is
    /// not; `a % b` in that body then emitted a second `cmp b, #0` plus a
    /// branch plus an inline `abort` block, all of it dominated by a test that
    /// had just settled the identical question.
    ///
    /// A fact enters here from ONE place — the head of a `while x != 0` body —
    /// and leaves on ANY definition of the slot, which `emit` applies
    /// centrally: `b = a % b` kills `b`'s fact at the store, so the NEXT
    /// division by `b` is guarded again.
    ///
    /// PUBLISHING AFTER A GUARD THIS PASS ITSELF EMITTED WAS TRIED AND IS NOT
    /// SOUND, which is why it is absent. `if c { x = a / d }` then `y = b / d`
    /// would elide the second guard on the strength of a proof that only holds
    /// on the path through the `if`. The loop-head fact does not have that
    /// defect: it is retracted by `defer` at the end of the body, and every
    /// merge INSIDE the body is a merge of paths that all passed the head test.
    ///
    /// The set is SLOT-KEYED, not name-keyed, because a slot is what a
    /// definition and a `dnir.Value` both carry; a name that has been rebound
    /// to a different slot is a different fact and correctly misses.
    nonzero_slots: std.AutoHashMapUnmanaged(u32, void) = .empty,
    /// Block-scoped value numbering: (op, lhs, rhs, f64) -> temp, for pure
    /// binops only (see `cseAdmits`). Cleared at every block entry; `emit`
    /// retracts entries on stores and calls. A hit reuses the earlier temp
    /// instead of emitting the operation a second time.
    cse: std.HashMapUnmanaged(CseKey, dnir.Value, std.hash_map.AutoContext(CseKey), std.hash_map.default_max_load_percentage) = .empty,
    /// Statements swallowed by a multi-statement idiom prologue (currently the
    /// popcount idiom): the prologue discharged their semantics up front, so
    /// the block loop must not lower them. Keyed by statement pointer; the
    /// prologue inserts them, the loop skips them.
    popcount_swallowed: std.AutoHashMapUnmanaged(*const ast.Stmt, void) = .empty,
    satadd_swallowed: std.AutoHashMapUnmanaged(*const ast.Stmt, void) = .empty,
    /// Statements swallowed by the bit-reverse idiom prologue: it discharged
    /// the loop's whole semantics up front (post-loop r/x/i values stored),
    /// so the dispatch loop must not lower the vacuous `while`. Keyed by
    /// statement pointer; the prologue inserts, the loop skips.
    bitrev_swallowed: std.AutoHashMapUnmanaged(*const ast.Stmt, void) = .empty,
    /// Statements swallowed by the loopselect prologue: it discharged the
    /// zero-or-one-trip loop's whole semantics up front (the predicated acc
    /// add plus iv = cond), so the dispatch loop must not lower the vacuous
    /// `while`. Keyed by statement pointer; the prologue inserts, the loop
    /// skips.
    loopselect_swallowed: std.AutoHashMapUnmanaged(*const ast.Stmt, void) = .empty,
    /// Statements swallowed by the statically-zero-trip elimination: `iv = v`
    /// immediately before `while iv < n` with exact literals and `v >= n`, so
    /// the body provably never executes. The binding lowers normally; the
    /// dispatch loop must not lower the dead `while`.
    zerotrip_swallowed: std.AutoHashMapUnmanaged(*const ast.Stmt, void) = .empty,
    next_temp: u32 = 0,
    locals: std.StringHashMapUnmanaged(u32) = .empty,
    instrs: std.ArrayList(dnir.Instr) = .empty,
    /// Exact function entity being lowered. Name resolve walks this home only.
    function: ?semantic_graph.id = null,
    /// Function summaries (purity, const, arg-independence), computed on
    /// demand and retained for call-site folding. See speed/summary.zig.
    summary_cache: ?*summary.Cache = null,
    /// A counted-loop reduction armed by the block prologue for the immediately
    /// following `while` statement, or null. The prologue recognizes the shape
    /// (`iv = 0` immediately before `while iv < bound` with a provably
    /// non-negative bound and a trailing `iv = iv + 1` step); the while arm
    /// consumes the plan after register promotion and either emits the
    /// countdown or declines to the ordinary loop. Never survives past the
    /// statement it was armed for.
    counted_plan: ?CountedPlan = null,
    /// The function being lowered, when a self-call in TAIL position can be
    /// turned into a jump. Empty disables the rewrite — see `tryEmitSelfTail`.
    self_name: []const u8 = "",
    /// Its parameter slots, in order. One slot per parameter, which is what
    /// makes the reassign-and-jump legal: a record parameter occupies several
    /// slots and is excluded rather than partially written.
    self_param_slots: []const u32 = &.{},
    /// Instruction indices of `break` branches waiting for the innermost loop end.
    loop_breaks: std.ArrayListUnmanaged(std.ArrayListUnmanaged(u32)) = .empty,
    /// Back-edge targets for `continue` in the innermost loop.
    loop_heads: std.ArrayListUnmanaged(u32) = .empty,
    /// Module-level graph entity id → linker symbol from declaration provenance.
    entity_linkage: *const std.AutoHashMapUnmanaged(semantic_graph.id, []const u8),
    /// Relation level edges declared as `family(level) = (…) …` → `family__level`.
    relation_edges: *const std.StringHashMapUnmanaged([]const u8) = &empty_relation_edges,

    fn resident(ctx: *LowerCtx, name: []const u8, aggregate: semantic_graph.id, record: dnir.RecordDesc) Error!u32 {
        const base = ctx.freshTemp();
        try ctx.emit(.{ .op = .alloc_slots, .result = base, .lhs = .{ .i64 = @intCast(record.fields.len) } });
        for (record.fields, record.kinds, 0..) |field, kind, index| {
            const key = try std.fmt.allocPrint(ctx.alloc, "{s}.{s}", .{ name, field });
            defer ctx.alloc.free(key);
            const slot = ctx.locals.get(key) orelse
                return invalidGraphFacts(ctx.diagnostic, @src(), "record-parameter-place-unproved");
            const ty: RT = switch (kind) {
                .str => .str,
                .f64 => .f64,
                .i64 => if (index < record.widths.len) record.widths[index] orelse .i64 else .i64,
            };
            const cell = ctx.freshTemp();
            try ctx.emit(.{ .op = .alloc_slots, .result = cell, .lhs = .{ .i64 = 1 } });
            try ctx.emit(.{
                .op = .store_index,
                .record = record.name,
                .field = field,
                .ty = ty,
                .lhs = .{ .temp = cell },
                .rhs = .{ .i64 = 1 },
                .third = .{ .local = slot },
            });
            try ctx.emit(.{
                .op = .store_index,
                .ty = .i64,
                .lhs = .{ .temp = base },
                .rhs = .{ .i64 = @intCast(index + 1) },
                .third = .{ .temp = cell },
            });
        }
        try ctx.aggregate_bases.put(ctx.alloc, aggregate, base);
        try ctx.directory.put(ctx.alloc, base, {});
        try Record.bind(ctx, name, record, base);
        return base;
    }

    pub fn deinit(self: *LowerCtx) void {
        var it = self.locals.iterator();
        while (it.next()) |e| self.alloc.free(e.key_ptr.*);
        self.locals.deinit(self.alloc);
        self.f64_slots.deinit(self.alloc);
        self.str_slots.deinit(self.alloc);
        self.hash_slots.deinit(self.alloc);
        self.bool_slots.deinit(self.alloc);
        self.narrow_slots.deinit(self.alloc);
        self.ptr_slots.deinit(self.alloc);
        self.directory.deinit(self.alloc);
        self.byteseq_slots.deinit(self.alloc);
        self.enclosing.deinit(self.alloc);
        var pr = self.param_record_types.iterator();
        while (pr.next()) |entry| self.alloc.free(entry.key_ptr.*);
        self.param_record_types.deinit(self.alloc);
        self.aggregate_bases.deinit(self.alloc);
        self.table_lens.deinit(self.alloc);
        var ct = self.const_tables.iterator();
        while (ct.next()) |e| {
            self.alloc.free(e.key_ptr.*);
            self.alloc.free(e.value_ptr.*);
        }
        self.const_tables.deinit(self.alloc);
        var cn = self.const_nums.iterator();
        while (cn.next()) |e| self.alloc.free(e.key_ptr.*);
        self.const_nums.deinit(self.alloc);
        var st = self.str_tables.iterator();
        while (st.next()) |e| self.alloc.free(e.key_ptr.*);
        self.str_tables.deinit(self.alloc);
        var ci = self.const_ints.iterator();
        while (ci.next()) |e| self.alloc.free(e.key_ptr.*);
        self.const_ints.deinit(self.alloc);
        // Normally already empty — `ResultName.release` gives the name back at
        // the end of every collection relation. Drained here so a bail out of a
        // half-lowered body relation does not leak the key.
        var fl = self.fused_literals.iterator();
        while (fl.next()) |e| self.alloc.free(e.key_ptr.*);
        self.fused_literals.deinit(self.alloc);
        if (self.self_param_slots.len > 0) self.alloc.free(self.self_param_slots);
        while (self.loop_breaks.pop()) |breaks| {
            var pending = breaks;
            pending.deinit(self.alloc);
        }
        self.loop_breaks.deinit(self.alloc);
        self.loop_heads.deinit(self.alloc);
        self.instrs.deinit(self.alloc);
        self.nonzero_slots.deinit(self.alloc);
        self.cse.deinit(self.alloc);
        self.popcount_swallowed.deinit(self.alloc);
        self.satadd_swallowed.deinit(self.alloc);
        self.bitrev_swallowed.deinit(self.alloc);
        self.loopselect_swallowed.deinit(self.alloc);
        self.zerotrip_swallowed.deinit(self.alloc);
        self.absent_applications.deinit(self.alloc);
        self.summary_folded.deinit(self.alloc);
    }

    fn freshTemp(self: *LowerCtx) u32 {
        const t = self.next_temp;
        self.next_temp += 1;
        return t;
    }

    /// KILLING A NON-ZERO FACT IS DONE HERE AND NOWHERE ELSE.
    ///
    /// Every slot this lowering ever defines is defined by an instruction that
    /// passes through `emit`, so this one line is the whole invalidation rule
    /// and there is no second place for a new instruction kind to forget it. A
    /// slot that is written is a slot whose value is no longer the one the
    /// guard proved, whatever was written into it.
    fn emit(self: *LowerCtx, instr: dnir.Instr) Error!void {
        if (self.nonzero_slots.count() != 0) {
            if (instr.result) |r| _ = self.nonzero_slots.remove(r);
            for (instr.pack_results) |pr| if (pr.temp) |t| {
                _ = self.nonzero_slots.remove(t);
            };
        }
        // VALUE-NUMBER INVALIDATION. A stored local retracts every numbered
        // expression that names it; a call or a heap write retracts the whole
        // table, since an unknown callee or an aliased write may redefine any
        // slot. `load_global` can also carry a slot in `result` (the
        // while-loop module-binding promotion preloads into fresh slots).
        if (self.cse.count() != 0) {
            switch (instr.op) {
                .store_local, .load_global => if (instr.result) |r| try self.cseKillLocal(r),
                .store_global, .store_index, .call_direct, .call_extern => self.cse.clearRetainingCapacity(),
                else => {},
            }
        }
        try self.instrs.append(self.alloc, instr);
    }

    /// Retract every value-numbered expression that reads `slot`. Temps are
    /// write-once so they need no retraction; only `.local` operands can
    /// change under a numbered entry.
    fn cseKillLocal(self: *LowerCtx, slot: u32) Error!void {
        var dead = std.ArrayListUnmanaged(CseKey).empty;
        defer dead.deinit(self.alloc);
        var it = self.cse.iterator();
        while (it.next()) |e| {
            const k = e.key_ptr.*;
            if ((k.lhs.kind == 2 and k.lhs.bits == slot) or
                (k.rhs.kind == 2 and k.rhs.bits == slot))
            {
                try dead.append(self.alloc, k);
            }
        }
        for (dead.items) |k| _ = self.cse.remove(k);
    }
};

fn internInstrStrings(alloc: std.mem.Allocator, instrs: []dnir.Instr) Error!void {
    const Strings = struct {
        callee: []const u8 = "",
        req_alias: []const u8 = "",
        field: []const u8 = "",
        record: []const u8 = "",

        fn deinit(self: @This(), allocator: std.mem.Allocator) void {
            if (self.callee.len > 0) allocator.free(self.callee);
            if (self.req_alias.len > 0) allocator.free(self.req_alias);
            if (self.field.len > 0) allocator.free(self.field);
            if (self.record.len > 0) allocator.free(self.record);
        }
    };

    const strings = try alloc.alloc(Strings, instrs.len);
    defer alloc.free(strings);
    for (strings) |*entry| entry.* = .{};
    errdefer for (strings) |entry| entry.deinit(alloc);

    for (instrs, strings) |instruction, *entry| {
        if (instruction.callee.len > 0) entry.callee = try alloc.dupe(u8, instruction.callee);
        if (instruction.req_alias.len > 0) entry.req_alias = try alloc.dupe(u8, instruction.req_alias);
        if (instruction.field.len > 0) entry.field = try alloc.dupe(u8, instruction.field);
        if (instruction.record.len > 0) entry.record = try alloc.dupe(u8, instruction.record);
    }
    for (instrs, strings) |*instruction, entry| {
        instruction.callee = entry.callee;
        instruction.req_alias = entry.req_alias;
        instruction.field = entry.field;
        instruction.record = entry.record;
    }
}

// LAWFUL NONEXECUTION LIVES IN `comptime.zig`, NOT HERE.
//
// `bodyHasNoApplication` / `stmtHasNoApplication` / `exprHasNoApplication` /
// `bodyHasLoop` / `foldWholeBody` stood here and stand there now, verbatim,
// behind `comptime.foldRelationBody`. Keeping a copy on this side would be a
// SECOND IMPLEMENTATION OF ONE PREDICATE — the shape that produced three
// defects on this surface in a day — and the two would only have to disagree
// once for a body to be folded under one rule and lowered under the other.

/// The pack a relation's own returns declare, when no tuple annotation does.
///
/// SOURCE-INFER-ONE: the arity is uniquely recoverable from the body, and a
/// relation whose every `return a, b` agrees on two members answers a pack of
/// two regardless of whether the declaration spells it. The old path read only
/// the annotation (`resultPackTypes`), so `two = (x: i64)` with body
/// `return x * 2, x * 3` lowered ZERO declared members and then refused its
/// own return at `result-pack-arity` — a fact the body states being re-asked
/// of a declaration that never carried it.
///
/// PURE AST, deliberately. The scan names the ARITY and nothing else; each
/// member's physical class is decided at the return site itself, by the same
/// predicates (`exprIsF64` / `exprIsPointer`) that type a scalar return, so
/// this pass can never publish a member class the body then disagrees with.
/// A member that is f64 refuses at that site (`result-pack-abi`), not here.
///
/// Every multi-value return must agree on the count. A single-value return is
/// not pack evidence either way and does not veto: a relation may answer its
/// pack conditionally (`if p return a, b ; 0`). A disagreement, or no
/// multi-value return at all, leaves the declared pack exactly as given.
fn scanReturnPackArities(block: *const ast.Block, arity: *?usize) bool {
    var seen = false;
    for (block.stmts) |*stmt| {
        switch (stmt.*) {
            .ret => |r| {
                if (r.vals.len < 2) continue;
                if (arity.* == null) {
                    arity.* = r.vals.len;
                    seen = true;
                } else if (arity.* != r.vals.len) return false;
            },
            .while_loop => |*ws| {
                if (!scanReturnPackArities(&ws.body, arity)) return false;
            },
            .num_for => |*nf| {
                if (!scanReturnPackArities(&nf.body, arity)) return false;
            },
            .if_stmt => |*branch| {
                if (!scanReturnPackArities(&branch.then, arity)) return false;
                for (branch.elseifs) |*elseif| {
                    if (!scanReturnPackArities(&elseif.body, arity)) return false;
                }
                if (branch.else_body) |*else_block| {
                    if (!scanReturnPackArities(else_block, arity)) return false;
                }
            },
            .do_block => |*db| {
                if (!scanReturnPackArities(&db.body, arity)) return false;
            },
            else => {},
        }
    }
    return seen;
}

fn residency(graph: *const semantic_graph.SemanticGraph, signature: *Parameter.Map, diagnostic: *Diagnostic) Error!void {
    var changed = true;
    while (changed) {
        changed = false;
        for (graph.application_facts.items) |application| {
            const target = graph.applicationTarget(application.application) orelse continue;
            const callee = signature.get(target) orelse continue;
            const caller = graph.applicationCaller(application.application) orelse continue;
            const layout = signature.get(caller) orelse continue;
            const subject = graph.applicationSubject(application.application);
            const arguments = graph.applicationArguments(application.application) orelse continue;
            const offset: usize = @intFromBool(subject != null);
            if (callee.params.len != offset + arguments.len) continue;
            for (callee.params, 0..) |parameter, index| {
                if (parameter.record == null or !parameter.ty.eql(physical_pointer)) continue;
                const operand = if (index < offset) subject.? else arguments[index - offset];
                var binding = switch (graph.valueOrigin(operand)) {
                    .one => |value| value,
                    .none, .unknown => continue,
                };
                var remaining = graph.nodes.items.len;
                while (remaining > 0) : (remaining -= 1) {
                    const current = graph.get(binding) orelse break;
                    if (current.kind != .local or current.scope != caller) break;
                    const initialization = switch (graph.bindingInitialization(binding)) {
                        .known => |fact| fact,
                        .invalid, .unvisited => break,
                    };
                    binding = switch (graph.valueOrigin(initialization.value)) {
                        .one => |value| value,
                        .none, .unknown => break,
                    };
                }
                if (remaining == 0) return invalidGraphFacts(diagnostic, @src(), "record-alias-origin");
                const node = graph.get(binding) orelse continue;
                if (node.kind != .param or node.scope != caller) continue;
                var count: usize = 0;
                var position: ?usize = null;
                for (graph.nested.of(caller)) |child| {
                    const member = graph.get(child) orelse continue;
                    if (member.kind != .param) continue;
                    if (member.scope != caller)
                        return invalidGraphFacts(diagnostic, @src(), "function-parameter-pack");
                    if (child == binding) position = count;
                    count += 1;
                }
                const ordinal = position orelse continue;
                if (count != layout.params.len or ordinal >= layout.params.len)
                    return invalidGraphFacts(diagnostic, @src(), "function-parameter-pack");
                if (layout.params[ordinal].record == null) continue;
                for (@constCast(layout.params)) |*candidate| {
                    if (candidate.record == null or candidate.ty.eql(physical_pointer)) continue;
                    candidate.ty = physical_pointer;
                    changed = true;
                }
            }
        }
    }
}

fn lowerFunction(
    alloc: std.mem.Allocator,
    fd: *const ast.FuncDecl,
    id: ?semantic_graph.id,
    records: []const dnir.RecordDesc,
    graph: *const semantic_graph.SemanticGraph,
    occurrences: *const OccurrenceBridge,
    diagnostic: *Diagnostic,
    require_graph_facts: bool,
    externs: *std.ArrayList(dnir.Extern),
    func_record_returns: *std.StringHashMapUnmanaged([]const u8),
    fp_params: *const std.StringHashMapUnmanaged([]bool),
    module_consts: *const ModuleConsts,
    module_globals: *const ModuleGlobals,
    entity_linkage: *const std.AutoHashMapUnmanaged(semantic_graph.id, []const u8),
    relation_edges: *const std.StringHashMapUnmanaged([]const u8),
    signature: *const Parameter.Map,
    summary_cache: *summary.Cache,
) Error!dnir.Function {
    const borrowed = if (id) |entity| if (signature.get(entity)) |layout| layout.params else null else null;
    const physical = borrowed orelse try Parameter.lower(alloc, fd, records);
    defer if (borrowed == null) {
        for (physical) |parameter| deinitParam(alloc, parameter);
        alloc.free(physical);
    };
    const owned_params = try Parameter.project(alloc, physical);
    errdefer {
        for (owned_params) |parameter| deinitParam(alloc, parameter);
        alloc.free(owned_params);
    }
    var ret_pack = try resultPackTypes(alloc, fd.func.ret_type);
    errdefer if (ret_pack.len > 0) alloc.free(ret_pack);
    if (ret_pack.len == 0 and fd.func.ret_type != .tuple) {
        // The body's own returns state the pack the annotation omitted
        // (`scanReturnPackArities`). Members default to the GP register class;
        // an f64 or record member refuses at its own return site, exactly as
        // a declared pack's would. A declared empty tuple never reaches here.
        var arity: ?usize = null;
        if (scanReturnPackArities(&fd.func.body, &arity)) {
            if (arity.? > max_reg_record_fields) return error.UnsupportedConstruct;
            const inferred = try alloc.alloc(RT, arity.?);
            errdefer alloc.free(inferred);
            @memset(inferred, .i64);
            ret_pack = inferred;
        }
    }
    var ctx: LowerCtx = .{
        .alloc = alloc,
        .diagnostic = diagnostic,
        .records = records,
        .signature = signature,
        .graph = graph,
        .function = id,
        .summary_cache = summary_cache,
        .occurrences = occurrences,
        .require_graph_facts = require_graph_facts,
        .externs = externs,
        .func_record_returns = func_record_returns,
        .fp_params = fp_params,
        .entity_linkage = entity_linkage,
        .relation_edges = relation_edges,
        .self_fp_params = blk: {
            const slots = f64AbiParamSlots(fd, records) orelse break :blk false;
            break :blk slots > 0;
        },
        .module_consts = module_consts,
        .module_globals = module_globals,
        .ret_record = if (findRecordName(records, fd.func.ret_type)) |r| r.name else null,
        .ret_pack = ret_pack,
        .tables_in_memory = blockNeedsMemoryTables(&fd.func.body),
        .body = &fd.func.body,
    };
    defer ctx.deinit();

    var param_slot_cursor: u32 = 0;
    // A relation-edge / projection variant (`subject(tail) = (code)`, mangled to
    // `subject__tail`) receives the projection level (`tail`) as an implicit
    // slot-0 parameter. It occupies a real slot, so the flat-frame test below and
    // the self-param set must count it alongside the declared operand params.
    var edge_level_slots: u32 = 0;
    // A relation-edge projection level (`family(level) = (…)`, mangled
    // `family__level`) is a runtime subject parameter ONLY when the body actually
    // reads the level identifier — e.g. `len(path) = (min)` whose body uses
    // `path`, applied `len(value)(min)` / `value:len(min)` with the level passed
    // as an argument. A compile-time-only projection marker — `subject(tail)`,
    // `dot(io)`, `rules(q)` whose bodies never mention the level — is baked into
    // the mangled callee and the call passes only the real operands, so a level
    // slot here would shift every operand by one register.
    if (fd.path.len == 1) {
        if (relationEdgeLevel(fd.path[0])) |level| {
            if (ast.blockMentionsIdent(&fd.func.body, level)) {
                const owned = try alloc.dupe(u8, level);
                ctx.locals.put(alloc, owned, param_slot_cursor) catch |err| {
                    alloc.free(owned);
                    return err;
                };
                try ctx.str_slots.put(alloc, param_slot_cursor, {});
                param_slot_cursor += 1;
                edge_level_slots = 1;
            }
        }
    }
    var cursor: usize = edge_level_slots;
    for (fd.func.params) |par| {
        if (cursor >= physical.len)
            return invalidGraphFacts(ctx.diagnostic, @src(), "function-parameter-pack");
        const parameter = physical[cursor];
        cursor += 1;
        if (blk: {
            if (findRecordName(records, par.typ)) |r| break :blk r;
            if (par.typ == .named) {
                if (findRecordByNominal(records, par.typ.named, graph)) |r| break :blk r;
            }
            break :blk null;
        }) |rec| {
            const param_key = try alloc.dupe(u8, par.name);
            try ctx.param_record_types.put(alloc, param_key, rec.name);
            if (parameter.ty.eql(physical_pointer)) {
                const owned = try alloc.dupe(u8, par.name);
                ctx.locals.put(alloc, owned, param_slot_cursor) catch |err| {
                    alloc.free(owned);
                    return err;
                };
                try ctx.ptr_slots.put(alloc, param_slot_cursor, {});
                try ctx.directory.put(alloc, param_slot_cursor, {});
                param_slot_cursor += 1;
                continue;
            }
            var all_scalar = rec.fields.len > 0;
            for (rec.kinds) |kind| if (kind == .f64) {
                all_scalar = false;
            };
            if (all_scalar) {
                for (rec.fields, 0..) |field, field_index| {
                    const key = try std.fmt.allocPrint(alloc, "{s}.{s}", .{ par.name, field });
                    ctx.locals.put(alloc, key, param_slot_cursor) catch |err| {
                        alloc.free(key);
                        return err;
                    };
                    if (field_index < rec.kinds.len) switch (rec.kinds[field_index]) {
                        .str => try ctx.str_slots.put(alloc, param_slot_cursor, {}),
                        .f64 => try ctx.f64_slots.put(alloc, param_slot_cursor, {}),
                        .i64 => {},
                    };
                    if (field_index < rec.widths.len) if (rec.widths[field_index]) |width|
                        try ctx.narrow_slots.put(alloc, param_slot_cursor, width);
                    param_slot_cursor += 1;
                }
                continue;
            }
        }
        const owned = try alloc.dupe(u8, par.name);
        ctx.locals.put(alloc, owned, param_slot_cursor) catch |err| {
            alloc.free(owned);
            return err;
        };
        // A `str` parameter is a `const char*`, so `#p` inside the body can use
        // strlen just like a str local.
        if (resolveType(par.typ) == .str) try ctx.str_slots.put(alloc, param_slot_cursor, {});
        // An `f64` parameter arrives in a double register; without this
        // the body sees a GP slot and a conversion of the parameter
        // moves its BITS (the f2i miscompile) instead of converting.
        if (resolveType(par.typ) == .f64) try ctx.f64_slots.put(alloc, param_slot_cursor, {});
        // A `bool` parameter is an integer register the printer must not read as
        // a number.
        if (isBoolType(par.typ)) try ctx.bool_slots.put(alloc, param_slot_cursor, {});
        // A `ptr` parameter carries the base address of a caller's positional
        // table, so `p[i]` in the body is a scaled load off that register.
        if (typeIsPtr(par.typ)) try ctx.ptr_slots.put(alloc, param_slot_cursor, {});
        // A parameter's declared width is a declared width like any other. Only
        // `i32` can reach here — `functionEligible` refuses `u8`/`u16`/`u32`
        // parameters outright — but the body's arithmetic must still see it as
        // a 32-bit binding rather than as an i64.
        if (narrowIntOfType(par.typ)) |width| {
            try ctx.narrow_slots.put(alloc, param_slot_cursor, width);
        }
        param_slot_cursor += 1;
    }
    // Locals and temps share one id space (`freshTemp` allocates both), but the
    // parameter slots above were assigned by index rather than through it. Without
    // advancing the cursor the first temps alias the parameters, and the backend's
    // single slot->register map silently rebinds a parameter to a temp's register.
    ctx.next_temp = param_slot_cursor;
    // Slots below this are the relation's OPERANDS. A whole-body scan cannot
    // see an operand's binding, so "the body binds this name exactly once"
    // does not describe a parameter — see `determinedTextLen`.
    ctx.param_slots = param_slot_cursor;

    // §12 TAIL, armed only for a flat scalar frame. `param_slot_cursor` counts
    // the slots actually assigned above, so this equality IS the test for "one
    // slot per parameter" — a record parameter exploded into several and the
    // cursor runs ahead of the parameter list.
    // The flat scalar frame is "one slot per declared operand plus the implicit
    // projection level, if any" — a record parameter exploded into several fields
    // runs the cursor ahead of that and disqualifies the frame.
    if (param_slot_cursor == fd.func.params.len + edge_level_slots) {
        const slots = try alloc.alloc(u32, param_slot_cursor);
        for (0..param_slot_cursor) |i| slots[i] = @intCast(i);
        ctx.self_param_slots = slots;
        // Bare-name self-tail-recursion applies only to a single-path relation;
        // a method or projection-variant body reaches its own entity through a
        // mangled/qualified name, never a bare identifier, so leaving self_name
        // unset for those keeps isSelfTailCall() unchanged while operand-ABI
        // recognition (self_param_slots) still covers every declared operand.
        if (fd.path.len == 1 and edge_level_slots == 0) ctx.self_name = fd.path[0];
    }

    // LAWFUL NONEXECUTION. A relation that takes no operands and whose body the
    // compile-time evaluator can run to an integer does not need a body at
    // runtime — the value IS the answer, so emit it and lower nothing.
    //
    // This is the elimination frontier's first instance: the evaluator already
    // executes `while` and `for` (evalWhile / evalNumFor), so a bounded loop
    // folds here even though the backend has no loop-folding pass of its own.
    // Measured before this: `while i <= 100 : s += i` emitted 15 instructions
    // and a real branch.
    //
    // Fails CLOSED: any evaluator error — an unsupported construct, a world
    // effect, the step limit — falls through to ordinary lowering. Nothing is
    // assumed foldable; it is folded only when it actually evaluated.
    // THE MODULE'S INITIALIZERS ARE NOT AN ENTRY'S JOB, AND THEY USED TO BE.
    //
    // This is where a store of every module-global initializer was emitted,
    // guarded on `fd.path[0] == "main"`. A LIBRARY OBJECT HAS NO `main`, so the
    // store existed nowhere and `global G: i64 = 7` started at 0 — `ok compile`,
    // exit 0, no diagnostic, and a C driver calling `bump(); bump(); peek()`
    // read `1 2 2` where the answer is `8 9 9`. Measured at 3260b1e5, `--emit
    // obj` and `--emit dylib` alike.
    //
    // An initializer that is a compile-time constant is a PROPERTY OF THE
    // STORAGE, not an instruction anybody runs: it belongs in the image the
    // loader maps, which is what `dnir.Module.globals` now carries and what
    // `__DATA,__data` realizes. `HPLS.md` §31 — absence is a representation —
    // and §76-77, where startup and loader work are first-class costs: the
    // right number of instructions for a load-time constant is zero, in EVERY
    // artifact kind, which is also the only way exe and obj can agree by
    // construction rather than by a guard naming one function.
    //
    // An initializer that does NOT fold is refused in `lowerModuleFromGraph`,
    // so nothing reaches here needing a store.

    try lowerBlock(&ctx, &fd.func.body, true);

    // LAWFUL NONEXECUTION. A relation taking no operands whose body the
    // compile-time evaluator runs to an integer does not need that body at
    // runtime — the value IS the answer. The evaluator already executes `while`
    // and `for`, so a bounded loop folds here although the backend has no
    // loop-folding pass of its own. Measured before: `while i <= 100 : s += i`
    // emitted 15 instructions and a real branch; now 2 and none.
    //
    // THE BODY IS LOWERED FIRST AND ONLY THEN DISCARDED. Skipping `lowerBlock`
    // also skips the graph bookkeeping it performs, and an application that was
    // never lowered is never resolved: a body reading `os.args` folded to a
    // constant while leaving an unresolved application behind, and a call that
    // could NOT resolve would have been hidden rather than diagnosed. Lowering
    // first keeps every check; only the emitted instructions are replaced.
    //
    // Fails CLOSED: any evaluator error — an unsupported construct, an unbound
    // name like `os.args`, the step limit — leaves the lowered body in place.
    //
    // APPLICATIONS ARE ADMITTED NOW, and the predicate that decides it lives
    // ONCE, in `comptime.zig`. `foldRelationBody` keeps the old behaviour
    // VERBATIM for a body that applies nothing — same two guards, same budget,
    // same evaluator, empty bindings — so routing it in here cannot move a case
    // that folded before; the new capability is confined to the branch where the
    // body does apply something, and that branch is gated on
    // `ApplicationFact.effect` through `graph_query.effectFreeCalleeClosure`.
    var folded = false;
    if (fd.func.params.len == 0 and !fd.func.vararg and fd.func.vararg_name == null) {
        if (comptime_eval.foldRelationBody(alloc, graph, id, &fd.func)) |k| {
            ctx.instrs.clearRetainingCapacity();
            try ctx.emit(.{ .op = .ret, .lhs = .{ .i64 = k } });
            // THE APPLICATIONS INSIDE THIS BODY ARE NOW REALIZED NOWHERE, and
            // that has to be SAID. `native_backend` requires every published
            // application to be realized exactly once; a folded relation
            // realizes none of its own, and without this fact the count check
            // reads the difference as a dropped call (DNB011). Published on the
            // function rather than back onto the graph — see
            // `native_ir.Function.folded_to_constant`.
            folded = true;
        }
    }

    // A void body has no tail result to return from, so nothing emitted `ret`
    // and the backend's "did this function return?" check failed the module.
    // The value is never read by any caller; it exists so the epilogue runs.
    if (isVoidType(fd.func.ret_type)) {
        const ends_in_ret = ctx.instrs.items.len > 0 and
            ctx.instrs.items[ctx.instrs.items.len - 1].op == .ret;
        if (!ends_in_ret) try ctx.emit(.{ .op = .ret, .lhs = .{ .i64 = 0 }, .ty = .any });
    }

    const owned_instrs = try ctx.instrs.toOwnedSlice(alloc);
    var strings_interned = false;
    errdefer {
        if (strings_interned) {
            for (owned_instrs) |instruction| dnir.deinitInstr(alloc, instruction);
        } else {
            for (owned_instrs) |instruction| {
                if (instruction.vals.len > 0) alloc.free(instruction.vals);
                if (instruction.pack_results.len > 0) alloc.free(instruction.pack_results);
            }
        }
        alloc.free(owned_instrs);
    }
    try internInstrStrings(alloc, owned_instrs);
    strings_interned = true;

    const blocks = try alloc.alloc(dnir.Block, 1);
    errdefer alloc.free(blocks);
    blocks[0] = .{ .instrs = owned_instrs };

    // A RELATION THAT FOLDED WHOLE REALIZES NONE OF ITS OWN, and
    // `unrealizedApplicationCount` already counts every one of them from
    // `folded_to_constant`. Listing them again here would subtract them twice.
    const owned_absent = if (folded)
        try alloc.alloc(semantic_graph.id, 0)
    else
        try ctx.absent_applications.toOwnedSlice(alloc);
    errdefer alloc.free(owned_absent);
    const owned_summary_folded = if (folded)
        try alloc.alloc(semantic_graph.id, 0)
    else
        try ctx.summary_folded.toOwnedSlice(alloc);
    errdefer alloc.free(owned_summary_folded);

    const ret_rec = findRecordName(records, fd.func.ret_type);
    const ret_record_name = if (ret_rec) |r| try alloc.dupe(u8, r.name) else null;
    errdefer if (ret_record_name) |record| alloc.free(record);
    const graph_linkage = if (id) |entity| graph.callableLinkage(entity) else null;
    if (graph.requiresCallableLinkage() and graph_linkage == null)
        return invalidGraphFacts(diagnostic, @src(), "missing-callable-linkage");
    const export_name = if (graph_linkage) |linkage|
        try alloc.dupe(u8, linkage.symbol)
    else
        try funcExportName(alloc, graph.selfHome(), fd);
    errdefer alloc.free(export_name);
    return .{
        .name = export_name,
        .ret = resolveType(fd.func.ret_type),
        .ret_pack = ret_pack,
        .params = owned_params,
        .ret_record = ret_record_name,
        .foreign_boundary = if (graph_linkage) |linkage|
            linkage.exposure != .internal
        else
            foreignBoundaryName(fd) != null,
        .is_float_kernel = blk: {
            const slots = f64AbiParamSlots(fd, records) orelse break :blk false;
            break :blk slots > 0 and slots <= 8;
        },
        .id = id,
        .folded_to_constant = folded,
        .absent_applications = owned_absent,
        .summary_folded_applications = owned_summary_folded,
        .blocks = blocks,
    };
}

/// Physical process entry from the file-scope tail. The DNIR name `main` is
/// the linker ABI, not a source binding.
fn root(
    alloc: std.mem.Allocator,
    mod: *const ast.Module,
    id: ?semantic_graph.id,
    records: []const dnir.RecordDesc,
    graph: *const semantic_graph.SemanticGraph,
    occurrences: *const OccurrenceBridge,
    diagnostic: *Diagnostic,
    require_graph_facts: bool,
    externs: *std.ArrayList(dnir.Extern),
    func_record_returns: *std.StringHashMapUnmanaged([]const u8),
    fp_params: *const std.StringHashMapUnmanaged([]bool),
    module_consts: *const ModuleConsts,
    module_globals: *const ModuleGlobals,
    entity_linkage: *const std.AutoHashMapUnmanaged(semantic_graph.id, []const u8),
    relation_edges: *const std.StringHashMapUnmanaged([]const u8),
    signature: *const Parameter.Map,
) Error!dnir.Function {
    var ctx: LowerCtx = .{
        .alloc = alloc,
        .diagnostic = diagnostic,
        .records = records,
        .signature = signature,
        .graph = graph,
        .function = id,
        .occurrences = occurrences,
        .require_graph_facts = require_graph_facts,
        .externs = externs,
        .func_record_returns = func_record_returns,
        .fp_params = fp_params,
        .entity_linkage = entity_linkage,
        .relation_edges = relation_edges,
        .module_consts = module_consts,
        .module_globals = module_globals,
        .module_root = true,
        .ret_record = null,
    };
    defer ctx.deinit();
    for (mod.body.stmts, 0..) |*stmt, i| {
        try pushEnclosingFrame(&ctx, &mod.body, i);
        defer popEnclosingFrame(&ctx);
        // A fired additive prologue claims the statement: the counted-loop
        // arming is excluded so an armed reduction cannot re-run a loop the
        // prologue already finalized (its trip test is false on entry).
        const claimed = try runAdditivePrologues(&ctx, mod.body.stmts, i);
        if (!claimed) tryArmCountedLoop(&ctx, mod.body.stmts, i);
        // A prologue may have swallowed this statement (bitrev/loopselect
        // swallow the loop they replace; satadd/popcount discharge their
        // idioms up front); do not lower it.
        if (ctx.popcount_swallowed.contains(stmt)) continue;
        if (ctx.satadd_swallowed.contains(stmt)) continue;
        if (ctx.bitrev_swallowed.contains(stmt)) continue;
        if (ctx.loopselect_swallowed.contains(stmt)) continue;
        if (ctx.zerotrip_swallowed.contains(stmt)) continue;
        // A provably-redundant `x = x & INT64_MAX` mask is skipped, not emitted.
        if (try trySkipInt64MaxMask(&ctx, mod.body.stmts, i, stmtIsTailSlot(&mod.body, i))) continue;
        switch (stmt.*) {
        .func_decl,
        .const_decl,
        .global_decl,
        .alias_def,
        .enum_def,
        .macro_def,
        .concept_def,
        .cinclude,
        .directive,
        => {},
        // The module's value is the program's exit code, so the last
        // statement (when there is no tail_expr) is in the tail slot.
        // Without this a tail `if` with different-valued arms lowered its
        // arms as effects and the module fell through to `ret 0`:
        // `if 1 == 2 / 7 / else / 9` exited 0 instead of 9.
        else => try lowerStmt(&ctx, stmt, stmtIsTailSlot(&mod.body, i)),
        }
    }
    if (tail_result_demand.blockTailResult(&mod.body)) |tail| {
        if (status(&ctx, tail.expr)) {
            _ = try tryEmitTailDemandReturn(&ctx, &mod.body);
        } else if (tailAnchoredAway(&mod.body, tail)) {
            // The resolved value anchored to an earlier statement that has
            // ALREADY been lowered by the loop above, so re-lowering it here
            // buys nothing and re-evaluates it; the file's tail expression is
            // the only thing still owed an emission. See `tailAnchoredAway`.
            try lowerBlockTailEffect(&ctx, &mod.body);
        } else {
            _ = try lowerExprCons(&ctx, tail.expr, .discard);
        }
    }
    // A trailing control-flow statement may leave its `ret` INSIDE a branch
    // (the tail-if whose then-arm returns), with the fall-through `br`
    // targeting the past-the-end sentinel. The `last op != .ret` check cannot
    // see into branches; a trailing conditional always needs its join point
    // materialized as a real instruction, or the false edge falls through
    // into whatever symbol the linker placed next.
    const last_is_branch = blk: {
        if (mod.body.stmts.len == 0) break :blk false;
        break :blk switch (mod.body.stmts[mod.body.stmts.len - 1]) {
            .if_stmt, .while_loop, .num_for, .gen_for => true,
            else => false,
        };
    };
    if (ctx.instrs.items.len == 0 or last_is_branch or ctx.instrs.items[ctx.instrs.items.len - 1].op != .ret) {
        try ctx.emit(.{ .op = .ret, .lhs = .{ .i64 = 0 }, .ty = .any });
    }
    const owned_instrs = try ctx.instrs.toOwnedSlice(alloc);
    var strings_interned = false;
    errdefer {
        if (strings_interned) {
            for (owned_instrs) |instruction| dnir.deinitInstr(alloc, instruction);
        } else {
            for (owned_instrs) |instruction| {
                if (instruction.vals.len > 0) alloc.free(instruction.vals);
                if (instruction.pack_results.len > 0) alloc.free(instruction.pack_results);
            }
        }
        alloc.free(owned_instrs);
    }
    try internInstrStrings(alloc, owned_instrs);
    strings_interned = true;
    const blocks = try alloc.alloc(dnir.Block, 1);
    errdefer alloc.free(blocks);
    blocks[0] = .{ .instrs = owned_instrs };
    const owned_absent = try ctx.absent_applications.toOwnedSlice(alloc);
    errdefer alloc.free(owned_absent);
    const owned_summary_folded = try ctx.summary_folded.toOwnedSlice(alloc);
    errdefer alloc.free(owned_summary_folded);
    const export_name = try alloc.dupe(u8, "main");
    errdefer alloc.free(export_name);
    return .{
        .name = export_name,
        .ret = .i64,
        .params = &.{},
        .ret_record = null,
        .id = id,
        .absent_applications = owned_absent,
        .summary_folded_applications = owned_summary_folded,
        .blocks = blocks,
    };
}

fn resolveType(t: ast.TypeExpr) RT {
    return switch (t) {
        .named => |n| blk: {
            if (std.mem.eql(u8, n, "i64")) break :blk .i64;
            if (isIntAlias(n)) break :blk .i64;
            if (std.mem.eql(u8, n, "i32")) break :blk .i32;
            if (std.mem.eql(u8, n, "str")) break :blk .str;
            if (std.mem.eql(u8, n, "bool")) break :blk .bool;
            if (std.mem.eql(u8, n, "f64")) break :blk .f64;
            if (std.mem.eql(u8, n, "ptr") or std.mem.eql(u8, n, "void*")) break :blk physical_pointer;
            break :blk .any;
        },
        .inferred => .any,
        .pointer => physical_pointer,
        else => .any,
    };
}

/// `int` and `integer` ARE `i64`, and this is not a courtesy: `types.zig`
/// resolves both to `.i64` under "Common aliases", so they are the same type by
/// the language's own answer. This pass matched the two spellings `i64` and
/// `i32` literally, so `exit(code: int)` in `lib/os.id` was ineligible —
/// and because `lowerModule` requires EVERY function in a module to lower, one
/// spliced `os.exit` refused the whole program. Two spellings of one type, and
/// the narrower reading cost every program that touches `std.os`.
///
/// Only the exact aliases. `i8`, `u32` and friends resolve to their own widths
/// and would need truncation this pass does not emit, so they stay out.
fn isIntAlias(n: []const u8) bool {
    return std.mem.eql(u8, n, "int") or std.mem.eql(u8, n, "integer");
}

// ---------------------------------------------------------------------------
// DECLARED INTEGER WIDTH
//
// `resolveType` above answers `.any` for `u8`/`u16`/`u32` and `.i32` for `i32`,
// and until this section existed NOTHING downstream ever read a width: every
// value lived at 64 bits from the literal to the exit status. So
//
//     h: u32 = 4294967295
//     h = h + 5
//
// answered 4294967300 under the DEFAULT backend and 4 under `--backend=c`,
// which emits a real `uint32_t` and a real `((uint32_t)(...))` cast. The same
// silence produced 79 instead of 118 from `tools/wasm/bench/hash.id`, a
// 200M-iteration FNV hash whose true answer (1899277430, low byte 118) is
// recorded in its own header and was recomputed independently.
//
// THE WIDTH IS KNOWN HERE AND ONLY HERE. Sema types the binding, but the DNIR
// instruction stream had no field carrying it to the arithmetic — `Instr.ty`
// existed and was written `.any` for every integer op. These helpers put the
// declared width INTO `Instr.ty`, and `native_backend.emitNarrowFit` reads it
// back out. Nothing is reconstructed from context.
// ---------------------------------------------------------------------------

/// THE PROJECTION MOVED TO `types.zig`, BESIDE THE DESCRIPTOR IT BELONGS TO.
///
/// It had to. `comptime.zig`'s folder must apply the SAME projection this file
/// hands to the store, and `dnir_lower` already imports `comptime.zig`, so the
/// folder could not import this one. It answered in the full 64-bit ring
/// instead and `t: i32` folded to a value no store could ever hold.
///
/// These are ALIASES, not copies — `native_backend` already reaches the
/// projection this way (`const narrowFit = dnir_lower.narrowFit;`) and keeps
/// doing so unchanged.
pub const NarrowFit = types.NarrowFit;

pub fn narrowFit(ty: RT) ?NarrowFit {
    return ty.narrowFit();
}

/// DO THE LOW 32 BITS OF THIS OPERATION DEPEND ONLY ON THE LOW 32 BITS OF ITS
/// OPERANDS?
///
/// True for exactly `add`, `sub`, `mul`, `band`, `bor` and `bxor`: carries and
/// borrows travel upward and the bitwise three are bit-local, so the answer
/// modulo 2^32 is a function of the operands modulo 2^32. That is the ONLY
/// property a 32-bit destination form needs — no known-bits lattice, no
/// canonical operands, no range fact.
///
/// FALSE FOR EVERYTHING ELSE, and the exclusions are the load-bearing part:
/// `shl`/`shr` are ranked `.int64` by `exprCRank` because the operand is
/// WIDENED before the shift, and the two forms mask the amount to a different
/// number of bits besides; `div`/`idiv`/`mod` are realized with SIGNED
/// division, which reads bit 31 as a sign in the narrow form; comparisons carry
/// no width at all.
///
/// Shared with `native_backend`, which selects the realization from it, so the
/// rule that admits the transform and the rule that emits it are one function.
pub fn lowThirtyTwoExact(op: dnir.BinOpTag) bool {
    return switch (op) {
        .add, .sub, .mul, .band, .bor, .bxor => true,
        else => false,
    };
}

/// The compile-time half of `native_backend.emitNarrowFit`: the value the refit
/// instruction would produce, for a literal that never reaches a register.
///
/// The two MUST agree bit for bit. A folded constant that skipped the
/// truncation the register path performs is a decision computed against one
/// state and read against another — the shape behind every silent wrong answer
/// in this tree. `native_backend` calls THIS function rather than carrying its
/// own copy.
pub const narrowFitConst = types.narrowFitConst;

/// The declared narrow width of a type expression, or null for everything else.
///
/// `i32` is included even though `resolveType` already answers `.i32`: nothing
/// downstream had ever acted on that answer, so `h: i32 = 2147483647; h = h + 1`
/// printed 2147483648 where C printed -2147483648.
const narrowIntOfType = types.narrowIntOfType;

/// C's integer-promotion rank for an operand, as `--backend=c` computes it —
/// because that backend emits real C and real C types, so its arithmetic IS
/// C's usual arithmetic conversions and the differential is decided by them.
///
/// Measured, not assumed. `uint8_t e = 250` then `print(e + 10)` prints **260**
/// under `--backend=c`: `u8` and `u16` promote to `int`, so the addition is not
/// narrow at all and must not be truncated. `uint32_t a` then `print(a + 5)`
/// prints **4**: `u32` promotes to `unsigned int`, which is where the wrap
/// lives. `int32_t b` then `print(b + 1)` prints 2147483648 — signed overflow
/// is undefined in C and the emitted program does not wrap it, so neither does
/// this. `.int32` therefore means "promoted to a 32-bit type whose overflow is
/// not defined", and only `.uint32` earns a refit.
const CRank = enum { int32, uint32, int64 };

fn crankOfNarrow(ty: RT) CRank {
    return switch (ty) {
        .u32 => .uint32,
        // `u8`, `u16`, `i8`, `i16`, `i32` all promote to `int`.
        .u8, .u16, .i8, .i16, .i32 => .int32,
        else => .int64,
    };
}

/// C's usual arithmetic conversions over two promoted operands.
fn crankJoin(a: CRank, b: CRank) CRank {
    if (a == .int64 or b == .int64) return .int64;
    if (a == .uint32 or b == .uint32) return .uint32;
    return .int32;
}

fn isIntType(t: ast.TypeExpr) bool {
    return t == .named and (std.mem.eql(u8, t.named, "i64") or
        std.mem.eql(u8, t.named, "i32") or std.mem.eql(u8, t.named, "u64") or
        isIntAlias(t.named));
}

/// `bool` rides an integer register like any other scalar.
///
/// It was absent from the eligibility predicate entirely, so one `bool`
/// parameter refused the WHOLE module (lowerModule requires every function to
/// lower) — `branch_sum(cond: bool): i64` reported DNB002 while the identical
/// function taking `i64` lowered. Nothing downstream needed teaching: `true`
/// and `false` already lower to `.i64` 1 and 0, `resolveType` already maps the
/// name to `RT.bool`, and the backend routes every non-`.f64` parameter through
/// x0..x7. Only the gate was missing.
///
/// Kept SEPARATE from `isIntType` rather than folded into it: `isIntType` also
/// answers "may this be a record field kind" and "may this be a numeric-for
/// index", and a boolean loop counter is not a thing this admits by accident.
fn isBoolType(t: ast.TypeExpr) bool {
    return t == .named and std.mem.eql(u8, t.named, "bool");
}

fn isStrType(t: ast.TypeExpr) bool {
    return t == .named and std.mem.eql(u8, t.named, "str");
}

/// `: void` — a function that exists for its effects.
///
/// Rejecting these made a whole MODULE ineligible, not just the function:
/// lowerModule requires every function to lower, so one `render(): void`
/// alongside natively-lowerable helpers bailed the lot (mandelbrot, test_sql).
fn isVoidType(t: ast.TypeExpr) bool {
    return t == .named and std.mem.eql(u8, t.named, "void");
}

/// `any` rides a single GP register at the ABI — same shape as `i64`/`str`/
/// `ptr`/`bool`, no class-specific lowering. Functions that return it are
/// the lawful shape for a generic thunk whose result descriptor is unknown
/// at the call site (see `examples/hash/agreement.id`'s `box: any = (x) x`).
/// Admitting `any` here is the same admission `lowerPrint` already had to
/// make for its `print(x: any)` shape — the type system carries it as the
/// catch-all register-typed descriptor, and refusing it at function-
/// declaration time meant every generic forwarder had to widen its
/// parameter face, which is the opposite of the monotonicity the law
/// asked for.
fn isAnyType(t: ast.TypeExpr) bool {
    return t == .named and std.mem.eql(u8, t.named, "any");
}

/// True when the file-scope tail *is* the process status (integer, bool, or
/// f64 that the ABI widens). A str or other value is produced for its effects
/// and must not leak a register as `_main`'s i64.
fn status(ctx: *LowerCtx, expr: *const ast.Expr) bool {
    if (effect(expr)) return false;
    if (exprIsStr(ctx, expr)) return false;
    return exprIsIntegral(ctx, expr) or exprIsBoolish(ctx, expr) or exprIsF64(ctx, expr);
}

/// A tail call that yields nothing — its value is not a result, it is an effect.
///
/// DEMAND (rule 3) makes the last expression of a block its result, which is
/// right for every expression that HAS one. `print` and `stdout:write` do not:
/// they are egress. An if-body ending in `print(" ")` or a file whose tail is
/// `stdout:write("hi")` is a discarded statement in tail position. Returning
/// the `puts` register made write-only roots exit 61.
///
/// Syntactic rather than type-directed because `LowerCtx` carries no type map.
/// A general rule wants the callee's declared return type.
fn effect(expr: *const ast.Expr) bool {
    switch (expr.*) {
        .call => |c| {
            const callee = c.func;
            return callee.* == .name and std.mem.eql(u8, callee.name.ident, "print");
        },
        .method_call => |mc| {
            if (mc.obj.* != .name or mc.args.len != 1) return false;
            return std.mem.eql(u8, mc.obj.name.ident, "stdout") and
                std.mem.eql(u8, mc.method, "write");
        },
        else => return false,
    }
}

/// §12 TAIL — a self-call in tail position is a JUMP, not a frame.
///
/// `tail = (n, acc) … tail(n - 1, acc + 1)` at ten million deep is the
/// fixture; the direct backend pushed ten million frames and took SIGSEGV
/// where the C backend answered 10000000, because clang does the sibling call
/// and this pass did not. The rewrite is the standard one: evaluate the
/// arguments, write them over the parameter slots, branch to instruction 0.
///
/// Every argument lands in a FRESH TEMP before any slot is written. Writing
/// them in place would make `tail(acc, n)` — a swap — read the parameter it had
/// already overwritten, which is a wrong answer rather than a crash.
///
/// Declined, not guessed, whenever the frame is not a flat row of scalar slots:
/// a record parameter occupies several slots, an f64 parameter arrives in the
/// FP file, and a record return leaves through x8. Each of those needs its own
/// reassignment and none of them is this rewrite.
fn tryEmitSelfTail(ctx: *LowerCtx, expr: *const ast.Expr) Error!bool {
    if (ctx.self_name.len == 0) return false;
    if (expr.* != .call) return false;
    // A checked application cannot become a branch until the semantic graph
    // supplies a transform id and witness. Let ordinary checked-call
    // lowering retain the application instead of authorizing a rewrite from
    // the callee spelling.
    if (ctx.occurrences.get(expr) != null) return false;
    if (ctx.require_graph_facts and !ctx.graph.bootstrapApplicationExpr(expr))
        return refuseMissingApplication(ctx, @src(), expr);
    const c = expr.call;
    if (c.func.* != .name) return false;
    if (!std.mem.eql(u8, c.func.name.ident, ctx.self_name)) return false;
    if (c.args.len != ctx.self_param_slots.len) return false;
    if (ctx.ret_record != null) return false;
    if (ctx.self_fp_params) return false;
    for (c.args) |a| {
        if (exprTouchesF64(ctx, a)) return false;
    }

    var staged: [8]u32 = undefined;
    if (c.args.len > staged.len) return false;
    for (c.args, 0..) |a, i| {
        const v = try lowerExprCons(ctx, a, .single);
        staged[i] = ctx.freshTemp();
        try ctx.emit(.{ .op = .store_local, .result = staged[i], .lhs = v, .ty = .any });
    }
    for (ctx.self_param_slots, 0..) |slot, i| {
        try ctx.emit(.{ .op = .store_local, .result = slot, .lhs = .{ .local = staged[i] }, .ty = .any });
    }
    try ctx.emit(.{ .op = .br, .branch_target = 0 });
    return true;
}

fn tryEmitTailDemandReturn(ctx: *LowerCtx, block: *const ast.Block) Error!bool {
    const r = tail_result_demand.blockTailResult(block) orelse return false;
    // The tail expression still runs even when the block's VALUE came from an
    // earlier statement. See `tailAnchoredAway`.
    if (tailAnchoredAway(block, r)) try lowerBlockTailEffect(ctx, block);
    // gap[033]: emitting `ret` here made `if c print(" ") end` compile to
    // `return print(" ")`, returning whatever register the void call left —
    // exit 59, and 224 with an else, where the C backend exits 0. Lower it as
    // the effect it is and report "no return", so the branch falls through.
    if (effect(r.expr)) {
        _ = try lowerExprCons(ctx, r.expr, .discard);
        return false;
    }
    const ret_ty: RT = if (exprIsF64(ctx, r.expr))
        .f64
    else if (exprIsPointer(ctx, r.expr))
        physical_pointer
    else
        .any;
    if (ctx.ret_record != null and (r.expr.* == .table or isRecordLocalName(ctx, r.expr))) {
        try lowerRecordReturn(ctx, r.expr);
        return true;
    }
    // A trailing compound assignment has ALREADY been lowered as a statement,
    // so its storage holds the answer. Lowering `r.expr` here would evaluate
    // `x * 2` a second time against the updated `x` — `twice(5)` returned 20
    // where the C backend returned 10, and `v.x += amt` returned 5+3+3 for
    // 5+3. Return the slot, not the expression.
    if (r.rule == .tail_compound_assignment) {
        if (r.target) |target| {
            if (compoundTargetSlot(ctx, target)) |slot| {
                try ctx.emit(.{ .op = .ret, .lhs = .{ .local = slot }, .ty = ret_ty });
                return true;
            }
            // A MODULE GLOBAL IS STORAGE THIS PASS CAN NAME — it just is not a
            // LOCAL SLOT. `compoundTargetSlot` asks `ctx.locals` and nothing
            // else, so `A = A .. line` and `N = N + 1` as a function's tail
            // both fell to the refusal below even though the assignment above
            // had already emitted a `store_global` for exactly that name. The
            // invariant the comment demands is satisfied by reading the
            // storage back, not by re-evaluating: `load_global` after
            // `store_global` is the value that was stored, once.
            // The same storage one level down: `M.x += 1` as a tail has
            // already been lowered as a statement, and its `__DATA` word holds
            // the answer. Reading it back is the invariant the comment above
            // demands; re-evaluating the update expression would apply the
            // operator twice.
            if (target.* == .field and target.field.obj.* == .name) {
                var fbuf: [512]u8 = undefined;
                const fkey = std.fmt.bufPrint(&fbuf, "{s}.{s}", .{
                    target.field.obj.name.ident,
                    target.field.field,
                }) catch "";
                if (fkey.len > 0 and ctx.locals.get(fkey) == null) {
                    if (moduleFieldWord(ctx, target.field.obj.name.ident, fkey)) |pair| {
                        const gty = pair[0];
                        const storage_key = pair[1];
                        const t = ctx.freshTemp();
                        try ctx.emit(.{
                            .op = .load_global,
                            .result = t,
                            .field = storage_key,
                            .ty = gty,
                        });
                        try ctx.emit(.{
                            .op = .ret,
                            .lhs = .{ .temp = t },
                            .ty = if (gty == .f64) .f64 else ret_ty,
                        });
                        return true;
                    }
                }
            }
            if (target.* == .name) {
                if (ctx.locals.get(target.name.ident) == null) {
                    if (ctx.module_globals.types.get(target.name.ident)) |gty| {
                        const t = ctx.freshTemp();
                        try ctx.emit(.{
                            .op = .load_global,
                            .result = t,
                            .field = target.name.ident,
                            .ty = gty,
                        });
                        if (gty == .str) try ctx.str_slots.put(ctx.alloc, t, {});
                        try ctx.emit(.{
                            .op = .ret,
                            .lhs = .{ .temp = t },
                            .ty = if (gty == .f64) .f64 else ret_ty,
                        });
                        return true;
                    }
                }
            }
        }
        // No storage this pass can name. Re-evaluating would be a miscompile,
        // so the function is declined rather than mis-lowered.
        return bail(ctx.diagnostic, @src());
    }
    if (ctx.occurrences.get(r.expr)) |occ| {
        if (applicationRealizationEmitted(ctx, occ.application)) {
            if (try tryEmitTailAssignStorageReturnForApplication(ctx, block, occ.application, ret_ty))
                return true;
            if (r.rule == .tail_call and block.stmts.len > 0) {
                const last = &block.stmts[block.stmts.len - 1];
                if (last.* == .assign) {
                    const as = last.assign;
                    if (as.values.len == 1 and as.values[0] == r.expr) return false;
                }
            }
        }
    }
    if (try tryEmitSelfTail(ctx, r.expr)) return true;
    try ctx.emit(.{ .op = .ret, .lhs = try lowerExpr(ctx, r.expr), .ty = ret_ty });
    return true;
}

fn applicationRealizationEmitted(ctx: *const LowerCtx, application: semantic_graph.id) bool {
    for (ctx.instrs.items) |instr| {
        if (instr.op != .call_direct) continue;
        const app = instr.application orelse continue;
        if (std.meta.eql(app, application)) return true;
    }
    return false;
}

fn tryEmitTailAssignStorageReturn(
    ctx: *LowerCtx,
    target: *const ast.Expr,
    retTy: RT,
) Error!bool {
    switch (target.*) {
        .name => |n| {
            if (ctx.locals.get(n.ident)) |slot| {
                try ctx.emit(.{ .op = .ret, .lhs = .{ .local = slot }, .ty = retTy });
                return true;
            }
            if (ctx.module_globals.types.get(n.ident)) |gty| {
                const t = ctx.freshTemp();
                try ctx.emit(.{ .op = .load_global, .result = t, .field = n.ident, .ty = gty });
                try ctx.emit(.{ .op = .ret, .lhs = .{ .temp = t }, .ty = if (gty == .f64) .f64 else retTy });
                return true;
            }
        },
        .field => {
            if (compoundTargetSlot(ctx, target)) |slot| {
                try ctx.emit(.{ .op = .ret, .lhs = .{ .local = slot }, .ty = retTy });
                return true;
            }
        },
        else => {},
    }
    return false;
}

fn tryEmitTailAssignStorageReturnForApplication(
    ctx: *LowerCtx,
    block: *const ast.Block,
    application: semantic_graph.id,
    retTy: RT,
) Error!bool {
    if (block.stmts.len == 0) return false;
    const last = &block.stmts[block.stmts.len - 1];
    if (last.* != .assign) return false;
    const as = last.assign;
    if (as.values.len != 1 or as.targets.len != 1) return false;
    const val = as.values[0];
    const occ = ctx.occurrences.get(val) orelse return false;
    if (!std.meta.eql(occ.application, application)) return false;
    return try tryEmitTailAssignStorageReturn(ctx, as.targets[0], retTy);
}

/// The local slot a compound-assignment target was stored into. Field targets
/// live under the `obj.field` key `lowerFieldAssignTarget` writes.
fn compoundTargetSlot(ctx: *LowerCtx, target: *const ast.Expr) ?u32 {
    switch (target.*) {
        .name => |n| return ctx.locals.get(n.ident),
        .field => |f| {
            if (f.obj.* != .name) return null;
            var buf: [512]u8 = undefined;
            const fk = std.fmt.bufPrint(&buf, "{s}.{s}", .{ f.obj.name.ident, f.field }) catch return null;
            return ctx.locals.get(fk);
        },
        else => return null,
    }
}

fn lowerBlock(ctx: *LowerCtx, block: *const ast.Block, allow_return: bool) Error!void {
    const saved_answering = ctx.block_answering;
    ctx.block_answering = allow_return;
    defer ctx.block_answering = saved_answering;
    // No value-numbered fact crosses a control-flow edge: every reuse stays
    // inside straight-line code where domination is textual.
    ctx.cse.clearRetainingCapacity();
    for (block.stmts, 0..) |*stmt, i| {
        try pushEnclosingFrame(ctx, block, i);
        defer popEnclosingFrame(ctx);
        // A multi-statement idiom prologue (popcount) swallowed this statement;
        // its semantics were discharged up front.
        if (ctx.popcount_swallowed.contains(stmt)) continue;
        if (ctx.satadd_swallowed.contains(stmt)) continue;
        if (ctx.bitrev_swallowed.contains(stmt)) continue;
        if (ctx.loopselect_swallowed.contains(stmt)) continue;
        if (ctx.zerotrip_swallowed.contains(stmt)) continue;
        // A fired additive prologue claims the statement: the counted-loop
        // arming is excluded so an armed reduction cannot re-run a loop the
        // prologue already finalized (its trip test is false on entry).
        const claimed = try runAdditivePrologues(ctx, block.stmts, i);
        if (!claimed) tryArmCountedLoop(ctx, block.stmts, i);
        // The prologue may have swallowed this statement itself (popcount
        // discharges all six up front; bitrev/loopselect swallow the loop they
        // replace); do not lower it twice.
        if (ctx.popcount_swallowed.contains(stmt)) continue;
        if (ctx.satadd_swallowed.contains(stmt)) continue;
        if (ctx.bitrev_swallowed.contains(stmt)) continue;
        if (ctx.loopselect_swallowed.contains(stmt)) continue;
        if (ctx.zerotrip_swallowed.contains(stmt)) continue;
        // A provably-redundant `x = x & INT64_MAX` mask is skipped, not emitted.
        if (try trySkipInt64MaxMask(ctx, block.stmts, i, allow_return and stmtIsTailSlot(block, i))) continue;
        try lowerStmt(ctx, stmt, allow_return and stmtIsTailSlot(block, i));
    }
    if (allow_return) {
        _ = try tryEmitTailDemandReturn(ctx, block);
        return;
    }
    // gap[104], same hole as `lowerBlockReturns`: without this the tail
    // expression of a non-answering block is lowered by nobody.
    try lowerBlockTailEffect(ctx, block);
}

/// `req "path"` — a compile-time module binding, not a runtime call.
fn isReqCall(expr: *const ast.Expr) bool {
    if (expr.* != .call) return false;
    const c = expr.call;
    if (c.func.* != .name or !std.mem.eql(u8, c.func.name.ident, "req")) return false;
    return c.args.len == 1 and c.args[0].* == .quoted;
}

fn lowerFieldAssignTarget(ctx: *LowerCtx, obj: *const ast.Expr, field_name: []const u8, value: *const ast.Expr) Error!void {
    if (obj.* != .name) return bail(ctx.diagnostic, @src());
    const fk = try std.fmt.allocPrint(ctx.alloc, "{s}.{s}", .{ obj.name.ident, field_name });
    defer ctx.alloc.free(fk);
    const v = try lowerExprCons(ctx, value, .single);
    if (Record.locate(ctx, obj.name.ident)) |base| {
        const rec = recordLocalDesc(ctx, obj.name.ident) orelse
            return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-carrier");
        const projected = Record.project(rec, field_name) orelse
            return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-projection");
        if (ctx.require_graph_facts) {
            const origin = ctx.graph.valueByAst(value) orelse
                return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-write-value");
            const node = ctx.graph.get(origin) orelse
                return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-write-value");
            const descriptor = node.descriptor orelse
                return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-write-descriptor");
            const incoming = types.scalarFieldCell(descriptor) orelse
                return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-write-carrier");
            const resident: types.ScalarFieldCell = if (projected.ty == .f64)
                .f64
            else if (projected.ty == .str)
                .str
            else
                .i64;
            if (incoming != resident)
                return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-write-carrier");
        }
        var carrier: dnir.Value = .{ .local = base };
        var index = projected.index;
        if (ctx.directory.contains(base)) {
            const cell = ctx.freshTemp();
            try ctx.emit(.{
                .op = .load_index,
                .ty = .i64,
                .result = cell,
                .lhs = .{ .local = base },
                .rhs = .{ .i64 = projected.index },
            });
            try ctx.ptr_slots.put(ctx.alloc, cell, {});
            carrier = .{ .temp = cell };
            index = 1;
        }
        try ctx.emit(.{
            .op = .store_index,
            .record = if (ctx.directory.contains(base)) rec.name else "",
            .field = field_name,
            .ty = projected.ty,
            .lhs = carrier,
            .rhs = .{ .i64 = index },
            .third = v,
        });
        subsumeProducerRefit(ctx);
        return;
    }
    if (ctx.locals.get(fk)) |slot| {
        if (ctx.require_graph_facts and !ctx.graph.gateTransportModule() and slot < ctx.param_slots)
            return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-parameter-place-unproved");
        if (ctx.require_graph_facts) {
            const origin = ctx.graph.valueByAst(value) orelse
                return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-write-value");
            const node = ctx.graph.get(origin) orelse
                return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-write-value");
            const descriptor = node.descriptor orelse
                return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-write-descriptor");
            const incoming = types.scalarFieldCell(descriptor) orelse
                return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-write-carrier");
            const resident: types.ScalarFieldCell = if (ctx.f64_slots.contains(slot))
                .f64
            else if (ctx.str_slots.contains(slot))
                .str
            else
                .i64;
            if (incoming != resident)
                return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-write-carrier");
        }
        // THE FIELD'S DECLARED WIDTH APPLIES AT EVERY WRITE, not only at the
        // literal that created the storage. This read is the whole repair:
        // `store_ty` was unconditionally `.any` here, so `r.f = r.f + K` on an
        // `f: i32` emitted a full 64-bit `str` and answered a value the place
        // cannot hold — at all six widths, folded and emitted alike.
        const store_ty: RT = if (exprIsF64(ctx, value))
            .f64
        else
            ctx.narrow_slots.get(slot) orelse .any;
        if (store_ty == .f64) try ctx.f64_slots.put(ctx.alloc, slot, {});
        if (exprIsStr(ctx, value)) try ctx.str_slots.put(ctx.alloc, slot, {});
        // THE BYTE FACE IS RECORDED AT THE SAME STORE (GAP-207). Both
        // directions: a slot REASSIGNED away from a byte sequence stops being
        // one, and leaving the mark set would refuse a legal concat for the
        // rest of the body.
        if (exprIsByteSequence(ctx, value))
            try ctx.byteseq_slots.put(ctx.alloc, slot, {})
        else
            _ = ctx.byteseq_slots.remove(slot);
        try ctx.emit(.{ .op = .store_local, .result = slot, .lhs = v, .ty = store_ty });
        subsumeProducerRefit(ctx);
        return;
    }
    // A MODULE-SCOPE TABLE FIELD GOES TO ITS STORAGE, and this arm must sit
    // above the fresh-local fallback below for the same reason the `.name` arm
    // in `lowerAssignTarget` must: that fallback IS the defect. With no local of
    // this key in scope it minted one, so `M.x = 1` in a relation body wrote a
    // register the module body could not see and the module body's own write
    // went to a different register still — two stores describing one field.
    if (moduleFieldWord(ctx, obj.name.ident, fk)) |pair| {
        const gty = pair[0];
        const storage_key = pair[1];
        try ctx.emit(.{
            .op = .store_global,
            .field = storage_key,
            .lhs = v,
            .ty = gty,
        });
        subsumeProducerRefit(ctx);
        return;
    }
    if (ctx.require_graph_facts and ctx.locals.contains(obj.name.ident))
        return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-place-unproved");
    const store_ty: RT = if (exprIsF64(ctx, value)) .f64 else .any;
    const slot = ctx.freshTemp();
    try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, fk), slot);
    if (store_ty == .f64) try ctx.f64_slots.put(ctx.alloc, slot, {});
    if (exprIsStr(ctx, value)) try ctx.str_slots.put(ctx.alloc, slot, {});
    // THE BYTE FACE IS RECORDED AT THE SAME STORE (GAP-207). Both
    // directions: a slot REASSIGNED away from a byte sequence stops being
    // one, and leaving the mark set would refuse a legal concat for the
    // rest of the body.
    if (exprIsByteSequence(ctx, value))
        try ctx.byteseq_slots.put(ctx.alloc, slot, {})
    else
        _ = ctx.byteseq_slots.remove(slot);
    try ctx.emit(.{ .op = .store_local, .result = slot, .lhs = v, .ty = store_ty });
}

fn exprCallConsumption(expr: *const ast.Expr) types.ReturnConsumption {
    return switch (expr.*) {
        .call, .method_call => .discard,
        else => .single,
    };
}

fn exprReturnsF64(ctx: *LowerCtx, expr: *const ast.Expr) bool {
    if (applicationResultIs(ctx, expr, .f64)) return true;
    if (expr.* != .call) return false;
    // `math.sqrt(x)` and friends are libm: f64 in, f64 out. Without this the
    // binding `r: f64 = math.sqrt(x)` stores through the INTEGER path — the
    // assembly showed `fmov d1, d0` for the result and then `mov x9, x1` for
    // the store, so the f64 local was never written and the consumer read a
    // register nothing had touched.
    //
    // Third time this exact lesson: a producer the type tracker does not know
    // about breaks every consumer downstream. exprIsStr needed it for
    // string.char, then again for concat; this is the f64 twin.
    if (expr.call.func.* == .field) {
        const f = expr.call.func.field;
        if (f.obj.* == .name and std.mem.eql(u8, f.obj.name.ident, "math") and
            expr.call.args.len == 1) return true;
    }
    if (expr.call.func.* != .name) return false;
    // `__as(f64, x)` — the `@as` intrinsic — answers f64 when the target
    // is "f64". The type arg is a quoted string; the value converts via
    // `scvtf` in the native backend's `evalDnirValueFp`.
    if (std.mem.eql(u8, expr.call.func.name.ident, "__as") and expr.call.args.len == 2) {
        if (expr.call.args[0].* == .quoted and std.mem.eql(u8, expr.call.args[0].quoted.val, "f64")) {
            return true;
        }
    }
    return functionResultIs(ctx, expr.call.func.name.ident, .f64);
}

fn storePackName(
    ctx: *LowerCtx,
    name: []const u8,
    value: dnir.Value,
    descriptor: types.ResolvedType,
) Error!void {
    if (ctx.locals.get(name)) |slot| {
        const store_ty: RT = if (descriptor == .f64)
            .f64
        else
            ctx.narrow_slots.get(slot) orelse .any;
        if (descriptor == .f64) try ctx.f64_slots.put(ctx.alloc, slot, {}) else _ = ctx.f64_slots.remove(slot);
        if (descriptor == .str) try ctx.str_slots.put(ctx.alloc, slot, {}) else _ = ctx.str_slots.remove(slot);
        if (descriptor == .bool) try ctx.bool_slots.put(ctx.alloc, slot, {}) else _ = ctx.bool_slots.remove(slot);
        if (descriptor == .pointer) try ctx.ptr_slots.put(ctx.alloc, slot, {}) else _ = ctx.ptr_slots.remove(slot);
        try ctx.emit(.{ .op = .store_local, .result = slot, .lhs = value, .ty = store_ty });
        return;
    }
    if (ctx.module_globals.types.get(name)) |ty| {
        try ctx.emit(.{ .op = .store_global, .field = name, .lhs = value, .ty = ty });
        return;
    }
    const slot = ctx.freshTemp();
    try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, name), slot);
    const store_ty: RT = if (descriptor == .f64) .f64 else .any;
    if (descriptor == .f64) try ctx.f64_slots.put(ctx.alloc, slot, {});
    if (descriptor == .str) try ctx.str_slots.put(ctx.alloc, slot, {});
    if (descriptor == .bool) try ctx.bool_slots.put(ctx.alloc, slot, {});
    if (descriptor == .pointer) try ctx.ptr_slots.put(ctx.alloc, slot, {});
    try ctx.emit(.{ .op = .store_local, .result = slot, .lhs = value, .ty = store_ty });
}

fn prepareLocalPackSlots(ctx: *LowerCtx, names: []const ast.LocalName) Error!void {
    for (names) |name| {
        const width = narrowIntOfType(name.typ) orelse continue;
        const slot = ctx.locals.get(name.ident) orelse blk: {
            const fresh = ctx.freshTemp();
            const owned = try ctx.alloc.dupe(u8, name.ident);
            ctx.locals.put(ctx.alloc, owned, fresh) catch |err| {
                ctx.alloc.free(owned);
                return err;
            };
            break :blk fresh;
        };
        try ctx.narrow_slots.put(ctx.alloc, slot, width);
    }
}

fn lowerOneToManyPackDeclaration(
    ctx: *LowerCtx,
    names: []const ast.LocalName,
    initializers: []const *ast.Expr,
) Error!bool {
    if (initializers.len != 1 or names.len <= 1) return false;
    const source = initializers[0];
    const application_fact = ctx.occurrences.get(source) orelse return false;
    const adjustment = ctx.graph.packAdjustment(application_fact.application) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "declaration-pack-adjustment");
    const sources = ctx.graph.packMembers(adjustment.source_pack) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "declaration-source-pack");
    const targets = ctx.graph.packMembers(adjustment.target_pack) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "declaration-target-pack");
    if (sources.len == 0 or targets.len != names.len) return false;
    for (targets, names) |target_id, *name| {
        const node = ctx.graph.get(target_id) orelse
            return invalidGraphFacts(ctx.diagnostic, @src(), "declaration-target-member");
        const raw = node.ast_ref orelse
            return invalidGraphFacts(ctx.diagnostic, @src(), "declaration-target-provenance");
        const published: *const ast.LocalName = @ptrCast(@alignCast(raw));
        if (node.kind != .local or published != name or node.name == null or
            !std.mem.eql(u8, node.name.?, name.ident))
        {
            return invalidGraphFacts(ctx.diagnostic, @src(), "declaration-target-place");
        }
    }

    try prepareLocalPackSlots(ctx, names);
    if (sources.len == 1) {
        const source_node = ctx.graph.get(sources[0]) orelse
            return invalidGraphFacts(ctx.diagnostic, @src(), "declaration-source-member");
        const descriptor = source_node.descriptor orelse
            return invalidGraphFacts(ctx.diagnostic, @src(), "declaration-source-descriptor");
        const first = try lowerExprCons(ctx, source, .single);
        try storePackName(ctx, names[0].ident, first, descriptor);
        for (names[1..]) |name| {
            try storePackName(ctx, name.ident, .{ .i64 = 0 }, .nil);
        }
        return true;
    }

    var temps: [max_reg_record_fields]?u32 = @splat(null);
    try lowerCheckedPackCall(ctx, application_fact, @min(sources.len, names.len), &temps);
    for (names, 0..) |name, i| {
        if (i >= sources.len) {
            try storePackName(ctx, name.ident, .{ .i64 = 0 }, .nil);
            continue;
        }
        const node = ctx.graph.get(sources[i]) orelse
            return invalidGraphFacts(ctx.diagnostic, @src(), "declaration-source-member");
        const descriptor = node.descriptor orelse
            return invalidGraphFacts(ctx.diagnostic, @src(), "declaration-source-descriptor");
        const temp = temps[i] orelse
            return invalidGraphFacts(ctx.diagnostic, @src(), "declaration-pack-demand");
        try storePackName(ctx, name.ident, .{ .temp = temp }, descriptor);
    }
    return true;
}

/// Realize binding adjustment directly from graph packs. The call runs once;
/// ordered demanded members are stored, surplus source members disappear, and
/// missing target members are nil-filled. No target count or result shape is
/// reconstructed from the callee spelling.
fn lowerOneToManyPackAssign(
    ctx: *LowerCtx,
    assignment_targets: []const *ast.Expr,
    assignment_values: []const *ast.Expr,
) Error!bool {
    if (assignment_values.len != 1 or assignment_targets.len <= 1) return false;
    const source = assignment_values[0];
    const application_fact = ctx.occurrences.get(source) orelse return false;
    const adjustment = ctx.graph.packAdjustment(application_fact.application) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "binding-pack-adjustment");
    const sources = ctx.graph.packMembers(adjustment.source_pack) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "binding-source-pack");
    const targets = ctx.graph.packMembers(adjustment.target_pack) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "binding-target-pack");
    if (sources.len == 0 or targets.len != assignment_targets.len) return false;
    for (targets, assignment_targets) |target_id, target| {
        const node = ctx.graph.get(target_id) orelse
            return invalidGraphFacts(ctx.diagnostic, @src(), "binding-target-member");
        const raw = node.ast_ref orelse
            return invalidGraphFacts(ctx.diagnostic, @src(), "binding-target-provenance");
        const published: *const ast.Expr = @ptrCast(@alignCast(raw));
        if (published != target or target.* != .name) {
            return invalidGraphFacts(ctx.diagnostic, @src(), "binding-target-place");
        }
    }

    if (sources.len == 1) {
        const source_node = ctx.graph.get(sources[0]) orelse
            return invalidGraphFacts(ctx.diagnostic, @src(), "binding-source-member");
        const descriptor = source_node.descriptor orelse
            return invalidGraphFacts(ctx.diagnostic, @src(), "binding-source-descriptor");
        const first = try lowerExprCons(ctx, source, .single);
        try storePackName(ctx, assignment_targets[0].name.ident, first, descriptor);
        for (assignment_targets[1..]) |target| {
            try storePackName(ctx, target.name.ident, .{ .i64 = 0 }, .nil);
        }
        return true;
    }

    var temps: [max_reg_record_fields]?u32 = @splat(null);
    try lowerCheckedPackCall(ctx, application_fact, @min(sources.len, assignment_targets.len), &temps);
    for (assignment_targets, 0..) |target, i| {
        if (i >= sources.len) {
            try storePackName(ctx, target.name.ident, .{ .i64 = 0 }, .nil);
            continue;
        }
        const node = ctx.graph.get(sources[i]) orelse
            return invalidGraphFacts(ctx.diagnostic, @src(), "binding-source-member");
        const descriptor = node.descriptor orelse
            return invalidGraphFacts(ctx.diagnostic, @src(), "binding-source-descriptor");
        const temp = temps[i] orelse
            return invalidGraphFacts(ctx.diagnostic, @src(), "binding-pack-demand");
        try storePackName(ctx, target.name.ident, .{ .temp = temp }, descriptor);
    }
    return true;
}

fn functionResultIs(
    ctx: *const LowerCtx,
    name: []const u8,
    expected: std.meta.Tag(types.ResolvedType),
) bool {
    const start = ctx.function orelse return false;
    const entity = ctx.graph.resolveInHome(start, name, .func) orelse return false;
    const descriptor = ctx.graph.functionResultDescriptor(entity) orelse return false;
    return std.meta.activeTag(descriptor) == expected;
}

/// The unchecked call path (reached only when `require_graph_facts` is false
/// — a waivered module) mangles a bare callee name the same way the
/// definition side does in `funcExportName`, so a local `capture` call and
/// the emitted `idol_gate_architecture__capture` definition agree.
/// A name that resolves to a graph-known function comes back mangled; a
/// name the graph does not know is preserved verbatim so foreign/library
/// symbol paths keep working.
fn calleeForCall(ctx: *LowerCtx, name: []const u8) ![]const u8 {
    const start = ctx.function orelse return try ctx.alloc.dupe(u8, name);
    if (ctx.graph.resolveInHome(start, name, .func)) |entity| {
        if (ctx.entity_linkage.get(entity)) |existing| return try ctx.alloc.dupe(u8, existing);
        if (ctx.graph.callableLinkage(entity)) |linkage| {
            if (linkage.exposure == .c_import) return try ctx.alloc.dupe(u8, linkage.symbol);
        }
    }
    return try ctx.alloc.dupe(u8, name);
}

// ════════════════════════════════════════════════════════════════════════════
// LINEAR-IV STRENGTH REDUCTION
//
// A `while` loop whose body ends in `iv = iv + step` and evaluates `iv*C+K`
// (literal C != 0, literal K) in the body pays one multiply per occurrence
// per iteration — the backend fuses the `mul`+`add` into a madd, but it stays
// a multiply-class operation on the loop's critical path. `v = iv*C+K` is
// itself an induction variable with stride `C*step`: set it once before the
// loop, advance it once per iteration next to the iv step, and every
// `iv*C+K` in the body becomes a plain register read.
//
// The (C,K) pairs are discovered from the lowered DNIR, so the rewrite only
// fires on the exact shapes the backend would otherwise multiply. The AST
// check is a cheap pre-filter (last statement is the iv step); every
// legality proof is re-established on the DNIR before anything is mutated:
// exactly one iv store of the right shape, no branches in the body range
// (deletion would invalidate their targets), every pair's uses accounted
// for. Any decline leaves the instruction stream untouched: the inits are
// inserted only after the rewrite commits.
//
// WHY IT IS CORRECT. Before the iv step of each iteration, `v = iv*C+K`
// holds: the init establishes it on loop entry, and the update adds exactly
// `(iv+step)*C+K - (iv*C+K) = C*step`, computed mod 2^64 exactly like the
// original chain. The step is the body's last statement and the range holds
// no branches, so every rewritten use executes after its iteration's
// init/update and before the next update. `break`/`continue` lower to `.br`
// and decline the rewrite; the iv-store count declines any second write.
const IvsrPair = struct {
    c: i64,
    k: i64,
    v_slot: u32,
    ty: RT,
};

const IvsrHead = struct {
    iv: []const u8,
    step: i64,
};

/// Cheap AST pre-filter: the body's last statement must be `iv = iv + step`
/// with a nonzero literal step. Returns the iv name and step, or null.
fn ivsrCheckBody(body: *const ast.Block) ?IvsrHead {
    if (body.tail_expr != null) return null;
    const n = body.stmts.len;
    if (n == 0) return null;
    const last: *const ast.Stmt = &body.stmts[n - 1];
    const as = switch (last.*) {
        .assign => |*a| a,
        else => return null,
    };
    if (as.targets.len != 1 or as.values.len != 1) return null;
    const iv = switch (as.targets[0].*) {
        .name => |nm| nm.ident,
        else => return null,
    };
    const b = switch (as.values[0].*) {
        .binop => |*bb| bb,
        else => return null,
    };
    // iv+k, k+iv (step k), or iv-k (step -k). k-iv is not a
    // constant step and declines.
    const step: i64 = if (b.op == .add and b.lhs.* == .name and std.mem.eql(u8, b.lhs.name.ident, iv) and b.rhs.* == .int_lit)
        b.rhs.int_lit.val
    else if (b.op == .add and b.rhs.* == .name and std.mem.eql(u8, b.rhs.name.ident, iv) and b.lhs.* == .int_lit)
        b.lhs.int_lit.val
    else if (b.op == .sub and b.lhs.* == .name and std.mem.eql(u8, b.lhs.name.ident, iv) and b.rhs.* == .int_lit)
        0 -% b.rhs.int_lit.val
    else
        return null;
    if (step == 0) return null;
    return .{ .iv = iv, .step = step };
}

fn ivsrIsLocal(v: dnir.Value, slot: u32) bool {
    return switch (v) {
        .local => |s| s == slot,
        else => false,
    };
}

fn ivsrIsTemp(v: dnir.Value, t: u32) bool {
    return switch (v) {
        .temp => |tt| tt == t,
        else => false,
    };
}

fn ivsrAsI64(v: dnir.Value) ?i64 {
    return switch (v) {
        .i64 => |x| x,
        else => null,
    };
}

/// True when `ins` reads temp `t` in any operand position.
fn ivsrUsesTemp(ins: *const dnir.Instr, t: u32) bool {
    if (ivsrIsTemp(ins.lhs, t)) return true;
    if (ivsrIsTemp(ins.rhs, t)) return true;
    if (ivsrIsTemp(ins.third, t)) return true;
    for (ins.vals) |v| if (ivsrIsTemp(v, t)) return true;
    return false;
}

/// When `ins` is `add(temp(t), K)` with a literal K (either order), returns K.
fn ivsrAddTempLit(ins: *const dnir.Instr, t: u32) ?i64 {
    if (ins.op != .binop or ins.binop != .add) return null;
    if (ivsrIsTemp(ins.lhs, t)) return ivsrAsI64(ins.rhs);
    if (ivsrIsTemp(ins.rhs, t)) return ivsrAsI64(ins.lhs);
    return null;
}

/// Get-or-create the stride slot for (c,k).
fn ivsrPairFor(
    ctx: *LowerCtx,
    pairs: *std.ArrayListUnmanaged(IvsrPair),
    c: i64,
    k: i64,
    ty: RT,
) Error!u32 {
    for (pairs.items) |pr| if (pr.c == c and pr.k == k) return pr.v_slot;
    const v = ctx.freshTemp();
    try pairs.append(ctx.alloc, .{ .c = c, .k = k, .v_slot = v, .ty = ty });
    return v;
}

fn ivsrPairSlot(pairs: *const std.ArrayListUnmanaged(IvsrPair), c: i64, k: i64) ?u32 {
    for (pairs.items) |pr| if (pr.c == c and pr.k == k) return pr.v_slot;
    return null;
}

/// DNIR rewrite for linear-IV strength reduction (see the section header).
/// Discovers `mul(iv,C)` sources and their `add(.,K)` consumers in
/// [body_start, body_end), replaces every consumed value with a stride
/// variable `v = iv*C+K`, deletes the dead multiplies, inserts one
/// `v += C*step` per pair after the iv step, and inserts the inits before
/// the loop head (adjusting head_idx, fail_idx, and the loop_heads top for
/// the shift). Returns true on commit; false leaves the stream untouched.
fn applyLinearIVSR(
    ctx: *LowerCtx,
    iv_slot: u32,
    step: i64,
    head_idx: *u32,
    fail_idx: *usize,
    body_start: u32,
    body_end: u32,
) Error!bool {
    // Belt-and-braces: the stride arithmetic below is mod 2^64 while a narrow
    // iv wraps at its declared modulus. The arming site already declines
    // these; re-prove it here so no future caller can slip one through.
    if (ctx.narrow_slots.contains(iv_slot)) return false;
    var bend: u32 = body_end;
    // No branches in the range: deletion shifts indices and would invalidate
    // branch targets. (`break`/`continue` lower to `.br`, so they decline.)
    for (ctx.instrs.items[body_start..bend]) |ins| {
        if (ins.op == .br) return false;
        // `vals` is const: a doomed temp used there could not be rewritten.
        if (ins.vals.len > 0) return false;
    }
    // temp -> defining instruction index, for the range.
    var def = std.AutoHashMapUnmanaged(u32, u32).empty;
    defer def.deinit(ctx.alloc);
    for (ctx.instrs.items[body_start..bend], body_start..) |ins, idx| {
        if (ins.result) |r| try def.put(ctx.alloc, r, @intCast(idx));
    }
    // The iv step: exactly one `store_local iv_slot` in the range, and it
    // must store `iv + step`.
    var step_count: u32 = 0;
    for (ctx.instrs.items[body_start..bend]) |ins| {
        if (ins.op != .store_local or ins.result != iv_slot) continue;
        step_count += 1;
        const t = switch (ins.lhs) {
            .temp => |tt| tt,
            else => return false,
        };
        const di = def.get(t) orelse return false;
        const din = ctx.instrs.items[di];
        if (din.op != .binop) return false;
        // add(iv, step) in either operand order, or sub(iv, k) with
        // step == -k. sub(k, iv) is not a constant step and declines.
        const step_ok: bool = switch (din.binop) {
            .add => (ivsrIsLocal(din.lhs, iv_slot) and ivsrAsI64(din.rhs) == step) or
                (ivsrIsLocal(din.rhs, iv_slot) and ivsrAsI64(din.lhs) == step),
            .sub => ivsrIsLocal(din.lhs, iv_slot) and ivsrAsI64(din.rhs) == (0 -% step),
            else => false,
        };
        if (!step_ok) return false;
    }
    if (step_count != 1) return false;

    // C-sources: `mul(iv, C)` / `mul(C, iv)` with C != 0.
    const CSource = struct { idx: u32, t1: u32, c: i64, ty: RT };
    var sources = std.ArrayListUnmanaged(CSource).empty;
    defer sources.deinit(ctx.alloc);
    for (ctx.instrs.items[body_start..bend], body_start..) |ins, idx| {
        if (ins.op != .binop or ins.binop != .mul) continue;
        const r = ins.result orelse continue;
        const c: ?i64 = if (ivsrIsLocal(ins.lhs, iv_slot))
            ivsrAsI64(ins.rhs)
        else if (ivsrIsLocal(ins.rhs, iv_slot))
            ivsrAsI64(ins.lhs)
        else
            null;
        const cc = c orelse continue;
        if (cc == 0) continue;
        try sources.append(ctx.alloc, .{ .idx = @intCast(idx), .t1 = r, .c = cc, .ty = ins.ty });
    }
    if (sources.items.len == 0) return false;

    // Per source: the `add(t1, K)` consumers and whether t1 is used raw.
    const AddUse = struct { idx: u32, t2: u32, k: i64, ty: RT };
    const SrcPlan = struct {
        src: CSource,
        adds: std.ArrayListUnmanaged(AddUse),
        raw_use: bool,
    };
    var plans = std.ArrayListUnmanaged(SrcPlan).empty;
    defer {
        for (plans.items) |*p| p.adds.deinit(ctx.alloc);
        plans.deinit(ctx.alloc);
    }
    for (sources.items) |src| {
        var adds = std.ArrayListUnmanaged(AddUse).empty;
        var raw_use = false;
        for (ctx.instrs.items[body_start..bend], body_start..) |ins, idx| {
            if (idx == src.idx) continue;
            if (!ivsrUsesTemp(&ins, src.t1)) continue;
            if (ivsrAddTempLit(&ins, src.t1)) |k| {
                const t2 = ins.result orelse return false;
                try adds.append(ctx.alloc, .{ .idx = @intCast(idx), .t2 = t2, .k = k, .ty = ins.ty });
            } else {
                raw_use = true;
            }
        }
        try plans.append(ctx.alloc, .{ .src = src, .adds = adds, .raw_use = raw_use });
    }

    // One stride variable per distinct (C,K).
    var pairs = std.ArrayListUnmanaged(IvsrPair).empty;
    defer pairs.deinit(ctx.alloc);
    for (plans.items) |*p| {
        for (p.adds.items) |a| _ = try ivsrPairFor(ctx, &pairs, p.src.c, a.k, a.ty);
        if (p.raw_use) _ = try ivsrPairFor(ctx, &pairs, p.src.c, 0, p.src.ty);
    }
    if (pairs.items.len == 0) return false;

    // --- Commit: rewrite uses. ---
    var items = ctx.instrs.items;
    for (plans.items) |*p| {
        for (p.adds.items) |a| {
            const v = ivsrPairSlot(&pairs, p.src.c, a.k) orelse return false;
            const nv: dnir.Value = .{ .local = v };
            for (items[body_start..bend]) |*ins| {
                if (ivsrIsTemp(ins.lhs, a.t2)) ins.lhs = nv;
                if (ivsrIsTemp(ins.rhs, a.t2)) ins.rhs = nv;
                if (ivsrIsTemp(ins.third, a.t2)) ins.third = nv;

            }
        }
        if (p.raw_use) {
            const v = ivsrPairSlot(&pairs, p.src.c, 0) orelse return false;
            const nv: dnir.Value = .{ .local = v };
            for (items[body_start..bend]) |*ins| {
                // The add-consumers keep reading t1 until deleted below.
                if (ivsrAddTempLit(ins, p.src.t1) != null) continue;
                if (ivsrIsTemp(ins.lhs, p.src.t1)) ins.lhs = nv;
                if (ivsrIsTemp(ins.rhs, p.src.t1)) ins.rhs = nv;
                if (ivsrIsTemp(ins.third, p.src.t1)) ins.third = nv;

            }
        }
    }

    // --- Commit: delete the dead muls and adds. ---
    var del = std.ArrayListUnmanaged(u32).empty;
    defer del.deinit(ctx.alloc);
    var doomed = std.ArrayListUnmanaged(u32).empty;
    defer doomed.deinit(ctx.alloc);
    for (plans.items) |*p| {
        for (p.adds.items) |a| {
            try del.append(ctx.alloc, a.idx);
            try doomed.append(ctx.alloc, a.t2);
        }
        try del.append(ctx.alloc, p.src.idx);
        try doomed.append(ctx.alloc, p.src.t1);
    }
    // Safety: every remaining use of a doomed temp must sit inside a doomed
    // instruction (about to be deleted with it).
    items = ctx.instrs.items;
    for (doomed.items) |t| {
        for (items[body_start..bend], body_start..) |*ins, idx| {
            if (!ivsrUsesTemp(ins, t)) continue;
            var ok = false;
            for (del.items) |di| if (di == idx) {
                ok = true;
                break;
            };
            if (!ok) return false;
        }
    }
    std.mem.sort(u32, del.items, {}, std.sort.desc(u32));
    for (del.items) |di| _ = ctx.instrs.orderedRemove(@as(usize, di));
    // Deletions move the body end left.
    bend -= @intCast(del.items.len);
    // --- Commit: one `v += C*step` per pair, right after the iv step. ---
    var si: ?u32 = null;
    for (ctx.instrs.items[body_start..bend], body_start..) |ins, idx| {
        if (ins.op == .store_local and ins.result == iv_slot) si = @intCast(idx);
    }
    const step_at = si orelse return false; // unreachable: stores are untouched
    var at: usize = step_at;
    for (pairs.items) |pr| {
        const stride: i64 = pr.c *% step;
        const t = ctx.freshTemp();
        try ctx.instrs.insert(ctx.alloc, at + 1, .{
            .op = .binop, .binop = .add, .result = t,
            .lhs = .{ .local = pr.v_slot }, .rhs = .{ .i64 = stride }, .ty = pr.ty,
        });
        at += 1;
        try ctx.instrs.insert(ctx.alloc, at + 1, .{
            .op = .store_local, .result = pr.v_slot, .lhs = .{ .temp = t }, .ty = pr.ty,
        });
        at += 1;
        _ = ctx.nonzero_slots.remove(pr.v_slot);
        try ctx.cseKillLocal(pr.v_slot);
    }

    // --- Commit: the `v = iv*C+K` inits before the loop head. ---
    // Inserted in reverse at head_idx so the stream reads mul, add, store.
    var inserted: u32 = 0;
    for (pairs.items) |pr| {
        const t1 = ctx.freshTemp();
        if (pr.k == 0) {
            try ctx.instrs.insert(ctx.alloc, @as(usize, head_idx.*), .{
                .op = .store_local, .result = pr.v_slot, .lhs = .{ .temp = t1 }, .ty = pr.ty,
            });
            try ctx.instrs.insert(ctx.alloc, @as(usize, head_idx.*), .{
                .op = .binop, .binop = .mul, .result = t1,
                .lhs = .{ .local = iv_slot }, .rhs = .{ .i64 = pr.c }, .ty = pr.ty,
            });
            inserted += 2;
        } else {
            const t2 = ctx.freshTemp();
            try ctx.instrs.insert(ctx.alloc, @as(usize, head_idx.*), .{
                .op = .store_local, .result = pr.v_slot, .lhs = .{ .temp = t2 }, .ty = pr.ty,
            });
            try ctx.instrs.insert(ctx.alloc, @as(usize, head_idx.*), .{
                .op = .binop, .binop = .add, .result = t2,
                .lhs = .{ .temp = t1 }, .rhs = .{ .i64 = pr.k }, .ty = pr.ty,
            });
            try ctx.instrs.insert(ctx.alloc, @as(usize, head_idx.*), .{
                .op = .binop, .binop = .mul, .result = t1,
                .lhs = .{ .local = iv_slot }, .rhs = .{ .i64 = pr.c }, .ty = pr.ty,
            });
            inserted += 3;
        }
        _ = ctx.nonzero_slots.remove(pr.v_slot);
        try ctx.cseKillLocal(pr.v_slot);
    }
    head_idx.* += inserted;
    fail_idx.* += inserted;
    if (ctx.loop_heads.items.len > 0) {
        ctx.loop_heads.items[ctx.loop_heads.items.len - 1] += inserted;
    }
    return true;
}
fn lowerStmt(ctx: *LowerCtx, stmt: *const ast.Stmt, allow_return: bool) Error!void {
    switch (stmt.*) {
        .local_decl => |ld| {
            if (try lowerOneToManyPackDeclaration(ctx, ld.names, ld.inits)) return;
            if (ld.names.len != ld.inits.len and ld.inits.len == 1) return bail(ctx.diagnostic, @src());
            for (ld.names, 0..) |*ln, i| {
                // A declaration introduces a lexical binding regardless of
                // its representation or width.  Publishing the local slot
                // before lowering the initializer is load-bearing when a
                // module binding has the same spelling: without it, the
                // initializer falls through lowerAssignTarget's module-global
                // arm and writes the wrong storage.  Narrow-width handling
                // below only qualifies this already-published binding; it must
                // never be the condition that creates the binding.
                var local_slot: ?u32 = null;
                if (!ctx.module_root) {
                    local_slot = ctx.locals.get(ln.ident) orelse blk: {
                        const fresh = ctx.freshTemp();
                        const owned = try ctx.alloc.dupe(u8, ln.ident);
                        ctx.locals.put(ctx.alloc, owned, fresh) catch |err| {
                            ctx.alloc.free(owned);
                            return err;
                        };
                        break :blk fresh;
                    };
                }
                // The declared width has to be on record BEFORE the initializer
                // is lowered, because the initializer's store is the first place
                // it applies: `h: u8 = 300` is 44 under `--backend=c`, which
                // writes `uint8_t h = ((uint8_t)(300))`. Marking the slot after
                // `lowerAssignTarget` would have left exactly the first store
                // unrefitted — a wrong answer visible only on the declaration.
                if (narrowIntOfType(ln.typ)) |width| {
                    const slot = local_slot orelse blk: {
                        const fresh = ctx.freshTemp();
                        const owned = try ctx.alloc.dupe(u8, ln.ident);
                        ctx.locals.put(ctx.alloc, owned, fresh) catch |err| {
                            ctx.alloc.free(owned);
                            return err;
                        };
                        break :blk fresh;
                    };
                    try ctx.narrow_slots.put(ctx.alloc, slot, width);
                }
                if (i < ld.inits.len) {
                    if (try skipStaticAggregateBinding(ctx, ln.ident)) continue;
                    try lowerAssignTarget(ctx, ln.ident, ld.inits[i]);
                    try noteConstNum(ctx, stmt, ln.ident, ld.inits[i], ln.typ);
                }
                if (ln.typ != .inferred and isFloatType(ln.typ)) {
                    if (ctx.locals.get(ln.ident)) |slot| try ctx.f64_slots.put(ctx.alloc, slot, {});
                }
                // An unannotated binding takes its floatness from the
                // initializer: `x = 0.1 + 0.2` is f64 even though no
                // annotation says so. Without this, `exprIsF64` misses the
                // name, `exprIsIntegral` admits it by elimination, and a
                // concat prints the double's bits through `%lld`.
                if (i < ld.inits.len and exprIsF64(ctx, ld.inits[i])) {
                    if (ctx.locals.get(ln.ident)) |slot| try ctx.f64_slots.put(ctx.alloc, slot, {});
                }
                // `ok: bool = f()` where `f` is not declared `: bool`. The
                // ANNOTATION is the answer here and the initializer is not, so
                // the mark has to follow the declared type as well.
                if (isBoolType(ln.typ)) {
                    if (ctx.locals.get(ln.ident)) |slot| try ctx.bool_slots.put(ctx.alloc, slot, {});
                }
                if (typeIsPtr(ln.typ)) {
                    if (ctx.locals.get(ln.ident)) |slot| try ctx.ptr_slots.put(ctx.alloc, slot, {});
                }
            }
        },
        .assign => |as| {
            if (try lowerOneToManyPackAssign(ctx, as.targets, as.values)) return;
            if (as.targets.len != as.values.len) return bail(ctx.diagnostic, @src());
            for (as.targets, as.values) |target, value| {
                if (target.* == .name and try skipStaticAggregateBinding(ctx, target.name.ident)) continue;
                // The environment is a PLACE. This runs before the switch below
                // because `os.env[k]` is an `.index` whose object is a `.field`,
                // which `lowerIndexAssignTarget` rejects outright, and
                // `env(k)`/`os.env(k)` are `.call` targets, which the switch has
                // no arm for at all.
                if (envPlaceKey(ctx, target)) |key| {
                    try lowerEnvStore(ctx, key, value);
                    continue;
                }
                switch (target.*) {
                    .name => |n| {
                        try lowerAssignTarget(ctx, n.ident, value);
                        try noteConstNum(ctx, stmt, n.ident, value, .inferred);
                    },
                    .field => |f| try lowerFieldAssignTarget(ctx, f.obj, f.field, value),
                    .index => |ix| try lowerIndexAssignTarget(ctx, ix.obj, ix.key, value),
                    else => return bail(ctx.diagnostic, @src()),
                }
            }
        },
        .if_stmt => |is| {
            if (is.binding) |b| {
                try lowerAssignTarget(ctx, b.name, b.expr);
                try noteConstNum(ctx, stmt, b.name, b.expr, .inferred);
            }
            // CONSTANT CONDITION: lower the arm that runs, and only it.
            //
            // Bounded deliberately to a chainless `if`. An `elseif` chain whose
            // first condition is constant-false still has runtime conditions
            // after it, so folding it means re-forming the chain rather than
            // choosing an arm, and re-forming is where a rewrite starts moving
            // statements the graph holds pointers into -- the cost the
            // file-scope closure work already paid once. A chain is left whole.
            //
            // A binding is lowered first and unconditionally, above, because
            // `if x = f() ...` binds whatever the condition decides.
            if (is.binding == null and is.elseifs.len == 0) {
                if (constConditionTruth(ctx, is.cond)) |truth| {
                    // THE CONDITION IS DECIDED, ITS APPLICATIONS ARE NOT ABSENT.
                    //
                    // `constConditionTruth` answers from `exactI64OfExpr`, and
                    // one of the shapes it answers for is a PUBLISHED aggregate
                    // projection (`xs[2][1]`) — an application the graph owns
                    // and `native_backend` requires to be realized exactly once.
                    // Returning here without lowering the condition deleted
                    // those realization rows, and the module was refused with
                    // `application-realization-count`: measured at HEAD, `if
                    // xs[2][1] > 2` REFUSED while the same projection bound to a
                    // name first compiled. The fold was turning new knowledge
                    // into a refusal.
                    //
                    // ONLY THE LINEAGE, NEVER THE COMPARISON. Lowering the whole
                    // condition here would re-emit the `cmp`/`cset` gap[213]
                    // deleted — measured: `if 3 > 100` went from two
                    // instructions back to six. This walks to the published
                    // projections and realizes those, and nothing else.
                    try lowerFoldedConditionLineage(ctx, is.cond);
                    const gate = allow_return or
                        (ctx.block_answering and branchIsValueGuard(if (truth) &is.then else if (is.else_body) |*eb| eb else &is.then));
                    if (truth) {
                        _ = try lowerBlockReturns(ctx, &is.then, gate);
                    } else if (is.else_body) |*eb| {
                        _ = try lowerBlockReturns(ctx, eb, gate);
                    }
                    return;
                }
            }
            var end_branches: std.ArrayListUnmanaged(u32) = .empty;
            defer end_branches.deinit(ctx.alloc);

            const cond = try lowerExpr(ctx, is.cond);
            var fail_idx = ctx.instrs.items.len;
            try ctx.emit(.{ .op = .br, .lhs = cond, .branch_target = 0, .branch_condition = .when_false });

            // A branch early-returns when the `if` is itself the block's tail
            // slot (`allow_return`), OR when the enclosing block is a return
            // context and the branch is a value guard — `if n < 2 \n n` exits
            // the function even though the recursive tail follows it. Trailing
            // assignments/effects still fall through (see `branchIsValueGuard`).
            const answering = ctx.block_answering;
            const then_gate = allow_return or (answering and branchIsValueGuard(&is.then));
            const then_ret = try lowerBlockReturns(ctx, &is.then, then_gate);
            if (!then_ret) {
                try end_branches.append(ctx.alloc, @intCast(ctx.instrs.items.len));
                try ctx.emit(.{ .op = .br, .branch_target = 0 });
            }

            for (is.elseifs) |elseif| {
                const next_idx: u32 = @intCast(ctx.instrs.items.len);
                ctx.instrs.items[fail_idx].branch_target = next_idx;
                const econd = try lowerExpr(ctx, elseif.cond);
                fail_idx = ctx.instrs.items.len;
                try ctx.emit(.{ .op = .br, .lhs = econd, .branch_target = 0, .branch_condition = .when_false });
                const ei_gate = allow_return or (answering and branchIsValueGuard(&elseif.body));
                const branch_ret = try lowerBlockReturns(ctx, &elseif.body, ei_gate);
                if (!branch_ret) {
                    try end_branches.append(ctx.alloc, @intCast(ctx.instrs.items.len));
                    try ctx.emit(.{ .op = .br, .branch_target = 0 });
                }
            }

            const else_start: u32 = @intCast(ctx.instrs.items.len);
            ctx.instrs.items[fail_idx].branch_target = else_start;
            if (is.else_body) |*eb| {
                const else_gate = allow_return or (answering and branchIsValueGuard(eb));
                _ = try lowerBlockReturns(ctx, eb, else_gate);
            }

            const end_idx: u32 = @intCast(ctx.instrs.items.len);
            for (end_branches.items) |*br_off| {
                ctx.instrs.items[br_off.*].branch_target = end_idx;
            }
        },
        .while_loop => |ws| {
            // TWO TRANSFORMS COMPOSED, AND THE ORDER IS THE WHOLE ARGUMENT.
            //
            // MODULE-BINDING REGISTER PROMOTION. The preloads sit BEFORE
            // `head_idx`, so the back edge re-runs the test and not the load;
            // the write-backs sit AT `end_idx`, which is where both the failing
            // test and every `break` are patched to land (P2).
            var promo: [max_promoted_bindings]Promotion = undefined;
            const promo_len = planPromotions(ctx, ws, &promo);
            for (promo[0..promo_len]) |p| {
                try ctx.emit(.{ .op = .load_global, .result = p.slot, .field = p.name, .ty = .i64 });
                try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, p.name), p.slot);
            }
            // gap[221] — the unrolled main loop is emitted AHEAD of this, and
            // this lowering, unchanged, becomes its residual. When the loop is
            // not a plannable counted loop the call emits nothing and the
            // program lowers exactly as it did before.
            //
            // IT RUNS INSIDE THE PROMOTION'S SHADOW SCOPE — after the preloads
            // and the `ctx.locals` installs above, before the write-backs
            // below — and that placement discharges the two obligations the
            // composition has that neither transform has alone.
            //
            // OBLIGATION 1: THE UNROLLED COPIES MUST READ THE REGISTER. They do
            // because by the time this call lowers the body, the promoted
            // module names resolve through `ctx.locals` like any other local,
            // so the body lowers to `store_local`/`binop` rather than to
            // `store_global`/`load_global`. This is not merely a speed
            // difference: `unrollRangeIsCopyable` REFUSES `load_global` and
            // `store_global`, so with the two calls in the other order the
            // unroll does not run slowly at module scope — it declines
            // outright, which is what it did in the lane that measured it
            // against a bare baseline. Composition is what makes the transform
            // reach module-scope loops at all.
            //
            // OBLIGATION 2: THE WRITE-BACK MUST HAPPEN EXACTLY ONCE, AFTER THE
            // RESIDUAL. It does because it is still emitted at `end_idx`, and
            // nothing between here and there stores the binding. Control
            // reaches the residual from the unrolled loop with the promoted
            // registers LIVE: the unrolled loop's two exits — its failing head
            // test and its overflow guard — are both patched to the
            // instruction index the ordinary lowering below then begins at,
            // which is exactly the residual's `head_idx`. A `store_global`
            // emitted between the two loops with no reload after it is the
            // silent stale-value defect this ordering exists to prevent: the
            // residual would go on updating a register whose word had already
            // been written, and the module would keep the value the unrolled
            // loop left rather than the one the whole loop computed.
            //
            // AND NOTHING LEAVES THE UNROLLED LOOP PAST THE WRITE-BACK.
            // `unrollScanBlock` refuses `break`, `continue`, `return` and every
            // statement kind it has not been reasoned about; `unrollRangeIsCopyable`
            // refuses a branch leaving the copied range; and
            // `emitUnrolledWhilePrologue` withdraws itself if the body lowering
            // registered a break against the ENCLOSING loop anyway. So the
            // unrolled loop has exactly the two exits named above.
            ordinary: {
                // COUNTED-LOOP REDUCTION. The block prologue armed a plan for
                // exactly this statement (identity-checked below); the promotion
                // shadows are installed above, so the induction variable and the
                // bound resolve through `ctx.locals` exactly as the ordinary loop
                // would see them. Success emits the countdown and shares the exit
                // below; any doubt drops the plan and the loop lowers ordinarily.
                const counted = ctx.counted_plan;
                ctx.counted_plan = null;
                var fix_plan: ?CountedPlan = null;
                if (counted) |plan| if (plan.stmt == stmt) {
                    fix_plan = plan;
                    if (try lowerSelfMapCountedWhile(ctx, ws, plan)) {
                        try finishWhileLowering(ctx, null, promo[0..promo_len], null, &.{});
                        break :ordinary;
                    }
                    if (try lowerDirectCountedWhile(ctx, ws, plan)) {
                        try finishWhileLowering(ctx, null, promo[0..promo_len], null, &.{});
                        break :ordinary;
                    }
                    if (try lowerNestedDirectCountedWhile(ctx, ws, plan)) |live| {
                        // The fold proved these induction variables dead; their
                        // promotion write-backs (if any) are dead with them.
                        const nd = plan.nested_direct.?;
                        var dead_names: [2][]const u8 = undefined;
                        var dead_len: usize = 0;
                        if (live.iv_dead) {
                            dead_names[dead_len] = plan.iv;
                            dead_len += 1;
                        }
                        if (live.inner_dead) {
                            dead_names[dead_len] = nd.inner_iv;
                            dead_len += 1;
                        }
                        try finishWhileLowering(ctx, null, promo[0..promo_len], null, dead_names[0..dead_len]);
                        break :ordinary;
                    }
                    if (try lowerNestedTriangularCountedWhile(ctx, ws, plan)) |live| {
                        // The fold proved these induction variables dead; their
                        // promotion write-backs (if any) are dead with them.
                        const nt = plan.nested_triangular.?;
                        var dead_names: [3][]const u8 = undefined;
                        var dead_len: usize = 0;
                        if (live.iv_dead) {
                            dead_names[dead_len] = plan.iv;
                            dead_len += 1;
                        }
                        if (live.inner_iv_dead) {
                            dead_names[dead_len] = nt.inner_iv;
                            dead_len += 1;
                        }
                        if (live.inner_acc_dead) {
                            dead_names[dead_len] = nt.inner_acc;
                            dead_len += 1;
                        }
                        try finishWhileLowering(ctx, null, promo[0..promo_len], null, dead_names[0..dead_len]);
                        break :ordinary;
                    }
                    if (try lowerDigitSumCountedWhile(ctx, ws, plan)) {
                        try finishWhileLowering(ctx, null, promo[0..promo_len], null, &.{});
                        break :ordinary;
                    }
                    if (try lowerBitRevSumCountedWhile(ctx, ws, plan)) {
                        try finishWhileLowering(ctx, null, promo[0..promo_len], null, &.{});
                        break :ordinary;
                    }
                    if (try lowerCountedWhile(ctx, ws, plan)) |cr| {
                        try finishWhileLowering(ctx, cr.latch_fail, promo[0..promo_len], cr.wb_idx, &.{});
                        break :ordinary;
                    }
                };
                // LINEAR-IV STRENGTH REDUCTION arming (see the section
                // header above `lowerStmt`). The AST check is only a
                // pre-filter; `applyLinearIVSR` re-proves everything on the
                // DNIR after the body is lowered and declines without
                // touching the stream.
                var ivsr_slot: u32 = 0;
                var ivsr_step: i64 = 0;
                var ivsr_armed = false;
                if (ivsrCheckBody(&ws.body)) |ih| {
                    if (ctx.locals.get(ih.iv)) |slot| {
                        // Narrow (i8/i16/...) and non-integer slots decline:
                        // the stride variable advances mod 2^64, but a narrow
                        // iv wraps at its declared modulus, desynchronizing
                        // v = iv*C+K on wrap. Mirrors the unrollPlainIntSlot
                        // gate on the fixed-point early-exit prologue above.
                        if (unrollPlainIntSlot(ctx, slot)) {
                            ivsr_armed = true;
                            ivsr_slot = slot;
                            ivsr_step = ih.step;
                        }
                    }
                }
                try emitUnrolledWhilePrologue(ctx, ws);
                try ctx.loop_breaks.append(ctx.alloc, std.ArrayListUnmanaged(u32).empty);
                var head_idx: u32 = @intCast(ctx.instrs.items.len);
                try ctx.loop_heads.append(ctx.alloc, head_idx);
                defer _ = ctx.loop_heads.pop();
                const cond = try lowerExpr(ctx, ws.cond);
                var fail_idx = ctx.instrs.items.len;
                try ctx.emit(.{ .op = .br, .lhs = cond, .branch_target = 0, .branch_condition = .when_false });
                // `while b != 0` HAS ALREADY DECIDED WHETHER `b` IS ZERO. The branch
                // above leaves the loop when it is, so the body below is reached
                // only when it is not -- which is precisely the question a divisor
                // guard inside the body would ask a second time. Publish the fact;
                // `emit` retracts it the moment the body writes the slot.
                const proved: ?u32 = nonZeroSlotOfCondition(ctx, ws.cond);
                const already_proved = if (proved) |sl| ctx.nonzero_slots.contains(sl) else false;
                if (proved) |sl| {
                    if (!already_proved) try ctx.nonzero_slots.put(ctx.alloc, sl, {});
                }
                defer if (proved) |sl| {
                    // Outside the loop the name is ZERO, not non-zero. The fact is
                    // scoped to the body and must not outlive it.
                    if (!already_proved) _ = ctx.nonzero_slots.remove(sl);
                };
                // Captured BEFORE the fixed-point early-exit prologue below: that
                // prologue emits `.br` instructions and an extra iv store, so the
                // belt-and-braces re-verification inside applyLinearIVSR (no `.br`,
                // exactly one iv store in range) declines whenever fix-exit fired.
                // When fix-exit does not fire the range is exactly the lowered body,
                // the shape this transform was verified against.
                const ivsr_body_start: u32 = @intCast(ctx.instrs.items.len);
                // Absorbing fixed-point early exit: the arm proved the body maps
                // `target == value` to itself exactly, so every remaining iteration
                // is a no-op. Emits `if target == value { iv = bound; break }`.
                // The induction write-back preserves the full trip count's
                // post-loop `iv == bound`; the target is already exact and every
                // other body-assigned name was proven dead after the loop.
                if (fix_plan) |fp| if (fp.fix_exit) |fx| {
                    if (fp.bound_lit) |bl| {
                        if (ctx.locals.get(fx.target)) |tslot| {
                            if (ctx.locals.get(fp.iv)) |ivslot| {
                                if (unrollPlainIntSlot(ctx, tslot) and unrollPlainIntSlot(ctx, ivslot)) {
                                    const t = ctx.freshTemp();
                                    try ctx.emit(.{ .op = .binop, .result = t, .binop = .eq, .lhs = .{ .local = tslot }, .rhs = .{ .i64 = fx.value } });
                                    const else_idx: u32 = @intCast(ctx.instrs.items.len);
                                    try ctx.emit(.{ .op = .br, .lhs = .{ .temp = t }, .branch_target = 0, .branch_condition = .when_false });
                                    try ctx.emit(.{ .op = .store_local, .result = ivslot, .lhs = .{ .i64 = bl }, .ty = .i64 });
                                    const br_idx: u32 = @intCast(ctx.instrs.items.len);
                                    try ctx.emit(.{ .op = .br, .branch_target = 0 });
                                    try ctx.loop_breaks.items[ctx.loop_breaks.items.len - 1].append(ctx.alloc, br_idx);
                                    ctx.instrs.items[else_idx].branch_target = @intCast(ctx.instrs.items.len);
                                }
                            }
                        }
                    }
                };
                // A loop body is never an implicit-tail position: its last statement
                // runs once per iteration, not once per call. Propagating
                // `allow_return` here makes `tryEmitTailDemandReturn` end the body
                // with `return <last expr>`, so the loop returns after one pass.
                // Explicit `return` inside the body still lowers via the `.ret` arm.
                _ = try lowerBlockReturns(ctx, &ws.body, false);
                if (ivsr_armed) {
                    const ivsr_body_end: u32 = @intCast(ctx.instrs.items.len);
                    _ = try applyLinearIVSR(ctx, ivsr_slot, ivsr_step, &head_idx, &fail_idx, ivsr_body_start, ivsr_body_end);
                }
                try ctx.emit(.{ .op = .br, .branch_target = head_idx });
                try finishWhileLowering(ctx, fail_idx, promo[0..promo_len], null, &.{});
            }
        },
        .num_for => |nf| try lowerNumFor(ctx, nf),
        .ret => |r| {
            if (r.vals.len == 0) {
                try ctx.emit(.{ .op = .ret, .lhs = .{ .i64 = 0 } });
            } else if (r.vals.len > 1) {
                if (ctx.ret_pack.len != r.vals.len) {
                    return bailWith(ctx.diagnostic, @src(), "result-pack-arity");
                }
                const vals = try ctx.alloc.alloc(dnir.Value, r.vals.len);
                errdefer ctx.alloc.free(vals);
                for (r.vals, 0..) |value, i| {
                    const expected = ctx.ret_pack[i];
                    if (expected == .f64 or expected == .any or expected == .void or
                        expected == .@"struct" or expected == .table_type)
                    {
                        return bailWith(ctx.diagnostic, @src(), "result-pack-abi");
                    }
                    // The DECLARED class and the VALUE's own class must agree.
                    // A declared pack always said so; a pack inferred from the
                    // returns (`scanReturnPackArities`) names the GP class for
                    // every member, so an f64 member refuses HERE rather than
                    // riding an integer register to the caller — the exact
                    // refusal the declared path gives the same body.
                    if (exprIsF64(ctx, value)) {
                        return bailWith(ctx.diagnostic, @src(), "result-pack-abi");
                    }
                    vals[i] = try lowerExpr(ctx, value);
                }
                try ctx.emit(.{ .op = .ret_pack, .vals = vals });
            } else if (r.vals[0].* == .table or
                (ctx.ret_record != null and isRecordLocalName(ctx, r.vals[0])))
            {
                try lowerRecordReturn(ctx, r.vals[0]);
            } else if (!try tryEmitSelfTail(ctx, r.vals[0])) {
                const ret_ty: RT = if (exprIsF64(ctx, r.vals[0]))
                    .f64
                else if (exprIsPointer(ctx, r.vals[0]))
                    physical_pointer
                else
                    .any;
                try ctx.emit(.{ .op = .ret, .lhs = try lowerExpr(ctx, r.vals[0]), .ty = ret_ty });
            }
        },
        .expr_stmt => |es| {
            // A bare table expression statement is the block's tail result —
            // `tryEmitTailDemandReturn` turns it into the record return. When a
            // preceding statement pushes it out of `blk.tail_expr` and into
            // `stmts`, lowering it here as an ordinary expression hit
            // `lowerExprCons`, which has no `.table` arm, and failed the whole
            // function. Leave it for the tail handler.
            if (es.expr.* == .table) return;
            _ = try lowerExprCons(ctx, es.expr, exprCallConsumption(es.expr));
        },
        .call_stmt => |cs| {
            _ = try lowerExprCons(ctx, cs.expr, .discard);
        },
        .do_block => |db| {
            // A parser-produced block wrapper (simultaneous assignment, table
            // destructuring). It is not a scope: the parser already resolved
            // names into the enclosing function's bindings, and re-entering
            // scope machinery here would see staged place/value temporaries as
            // fresh declarations. Statements lower in sequence; the tail
            // expression, if any, is the enclosing statement's value.
            for (db.body.stmts, 0..) |*inner, i| {
                try pushEnclosingFrame(ctx, &db.body, i);
                defer popEnclosingFrame(ctx);
                tryArmCountedLoop(ctx, db.body.stmts, i);
                if (ctx.zerotrip_swallowed.contains(inner)) continue;
                try lowerStmt(ctx, inner, false);
            }
            if (db.body.tail_expr) |te| _ = try lowerExprCons(ctx, te, .discard);
        },
        .brk => {
            if (ctx.loop_breaks.items.len == 0) return bail(ctx.diagnostic, @src());
            const br_idx: u32 = @intCast(ctx.instrs.items.len);
            try ctx.emit(.{ .op = .br, .branch_target = 0 });
            try ctx.loop_breaks.items[ctx.loop_breaks.items.len - 1].append(ctx.alloc, br_idx);
        },
        .cont => {
            if (ctx.loop_heads.items.len == 0) return bail(ctx.diagnostic, @src());
            try ctx.emit(.{ .op = .br, .branch_target = ctx.loop_heads.items[ctx.loop_heads.items.len - 1] });
        },
        .directive => |d| {
            if (std.mem.eql(u8, d.attr.name, "comp.hint.fence") or
                std.mem.eql(u8, d.attr.name, "fence") or
                std.mem.eql(u8, d.attr.name, "__fence"))
            {
                _ = try lowerHwIntrinsic(ctx, .fence, &.{});
            } else if (std.mem.eql(u8, d.attr.name, "comp.hint.spin_wait") or
                std.mem.eql(u8, d.attr.name, "spin_wait") or
                std.mem.eql(u8, d.attr.name, "__spin_wait"))
            {
                _ = try lowerHwIntrinsic(ctx, .spin_wait, &.{});
            } else {
                return bailNamed(ctx.diagnostic, @src(), "directive-not-lowered", d.attr.name);
            }
        },
        else => return bailNamed(ctx.diagnostic, @src(), "statement-not-lowered", @tagName(stmt.*)),
    }
}

/// gap[221] — UNROLL A COUNTED `while` WHOSE TRIP COUNT IS A RUNTIME VALUE.
///
/// MEASURED BEFORE IT WAS BUILT, at subject a8929d50, by hand-unrolling the
/// SOURCE of four runtime-trip-count kernels and compiling both spellings with
/// the UNPATCHED compiler — so the headroom is the unroll's own and not a
/// difference between two compilers. Factor 4 predicted 1.25x-1.64x.
///
/// MEASURED AGAIN AFTER IT WAS BUILT, severed against enabled through
/// `IDOL_UNROLL` on ONE compiler binary, min-of-9, ~1.03s arms, 3.4e9 inner
/// iterations, whole distribution within 2% of its own minimum:
///
///     kernel          severed   unrolled   ratio
///     fib recurrence   1.0322     0.7325   1.409x
///     sum reduce       1.0025     0.6254   1.603x
///     square reduce    1.0033     0.6484   1.547x
///     mul+add mix      1.0315     0.8622   1.196x
///
/// On the fib kernel that is also 1.31x FASTER THAN `clang -O3` on the same
/// source (0.7398 against 0.9703), which clang does not unroll because the
/// bound is runtime.
///
/// GAP-205 RANKED THIS 5.77x AND THAT NUMBER IS NOT THIS TRANSFORM. It came
/// from FULLY unrolling a loop whose trip count is the literal 30, where the
/// loop DISAPPEARS and what is measured is constant folding. Against a runtime
/// bound the honest band is 1.20x-1.60x at factor 4.
///
/// FACTOR 4 IS THE MEASURED RESEARCH CANDIDATE. Swept on the same four kernels:
/// factor 2 REGRESSES mix to 0.920x, factor 3 loses half the win on the reduce
/// kernels (1.16x against 1.48x at factor 2) because the residual it leaves is
/// larger, and factor 8 wins more on one kernel and less on two. 4 measures
/// 1.19x-1.61x with no row below 1.
///
/// THE RECURRENCE IS NOT SHORTENED AND NOTHING HERE CLAIMS IT IS. The fib body
/// is a chain of 1-cycle adds; unrolling it takes the loop from ~1.37 cycles
/// per iteration to ~1.0, which is the chain bound, and no further. What is
/// removed is the back-edge and the trip test, not the dependence — and the
/// instruction count barely moves. On the sum kernel the rolled loop is 7
/// instructions with 2 branches per iteration and the unrolled one is 5
/// instructions with 2 branches per FOUR iterations. GAP-205's own rule reads
/// the right axis: what pays here is the back-edge, not the instruction.
///
/// LEGALITY. The unrolled loop runs only while `iv <cmp> bound - (K-1)*step`,
/// which is exactly the condition under which the original loop would take K
/// more iterations. So NO BODY COPY IS SPECULATED: every copy that executes is
/// an iteration the rolled loop also executes, in the same order, with the same
/// values. Trip counts 0, 1, K-1, K, K+1 and large all fall out of that without
/// a special case — the residual is the ORIGINAL loop, emitted unchanged
/// immediately after, and it is what runs when fewer than K iterations remain.
/// A body that traps mid-loop traps in the same copy the rolled loop would
/// have trapped in, because the copy before it ran on the same values.
///
/// THE `bound - (K-1)*step` SUBTRACTION CAN OVERFLOW and that is the one place
/// a wrong answer could enter: if it wraps, `iv <cmp> lim` admits iterations
/// the original refuses. A runtime bound gets a runtime guard (`lim` must land
/// on the expected side of `bound`, which it does exactly when the subtraction
/// did not wrap) branching straight past the unrolled loop; a literal bound is
/// checked at compile time and the transform simply declines.
///
/// CURRENT DISPOSITION: RESEARCH-ONLY AND OFF BY DEFAULT. Eligibility below is
/// still reconstructed from AST shapes, local slot names and a duplicated
/// operator classifier; the graph publishes neither a transformation identity
/// nor its input/output correspondence, observation obligations or witness.
/// Those are admission prerequisites, not documentation debt. `IDOL_UNROLL`
/// therefore selects an explicit experiment; ordinary compilation must retain
/// the original loop until that graph-native transformation path exists.
const UnrollPlan = struct {
    iv_slot: u32,
    cmp: dnir.BinOpTag,
    bound: dnir.Value,
    step: i64,
    factor: u32,
};

/// `IDOL_UNROLL` — an explicit research selector. `off`/`0`/`1`, absence,
/// emptiness and malformed values leave the transform off; an integer 2..16
/// selects the factor. One compiler binary therefore produces both arms of a
/// timing comparison without making the unwitnessed arm production law.
pub fn unrollFactorSetting() u32 {
    const raw = std.c.getenv("IDOL_UNROLL") orelse return unrollFactorFromText(null);
    return unrollFactorFromText(std.mem.sliceTo(raw, 0));
}

fn unrollFactorFromText(setting: ?[]const u8) u32 {
    const text = setting orelse return 1;
    if (text.len == 0) return 1;
    if (std.mem.eql(u8, text, "off") or std.mem.eql(u8, text, "OFF")) return 1;
    const n = std.fmt.parseInt(u32, text, 10) catch return 1;
    if (n < 2) return 1;
    if (n > 16) return 16;
    return n;
}

test "dnir_lower: runtime unroll is research opt-in pending graph transform identity" {
    try std.testing.expectEqual(@as(u32, 1), unrollFactorFromText(null));
    try std.testing.expectEqual(@as(u32, 1), unrollFactorFromText(""));
    try std.testing.expectEqual(@as(u32, 1), unrollFactorFromText("off"));
    try std.testing.expectEqual(@as(u32, 1), unrollFactorFromText("0"));
    try std.testing.expectEqual(@as(u32, 1), unrollFactorFromText("1"));
    try std.testing.expectEqual(@as(u32, 1), unrollFactorFromText("invalid"));
    try std.testing.expectEqual(@as(u32, 4), unrollFactorFromText("4"));
    try std.testing.expectEqual(@as(u32, 16), unrollFactorFromText("99"));
}

test "dnir_lower: unroll copies have physical positions but no derived occurrences" {
    // EXECUTABLE CENSUS FOR THE RESEARCH UNROLLER'S DELETION CONDITION.
    // One lowered body position is copied four times. Branch destinations move
    // with each physical copy, while the result/local ids are copied verbatim
    // and no graph occurrence survives. An instruction index is not semantic
    // identity; this test therefore records the ambiguity instead of minting a
    // lowering-owned transform/occurrence vocabulary to conceal it.
    // Remaining consumers are `emitUnrolledWhilePrologue`, which appends these
    // copies, and `Arm64Compiler`, which observes their reused physical ids.
    const factor: usize = 4;
    const body = [_]dnir.Instr{
        .{
            .op = .binop,
            .result = 12,
            .binop = .add,
            .lhs = .{ .local = 4 },
            .rhs = .{ .i64 = 1 },
        },
        .{
            .op = .br,
            .lhs = .{ .temp = 12 },
            .branch_target = 2,
            .branch_condition = .when_true,
        },
    };
    var copies: [body.len * factor]dnir.Instr = undefined;
    for (0..factor) |copy| {
        const offset: u32 = @intCast(copy * body.len);
        for (body, 0..) |instruction, instruction_index| {
            copies[copy * body.len + instruction_index] =
                unrollPhysicalCopy(instruction, offset);
        }
    }

    try std.testing.expectEqual(@as(usize, 4), copies.len / body.len);
    for (0..factor) |copy| {
        const binop = copies[copy * body.len];
        const branch = copies[copy * body.len + 1];
        // SAME PHYSICAL VALUE IDS in all four copies.
        try std.testing.expectEqual(@as(?u32, 12), binop.result);
        try std.testing.expectEqual(@as(u32, 4), binop.lhs.local);
        try std.testing.expectEqual(@as(u32, 12), branch.lhs.temp);
        // DISTINCT PHYSICAL POSITIONS/DESTINATIONS, not distinct occurrences.
        try std.testing.expectEqual(@as(u32, @intCast(2 + copy * body.len)), branch.branch_target);
        try std.testing.expect(binop.relation == null);
        try std.testing.expect(binop.application == null);
        try std.testing.expect(binop.value == null);
        try std.testing.expect(binop.subject == null);
    }

    // Damage controls: the research copy range must refuse as soon as any
    // existing semantic coordinate reaches it. The first control establishes
    // the positive physical shape; each later arm changes only one fact.
    try std.testing.expect(unrollRangeIsCopyable(&body, 0, body.len));
    var identified = body;
    identified[0].relation = 1;
    try std.testing.expect(!unrollRangeIsCopyable(&identified, 0, identified.len));
    identified = body;
    identified[0].application = 2;
    try std.testing.expect(!unrollRangeIsCopyable(&identified, 0, identified.len));
    identified = body;
    identified[0].value = 3;
    try std.testing.expect(!unrollRangeIsCopyable(&identified, 0, identified.len));
    identified = body;
    identified[0].subject = 4;
    try std.testing.expect(!unrollRangeIsCopyable(&identified, 0, identified.len));

    // Delete this census only when the graph producer supplies one exact
    // transform id plus original and per-copy application/value occurrence ids,
    // and `MachineLineage` carries those same ids into object ranges. Until then
    // the ordinary compiler keeps this transform off and the research arm stays
    // fail-closed.
}

/// A slot that holds a plain full-width integer and nothing else. An induction
/// variable that is secretly an f64, a `str` descriptor, a pointer, a bool or a
/// declared-narrow binding is not one this arithmetic reasons about.
fn unrollPlainIntSlot(ctx: *const LowerCtx, slot: u32) bool {
    if (ctx.f64_slots.contains(slot)) return false;
    if (ctx.str_slots.contains(slot)) return false;
    if (ctx.ptr_slots.contains(slot)) return false;
    if (ctx.bool_slots.contains(slot)) return false;
    if (ctx.narrow_slots.contains(slot)) return false;
    return true;
}

/// The local slot a NAME denotes here, in the same binding order the `.name`
/// arm of `lowerExprCons` states. A published application on the expression, a
/// fused body-relation shadow, or a non-integer slot all answer null.
fn unrollNameSlot(ctx: *const LowerCtx, expr: *const ast.Expr) ?u32 {
    if (expr.* != .name) return null;
    if (ctx.occurrences.get(expr) != null) return null;
    if (ctx.fused_literals.contains(expr.name.ident)) return null;
    const slot = ctx.locals.get(expr.name.ident) orelse return null;
    if (!unrollPlainIntSlot(ctx, slot)) return null;
    return slot;
}

/// Every expression under `expr` is one this transform can duplicate: no
/// published application anywhere, and no expression kind that could reach a
/// call, a table, a string or a place.
///
/// `scan.declared` carries the names the body BINDS BEFORE this expression.
/// They are not in `ctx.locals` yet — nothing in the body has been lowered —
/// and without them a body as ordinary as `t = a + b ; b = t` reads as
/// uncopyable because `t` resolves nowhere.
fn unrollExprIsCopyable(ctx: *const LowerCtx, scan: *const UnrollBodyScan, expr: *const ast.Expr) bool {
    // THE GRAPH DECIDES, not the spelling. `occurrences` is the same index
    // `native_backend` counts realizations against, so an expression the graph
    // published an application for is refused here by the producer's own
    // record rather than by a guess about which syntax makes calls.
    if (ctx.occurrences.get(expr) != null) return false;
    return switch (expr.*) {
        .int_lit, .true_lit, .false_lit => true,
        .name => |n| blk: {
            if (ctx.fused_literals.contains(n.ident)) break :blk false;
            if (scan.declaresName(n.ident)) break :blk true;
            const slot = ctx.locals.get(n.ident) orelse break :blk false;
            break :blk unrollPlainIntSlot(ctx, slot);
        },
        .unop => |u| (u.op == .neg or u.op == .not or u.op == .bnot) and
            unrollExprIsCopyable(ctx, scan, u.operand),
        // THE OPERATOR HAS TO BE ARITHMETIC THAT CANNOT CALL, not merely a
        // `binop` node. `pow` and `concat` reach a runtime helper and `matmul`,
        // `pipeline` and `contains` are applications — copying any of them
        // either duplicates a call or breaks `native_backend`'s
        // application-realization count. `promotableExpr` (P1) already owns the
        // exact list of ops that are safe to duplicate inside a loop region;
        // this asks it rather than keeping a second copy that can drift.
        //
        // The emitted-stream check in `unrollRangeIsCopyable` would catch these
        // too, but only by withdrawing AFTER the body was lowered. Refusing on
        // the AST keeps the common case out of the asymmetric withdrawal path
        // above.
        .binop => |b| unrollCopyableBinOp(b.op) and
            unrollExprIsCopyable(ctx, scan, b.lhs) and unrollExprIsCopyable(ctx, scan, b.rhs),
        else => false,
    };
}

/// The binary operators `promotableExpr` admits — the ops that are arithmetic
/// and cannot reach a call. Stated against that predicate so the two lanes
/// cannot disagree about which operators are duplicable.
fn unrollCopyableBinOp(op: ast.BinOp) bool {
    return switch (op) {
        .add,
        .sub,
        .mul,
        .div,
        .idiv,
        .mod,
        .band,
        .bor,
        .bxor,
        .lshift,
        .rshift,
        .eq,
        .neq,
        .lt,
        .gt,
        .leq,
        .geq,
        .@"and",
        .@"or",
        => true,
        else => false,
    };
}

fn unrollExprAssignsName(expr: *const ast.Expr, ident: []const u8) bool {
    return expr.* == .name and std.mem.eql(u8, expr.name.ident, ident);
}

const UnrollBodyScan = struct {
    ok: bool = true,
    stmts: u32 = 0,
    iv_writes: u32 = 0,
    /// Names the body binds. Bounded by the statement budget, so a fixed array
    /// is the whole storage and the scan allocates nothing.
    declared: [32][]const u8 = undefined,
    declared_len: usize = 0,

    fn declaresName(self: *const UnrollBodyScan, ident: []const u8) bool {
        for (self.declared[0..self.declared_len]) |name| {
            if (std.mem.eql(u8, name, ident)) return true;
        }
        return false;
    }

    fn declare(self: *UnrollBodyScan, ident: []const u8) void {
        if (self.declared_len == self.declared.len) {
            self.ok = false;
            return;
        }
        self.declared[self.declared_len] = ident;
        self.declared_len += 1;
    }
};

/// Walk a candidate body. Refuses every statement kind that can leave the body
/// (`break`, `continue`, `return`, `goto`), every kind that can call or read
/// storage the copies would then touch more than once, and every nested loop.
fn unrollScanBlock(
    ctx: *const LowerCtx,
    block: *const ast.Block,
    iv: []const u8,
    bound: ?[]const u8,
    scan: *UnrollBodyScan,
) void {
    if (block.tail_expr != null) {
        scan.ok = false;
        return;
    }
    for (block.stmts) |*stmt| {
        if (!scan.ok) return;
        scan.stmts += 1;
        switch (stmt.*) {
            .local_decl => |ld| {
                if (ld.names.len != ld.inits.len) {
                    scan.ok = false;
                    return;
                }
                for (ld.inits) |init| {
                    if (!unrollExprIsCopyable(ctx, scan, init)) scan.ok = false;
                }
                for (ld.names) |nm| {
                    // A body-local rebinding of the induction variable or of
                    // the bound would make the trip arithmetic describe a
                    // different name than the loop tests.
                    if (std.mem.eql(u8, nm.ident, iv)) scan.ok = false;
                    if (bound) |b| if (std.mem.eql(u8, nm.ident, b)) {
                        scan.ok = false;
                    };
                    scan.declare(nm.ident);
                }
            },
            .assign => |as| {
                if (as.targets.len != as.values.len) {
                    scan.ok = false;
                    return;
                }
                for (as.targets) |t| {
                    if (t.* != .name) {
                        scan.ok = false;
                        return;
                    }
                    if (ctx.occurrences.get(t) != null) scan.ok = false;
                    if (unrollExprAssignsName(t, iv)) scan.iv_writes += 1;
                    if (bound) |b| if (unrollExprAssignsName(t, b)) {
                        scan.ok = false;
                    };
                }
                for (as.values) |v| {
                    if (!unrollExprIsCopyable(ctx, scan, v)) scan.ok = false;
                }
            },
            .if_stmt => |ifs| {
                if (ifs.binding != null) {
                    scan.ok = false;
                    return;
                }
                if (!unrollExprIsCopyable(ctx, scan, ifs.cond)) scan.ok = false;
                unrollScanBlock(ctx, &ifs.then, iv, bound, scan);
                for (ifs.elseifs) |ei| {
                    if (!unrollExprIsCopyable(ctx, scan, ei.cond)) scan.ok = false;
                    unrollScanBlock(ctx, &ei.body, iv, bound, scan);
                }
                if (ifs.else_body) |eb| unrollScanBlock(ctx, &eb, iv, bound, scan);
            },
            else => {
                scan.ok = false;
                return;
            },
        }
    }
}

/// The constant step of a trailing `iv = iv + c` / `iv = iv - c`, or null.
fn unrollTrailingStep(ctx: *const LowerCtx, stmt: *const ast.Stmt, iv: []const u8) ?i64 {
    if (stmt.* != .assign) return null;
    const as = stmt.assign;
    if (as.targets.len != 1 or as.values.len != 1) return null;
    if (!unrollExprAssignsName(as.targets[0], iv)) return null;
    const v = as.values[0];
    if (v.* != .binop) return null;
    const b = v.binop;
    if (b.op != .add and b.op != .sub) return null;
    if (!unrollExprAssignsName(b.lhs, iv)) return null;
    const c = constIntValue(ctx.graph, b.rhs) orelse return null;
    if (b.op == .add) return c;
    return std.math.negate(c) catch null;
}

fn unrollPlanWhile(ctx: *const LowerCtx, ws: anytype) ?UnrollPlan {
    const factor = unrollFactorSetting();
    if (factor < 2) return null;
    if (ws.cond.* != .binop) return null;
    if (ctx.occurrences.get(ws.cond) != null) return null;
    const cond = ws.cond.binop;
    const cmp: dnir.BinOpTag = switch (cond.op) {
        .lt => .lt,
        .leq => .leq,
        .gt => .gt,
        .geq => .geq,
        else => return null,
    };
    const iv_expr = cond.lhs;
    if (iv_expr.* != .name) return null;
    const iv = iv_expr.name.ident;
    const iv_slot = unrollNameSlot(ctx, iv_expr) orelse return null;

    var bound_name: ?[]const u8 = null;
    const bound: dnir.Value = blk: {
        if (constIntValue(ctx.graph, cond.rhs)) |v| break :blk .{ .i64 = v };
        const slot = unrollNameSlot(ctx, cond.rhs) orelse return null;
        bound_name = cond.rhs.name.ident;
        break :blk .{ .local = slot };
    };
    if (bound_name) |b| if (std.mem.eql(u8, b, iv)) return null;

    if (ws.body.stmts.len == 0) return null;
    const step = unrollTrailingStep(ctx, &ws.body.stmts[ws.body.stmts.len - 1], iv) orelse return null;
    if (step == 0) return null;
    // A COUNTER RUNNING THE WRONG WAY NEVER TERMINATES, and unrolling an
    // infinite loop is still an infinite loop — but the limit arithmetic below
    // assumes the counter moves TOWARD the bound, so state the requirement
    // rather than relying on the program not to be written.
    switch (cmp) {
        .lt, .leq => if (step <= 0) return null,
        .gt, .geq => if (step >= 0) return null,
        else => return null,
    }

    var scan: UnrollBodyScan = .{};
    unrollScanBlock(ctx, &ws.body, iv, bound_name, &scan);
    if (!scan.ok) return null;
    // Exactly one write to the induction variable, and it is the trailing step
    // the plan is built from.
    if (scan.iv_writes != 1) return null;
    if (scan.stmts == 0 or scan.stmts > 24) return null;
    if (scan.stmts * factor > 96) return null;

    return .{ .iv_slot = iv_slot, .cmp = cmp, .bound = bound, .step = step, .factor = factor };
}

/// Every DNIR instruction in `[start, end)` may be duplicated verbatim.
///
/// THE OP WHITELIST IS THE REALIZATION-COUNT ARGUMENT. `native_backend`
/// requires every application the graph published to be realized EXACTLY ONCE,
/// so copying an instruction that carries an application id would refuse the
/// module (`application-realization-count`) — or, worse, execute a call twice.
/// The ops admitted here carry none, own no heap slices, and touch no storage
/// outside the frame.
///
/// The branch check is the control-flow argument: a `br` leaving the range is a
/// `break`, a `continue` or a return, and the copies have no such edge to
/// offset. A target of exactly `end` is the body's own fall-through and becomes
/// the next copy's first instruction, which is what falling through means here.
fn unrollRangeIsCopyable(instrs: []const dnir.Instr, start: u32, end: u32) bool {
    var i = start;
    while (i < end) : (i += 1) {
        const in = instrs[i];
        switch (in.op) {
            .@"const", .store_local, .binop, .br => {},
            else => return false,
        }
        if (in.relation != null or in.application != null or in.value != null or in.subject != null) return false;
        if (in.aggregate != null or in.target != null) return false;
        if (in.realization_start != null) return false;
        if (in.vals.len != 0 or in.pack_results.len != 0) return false;
        if (in.callee.len != 0 or in.field.len != 0 or in.record.len != 0 or in.req_alias.len != 0) return false;
        if (in.op == .br and (in.branch_target < start or in.branch_target > end)) return false;
    }
    return true;
}

/// Copy one already-lowered instruction to another PHYSICAL schedule position.
/// This deliberately adjusts only a branch destination. It does not manufacture
/// a transformation id or derived semantic occurrence: lowering is not their
/// producer. `unrollRangeIsCopyable` therefore refuses every instruction that
/// already carries a semantic coordinate. The executable census above pins the
/// remaining same-origin/same-occurrence ambiguity until the graph owns it.
fn unrollPhysicalCopy(instruction: dnir.Instr, offset: u32) dnir.Instr {
    var copied = instruction;
    if (copied.op == .br) copied.branch_target += offset;
    return copied;
}

/// Emit the unrolled main loop AHEAD of the ordinary loop lowering, so the
/// ordinary lowering that follows IS the residual. Emits nothing at all when
/// the loop is not a plannable counted loop; the caller is unchanged either way.
fn emitUnrolledWhilePrologue(ctx: *LowerCtx, ws: anytype) Error!void {
    const plan = unrollPlanWhile(ctx, ws) orelse return;

    // `(factor - 1) * step`, the distance from the last counter value the
    // unrolled loop may admit to the bound. Computed with overflow checks: a
    // step and factor whose product does not fit is not a loop this reasons
    // about.
    const span = std.math.mul(i64, @as(i64, plan.factor - 1), plan.step) catch return;

    const saved_instrs = ctx.instrs.items.len;
    // THE ENCLOSING LOOP'S BREAK LIST, so a withdrawal cannot leave a dangling
    // index in it. This prologue runs BEFORE the `while` arm pushes its own
    // list, so a `break` lowered here would register against the loop OUTSIDE
    // this one; `unrollScanBlock` refuses `.brk` outright, but a withdrawal
    // that shrank `ctx.instrs` past a recorded index would then patch an
    // unrelated instruction's branch target. Recorded rather than reasoned
    // about, and checked below.
    const saved_breaks: usize = if (ctx.loop_breaks.items.len == 0)
        0
    else
        ctx.loop_breaks.items[ctx.loop_breaks.items.len - 1].items.len;

    // THE LIMIT IS NEVER GIVEN A LOCAL SLOT, and that is a measured decision
    // rather than a style. `native_backend.planGpStackLocals` earns a register
    // home for a slot by finding its `store_local` INSIDE a loop range; a
    // preheader store is outside every range, so a `store_local` here takes a
    // FRAME slot and the unrolled loop pays an `ldr` per trip for a value that
    // never changes. It also broke the pinned test "a carried local in a
    // calling function keeps its register across the back edge", which counts
    // exactly that: expected 0 frame locals, found 1. Recomputing the
    // subtraction in the loop head instead costs one `sub` per K iterations,
    // in a register, and leaves the frame exactly as it was.
    var bound_slot: ?u32 = null;
    var limit_const: i64 = 0;
    var guard_idx: ?usize = null;
    switch (plan.bound) {
        .i64 => |b| limit_const = std.math.sub(i64, b, span) catch return,
        .local => |slot| {
            bound_slot = slot;
            // THE OVERFLOW GUARD, STATED AS THE CONDITION RATHER THAN DETECTED
            // AFTER THE FACT. `bound - span` is evaluated in wrapping i64 below,
            // and a wrapped limit would admit iterations the rolled loop
            // refuses — the one way a wrong answer could enter here. With
            // `span > 0` the subtraction is exact exactly when
            // `bound >= INT64_MIN + span`, and that right-hand side is a
            // compile-time constant; symmetric against INT64_MAX for `span < 0`.
            // When the guard fails, control goes straight past the unrolled
            // loop and the residual — which is the ORIGINAL loop, emitted
            // unchanged below — runs the whole trip.
            const edge: i64 = if (span > 0)
                std.math.minInt(i64) + span
            else
                std.math.maxInt(i64) + span;
            const guard = ctx.freshTemp();
            try ctx.emit(.{
                .op = .binop,
                .result = guard,
                .binop = if (span > 0) .geq else .leq,
                .lhs = .{ .local = slot },
                .rhs = .{ .i64 = edge },
            });
            guard_idx = ctx.instrs.items.len;
            try ctx.emit(.{
                .op = .br,
                .lhs = .{ .temp = guard },
                .branch_target = 0,
                .branch_condition = .when_false,
            });
        },
        else => return,
    }

    const head_idx: u32 = @intCast(ctx.instrs.items.len);
    const limit: dnir.Value = if (bound_slot) |slot| blk: {
        const t = ctx.freshTemp();
        try ctx.emit(.{
            .op = .binop,
            .result = t,
            .binop = .sub,
            .lhs = .{ .local = slot },
            .rhs = .{ .i64 = span },
        });
        break :blk .{ .temp = t };
    } else .{ .i64 = limit_const };

    const cond_temp = ctx.freshTemp();
    try ctx.emit(.{
        .op = .binop,
        .result = cond_temp,
        .binop = plan.cmp,
        .lhs = .{ .local = plan.iv_slot },
        .rhs = limit,
    });
    const fail_idx = ctx.instrs.items.len;
    try ctx.emit(.{
        .op = .br,
        .lhs = .{ .temp = cond_temp },
        .branch_target = 0,
        .branch_condition = .when_false,
    });

    const body_start: u32 = @intCast(ctx.instrs.items.len);
    // Loop bodies are not implicit-tail positions — see the while_loop arm.
    _ = try lowerBlockReturns(ctx, &ws.body, false);
    const body_end: u32 = @intCast(ctx.instrs.items.len);

    // BELT AND BRACES, and it is not redundant with the AST scan: the scan
    // rules on what the SOURCE says, this rules on what lowering actually
    // emitted. If they ever disagree the emitted stream wins, the whole
    // prologue is withdrawn, and the ordinary lowering below runs the loop
    // exactly as it did before this existed.
    const broke_out: bool = ctx.loop_breaks.items.len != 0 and
        ctx.loop_breaks.items[ctx.loop_breaks.items.len - 1].items.len != saved_breaks;
    if (broke_out or body_end == body_start or
        !unrollRangeIsCopyable(ctx.instrs.items, body_start, body_end))
    {
        ctx.instrs.shrinkRetainingCapacity(saved_instrs);
        if (ctx.loop_breaks.items.len != 0) {
            ctx.loop_breaks.items[ctx.loop_breaks.items.len - 1].shrinkRetainingCapacity(saved_breaks);
        }
        // `ctx.next_temp` IS DELIBERATELY NOT ROLLED BACK, and this is the one
        // place the withdrawal has to be asymmetric. The withdrawn lowering may
        // have BOUND NAMES: a body-local `t: i64 = ...` puts `t -> slot N` into
        // `ctx.locals`, and that entry survives the shrink because `ctx.locals`
        // is not part of the emitted stream. Rewinding the counter would then
        // hand slot N out again to the residual's first `freshTemp` — a `.temp`
        // and a `.local` share one numbering space here, so the residual's
        // condition temp and the body's `t` would be the same register and the
        // loop would compute a wrong answer that still compiles. Burning the
        // slot numbers instead costs a few unused ids; `planGpStackLocals`
        // enumerates slots from the INSTRUCTIONS, so an id no instruction
        // mentions never reaches a frame or a home.
        return;
    }

    var copy: u32 = 1;
    while (copy < plan.factor) : (copy += 1) {
        const offset: u32 = @as(u32, @intCast(ctx.instrs.items.len)) - body_start;
        var i = body_start;
        while (i < body_end) : (i += 1) {
            try ctx.emit(unrollPhysicalCopy(ctx.instrs.items[i], offset));
        }
    }

    try ctx.emit(.{ .op = .br, .branch_target = head_idx });
    const exit_idx: u32 = @intCast(ctx.instrs.items.len);
    ctx.instrs.items[fail_idx].branch_target = exit_idx;
    if (guard_idx) |g| ctx.instrs.items[g].branch_target = exit_idx;
}

/// What one name mapped to before a nested block declared it — the fact that
/// lets the block's exit restore the enclosing binding instead of leaking the
/// shadow's slot (gap[228]).
const BlockDeclaration = struct { name: []const u8, prior: ?u32 };

/// The names this block DECLARES at its own statement level, each with the
/// mapping it is about to shadow. Only `.local_decl` rows: a declaration is a
/// new binding scoped to the block, which is exactly the adjudication the
/// lift's roster performs (`liftBindingsInBlock` shrinks its `declared` roster
/// at block exit). A bare assignment is not recorded because it is not a new
/// binding — it targets whatever binding is visible, and diverting it would be
/// the opposite defect.
fn noteBlockDeclarations(
    ctx: *LowerCtx,
    block: *const ast.Block,
    out: *std.ArrayListUnmanaged(BlockDeclaration),
) Error!void {
    for (block.stmts) |*stmt| {
        if (stmt.* != .local_decl) continue;
        for (stmt.local_decl.names) |n| {
            var recorded = false;
            for (out.items) |row| {
                if (std.mem.eql(u8, row.name, n.ident)) {
                    recorded = true;
                    break;
                }
            }
            if (recorded) continue;
            try out.append(ctx.alloc, .{ .name = n.ident, .prior = ctx.locals.get(n.ident) });
        }
    }
}

/// gap[228], the extent half. `ctx.locals` is the lowering's binding
/// environment, and it is keyed by SPELLING with no block extent — so a
/// declaration inside a nested block used to stay in the map after the block
/// closed, and a later write or read of the same spelling was answered from
/// the shadow's slot while the graph's `mutations` column named the module
/// binding. Measured before this restore existed: `deep()` writing `ring = 2`
/// BELOW a closed `if` block that declared its own `ring` left the module word
/// untouched and the program answered 0 where the answer is 2, with
/// `binding_mutations` correctly naming the module binding the whole time.
///
/// The restore consumes the same fact the lift consumes: a declaration's
/// extent IS its block. A name whose `prior` slot exists points back at the
/// enclosing binding's slot; a name with no prior mapping is removed so the
/// next mention falls through to the storage the graph adjudicated
/// (`ModuleGlobals` for a module binding, a refusal for a name nothing binds).
fn restoreBlockDeclarations(ctx: *LowerCtx, rows: []const BlockDeclaration) void {
    for (rows) |row| {
        if (row.prior) |slot| {
            if (ctx.locals.getPtr(row.name)) |held| held.* = slot;
            continue;
        }
        if (ctx.locals.fetchRemove(row.name)) |entry| ctx.alloc.free(entry.key);
    }
}

fn lowerBlockReturns(ctx: *LowerCtx, block: *const ast.Block, allow_return: bool) Error!bool {
    const saved_answering = ctx.block_answering;
    ctx.block_answering = allow_return;
    defer ctx.block_answering = saved_answering;
    // No value-numbered fact crosses a control-flow edge: every reuse stays
    // inside straight-line code where domination is textual.
    ctx.cse.clearRetainingCapacity();
    var declarations: std.ArrayListUnmanaged(BlockDeclaration) = .empty;
    defer declarations.deinit(ctx.alloc);
    try noteBlockDeclarations(ctx, block, &declarations);
    defer restoreBlockDeclarations(ctx, declarations.items);
    for (block.stmts, 0..) |*stmt, i| {
        try pushEnclosingFrame(ctx, block, i);
        defer popEnclosingFrame(ctx);
        // A multi-statement idiom prologue (popcount) swallowed this statement;
        // its semantics were discharged up front.
        if (ctx.popcount_swallowed.contains(stmt)) continue;
        if (ctx.satadd_swallowed.contains(stmt)) continue;
        if (ctx.bitrev_swallowed.contains(stmt)) continue;
        if (ctx.loopselect_swallowed.contains(stmt)) continue;
        if (ctx.zerotrip_swallowed.contains(stmt)) continue;
        const tail_here = allow_return and stmtIsTailSlot(block, i);
        if (stmt.* == .ret) {
            try lowerStmt(ctx, stmt, tail_here);
            return true;
        }
        // A fired additive prologue claims the statement: the counted-loop
        // arming is excluded so an armed reduction cannot re-run a loop the
        // prologue already finalized (its trip test is false on entry).
        const claimed = try runAdditivePrologues(ctx, block.stmts, i);
        if (!claimed) tryArmCountedLoop(ctx, block.stmts, i);
        // The prologue may have swallowed this statement itself (popcount
        // discharges all six up front; bitrev/loopselect swallow the loop they
        // replace); do not lower it twice.
        if (ctx.popcount_swallowed.contains(stmt)) continue;
        if (ctx.satadd_swallowed.contains(stmt)) continue;
        if (ctx.bitrev_swallowed.contains(stmt)) continue;
        if (ctx.loopselect_swallowed.contains(stmt)) continue;
        if (ctx.zerotrip_swallowed.contains(stmt)) continue;
        // A provably-redundant `x = x & INT64_MAX` mask is skipped, not emitted.
        if (try trySkipInt64MaxMask(ctx, block.stmts, i, tail_here)) continue;
        try lowerStmt(ctx, stmt, tail_here);
    }
    if (allow_return) return try tryEmitTailDemandReturn(ctx, block);

    // The enclosing block demands an answer even though this arm was not
    // admitted as its syntactic return slot.  The tail operand is therefore
    // the function answer when this arm is selected.  Lowering it and throwing
    // the operand away preserved only its effects; the join then observed the
    // other arm's value (or zero).  Carry the existing answer fact to the
    // function boundary and tell the branch builder this arm terminated.
    if (saved_answering) {
        if (block.tail_expr) |tail| {
            if (tail.* != .table and !effect(tail)) {
                const ret_ty: RT = if (exprIsF64(ctx, tail))
                    .f64
                else if (exprIsPointer(ctx, tail))
                    physical_pointer
                else
                    .any;
                try ctx.emit(.{ .op = .ret, .lhs = try lowerExprCons(ctx, tail, .single), .ty = ret_ty });
                return true;
            }
        }
    }

    try lowerBlockTailEffect(ctx, block);
    return false;
}

/// gap[104] — a block's tail expression whose value NOBODY DEMANDS is a
/// STATEMENT, and it has to be lowered like one.
///
/// `blk.tail_expr` is the parser's home for a final expression, and the ONLY
/// thing that ever lowered it was `tryEmitTailDemandReturn`, which the two
/// callers here reach exclusively under `allow_return`. A branch body or a loop
/// body is lowered with `allow_return = false` — correctly, since neither is
/// the function's answer — so its tail expression was walked past by the
/// statement loop (it is not in `block.stmts`) and then never lowered at all.
/// Two paths, each right on its own, with the tail expression falling between:
///
///     if 42 > 10
///         print("first")   -- a statement; emitted
///         print("last")    -- the tail expression; SILENTLY DROPPED
///     end
///
///     while n < 3
///         n += 1           -- a statement; emitted
///         print("b")       -- the tail expression; SILENTLY DROPPED
///     end
///
/// Both printed nothing where the C backend printed. This is not about `print`,
/// not about constant conditions and not about branching: the branch is taken
/// (`if 42 > 10 return 7` answers 7 on both backends) and the loop iterates the
/// right number of times. Only the tail slot of a non-answering block is lost.
/// A tail ASSIGNMENT was always fine because an assignment is a `stmt`, so it
/// rides the loop above — which is exactly why the defect looked like it was
/// about void calls.
///
/// The C backend is the oracle and already states the rule: its `.statement`
/// tail mode emits `expr;` for the same position. `.discard` consumption is the
/// DNIR spelling of that semicolon.
///
/// `.table` is skipped for the reason `lowerStmt`'s `.expr_stmt` arm skips it —
/// `lowerExprCons` has no `.table` arm, so lowering one fails the whole
/// function. A bare table in a discarded position carries no effect, so
/// dropping it is the right answer rather than a second hole.
fn lowerBlockTailEffect(ctx: *LowerCtx, block: *const ast.Block) Error!void {
    const e = block.tail_expr orelse return;
    if (e.* == .table) return;
    _ = try lowerExprCons(ctx, e, exprCallConsumption(e));
}

/// gap[104] at the ANSWERING end of a block — the third home of the same hole.
///
/// `blockTailResult` treats a void-shaped tail call as transparent and walks
/// BACK to the preceding statement for the block's value, which is right: a
/// file ending in `print(…)` still answers with whatever it computed. But the
/// resolution it hands back then names that EARLIER statement, and both
/// consumers used it as the whole answer — so the tail expression itself,
/// which is not in `block.stmts` and is no longer the resolved result, was
/// lowered by nobody:
///
///     a = 64
///     print("{a}")
///
/// compiled, exited 64, and printed NOTHING, where the C oracle printed 64 and
/// exited 0. Every shape in `examples/table/` is this: a binding, then a tail
/// `print`. It stayed invisible while `print` refused outside gate transport —
/// a refusal cannot answer wrong — and became a SILENT WRONG ANSWER the moment
/// egress compiled everywhere.
///
/// `lowerBlockTailEffect` already states the rule for a non-answering block.
/// This is the same rule where the block does answer: the anchored value is the
/// result, and the tail expression is a discarded statement that still runs.
fn tailAnchoredAway(block: *const ast.Block, r: tail_result_demand.Resolution) bool {
    const tail = block.tail_expr orelse return false;
    return tail != r.expr;
}

/// Whether statement `i` occupies the slot the block's result comes out of.
///
/// `allow_return` means "this block's value is the function's answer", and it
/// was handed to EVERY statement in the block rather than only the last one.
/// The `.if_stmt` arm passes it straight into each branch body, so a branch
/// whose last statement is an assignment had that assignment rewritten into a
/// `return` by `tryEmitTailDemandReturn` — correct when the `if` really is the
/// block's tail, a miscompile when anything follows it:
///
///     r: i64 = 0
///     if r == 0
///         r = 5        -- lowered to `mov x0, #5 ; ret`
///     end
///     r += 100      -- unreachable
///     print(r)         -- unreachable
///
/// printed nothing and returned 5, where the C backend printed 105. The whole
/// remainder of the enclosing block was dead code behind a `ret` that the
/// branch had no business emitting. `while_loop` already forced `false` here
/// for the same reason, with the same comment; the `if` arm needed the rule
/// too, but conditionally, because an `if` CAN be a block's tail.
///
/// A trailing `tail_expr` is by definition the last thing in the block, so when
/// one is present NO statement is the tail slot — the branches join and the
/// tail expression is what returns.
fn stmtIsTailSlot(block: *const ast.Block, i: usize) bool {
    if (block.tail_expr != null) return false;
    return i + 1 == block.stmts.len;
}

/// A branch is a value guard when its tail is an explicit value-carrying
/// expression — `if n < 2 \n n`, `if x < 0 \n -x`. Taking such a branch is a
/// function exit whose value is the answer, even when the `if` is not the
/// block's syntactic tail (a guard clause preceding the fall-through result).
///
/// This is deliberately narrow. A branch whose tail is a trailing ASSIGNMENT
/// (`if r == 0 \n r = 5`) or a void-shaped effect (`if c \n print(" ")`) is NOT
/// a guard: it must fall through so the rest of the enclosing block still runs
/// (see the miscompiles catalogued at `stmtIsTailSlot`). Only an explicit
/// `tail_expr` that carries a value qualifies; an assignment lives in
/// `block.stmts` and has no `tail_expr`.
fn branchIsValueGuard(block: *const ast.Block) bool {
    const e = block.tail_expr orelse return false;
    return !tail_result_demand.isVoidShapedCall(e);
}

/// THE TRUTH OF A CONDITION WHOSE OPERANDS ARE BOTH LITERAL, or null.
///
/// gap[213] measured what its absence costs: `if 3 > 100` emitted `mov x9,#3`,
/// `mov x12,#0x64`, `cmp`, `csel` AND the dead arm's arithmetic -- eleven
/// instructions for a relation whose answer is `mov x0, #0`. The live twin
/// `if 3 < 100` was also eleven, differing only in the condition code. That is
/// not an if-conversion gap; the `csel` shows if-conversion already fires. It
/// is that NOTHING ANSWERED "this condition is constant" where realization
/// could read it.
///
/// Comparisons only. An integer is not a truth value in this language and a
/// non-comparison operand is not decided here -- `null` means "not known
/// constant", never "false", so the caller emits both arms exactly as before.
/// THE VALUE OF AN INTEGER EXPRESSION BUILT ONLY FROM LITERALS, or null.
///
/// NO NAME IS RESOLVED HERE, and that is the whole boundary. `ctx.const_ints`
/// would answer for a name, and `literalBindingOf`'s doc comment already
/// records why reading it is a wrong answer: the map "records a name's last
/// literal binding and is never invalidated by a non-literal reassignment, so
/// after `i = 1 ; i = i + 5` it still answers 1". gap[209] is that same
/// producer defect measured end to end. A condition folded from a stale name
/// would pick the wrong arm and still compile, so names are refused until the
/// producer is exact.
///
/// Division and remainder admit a literal non-zero divisor only; `sdiv` not
/// faulting today is a reason to exclude a zero divisor, not to allow it.
fn constIntValue(graph: *const semantic_graph.SemanticGraph, e: *const ast.Expr) ?i64 {
    // THE GRAPH FIRST, and it is not a stylistic preference. `exactI64OfExpr`
    // answers for three shapes this walk cannot reach at all:
    //
    //   * an integer literal -- which this walk DID answer, by re-parsing it.
    //     That re-parse is `gate/coverage.sh`'s `exact.i64` rival authority,
    //     and asking the graph is how it stops being one here.
    //   * `xs[1]` against a constant aggregate, whose selected member content
    //     the graph publishes at the access. `intLiteralStep` returns null for
    //     an `.index` node and always did.
    //   * a foreign module's `.field` constant, published by
    //     `liftForeignConstantFieldSites`. `intLiteralStep` returns null for a
    //     `.field` node too.
    //
    // So this is a widening, not a swap: conditions that were undecidable
    // become decidable because a producer now reaches them.
    //
    // STILL NO NAME IS RESOLVED HERE. gap[209] is fixed, but its fix made
    // `ModuleConsts` refuse an overwritten name rather than making the GRAPH
    // own module-binding value identity -- there is no edge from a module
    // binding to the value entity its initializer became, so the graph cannot
    // answer for `ring` and this must not pretend otherwise.
    //
    // THE AST RE-PARSE IS GONE FROM THIS SITE. `if (ast.intLiteralValue(e)) |v|
    // return v;` stood here as a fallback; with `exact_i64` reaching 98.4% of
    // the corpus's integer literal tokens it is a rival authority that answers
    // for the same shapes the graph already owns. Whether the remaining 1.6%
    // costs a fold anywhere is a MEASUREMENT, not an argument -- see the
    // corpus differential.
    if (graph.exactI64OfExpr(e)) |v| return v;
    switch (e.*) {
        .unop => |u| {
            const v = constIntValue(graph, u.operand) orelse return null;
            return switch (u.op) {
                .neg => std.math.negate(v) catch null,
                .bnot => ~v,
                else => null,
            };
        },
        .binop => |b| {
            const l = constIntValue(graph, b.lhs) orelse return null;
            const r = constIntValue(graph, b.rhs) orelse return null;
            return switch (b.op) {
                .add => l +% r,
                .sub => l -% r,
                .mul => l *% r,
                .band => l & r,
                .bor => l | r,
                .bxor => l ^ r,
                .lshift => if (r >= 0 and r < 64) l << @intCast(r) else null,
                .rshift => if (r >= 0 and r < 64) l >> @intCast(r) else null,
                // `@divFloor(INT_MIN, -1)` and `@mod(INT_MIN, -1)` overflow
                // the host and abort the compiler. A trap is not a value —
                // `comptime.zig` already refuses this pair for exactly that
                // reason, and this fold had only the divide-by-zero half.
                .idiv, .div => if (r == 0 or (r == -1 and l == std.math.minInt(i64)))
                    null
                else
                    @divFloor(l, r),
                .mod => if (r == 0 or (r == -1 and l == std.math.minInt(i64)))
                    null
                else
                    @mod(l, r),
                else => null,
            };
        },
        else => return null,
    }
}

/// Try to fold an expression to an integer via the callable summary cache.
/// Returns null if the expression is not a summary-foldable call.
fn summaryConstInt(ctx: *LowerCtx, e: *const ast.Expr) ?i64 {
    const cache = ctx.summary_cache orelse return null;
    const caller = ctx.function orelse return null;
    if (e.* != .call) return null;
    const k = summary.foldCallSite(cache, ctx.graph, caller, e) orelse return null;
    // Record the folded application so the realization validator does not
    // expect it to be materialized. Mirrors the hook in lowerExprCons.
    var folded: std.ArrayListUnmanaged(semantic_graph.id) = .empty;
    defer folded.deinit(ctx.alloc);
    collectFoldedCallApplications(ctx, e, &folded);
    for (folded.items) |app_id| {
        recordSummaryFolded(ctx, app_id);
    }
    return k;
}

fn constConditionTruth(ctx: *LowerCtx, cond: *const ast.Expr) ?bool {
    if (cond.* != .binop) return null;
    const b = cond.binop;
    const lhs = constIntValue(ctx.graph, b.lhs) orelse summaryConstInt(ctx, b.lhs) orelse return null;
    const rhs = constIntValue(ctx.graph, b.rhs) orelse summaryConstInt(ctx, b.rhs) orelse return null;
    return switch (b.op) {
        .eq => lhs == rhs,
        .neq => lhs != rhs,
        .lt => lhs < rhs,
        .gt => lhs > rhs,
        .leq => lhs <= rhs,
        .geq => lhs >= rhs,
        else => null,
    };
}

/// THE REALIZATION ROWS A DECIDED CONDITION STILL OWES.
///
/// `constConditionTruth` answers from `exactI64OfExpr`, and one of the shapes it
/// answers for is a PUBLISHED aggregate projection. When the caller then lowers
/// only the surviving arm, those applications are realized NOWHERE, and
/// `native_backend`'s "every published application exactly once" check reads the
/// difference as a dropped call. Measured at HEAD: `if xs[2][1] > 2` was REFUSED
/// with `application-realization-count` while `n = xs[2][1] ; if n > 2` — the
/// same projection, the same knowledge — compiled. The fold was converting new
/// semantic knowledge into a refusal instead of into a win.
///
/// This walks the DECIDED condition to the occurrences the graph published and
/// realizes those only. It does not lower the comparison, so the branch and the
/// `cmp`/`cset` gap[213] removed stay removed.
///
/// SCOPE IS THE AGGREGATE PROJECTION, deliberately. Any other published
/// application inside a decided condition has exactly the accounting problem it
/// had before this existed; widening the walk to realize an ordinary call would
/// EXECUTE a call the fold had elided, which is a semantic change and not this
/// change. That case stays refused, visibly, rather than being papered over.
fn lowerFoldedConditionLineage(ctx: *LowerCtx, expr: *const Expr) Error!void {
    if (ctx.occurrences.get(expr)) |application| {
        if (ctx.graph.aggregateAccess(application.application) != null) {
            _ = try lowerAggregateAccess(ctx, application, .discard);
            return;
        }
    }
    switch (expr.*) {
        .binop => |b| {
            try lowerFoldedConditionLineage(ctx, b.lhs);
            try lowerFoldedConditionLineage(ctx, b.rhs);
        },
        .unop => |u| try lowerFoldedConditionLineage(ctx, u.operand),
        else => {},
    }
}

fn resolveIntStep(ctx: *LowerCtx, step: *const ast.Expr) Error!i64 {
    // The graph owns literal content after publication.  Re-reading an
    // integer literal here made numeric-for lowering a semantic AST backedge:
    // poisoning the tree after lift could change the physical step while the
    // published value fact remained unchanged.  Do not retain an AST fallback;
    // absence of the graph fact is an honest refusal.
    if (ctx.graph.exactI64OfExpr(step)) |v| return v;
    if (step.* == .name) {
        if (ctx.const_ints.get(step.name.ident)) |v| return v;
    }
    return bail(ctx.diagnostic, @src());
}

fn lowerNumFor(ctx: *LowerCtx, loop: anytype) Error!void {
    if (loop.var_typ != .inferred and !isIntType(loop.var_typ)) return bail(ctx.diagnostic, @src());
    const step_lit: ?i64 = if (loop.step) |step| resolveIntStep(ctx, step) catch null else 1;
    if (step_lit == null) {
        try lowerRuntimeNumFor(ctx, loop);
        return;
    }
    const step = step_lit.?;
    if (step == 0) return bail(ctx.diagnostic, @src());
    try lowerConstNumFor(ctx, loop, step);
}

fn lowerConstNumFor(ctx: *LowerCtx, loop: anytype, step_lit: i64) Error!void {
    try lowerAssignTarget(ctx, loop.var_name, loop.start);
    const i_slot = ctx.locals.get(loop.var_name) orelse return bail(ctx.diagnostic, @src());
    const head_idx: u32 = @intCast(ctx.instrs.items.len);
    const cond_temp = ctx.freshTemp();
    const cmp_op: dnir.BinOpTag = if (step_lit > 0) .leq else .geq;
    try ctx.emit(.{
        .op = .binop,
        .result = cond_temp,
        .binop = cmp_op,
        .lhs = .{ .local = i_slot },
        .rhs = try lowerExpr(ctx, loop.stop),
    });
    const fail_idx = ctx.instrs.items.len;
    try ctx.emit(.{ .op = .br, .lhs = .{ .temp = cond_temp }, .branch_target = 0, .branch_condition = .when_false });
    // Loop bodies are not implicit-tail positions — see the while_loop arm.
    _ = try lowerBlockReturns(ctx, &loop.body, false);
    const next_temp = ctx.freshTemp();
    try ctx.emit(.{
        .op = .binop,
        .result = next_temp,
        .binop = .add,
        .lhs = .{ .local = i_slot },
        .rhs = .{ .i64 = step_lit },
    });
    try ctx.emit(.{ .op = .store_local, .result = i_slot, .lhs = .{ .temp = next_temp } });
    try ctx.emit(.{ .op = .br, .branch_target = head_idx });
    const end_idx: u32 = @intCast(ctx.instrs.items.len);
    ctx.instrs.items[fail_idx].branch_target = end_idx;
}

fn lowerRuntimeNumFor(ctx: *LowerCtx, loop: anytype) Error!void {
    try lowerAssignTarget(ctx, loop.var_name, loop.start);
    const i_slot = ctx.locals.get(loop.var_name) orelse return bail(ctx.diagnostic, @src());

    const stop_key = try ctx.alloc.dupe(u8, "__dnir_stop");
    const stop_slot = ctx.freshTemp();
    try ctx.locals.put(ctx.alloc, stop_key, stop_slot);
    const stop_v = try lowerExpr(ctx, loop.stop);
    try ctx.emit(.{ .op = .store_local, .result = stop_slot, .lhs = stop_v });

    const step_key = try ctx.alloc.dupe(u8, "__dnir_step");
    const step_slot = ctx.freshTemp();
    try ctx.locals.put(ctx.alloc, step_key, step_slot);
    const step_v = if (loop.step) |step| try lowerExpr(ctx, step) else @as(dnir.Value, .{ .i64 = 1 });
    try ctx.emit(.{ .op = .store_local, .result = step_slot, .lhs = step_v });

    const head_idx: u32 = @intCast(ctx.instrs.items.len);

    const sign_temp = ctx.freshTemp();
    try ctx.emit(.{
        .op = .binop,
        .result = sign_temp,
        .binop = .lt,
        .lhs = .{ .local = step_slot },
        .rhs = .{ .i64 = 0 },
    });
    const to_pos_idx = ctx.instrs.items.len;
    try ctx.emit(.{ .op = .br, .lhs = .{ .temp = sign_temp }, .branch_target = 0, .branch_condition = .when_false });

    const neg_cond = ctx.freshTemp();
    try ctx.emit(.{
        .op = .binop,
        .result = neg_cond,
        .binop = .geq,
        .lhs = .{ .local = i_slot },
        .rhs = .{ .local = stop_slot },
    });
    const neg_fail = ctx.instrs.items.len;
    try ctx.emit(.{ .op = .br, .lhs = .{ .temp = neg_cond }, .branch_target = 0, .branch_condition = .when_false });
    const to_body_from_neg = ctx.instrs.items.len;
    try ctx.emit(.{ .op = .br, .branch_target = 0 });

    const pos_check_idx: u32 = @intCast(ctx.instrs.items.len);
    ctx.instrs.items[to_pos_idx].branch_target = pos_check_idx;

    const pos_cond = ctx.freshTemp();
    try ctx.emit(.{
        .op = .binop,
        .result = pos_cond,
        .binop = .leq,
        .lhs = .{ .local = i_slot },
        .rhs = .{ .local = stop_slot },
    });
    const pos_fail = ctx.instrs.items.len;
    try ctx.emit(.{ .op = .br, .lhs = .{ .temp = pos_cond }, .branch_target = 0, .branch_condition = .when_false });

    const body_idx: u32 = @intCast(ctx.instrs.items.len);
    ctx.instrs.items[to_body_from_neg].branch_target = body_idx;

    // Loop bodies are not implicit-tail positions — see the while_loop arm.
    _ = try lowerBlockReturns(ctx, &loop.body, false);

    const next_temp = ctx.freshTemp();
    try ctx.emit(.{
        .op = .binop,
        .result = next_temp,
        .binop = .add,
        .lhs = .{ .local = i_slot },
        .rhs = .{ .local = step_slot },
    });
    try ctx.emit(.{ .op = .store_local, .result = i_slot, .lhs = .{ .temp = next_temp } });
    try ctx.emit(.{ .op = .br, .branch_target = head_idx });

    const exit_idx: u32 = @intCast(ctx.instrs.items.len);
    ctx.instrs.items[neg_fail].branch_target = exit_idx;
    ctx.instrs.items[pos_fail].branch_target = exit_idx;
}

fn exprIsF64(ctx: *LowerCtx, expr: *const ast.Expr) bool {
    if (applicationResultIs(ctx, expr, .f64)) return true;
    return switch (expr.*) {
        .float_lit => true,
        .call => exprReturnsF64(ctx, expr),
        .method_call => |m| blk: {
            if (std.mem.eql(u8, m.method, "to") and m.args.len == 1) {
                if (m.args[0].* == .name and std.mem.eql(u8, m.args[0].name.ident, "f64")) {
                    break :blk true;
                }
            }
            if (std.mem.eql(u8, m.method, "from") and m.args.len == 1) {
                if (m.obj.* == .name and std.mem.eql(u8, m.obj.name.ident, "f64")) {
                    break :blk true;
                }
            }
            break :blk false;
        },
        // Arithmetic promotes: if either operand is f64, the result is f64.
        // Without this, `x = 0.1 + 0.2` leaves the binop unrecognized, the
        // binding never marks the slot, and a later concat prints the
        // double's bits through `%lld`. Comparisons answer bool, not f64.
        .binop => |b| switch (b.op) {
            .add, .sub, .mul, .div, .mod => exprIsF64(ctx, b.lhs) or exprIsF64(ctx, b.rhs),
            else => false,
        },
        .name => |n| blk: {
            // P0-A: the graph descriptor is consulted, not obeyed blindly.
            // Sema types `x: f32` as .f32, but the runtime never narrows
            // f32 to binary32 -- the slot census (f64_slots) is the
            // physical fact. The old `descriptor == .f64` short-circuit
            // answered "not float" for f32 names, so `x + y` took the
            // integer binop path and added double bit patterns as
            // integers: a silent wrong answer. A .f64 descriptor still
            // answers true immediately; anything else falls through to
            // the slot census.
            switch (graphNameDescriptor(ctx, expr)) {
                .known => |descriptor| if (descriptor == .f64) break :blk true,
                .unknown, .unvisited => {},
            }
            const slot = ctx.locals.get(n.ident) orelse break :blk false;
            break :blk ctx.f64_slots.contains(slot);
        },
        else => false,
    };
}

/// True for the `ptr` / `void*` annotation — the base address of a
/// memory-backed positional table.
fn typeIsPtr(t: ast.TypeExpr) bool {
    return switch (t) {
        .named => |name| std.mem.eql(u8, name, "ptr") or std.mem.eql(u8, name, "void*"),
        .pointer => true,
        else => false,
    };
}

/// The expression produces an address value. Exact pointee identity stays in
/// the graph descriptor; this predicate selects the one-register physical
/// representation and propagates it through local storage.
fn exprIsPointer(ctx: *const LowerCtx, expr: *const ast.Expr) bool {
    if (applicationResultIs(ctx, expr, .pointer)) return true;
    return switch (expr.*) {
        .name => |n| blk: {
            switch (graphNameDescriptor(ctx, expr)) {
                .known => |descriptor| break :blk descriptor == .pointer,
                .unknown, .unvisited => {},
            }
            const slot = ctx.locals.get(n.ident) orelse break :blk false;
            break :blk ctx.ptr_slots.contains(slot);
        },
        .call => |call| blk: {
            if (call.func.* != .field or call.func.field.obj.* != .name) break :blk false;
            const field = call.func.field;
            if (!std.mem.eql(u8, field.obj.name.ident, "mem")) break :blk false;
            break :blk std.mem.eql(u8, field.field, "alloc") or
                std.mem.eql(u8, field.field, "ptr_from_addr");
        },
        .if_expr => |branch| exprIsPointer(ctx, branch.then_expr) and
            exprIsPointer(ctx, branch.else_expr),
        else => false,
    };
}

/// True when `name` binds a positional table — either already memory-backed, or
/// register-exploded with a recorded length.
fn nameIsPositionalTable(ctx: *LowerCtx, name: []const u8) bool {
    if (ctx.locals.get(name)) |s| {
        if (ctx.ptr_slots.contains(s)) return true;
    }
    var buf: [256]u8 = undefined;
    const len_key = std.fmt.bufPrint(&buf, "{s}.len", .{name}) catch return false;
    const len_slot = ctx.locals.get(len_key) orelse return false;
    return ctx.table_lens.contains(len_slot);
}

/// True when any positional table bound anywhere in `stmts` is wider than the
/// select chain serves.
///
/// One table crossing the threshold decides the representation for EVERY table
/// in the function, because the two representations must not be mixed. A loop
/// that both loads from a memory-backed table and stores into a select-chain
/// one reads a stale index — `x = w(i) ; r(i) = x` kept yielding `w(1)`. That
/// is a real backend defect independent of this pass, but it was unreachable
/// while wide tables simply refused to compile, and making them compile is what
/// exposed it. Choosing one representation per function keeps this change to
/// what it is meant to be: strictly more programs accepted, none altered.
fn stmtsBindWideTable(stmts: []const ast.Stmt) bool {
    for (stmts) |st| {
        const wide = switch (st) {
            .local_decl => |d| exprsBindWideTable(d.inits),
            .global_decl => |d| exprsBindWideTable(d.inits),
            .const_decl => |d| exprIsWideTable(d.val),
            .assign => |a| exprsBindWideTable(a.values),
            .do_block => |b| stmtsBindWideTable(b.body.stmts),
            .while_loop => |w| stmtsBindWideTable(w.body.stmts),
            .repeat_loop => |r| stmtsBindWideTable(r.body.stmts),
            .num_for => |f| stmtsBindWideTable(f.body.stmts),
            .gen_for => |f| stmtsBindWideTable(f.body.stmts),
            .if_stmt => |f| blk: {
                if (stmtsBindWideTable(f.then.stmts)) break :blk true;
                for (f.elseifs) |ei| if (stmtsBindWideTable(ei.body.stmts)) break :blk true;
                break :blk if (f.else_body) |eb| stmtsBindWideTable(eb.stmts) else false;
            },
            else => false,
        };
        if (wide) return true;
    }
    return false;
}

fn exprsBindWideTable(exprs: []const *ast.Expr) bool {
    for (exprs) |e| if (exprIsWideTable(e)) return true;
    return false;
}

// ---------------------------------------------------------------------------
// THE FACT THAT DECIDES A TABLE'S REPRESENTATION IS INDEX CONSTANCY, NOT WIDTH.
//
// A select chain answers `t(i)` with one compare-and-select PER ELEMENT. For a
// compile-time index that is free — the chain collapses to the element's own
// slot, or to the literal. For a RUNTIME index it is a LINEAR SCAN, O(width) on
// every single access, and it is the dominant cost of this whole project:
// profiled on `native.out`, 62,587,868 of 94,458,056 executed instructions —
// 66.3% — are array subscripts lowered to if-chains. One subscript into a
// 16-element array costs exactly 60 instructions; into an 8-element array,
// exactly 29. Memory costs one scaled load, at any width.
//
// So the ordering INVERTS with index constancy, which is why a width threshold
// could never be tuned into the right answer:
//
//                        constant index      runtime index
//     select chain              2 instrs      O(width) — 305 at width 32
//     frame memory            174 instrs      O(1)     — 206 at width 33
//
// The decision, in the order it is taken:
//
//   1. DETERMINED and read only at compile-time indices -> no table at all
//      (`noteConstTable`); the value is the answer, at any extent.
//   2. Read or written at a RUNTIME index -> frame memory, AT ANY WIDTH. This
//      function.
//   3. Wider than the register file can hold -> frame memory. `select_chain_max`
//      survives ONLY as this feasibility bound; it no longer selects a strategy.
//   4. Otherwise -> one slot per element.
//
// Uniform per function, as before: mixing the two representations inside one
// relation is what made `x = w(i) ; r(i) = x` read a stale index.
// ---------------------------------------------------------------------------

const max_tracked_tables = 64;

/// Names bound to a positional table literal in the function being lowered.
/// Overflow answers "assume everything", which costs speed and never an answer.
const TableNames = struct {
    names: [max_tracked_tables][]const u8 = undefined,
    len: usize = 0,
    overflow: bool = false,

    fn add(self: *TableNames, n: []const u8) void {
        if (self.has(n)) return;
        if (self.len == max_tracked_tables) {
            self.overflow = true;
            return;
        }
        self.names[self.len] = n;
        self.len += 1;
    }

    fn has(self: *const TableNames, n: []const u8) bool {
        if (self.overflow) return true;
        for (self.names[0..self.len]) |e| if (std.mem.eql(u8, e, n)) return true;
        return false;
    }
};

fn collectTableNamesExpr(name: []const u8, init: *const ast.Expr, out: *TableNames) void {
    if (init.* == .table and tableIsPositional(init)) out.add(name);
}

fn collectTableNames(stmts: []const ast.Stmt, out: *TableNames) void {
    for (stmts) |st| switch (st) {
        .local_decl => |d| for (d.names, 0..) |n, i| {
            if (i < d.inits.len) collectTableNamesExpr(n.ident, d.inits[i], out);
        },
        .global_decl => |d| for (d.names, 0..) |n, i| {
            if (i < d.inits.len) collectTableNamesExpr(n.ident, d.inits[i], out);
        },
        .const_decl => |d| collectTableNamesExpr(d.ident, d.val, out),
        .assign => |a| for (a.targets, 0..) |t, i| {
            if (t.* == .name and i < a.values.len) collectTableNamesExpr(t.name.ident, a.values[i], out);
        },
        .do_block => |b| collectTableNames(b.body.stmts, out),
        .while_loop => |w| collectTableNames(w.body.stmts, out),
        .repeat_loop => |r| collectTableNames(r.body.stmts, out),
        .num_for => |f| collectTableNames(f.body.stmts, out),
        .gen_for => |f| collectTableNames(f.body.stmts, out),
        .if_stmt => |f| {
            collectTableNames(f.then.stmts, out);
            for (f.elseifs) |ei| collectTableNames(ei.body.stmts, out);
            if (f.else_body) |eb| collectTableNames(eb.stmts, out);
        },
        else => {},
    };
}

/// `t(k)` on a tracked table with `k` not a compile-time literal.
fn exprRuntimeIndexes(expr: *const ast.Expr, tables: *const TableNames) bool {
    return switch (expr.*) {
        .index => |ix| blk: {
            if (ix.obj.* == .name and tables.has(ix.obj.name.ident) and
                ast.intLiteralValue(ix.key) == null) break :blk true;
            break :blk exprRuntimeIndexes(ix.obj, tables) or exprRuntimeIndexes(ix.key, tables);
        },
        .field => |f| exprRuntimeIndexes(f.obj, tables),
        .call => |c| blk: {
            if (exprRuntimeIndexes(c.func, tables)) break :blk true;
            for (c.args) |a| if (exprRuntimeIndexes(a, tables)) break :blk true;
            break :blk false;
        },
        .method_call => |m| blk: {
            if (exprRuntimeIndexes(m.obj, tables)) break :blk true;
            for (m.args) |a| if (exprRuntimeIndexes(a, tables)) break :blk true;
            break :blk false;
        },
        .binop => |b| exprRuntimeIndexes(b.lhs, tables) or exprRuntimeIndexes(b.rhs, tables),
        .unop => |u| exprRuntimeIndexes(u.operand, tables),
        .try_expr => |x| exprRuntimeIndexes(x.operand, tables),
        .unwrap_expr => |x| exprRuntimeIndexes(x.operand, tables),
        .await_expr => |x| exprRuntimeIndexes(x.operand, tables),
        .contains_expr => |c| exprRuntimeIndexes(c.lhs, tables) or exprRuntimeIndexes(c.rhs, tables),
        .if_expr => |ie| exprRuntimeIndexes(ie.cond, tables) or
            exprRuntimeIndexes(ie.then_expr, tables) or exprRuntimeIndexes(ie.else_expr, tables),
        .sequence => |s| blk: {
            for (s.exprs) |e| if (exprRuntimeIndexes(e, tables)) break :blk true;
            break :blk false;
        },
        .range => |r| exprRuntimeIndexes(r.start, tables) or exprRuntimeIndexes(r.end, tables) or
            (if (r.step) |st| exprRuntimeIndexes(st, tables) else false),
        .macro_call => |mc| blk: {
            for (mc.args) |a| if (exprRuntimeIndexes(a, tables)) break :blk true;
            break :blk false;
        },
        .table => |t| blk: {
            for (t.fields) |fld| {
                const hit = switch (fld) {
                    .positional => |v| exprRuntimeIndexes(v, tables),
                    .named => |nf| exprRuntimeIndexes(nf.val, tables),
                    .semantic => |sf| exprRuntimeIndexes(sf.val, tables),
                    .spread => |sp| exprRuntimeIndexes(sp, tables),
                    .indexed => |ix| exprRuntimeIndexes(ix.key, tables) or exprRuntimeIndexes(ix.val, tables),
                };
                if (hit) break :blk true;
            }
            break :blk false;
        },
        .match_expr => |m| blk: {
            if (exprRuntimeIndexes(m.scrutinee, tables)) break :blk true;
            for (m.arms) |arm| {
                if (arm.guard) |g| if (exprRuntimeIndexes(g, tables)) break :blk true;
                if (blockRuntimeIndexes(&arm.body, tables)) break :blk true;
            }
            break :blk false;
        },
        // Unmodeled shapes answer "no runtime index seen", which keeps today's
        // representation. This question only trades speed for speed — either
        // answer compiles and both are correct — so the safe default here is the
        // one that changes nothing.
        else => false,
    };
}

fn blockRuntimeIndexes(block: *const ast.Block, tables: *const TableNames) bool {
    for (block.stmts) |*s| if (stmtRuntimeIndexes(s, tables)) return true;
    if (block.tail_expr) |t| return exprRuntimeIndexes(t, tables);
    return false;
}

fn stmtRuntimeIndexes(stmt: *const ast.Stmt, tables: *const TableNames) bool {
    return switch (stmt.*) {
        .local_decl => |d| blk: {
            for (d.inits) |e| if (exprRuntimeIndexes(e, tables)) break :blk true;
            break :blk false;
        },
        .const_decl => |d| exprRuntimeIndexes(d.val, tables),
        .global_decl => |d| blk: {
            for (d.inits) |e| if (exprRuntimeIndexes(e, tables)) break :blk true;
            break :blk false;
        },
        // The STORE face counts too: `t(i) = v` with a runtime `i` is a
        // select-chain of stores, the same linear scan from the other side.
        .assign => |a| blk: {
            for (a.targets) |t| if (exprRuntimeIndexes(t, tables)) break :blk true;
            for (a.values) |e| if (exprRuntimeIndexes(e, tables)) break :blk true;
            break :blk false;
        },
        .call_stmt => |c| exprRuntimeIndexes(c.expr, tables),
        .expr_stmt => |c| exprRuntimeIndexes(c.expr, tables),
        .do_block => |d| blockRuntimeIndexes(&d.body, tables),
        .while_loop => |w| exprRuntimeIndexes(w.cond, tables) or blockRuntimeIndexes(&w.body, tables),
        .repeat_loop => |r| blockRuntimeIndexes(&r.body, tables) or exprRuntimeIndexes(r.cond, tables),
        .if_stmt => |f| blk: {
            if (f.binding) |b| if (exprRuntimeIndexes(b.expr, tables)) break :blk true;
            if (exprRuntimeIndexes(f.cond, tables)) break :blk true;
            if (blockRuntimeIndexes(&f.then, tables)) break :blk true;
            for (f.elseifs) |ei| {
                if (exprRuntimeIndexes(ei.cond, tables)) break :blk true;
                if (blockRuntimeIndexes(&ei.body, tables)) break :blk true;
            }
            if (f.else_body) |eb| if (blockRuntimeIndexes(&eb, tables)) break :blk true;
            break :blk false;
        },
        .num_for => |n| blk: {
            if (exprRuntimeIndexes(n.start, tables) or exprRuntimeIndexes(n.stop, tables)) break :blk true;
            if (n.step) |st| if (exprRuntimeIndexes(st, tables)) break :blk true;
            break :blk blockRuntimeIndexes(&n.body, tables);
        },
        .gen_for => |g| blk: {
            for (g.iters) |e| if (exprRuntimeIndexes(e, tables)) break :blk true;
            break :blk blockRuntimeIndexes(&g.body, tables);
        },
        .ret => |r| blk: {
            for (r.vals) |e| if (exprRuntimeIndexes(e, tables)) break :blk true;
            break :blk false;
        },
        else => false,
    };
}

/// The per-function representation decision. See the block comment above.
fn blockNeedsMemoryTables(body: *const ast.Block) bool {
    if (stmtsBindWideTable(body.stmts)) return true;
    var tables: TableNames = .{};
    collectTableNames(body.stmts, &tables);
    if (tables.len == 0 and !tables.overflow) return false;
    return blockRuntimeIndexes(body, &tables);
}

fn exprIsWideTable(expr: *const ast.Expr) bool {
    if (expr.* != .table) return false;
    var n: i64 = 0;
    for (expr.table.fields) |fld| {
        if (fld != .positional) return false;
        n += 1;
    }
    return n > select_chain_max;
}

/// Widest table whose variable-index access still lowers as a select chain.
///
/// A register-exploded table answers `t(i)` with one compare-and-select per
/// element, so the chain is O(len) instructions for a single access. That is a
/// win while the table is small — no memory traffic at all — and a loss once it
/// is not. Past this width both access paths materialize the table into frame
/// memory and issue one scaled load/store instead, which is also what lifts the
/// old order-8 ceiling on `rec`: nothing about the recurrence needed 8, the
/// coefficients simply had nowhere wider to live.
///
/// ONE SOURCE, NOT TWO IN AGREEMENT. This was declared here AND in
/// `table_facts.zig`, the second carrying a comment saying the two "MUST equal"
/// each other. Two declarations that must be kept equal is the shape that gave
/// this project a JIT emitting "native" while its caller compared against
/// "arm64" — nothing detects the day they stop matching. The FACT module owns
/// the decision; this pass consumes it.
///
/// Note what the threshold does and does not decide any more. It chooses how to
/// REALIZE a table that must exist. Whether one must exist at all is answered
/// before it, by `noteConstTable`, and that answer holds at every extent.
const select_chain_max: i64 = table_facts.select_chain_max;

/// The slot holding a table base address, when `expr` names one.
fn ptrSlotOf(ctx: *LowerCtx, expr: *const ast.Expr) ?u32 {
    if (expr.* != .name) return null;
    const slot = ctx.locals.get(expr.name.ident) orelse return null;
    if (!ctx.ptr_slots.contains(slot)) return null;
    return slot;
}

/// Copy a register-exploded positional table into a contiguous frame region and
/// return the slot holding its base address.
///
/// This is the bridge between the two representations. Elements stay in
/// registers for local use (which is faster and is what the existing select-chain
/// lowering depends on); memory is materialized only where a base pointer is
/// actually needed — at a call site. A table already living in memory (a `ptr`
/// param being forwarded) is passed straight through.
fn materializeTableSlots(ctx: *LowerCtx, name: []const u8) Error!u32 {
    if (ctx.locals.get(name)) |s| {
        if (ctx.ptr_slots.contains(s)) return s;
    }
    const len_key = try std.fmt.allocPrint(ctx.alloc, "{s}.len", .{name});
    defer ctx.alloc.free(len_key);
    const len_slot = ctx.locals.get(len_key) orelse return bail(ctx.diagnostic, @src());
    const len = ctx.table_lens.get(len_slot) orelse return bail(ctx.diagnostic, @src());
    if (len <= 0 or len > 4096) return bail(ctx.diagnostic, @src());

    const base = ctx.freshTemp();
    try ctx.emit(.{ .op = .alloc_slots, .result = base, .lhs = .{ .i64 = len } });
    var i: i64 = 1;
    while (i <= len) : (i += 1) {
        const elem_key = try std.fmt.allocPrint(ctx.alloc, "{s}.{d}", .{ name, i });
        defer ctx.alloc.free(elem_key);
        const elem_slot = ctx.locals.get(elem_key) orelse return bail(ctx.diagnostic, @src());
        try ctx.emit(.{
            .op = .store_index,
            .ty = .i64,
            .lhs = .{ .temp = base },
            .rhs = .{ .i64 = i },
            .third = .{ .local = elem_slot },
        });
    }
    try ctx.ptr_slots.put(ctx.alloc, base, {});
    // From here on the name *is* the memory. Rebinding it means every later
    // read, write and argument in this function goes through the same base, so a
    // callee's `t[2] = 99` is visible to the caller. Without this, each call site
    // materialized a fresh copy from the (now stale) element registers and
    // mutations were silently lost. Reads before this point are still correct:
    // materialization happens at the first call that takes the table, so nothing
    // could have mutated it yet.
    try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, name), base);
    return base;
}

// ---------------------------------------------------------------------------
// The vector beachhead: one integer reduction over a memory-backed table.
// ---------------------------------------------------------------------------

/// Marks a DNIR `hw_unary` as a VECTOR REDUCTION rather than a scalar bit
/// intrinsic. `native.zig` reads the same constant.
///
/// This rides `hw_unary` + `.field` because a vector op is not expressible in
/// `native/ir.zig`'s `Op` set and that file is not this pass's to change. The
/// convention is not invented here: `mov_arg` already discriminates its
/// variadic-tail form with `.field = "vararg"`. The tag is checked FIRST in the
/// backend's `hw_unary` arm, so `.hw` stays `.none` and every existing consumer
/// — `intrinsicOfOp`, `functionHardwareTier`, `definition` — reads exactly what
/// it read before. That also means the module's hardware tier still reports
/// `.scalar`; making it report `.vector` needs an `Op`, which is the first item
/// in "what remains".
pub const vec_reduce_add_i64_tag = "vec.reduce.add.i64";

/// One 128-bit ARM64 vector register holds two i64 lanes. Everything below is
/// written against this number rather than a literal 2, because the number is
/// the only target-specific thing in the recognizer — the FACTS it checks
/// (contiguity, element type, extent, associativity) are not.
const vec_i64_lanes: i64 = 2;

fn identOf(e: *const ast.Expr) ?[]const u8 {
    return switch (e.*) {
        .name => |n| n.ident,
        else => null,
    };
}

const IndexNames = struct { tbl: []const u8, idx: []const u8 };

/// `tbl[idx]` with both sides plain names, or null.
fn indexNames(e: *const ast.Expr) ?IndexNames {
    const ix = switch (e.*) {
        .index => |x| x,
        else => return null,
    };
    return .{
        .tbl = identOf(ix.obj) orelse return null,
        .idx = identOf(ix.key) orelse return null,
    };
}

const ReduceStep = struct { acc: []const u8, tbl: []const u8, idx: []const u8 };

/// `acc = acc + tbl[idx]` in either operand order (which is also what `+=`
/// desugars to), or null.
fn reduceStep(st: *const ast.Stmt) ?ReduceStep {
    const a = switch (st.*) {
        .assign => |x| x,
        else => return null,
    };
    if (a.targets.len != 1 or a.values.len != 1) return null;
    const acc = identOf(a.targets[0]) orelse return null;
    const b = switch (a.values[0].*) {
        .binop => |x| x,
        else => return null,
    };
    if (b.op != .add) return null;
    if (identOf(b.lhs)) |l| {
        if (std.mem.eql(u8, l, acc)) {
            if (indexNames(b.rhs)) |ix| return .{ .acc = acc, .tbl = ix.tbl, .idx = ix.idx };
        }
    }
    if (identOf(b.rhs)) |r| {
        if (std.mem.eql(u8, r, acc)) {
            if (indexNames(b.lhs)) |ix| return .{ .acc = acc, .tbl = ix.tbl, .idx = ix.idx };
        }
    }
    return null;
}

/// `idx = idx + 1` in either operand order.
///
/// The AST supplies only the operation shape and name identity. The increment
/// literal's content is the graph's exact-i64 fact; absence refuses the
/// specialization rather than re-reading mutable syntax.
fn stepIsIncrementOfOne(graph: *const semantic_graph.SemanticGraph, st: *const ast.Stmt, idx: []const u8) bool {
    const a = switch (st.*) {
        .assign => |x| x,
        else => return false,
    };
    if (a.targets.len != 1 or a.values.len != 1) return false;
    const t = identOf(a.targets[0]) orelse return false;
    if (!std.mem.eql(u8, t, idx)) return false;
    const b = switch (a.values[0].*) {
        .binop => |x| x,
        else => return false,
    };
    if (b.op != .add) return false;
    if (identOf(b.lhs)) |l| {
        if (std.mem.eql(u8, l, idx) and graph.exactI64OfExpr(b.rhs) == @as(?i64, 1)) return true;
    }
    if (identOf(b.rhs)) |r| {
        if (std.mem.eql(u8, r, idx) and graph.exactI64OfExpr(b.lhs) == @as(?i64, 1)) return true;
    }
    return false;
}

/// Inclusive last index of `while idx <= N` / `while idx < N`, or null.
///
/// The graph owns literal content after publication. The condition's AST is
/// retained only for its shape (left operand and comparison operator); the
/// bound value must come from the exact-i64 fact for the right-hand occurrence.
fn loopUpperBound(graph: *const semantic_graph.SemanticGraph, cond: *const ast.Expr, idx: []const u8) ?i64 {
    const b = switch (cond.*) {
        .binop => |x| x,
        else => return null,
    };
    const l = identOf(b.lhs) orelse return null;
    if (!std.mem.eql(u8, l, idx)) return null;
    const n = graph.exactI64OfExpr(b.rhs) orelse return null;
    return switch (b.op) {
        .leq => n,
        .lt => n - 1,
        else => null,
    };
}

// ── counted-loop reduction ───────────────────────────────────────────────────
//
// A `while` of the exact shape
//
//     iv = 0
//     while iv < bound
//         <body never reading iv>
//         iv = iv + 1
//
// with `bound` provably non-negative runs its body exactly `bound` times and
// leaves `iv == bound`. The production backend lowers it as a COUNTDOWN — one
// register, no per-iteration comparison against the bound:
//
//     n = bound
//     if n == 0 goto end     (cold pre-guard: the source loop runs zero times)
// head:
//     <body>
//     n = n - 1
//     if n != 0 goto head
// end:
//     iv = bound
//
// The trailing `iv = bound` preserves the source loop's exit state, which the
// promotion write-back in the shared exit then carries to the module.
//
// LEGALITY is established before anything is emitted:
//   - the induction variable starts at exactly 0 in the immediately preceding
//     statement (`literalBindingOf` reads that statement, never `ctx.const_ints`,
//     which is stale by design);
//   - the comparison is `<` against a provably non-negative bound;
//   - the bound is a literal (the graph's exact-i64 fact) or a name whose
//     non-negativity the graph's own width transfer proves
//     (`value_range.widthOfExpr` — the derivation the range producer settles
//     its lattice with, never a second copy of it);
//   - the body's only write to the induction variable is the terminal step
//     (`unrollScanBlock` counts it; a second write declines);
//   - nothing in the body reads the induction variable (a read would observe
//     the countdown's reversed trip values);
//   - the body performs no calls and touches no storage twice
//     (`unrollExprIsCopyable`, shared with the unroller);
//   - `break`, `continue`, `return`, nested loops and tail expressions decline.
// Any doubt declines to the ordinary loop: less knowledge emits more
// instructions, never a different answer.
//
// NESTED DIRECT FORM. When the body is exactly
//
//     J = 0
//     while J < B            (B provably non-negative)
//         T = T + 1
//         J = J + 1
//     iv = iv + 1
//
// the inner loop is itself the direct form, so the whole nest folds to
// `T = T + bound * B` with no loop at all (the inner induction variable is
// written back only when the outer bound is nonzero, since its `J = 0` init
// never runs on a zero trip). Every aliasing doubt declines.

/// The plan the block prologue arms for the immediately following `while`.
/// Absorbing fixed-point early exit for a counted loop. When the loop-carried
/// state `target` reaches `value`, the body maps that state to itself exactly
/// (proven by exact evaluation, traps included), so every remaining iteration
/// is a no-op and the loop may exit at the top as soon as the state is seen.
const FixExit = struct {
    target: []const u8,
    value: i64,
};

const CountedPlan = struct {
    /// Identity with the `while` statement the prologue saw, so a plan is
    /// never consumed by a different loop.
    stmt: *const ast.Stmt,
    /// The induction variable name.
    iv: []const u8,
    /// Bound when it is a literal (proven >= 0 by the graph's exact-i64 fact).
    bound_lit: ?i64,
    /// Bound when it is a name (proven non-negative by the width transfer).
    bound_name: ?[]const u8,
    /// Accumulator name for the direct form, settled at arm time: the body is
    /// the exact two increments and both slots are plain integers. Null when
    /// the direct form must not fire. Settled here because promotion installs
    /// fresh unmarked slots before emission, so the markings are intact now.
    direct_acc: ?[]const u8,
    /// Nested direct form, settled at arm time: the body is exactly
    /// `J = 0; while J < B { T = T + 1; J = J + 1 }; iv = iv + 1` with the
    /// inner loop's own direct form proven, so the nest folds to
    /// `T = T + bound * B`. Null when the shape does not match. Settled here
    /// because promotion installs fresh unmarked slots before emission, so
    /// the markings are intact now.
    nested_direct: ?NestedDirect = null,
    /// Nested triangular closed form, settled at arm time: the outer
    /// body's inner `while J < M` folds per outer iteration to
    /// `T = K*tri(M)` and the outer accumulation to
    /// `acc = acc + C*tri(M)*tri(N)`. Armed only when `direct_acc` and
    /// `nested_direct` both declined. Null otherwise.
    nested_triangular: ?NestedTriangular = null,
    /// Self-map deletion, settled at arm time: the body is straight-line pure
    /// integer dataflow that reproduces the loop-entry state (proven by exact
    /// evaluation), so the loop is dead and the induction variable is bound
    /// to the trip count with no loop emitted. False unless proven.
    self_map: bool = false,
    /// K-step convergence state, settled at arm time alongside `self_map`:
    /// the exact fixed-point state the proof reached (equal to the entry
    /// constants when the body is a one-step self-map). The emitter rebinds
    /// surviving names to these constants; a name whose fixed point equals
    /// its entry constant needs no store. Null unless `self_map` was proven.
    self_map_env: ?SelfMapEnv = null,
    /// Absorbing fixed-point early exit, settled at arm time: the body is
    /// straight-line pure integer dataflow with a proven absorbing state
    /// `target == value`, so the loop may exit at the top as soon as that
    /// state is observed. The induction variable is written back to the bound
    /// on the early path, preserving the full trip count's post-loop state.
    /// Null unless proven. Only armed for literal bounds, so the trip count
    /// cannot change under the loop. Moot when `self_map` deleted the loop.
    fix_exit: ?FixExit = null,
};

/// The direct form's accumulator, settled at ARM time. The body must be
/// exactly the two increments, and the induction variable and accumulator
/// slots must both be plain integers: the emitted form is integer arithmetic
/// on both, so a secret f64, str, bool, pointer or declared-narrow binding
/// would have its bit pattern reinterpreted. Settled here and not at emission
/// because promotion installs fresh unmarked slots before the emission site
/// runs; the markings this gate reads are only intact now.
fn directAccIfPlainInt(ctx: *LowerCtx, ws: anytype, iv: []const u8, bound_name: ?[]const u8) ?[]const u8 {
    const body_n = ws.body.stmts.len;
    if (body_n != 2 or ws.body.tail_expr != null) return null;
    const s0 = &ws.body.stmts[0];
    const s1 = &ws.body.stmts[1];
    var acc: ?[]const u8 = null;
    if (stepIsIncrementOfOne(ctx.graph, s0, iv)) {
        acc = accNameOfIncrement(s1, iv);
    } else if (stepIsIncrementOfOne(ctx.graph, s1, iv)) {
        acc = accNameOfIncrement(s0, iv);
    } else return null;
    const acc_name = acc orelse return null;
    if (std.mem.eql(u8, acc_name, iv)) return null;
    if (bound_name) |bn| if (std.mem.eql(u8, acc_name, bn)) return null;
    const iv_slot = ctx.locals.get(iv) orelse return null;
    const acc_slot = ctx.locals.get(acc_name) orelse return null;
    if (!unrollPlainIntSlot(ctx, iv_slot)) return null;
    if (!unrollPlainIntSlot(ctx, acc_slot)) return null;
    return acc_name;
}

/// The nested direct form's armed parts, settled at arm time: the outer
/// counted loop's body is exactly
///
///     J = 0
///     while J < B
///         T = T + 1
///         J = J + 1
///     iv = iv + 1
///
/// with the inner loop's own direct form proven (B provably non-negative,
/// the exact two increments, plain-integer slots). The nest then folds to
/// `T = T + bound * B` with no loop at all. Two's-complement add and mul
/// wrap, so regrouping `T + B + ... + B` (bound times) into `T + bound * B`
/// is exact. Null when the shape does not match.
const NestedDirect = struct {
    /// Identity with the inner `while` statement, so the plan is never
    /// consumed by a different loop.
    inner_stmt: *const ast.Stmt,
    /// The inner loop's induction variable; `J = 0` precedes it in the body.
    inner_iv: []const u8,
    /// Inner bound when it is a literal (proven >= 0 by the exact-i64 fact).
    inner_bound_lit: ?i64,
    /// Inner bound when it is a name (proven non-negative by the width transfer).
    inner_bound_name: ?[]const u8,
    /// The inner loop's accumulator (`T = T + 1`), settled at arm time.
    acc: []const u8,
};

/// Plain-integer gate for a nested-direct name at the OUTER loop's arm time.
/// The outer loop's own promotion has not run yet, so the name may not be in
/// `ctx.locals` at all. A module global proves its type through the
/// module-global type column (the same `.i64` gate promotion itself uses); a
/// name already in `ctx.locals` (a true local, or an enclosing loop's shadow,
/// itself `.i64`-gated) uses the intact slot markings; a name bound nowhere
/// yet is first bound by the inner `J = 0` literal the shape match verified,
/// so the source rebinds it to integer 0 on every taken path and the integer
/// write-back is sound (its slot is materialized at emission).
fn nestedPlainInt(ctx: *LowerCtx, name: []const u8) bool {
    if (ctx.module_globals.types.get(name)) |ty| return ty == .i64;
    if (ctx.locals.get(name)) |slot| return unrollPlainIntSlot(ctx, slot);
    return true;
}

/// The inner loop's accumulator for the nested direct form, settled at the
/// OUTER loop's arm time. Same shape proof as `directAccIfPlainInt` -- exactly
/// the two increments, one stepping the inner iv -- but the plain-integer
/// gate goes through `nestedPlainInt`: the outer loop's own promotion has not
/// run yet, so the inner names may not be in `ctx.locals`. The accumulator
/// must additionally be distinct from the outer induction variable and the
/// outer bound (the fold reads the outer bound once, after the nest).
fn nestedDirectAcc(
    ctx: *LowerCtx,
    ws: anytype,
    iv: []const u8,
    inner_bound_name: ?[]const u8,
    outer_iv: []const u8,
    outer_bound_name: ?[]const u8,
) ?[]const u8 {
    const body_n = ws.body.stmts.len;
    if (body_n != 2 or ws.body.tail_expr != null) return null;
    const s0 = &ws.body.stmts[0];
    const s1 = &ws.body.stmts[1];
    var acc: ?[]const u8 = null;
    if (stepIsIncrementOfOne(ctx.graph, s0, iv)) {
        acc = accNameOfIncrement(s1, iv);
    } else if (stepIsIncrementOfOne(ctx.graph, s1, iv)) {
        acc = accNameOfIncrement(s0, iv);
    } else return null;
    const acc_name = acc orelse return null;
    if (std.mem.eql(u8, acc_name, iv)) return null;
    if (std.mem.eql(u8, acc_name, outer_iv)) return null;
    if (inner_bound_name) |bn| if (std.mem.eql(u8, acc_name, bn)) return null;
    if (outer_bound_name) |bn| if (std.mem.eql(u8, acc_name, bn)) return null;
    if (!nestedPlainInt(ctx, iv)) return null;
    if (!nestedPlainInt(ctx, acc_name)) return null;
    return acc_name;
}

/// Arm-time recognition of the nested direct form. `ws` is the outer `while`
/// whose plan is being armed; the checks mirror the inner loop's own direct
/// form (which is bypassed: the inner loop is never lowered). Every aliasing
/// doubt declines: the inner bound must touch neither induction variable (a
/// stale read, or a trip count that varies per outer iteration), the outer
/// bound must not be the inner iv (the body's `J = 0` would make the trip
/// count dynamic), and the accumulator must be distinct from both induction
/// variables and both bounds.
fn nestedDirectParts(ctx: *LowerCtx, stmts: []const ast.Stmt, at: usize, ws: anytype, iv: []const u8, bound_name: ?[]const u8) ?NestedDirect {
    const body = ws.body.stmts;
    if (body.len != 3 or ws.body.tail_expr != null) return null;
    // body[2] steps the outer iv: the caller verified that before this runs.
    const s1 = &body[1];
    const s_while = switch (s1.*) {
        .while_loop => |w| w,
        else => return null,
    };
    const b2 = switch (s_while.cond.*) {
        .binop => |x| x,
        else => return null,
    };
    if (b2.op != .lt) return null;
    const j = identOf(b2.lhs) orelse return null;
    if (std.mem.eql(u8, j, iv)) return null;
    // The inner induction variable starts at exactly 0 in the body's first
    // statement. The emission skips that init, so the value read for the
    // inner bound must not be either induction variable.
    if (literalBindingOf(ctx.graph, &body[0], j) != @as(?i64, 0)) return null;
    var inner_lit: ?i64 = null;
    var inner_name: ?[]const u8 = null;
    if (ctx.graph.exactI64OfExpr(b2.rhs)) |n2| {
        if (n2 < 0) return null;
        inner_lit = n2;
    } else {
        const bn2 = identOf(b2.rhs) orelse return null;
        if (std.mem.eql(u8, bn2, j)) return null;
        if (std.mem.eql(u8, bn2, iv)) return null;
        if (!countedBoundNonNeg(ctx, stmts, at, bn2)) return null;
        inner_name = bn2;
    }
    if (bound_name) |bn| {
        if (std.mem.eql(u8, bn, j)) return null;
        if (std.mem.eql(u8, bn, iv)) return null;
    }
    // The inner loop's own direct form, settled at arm time when the slot
    // markings are intact: exactly the two increments, plain-integer slots,
    // accumulator distinct from the inner iv and the inner bound.
    // nestedDirectAcc already enforced acc distinct from the outer iv and the
    // outer bound; the remaining alias doubts are settled above.
    const acc = nestedDirectAcc(ctx, s_while, j, inner_name, iv, bound_name) orelse return null;
    return .{
        .inner_stmt = s1,
        .inner_iv = j,
        .inner_bound_lit = inner_lit,
        .inner_bound_name = inner_name,
        .acc = acc,
    };
}


/// The nested triangular form's armed parts, settled at arm time: the outer
/// counted loop's body is exactly
///
///     T = 0
///     J = 0
///     while J < M            (M a literal >= 0)
///         T = T + J * K      (K = iv, or c*iv / iv*c with c a literal or
///         J = J + 1           an outer-loop-invariant name)
///     acc = acc + T
///     iv = iv + 1
///
/// with the outer bound N a literal >= 0. Per outer iteration the inner loop
/// folds to T = K * tri(M); substituting K = c*iv and summing the outer
/// iterations gives acc = acc + c * tri(M) * tri(N) with no loop at all.
/// tri(k) = k*(k-1)/2 is evaluated with wrapping arithmetic as (k/2)*(k-1)
/// for even k and k*((k-1)/2) for odd k; both divisions are exact, so the
/// wrapped result is the exact triangular number mod 2^64, matching the
/// iterated wrapping sum. Null when the shape does not match.
const NestedTriangular = struct {
    /// Identity with the inner `while` statement, so the plan is never
    /// consumed by a different loop.
    inner_stmt: *const ast.Stmt,
    /// The inner loop's induction variable (`J = 0` precedes it in the body).
    inner_iv: []const u8,
    /// The inner loop's accumulator (reset to 0 each outer iteration).
    inner_acc: []const u8,
    /// Inner bound literal M (>= 0, proven by the exact-i64 fact).
    inner_bound_lit: i64,
    /// The outer accumulator (`acc = acc + T`).
    outer_acc: []const u8,
    /// K = k_lit * iv (1 when K is the bare iv). Null when k_name applies.
    k_lit: ?i64,
    /// K = k_name * iv with k_name outer-loop-invariant. Null when k_lit.
    k_name: ?[]const u8,
    /// tri(M) mod 2^64, exact.
    tri_m: i64,
    /// tri(N) mod 2^64, exact.
    tri_n: i64,
};

/// tri(n) = n*(n-1)/2 mod 2^64, exact for every n >= 0. n*(n-1) is always
/// even; halving the even factor first keeps the division exact, so the
/// wrapping product is the exact triangular number mod 2^64.
fn triNum(n: i64) i64 {
    if (@rem(n, 2) == 0) return @divExact(n, 2) *% (n - 1);
    return n *% @divExact(n - 1, 2);
}

/// The K factor of a `T = T + J * K` addend.
const TriangularK = struct {
    /// K = lit * iv (1 when K is the bare iv). Null when name applies.
    lit: ?i64,
    /// K = name * iv. Null when lit applies.
    name: ?[]const u8,
};

/// The K factor of the `J * K` addend: K is the bare outer iv, or c*iv /
/// iv*c with c a literal or a name. Anything else (K mentioning J, K = iv*iv,
/// a non-mul, a call) returns null. The caller proves a name c invariant.
/// Only `.assign` statements are accepted for the inits and the accumulation:
/// a `.local_decl` would scope the name to the loop body, and the emission's
/// write-backs must target the same binding the body wrote.
fn triangularKOf(
    ctx: *LowerCtx,
    addend: *const ast.Expr,
    j_name: []const u8,
    iv: []const u8,
) ?TriangularK {
    const mu = switch (addend.*) {
        .binop => |x| x,
        else => return null,
    };
    if (mu.op != .mul) return null;
    const mu_lhs_j = if (identOf(mu.lhs)) |ln| std.mem.eql(u8, ln, j_name) else false;
    const mu_rhs_j = if (identOf(mu.rhs)) |rn| std.mem.eql(u8, rn, j_name) else false;
    if (mu_lhs_j == mu_rhs_j) return null;
    const kexpr = if (mu_lhs_j) mu.rhs else mu.lhs;
    if (identOf(kexpr)) |kn| {
        if (!std.mem.eql(u8, kn, iv)) return null;
        return .{ .lit = 1, .name = null };
    }
    const km = switch (kexpr.*) {
        .binop => |x| x,
        else => return null,
    };
    if (km.op != .mul) return null;
    const km_lhs_iv = if (identOf(km.lhs)) |ln| std.mem.eql(u8, ln, iv) else false;
    const km_rhs_iv = if (identOf(km.rhs)) |rn| std.mem.eql(u8, rn, iv) else false;
    if (km_lhs_iv == km_rhs_iv) return null;
    const cexpr = if (km_lhs_iv) km.rhs else km.lhs;
    if (ctx.graph.exactI64OfExpr(cexpr)) |cl| return .{ .lit = cl, .name = null };
    const cn = identOf(cexpr) orelse return null;
    return .{ .lit = null, .name = cn };
}

/// The target name and value of the single assignment `name = value`.
/// Anything else (multi-target, destructuring, declarations) returns null.
fn assignTargetAndValue(st: *const ast.Stmt) ?struct {
    name: []const u8,
    value: *const ast.Expr,
} {
    const a = switch (st.*) {
        .assign => |x| x,
        else => return null,
    };
    if (a.targets.len != 1 or a.values.len != 1) return null;
    return .{ .name = identOf(a.targets[0]) orelse return null, .value = a.values[0] };
}

/// Arm-time recognition of the nested triangular form. `ws` is the outer
/// `while` whose plan is being armed and `bound_lit` its literal bound (null
/// declines: the trip count must be a compile-time constant for the closed
/// form). The body's last statement steps the outer iv; the caller verified
/// that before this runs. Every aliasing doubt declines: T, J, acc and iv
/// pairwise distinct; K's factor c distinct from all four (the body's writes
/// are exactly T=0, J=0, acc=acc+T and the iv step, and the inner body writes
/// only T and J, so distinctness is the whole invariance proof); the inner
/// accumulation mentions neither acc nor any call.
fn nestedTriangularParts(
    ctx: *LowerCtx,
    ws: anytype,
    iv: []const u8,
    bound_lit: ?i64,
) ?NestedTriangular {
    const n_outer = bound_lit orelse return null;
    const body = ws.body.stmts;
    if (body.len != 5 or ws.body.tail_expr != null) return null;
    const t_init = assignTargetAndValue(&body[0]) orelse return null;
    const t_name = t_init.name;
    if (ctx.graph.exactI64OfExpr(t_init.value) != @as(?i64, 0)) return null;
    const j_init = assignTargetAndValue(&body[1]) orelse return null;
    const j_name = j_init.name;
    if (ctx.graph.exactI64OfExpr(j_init.value) != @as(?i64, 0)) return null;
    if (std.mem.eql(u8, t_name, iv) or std.mem.eql(u8, j_name, iv)) return null;
    if (std.mem.eql(u8, t_name, j_name)) return null;
    const s_while = switch (body[2]) {
        .while_loop => |w| w,
        else => return null,
    };
    const b2 = switch (s_while.cond.*) {
        .binop => |x| x,
        else => return null,
    };
    if (b2.op != .lt) return null;
    const j2 = identOf(b2.lhs) orelse return null;
    if (!std.mem.eql(u8, j2, j_name)) return null;
    const m = ctx.graph.exactI64OfExpr(b2.rhs) orelse return null;
    if (m < 0) return null;
    const acc_st = assignTargetAndValue(&body[3]) orelse return null;
    const acc_name = acc_st.name;
    if (std.mem.eql(u8, acc_name, iv) or std.mem.eql(u8, acc_name, j_name) or
        std.mem.eql(u8, acc_name, t_name)) return null;
    const acc_bo = switch (acc_st.value.*) {
        .binop => |x| x,
        else => return null,
    };
    if (acc_bo.op != .add) return null;
    const acc_lhs_acc = if (identOf(acc_bo.lhs)) |ln| std.mem.eql(u8, ln, acc_name) else false;
    const acc_rhs_acc = if (identOf(acc_bo.rhs)) |rn| std.mem.eql(u8, rn, acc_name) else false;
    if (acc_lhs_acc == acc_rhs_acc) return null;
    const acc_other = if (acc_lhs_acc) acc_bo.rhs else acc_bo.lhs;
    const acc_other_name = identOf(acc_other) orelse return null;
    if (!std.mem.eql(u8, acc_other_name, t_name)) return null;
    if (exprHasCall(acc_st.value)) return null;
    const ib = s_while.body.stmts;
    if (ib.len != 2 or s_while.body.tail_expr != null) return null;
    // The J-increment must trail the accumulation: the closed form sums
    // J*K over the J values at the accumulation point, which are 0..M-1
    // only when the increment is last. A leading increment accumulates
    // 1..M (M*(M+1)/2), a different sum -- decline rather than misfold.
    if (!stepIsIncrementOfOne(ctx.graph, &ib[1], j_name)) return null;
    const tacc = &ib[0];
    const ta_st = assignTargetAndValue(tacc) orelse return null;
    if (!std.mem.eql(u8, ta_st.name, t_name)) return null;
    if (ast.exprMentionsIdent(ta_st.value, acc_name)) return null;
    if (exprHasCall(ta_st.value)) return null;
    const ta_bo = switch (ta_st.value.*) {
        .binop => |x| x,
        else => return null,
    };
    if (ta_bo.op != .add) return null;
    const ta_lhs_t = if (identOf(ta_bo.lhs)) |ln| std.mem.eql(u8, ln, t_name) else false;
    const ta_rhs_t = if (identOf(ta_bo.rhs)) |rn| std.mem.eql(u8, rn, t_name) else false;
    if (ta_lhs_t == ta_rhs_t) return null;
    const addend = if (ta_lhs_t) ta_bo.rhs else ta_bo.lhs;
    const k = triangularKOf(ctx, addend, j_name, iv) orelse return null;
    if (k.name) |cn| {
        if (std.mem.eql(u8, cn, iv) or std.mem.eql(u8, cn, j_name) or
            std.mem.eql(u8, cn, t_name) or std.mem.eql(u8, cn, acc_name)) return null;
    }
    if (!nestedPlainInt(ctx, iv)) return null;
    if (!nestedPlainInt(ctx, acc_name)) return null;
    if (!nestedPlainInt(ctx, j_name)) return null;
    if (!nestedPlainInt(ctx, t_name)) return null;
    if (k.name) |cn| if (!nestedPlainInt(ctx, cn)) return null;
    return .{
        .inner_stmt = &body[2],
        .inner_iv = j_name,
        .inner_acc = t_name,
        .inner_bound_lit = m,
        .outer_acc = acc_name,
        .k_lit = k.lit,
        .k_name = k.name,
        .tri_m = triNum(m),
        .tri_n = triNum(n_outer),
    };
}

/// Block-level recognition: `stmts[at]` is `iv = 0` followed by
/// `while iv < bound` with a provably non-negative bound and a trailing
/// `iv = iv + 1` step. Arms `ctx.counted_plan`; emits nothing. Any doubt
/// leaves the plan disarmed and the loop lowers ordinarily.
fn tryArmCountedLoop(ctx: *LowerCtx, stmts: []const ast.Stmt, at: usize) void {
    const st = &stmts[at];
    const ws = switch (st.*) {
        .while_loop => |w| w,
        else => return,
    };
    const b = switch (ws.cond.*) {
        .binop => |x| x,
        else => return,
    };
    if (b.op != .lt) return;
    const iv = identOf(b.lhs) orelse return;
    // A statically zero-trip loop: `iv = v` binds the induction variable to
    // an exact literal immediately before, and the bound is an exact literal
    // `n` with `v >= n`, so `iv < n` is false on entry and the body provably
    // never executes. Swallow the loop; the binding lowers normally.
    if (at > 0) {
        if (literalBindingOf(ctx.graph, &stmts[at - 1], iv)) |v| {
            if (ctx.graph.exactI64OfExpr(b.rhs)) |n| {
                if (v >= n) {
                    ctx.zerotrip_swallowed.put(ctx.alloc, st, {}) catch return;
                    return;
                }
            }
        }
    }
    // The induction variable starts at exactly 0 in the immediately preceding
    // statement.
    if (at == 0) return;
    if (literalBindingOf(ctx.graph, &stmts[at - 1], iv) != @as(?i64, 0)) return;
    var plan = CountedPlan{ .stmt = st, .iv = iv, .bound_lit = null, .bound_name = null, .direct_acc = null };
    if (ctx.graph.exactI64OfExpr(b.rhs)) |n| {
        if (n < 0) return;
        plan.bound_lit = n;
    } else {
        const bname = identOf(b.rhs) orelse return;
        if (!countedBoundNonNeg(ctx, stmts, at, bname)) return;
        plan.bound_name = bname;
    }
    // The body's last statement steps the induction variable by exactly one.
    const n = ws.body.stmts.len;
    if (n == 0 or ws.body.tail_expr != null) return;
    if (!stepIsIncrementOfOne(ctx.graph, &ws.body.stmts[n - 1], iv)) return;
    plan.direct_acc = directAccIfPlainInt(ctx, ws, iv, plan.bound_name);
    if (plan.direct_acc == null) {
        plan.nested_direct = nestedDirectParts(ctx, stmts, at, ws, iv, plan.bound_name);
    }
    if (plan.direct_acc == null and plan.nested_direct == null) {
        plan.nested_triangular = nestedTriangularParts(ctx, ws, iv, plan.bound_lit);
    }
    if (plan.bound_lit) |bl| {
        if (selfMapLoopProven(ctx, stmts, at, ws, iv, bl, &plan)) plan.self_map = true;
    }
    // Absorbing fixed-point early exit (fixExitProven): only for literal
    // bounds, so the trip count cannot change under the loop. Moot when the
    // self-map proof already deleted the loop.
    if (plan.bound_lit != null and !plan.self_map) {
        plan.fix_exit = fixExitProven(ctx, stmts, at, st, ws, iv);
    }
    ctx.counted_plan = plan;
}

/// Abstract value for the fixed-point proof: an exact known constant, the
/// loop-entry value of one of the environment's own names (`entry` holds that
/// name's index — whatever the value was on entry, tracked exactly through
/// identity operations only), or fully unknown.
const FixExitVal = union(enum) {
    known: i64,
    entry: u32,
    unknown,
};

/// Environment for the fixed-point proof. An `entry(i)` tag is created only
/// in slot `i` itself and identity propagation never moves a tag between
/// slots, so `value[j] == .entry(j)` proves name `j` unchanged through the
/// evaluated body.
const FixExitEnv = struct {
    names: [self_map_max_names][]const u8 = undefined,
    value: [self_map_max_names]FixExitVal = undefined,
    len: usize = 0,

    fn indexOf(self: *const FixExitEnv, name: []const u8) ?usize {
        for (0..self.len) |i| {
            if (std.mem.eql(u8, self.names[i], name)) return i;
        }
        return null;
    }
};

/// Absorbing fixed-point early exit, settled at arm time. Recognizes a counted
/// loop whose body is straight-line pure integer dataflow (`assign` only, one
/// plain-ident target each) with exactly one write to the induction variable
/// (the terminal step), and proves that some loop-carried state `target`
/// reaches an absorbing fixed point `value` in {0, 1}: exact abstract
/// evaluation of the body from the state `target == value` (other carried
/// names tracked as their entry values through the exact identity
/// simplifications x+0=x, x*1=x, x*0=0; loop-invariant names resolved; traps
/// refusing) reproduces `target == value`. Every other name the body assigns
/// must be dead after the loop (nameDeadAfterFold's conservative
/// both-directions scan) or proven unchanged through the fixed state (its
/// final abstract value is its own entry value); the induction variable is
/// made exact by the emission's write-back.
/// Fails closed on any effect, branch, unsupported expression, multiple
/// induction writes, trap, or live state.
fn fixExitProven(
    ctx: *LowerCtx,
    stmts: []const ast.Stmt,
    at: usize,
    st: *const ast.Stmt,
    ws: anytype,
    iv: []const u8,
) ?FixExit {
    const body_all = ws.body.stmts;
    const n = body_all.len;
    if (n == 0) return null;
    const body = body_all[0 .. n - 1];
    // Shape: every statement a single-target single-value plain-ident assign;
    // exactly one write to the induction variable in the whole body (the
    // terminal step, verified by the arming above), so the trip count is
    // exact and the loop terminates.
    var iv_writes: usize = 0;
    for (body_all) |*s| {
        const a = switch (s.*) {
            .assign => |x| x,
            else => return null,
        };
        if (a.targets.len != 1 or a.values.len != 1) return null;
        const t = identOf(a.targets[0]) orelse return null;
        if (std.mem.eql(u8, t, iv)) iv_writes += 1;
    }
    if (iv_writes != 1) return null;
    // Candidate targets: every name the body assigns, except the induction
    // variable. The fixed-point values tried are 0 and 1.
    var seen: [self_map_max_names][]const u8 = undefined;
    var seen_len: usize = 0;
    for (body) |*s| {
        const a = switch (s.*) {
            .assign => |x| x,
            else => return null,
        };
        const t = identOf(a.targets[0]) orelse return null;
        if (std.mem.eql(u8, t, iv)) continue;
        var dup = false;
        for (seen[0..seen_len]) |x| if (std.mem.eql(u8, x, t)) {
            dup = true;
            break;
        };
        if (dup) continue;
        if (seen_len >= self_map_max_names) return null;
        seen[seen_len] = t;
        seen_len += 1;
    }
    for (seen[0..seen_len]) |target| {
        for ([_]i64{ 0, 1 }) |v| {
            const fenv = fixExitEvalBody(ctx, stmts, at, body, iv, target, v) orelse continue;
            const tidx = fenv.indexOf(target) orelse continue;
            const target_holds = switch (fenv.value[tidx]) {
                .known => |tv| tv == v,
                else => false,
            };
            if (!target_holds) continue;
            // Liveness: every other body-assigned name must be dead after the
            // loop, or proven unchanged through the fixed state: its final
            // abstract value is its own entry value, so the early exit leaves
            // it exactly where the full loop would. The target is exact
            // (value) and the induction variable is written back by the
            // emission.
            var ok = true;
            for (seen[0..seen_len]) |other| {
                if (std.mem.eql(u8, other, target)) continue;
                if (nameDeadAfterFold(ctx, other, st)) continue;
                const oidx = fenv.indexOf(other) orelse {
                    ok = false;
                    break;
                };
                const unchanged = switch (fenv.value[oidx]) {
                    .entry => |e| e == oidx,
                    else => false,
                };
                if (!unchanged) {
                    ok = false;
                    break;
                }
            }
            if (ok) return .{ .target = target, .value = v };
        }
    }
    return null;
}

/// Abstract evaluation of the body from the fixed-point state
/// `target == value`. Names resolve to: the fixed-point value for the target,
/// unknown for the induction variable, entry-value tags for carried names,
/// loop-invariant constants for names the body never assigns (via the
/// dominating store), and sequential abstract values for names assigned
/// earlier in the body. Any unsupported shape or trap (division by zero,
/// INT64_MIN / -1, division by an unknown divisor) fails the proof (null).
/// When the target's final abstract value is exactly `value`, the state is
/// absorbing: by induction over the body, every assigned name's abstract
/// value soundly describes its runtime value whenever the body is entered
/// with `target == value`, so the runtime body maps the fixed-point state to
/// itself exactly.
fn fixExitEvalBody(
    ctx: *LowerCtx,
    stmts: []const ast.Stmt,
    at: usize,
    body: []const ast.Stmt,
    iv: []const u8,
    target: []const u8,
    value: i64,
) ?FixExitEnv {
    var fenv = FixExitEnv{};
    for (body) |*s| {
        const a = switch (s.*) {
            .assign => |x| x,
            else => return null,
        };
        if (!fixExitCollectExpr(ctx, a.targets[0], &fenv)) return null;
        if (!fixExitCollectExpr(ctx, a.values[0], &fenv)) return null;
    }
    // Carried names (other than the target) are their entry values at entry;
    // only the target is pinned to the fixed-point value.
    var carried: [self_map_max_names]bool = undefined;
    for (&carried) |*c| c.* = false;
    for (body) |*s| {
        const a = switch (s.*) {
            .assign => |x| x,
            else => return null,
        };
        const t = identOf(a.targets[0]) orelse return null;
        const idx = fenv.indexOf(t) orelse return null;
        carried[idx] = true;
    }
    for (0..fenv.len) |i| {
        const nm = fenv.names[i];
        if (std.mem.eql(u8, nm, target)) {
            fenv.value[i] = .{ .known = value };
        } else if (std.mem.eql(u8, nm, iv)) {
            fenv.value[i] = .unknown;
        } else if (carried[i]) {
            fenv.value[i] = .{ .entry = @intCast(i) };
        } else if (countedDominatingStoreRhs(stmts, at, nm)) |re| {
            fenv.value[i] = if (ctx.graph.exactI64OfExpr(re)) |c|
                FixExitVal{ .known = c }
            else
                .unknown;
        } else {
            fenv.value[i] = .unknown;
        }
    }
    for (body) |*s| {
        const a = switch (s.*) {
            .assign => |x| x,
            else => return null,
        };
        var failed = false;
        const v = fixExitEvalExpr(ctx, a.values[0], &fenv, &failed);
        if (failed) return null;
        const t = identOf(a.targets[0]) orelse return null;
        const idx = fenv.indexOf(t) orelse return null;
        fenv.value[idx] = v;
    }
    return fenv;
}

/// Name/shape collection for the fixed-point proof. Accepts integer literals,
/// plain names, and the four integer binops; anything else (calls, tables,
/// comparisons, gate-transport applications) declines the proof.
fn fixExitCollectExpr(ctx: *LowerCtx, e: *const ast.Expr, fenv: *FixExitEnv) bool {
    if (ctx.occurrences.get(e) != null) return false;
    switch (e.*) {
        .int_lit => return true,
        .name => |nm| {
            if (fenv.indexOf(nm.ident) != null) return true;
            if (fenv.len >= self_map_max_names) return false;
            fenv.names[fenv.len] = nm.ident;
            fenv.value[fenv.len] = .unknown;
            fenv.len += 1;
            return true;
        },
        .binop => |b| {
            switch (b.op) {
                .add, .sub, .mul, .div => {},
                else => return false,
            }
            return fixExitCollectExpr(ctx, b.lhs, fenv) and
                fixExitCollectExpr(ctx, b.rhs, fenv);
        },
        else => return false,
    }
}

/// Identity simplifications for the fixed-point proof, all exact under
/// wrapping integer semantics: x+0=x, x*1=x, x*0=0 (and mirrors). Anything not
/// an identity and not fully known degrades to unknown; entry tags only ever
/// survive identity operations, never mixed arithmetic.
fn fixExitAdd(l: FixExitVal, r: FixExitVal) FixExitVal {
    switch (l) {
        .known => |lv| switch (r) {
            .known => |rv| return .{ .known = lv +% rv },
            else => return if (lv == 0) r else .unknown,
        },
        else => switch (r) {
            .known => |rv| return if (rv == 0) l else .unknown,
            else => return .unknown,
        },
    }
}

fn fixExitSub(l: FixExitVal, r: FixExitVal) FixExitVal {
    switch (l) {
        .known => |lv| switch (r) {
            .known => |rv| return .{ .known = lv -% rv },
            else => return .unknown,
        },
        else => switch (r) {
            .known => |rv| return if (rv == 0) l else .unknown,
            else => return .unknown,
        },
    }
}

fn fixExitMul(l: FixExitVal, r: FixExitVal) FixExitVal {
    switch (l) {
        .known => |lv| switch (r) {
            .known => |rv| return .{ .known = lv *% rv },
            else => {
                if (lv == 0) return .{ .known = 0 };
                if (lv == 1) return r;
                return .unknown;
            },
        },
        else => switch (r) {
            .known => |rv| {
                if (rv == 0) return .{ .known = 0 };
                if (rv == 1) return l;
                return .unknown;
            },
            else => return .unknown,
        },
    }
}

/// Exact abstract expression evaluation for the fixed-point proof.
/// Wrapping add/sub/mul, truncating division. Identity simplifications let an
/// entry value survive provably-no-op arithmetic; anything else unproven
/// degrades to unknown. Only definite proof failures set `failed`:
/// unsupported shapes, division by zero, INT64_MIN / -1, or a division whose
/// divisor is unknown (it might be zero when the fixed point holds, and
/// trap-freedom cannot be established) — exactly like the emitted code's
/// runtime trap check.
fn fixExitEvalExpr(
    ctx: *LowerCtx,
    e: *const ast.Expr,
    fenv: *const FixExitEnv,
    failed: *bool,
) FixExitVal {
    switch (e.*) {
        .int_lit => |l| return .{ .known = l.val },
        .name => |nm| {
            const idx = fenv.indexOf(nm.ident) orelse {
                failed.* = true;
                return .unknown;
            };
            return fenv.value[idx];
        },
        .binop => |b| {
            const l = fixExitEvalExpr(ctx, b.lhs, fenv, failed);
            const r = fixExitEvalExpr(ctx, b.rhs, fenv, failed);
            if (failed.*) return .unknown;
            switch (b.op) {
                .add => return fixExitAdd(l, r),
                .sub => return fixExitSub(l, r),
                .mul => return fixExitMul(l, r),
                .div => {
                    const rv = switch (r) {
                        .known => |v| v,
                        else => {
                            failed.* = true;
                            return .unknown;
                        },
                    };
                    if (rv == 0) {
                        failed.* = true;
                        return .unknown;
                    }
                    switch (l) {
                        .known => |lv| {
                            if (rv == -1 and lv == std.math.minInt(i64)) {
                                failed.* = true;
                                return .unknown;
                            }
                            return .{ .known = selfMapFoldBinop(b.op, lv, rv) orelse {
                                failed.* = true;
                                return .unknown;
                            } };
                        },
                        else => {
                            // x/1 is exact for every x and cannot trap; x/-1
                            // might trap (INT64_MIN) when x is not known.
                            if (rv == 1) return l;
                            if (rv == -1) {
                                failed.* = true;
                                return .unknown;
                            }
                            return .unknown;
                        },
                    }
                },
                else => {
                    failed.* = true;
                    return .unknown;
                },
            }
        },
        else => {
            failed.* = true;
            return .unknown;
        },
    }
}

/// Maximum distinct non-iv names a self-map proof tracks. Overflow declines
/// the transform (fails closed); real counted loops stay far below it.
const self_map_max_names = 32;

/// Maximum body evaluations the K-step convergence proof runs before it
/// gives up and declines. Each step is exact constant evaluation, so the
/// compile-time cost is trivial; 32 covers every converging bench program
/// (div 15, divby7 11, divpow2 8) with margin.
const self_map_max_steps: usize = 32;

/// IDOL_CONVK_OFF set -- THE SEVERING CONTROL for the K-step convergence
/// generalization. Set it and the self-map proof runs exactly one body
/// evaluation (the pre-generalization single-step check); unset and it runs
/// up to self_map_max_steps evaluations hunting a fixed point.
fn convKDisabled() bool {
    return std.c.getenv("IDOL_CONVK_OFF") != null;
}

/// Entry environment for the self-map proof: every non-iv name the body
/// mentions, with its loop-entry constant and its value as the proof
/// evaluates the body once on the entry state.
const SelfMapEnv = struct {
    names: [self_map_max_names][]const u8 = undefined,
    entry: [self_map_max_names]i64 = undefined,
    value: [self_map_max_names]i64 = undefined,
    len: usize = 0,

    fn indexOf(self: *const SelfMapEnv, name: []const u8) ?usize {
        for (0..self.len) |i| {
            if (std.mem.eql(u8, self.names[i], name)) return i;
        }
        return null;
    }

    /// Record a name; false when the environment is full (decline).
    fn note(self: *SelfMapEnv, name: []const u8) bool {
        if (self.indexOf(name) != null) return true;
        if (self.len == self_map_max_names) return false;
        self.names[self.len] = name;
        self.len += 1;
        return true;
    }
};

/// Exact integer arithmetic for the self-map proof, mirroring the backend's
/// own constant folder (`foldConstBinop` in native.zig): wrapping add/sub/mul
/// and truncating division. The two shapes the folder refuses -- division by
/// zero and minInt/-1 -- return null here as well, so a body that would trap
/// (or whose trap the backend routes elsewhere) declines the transform and
/// keeps its original trap behavior.
fn selfMapFoldBinop(op: ast.BinOp, l: i64, r: i64) ?i64 {
    return switch (op) {
        .add => l +% r,
        .sub => l -% r,
        .mul => l *% r,
        .div => if (r == 0 or (r == -1 and l == std.math.minInt(i64)))
            null
        else
            @divFloor(l, r),
        else => null,
    };
}

/// Collect every `.name` under `e` into the environment; false on any shape
/// outside int literal / name / whitelisted binop, on any read of the
/// induction variable (its value varies by iteration, so it has no entry
/// constant), and on any subexpression that carries a published application
/// (the graph's own record, never a guess about syntax).
fn selfMapCollectNames(ctx: *LowerCtx, e: *const ast.Expr, iv: []const u8, senv: *SelfMapEnv) bool {
    if (ctx.occurrences.get(e) != null) return false;
    switch (e.*) {
        .int_lit => return true,
        .name => |nm| {
            if (std.mem.eql(u8, nm.ident, iv)) return false;
            return senv.note(nm.ident);
        },
        .binop => |b| {
            switch (b.op) {
                .add, .sub, .mul, .div => {},
                else => return false,
            }
            return selfMapCollectNames(ctx, b.lhs, iv, senv) and
                selfMapCollectNames(ctx, b.rhs, iv, senv);
        },
        else => return false,
    }
}

/// Evaluate `e` exactly on the environment's current values; null on any
/// shape the collector declined (unreachable when the collector ran first)
/// or any arithmetic the backend folder refuses.
fn selfMapEvalExpr(ctx: *LowerCtx, e: *const ast.Expr, senv: *const SelfMapEnv) ?i64 {
    if (ctx.occurrences.get(e) != null) return null;
    switch (e.*) {
        .int_lit => |l| return l.val,
        .name => |nm| {
            const i = senv.indexOf(nm.ident) orelse return null;
            return senv.value[i];
        },
        .binop => |b| {
            const l = selfMapEvalExpr(ctx, b.lhs, senv) orelse return null;
            const r = selfMapEvalExpr(ctx, b.rhs, senv) orelse return null;
            return selfMapFoldBinop(b.op, l, r);
        },
        else => return null,
    }
}

/// SELF-MAP LOOP DELETION, K-STEP CONVERGENCE (arm-time proof).
///
/// A counted loop with a literal bound whose body is straight-line pure
/// integer dataflow is dead when bounded exact evaluation of the body reaches
/// a fixed point: step one on the entry constants is the old single-step
/// check (entry already a fixed point); a later step whose output reproduces
/// its input state is a fixed point of the deterministic body, so every
/// remaining iteration is dead and the loop's final state is that fixed
/// point. Only an immediate S_j == S_{j-1} is deletion-sound -- cycles
/// decline -- and convergence must land within the actual trip count.
/// Proved here by exact evaluation; anything the proof cannot follow exactly
/// refuses the transform and the loop lowers through the other counted forms
/// or ordinarily. In particular:
///   - only `.assign` statements with a single plain-name target;
///   - the induction variable is never read (no entry constant) and only the
///     trailing step may write it;
///   - every body name resolves to a plain-integer slot (no f64, str, bool,
///     pointer, or declared-narrow binding) with a dominating constant store,
///     settled at arm time while the slot markings are intact;
///   - a name the dominating-store scan cannot pin to a constant (outer
///     induction variables, calls, unknown values) declines.
fn selfMapLoopProven(ctx: *LowerCtx, stmts: []const ast.Stmt, at: usize, ws: anytype, iv: []const u8, bound: i64, plan: *CountedPlan) bool {
    if (bound < 0) return false;
    const body = ws.body.stmts;
    const n = body.len;
    if (n == 0 or ws.body.tail_expr != null) return false;
    if (!stepIsIncrementOfOne(ctx.graph, &body[n - 1], iv)) return false;
    var senv = SelfMapEnv{};
    for (body[0 .. n - 1]) |*st| {
        const a = switch (st.*) {
            .assign => |x| x,
            else => return false,
        };
        if (a.targets.len != 1 or a.values.len != 1) return false;
        const target = identOf(a.targets[0]) orelse return false;
        if (std.mem.eql(u8, target, iv)) return false;
        if (!senv.note(target)) return false;
        if (!selfMapCollectNames(ctx, a.values[0], iv, &senv)) return false;
    }
    for (0..senv.len) |k| {
        const slot = ctx.locals.get(senv.names[k]) orelse return false;
        if (!unrollPlainIntSlot(ctx, slot)) return false;
        const rhs = countedDominatingStoreRhs(stmts, at, senv.names[k]) orelse return false;
        const v = ctx.graph.exactI64OfExpr(rhs) orelse return false;
        senv.entry[k] = v;
        senv.value[k] = v;
    }
    var prev: [self_map_max_names]i64 = undefined;
    for (0..senv.len) |k| prev[k] = senv.entry[k];
    const max_steps: usize = if (convKDisabled()) 1 else self_map_max_steps;
    var step: usize = 0;
    while (step < max_steps) : (step += 1) {
        for (body[0 .. n - 1]) |*st| {
            const a = switch (st.*) {
                .assign => |x| x,
                else => return false,
            };
            const target = identOf(a.targets[0]) orelse return false;
            const v = selfMapEvalExpr(ctx, a.values[0], &senv) orelse return false;
            const i = senv.indexOf(target) orelse return false;
            senv.value[i] = v;
        }
        // A step that reproduces its input state is a fixed point of the
        // deterministic body: by induction every later iteration does too.
        // Names only read are never updated, so they compare equal
        // trivially; only immediate S_j == S_{j-1} deletes -- a cycle that
        // merely revisits an older state declines.
        var fixed = true;
        for (0..senv.len) |k| {
            if (senv.value[k] != prev[k]) {
                fixed = false;
                break;
            }
        }
        if (fixed) {
            // The fixed point must be reached inside the actual trip count;
            // a loop that ends first still computes real iterations. Step 0
            // reproduces the entry state itself, so it is sound for any
            // bound (it is the pre-generalization single-step check).
            if (step > 0 and step + 1 > @as(usize, @intCast(bound))) return false;
            plan.self_map_env = senv;
            return true;
        }
        for (0..senv.len) |k| prev[k] = senv.value[k];
    }
    return false;
}

/// The bound name is provably non-negative.
///   - Inside a relation the graph's own range column answers.
///   - At module scope the graph publishes no ranges, so the nearest
///     dominating store to the name is found by scanning back over statements
///     that cannot have written it, and the graph's OWN width transfer runs
///     over that store's right-hand side. A name met while its width is in
///     flight answers unknown, exactly as the producer's in-flight lattice
///     does. Absence of a proof declines; it never admits.
fn countedBoundNonNeg(ctx: *LowerCtx, stmts: []const ast.Stmt, at: usize, bound_name: []const u8) bool {
    // A declared-narrow bound is stored truncated: `y: i8 = 200` keeps -56
    // while the width transfer sees the literal 200. The proof is about the
    // initializer, not the stored value the loop reads, so the bound must not
    // be narrow. Both the declared global type and the slot marking are
    // consulted; the slot check runs at arm time, when markings are intact.
    if (ctx.module_globals.types.get(bound_name)) |rt| switch (rt) {
        .i8, .i16, .i32, .u8, .u16, .u32 => return false,
        else => {},
    };
    if (ctx.locals.get(bound_name)) |slot| {
        if (ctx.narrow_slots.contains(slot)) return false;
    }
    // Inside a relation the graph's own range column answers. ctx.function is
    // not the discriminator: at module scope it may still carry the root id,
    // while the graph publishes no ranges outside relations.
    if (!ctx.module_root) {
        if (ctx.function) |relation| {
            const subject = ctx.graph.bindingNamedIn(relation, bound_name) orelse return false;
            return ctx.graph.nonNegativeWidth(subject) != null;
        }
        return false;
    }
    // The semantic graph publishes module binding ranges; the backend
    // consumes that column rather than re-deriving provenance.
    _ = stmts;
    _ = at;
    return ctx.graph.moduleBindingWidth(bound_name) != null;
}


/// The right-hand side of the nearest store to `name` in `stmts[0..at]`, or
/// null when no store dominates: any statement that is not a plain
/// single-target store to a different plain name may have written `name` (a
/// call, a branch, a loop, a computed target), and an unproven bound declines
/// the transform.
fn countedDominatingStoreRhs(stmts: []const ast.Stmt, at: usize, name: []const u8) ?*const ast.Expr {
    var i = at;
    while (i > 0) {
        i -= 1;
        switch (stmts[i]) {
            .assign => |a| {
                if (a.targets.len != 1 or a.values.len != 1) return null;
                const t = identOf(a.targets[0]) orelse return null;
                if (std.mem.eql(u8, t, name)) return a.values[0];
            },
            .local_decl => |d| {
                if (d.names.len != d.inits.len) return null;
                for (d.names, 0..) |nm, k| {
                    if (std.mem.eql(u8, nm.ident, name)) return d.inits[k];
                }
            },
            .const_decl => |d| {
                if (std.mem.eql(u8, d.ident, name)) return d.val;
            },
            .global_decl => |d| {
                if (d.names.len != d.inits.len) return null;
                for (d.names, 0..) |nm, k| {
                    if (std.mem.eql(u8, nm.ident, name)) return d.inits[k];
                }
            },
            else => return null,
        }
    }
    return null;
}

/// Shared exit of every `while` lowering: patch the failing head test and all
/// `break`s to the end, retire the promotion shadows, and write promoted
/// bindings back to the module. The ordinary loop and the counted countdown
/// both land here, so the promotion write-back happens exactly once, at the
/// end, on every path.
fn finishWhileLowering(ctx: *LowerCtx, fail_idx: ?usize, promo: []const Promotion, wb_idx: ?usize, dead_names: []const []const u8) Error!void {
    const end_idx: u32 = @intCast(ctx.instrs.items.len);
    // A counted loop's induction-variable write-back precedes the shared exit;
    // the failing latch must land ON it, not past it.
    const target: u32 = if (wb_idx) |w| @intCast(w) else end_idx;
    if (fail_idx) |fi| ctx.instrs.items[fi].branch_target = target;
    var breaks = ctx.loop_breaks.pop() orelse return bail(ctx.diagnostic, @src());
    defer breaks.deinit(ctx.alloc);
    for (breaks.items) |br_idx| {
        ctx.instrs.items[br_idx].branch_target = target;
    }
    for (promo) |p| {
        // Retire the shadow FIRST, so nothing after the loop can reach
        // the register instead of the word.
        if (ctx.locals.fetchRemove(p.name)) |kv| ctx.alloc.free(kv.key);
        // `lowerAssignTarget`'s local arm records a literal store in
        // `const_ints`; the `store_global` arm it replaced records
        // nothing. Dropping the entry keeps everything AFTER the loop
        // reading exactly what it read before this pass existed.
        if (ctx.const_ints.fetchRemove(p.name)) |kv| ctx.alloc.free(kv.key);
        if (p.written) {
            var dead = false;
            for (dead_names) |dn| if (std.mem.eql(u8, dn, p.name)) {
                dead = true;
                break;
            };
            // A dead induction variable's promotion write-back is dead with it:
            // the liveness proof showed no read after the loop observes the
            // name, so the global word it would refresh is never read either.
            if (!dead) {
                try ctx.emit(.{
                    .op = .store_global,
                    .field = p.name,
                    .lhs = .{ .local = p.slot },
                    .ty = .i64,
                });
            }
        }
    }
}

/// Self-map deletion: the arm-time proof showed bounded exact evaluation
/// of the body reaches a fixed point, so every iteration past convergence is
/// dead and the loop computes nothing. Binds the induction variable to the
/// trip count -- its value after the loop -- rebinds each surviving name to
/// its proven fixed-point constant, and emits no loop. Returns true when the
/// proven shape matched and the deletion was emitted, false to fall back to
/// the direct form, the countdown, or the ordinary loop. Only the emission
/// runs here; the proof itself settled at arm time (slot markings intact) and
/// is re-verified below by structural identity only.
///
/// Runs inside the promotion's shadow scope (after the preloads, before the
/// write-backs), so the induction variable and the bound resolve through
/// `ctx.locals` exactly as the ordinary loop would see them. The surviving
/// names keep their promoted values -- which equal the entry constants --
/// and the write-backs carry them out unchanged.
fn lowerSelfMapCountedWhile(ctx: *LowerCtx, ws: anytype, plan: CountedPlan) Error!bool {
    if (!plan.self_map) return false;
    const b = switch (ws.cond.*) {
        .binop => |x| x,
        else => return false,
    };
    if (b.op != .lt) return false;
    const iv = identOf(b.lhs) orelse return false;
    if (!std.mem.eql(u8, iv, plan.iv)) return false;
    const n = plan.bound_lit orelse return false;
    if (ctx.graph.exactI64OfExpr(b.rhs) != @as(?i64, n)) return false;
    const iv_slot = ctx.locals.get(plan.iv) orelse return false;
    // Push an empty break list so finishWhileLowering's pop balances.
    try ctx.loop_breaks.append(ctx.alloc, std.ArrayListUnmanaged(u32).empty);
    const bound_v = try lowerExpr(ctx, b.rhs);
    try ctx.emit(.{ .op = .store_local, .result = iv_slot, .lhs = bound_v, .ty = .i64 });
    // K-step convergence: the fixed point can differ from the entry state, so
    // rebind each surviving name to its proven fixed-point constant. The
    // promotion write-backs then carry the loop's true final state out.
    // A name whose fixed point equals its entry constant needs no store;
    // a name the shadow scope cannot resolve fails closed to the other forms.
    if (plan.self_map_env) |fix| {
        for (0..fix.len) |k| {
            if (fix.value[k] == fix.entry[k]) continue;
            const slot = ctx.locals.get(fix.names[k]) orelse return false;
            try ctx.emit(.{ .op = .store_local, .result = slot, .lhs = .{ .i64 = fix.value[k] }, .ty = .i64 });
        }
    }
    return true;
}

/// Emit the countdown for an armed plan. Returns the latch-test fail index and
/// the induction-variable write-back index for the shared exit, or null when
/// any check fails — in which case NOTHING is emitted and the caller lowers
/// the loop ordinarily.
///
/// Runs inside the promotion's shadow scope (after the preloads, before the
/// write-backs), so the induction variable and the bound resolve through
/// `ctx.locals` exactly as the ordinary loop would see them.
/// Direct reduction for the exact two-statement counted loop:
///
///   iv = 0
///   while iv < bound
///     acc = acc + 1
///     iv = iv + 1
///
/// becomes `acc = acc + bound; iv = bound` with NO loop at all. Returns true
/// when the shape matched and the direct form was emitted, false to fall back
/// to the countdown (or the ordinary loop). The bound's non-negativity is
/// established by the plan arming.
fn lowerDirectCountedWhile(ctx: *LowerCtx, ws: anytype, plan: CountedPlan) Error!bool {
    const b = switch (ws.cond.*) {
        .binop => |x| x,
        else => return false,
    };
    if (b.op != .lt) return false;
    const iv = identOf(b.lhs) orelse return false;
    if (!std.mem.eql(u8, iv, plan.iv)) return false;
    if (plan.bound_lit) |n| {
        if (ctx.graph.exactI64OfExpr(b.rhs) != @as(?i64, n)) return false;
    } else if (plan.bound_name) |bn| {
        const rhs_name = identOf(b.rhs) orelse return false;
        if (!std.mem.eql(u8, rhs_name, bn)) return false;
    } else return false;
    // Body must be EXACTLY two increments, no tail, no other effects.
    const body_n = ws.body.stmts.len;
    if (body_n != 2 or ws.body.tail_expr != null) return false;
    const s0 = &ws.body.stmts[0];
    const s1 = &ws.body.stmts[1];
    // One statement steps the iv; the other steps the accumulator.
    var acc: ?[]const u8 = null;
    var acc_stmt: ?*const ast.Stmt = null;
    if (stepIsIncrementOfOne(ctx.graph, s0, iv)) {
        acc = accNameOfIncrement(s1, iv);
        acc_stmt = s1;
    } else if (stepIsIncrementOfOne(ctx.graph, s1, iv)) {
        acc = accNameOfIncrement(s0, iv);
        acc_stmt = s0;
    } else return false;
    const acc_name = acc orelse return false;
    // Distinct identities; the accumulator must not observe the counter.
    if (std.mem.eql(u8, acc_name, iv)) return false;
    if (plan.bound_name) |bn| if (std.mem.eql(u8, acc_name, bn)) return false;
    if (ast.stmtMentionsIdent(acc_stmt.?, iv)) return false;
    const iv_slot = ctx.locals.get(plan.iv) orelse return false;
    const acc_slot = ctx.locals.get(acc_name) orelse return false;
    // The type gate was settled at arm time, when the slot markings were
    // intact. The re-derived accumulator must be the armed one; anything else
    // means the loop changed under the plan.
    const armed_acc = plan.direct_acc orelse return false;
    if (!std.mem.eql(u8, acc_name, armed_acc)) return false;
    // ALL CHECKS PASSED - emit the direct form, no loop.
    // Push an empty break list so finishWhileLowering's pop balances.
    try ctx.loop_breaks.append(ctx.alloc, std.ArrayListUnmanaged(u32).empty);
    const bound_v = try lowerExpr(ctx, b.rhs);
    const cur: dnir.Value = .{ .local = acc_slot };
    const sum = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = sum, .binop = .add, .lhs = cur, .rhs = bound_v, .ty = .i64 });
    try ctx.emit(.{ .op = .store_local, .result = acc_slot, .lhs = .{ .temp = sum }, .ty = .i64 });
    try ctx.emit(.{ .op = .store_local, .result = iv_slot, .lhs = bound_v, .ty = .i64 });
    return true;
}
fn floorSum(n: u128, m: u128, a: u128, b: u128) u128 {
    var ans: u128 = 0;
    var nn: u128 = n;
    var mm: u128 = m;
    var aa: u128 = a;
    var bb: u128 = b;
    while (true) {
        if (aa >= mm) {
            ans += (nn - 1) * nn / 2 * (aa / mm);
            aa %= mm;
        }
        if (bb >= mm) {
            ans += nn * (bb / mm);
            bb %= mm;
        }
        const y_max: u128 = aa * nn + bb;
        if (y_max < mm) break;
        nn = y_max / mm;
        bb = y_max % mm;
        const t: u128 = mm;
        mm = aa;
        aa = t;
    }
    return ans;
}

fn digitSumClosedForm(n: i64, a: i64, b: i64, k: i64) ?u128 {
    var total: u128 = 0;
    var pow10: u128 = 1;
    var kk: i64 = 0;
    while (kk < k) : (kk += 1) {
        const sk: u128 = floorSum(@intCast(n), pow10, @intCast(a), @intCast(b));
        const sk1: u128 = floorSum(@intCast(n), pow10 * 10, @intCast(a), @intCast(b));
        total += sk - 10 * sk1;
        pow10 *= 10;
    }
    const bound: u128 = 9 * @as(u128, @intCast(k)) * @as(u128, @intCast(n));
    if (total > bound) return null;
    return total;
}

fn mulByLit(graph: *const semantic_graph.SemanticGraph, e: *const ast.Expr, iv: []const u8) ?i64 {
    const bo = switch (e.*) {
        .binop => |x| x,
        else => return null,
    };
    if (bo.op != .mul) return null;
    if (identOf(bo.lhs)) |l| {
        if (std.mem.eql(u8, l, iv)) return graph.exactI64OfExpr(bo.rhs);
    }
    if (identOf(bo.rhs)) |r| {
        if (std.mem.eql(u8, r, iv)) return graph.exactI64OfExpr(bo.lhs);
    }
    return null;
}

fn accAddNames(st: *const ast.Stmt, lhs_name: []const u8, rhs_name: []const u8) ?[]const u8 {
    const a = switch (st.*) {
        .assign => |x| x,
        else => return null,
    };
    if (a.targets.len != 1 or a.values.len != 1) return null;
    const tgt = identOf(a.targets[0]) orelse return null;
    const bo = switch (a.values[0].*) {
        .binop => |x| x,
        else => return null,
    };
    if (bo.op != .add) return null;
    if (identOf(bo.lhs)) |l| {
        if (std.mem.eql(u8, l, lhs_name)) {
            if (identOf(bo.rhs)) |r| {
                if (std.mem.eql(u8, r, rhs_name)) return tgt;
            }
        }
    }
    if (identOf(bo.rhs)) |r| {
        if (std.mem.eql(u8, r, lhs_name)) {
            if (identOf(bo.lhs)) |l| {
                if (std.mem.eql(u8, l, rhs_name)) return tgt;
            }
        }
    }
    return null;
}

fn lowerDigitSumCountedWhile(ctx: *LowerCtx, ws: anytype, plan: CountedPlan) Error!bool {
    const n = plan.bound_lit orelse return false;
    if (n < 1) return false;
    const b = switch (ws.cond.*) {
        .binop => |x| x,
        else => return false,
    };
    if (b.op != .lt) return false;
    const iv = identOf(b.lhs) orelse return false;
    if (!std.mem.eql(u8, iv, plan.iv)) return false;
    if (ctx.graph.exactI64OfExpr(b.rhs) != @as(?i64, n)) return false;

    const bstmts = ws.body.stmts;
    if (bstmts.len != 6 or ws.body.tail_expr != null) return false;
    if (!stepIsIncrementOfOne(ctx.graph, &bstmts[5], iv)) return false;

    const s0 = switch (bstmts[0]) {
        .assign => |x| x,
        else => return false,
    };
    if (s0.targets.len != 1 or s0.values.len != 1) return false;
    const xname = identOf(s0.targets[0]) orelse return false;
    const add0 = switch (s0.values[0].*) {
        .binop => |x| x,
        else => return false,
    };
    if (add0.op != .add) return false;
    const ab: struct { a: i64, b: ?i64 } = blk: {
        if (mulByLit(ctx.graph, add0.lhs, iv)) |a| {
            break :blk .{ .a = a, .b = ctx.graph.exactI64OfExpr(add0.rhs) };
        }
        if (mulByLit(ctx.graph, add0.rhs, iv)) |a| {
            break :blk .{ .a = a, .b = ctx.graph.exactI64OfExpr(add0.lhs) };
        }
        return false;
    };
    const A: i64 = ab.a;
    const B: i64 = ab.b orelse return false;
    if (A < 0 or B < 0) return false;
    const max_x: i128 = @as(i128, A) * @as(i128, n - 1) + @as(i128, B);
    if (max_x > @as(i128, std.math.maxInt(i64))) return false;

    const s1 = switch (bstmts[1]) {
        .assign => |x| x,
        else => return false,
    };
    if (s1.targets.len != 1 or s1.values.len != 1) return false;
    const sname = identOf(s1.targets[0]) orelse return false;
    if (ctx.graph.exactI64OfExpr(s1.values[0]) != @as(?i64, 0)) return false;
    const s2 = switch (bstmts[2]) {
        .assign => |x| x,
        else => return false,
    };
    if (s2.targets.len != 1 or s2.values.len != 1) return false;
    const jname = identOf(s2.targets[0]) orelse return false;
    if (ctx.graph.exactI64OfExpr(s2.values[0]) != @as(?i64, 0)) return false;

    const inner = switch (bstmts[3]) {
        .while_loop => |w| w,
        else => return false,
    };
    const icond = switch (inner.cond.*) {
        .binop => |x| x,
        else => return false,
    };
    if (icond.op != .lt) return false;
    const jiv = identOf(icond.lhs) orelse return false;
    if (!std.mem.eql(u8, jiv, jname)) return false;
    const kval = ctx.graph.exactI64OfExpr(icond.rhs) orelse return false;
    if (kval < 1 or kval > 18) return false;
    const istmts = inner.body.stmts;
    if (istmts.len != 5 or inner.body.tail_expr != null) return false;
    if (!stepIsIncrementOfOne(ctx.graph, &istmts[4], jname)) return false;

    const qi = switch (istmts[0]) {
        .assign => |x| x,
        else => return false,
    };
    if (qi.targets.len != 1 or qi.values.len != 1) return false;
    const qname = identOf(qi.targets[0]) orelse return false;
    const div0 = switch (qi.values[0].*) {
        .binop => |x| x,
        else => return false,
    };
    if (div0.op != .div) return false;
    const dxname = identOf(div0.lhs) orelse return false;
    if (!std.mem.eql(u8, dxname, xname)) return false;
    if (ctx.graph.exactI64OfExpr(div0.rhs) != @as(?i64, 10)) return false;

    const di = switch (istmts[1]) {
        .assign => |x| x,
        else => return false,
    };
    if (di.targets.len != 1 or di.values.len != 1) return false;
    const dname = identOf(di.targets[0]) orelse return false;
    const sub0 = switch (di.values[0].*) {
        .binop => |x| x,
        else => return false,
    };
    if (sub0.op != .sub) return false;
    const sxname = identOf(sub0.lhs) orelse return false;
    if (!std.mem.eql(u8, sxname, xname)) return false;
    const mul0 = switch (sub0.rhs.*) {
        .binop => |x| x,
        else => return false,
    };
    if (mul0.op != .mul) return false;
    const mqname = identOf(mul0.lhs) orelse return false;
    if (!std.mem.eql(u8, mqname, qname)) return false;
    if (ctx.graph.exactI64OfExpr(mul0.rhs) != @as(?i64, 10)) return false;

    if (accAddNames(&istmts[2], sname, dname)) |tgt| {
        if (!std.mem.eql(u8, tgt, sname)) return false;
    } else return false;

    const xi = switch (istmts[3]) {
        .assign => |x| x,
        else => return false,
    };
    if (xi.targets.len != 1 or xi.values.len != 1) return false;
    const xxname = identOf(xi.targets[0]) orelse return false;
    if (!std.mem.eql(u8, xxname, xname)) return false;
    const xqname = identOf(xi.values[0]) orelse return false;
    if (!std.mem.eql(u8, xqname, qname)) return false;

    const t_outer: []const u8 = blk: {
        const a = switch (bstmts[4]) {
            .assign => |x| x,
            else => return false,
        };
        if (a.targets.len != 1 or a.values.len != 1) return false;
        const tgt = identOf(a.targets[0]) orelse return false;
        const bo = switch (a.values[0].*) {
            .binop => |x| x,
            else => return false,
        };
        if (bo.op != .add) return false;
        var t_cand: ?[]const u8 = null;
        if (identOf(bo.lhs)) |l| {
            if (identOf(bo.rhs)) |r| {
                if (std.mem.eql(u8, r, sname)) t_cand = l;
            }
        }
        if (t_cand == null) {
            if (identOf(bo.rhs)) |r| {
                if (identOf(bo.lhs)) |l| {
                    if (std.mem.eql(u8, l, sname)) t_cand = r;
                }
            }
        }
        const tc = t_cand orelse return false;
        if (!std.mem.eql(u8, tgt, tc)) return false;
        break :blk tc;
    };

    const names = [_][]const u8{ iv, xname, sname, jname, qname, dname, t_outer };
    for (names, 0..) |a, i| {
        for (names[0..i]) |bb2| {
            if (std.mem.eql(u8, a, bb2)) return false;
        }
    }

    const total_u128 = digitSumClosedForm(n, A, B, kval) orelse return false;
    const total: i64 = @truncate(@as(i128, @bitCast(total_u128)));

    const x_last: u128 = @as(u128, @intCast(A)) * @as(u128, @intCast(n - 1)) + @as(u128, @intCast(B));
    var xv: u128 = x_last;
    var s_final: u128 = 0;
    var d_final: u128 = 0;
    var kk: i64 = 0;
    while (kk < kval) : (kk += 1) {
        d_final = xv % 10;
        s_final += d_final;
        xv /= 10;
    }
    const x_final: i64 = @intCast(xv);

    const t_slot = ctx.locals.get(t_outer) orelse return false;
    const iv_slot = ctx.locals.get(iv) orelse return false;
    const x_slot = blk: {
        if (ctx.locals.get(xname)) |s| break :blk s;
        const s = ctx.freshTemp();
        try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, xname), s);
        break :blk s;
    };
    const s_slot = blk: {
        if (ctx.locals.get(sname)) |s| break :blk s;
        const s = ctx.freshTemp();
        try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, sname), s);
        break :blk s;
    };
    const j_slot = blk: {
        if (ctx.locals.get(jname)) |s| break :blk s;
        const s = ctx.freshTemp();
        try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, jname), s);
        break :blk s;
    };
    const q_slot = blk: {
        if (ctx.locals.get(qname)) |s| break :blk s;
        const s = ctx.freshTemp();
        try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, qname), s);
        break :blk s;
    };
    const d_slot = blk: {
        if (ctx.locals.get(dname)) |s| break :blk s;
        const s = ctx.freshTemp();
        try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, dname), s);
        break :blk s;
    };

    try ctx.loop_breaks.append(ctx.alloc, std.ArrayListUnmanaged(u32).empty);
    {
        const cur: dnir.Value = .{ .local = t_slot };
        const sum = ctx.freshTemp();
        try ctx.emit(.{ .op = .binop, .result = sum, .binop = .add, .lhs = cur, .rhs = .{ .i64 = total }, .ty = .i64 });
        try ctx.emit(.{ .op = .store_local, .result = t_slot, .lhs = .{ .temp = sum }, .ty = .i64 });
    }
    try ctx.emit(.{ .op = .store_local, .result = iv_slot, .lhs = .{ .i64 = n }, .ty = .i64 });
    try ctx.emit(.{ .op = .store_local, .result = x_slot, .lhs = .{ .i64 = x_final }, .ty = .i64 });
    try ctx.emit(.{ .op = .store_local, .result = s_slot, .lhs = .{ .i64 = @intCast(s_final) }, .ty = .i64 });
    try ctx.emit(.{ .op = .store_local, .result = j_slot, .lhs = .{ .i64 = kval }, .ty = .i64 });
    try ctx.emit(.{ .op = .store_local, .result = q_slot, .lhs = .{ .i64 = x_final }, .ty = .i64 });
    try ctx.emit(.{ .op = .store_local, .result = d_slot, .lhs = .{ .i64 = @intCast(d_final) }, .ty = .i64 });
    return true;
}

/// BIT-REVERSE-SUM CLOSED FORM: `t += sum of bit-reversed affine values`.
///
/// Recognizes
///
///     while iv < N                          (N >= 1 literal)
///         x = iv * A + C                    (A, C >= 0 literals, A*(N-1)+C <= i64max)
///         x = x & M                         (M = 2^m - 1 literal, 1 <= m <= 62)
///         r = 0
///         i = 0
///         while i < m                       (literal trip count == m)
///             r = r * 2 + (x & 1)           (either add-operand order)
///             x = x / 2                     (or x >> 1)
///             i = i + 1
///         t = t + r                         (either add-operand order)
///         iv = iv + 1
///
/// and replaces the whole nest with `t += total` plus the final values of the
/// loop variables, emitting no loop at all.
///
/// WHY THIS IS SOUND. The inner loop is the bit-reverse idiom the prologue in
/// `tryEmitBitReversePrologue` proves: after m iterations r = rev_m(x_0), the
/// low m bits of the masked x_0 reversed, and x = 0. Write v_o = A*o+C
/// (>= 0 and exact: the max_x check rules out i64 overflow) and
/// x_o = v_o mod 2^m (the mask). Bit j of r_o is bit (m-1-j) of x_o, and for
/// k < m, bit_k(x_o) = bit_k(v_o) since the mask only drops bits >= m, with
/// bit_k(v) = floor(v/2^k) - 2*floor(v/2^{k+1}). Summing over the outer loop:
///
///     t_new = t_old + sum_{j<m} 2^j * (S(m-1-j) - 2*S(m-j))
///
/// where S(k) = sum_{o<N} floor((A*o+C)/2^k), each a logarithmic-time
/// `floorSum` evaluation done here at compile time. The u128 bound check
/// `total <= N*(2^m-1)` guards the closed form's internal consistency; the
/// emitted i64 add wraps exactly like the source loop's accumulation, so the
/// result is identical even past i64max. Final values: iv = N, x = 0 (x_0 < 2^m
/// halves to zero in m steps), r = rev_m(x_{N-1}), i = m. Any shape doubt
/// returns false and the nest lowers exactly as it does today.
fn bitRevSumClosedForm(n: i64, a: i64, b: i64, m: i64) ?u128 {
    var total: u128 = 0;
    var jj: i64 = 0;
    while (jj < m) : (jj += 1) {
        const k1: u128 = @as(u128, 1) << @as(u7, @intCast(m - 1 - jj));
        const k2: u128 = @as(u128, 1) << @as(u7, @intCast(m - jj));
        const nu: u128 = @as(u128, @intCast(n));
        const au: u128 = @as(u128, @intCast(a));
        const bu: u128 = @as(u128, @intCast(b));
        const s1: u128 = floorSum(nu, k1, au, bu);
        const s2: u128 = floorSum(nu, k2, au, bu);
        total += (@as(u128, 1) << @as(u7, @intCast(jj))) * (s1 - 2 * s2);
    }
    const bound: u128 = @as(u128, @intCast(n)) * (((@as(u128, 1) << @as(u7, @intCast(m))) - 1));
    if (total > bound) return null;
    return total;
}

fn lowerBitRevSumCountedWhile(ctx: *LowerCtx, ws: anytype, plan: CountedPlan) Error!bool {
    const n = plan.bound_lit orelse return false;
    if (n < 1) return false;
    const b = switch (ws.cond.*) {
        .binop => |x| x,
        else => return false,
    };
    if (b.op != .lt) return false;
    const iv = identOf(b.lhs) orelse return false;
    if (!std.mem.eql(u8, iv, plan.iv)) return false;
    if (ctx.graph.exactI64OfExpr(b.rhs) != @as(?i64, n)) return false;

    const bstmts = ws.body.stmts;
    if (bstmts.len != 7 or ws.body.tail_expr != null) return false;
    if (!stepIsIncrementOfOne(ctx.graph, &bstmts[6], iv)) return false;

    const s0 = switch (bstmts[0]) {
        .assign => |x| x,
        else => return false,
    };
    if (s0.targets.len != 1 or s0.values.len != 1) return false;
    const xname = identOf(s0.targets[0]) orelse return false;
    const add0 = switch (s0.values[0].*) {
        .binop => |x| x,
        else => return false,
    };
    if (add0.op != .add) return false;
    const ab: struct { a: i64, c: ?i64 } = blk: {
        if (mulByLit(ctx.graph, add0.lhs, iv)) |a| {
            break :blk .{ .a = a, .c = ctx.graph.exactI64OfExpr(add0.rhs) };
        }
        if (mulByLit(ctx.graph, add0.rhs, iv)) |a| {
            break :blk .{ .a = a, .c = ctx.graph.exactI64OfExpr(add0.lhs) };
        }
        return false;
    };
    const A: i64 = ab.a;
    const C: i64 = ab.c orelse return false;
    if (A < 0 or C < 0) return false;
    const max_x: i128 = @as(i128, A) * @as(i128, n - 1) + @as(i128, C);
    if (max_x > @as(i128, std.math.maxInt(i64))) return false;

    const s1 = switch (bstmts[1]) {
        .assign => |x| x,
        else => return false,
    };
    if (s1.targets.len != 1 or s1.values.len != 1) return false;
    const x1name = identOf(s1.targets[0]) orelse return false;
    if (!std.mem.eql(u8, x1name, xname)) return false;
    const band0 = switch (s1.values[0].*) {
        .binop => |x| x,
        else => return false,
    };
    if (band0.op != .band) return false;
    const mval: i64 = blk: {
        if (identOf(band0.lhs)) |l| {
            if (std.mem.eql(u8, l, xname)) {
                if (ctx.graph.exactI64OfExpr(band0.rhs)) |v| break :blk v;
            }
        }
        if (identOf(band0.rhs)) |r| {
            if (std.mem.eql(u8, r, xname)) {
                if (ctx.graph.exactI64OfExpr(band0.lhs)) |v| break :blk v;
            }
        }
        return false;
    };
    if (mval < 1) return false;
    var m: i64 = 0;
    var p: u64 = 1;
    while (p <= @as(u64, @intCast(mval))) {
        m += 1;
        if (m > 62) return false;
        p *= 2;
    }
    if (p - 1 != @as(u64, @intCast(mval))) return false;

    const s2 = switch (bstmts[2]) {
        .assign => |x| x,
        else => return false,
    };
    if (s2.targets.len != 1 or s2.values.len != 1) return false;
    const rname = identOf(s2.targets[0]) orelse return false;
    if (ctx.graph.exactI64OfExpr(s2.values[0]) != @as(?i64, 0)) return false;
    const s3 = switch (bstmts[3]) {
        .assign => |x| x,
        else => return false,
    };
    if (s3.targets.len != 1 or s3.values.len != 1) return false;
    const iname = identOf(s3.targets[0]) orelse return false;
    if (ctx.graph.exactI64OfExpr(s3.values[0]) != @as(?i64, 0)) return false;

    const inner = switch (bstmts[4]) {
        .while_loop => |w| w,
        else => return false,
    };
    const icond = switch (inner.cond.*) {
        .binop => |x| x,
        else => return false,
    };
    if (icond.op != .lt) return false;
    const jiv = identOf(icond.lhs) orelse return false;
    if (!std.mem.eql(u8, jiv, iname)) return false;
    if (ctx.graph.exactI64OfExpr(icond.rhs) != @as(?i64, m)) return false;
    const istmts = inner.body.stmts;
    if (istmts.len != 3 or inner.body.tail_expr != null) return false;
    const ap = bitRevAccum(ctx.graph, &istmts[0]) orelse return false;
    if (!std.mem.eql(u8, ap.acc, rname)) return false;
    if (!std.mem.eql(u8, ap.src, xname)) return false;
    if (std.mem.eql(u8, ap.acc, ap.src)) return false;
    if (!bitRevHalve(ctx.graph, &istmts[1], xname)) return false;
    if (!stepIsIncrementOfOne(ctx.graph, &istmts[2], iname)) return false;

    const tname: []const u8 = blk: {
        const a = switch (bstmts[5]) {
            .assign => |x| x,
            else => return false,
        };
        if (a.targets.len != 1 or a.values.len != 1) return false;
        const tgt = identOf(a.targets[0]) orelse return false;
        const bo = switch (a.values[0].*) {
            .binop => |x| x,
            else => return false,
        };
        if (bo.op != .add) return false;
        var t_cand: ?[]const u8 = null;
        if (identOf(bo.lhs)) |l| {
            if (identOf(bo.rhs)) |r| {
                if (std.mem.eql(u8, r, rname)) t_cand = l;
            }
        }
        if (t_cand == null) {
            if (identOf(bo.rhs)) |r| {
                if (identOf(bo.lhs)) |l| {
                    if (std.mem.eql(u8, l, rname)) t_cand = r;
                }
            }
        }
        const tc = t_cand orelse return false;
        if (!std.mem.eql(u8, tgt, tc)) return false;
        break :blk tc;
    };

    const names = [_][]const u8{ iv, xname, rname, iname, tname };
    for (names, 0..) |aname, ii| {
        for (names[0..ii]) |bname| {
            if (std.mem.eql(u8, aname, bname)) return false;
        }
    }

    const total_u128 = bitRevSumClosedForm(n, A, C, m) orelse return false;
    const total: i64 = @truncate(@as(i128, @bitCast(total_u128)));

    const mask_u128: u128 = (@as(u128, 1) << @as(u7, @intCast(m))) - 1;
    const x_last: u128 = (@as(u128, @intCast(A)) * @as(u128, @intCast(n - 1)) + @as(u128, @intCast(C))) & mask_u128;
    var rv: u128 = 0;
    var xv: u128 = x_last;
    var kk: i64 = 0;
    while (kk < m) : (kk += 1) {
        rv = rv * 2 + (xv & 1);
        xv >>= 1;
    }
    const r_final: i64 = @intCast(rv);

    const t_slot = ctx.locals.get(tname) orelse return false;
    const iv_slot = ctx.locals.get(iv) orelse return false;
    const x_slot = blk: {
        if (ctx.locals.get(xname)) |s| break :blk s;
        const s = ctx.freshTemp();
        try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, xname), s);
        break :blk s;
    };
    const r_slot = blk: {
        if (ctx.locals.get(rname)) |s| break :blk s;
        const s = ctx.freshTemp();
        try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, rname), s);
        break :blk s;
    };
    const i_slot = blk: {
        if (ctx.locals.get(iname)) |s| break :blk s;
        const s = ctx.freshTemp();
        try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, iname), s);
        break :blk s;
    };

    try ctx.loop_breaks.append(ctx.alloc, std.ArrayListUnmanaged(u32).empty);
    {
        const cur: dnir.Value = .{ .local = t_slot };
        const sum = ctx.freshTemp();
        try ctx.emit(.{ .op = .binop, .result = sum, .binop = .add, .lhs = cur, .rhs = .{ .i64 = total }, .ty = .i64 });
        try ctx.emit(.{ .op = .store_local, .result = t_slot, .lhs = .{ .temp = sum }, .ty = .i64 });
    }
    try ctx.emit(.{ .op = .store_local, .result = iv_slot, .lhs = .{ .i64 = n }, .ty = .i64 });
    try ctx.emit(.{ .op = .store_local, .result = x_slot, .lhs = .{ .i64 = 0 }, .ty = .i64 });
    try ctx.emit(.{ .op = .store_local, .result = r_slot, .lhs = .{ .i64 = r_final }, .ty = .i64 });
    try ctx.emit(.{ .op = .store_local, .result = i_slot, .lhs = .{ .i64 = m }, .ty = .i64 });
    return true;
}
/// Emit the nested direct form for an armed plan: the nest
///
///     iv = 0
///     while iv < bound
///         J = 0
///         while J < B
///             T = T + 1
///             J = J + 1
///         iv = iv + 1
///
/// becomes `T = T + bound * B; iv = bound` with no loop, and `J = B` on the
/// taken path. The inner write-back is guarded: the source runs the inner
/// `J = 0` init only when the outer loop trips, so on a zero trip J keeps
/// its entry value. Returns true when the shape matched and the form was
/// emitted, false to fall back to the countdown or the ordinary loop. Only
/// the emission runs here; the proof settled at arm time and is re-verified
/// below by structural identity only.
/// Push the enclosing-block frame for statement `i` of `block`. Pair with
/// `popEnclosingFrame` via defer so `continue` and errors still pop.
fn pushEnclosingFrame(ctx: *LowerCtx, block: *const ast.Block, i: usize) Error!void {
    try ctx.enclosing.append(ctx.alloc, .{ .block = block, .idx = i });
}

fn popEnclosingFrame(ctx: *LowerCtx) void {
    _ = ctx.enclosing.pop();
}

/// Does any statement in `stmts` mention `name`, excluding the subtree of
/// `excl` (the folded loop itself)? A mention is a conservative read: the
/// scan cannot tell whether the mention observes the folded write-back, so
/// any mention keeps the write-back.
fn blockStmtsMentionIdent(stmts: []const ast.Stmt, name: []const u8, excl: ?*const ast.Stmt) bool {
    for (stmts) |*s| {
        if (excl) |e| if (s == e) continue;
        if (ast.stmtMentionsIdent(s, name)) return true;
    }
    return false;
}

/// Prove the folded loop's write-back to `name` is dead: no read after the
/// fold can observe it. Walks the enclosing-block stack innermost-out. For
/// every frame the statements after the current position are scanned, and
/// the statements before it are scanned too — conservatively, because on a
/// back edge the prefix re-executes, and a prefix read with no intervening
/// write would observe the write-back. When the current statement is an
/// enclosing loop, its condition and full body are scanned as well: the back
/// edge can re-enter a sibling branch (e.g. an `else`) that the linear
/// prefix/suffix scans do not cover. Each block's tail expression is
/// scanned too. Any mention keeps the write-back; silence across every
/// frame proves death. The scan is purely conservative — it may keep a dead
/// write-back, but it never drops a live one.
fn nameDeadAfterFold(ctx: *LowerCtx, name: []const u8, excl: *const ast.Stmt) bool {
    const frames = ctx.enclosing.items;
    var fi = frames.len;
    while (fi > 0) {
        fi -= 1;
        const fr = frames[fi];
        if (fr.idx + 1 < fr.block.stmts.len and
            blockStmtsMentionIdent(fr.block.stmts[fr.idx + 1 ..], name, excl)) return false;
        if (fr.idx > 0 and
            blockStmtsMentionIdent(fr.block.stmts[0..fr.idx], name, excl)) return false;
        if (fr.block.tail_expr) |te| {
            if (ast.exprMentionsIdent(te, name)) return false;
        }
        const s = &fr.block.stmts[fr.idx];
        if (s == excl) continue;
        switch (s.*) {
            .while_loop => |w| {
                if (ast.exprMentionsIdent(w.cond, name)) return false;
                if (blockStmtsMentionIdent(w.body.stmts, name, excl)) return false;
                if (w.body.tail_expr) |te| if (ast.exprMentionsIdent(te, name)) return false;
            },
            .repeat_loop => |r| {
                if (ast.exprMentionsIdent(r.cond, name)) return false;
                if (blockStmtsMentionIdent(r.body.stmts, name, excl)) return false;
                if (r.body.tail_expr) |te| if (ast.exprMentionsIdent(te, name)) return false;
            },
            .num_for => |f| {
                if (blockStmtsMentionIdent(f.body.stmts, name, excl)) return false;
                if (f.body.tail_expr) |te| if (ast.exprMentionsIdent(te, name)) return false;
            },
            .gen_for => |f| {
                if (blockStmtsMentionIdent(f.body.stmts, name, excl)) return false;
                if (f.body.tail_expr) |te| if (ast.exprMentionsIdent(te, name)) return false;
            },
            else => {},
        }
    }
    return true;
}

fn lowerNestedDirectCountedWhile(ctx: *LowerCtx, ws: anytype, plan: CountedPlan) Error!?NestedFoldLiveness {
    const nd = plan.nested_direct orelse return null;
    const b = switch (ws.cond.*) {
        .binop => |x| x,
        else => return null,
    };
    if (b.op != .lt) return null;
    const iv = identOf(b.lhs) orelse return null;
    if (!std.mem.eql(u8, iv, plan.iv)) return null;
    if (plan.bound_lit) |n| {
        if (ctx.graph.exactI64OfExpr(b.rhs) != @as(?i64, n)) return null;
    } else if (plan.bound_name) |bn| {
        const rhs_name = identOf(b.rhs) orelse return null;
        if (!std.mem.eql(u8, rhs_name, bn)) return null;
    } else return null;
    const body = ws.body.stmts;
    if (body.len != 3 or ws.body.tail_expr != null) return null;
    if (!stepIsIncrementOfOne(ctx.graph, &body[2], plan.iv)) return null;
    const s1 = &body[1];
    if (nd.inner_stmt != @as(*const ast.Stmt, s1)) return null;
    const s_while = switch (s1.*) {
        .while_loop => |w| w,
        else => return null,
    };
    const b2 = switch (s_while.cond.*) {
        .binop => |x| x,
        else => return null,
    };
    if (b2.op != .lt) return null;
    const j = identOf(b2.lhs) orelse return null;
    if (!std.mem.eql(u8, j, nd.inner_iv)) return null;
    if (nd.inner_bound_lit) |n2| {
        if (ctx.graph.exactI64OfExpr(b2.rhs) != @as(?i64, n2)) return null;
    } else if (nd.inner_bound_name) |bn2| {
        const rhs2 = identOf(b2.rhs) orelse return null;
        if (!std.mem.eql(u8, rhs2, bn2)) return null;
    } else return null;
    if (literalBindingOf(ctx.graph, &body[0], nd.inner_iv) != @as(?i64, 0)) return null;
    // Re-derive the accumulator structurally (slot markings are not intact at
    // emission); it must be the armed one.
    const ib = s_while.body.stmts;
    if (ib.len != 2 or s_while.body.tail_expr != null) return null;
    var acc: ?[]const u8 = null;
    if (stepIsIncrementOfOne(ctx.graph, &ib[0], nd.inner_iv)) {
        acc = accNameOfIncrement(&ib[1], nd.inner_iv);
    } else if (stepIsIncrementOfOne(ctx.graph, &ib[1], nd.inner_iv)) {
        acc = accNameOfIncrement(&ib[0], nd.inner_iv);
    } else return null;
    const acc_name = acc orelse return null;
    if (!std.mem.eql(u8, acc_name, nd.acc)) return null;
    if (std.mem.eql(u8, acc_name, iv)) return null;
    if (std.mem.eql(u8, acc_name, j)) return null;
    if (plan.bound_name) |bn| if (std.mem.eql(u8, acc_name, bn)) return null;
    if (nd.inner_bound_name) |bn2| if (std.mem.eql(u8, acc_name, bn2)) return null;
    const iv_slot = ctx.locals.get(plan.iv) orelse return null;
    const acc_slot = ctx.locals.get(acc_name) orelse return null;
    // The inner iv's slot: the outer loop's promotion shadows it when it is
    // a written `.i64` module global. Otherwise the name is first bound by
    // the inner `J = 0` the shape match verified -- which this emission
    // replaces -- so materialize the slot the source's init would have
    // created. A module global that promotion did not shadow declines: a
    // fresh local would diverge from the global later reads use.
    const j_slot: u32 = if (ctx.locals.get(nd.inner_iv)) |s| s else blk: {
        if (ctx.module_globals.types.get(nd.inner_iv) != null) return null;
        const s = ctx.freshTemp();
        try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, nd.inner_iv), s);
        break :blk s;
    };
    // ALL CHECKS PASSED - emit the folded nest, no loop.
    // Push an empty break list so finishWhileLowering's pop balances.
    try ctx.loop_breaks.append(ctx.alloc, std.ArrayListUnmanaged(u32).empty);
    const bound_v = try lowerExpr(ctx, b.rhs);
    const inner_bound_v = try lowerExpr(ctx, b2.rhs);
    const prod = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = prod, .binop = .mul, .lhs = bound_v, .rhs = inner_bound_v, .ty = .i64 });
    const sum = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = sum, .binop = .add, .lhs = .{ .local = acc_slot }, .rhs = .{ .temp = prod }, .ty = .i64 });
    try ctx.emit(.{ .op = .store_local, .result = acc_slot, .lhs = .{ .temp = sum }, .ty = .i64 });
    // Liveness-gated write-back elimination: when an induction variable is
    // never read after the folded loop, its write-back is dead. The proof
    // walks the enclosing-block stack (`nameDeadAfterFold`); any doubt keeps
    // the write-back, so a wrong proof can only cost the optimization, never
    // correctness.
    const iv_dead = nameDeadAfterFold(ctx, plan.iv, plan.stmt);
    const inner_dead = nameDeadAfterFold(ctx, nd.inner_iv, plan.stmt);
    if (!iv_dead) {
        try ctx.emit(.{ .op = .store_local, .result = iv_slot, .lhs = bound_v, .ty = .i64 });
    }
    if (!inner_dead) {
        // Cold guard for the inner write-back: the source runs the inner `J = 0`
        // init only when the outer loop trips at least once.
        const guard_t = ctx.freshTemp();
        try ctx.emit(.{ .op = .binop, .result = guard_t, .binop = .neq, .lhs = bound_v, .rhs = .{ .i64 = 0 }, .ty = .i64 });
        const guard_fail = ctx.instrs.items.len;
        try ctx.emit(.{ .op = .br, .lhs = .{ .temp = guard_t }, .branch_target = 0, .branch_condition = .when_false });
        try ctx.emit(.{ .op = .store_local, .result = j_slot, .lhs = inner_bound_v, .ty = .i64 });
        ctx.instrs.items[guard_fail].branch_target = @intCast(ctx.instrs.items.len);
    }
    return .{ .iv_dead = iv_dead, .inner_dead = inner_dead };
}


const NestedTriangularLiveness = struct {
    /// The outer induction variable is never read after the folded loop.
    iv_dead: bool,
    /// The inner induction variable is never read after the folded loop.
    inner_iv_dead: bool,
    /// The inner accumulator is never read after the folded loop.
    inner_acc_dead: bool,
};

/// Emission for the nested triangular form (armed by `nestedTriangularParts`).
/// Re-verifies the armed parts against the current AST, then replaces the
/// whole nest with `acc = acc + C*tri(M)*tri(N)` (one add when C is a
/// literal, one mul and one add when C is an invariant name) plus write-backs
/// of the surviving induction variables: `iv = N` when live, `J = M` when
/// live, `T = C*(N-1)*tri(M)` when live (the inner accumulator's value after
/// the final outer iteration). When N = 0 the nest never executes and nothing
/// is emitted. Returns the fold liveness for the caller, or null to decline
/// when the armed proof no longer holds.
fn lowerNestedTriangularCountedWhile(ctx: *LowerCtx, ws: anytype, plan: CountedPlan) Error!?NestedTriangularLiveness {
    const nt = plan.nested_triangular orelse return null;
    const body = ws.body.stmts;
    if (body.len != 5 or ws.body.tail_expr != null) return null;
    if (nt.inner_stmt != @as(*const ast.Stmt, &body[2])) return null;
    if (!stepIsIncrementOfOne(ctx.graph, &body[4], plan.iv)) return null;
    const b = switch (ws.cond.*) {
        .binop => |x| x,
        else => return null,
    };
    if (b.op != .lt) return null;
    const bl = identOf(b.lhs) orelse return null;
    if (!std.mem.eql(u8, bl, plan.iv)) return null;
    const n_outer = plan.bound_lit orelse return null;
    const t_init = assignTargetAndValue(&body[0]) orelse return null;
    if (!std.mem.eql(u8, t_init.name, nt.inner_acc)) return null;
    if (ctx.graph.exactI64OfExpr(t_init.value) != @as(?i64, 0)) return null;
    const j_init = assignTargetAndValue(&body[1]) orelse return null;
    if (!std.mem.eql(u8, j_init.name, nt.inner_iv)) return null;
    if (ctx.graph.exactI64OfExpr(j_init.value) != @as(?i64, 0)) return null;
    const s_while = switch (body[2]) {
        .while_loop => |w| w,
        else => return null,
    };
    const b2 = switch (s_while.cond.*) {
        .binop => |x| x,
        else => return null,
    };
    if (b2.op != .lt) return null;
    const j2 = identOf(b2.lhs) orelse return null;
    if (!std.mem.eql(u8, j2, nt.inner_iv)) return null;
    if (ctx.graph.exactI64OfExpr(b2.rhs) != @as(?i64, nt.inner_bound_lit)) return null;
    const acc_st = assignTargetAndValue(&body[3]) orelse return null;
    if (!std.mem.eql(u8, acc_st.name, nt.outer_acc)) return null;
    const acc_bo = switch (acc_st.value.*) {
        .binop => |x| x,
        else => return null,
    };
    if (acc_bo.op != .add) return null;
    const acc_sides_ok = blk: {
        const l = identOf(acc_bo.lhs);
        const r = identOf(acc_bo.rhs);
        break :blk l != null and r != null and
            ((std.mem.eql(u8, l.?, nt.outer_acc) and std.mem.eql(u8, r.?, nt.inner_acc)) or
            (std.mem.eql(u8, r.?, nt.outer_acc) and std.mem.eql(u8, l.?, nt.inner_acc)));
    };
    if (!acc_sides_ok) return null;
    const ib = s_while.body.stmts;
    if (ib.len != 2 or s_while.body.tail_expr != null) return null;
    // The J-increment must trail the accumulation (see the arm above):
    // a leading increment accumulates J*K over 1..M, not 0..M-1.
    if (!stepIsIncrementOfOne(ctx.graph, &ib[1], nt.inner_iv)) return null;
    const tacc = &ib[0];
    const ta_st = assignTargetAndValue(tacc) orelse return null;
    if (!std.mem.eql(u8, ta_st.name, nt.inner_acc)) return null;
    const ta_bo = switch (ta_st.value.*) {
        .binop => |x| x,
        else => return null,
    };
    if (ta_bo.op != .add) return null;
    const ta_lhs_t = if (identOf(ta_bo.lhs)) |ln| std.mem.eql(u8, ln, nt.inner_acc) else false;
    const ta_rhs_t = if (identOf(ta_bo.rhs)) |rn| std.mem.eql(u8, rn, nt.inner_acc) else false;
    if (ta_lhs_t == ta_rhs_t) return null;
    const addend = if (ta_lhs_t) ta_bo.rhs else ta_bo.lhs;
    const k = triangularKOf(ctx, addend, nt.inner_iv, plan.iv) orelse return null;
    if (nt.k_lit) |kl| {
        if (k.lit != kl) return null;
    } else {
        const kn = nt.k_name orelse return null;
        const k2n = k.name orelse return null;
        if (!std.mem.eql(u8, kn, k2n)) return null;
    }
    // The proof holds. Emit the closed form.
    // Push an empty break list so finishWhileLowering's pop balances.
    try ctx.loop_breaks.append(ctx.alloc, std.ArrayListUnmanaged(u32).empty);
    const acc_slot = ctx.locals.get(nt.outer_acc) orelse return null;
    const iv_slot = ctx.locals.get(plan.iv) orelse return null;
    const tri_mn = nt.tri_m *% nt.tri_n;
    if (n_outer > 0) {
        if (nt.k_lit) |kl| {
            const total = kl *% tri_mn;
            const sum = ctx.freshTemp();
            try ctx.emit(.{ .op = .binop, .result = sum, .binop = .add, .lhs = .{ .local = acc_slot }, .rhs = .{ .i64 = total }, .ty = .i64 });
            try ctx.emit(.{ .op = .store_local, .result = acc_slot, .lhs = .{ .temp = sum }, .ty = .i64 });
        } else {
            const cn = nt.k_name orelse return null;
            const c_slot = ctx.locals.get(cn) orelse return null;
            const t1 = ctx.freshTemp();
            try ctx.emit(.{ .op = .binop, .result = t1, .binop = .mul, .lhs = .{ .local = c_slot }, .rhs = .{ .i64 = tri_mn }, .ty = .i64 });
            const sum = ctx.freshTemp();
            try ctx.emit(.{ .op = .binop, .result = sum, .binop = .add, .lhs = .{ .local = acc_slot }, .rhs = .{ .temp = t1 }, .ty = .i64 });
            try ctx.emit(.{ .op = .store_local, .result = acc_slot, .lhs = .{ .temp = sum }, .ty = .i64 });
        }
    }
    const iv_dead = nameDeadAfterFold(ctx, plan.iv, plan.stmt);
    const inner_iv_dead = nameDeadAfterFold(ctx, nt.inner_iv, plan.stmt);
    const inner_acc_dead = nameDeadAfterFold(ctx, nt.inner_acc, plan.stmt);
    if (n_outer > 0 and !iv_dead) {
        try ctx.emit(.{ .op = .store_local, .result = iv_slot, .lhs = .{ .i64 = n_outer }, .ty = .i64 });
    }
    // The inner induction variable and accumulator need slots only for a live
    // write-back; mirror the nested-direct get-or-materialize so an
    // unshadowed module global declines instead of diverging.
    if (n_outer > 0 and !inner_iv_dead) {
        const j_slot: u32 = if (ctx.locals.get(nt.inner_iv)) |s| s else blk: {
            if (ctx.module_globals.types.get(nt.inner_iv) != null) return null;
            const s = ctx.freshTemp();
            try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, nt.inner_iv), s);
            break :blk s;
        };
        try ctx.emit(.{ .op = .store_local, .result = j_slot, .lhs = .{ .i64 = nt.inner_bound_lit }, .ty = .i64 });
    }
    if (n_outer > 0 and !inner_acc_dead) {
        const t_slot: u32 = if (ctx.locals.get(nt.inner_acc)) |s| s else blk: {
            if (ctx.module_globals.types.get(nt.inner_acc) != null) return null;
            const s = ctx.freshTemp();
            try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, nt.inner_acc), s);
            break :blk s;
        };
        if (nt.k_lit) |kl| {
            const tv = kl *% (n_outer - 1) *% nt.tri_m;
            try ctx.emit(.{ .op = .store_local, .result = t_slot, .lhs = .{ .i64 = tv }, .ty = .i64 });
        } else {
            const cn = nt.k_name orelse return null;
            const c_slot = ctx.locals.get(cn) orelse return null;
            const t1 = ctx.freshTemp();
            try ctx.emit(.{ .op = .binop, .result = t1, .binop = .mul, .lhs = .{ .local = c_slot }, .rhs = .{ .i64 = n_outer - 1 }, .ty = .i64 });
            const t2 = ctx.freshTemp();
            try ctx.emit(.{ .op = .binop, .result = t2, .binop = .mul, .lhs = .{ .temp = t1 }, .rhs = .{ .i64 = nt.tri_m }, .ty = .i64 });
            try ctx.emit(.{ .op = .store_local, .result = t_slot, .lhs = .{ .temp = t2 }, .ty = .i64 });
        }
    }
    return .{ .iv_dead = iv_dead, .inner_iv_dead = inner_iv_dead, .inner_acc_dead = inner_acc_dead };
}

/// If `st` is `name = name + 1` (or `1 + name`) with no mention of `forbidden`,
/// returns `name`. Otherwise null.
fn accNameOfIncrement(st: *const ast.Stmt, forbidden: []const u8) ?[]const u8 {
    const as = switch (st.*) {
        .assign => |a| a,
        else => return null,
    };
    if (as.targets.len != 1 or as.values.len != 1) return null;
    const tname = identOf(as.targets[0]) orelse return null;
    if (ast.stmtMentionsIdent(st, forbidden)) return null;
    const bo = switch (as.values[0].*) {
        .binop => |x| x,
        else => return null,
    };
    if (bo.op != .add) return null;
    const is_one = struct {
        fn f(e: *const ast.Expr) bool {
            return switch (e.*) {
                .int_lit => |l| l.val == 1,
                else => false,
            };
        }
    }.f;
    if (is_one(bo.lhs)) {
        if (identOf(bo.rhs)) |rn| if (std.mem.eql(u8, rn, tname)) return tname;
    }
    if (is_one(bo.rhs)) {
        if (identOf(bo.lhs)) |ln| if (std.mem.eql(u8, ln, tname)) return tname;
    }
    return null;
}

const CountedResult = struct { latch_fail: usize, wb_idx: usize };
fn lowerCountedWhile(ctx: *LowerCtx, ws: anytype, plan: CountedPlan) Error!?CountedResult {
    // Re-verify the condition shape against the plan: the prologue armed it,
    // the arm consumes it, and a loop rewritten in between declines here
    // rather than emitting for a different shape.
    const b = switch (ws.cond.*) {
        .binop => |x| x,
        else => return null,
    };
    if (b.op != .lt) return null;
    const iv = identOf(b.lhs) orelse return null;
    if (!std.mem.eql(u8, iv, plan.iv)) return null;
    if (plan.bound_lit) |n| {
        if (ctx.graph.exactI64OfExpr(b.rhs) != @as(?i64, n)) return null;
    } else if (plan.bound_name) |bn| {
        const rhs_name = identOf(b.rhs) orelse return null;
        if (!std.mem.eql(u8, rhs_name, bn)) return null;
    } else return null;
    // The induction variable's slot: a promoted module binding or a lexical
    // local. Anything else (an unpromoted module binding, a fused literal)
    // declines.
    const iv_slot = ctx.locals.get(plan.iv) orelse return null;
    // Body legality: exactly one write to the induction variable (the terminal
    // step), no reads of it, no calls, no storage touched twice, no exits.
    // `unrollScanBlock` refuses every statement kind that can leave the body,
    // call, or touch storage twice; the pass below refuses reads of the
    // induction variable, which would observe the countdown's reversed trip
    // values.
    var scan: UnrollBodyScan = .{};
    unrollScanBlock(ctx, &ws.body, plan.iv, plan.bound_name, &scan);
    if (!scan.ok) return null;
    const body_n = ws.body.stmts.len;
    if (body_n == 0 or ws.body.tail_expr != null) return null;
    if (scan.iv_writes != 1) return null;
    if (!stepIsIncrementOfOne(ctx.graph, &ws.body.stmts[body_n - 1], plan.iv)) return null;
    for (ws.body.stmts[0 .. body_n - 1]) |*s| {
        if (ast.stmtMentionsIdent(s, plan.iv)) return null;
    }

    // ALL CHECKS PASSED — emit the countdown.
    try ctx.loop_breaks.append(ctx.alloc, std.ArrayListUnmanaged(u32).empty);
    const bound_v = try lowerExpr(ctx, b.rhs);
    const n = ctx.freshTemp();
    try ctx.emit(.{ .op = .store_local, .result = n, .lhs = bound_v, .ty = .i64 });
    // Cold pre-guard: the source loop runs zero times when the bound is zero;
    // a bare do-while would run the body once.
    const pre_t = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = pre_t, .binop = .neq, .lhs = .{ .local = n }, .rhs = .{ .i64 = 0 } });
    const pre_fail = ctx.instrs.items.len;
    try ctx.emit(.{ .op = .br, .lhs = .{ .temp = pre_t }, .branch_target = 0, .branch_condition = .when_false });
    const head_idx: u32 = @intCast(ctx.instrs.items.len);
    try ctx.loop_heads.append(ctx.alloc, head_idx);
    defer _ = ctx.loop_heads.pop();
    // The body minus its terminal step, lowered exactly as the ordinary loop
    // would lower it.
    var sub = ws.body;
    sub.stmts = ws.body.stmts[0 .. body_n - 1];
    _ = try lowerBlockReturns(ctx, &sub, false);
    // Countdown latch: n -= 1; loop while n != 0.
    const dec = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = dec, .binop = .sub, .lhs = .{ .local = n }, .rhs = .{ .i64 = 1 } });
    try ctx.emit(.{ .op = .store_local, .result = n, .lhs = .{ .temp = dec }, .ty = .i64 });
    const latch_t = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = latch_t, .binop = .neq, .lhs = .{ .local = n }, .rhs = .{ .i64 = 0 } });
    const latch_fail = ctx.instrs.items.len;
    try ctx.emit(.{ .op = .br, .lhs = .{ .temp = latch_t }, .branch_target = 0, .branch_condition = .when_false });
    try ctx.emit(.{ .op = .br, .branch_target = head_idx });
    // The source loop exits with iv == bound. The write-back sits BEFORE the
    // shared exit target so the latch's failing branch lands on it; the
    // pre-guard's target stays past it (bound == 0 leaves iv at 0 either way).
    const wb_idx = ctx.instrs.items.len;
    try ctx.emit(.{ .op = .store_local, .result = iv_slot, .lhs = bound_v, .ty = .i64 });
    ctx.instrs.items[pre_fail].branch_target = @intCast(ctx.instrs.items.len);
    return .{ .latch_fail = latch_fail, .wb_idx = wb_idx };
}

/// `name = <int literal>` as the whole of `st`, or null.
///
/// The start index is read from the STATEMENT IMMEDIATELY BEFORE THE LOOP, not
/// from `ctx.const_ints`. That map records a name's last literal binding and is
/// never invalidated by a non-literal reassignment, so after `i = 1 ; i = i + 5`
/// it still answers 1. Reading it here would start the vector run at the wrong
/// element and produce a wrong answer that still compiles — the exact failure
/// mode this beachhead is required to avoid. The preceding statement is the one
/// place where the literal is provably the current value.
fn literalBindingOf(graph: *const semantic_graph.SemanticGraph, st: *const ast.Stmt, name: []const u8) ?i64 {
    switch (st.*) {
        .assign => |a| {
            if (a.targets.len != 1 or a.values.len != 1) return null;
            const t = identOf(a.targets[0]) orelse return null;
            if (!std.mem.eql(u8, t, name)) return null;
            return graph.exactI64OfExpr(a.values[0]);
        },
        .local_decl => |d| {
            if (d.names.len != 1 or d.inits.len != 1) return null;
            if (!std.mem.eql(u8, d.names[0].ident, name)) return null;
            return graph.exactI64OfExpr(d.inits[0]);
        },
        else => return null,
    }
}

/// True when `slot` holds something other than a plain i64.
fn slotIsNonInteger(ctx: *const LowerCtx, slot: u32) bool {
    return ctx.f64_slots.contains(slot) or
        ctx.str_slots.contains(slot) or
        ctx.bool_slots.contains(slot) or
        ctx.ptr_slots.contains(slot);
}

/// THE BEACHHEAD. Emit a NEON prologue for
///
///     idx = LO
///     while idx <= HI
///         acc = acc + tbl[idx]
///         idx = idx + 1
///
/// and nothing else. `stmts[at]` is the loop; `stmts[at - 1]` supplies `LO`.
///
/// The prologue is ADDITIVE: it sums a whole number of LANE-SIZED groups into
/// `acc`, advances `idx` past them, and then the ordinary scalar lowering of the
/// SAME loop runs unchanged and finishes the (at most one) remaining element.
/// Nothing is replaced, so every existing behaviour of that loop — bounds
/// handling, break/continue, the value of `idx` on exit — is whatever it already
/// was. When any condition below fails, this emits nothing at all and the loop
/// lowers exactly as it does today.
///
/// What has to be true, and where each fact comes from:
///
///   CONTIGUITY and ELEMENT TYPE — `tbl` resolves to a `ptr_slot`, i.e. an
///   `alloc_slots` region of 8-byte words. That representation was chosen at the
///   BINDING (`lowerPositionalTableIntoMemory`, or `materializeTableSlots` which
///   rebinds the name), never here. This pass only READS the decision; a
///   register-exploded table is declined, not materialized, so no copy can be
///   emitted at an access site and no loop can restore a table to its initial
///   value.
///
///   EXTENT — `tbl.len` carries the static element count, so `1 <= LO` and
///   `HI <= len` prove every lane load is in bounds without a per-element guard.
///
///   ASSOCIATIVITY — i64 addition. Two's-complement `add` is associative and
///   commutative including on overflow, and `add.2d` wraps identically to `add`,
///   so regrouping the summation is EXACT. This is why the case is integer and
///   not float: a float reduction reassociated this way changes the answer, and
///   that would need an explicit fact this compiler does not have.
///
///   REPRESENTATION UNIFORMITY — no BINDING changes representation. `acc` and
///   `idx` stay ordinary integer locals for the whole function; the vector
///   accumulator is a register private to one instruction's expansion, created
///   and consumed inside it, and never named by any slot.
///
/// CLAIM PROTOCOL — returns true when the prologue fired, claiming
/// `stmts[at]`; a claimed statement's semantics are discharged, so
/// structural loop transforms must not re-claim it.
fn tryEmitVectorReductionPrologue(ctx: *LowerCtx, stmts: []const ast.Stmt, at: usize) Error!bool {
    if (at == 0) return false;
    const ws = switch (stmts[at]) {
        .while_loop => |w| w,
        else => return false,
    };
    // Exactly the two statements, and no tail expression. Anything else in the
    // body could read `acc`, rebind `idx`, or store into `tbl`, and each of
    // those makes the regrouping observable.
    if (ws.body.tail_expr != null) return false;
    if (ws.body.stmts.len != 2) return false;

    const step = reduceStep(&ws.body.stmts[0]) orelse return false;
    if (!stepIsIncrementOfOne(ctx.graph, &ws.body.stmts[1], step.idx)) return false;
    if (std.mem.eql(u8, step.acc, step.idx)) return false;
    if (std.mem.eql(u8, step.acc, step.tbl)) return false;
    if (std.mem.eql(u8, step.idx, step.tbl)) return false;

    const hi = loopUpperBound(ctx.graph, ws.cond, step.idx) orelse return false;
    const lo = literalBindingOf(ctx.graph, &stmts[at - 1], step.idx) orelse return false;
    if (lo < 1 or hi < lo) return false;

    const base_slot = ctx.locals.get(step.tbl) orelse return false;
    if (!ctx.ptr_slots.contains(base_slot)) return false;

    var key_buf: [512]u8 = undefined;
    const len_key = std.fmt.bufPrint(&key_buf, "{s}.len", .{step.tbl}) catch return false;
    const len_slot = ctx.locals.get(len_key) orelse return false;
    const len = ctx.table_lens.get(len_slot) orelse return false;
    if (hi > len) return false;

    const acc_slot = ctx.locals.get(step.acc) orelse return false;
    if (slotIsNonInteger(ctx, acc_slot)) return false;
    const idx_slot = ctx.locals.get(step.idx) orelse return false;
    if (slotIsNonInteger(ctx, idx_slot)) return false;
    if (acc_slot == idx_slot or acc_slot == base_slot or idx_slot == base_slot) return false;

    // Whole lane groups only. A trip count below one group (which includes the
    // empty range) leaves this to the scalar loop entirely.
    const count = hi - lo + 1;
    const vectored = @divTrunc(count, vec_i64_lanes) * vec_i64_lanes;
    if (vectored < vec_i64_lanes) return false;

    const sum = ctx.freshTemp();
    try ctx.emit(.{
        .op = .hw_unary,
        .hw = .none,
        .field = vec_reduce_add_i64_tag,
        .ty = .i64,
        .result = sum,
        .lhs = .{ .local = base_slot },
        .rhs = .{ .i64 = lo },
        .third = .{ .i64 = vectored },
    });
    const folded = ctx.freshTemp();
    try ctx.emit(.{
        .op = .binop,
        .result = folded,
        .binop = .add,
        .lhs = .{ .local = acc_slot },
        .rhs = .{ .temp = sum },
        .ty = .any,
    });
    try ctx.emit(.{ .op = .store_local, .result = acc_slot, .lhs = .{ .temp = folded }, .ty = .any });
    try ctx.emit(.{ .op = .store_local, .result = idx_slot, .lhs = .{ .i64 = lo + vectored }, .ty = .any });

    // `idx` is no longer the literal the preceding statement bound. Dropping the
    // entry keeps `const_ints` from answering `LO` for it downstream; every
    // consumer of that map treats a miss as "not compile-time known" and stays
    // conservative.
    if (ctx.const_ints.fetchRemove(step.idx)) |kv| ctx.alloc.free(kv.key);
    return true;
}

/// Additive lowering prologues, tried in order; at most one fires per
/// statement. Returns whether a prologue claimed `stmts[at]`: a claimed
/// statement's semantics are discharged up front, so structural loop
/// transforms must not re-claim it — their arming is skipped when this
/// returns true (the counted-loop arming takes that guard at its merge).
/// `x = x & 0x7FFFFFFFFFFFFFFF` IDENTITY SKIP.
///
/// When the value of `x` at this point is provably non-negative with width
/// <= 63, masking with INT64_MAX is identity (x in [0, 2^63)), so the
/// statement is skipped instead of emitted. The width proof is the
/// established producer fact (`nonNegativeWidthOfExpr` on the name) with
/// the defining-assignment backward scan (`loopSelectSynWidth`) as the
/// fallback; anything unproved declines. Either operand order is accepted.
/// Tail-position statements decline: skipping must not drop a block value.
/// Value in one sentence: "a provably-redundant x & INT64_MAX mask is not
/// emitted."
fn trySkipInt64MaxMask(ctx: *LowerCtx, stmts: []const ast.Stmt, at: usize, is_tail: bool) Error!bool {
    if (is_tail) return false;
    const a = switch (stmts[at]) {
        .assign => |x| x,
        else => return false,
    };
    if (a.targets.len != 1 or a.values.len != 1) return false;
    const x = identOf(a.targets[0]) orelse return false;
    const b = switch (a.values[0].*) {
        .binop => |bb| bb,
        else => return false,
    };
    if (b.op != .band) return false;
    const mask_is_int64max: bool = blk: {
        if (isIdent(b.lhs, x)) {
            const m = ctx.graph.exactI64OfExpr(b.rhs) orelse break :blk false;
            break :blk m == 0x7FFFFFFFFFFFFFFF;
        }
        if (isIdent(b.rhs, x)) {
            const m = ctx.graph.exactI64OfExpr(b.lhs) orelse break :blk false;
            break :blk m == 0x7FFFFFFFFFFFFFFF;
        }
        break :blk false;
    };
    if (!mask_is_int64max) return false;
    const relation = ctx.function orelse return false;
    // The producer's name width is a sound whole-relation over-approximation
    // at any point; the defining-assignment scan is the point-precise
    // fallback. Either proving width <= 63 makes the mask identity.
    if (ctx.graph.nonNegativeWidthOfExpr(relation, a.targets[0])) |w| {
        if (w <= 63) return true;
    }
    if (loopSelectSynWidth(ctx, stmts, at, relation, a.targets[0], 0)) |w| {
        if (w <= 63) return true;
    }
    return false;
}

/// POPCOUNT IDIOM -> HARDWARE POPCOUNT.
///
/// Recognizes the six-statement SWAR popcount idiom (Hacker's Delight 5-1):
///
///     x = x - ((x / 2) & 0x5555555555555555)
///     x = (x & 0x3333333333333333) + ((x / 4) & 0x3333333333333333)
///     x = (x + (x / 16)) & 0x0F0F0F0F0F0F0F0F
///     x = x + (x / 256)
///     x = x + (x / 65536)
///     x = x + (x / 4294967296)
///
/// and replaces it with a single `.hw_unary .popcount`. The divisions are
/// SIGNED (`/`), so the transform is valid only when the value entering the
/// idiom is non-negative (then each `/ 2^k` is a logical shift). That fact
/// must come from the graph: the statement immediately preceding the idiom
/// has to be `x = <rhs>` with `nonNegativeWidthOfExpr` proving `<rhs>`
/// non-negative. When any condition fails this emits nothing and returns
/// false; the statements lower through the normal path unchanged.
///
/// Each halving step is accepted in two spellings: signed `x / 2^k` or
/// logical `x >> k`. The shift spelling is sound under the same entry
/// precondition: every SWAR step output is a vector of non-negative
/// bit-counts, so each step's input is non-negative and the two spellings
/// coincide on every reachable value.
///
/// On success the six SWAR statements are discharged up front: the popcount
/// is emitted and stored to `x`, and the six statements are recorded in
/// `popcount_swallowed` so the block loop skips them. The trailing
/// x = x & k (0 <= k <= 127) is required for soundness; for k == 127 it
/// is also swallowed (identity on the clean hardware popcount [0,64]);
/// for k < 127 it lowers normally and executes on the clean popcount.

/// Sound because for k <= 127, raw & k == popcount & k: k < 128, so only
/// the low 7 bits of the raw result affect the mask, and they hold the
/// true count. Without the mask the raw idiom upper-bit garbage is
/// observably different from a clean popcount, so unmasked idioms decline.
fn tryEmitPopcountIdiom(ctx: *LowerCtx, stmts: []const ast.Stmt, at: usize) Error!bool {
    if (at == 0 or at + 7 > stmts.len) return false;
    const graph = ctx.graph;

    // All six must be `x = <expr>` for the same `x`, each matching its step.
    var x_name: ?[]const u8 = null;
    for (stmts[at .. at + 6], 0..) |*st, k| {
        const a = switch (st.*) {
            .assign => |x| x,
            else => return false,
        };
        if (a.targets.len != 1 or a.values.len != 1) return false;
        const name = identOf(a.targets[0]) orelse return false;
        if (x_name == null) {
            x_name = name;
        } else if (!std.mem.eql(u8, x_name.?, name)) {
            return false;
        }
        if (!popcountStepMatches(graph, a.values[0], name, k)) return false;
    }
    const x = x_name.?;

    // The entry value comes from the immediately preceding `x = <rhs>`.
    const prev = switch (stmts[at - 1]) {
        .assign => |p| p,
        else => return false,
    };
    if (prev.targets.len != 1 or prev.values.len != 1) return false;
    const prev_name = identOf(prev.targets[0]) orelse return false;
    if (!std.mem.eql(u8, prev_name, x)) return false;
    const relation = ctx.function orelse return false;
    if (ctx.graph.nonNegativeWidthOfExpr(relation, prev.values[0]) == null) return false;

    // 64-bit idiom on a narrowed slot would count garbage high bits.
    const x_slot = ctx.locals.get(x) orelse return false;
    if (ctx.narrow_slots.contains(x_slot)) return false;

    // SOUNDNESS: the six SWAR steps leave partial-sum garbage in the upper
    // 57 bits; only the low 7 hold the count. Replacing the idiom with a
    // clean hardware popcount is observably different unless the very next
    // statement masks x to 7 bits (`x = x & k` with 0 <= k <= 127, either
    // operand order). The bench program does `x = x & 127`; without such a
    // mask this declines and the idiom lowers literally.
    const mask_a = switch (stmts[at + 6]) {
        .assign => |m| m,
        else => return false,
    };
    if (mask_a.targets.len != 1 or mask_a.values.len != 1) return false;
    const mask_name = identOf(mask_a.targets[0]) orelse return false;
    if (!std.mem.eql(u8, mask_name, x)) return false;
    const mask_bin = switch (mask_a.values[0].*) {
        .binop => |bb| bb,
        else => return false,
    };
    if (mask_bin.op != .band) return false;
    const mask_val: i64 = blk: {
        if (isIdent(mask_bin.lhs, x)) break :blk graph.exactI64OfExpr(mask_bin.rhs) orelse return false;
        if (isIdent(mask_bin.rhs, x)) break :blk graph.exactI64OfExpr(mask_bin.lhs) orelse return false;
        return false;
    };
    if (mask_val < 0 or mask_val > 127) return false;

    // t = popcount(x); x = t.
    const t = ctx.freshTemp();
    try ctx.emit(.{
        .op = .hw_unary,
        .hw = .popcount,
        .result = t,
        .lhs = .{ .local = x_slot },
        .ty = .i64,
    });
    try ctx.emit(.{ .op = .store_local, .result = x_slot, .lhs = .{ .temp = t }, .ty = .any });

    // Swallow the six SWAR steps. The trailing mask is swallowed only when
    // it is a no-op on a clean hardware popcount: x = x & 127 is identity
    // for every reachable x in [0,64]. Swallowing the mask is unsound for
    // k < 127, so only k == 127. The current statement (at) is swallowed
    // too, and the post-prologue check below skips its lowerStmt.
    for (stmts[at .. at + 6]) |*st| {
        try ctx.popcount_swallowed.put(ctx.alloc, st, {});
    }
    if (mask_val == 127) {
        try ctx.popcount_swallowed.put(ctx.alloc, &stmts[at + 6], {});
    }

    // `x` is rebound; drop the stale const fact.
    if (ctx.const_ints.fetchRemove(x)) |kv| ctx.alloc.free(kv.key);
    return true;
}

/// Step `k` (0-5) of the SWAR popcount idiom, or false. Masks and divisors
/// are graph exact-i64 facts; the AST supplies only shape and name identity.
/// Commuted operand orders are accepted; anything else declines.
fn popcountStepMatches(graph: *const semantic_graph.SemanticGraph, e: *const ast.Expr, x: []const u8, k: usize) bool {
    const b = switch (e.*) {
        .binop => |bb| bb,
        else => return false,
    };
    return switch (k) {
        // x = x - ((x / 2) & 0x5555555555555555)
        0 => b.op == .sub and isIdent(b.lhs, x) and isMaskedDiv(graph, b.rhs, x, 2, 0x5555555555555555),
        // x = (x & 0x3333333333333333) + ((x / 4) & 0x3333333333333333)
        1 => b.op == .add and isMaskedIdent(graph, b.lhs, x, 0x3333333333333333) and
            isMaskedDiv(graph, b.rhs, x, 4, 0x3333333333333333),
        // x = (x + (x / 16)) & 0x0F0F0F0F0F0F0F0F
        2 => b.op == .band and isMask(graph, b.rhs, 0x0F0F0F0F0F0F0F0F) and isShiftAdd(b.lhs, x, 16),
        // x = x + (x / 256)
        3 => b.op == .add and isIdent(b.lhs, x) and isHalving(b.rhs, x, 256),
        // x = x + (x / 65536)
        4 => b.op == .add and isIdent(b.lhs, x) and isHalving(b.rhs, x, 65536),
        // x = x + (x / 4294967296)
        5 => b.op == .add and isIdent(b.lhs, x) and isHalving(b.rhs, x, 4294967296),
        else => false,
    };
}

/// `e` is the identifier `x`.
fn isIdent(e: *const ast.Expr, x: []const u8) bool {
    const n = identOf(e) orelse return false;
    return std.mem.eql(u8, n, x);
}

/// `e` is `x / k` with a SIGNED division.
fn isDivBy(e: *const ast.Expr, x: []const u8, k: i64) bool {
    const b = switch (e.*) {
        .binop => |bb| bb,
        else => return false,
    };
    if (b.op != .div) return false;
    if (!isIdent(b.lhs, x)) return false;
    const d = ast.intLiteralValue(b.rhs) orelse return false;
    return d == k;
}

/// `e` is `x >> s` with s = log2(k): the logical-shift spelling of the
/// SWAR halving step for divisor k. Sound under the idiom's entry
/// precondition (documented above): each step's input is non-negative, so
/// the logical shift coincides with the truncating division.
fn isShrBy(e: *const ast.Expr, x: []const u8, k: i64) bool {
    const b = switch (e.*) {
        .binop => |bb| bb,
        else => return false,
    };
    if (b.op != .rshift) return false;
    if (!isIdent(b.lhs, x)) return false;
    const sh = ast.intLiteralValue(b.rhs) orelse return false;
    const want: i64 = switch (k) {
        2 => 1,
        4 => 2,
        16 => 4,
        256 => 8,
        65536 => 16,
        4294967296 => 32,
        else => return false,
    };
    return sh == want;
}

/// `e` is the SWAR halving step in either spelling: signed `x / 2^k` or
/// logical `x >> k`.
fn isHalving(e: *const ast.Expr, x: []const u8, k: i64) bool {
    return isDivBy(e, x, k) or isShrBy(e, x, k);
}

/// `e` has exact i64 value `mask`.
fn isMask(graph: *const semantic_graph.SemanticGraph, e: *const ast.Expr, mask: i64) bool {
    return graph.exactI64OfExpr(e) == mask;
}

/// `e` is `(x / k) & mask` in either `&` order.
fn isMaskedDiv(graph: *const semantic_graph.SemanticGraph, e: *const ast.Expr, x: []const u8, k: i64, mask: i64) bool {
    const b = switch (e.*) {
        .binop => |bb| bb,
        else => return false,
    };
    if (b.op != .band) return false;
    if (isHalving(b.lhs, x, k) and isMask(graph, b.rhs, mask)) return true;
    if (isHalving(b.rhs, x, k) and isMask(graph, b.lhs, mask)) return true;
    return false;
}

/// `e` is `x & mask` in either `&` order.
fn isMaskedIdent(graph: *const semantic_graph.SemanticGraph, e: *const ast.Expr, x: []const u8, mask: i64) bool {
    const b = switch (e.*) {
        .binop => |bb| bb,
        else => return false,
    };
    if (b.op != .band) return false;
    if (isIdent(b.lhs, x) and isMask(graph, b.rhs, mask)) return true;
    if (isIdent(b.rhs, x) and isMask(graph, b.lhs, mask)) return true;
    return false;
}

/// `e` is `x + (x / k)` in either `+` order.
fn isShiftAdd(e: *const ast.Expr, x: []const u8, k: i64) bool {
    const b = switch (e.*) {
        .binop => |bb| bb,
        else => return false,
    };
    if (b.op != .add) return false;
    if (isIdent(b.lhs, x) and isHalving(b.rhs, x, k)) return true;
    if (isIdent(b.rhs, x) and isHalving(b.lhs, x, k)) return true;
    return false;
}

/// ZERO-OR-ONE-TRIP LOOP → BRANCHLESS IF.
///
/// Recognizes
///
///     iv = 0                  (stmts[at-1])
///     while iv < bound         (stmts[at]; bound provably <= 1 via width)
///         acc = acc + <const>
///         iv = 1
///
/// and emits
///
///     cond = (0 < bound)
///     if cond { acc = acc + const }   (W7 if-converts to csel)
///     iv = cond
///
/// The `if` uses the ordinary one-sided branch shape so W7 if-conversion
/// makes it a `csel` with no new backend code. The `iv` store sets the exact
/// post-loop value (0 when bound <= 0, 1 when bound == 1); the loop that
/// lowers next sees its trip test false on entry and runs zero times.
///
/// SOUNDNESS: `bound <= 1` is load-bearing. If bound >= 2 the source loop
/// does not terminate (iv resets to 1, and 1 < bound stays true), so the
/// width proof is a termination proof, not just a bound.
/// True when executing `st` might rebind `name`: an assignment to it, a
/// declaration of it, any call (which can rebind a module binding), or any
/// statement shape this check does not model (fail closed). Pure control flow
/// (break/continue/goto/labels) and call-free expressions do not rebind. The
/// loopselect defining-RHS scan skips a statement only when this answers
/// false, so the nearest dominating assignment it finds truly dominates.
fn stmtMayRebind(st: *const ast.Stmt, name: []const u8) bool {
    return switch (st.*) {
        .assign => |a| {
            for (a.targets) |t| {
                if (identOf(t)) |tn| {
                    if (std.mem.eql(u8, tn, name)) return true;
                } else return true;
            }
            for (a.values) |v| if (exprHasCall(v)) return true;
            return false;
        },
        .call_stmt => true,
        .expr_stmt => |x| return exprHasCall(x.expr),
        .local_decl => |d| {
            for (d.names) |n| if (std.mem.eql(u8, n.ident, name)) return true;
            for (d.inits) |v| if (exprHasCall(v)) return true;
            return false;
        },
        .const_decl => |d| {
            if (std.mem.eql(u8, d.ident, name)) return true;
            return exprHasCall(d.val);
        },
        .global_decl => |d| {
            for (d.names) |n| if (std.mem.eql(u8, n.ident, name)) return true;
            for (d.inits) |v| if (exprHasCall(v)) return true;
            return false;
        },
        .do_block => |d| return blockMayRebind(&d.body, name),
        .while_loop => |w| return exprHasCall(w.cond) or blockMayRebind(&w.body, name),
        .repeat_loop => |r| return exprHasCall(r.cond) or blockMayRebind(&r.body, name),
        .if_stmt => |f| {
            if (exprHasCall(f.cond)) return true;
            if (f.binding) |b| {
                if (std.mem.eql(u8, b.name, name)) return true;
                if (exprHasCall(b.expr)) return true;
            }
            if (blockMayRebind(&f.then, name)) return true;
            for (f.elseifs) |ei| {
                if (exprHasCall(ei.cond)) return true;
                if (blockMayRebind(&ei.body, name)) return true;
            }
            if (f.else_body) |eb| if (blockMayRebind(&eb, name)) return true;
            return false;
        },
        .num_for => |f| {
            if (std.mem.eql(u8, f.var_name, name)) return true;
            if (exprHasCall(f.start) or exprHasCall(f.stop)) return true;
            if (f.step) |sp| if (exprHasCall(sp)) return true;
            return blockMayRebind(&f.body, name);
        },
        .gen_for => |f| {
            for (f.vars) |v| if (std.mem.eql(u8, v, name)) return true;
            for (f.iters) |it| if (exprHasCall(it)) return true;
            return blockMayRebind(&f.body, name);
        },
        .brk, .cont, .goto_stmt, .label_stmt => false,
        .ret => |r| {
            for (r.vals) |v| if (exprHasCall(v)) return true;
            return false;
        },
        else => true,
    };
}

fn blockMayRebind(blk: *const ast.Block, name: []const u8) bool {
    for (blk.stmts) |*st| if (stmtMayRebind(st, name)) return true;
    return false;
}

/// The literal the iv is bound to at the loop: the nearest dominating
/// `iv = <int literal>` scanning back from `at`, skipping statements that
/// provably cannot rebind the iv (fail closed on anything else). The init
/// need not sit immediately before the loop -- the bound's own definition may
/// sit between, as in `k = 0; m = 1 - c; while k < m`. Answers null when no
/// dominating literal binding exists.
fn loopSelectIvInit(ctx: *LowerCtx, stmts: []const ast.Stmt, at: usize, iv: []const u8) ?i64 {
    var i = at;
    while (i > 0) {
        i -= 1;
        const st = stmts[i];
        if (literalBindingOf(ctx.graph, &st, iv)) |lit| return lit;
        if (stmtMayRebind(&st, iv)) return null;
    }
    return null;
}

/// The loopselect bound width. The producer's name-keyed lattice is
/// flow-insensitive and join-widened, so a name rebound wide-then-narrow
/// (`c = wide; c = c & 1`) publishes the WIDE width at the loop even though
/// the value there is the narrow RHS. When the producer's name query cannot
/// prove width <= 1, scan stmts[..at] backward for the nearest dominating
/// `bound = RHS` assignment: every statement between it and the loop must be
/// a plain single-target `.assign` with a call-free value (a call could
/// rebind a module binding -- fail closed), and then the bound at the loop IS
/// the RHS value. The width is computed syntactically from the RHS with names
/// resolved to THEIR defining assignments (same dominance argument,
/// recursively; statement indices strictly decrease, so it terminates). A
/// name with no defining assignment in the scanned prefix falls back to the
/// published column -- a sound whole-body over-approximation at any point.
/// The producer query runs first (the established fact); the scan is the
/// fallback. Precedent: sataddSynWidth.
fn loopSelectBoundWidth(
    ctx: *LowerCtx,
    stmts: []const ast.Stmt,
    at: usize,
    relation: semantic_graph.id,
    bound_expr: *const ast.Expr,
) ?u8 {
    if (ctx.graph.nonNegativeWidthOfExpr(relation, bound_expr)) |w| {
        if (w <= 1) return w;
    }
    return loopSelectSynWidth(ctx, stmts, at, relation, bound_expr, 0);
}

/// Syntactic non-negative width over the backward scan. Arms mirror the
/// range.zig transfer for exactly the shapes the two consumers need:
/// int literals, names (via their defining assignment), bitwise-and (the
/// narrower side survives; a literal mask bounds the result), the `L - x`
/// rule, and bounded-growth `.add`/`.mul` (clamped to <= 63 like every
/// widthOfExprIn answer). Anything else answers null -- fail closed.
fn loopSelectSynWidth(
    ctx: *LowerCtx,
    stmts: []const ast.Stmt,
    up_to: usize,
    relation: semantic_graph.id,
    expr: *const ast.Expr,
    depth: u8,
) ?u8 {
    if (depth > 32) return null;
    const graph = ctx.graph;
    switch (expr.*) {
        .int_lit => |l| {
            if (l.val < 0) return null;
            var w: u8 = 0;
            var n: u64 = @intCast(l.val);
            while (n != 0) : (n >>= 1) w += 1;
            return w;
        },
        .name => |n| {
            var i = up_to;
            while (i > 0) {
                i -= 1;
                const st = stmts[i];
                // The defining assignment itself must be recognized before the
                // rebind check: assigning the name is what we are looking for.
                // Its value must be call-free (a call could rebind a module
                // binding mid-evaluation).
                if (st == .assign and st.assign.targets.len == 1 and st.assign.values.len == 1) {
                    if (identOf(st.assign.targets[0])) |t| {
                        if (std.mem.eql(u8, t, n.ident)) {
                            if (exprHasCall(st.assign.values[0])) break;
                            return loopSelectSynWidth(ctx, stmts, i, relation, st.assign.values[0], depth + 1);
                        }
                    }
                }
                // Not the definition: skip only statements that provably
                // cannot rebind the name; anything else ends the scan
                // (fail closed).
                if (stmtMayRebind(&st, n.ident)) break;
            }
            return graph.nonNegativeWidthOfExpr(relation, expr);
        },
        .binop => |b| {
            if (b.op == .band) {
                const x = loopSelectSynWidth(ctx, stmts, up_to, relation, b.lhs, depth + 1);
                const y = loopSelectSynWidth(ctx, stmts, up_to, relation, b.rhs, depth + 1);
                if (x == null) return y;
                if (y == null) return x;
                return @min(x.?, y.?);
            }
            if (b.op == .sub) {
                const L = ast.intLiteralValue(b.lhs) orelse return null;
                if (L < 0) return null;
                const w = loopSelectSynWidth(ctx, stmts, up_to, relation, b.rhs, depth + 1) orelse return null;
                if (w > 63) return null;
                const pow2w: u64 = @as(u64, 1) << @intCast(w);
                if (pow2w > @as(u64, @intCast(L)) + 1) return null;
                return loopSelectSynWidth(ctx, stmts, up_to, relation, b.lhs, depth + 1);
            }
            // Bounded growth, mirroring range.zig: add is max+1, mul is the
            // width sum; both need both sides proved, clamped to <= 63.
            if (b.op == .add) {
                const x = loopSelectSynWidth(ctx, stmts, up_to, relation, b.lhs, depth + 1) orelse return null;
                const y = loopSelectSynWidth(ctx, stmts, up_to, relation, b.rhs, depth + 1) orelse return null;
                const m: u16 = @as(u16, @max(x, y)) + 1;
                if (m > 63) return null;
                return @intCast(m);
            }
            if (b.op == .mul) {
                const x = loopSelectSynWidth(ctx, stmts, up_to, relation, b.lhs, depth + 1) orelse return null;
                const y = loopSelectSynWidth(ctx, stmts, up_to, relation, b.rhs, depth + 1) orelse return null;
                const s: u16 = @as(u16, x) + @as(u16, y);
                if (s > 63) return null;
                return @intCast(s);
            }
            return null;
        },
        else => return null,
    }
}

fn tryEmitLoopSelectPrologue(ctx: *LowerCtx, stmts: []const ast.Stmt, at: usize) Error!bool {
    const debug = false;
    if (at < 1) { if (debug) std.debug.print("LS: at<1\n", .{}); return false; }
    const ws = switch (stmts[at]) {
        .while_loop => |w| w,
        else => return false,
    };
    if (ws.body.tail_expr != null) return false;
    if (ws.body.stmts.len != 2) return false;

    const cb = switch (ws.cond.*) {
        .binop => |b| b,
        else => return false,
    };
    if (cb.op != .lt) return false;
    const iv = identOf(cb.lhs) orelse return false;
    const bound_expr = cb.rhs;

    // The bound must be a plain name not written in the body; otherwise the
    // prologue single evaluation differs from per-trip evaluation.
    const bound_name = identOf(bound_expr) orelse return false;

    const iv_init = loopSelectIvInit(ctx, stmts, at, iv) orelse return false;
    if (iv_init != 0) return false;

    var acc: ?[]const u8 = null;
    var acc_const: i64 = 0;
    var seen_add = false;
    var seen_iv1 = false;
    for (ws.body.stmts) |*st| {
        const a = switch (st.*) {
            .assign => |x| x,
            else => return false,
        };
        if (a.targets.len != 1 or a.values.len != 1) return false;
        const tname = identOf(a.targets[0]) orelse return false;
        if (std.mem.eql(u8, tname, iv)) {
            if (seen_iv1) return false;
            const v = ctx.graph.exactI64OfExpr(a.values[0]) orelse return false;
            if (v != 1) return false;
            seen_iv1 = true;
        } else if (std.mem.eql(u8, tname, bound_name)) {
            return false;
        } else {
            if (seen_add) return false;
            const b = switch (a.values[0].*) {
                .binop => |bb| bb,
                else => return false,
            };
            if (b.op != .add) return false;
            const lhs_is_acc = if (identOf(b.lhs)) |n| std.mem.eql(u8, n, tname) else false;
            const rhs_is_acc = if (identOf(b.rhs)) |n| std.mem.eql(u8, n, tname) else false;
            if (lhs_is_acc == rhs_is_acc) return false;
            const lit = if (lhs_is_acc) b.rhs else b.lhs;
            acc_const = ctx.graph.exactI64OfExpr(lit) orelse return false;
            if (ast.exprMentionsIdent(a.values[0], iv)) return false;
            if (ast.exprMentionsIdent(a.values[0], bound_name)) return false;
            acc = tname;
            seen_add = true;
        }
    }
    if (!seen_add or !seen_iv1) return false;
    const acc_name = acc.?;

    // Prove bound <= 1: a 1-bit non-negative width means bound in {0,1}.
    // Width 0 means bound == 0; the if folds to skip.
    const relation = ctx.function orelse return false;
    const w_opt = loopSelectBoundWidth(ctx, stmts, at, relation, bound_expr);
    if (debug) std.debug.print("LS: width of bound={s} = {?}\n", .{bound_name, w_opt});
    const w = w_opt orelse return false;
    if (w > 1) return false;

    const acc_slot = ctx.locals.get(acc_name) orelse return false;
    const iv_slot = ctx.locals.get(iv) orelse return false;
    const bound_slot = ctx.locals.get(bound_name) orelse return false;
    if (slotIsNonInteger(ctx, acc_slot)) return false;
    if (slotIsNonInteger(ctx, iv_slot)) return false;
    if (slotIsNonInteger(ctx, bound_slot)) return false;
    if (ctx.narrow_slots.contains(acc_slot)) return false;
    if (ctx.narrow_slots.contains(iv_slot)) return false;
    if (ctx.narrow_slots.contains(bound_slot)) return false;
    if (acc_slot == iv_slot) return false;

    // bound is in {0,1} (the width proof above), so (0 < bound) == bound and
    // the conditional add is the product: acc += const*bound. The mul+add
    // pair is adjacent with the product's single reader the add, which is
    // exactly the backend's madd fusion shape (fuse_madd): one `madd`
    // replaces the old compare+branch+csel sequence. iv = (0 < bound) is the
    // exact post-loop value, and equals bound on {0,1}. const*bound is exact
    // (0 or const), so no new overflow beyond the add the branch took.
    //
    // The loop is fully replaced: its post-state (acc, iv) is stored above,
    // and the trip test would be false on entry, so lowering it would only
    // emit dead entry scaffolding per outer iteration plus a dead body.
    // Swallow the `while` so the dispatch loop never lowers the vacuous husk.
    const bound_val = try lowerExpr(ctx, bound_expr);
    const prod_tmp = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = prod_tmp, .binop = .mul, .lhs = bound_val, .rhs = .{ .i64 = acc_const }, .ty = .i64 });
    const sum_tmp = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = sum_tmp, .binop = .add, .lhs = .{ .local = acc_slot }, .rhs = .{ .temp = prod_tmp }, .ty = .i64 });
    try ctx.emit(.{ .op = .store_local, .result = acc_slot, .lhs = .{ .temp = sum_tmp }, .ty = .any });
    try ctx.emit(.{ .op = .store_local, .result = iv_slot, .lhs = bound_val, .ty = .any });
    try ctx.loopselect_swallowed.put(ctx.alloc, &stmts[at], {});
    return true;
}

/// DIVISION-BASED SATURATION IDIOM → MIN VIA CMP+CSEL.
///
/// Recognizes
///
///     s = <non-negative expr>    (stmts[at-1])
///     q = C / (s + 1)            (stmts[at];     C > 0 constant)
///     isbig = 1 / (1 + q)        (stmts[at+1])
///     s = s*(1-isbig) + K*isbig  (stmts[at+2];   C-1 <= K <= C constant)
///
/// and replaces the three statements (two of them divisions) with
/// s = min(s, K) emitted as the one-sided branch shape the backend's
/// if-converter turns into cmp+csel.
///
/// WHY THIS IS SOUND. s >= 0 (proved below) so s+1 >= 1: no division by
/// zero, and the SIGNED divisions are exact (both operands non-negative).
/// q = C/(s+1) = 0 iff s+1 > C iff s >= C (integers, C > 0).
/// isbig = 1/(1+q) = 1 iff q = 0 iff s >= C, else 0 (q >= 0 so 1+q >= 1).
/// The third statement is s*(1-isbig) + K*isbig = (s >= C) ? K : s.
/// With C-1 <= K <= C this equals min(s, K): when s < C (so s <= C-1 <= K)
/// the value is s = min(s,K); when s >= C (>= K) the value is K = min(s,K).
///
/// FAIL-CLOSED: declines if C is not a positive constant, if s's
/// non-negativity is unprovable, if K is outside [C-1, C], if the shapes
/// deviate, if q/isbig/s are not distinct, if any slot is narrow or
/// non-integer, or if q/isbig are read after the idiom.
/// Robust non-negativity: tries graph proof first, then syntactic with
/// backward scan for latest assignments. Sound: every accepted shape is
/// provably >= 0.
fn sataddNonNegative(ctx: *LowerCtx, stmts: []const ast.Stmt, at: usize, expr: *const ast.Expr) bool {
    const graph = ctx.graph;
    const relation = ctx.function orelse ctx.graph.module_root orelse return false;
    if (graph.nonNegativeWidthOfExpr(relation, expr) != null) return true;
    return sataddSynNonNeg(graph, stmts, at, expr, 0);
}

/// SOUNDNESS: wrapping arithmetic means a+b >= 0 does NOT follow from
/// a >= 0 and b >= 0. This fallback proves a WIDTH (value in [0, 2^w)),
/// not just a sign: add widens by one, mul adds widths, and anything
/// reaching width 64 is declined, so no accepted shape can wrap negative.
/// Mirrors range.zig widthOfExpr transfer, over the syntactic backward scan.
fn sataddSynNonNeg(graph: *const semantic_graph.SemanticGraph, stmts: []const ast.Stmt, up_to: usize, expr: *const ast.Expr, depth: u8) bool {
    const w = sataddSynWidth(graph, stmts, up_to, expr, depth) orelse return false;
    return w <= 63;
}

fn sataddIntLitWidth(v: i64) ?u8 {
    if (v < 0) return null;
    var w: u8 = 0;
    var n: u64 = @intCast(v);
    while (n != 0) : (n >>= 1) w += 1;
    return w;
}

fn sataddSynWidth(graph: *const semantic_graph.SemanticGraph, stmts: []const ast.Stmt, up_to: usize, expr: *const ast.Expr, depth: u8) ?u8 {
    if (depth > 8) return null;
    switch (expr.*) {
        .int_lit => |l| return sataddIntLitWidth(l.val),
        .name => |n| {
            // Backward scan for latest assignment to name
            var i = up_to;
            while (i > 0) {
                i -= 1;
                const st = stmts[i];
                if (st != .assign) continue;
                const a = st.assign;
                if (a.targets.len != 1 or a.values.len != 1) continue;
                const t = identOf(a.targets[0]) orelse continue;
                if (!std.mem.eql(u8, t, n.ident)) continue;
                return sataddSynWidth(graph, stmts, i, a.values[0], depth + 1);
            }
            return null;
        },
        .binop => |b| {
            if (b.op == .add) {
                const w1 = sataddSynWidth(graph, stmts, up_to, b.lhs, depth + 1) orelse return null;
                const w2 = sataddSynWidth(graph, stmts, up_to, b.rhs, depth + 1) orelse return null;
                const m = @max(w1, w2);
                // [0,2^w1) + [0,2^w2) fits in [0,2^(m+1)); decline on overflow.
                if (m >= 63) return null;
                return m + 1;
            }
            if (b.op == .mul) {
                const w1 = sataddSynWidth(graph, stmts, up_to, b.lhs, depth + 1) orelse return null;
                const w2 = sataddSynWidth(graph, stmts, up_to, b.rhs, depth + 1) orelse return null;
                const sum: u16 = @as(u16, w1) + @as(u16, w2);
                if (sum > 63) return null;
                return @intCast(sum);
            }
            if (b.op == .band) {
                // x & mask with non-negative literal mask: result <= mask,
                // so the mask width bounds the result; bitwise-and cannot wrap.
                if (graph.exactI64OfExpr(b.lhs)) |m| {
                    if (sataddIntLitWidth(m)) |w| return w;
                }
                if (graph.exactI64OfExpr(b.rhs)) |m| {
                    if (sataddIntLitWidth(m)) |w| return w;
                }
                return null;
            }
            return null;
        },
        else => return null,
    }
}

fn tryEmitSataddIdiom(ctx: *LowerCtx, stmts: []const ast.Stmt, at: usize) Error!bool {
    if (at == 0 or at + 3 > stmts.len) return false;
    const graph = ctx.graph;

    // stmts[at]: q = C/(s+1).
    const qa = switch (stmts[at]) {
        .assign => |a| a,
        else => return false,
    };
    if (qa.targets.len != 1 or qa.values.len != 1) return false;
    const q_name = identOf(qa.targets[0]) orelse return false;
    const qp = sataddDivParts(graph, qa.values[0]) orelse return false;
    const C = qp.num;
    const s_name = qp.den;
    if (C <= 0) return false;

    // stmts[at+1]: isbig = 1/(1+q).
    const ba = switch (stmts[at + 1]) {
        .assign => |a| a,
        else => return false,
    };
    if (ba.targets.len != 1 or ba.values.len != 1) return false;
    const isbig_name = identOf(ba.targets[0]) orelse return false;
    const bp = sataddDivParts(graph, ba.values[0]) orelse return false;
    if (bp.num != 1) return false;
    if (!std.mem.eql(u8, bp.den, q_name)) return false;

    // q, isbig, s distinct.
    if (std.mem.eql(u8, q_name, isbig_name)) return false;
    if (std.mem.eql(u8, q_name, s_name)) return false;
    if (std.mem.eql(u8, isbig_name, s_name)) return false;

    // stmts[at+2]: s = s*(1-isbig) + K*isbig.
    const sa = switch (stmts[at + 2]) {
        .assign => |a| a,
        else => return false,
    };
    if (sa.targets.len != 1 or sa.values.len != 1) return false;
    const s_target = identOf(sa.targets[0]) orelse return false;
    if (!std.mem.eql(u8, s_target, s_name)) return false;
    const K = sataddMinParts(graph, sa.values[0], s_name, isbig_name) orelse return false;
    if (K < C - 1 or K > C) return false;

    // Entry: stmts[at-1] is s = <rhs>; prove <rhs> non-negative.
    const prev = switch (stmts[at - 1]) {
        .assign => |p| p,
        else => return false,
    };
    if (prev.targets.len != 1 or prev.values.len != 1) return false;
    const prev_name = identOf(prev.targets[0]) orelse return false;
    if (!std.mem.eql(u8, prev_name, s_name)) return false;
    if (!sataddNonNegative(ctx, stmts, at - 1, prev.values[0])) return false;

    // Slot for s: must exist, be integer, and not narrowed. (q and isbig
    // have no slots yet -- their statements have not been lowered -- but
    // their names are already proven distinct above, and as pure integer
    // divisions of an integer s they are integers by construction.)
    const s_slot = ctx.locals.get(s_name) orelse return false;
    if (slotIsNonInteger(ctx, s_slot)) return false;
    if (ctx.narrow_slots.contains(s_slot)) return false;

    // q and isbig must not be read after the idiom; their divisions are gone.
    if (sataddIdentUsedAfter(stmts, at + 3, q_name)) return false;
    if (sataddIdentUsedAfter(stmts, at + 3, isbig_name)) return false;

    // Emit s = min(s, K) as one-sided if: if s > K { s = K }.
    // The backend's if-converter turns this into cmp+csel.
    const cond_tmp = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = cond_tmp, .binop = .gt, .lhs = .{ .local = s_slot }, .rhs = .{ .i64 = K }, .ty = .i64 });
    const fail_idx: u32 = @intCast(ctx.instrs.items.len);
    try ctx.emit(.{ .op = .br, .lhs = .{ .temp = cond_tmp }, .branch_target = 0, .branch_condition = .when_false });
    const k_tmp = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = k_tmp, .binop = .bxor, .lhs = .{ .i64 = K }, .rhs = .{ .i64 = 0 }, .ty = .i64 });
    try ctx.emit(.{ .op = .store_local, .result = s_slot, .lhs = .{ .temp = k_tmp }, .ty = .any });
    const join_idx: u32 = @intCast(ctx.instrs.items.len);
    try ctx.emit(.{ .op = .br, .branch_target = 0 });
    const end_idx: u32 = @intCast(ctx.instrs.items.len);
    ctx.instrs.items[fail_idx].branch_target = end_idx;
    ctx.instrs.items[join_idx].branch_target = end_idx;

    // Swallow the three statements.
    for (stmts[at .. at + 3]) |*st| {
        try ctx.satadd_swallowed.put(ctx.alloc, st, {});
    }

    // q, isbig, s rebound; drop stale const facts.
    if (ctx.const_ints.fetchRemove(q_name)) |kv| ctx.alloc.free(kv.key);
    if (ctx.const_ints.fetchRemove(isbig_name)) |kv| ctx.alloc.free(kv.key);
    if (ctx.const_ints.fetchRemove(s_name)) |kv| ctx.alloc.free(kv.key);
    return true;
}

/// Matches NUM / (DEN + 1) with SIGNED division, NUM a graph-exact i64,
/// DEN an identifier, the + 1 on either side. Returns (num, den).
fn sataddDivParts(graph: *const semantic_graph.SemanticGraph, e: *const ast.Expr) ?struct { num: i64, den: []const u8 } {
    const b = switch (e.*) {
        .binop => |bb| bb,
        else => return null,
    };
    if (b.op != .div) return null;
    const num = graph.exactI64OfExpr(b.lhs) orelse return null;
    const add = switch (b.rhs.*) {
        .binop => |ab| ab,
        else => return null,
    };
    if (add.op != .add) return null;
    if (identOf(add.lhs)) |n| {
        if (graph.exactI64OfExpr(add.rhs) == 1) return .{ .num = num, .den = n };
        return null;
    }
    if (identOf(add.rhs)) |n| {
        if (graph.exactI64OfExpr(add.lhs) == 1) return .{ .num = num, .den = n };
        return null;
    }
    return null;
}

/// Matches s*(1-isbig) + K*isbig (commuted mul/add orders accepted) and
/// returns K. The (1-isbig) must be exactly 1 - isbig, not commuted.
fn sataddMinParts(graph: *const semantic_graph.SemanticGraph, e: *const ast.Expr, s: []const u8, isbig: []const u8) ?i64 {
    const b = switch (e.*) {
        .binop => |bb| bb,
        else => return null,
    };
    if (b.op != .add) return null;
    if (sataddTermIsS(s, isbig, b.lhs)) {
        return sataddTermIsK(graph, isbig, b.rhs);
    }
    if (sataddTermIsS(s, isbig, b.rhs)) {
        return sataddTermIsK(graph, isbig, b.lhs);
    }
    return null;
}

/// e is s*(1-isbig) in either mul order.
fn sataddTermIsS(s: []const u8, isbig: []const u8, e: *const ast.Expr) bool {
    const b = switch (e.*) {
        .binop => |bb| bb,
        else => return false,
    };
    if (b.op != .mul) return false;
    return (isIdent(b.lhs, s) and sataddIsOneMinusIsbig(b.rhs, isbig)) or
        (isIdent(b.rhs, s) and sataddIsOneMinusIsbig(b.lhs, isbig));
}

/// e is 1 - isbig (exact order).
fn sataddIsOneMinusIsbig(e: *const ast.Expr, isbig: []const u8) bool {
    const b = switch (e.*) {
        .binop => |bb| bb,
        else => return false,
    };
    if (b.op != .sub) return false;
    const one = ast.intLiteralValue(b.lhs) orelse return false;
    if (one != 1) return false;
    return isIdent(b.rhs, isbig);
}

/// e is K*isbig in either mul order; returns K (graph-exact i64).
fn sataddTermIsK(graph: *const semantic_graph.SemanticGraph, isbig: []const u8, e: *const ast.Expr) ?i64 {
    const b = switch (e.*) {
        .binop => |bb| bb,
        else => return null,
    };
    if (b.op != .mul) return null;
    if (isIdent(b.lhs, isbig)) return graph.exactI64OfExpr(b.rhs);
    if (isIdent(b.rhs, isbig)) return graph.exactI64OfExpr(b.lhs);
    return null;
}

/// True if the identifier name appears in any value position in
/// stmts[from..]. Conservative: unhandled AST shapes count as a use.
fn sataddIdentUsedAfter(stmts: []const ast.Stmt, from: usize, name: []const u8) bool {
    for (stmts[from..]) |*st| {
        if (sataddStmtMentions(st, name)) return true;
    }
    return false;
}

fn sataddStmtMentions(st: *const ast.Stmt, name: []const u8) bool {
    switch (st.*) {
        .assign => |a| {
            for (a.targets) |t| if (sataddExprMentions(t, name)) return true;
            for (a.values) |v| if (sataddExprMentions(v, name)) return true;
            return false;
        },
        // Conservative: any other statement shape counts as a use.
        else => return true,
    }
}

fn sataddExprMentions(e: *const ast.Expr, name: []const u8) bool {
    switch (e.*) {
        .name => |n| return std.mem.eql(u8, n.ident, name),
        .binop => |b| return sataddExprMentions(b.lhs, name) or sataddExprMentions(b.rhs, name),
        .unop => |u| return sataddExprMentions(u.operand, name),
        .int_lit, .float_lit, .true_lit, .false_lit, .nil => return false,
        .quoted => return false,
        // Conservative: unhandled shapes count as a use.
        else => return true,
    }
}

fn runAdditivePrologues(ctx: *LowerCtx, stmts: []const ast.Stmt, at: usize) Error!bool {
    if (try tryEmitVectorReductionPrologue(ctx, stmts, at)) return true;
    if (try tryEmitPopcountIdiom(ctx, stmts, at)) return true;
    if (try tryEmitLoopSelectPrologue(ctx, stmts, at)) return true;
    if (try tryEmitSataddIdiom(ctx, stmts, at)) return true;
    return try tryEmitBitReversePrologue(ctx, stmts, at);
}

/// BIT-REVERSE IDIOM → PARALLEL BIT-SWAP DATAFLOW.
///
/// Recognizes
///
///     x = <non-negative expr>     (stmts[at-3])
///     r = 0                       (stmts[at-2])
///     i = 0                       (stmts[at-1])
///     while i < N                 (stmts[at]; 1 <= N <= 64, literal trip count)
///         r = r * 2 + (x & 1)     (accumulate; must precede the halving)
///         x = x / 2               (or x = x >> 1)
///         i = i + 1
///
/// and replaces the N-iteration serial recurrence with the parallel
/// bit-swap dataflow — the scalar form of what the oracle does when it
/// vectorizes this kernel (observed: clang dissolves the loop-carried chain
/// into parallel per-bit dataflow and vectorizes across outer iterations).
///
/// WHY THIS IS SOUND. Write x_k, r_k for the values after k iterations, x_0
/// the loop-entry value, r_0 = 0. The halving is truncating division and x is
/// proved non-negative (below), so x_{k+1} = x_k >> 1 and x_k = x_0 >> k by
/// induction. Then r_{k+1} = 2*r_k + bit_k(x_0), so r_N is the low N bits of
/// x_0 reversed. The emitted dataflow computes reverse64(x_0) >> (64-N);
/// bit j of that is bit (N-1-j) of x_0 for j < N and 0 above — exactly r_N,
/// with no dependence chain left for the CPU to serialize on.
/// Two's-complement wrap in `r*2` cannot change the answer: the closed form
/// never multiplies.
///
/// The non-negativity of x is the load-bearing fact: it makes `/2` the
/// logical shift (so each halving is exact) and makes the post-loop
/// `x = x_0 >> N` exact. It comes from ONE producer —
/// `ctx.graph.nonNegativeWidthOfExpr` over the pre-loop binding's right-hand
/// expression, the same `ranges` column the divisor-sign machinery reads. A
/// null answer declines the transform; nothing is re-derived here.
///
/// THE PROLOGUE REPLACES THE LOOP. It stores the reversed value into `r`,
/// the shifted value into `x`, and N into `i` — exactly the post-loop state
/// the serial recurrence would have produced — and records the `while` in
/// `bitrev_swallowed` so the dispatch loop never lowers it. No vacuous loop
/// is emitted: the trip test would be false on entry, so lowering it would
/// only emit dead entry scaffolding per outer iteration plus a dead body.
/// Every observable behavior is the three post-loop values (no
/// break/continue admitted: the body is exactly the three idiom statements
/// and the condition is pure). When any condition fails this emits nothing
/// and the loop lowers exactly as it does today.
///
/// CLAIM PROTOCOL — returns true when the prologue fired, claiming
/// `stmts[at]`. Narrow `r`/`x` decline: their stores truncate per iteration
/// in the source while the prologue's `.any` stores are full-width, and a
/// pre-truncation non-negativity proof does not survive narrowing.
fn tryEmitBitReversePrologue(ctx: *LowerCtx, stmts: []const ast.Stmt, at: usize) Error!bool {
    if (at < 3) return false;
    const ws = switch (stmts[at]) {
        .while_loop => |w| w,
        else => return false,
    };
    if (ws.body.tail_expr != null) return false;
    if (ws.body.stmts.len != 3) return false;

    const cb = switch (ws.cond.*) {
        .binop => |x| x,
        else => return false,
    };
    if (cb.op != .lt and cb.op != .leq) return false;
    const idx = identOf(cb.lhs) orelse return false;

    const hi = loopUpperBound(ctx.graph, ws.cond, idx) orelse return false;
    const lo = literalBindingOf(ctx.graph, &stmts[at - 1], idx) orelse return false;
    if (lo != 0) return false;
    const n: i64 = hi - lo + 1;
    if (n < 1 or n > 64) return false;

    // Exactly one accumulate, one halving, one index increment.
    var accum: ?BitRevParts = null;
    var accum_at: usize = 3;
    for (ws.body.stmts, 0..) |*st, k| {
        if (bitRevAccum(ctx.graph, st)) |p| {
            if (accum != null) return false;
            accum = p;
            accum_at = k;
        }
    }
    const ap = accum orelse return false;
    if (std.mem.eql(u8, ap.acc, idx) or std.mem.eql(u8, ap.src, idx)) return false;
    if (std.mem.eql(u8, ap.acc, ap.src)) return false;

    var halve_at: usize = 3;
    var incr_at: usize = 3;
    for (ws.body.stmts, 0..) |*st, k| {
        if (k == accum_at) continue;
        if (bitRevHalve(ctx.graph, st, ap.src)) {
            if (halve_at != 3) return false;
            halve_at = k;
        } else if (stepIsIncrementOfOne(ctx.graph, st, idx)) {
            if (incr_at != 3) return false;
            incr_at = k;
        } else return false;
    }
    if (halve_at == 3 or incr_at == 3) return false;
    // The accumulate must read x BEFORE the halving shifts it; the reversed
    // order computes the reverse of bits [1,N], not [0,N).
    if (accum_at > halve_at) return false;

    // The three preceding statements: x = <non-negative>, r = 0, i = 0.
    const r_init = literalBindingOf(ctx.graph, &stmts[at - 2], ap.acc) orelse return false;
    if (r_init != 0) return false;
    const xa = switch (stmts[at - 3]) {
        .assign => |a| a,
        else => return false,
    };
    if (xa.targets.len != 1 or xa.values.len != 1) return false;
    const xt = identOf(xa.targets[0]) orelse return false;
    if (!std.mem.eql(u8, xt, ap.src)) return false;
    const relation = ctx.function orelse return false;
    if (ctx.graph.nonNegativeWidthOfExpr(relation, xa.values[0]) == null) return false;

    const r_slot = ctx.locals.get(ap.acc) orelse return false;
    const x_slot = ctx.locals.get(ap.src) orelse return false;
    const i_slot = ctx.locals.get(idx) orelse return false;
    if (slotIsNonInteger(ctx, r_slot)) return false;
    if (slotIsNonInteger(ctx, x_slot)) return false;
    if (slotIsNonInteger(ctx, i_slot)) return false;
    // Narrow slots truncate on every store while the prologue's stores are
    // full-width: the source truncates `r` each iteration, and the value the
    // idiom actually reverses is the post-truncation `x`, so a pre-truncation
    // non-negativity proof does not transfer. Decline. (`i` needs no check:
    // N <= 64 fits every narrow width.)
    if (ctx.narrow_slots.contains(r_slot)) return false;
    if (ctx.narrow_slots.contains(x_slot)) return false;
    if (r_slot == x_slot or r_slot == i_slot or x_slot == i_slot) return false;

    // Hoist the five swap masks; each is used twice per step.
    const rev_masks = [_]i64{
        0x5555555555555555,
        0x3333333333333333,
        0x0F0F0F0F0F0F0F0F,
        0x00FF00FF00FF00FF,
        0x0000FFFF0000FFFF,
    };
    const rev_shifts = [_]i64{ 1, 2, 4, 8, 16 };
    var mask_tmps: [5]u32 = undefined;
    for (rev_masks, 0..) |m, k| {
        const t = ctx.freshTemp();
        try ctx.emit(.{ .op = .@"const", .result = t, .lhs = .{ .i64 = m }, .ty = .i64 });
        mask_tmps[k] = t;
    }

    var cur: dnir.Value = .{ .local = x_slot };
    for (rev_shifts, 0..) |sh, k| {
        const shr_t = ctx.freshTemp();
        try ctx.emit(.{ .op = .binop, .result = shr_t, .binop = .shr, .lhs = cur, .rhs = .{ .i64 = sh }, .ty = .i64 });
        const a1 = ctx.freshTemp();
        try ctx.emit(.{ .op = .binop, .result = a1, .binop = .band, .lhs = .{ .temp = shr_t }, .rhs = .{ .temp = mask_tmps[k] }, .ty = .i64 });
        const a2 = ctx.freshTemp();
        try ctx.emit(.{ .op = .binop, .result = a2, .binop = .band, .lhs = cur, .rhs = .{ .temp = mask_tmps[k] }, .ty = .i64 });
        const shl_t = ctx.freshTemp();
        try ctx.emit(.{ .op = .binop, .result = shl_t, .binop = .shl, .lhs = .{ .temp = a2 }, .rhs = .{ .i64 = sh }, .ty = .i64 });
        const or_t = ctx.freshTemp();
        try ctx.emit(.{ .op = .binop, .result = or_t, .binop = .bor, .lhs = .{ .temp = a1 }, .rhs = .{ .temp = shl_t }, .ty = .i64 });
        cur = .{ .temp = or_t };
    }
    const shr32 = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = shr32, .binop = .shr, .lhs = cur, .rhs = .{ .i64 = 32 }, .ty = .i64 });
    const shl32 = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = shl32, .binop = .shl, .lhs = cur, .rhs = .{ .i64 = 32 }, .ty = .i64 });
    const full = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = full, .binop = .bor, .lhs = .{ .temp = shr32 }, .rhs = .{ .temp = shl32 }, .ty = .i64 });
    // r = reverse64(x) >> (64 - n)
    const r_new = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = r_new, .binop = .shr, .lhs = .{ .temp = full }, .rhs = .{ .i64 = 64 - n }, .ty = .i64 });
    try ctx.emit(.{ .op = .store_local, .result = r_slot, .lhs = .{ .temp = r_new }, .ty = .any });
    // x = x >> n — exact because x >= 0. n = 64 halves every non-negative
    // i64 word to zero, and `lsr #64` would encode as `lsr #0`.
    if (n == 64) {
        try ctx.emit(.{ .op = .store_local, .result = x_slot, .lhs = .{ .i64 = 0 }, .ty = .any });
    } else {
        const x_new = ctx.freshTemp();
        try ctx.emit(.{ .op = .binop, .result = x_new, .binop = .shr, .lhs = .{ .local = x_slot }, .rhs = .{ .i64 = n }, .ty = .i64 });
        try ctx.emit(.{ .op = .store_local, .result = x_slot, .lhs = .{ .temp = x_new }, .ty = .any });
    }
    // i = n: the loop's post-state. The `while` itself is swallowed below —
    // the prologue discharged its whole semantics — so no vacuous loop is
    // emitted for a trip test to reject.
    try ctx.emit(.{ .op = .store_local, .result = i_slot, .lhs = .{ .i64 = n }, .ty = .any });

    // r, x and i are no longer the values the preceding statements bound.
    // Dropping the entries keeps `const_ints` from answering stale literals
    // downstream; every consumer treats a miss as "not compile-time known".
    for ([_][]const u8{ ap.acc, ap.src, idx }) |name| {
        if (ctx.const_ints.fetchRemove(name)) |kv| ctx.alloc.free(kv.key);
    }
    // The loop is fully replaced: its post-state (r, x, i) is stored above.
    // Swallow the `while` so the dispatch loop never lowers the vacuous husk
    // (dead entry scaffolding per outer iteration, dead body in code size).
    try ctx.bitrev_swallowed.put(ctx.alloc, &stmts[at], {});
    return true;
}

const BitRevParts = struct { acc: []const u8, src: []const u8 };

/// `r = r * 2 + (x & 1)` in either add-operand order, or null. Returns the
/// accumulator and the source being reversed.
fn bitRevAccum(graph: *const semantic_graph.SemanticGraph, st: *const ast.Stmt) ?BitRevParts {
    const a = switch (st.*) {
        .assign => |x| x,
        else => return null,
    };
    if (a.targets.len != 1 or a.values.len != 1) return null;
    const acc = identOf(a.targets[0]) orelse return null;
    const b = switch (a.values[0].*) {
        .binop => |x| x,
        else => return null,
    };
    if (b.op != .add) return null;
    if (bitRevAccumOrder(graph, b.lhs, b.rhs, acc)) |p| return p;
    if (bitRevAccumOrder(graph, b.rhs, b.lhs, acc)) |p| return p;
    return null;
}

/// `mul_side = acc * 2` (either order) and `band_side = src & 1` (either
/// order), or null. The `2` and the `1` are graph exact-i64 facts; the AST
/// supplies only shape and name identity.
fn bitRevAccumOrder(
    graph: *const semantic_graph.SemanticGraph,
    mul_side: *const ast.Expr,
    band_side: *const ast.Expr,
    acc: []const u8,
) ?BitRevParts {
    const m = switch (mul_side.*) {
        .binop => |x| x,
        else => return null,
    };
    if (m.op != .mul) return null;
    const mul_ok = blk: {
        if (identOf(m.lhs)) |l| {
            if (std.mem.eql(u8, l, acc) and graph.exactI64OfExpr(m.rhs) == @as(?i64, 2)) break :blk true;
        }
        if (identOf(m.rhs)) |r| {
            if (std.mem.eql(u8, r, acc) and graph.exactI64OfExpr(m.lhs) == @as(?i64, 2)) break :blk true;
        }
        break :blk false;
    };
    if (!mul_ok) return null;
    const bd = switch (band_side.*) {
        .binop => |x| x,
        else => return null,
    };
    if (bd.op != .band) return null;
    if (identOf(bd.lhs)) |l| {
        if (graph.exactI64OfExpr(bd.rhs) == @as(?i64, 1)) return .{ .acc = acc, .src = l };
    }
    if (identOf(bd.rhs)) |r| {
        if (graph.exactI64OfExpr(bd.lhs) == @as(?i64, 1)) return .{ .acc = acc, .src = r };
    }
    return null;
}

/// `x = x / 2` or `x = x >> 1`, or false. The division is truncating; the
/// caller proves x non-negative, under which both spellings halve exactly.
fn bitRevHalve(graph: *const semantic_graph.SemanticGraph, st: *const ast.Stmt, x: []const u8) bool {
    const a = switch (st.*) {
        .assign => |v| v,
        else => return false,
    };
    if (a.targets.len != 1 or a.values.len != 1) return false;
    const t = identOf(a.targets[0]) orelse return false;
    if (!std.mem.eql(u8, t, x)) return false;
    const b = switch (a.values[0].*) {
        .binop => |v| v,
        else => return false,
    };
    const l = identOf(b.lhs) orelse return false;
    if (!std.mem.eql(u8, l, x)) return false;
    return switch (b.op) {
        .div => graph.exactI64OfExpr(b.rhs) == @as(?i64, 2),
        .rshift => graph.exactI64OfExpr(b.rhs) == @as(?i64, 1),
        else => false,
    };
}

/// True when `expr` holds a BOOLEAN rather than a number.
///
/// A bool rides an integer register, so no representation downstream can tell
/// `true` from `1`. The distinction is only visible where a value is RENDERED:
/// `"{ok}"` must print `true`, and `"%lld"` on the same register prints `1`.
/// That is a wrong answer, not a bail, so every renderer asks this first and
/// refuses whatever it cannot place.
///
/// The predicate is POSITIVE and deliberately narrow — the shapes that are
/// provably bool. Anything outside it is not "known integer"; `exprIsIntegral`
/// still has to prove that separately, and the two together are what admit an
/// operand.
fn exprIsBoolish(ctx: *LowerCtx, expr: *const ast.Expr) bool {
    if (applicationResultIs(ctx, expr, .bool)) return true;
    return switch (expr.*) {
        .true_lit, .false_lit => true,
        .unop => |u| u.op == .not,
        .binop => |b| switch (b.op) {
            .eq, .neq, .lt, .gt, .leq, .geq => true,
            // `a and b` / `a or b` yield an OPERAND in Lua, not a truth value,
            // so they are bool only when both arms are.
            .@"and", .@"or" => exprIsBoolish(ctx, b.lhs) and exprIsBoolish(ctx, b.rhs),
            else => false,
        },
        .call => |c| c.func.* == .name and functionResultIs(ctx, c.func.name.ident, .bool),
        .name => |n| blk: {
            const slot = ctx.locals.get(n.ident) orelse break :blk false;
            break :blk ctx.bool_slots.contains(slot);
        },
        // The expression-if is bool only when BOTH arms are — same rule the
        // `and`/`or` arm above applies, and for the same reason.
        .if_expr => |ie| exprIsBoolish(ctx, ie.then_expr) and exprIsBoolish(ctx, ie.else_expr),
        else => false,
    };
}

/// An operand of `..` this pass can render without changing the answer.
///
/// Either it is already text, or it is provably an integer that is not a bool.
/// `#s`, `s[i]`, an i64 local and an i64-returning call all qualify; an f64, a
/// bool, a record, a table base and anything unproven do not, and each of those
/// is a bail rather than a guess.
///
/// The classification is one descent per expression. The pre-fix shape asked
/// `exprIsStr` twice per concat level — once inside this predicate and once in
/// the `.concat` arm's at-least-one-side-str test — and each of those descents
/// asked again, so a left-nested chain of N concats cost 2^N predicate calls
/// and `gate/architecture.id` (which builds 20+ hole chains) never finished
/// lowering. The class carries both answers out of one walk.
const ConcatClass = enum { str, integral, f64, other };

fn concatOperandClass(ctx: *LowerCtx, expr: *const ast.Expr) ConcatClass {
    const class = concatOperandClassInner(ctx, expr);
    if (@import("builtin").mode == .debug and class == .other) {
        switch (expr.*) {
            .quoted => |qv| std.debug.print("concatOperand other: quoted:{s} textConst={}\n", .{ qv.val[0..@min(qv.val.len, 40)], graphTextConst(ctx.graph, expr) }),
            .name => |n| std.debug.print("concatOperand other: name:{s}\n", .{n.ident}),
            else => std.debug.print("concatOperand other: kind={s}\n", .{@tagName(expr.*)}),
        }
    }
    return class;
}

fn concatOperandClassInner(ctx: *LowerCtx, expr: *const ast.Expr) ConcatClass {
    if (exprIsStr(ctx, expr)) return .str;
    if (exprIsBoolish(ctx, expr)) return .other;
    // A BYTE SEQUENCE IS THE THIRD ANSWER, and it is stated here rather than
    // left to fall out of the two above (GAP-145 `law.text.byte`, GAP-207).
    // `dnir.Value` carries `void/i64/f64/str/local/temp/record` and has no
    // member for element descriptor `byte`, so the lawful shape is a REFUSAL
    // this pass can name, not a render. Without this line `exprIsIntegral`
    // admitted the `const char*` and `planConcat` printed it through `%lld`.
    if (exprIsByteSequence(ctx, expr)) return .other;
    // An f64 renders through `%.17g` -- the language's f64 text rendering,
    // the same conversion `duo_str_from_f64` uses to mirror `lua_to_str`
    // (codegen.zig). It is a fourth class, not `.integral`: `%lld` on a
    // double's bits is the plausible wrong answer the old refusal existed
    // to prevent, and a bool stays `.other`.
    if (exprIsF64(ctx, expr)) return .f64;
    if (exprIsIntegral(ctx, expr)) return .integral;
    return .other;
}

fn concatOperandOk(ctx: *LowerCtx, expr: *const ast.Expr) bool {
    return concatOperandClass(ctx, expr) != .other;
}

fn sameIndex(a: *const ast.Expr, b: *const ast.Expr) bool {
    if (a.* == .name and b.* == .name)
        return std.mem.eql(u8, a.name.ident, b.name.ident);
    if (a.* == .int_lit and b.* == .int_lit)
        return a.int_lit.val == b.int_lit.val;
    return false;
}

/// True when `expr` is known to produce a `str` (a `const char*`), so `#expr`
/// can lower to a `strlen` call rather than a dynamic length probe.
fn exprIsStr(ctx: *LowerCtx, expr: *const ast.Expr) bool {
    if (applicationResultIs(ctx, expr, .str)) return true;
    return switch (expr.*) {
        // Quote syntax is not a type. The semantic producer distinguishes
        // text from byte-sequence faces and publishes the value descriptor;
        // checked lowering consumes that fact and fails closed when it is
        // absent or damaged. Reading `.quoted` as unconditionally text here
        // was the rival AST classifier that kept single-quoted bytes and an
        // unpublished quote indistinguishable at this decision.
        .quoted => graphTextConst(ctx.graph, expr),
        // `..` ALWAYS produces text, including where one side is a number —
        // which is the shape `"{a} {b}"` desugars to. Requiring both sides to
        // be str was what made every interpolation of an integer answer "not a
        // string" and take the whole enclosing function to the C backend. At
        // least one side must still be a str: two integers concatenated is a
        // shape this pass has never lowered, and claiming it here would let
        // `lowerConcat` produce text where the answer was never checked.
        // `and`/`or` SELECT A VALUE, they do not compute one, so the result is
        // text exactly when every arm that can be selected is text. Without
        // these two arms the value lowered CORRECTLY and was tagged `.i64`, and
        // `lowerPrint` then chose `%lld` and printed the string's ADDRESS:
        //
        //     v = "set" or "FB"            print(v) -> 4304880776
        //     v = c and "yes" or "no"      print(v) -> 4343350452
        //
        // Both are accepted by the native-scalar precheck, whose `expr_type`
        // answers `.str` for the same two shapes (`codegen.zig`, the
        // `.@"and"`/`.@"or"` arms) — so the precheck claimed the shape and the
        // lowering disagreed, which is gap[034] (the precheck and the lowering
        // must claim the SAME set) failing in its dangerous direction: not a
        // refusal, a wrong answer that compiles and runs.
        //
        // The ternary `c and X or Y` needs its own case: it parses as
        // `(c and X) or Y`, and the recursive rule asks whether `c and X` is
        // text, which it is not — `c` is a bool. The reachable arms are X and
        // Y, which is exactly the pair `codegen.expr_type` inspects.
        .binop => |bb| switch (bb.op) {
            .concat => blk: {
                // ONE descent per side. `concatOperandClass` already answers
                // both questions — operand renderable, and is it text — so the
                // old shape's second `exprIsStr` per side re-descended the same
                // subtree and doubled the work every level down a chain.
                const l = concatOperandClass(ctx, bb.lhs);
                if (l == .other) break :blk false;
                const r = concatOperandClass(ctx, bb.rhs);
                if (r == .other) break :blk false;
                break :blk l == .str or r == .str;
            },
            .@"or" => if (bb.lhs.* == .binop and bb.lhs.binop.op == .@"and")
                exprIsStr(ctx, bb.lhs.binop.rhs) and exprIsStr(ctx, bb.rhs)
            else
                exprIsStr(ctx, bb.lhs) and exprIsStr(ctx, bb.rhs),
            .@"and" => exprIsStr(ctx, bb.lhs) and exprIsStr(ctx, bb.rhs),
            else => false,
        },
        // Two producers of str, one arm. A producer the type tracker does not
        // know about breaks every consumer downstream, so both belong here:
        //   * a call to a function declared `: str` — without it,
        //     `m = mk(...)` then `#m` bails because the local never entered
        //     str_slots;
        //   * `string.char(n)` — without it the very next `string.byte(s, 1)`
        //     does not recognize its own argument and falls through to an
        //     undefined `string_byte` symbol.
        .call => |c| switch (c.func.*) {
            .name => |n| blk: {
                if (std.mem.eql(u8, n.ident, "to") and c.args.len == 2 and
                    c.args[1].* == .name and std.mem.eql(u8, c.args[1].name.ident, "str") and
                    exprIsIntegral(ctx, c.args[0]))
                    break :blk true;
                // `gatecap(cmd)` captures process stdout as text (GAP-155).
                if (std.mem.eql(u8, n.ident, "gatecap") and c.args.len == 1)
                    break :blk true;
                // `incarnation()` answers the per-process boot token as text.
                if (std.mem.eql(u8, n.ident, "incarnation") and c.args.len == 0)
                    break :blk true;
                // `execap(prog, args, input)` captures process stdout as text.
                if (std.mem.eql(u8, n.ident, "execap") and c.args.len == 3)
                    break :blk true;
                // `sha256file(path)` answers the lowercase hex digest as text.
                // Without this arm the binding fell through to `.any`, the
                // slot never entered `str_slots`, and interpolation printed
                // the digest pointer as an integer (observed `4299405008`).
                if (std.mem.eql(u8, n.ident, "sha256file") and c.args.len == 1)
                    break :blk true;
                if (functionResultIs(ctx, n.ident, .str)) break :blk true;
                // ANY-RETURNING IDENTITY ON A STRING. `box: any = (x: any) x`
                // returns the descriptor of its argument unchanged; the runtime
                // value is a `str*` register whenever the call site passed a
                // `str`, so it must read here as text. `functionResultIs` answers
                // false because the declared return is `.any`, not `.str`; the
                // fallback inspects the actual argument so the contract holds
                // for the lawful forwarder shape and stays narrow enough not to
                // leak through ordinary callers.
                if (functionResultIs(ctx, n.ident, .any) and c.args.len == 1 and
                    exprIsStr(ctx, c.args[0])) break :blk true;
                break :blk false;
            },
            // `to(str)(n)` — the relation surface's own producer of str. It is
            // spelled as a call whose CALLEE is a call, so neither the
            // declared-return arm nor the `string.char` arm sees it, and every
            // consumer downstream (`#s`, `s[i]`, `..`) refused its result.
            .call => |inner| c.args.len == 1 and inner.func.* == .name and
                std.mem.eql(u8, inner.func.name.ident, "to") and
                inner.args.len == 1 and inner.args[0].* == .name and
                std.mem.eql(u8, inner.args[0].name.ident, "str"),
            .field => |f| f.obj.* == .name and
                std.mem.eql(u8, f.obj.name.ident, "string") and
                std.mem.eql(u8, f.field, "char"),
            else => false,
        },
        // SUBJECT-FIRST STRING METHOD. `s:rep(n)`, `s:sub(i, j)`, `s:match(p)`
        // and the rest of the string_methods roster all return str — the
        // graph does not yet publish the application result descriptor for
        // these (GAP-124), so `applicationResultIs` answers false and the
        // type checker has to fall back to the AST shape. The method roster
        // is the same one `native/bootstrap.zig` admits, so a method name
        // here matches what the call site is allowed to write; a subject
        // that does not lower to a str is `.other` in `concatOperandClass`
        // and refused by `planConcat`, so this arm cannot accidentally
        // admit `:sub(...)` on a non-str subject as text. The original
        // arms for `io:read`/`stdin:read`/`stdin:line` and `to(str)` are
        // preserved verbatim below; the `has` arm explicitly returns false
        // because a boolean answer is not text.
        .method_call => |mc| blk: {
            // THE NEW STRING-METHODS ROSTER. Each entry here must match the
            // `string_methods` list in `native/bootstrap.zig` so a method
            // admitted at the call site also admits the type answer here —
            // BUT ONLY FOR THE METHODS THAT RETURN TEXT. The roster conflates
            // two return classes: `sub`/`rep`/`at`/`char`/`match` answer a str
            // while `len`/`byte`/`find` answer an i64. Answering `true` for an
            // integral method made `print(s:len())` type `print_value` as
            // `.str`, which calls `puts` on the raw integer — measured
            // segfault, `KERN_INVALID_ADDRESS at 0x3` inside
            // `_platform_strlen` (`n = s:len(); print(n)` → exit 139). The
            // `has` arm below documents this same failure mode, already fixed
            // there by answering `false`; the integral members take the same
            // `%lld` path through `exprIsIntegral`, which already claims
            // `len`/`byte` on str subjects. The subject still must be text:
            // `:len` on a table is a different relation owned elsewhere.
            const str_result_methods = [_][]const u8{ "sub", "match", "char", "at", "rep" };
            for (str_result_methods) |m| {
                if (std.mem.eql(u8, mc.method, m) and exprIsStr(ctx, mc.obj))
                    break :blk true;
            }
            if (mc.obj.* == .name and std.mem.eql(u8, mc.obj.name.ident, "io") and
                std.mem.eql(u8, mc.method, "read"))
                break :blk true;
            if (mc.obj.* == .name and std.mem.eql(u8, mc.obj.name.ident, "stdin") and
                std.mem.eql(u8, mc.method, "read") and mc.args.len == 0)
                break :blk true;
            if (mc.obj.* == .name and std.mem.eql(u8, mc.obj.name.ident, "stdin") and
                std.mem.eql(u8, mc.method, "line") and mc.args.len == 0)
                break :blk true;
            if (std.mem.eql(u8, mc.method, "read") and mc.args.len == 0 and
                exprIsStr(ctx, mc.obj))
                break :blk true;
            if (std.mem.eql(u8, mc.method, "to") and mc.args.len == 1 and
                mc.args[0].* == .name and std.mem.eql(u8, mc.args[0].name.ident, "str") and
                exprIsIntegral(ctx, mc.obj))
                break :blk true;
            if (std.mem.eql(u8, mc.method, "sub") and mc.args.len >= 1 and mc.args.len <= 2)
                break :blk exprIsStr(ctx, mc.obj);
            // `has` answers a BOOL, never text. This arm used to answer
            // `exprIsStr(mc.obj)` — copied from `sub` two arms up, where the
            // subject IS the result type — which made `print(s:has(n))`
            // classify the boolean as text, lower through `puts` with the
            // raw 0/1 as the format pointer, and SEGFAULT before any output
            // (measured: exit 139, no stdout, `ok compile` both). Bool prints
            // take the `%lld` path like every other integral answer.
            if (std.mem.eql(u8, mc.method, "has") and mc.args.len == 1)
                break :blk false;
            break :blk false;
        },
        .name => |n| blk: {
            const graph_descriptor = graphNameDescriptor(ctx, expr);
            switch (graph_descriptor) {
                .known => |descriptor| break :blk descriptor == .str,
                .unknown, .unvisited => {},
            }
            // A module-level string constant is not a local, so the slot lookup
            // below can never see it. Without this arm the VALUE lowered fine
            // and every consumer still read it as an integer: `print(OWNER)`
            // chose `%lld` and printed the pointer, and `OWNER != "x"` compared
            // addresses. The type answer has to follow the value.
            const slot = ctx.locals.get(n.ident) orelse {
                // A WRITTEN module-scope binding is not a constant EITHER — and
                // that is not an oversight, it is the deliberate act of the
                // change that gave globals storage: `lowerModuleFromGraph`
                // removes every written global from `module_consts` because "a
                // name that is written is not a constant". That removal deleted
                // the only path by which this predicate could see a `global S:
                // str`, so the fact remained TRUE and REPRESENTED — in
                // `module_globals.types`, which the `.name` LOWERING arm reads
                // one screen up and even uses to seed `str_slots` — while every
                // predicate that gates a str candidate answered "not text".
                // HPLS §99: represented but not propagated.
                //
                // The declared type is asked EXACTLY, never "not i64": a `%s`
                // hole fed an integer prints an address, which is the concat
                // failure mode this tree has already paid for twice.
                if (ctx.module_globals.types.get(n.ident)) |ty| break :blk ty == .str;
                break :blk ctx.module_consts.strs.contains(n.ident);
            };
            break :blk ctx.str_slots.contains(slot);
        },
        // `Kind.owner` where the descriptor field holds a string literal — the
        // qualified spelling of the same module-level constant.
        .field => |f| blk: {
            // A member edge whose face is a VALUE is that value at its own
            // node, and the roster declares what it is. `cwd(expr)` alone was
            // the one member spelled out; the face is the general fact.
            if (osMemberOf(expr)) |m| {
                if (m.face == .value and m.result == .str) break :blk true;
            }
            if (checkedScalarFieldProjection(ctx, expr)) |ty| break :blk ty == .str;
            if (f.obj.* != .name) break :blk false;
            var buf: [512]u8 = undefined;
            const key = std.fmt.bufPrint(&buf, "{s}.{s}", .{ f.obj.name.ident, f.field }) catch break :blk false;
            if (ctx.module_consts.strs.contains(key)) break :blk true;
            if (ctx.locals.get(key)) |slot| break :blk ctx.str_slots.contains(slot);
            break :blk false;
        },
        // The expression-if produces text only when BOTH arms do. One str arm
        // and one integer arm is a slot whose type depends on the branch taken,
        // which no consumer downstream can read correctly.
        .if_expr => |ie| exprIsStr(ctx, ie.then_expr) and exprIsStr(ctx, ie.else_expr),
        // `t(i)` on a table of text is text at every index. `table_apply`
        // rewrites the application into `.index` before this pass runs, so the
        // dynamic read and the constant read arrive at the SAME node and get
        // the same answer — which is what the select chain, the memory-backed
        // load and `constTableRead` all need, since none of the three can
        // carry an element type in the value it returns.
        // A WORLD PROJECTION IS TEXT WHEN THE ROSTER SAYS SO. This was
        // `argv(ix.obj) or env(ix.obj)` — the two member names spelled out
        // here, and a third member added to the world would have been text at
        // the emit site and not-text at this predicate.
        .index => |ix| (if (osMemberOf(ix.obj)) |m| m.face == .projection and m.result == .str else false) or
            (ix.obj.* == .name and (ctx.str_tables.contains(ix.obj.name.ident) or
                ctx.module_consts.str_tables.contains(ix.obj.name.ident))),
        else => false,
    };
}

/// The realized value is text. Print/write must not reconstruct i64 from a
/// pointer just because the AST classifier missed a producer.
fn holds(ctx: *const LowerCtx, v: dnir.Value) bool {
    return switch (v) {
        .str => true,
        .temp => |t| blk: {
            var i = ctx.instrs.items.len;
            while (i > 0) {
                i -= 1;
                const ins = ctx.instrs.items[i];
                if (ins.result) |r| {
                    if (r == t) break :blk ins.ty == .str;
                }
            }
            break :blk false;
        },
        .local => |slot| ctx.str_slots.contains(slot),
        else => false,
    };
}

fn applicationNeedsGraphOccurrence(ctx: *const LowerCtx, expr: *const ast.Expr) bool {
    if (!ctx.require_graph_facts) return false;
    if (expr.* != .call and expr.* != .method_call) return false;
    if (expr.* == .method_call and std.mem.eql(u8, expr.method_call.method, "from")) return false;
    if (ctx.occurrences.get(expr) != null) return false;
    return !ctx.graph.bootstrapApplicationExpr(expr);
}

fn lowerAssignTarget(ctx: *LowerCtx, name: []const u8, value: *const ast.Expr) Error!void {
    if (applicationNeedsGraphOccurrence(ctx, value) and !recordExportMapAssignable(ctx, value)) {
        return refuseMissingApplication(ctx, @src(), value);
    }
    // `Alias = req "std.compiler.token"` binds a module at compile time; the
    // alias exists only so `Alias.CONST` can fold and `Alias.fn` can resolve to
    // an extern symbol. There is nothing to store at runtime, and lowering it as
    // an ordinary call pushed the whole program outside the direct subset.
    if (isReqCall(value)) return;
    // THE SOURCE FACE IS NOT THE ABI. `t: pt = mk(3, 2)` and `t: pt = 3:mk(2)`
    // are ONE application — same relation, same operands, same result — and
    // everything below this line reads them from the graph, which already
    // publishes them orientation-free: `applicationTarget` takes the `.binding`
    // edge, `checkedScalarOperands` projects the `.projection` subject and then
    // the position-ordered arguments. NOTHING in the record-result path asks
    // which face was written.
    //
    // This guard did, and that was the whole of the record row's refusal. A
    // `.method_call` skipped the block entirely and fell through to
    // `lowerExprCons` -> `lowerCheckedScalarCall`, whose FIRST act is
    // `checkedScalarResult` — a predicate that admits `i32 i64 bool str f64
    // void any` and nothing else. So the canonical face reached a SCALAR-ONLY
    // consumer for a RECORD result and answered DNB011 `application-result-abi`
    // while the retired operand-first face answered 5, measured. That is a
    // capability tax on canonical syntax, which `protocol-projection-one.md`
    // §10.2 forbids.
    //
    // ADMITTING THE FACE COSTS NO NEW ABI. `record-operand-register-abi`
    // already made record OPERANDS cross in registers, and this is the RESULT
    // side of the same call: `lowerCheckedRecordCallAssign` emits the identical
    // `call_direct` it emits for the operand-first face — measured
    // instruction-identical, and a normalized disassembly diff differs only in
    // the module tag on symbol names.
    //
    // A SCALAR-RESULT `.method_call` IS UNCHANGED, deliberately.
    // `recordForDescriptor` declines, `checkedScalarResult` runs the same
    // predicate `lowerCheckedScalarCall` was about to run on it, and the fall
    // through below reaches the same lowering it always did.
    if (value.* == .call or value.* == .method_call) {
        if (ctx.occurrences.get(value)) |application| {
            bindOccurrence(ctx.diagnostic, ctx.graph, application.application);
            const descriptor = try publishedDescriptor(ctx, application);
            // THE RESULT-VALUE -> SHAPE EDGE IS THE ONLY AUTHORITY for a
            // record result, and `recordForApplicationResult` is the only
            // reader of it. Recovering the record from the APPLICATION's own
            // published descriptor instead makes that edge unfalsifiable:
            // delete it and lowering still succeeds, which is exactly the
            // damage control `dnir_lower: checked aggregate result consumes
            // exact graph shape` runs. A second opinion about a fact is not a
            // fallback for it.
            if (recordForApplicationResult(ctx, application)) |record| {
                try lowerCheckedRecordCallAssign(ctx, name, application, record, value);
                return;
            }
            const results = ctx.graph.applicationResults(application.application) orelse
                return invalidGraphFacts(ctx.diagnostic, @src(), "application-result-pack");
            if (results.len == 1) {
                // Same rule one level down. `node.descriptor` is a FIELD on
                // the result node and survives deletion of the shape edge, so
                // reading a record out of it is the same unfalsifiable second
                // opinion. The node is still fetched, because its absence is a
                // real refusal.
                if (ctx.graph.get(results[0]) == null) {
                    return invalidGraphFacts(ctx.diagnostic, @src(), "application-result-member");
                }
                if (try tryAssignRecordCallFromExportMap(ctx, name, value)) return;
                try checkedScalarResult(ctx.diagnostic, descriptor);
            }
            if (try tryAssignRecordCallFromExportMap(ctx, name, value)) return;
        }
    }
    if (try tryAssignRecordCallFromExportMap(ctx, name, value)) return;
    if (value.* == .table) {
        if (tableIsPositional(value)) {
            try lowerPositionalTableAssign(ctx, name, value);
            return;
        }
        try lowerRecordLiteralAssign(ctx, name, value);
        return;
    }
    if (try Record.alias(ctx, name, value)) return;
    const v = try lowerExprCons(ctx, value, .single);
    const f64_store = exprIsF64(ctx, value);
    const pointer_store = exprIsPointer(ctx, value);
    if (ctx.locals.get(name)) |slot| {
        // THE STORE IS WHERE THE DECLARED WIDTH APPLIES — the exact place
        // `--backend=c` writes `((uint32_t)(...))`. The declared type wins over
        // whatever the initializer's own type is, which is the same rule the
        // `bool` mark above follows for the same reason.
        const store_ty: RT = if (f64_store)
            .f64
        else
            ctx.narrow_slots.get(slot) orelse .any;
        if (store_ty == .f64) try ctx.f64_slots.put(ctx.alloc, slot, {});
        if (exprIsStr(ctx, value)) try ctx.str_slots.put(ctx.alloc, slot, {});
        // THE BYTE FACE IS RECORDED AT THE SAME STORE (GAP-207). Both
        // directions: a slot REASSIGNED away from a byte sequence stops being
        // one, and leaving the mark set would refuse a legal concat for the
        // rest of the body.
        if (exprIsByteSequence(ctx, value))
            try ctx.byteseq_slots.put(ctx.alloc, slot, {})
        else
            _ = ctx.byteseq_slots.remove(slot);
        // Both directions. A slot REASSIGNED from a bool to an integer is no
        // longer a bool, and leaving the mark set would refuse a legal
        // interpolation for the rest of the function.
        if (exprIsBoolish(ctx, value))
            try ctx.bool_slots.put(ctx.alloc, slot, {})
        else
            _ = ctx.bool_slots.remove(slot);
        if (pointer_store)
            try ctx.ptr_slots.put(ctx.alloc, slot, {})
        else
            _ = ctx.ptr_slots.remove(slot);
        if (ast.intLiteralValue(value)) |n| {
            const gop = try ctx.const_ints.getOrPut(ctx.alloc, name);
            if (!gop.found_existing) gop.key_ptr.* = try ctx.alloc.dupe(u8, name);
            // The COMPILE-TIME copy of the binding's value has to be the value
            // the store leaves behind, or a numeric-for step reads 300 from a
            // `u8` that holds 44 — a decision computed against one state and
            // read against another.
            gop.value_ptr.* = narrowFitConst(n, store_ty);
        }
        try ctx.emit(.{ .op = .store_local, .result = slot, .lhs = v, .ty = store_ty });
        subsumeProducerRefit(ctx);
        return;
    }
    // A WRITTEN MODULE-SCOPE BINDING GOES TO ITS STORAGE, and this arm must sit
    // above the fresh-local fallback below — that fallback IS the defect. With
    // no local of this name in scope it minted one, so `total = total + i`
    // inside a function wrote a register nobody else could see, and the module's
    // other readers went on folding the initializer.
    if (ctx.module_globals.types.get(name)) |ty| {
        try ctx.emit(.{ .op = .store_global, .field = name, .lhs = v, .ty = ty });
        return;
    }
    const slot = ctx.freshTemp();
    try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, name), slot);
    // A slot created HERE was never declared with a type, so it carries no
    // width. `.local_decl` pre-creates the slot for every narrow declaration
    // precisely so that path never reaches this one.
    const store_ty: RT = if (f64_store) .f64 else .any;
    if (store_ty == .f64) try ctx.f64_slots.put(ctx.alloc, slot, {});
    if (exprIsStr(ctx, value)) try ctx.str_slots.put(ctx.alloc, slot, {});
    // THE BYTE FACE IS RECORDED AT THE SAME STORE (GAP-207). Both
    // directions: a slot REASSIGNED away from a byte sequence stops being
    // one, and leaving the mark set would refuse a legal concat for the
    // rest of the body.
    if (exprIsByteSequence(ctx, value))
        try ctx.byteseq_slots.put(ctx.alloc, slot, {})
    else
        _ = ctx.byteseq_slots.remove(slot);
    if (exprIsBoolish(ctx, value)) try ctx.bool_slots.put(ctx.alloc, slot, {});
    if (pointer_store) try ctx.ptr_slots.put(ctx.alloc, slot, {});
    if (ast.intLiteralValue(value)) |n| {
        const gop = try ctx.const_ints.getOrPut(ctx.alloc, name);
        if (!gop.found_existing) gop.key_ptr.* = try ctx.alloc.dupe(u8, name);
        gop.value_ptr.* = n;
    }
    try ctx.emit(.{ .op = .store_local, .result = slot, .lhs = v, .ty = store_ty });
    subsumeProducerRefit(ctx);
}

fn recordForDescriptor(
    records: []const dnir.RecordDesc,
    descriptor: types.ResolvedType,
    graph: ?*const semantic_graph.SemanticGraph,
) ?dnir.RecordDesc {
    if (descriptor == .@"struct") {
        const want = descriptor.@"struct".name;
        for (records) |record| {
            if (std.mem.eql(u8, record.name, want) and
                checkedRecordResultSupported(record)) return record;
        }
        // Foreign table shapes keep a `$shape.*` record name but the shape
        // entity's semantic name still reads `token`/`lexer`. Match that so
        // cross-home record returns reach `lowerCheckedRecordCall`.
        if (graph) |g| {
            for (records) |record| {
                const shape = record.semantic_shape orelse continue;
                const shape_node = g.get(shape) orelse continue;
                if (shape_node.name) |n| {
                    if (std.mem.eql(u8, n, want) and checkedRecordResultSupported(record))
                        return record;
                }
            }
        }
        if (findRecordByNominal(records, want, graph)) |record| return record;
        return null;
    }
    if (descriptor != .table_type) return null;
    const fields = descriptor.table_type.fields;
    for (records) |record| {
        if (record.fields.len != fields.len) continue;
        var matches = true;
        for (record.fields, record.kinds, fields) |name, kind, field| {
            if (!std.mem.eql(u8, name, field.name)) {
                matches = false;
                break;
            }
            const field_kind = tableFieldKind(field) orelse {
                matches = false;
                break;
            };
            if (field_kind != kind) {
                matches = false;
                break;
            }
        }
        if (matches and checkedRecordResultSupported(record)) return record;
    }
    for (records) |record| {
        if (recordCoversTableFields(record, fields)) return record;
    }
    return null;
}

fn recordForApplicationResult(
    ctx: *const LowerCtx,
    application: *const semantic_graph.ApplicationFact,
) ?dnir.RecordDesc {
    const shape = ctx.graph.applicationResultShape(application.application, 0) orelse return null;
    for (ctx.records) |record| {
        if (record.semantic_shape == shape and checkedRecordResultSupported(record)) return record;
    }
    const shape_node = ctx.graph.tableShapeEntity(shape) orelse return null;
    const shape_name = shape_node.name orelse return null;
    if (findRecordName(ctx.records, .{ .named = shape_name })) |record| {
        if (checkedRecordResultSupported(record)) return record;
    }
    if (findRecordByNominal(ctx.records, shape_name, ctx.graph)) |record| {
        if (checkedRecordResultSupported(record)) return record;
    }
    return null;
}

fn checkedRecordResultSupported(record: dnir.RecordDesc) bool {
    return record.fields.len > 0 and record.fields.len <= max_record_fields;
}

/// Selected callable entity id. Semantic analysis publishes both the applied
/// value and the selected implementation. This direct realization is lawful
/// only when they coincide; relation identity remains a separate graph edge.
fn applicationTarget(
    ctx: *const LowerCtx,
    application: *const semantic_graph.ApplicationFact,
) Error!semantic_graph.id {
    const applied = ctx.graph.applicationApplied(application.application) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "missing-application-applied");
    const target = ctx.graph.applicationTarget(application.application) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "missing-application-target");
    if (applied != target) {
        return invalidGraphFacts(ctx.diagnostic, @src(), "application-applied-target");
    }
    return target;
}

fn applicationRelation(
    ctx: *const LowerCtx,
    application: *const semantic_graph.ApplicationFact,
) Error!semantic_graph.id {
    return ctx.graph.applicationRelation(application.application) orelse
        invalidGraphFacts(ctx.diagnostic, @src(), "missing-application-relation");
}

/// Result consumption for checked one-result scalar/record relation calls
/// comes from the graph occurrence, never from the AST walker's separately
/// threaded context. Pack adjustment, multi-result calls, aggregate projection
/// and one-result `.multi` demand retain their existing lowering until exact
/// pack/projection correspondence owns those decisions too.
fn checkedApplicationConsumption(
    ctx: *LowerCtx,
    application: *const semantic_graph.ApplicationFact,
    result_members: []const semantic_graph.id,
    outside: types.ReturnConsumption,
) Error!types.ReturnConsumption {
    if (result_members.len != 1) return outside;
    const demand = ctx.graph.applicationDemand(application.application) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "application-demand");
    return switch (demand) {
        .discard, .single => demand,
        .multi => outside,
        .unknown => invalidGraphFacts(ctx.diagnostic, @src(), "application-demand"),
    };
}

fn linkageForTarget(ctx: *LowerCtx, target: semantic_graph.id) Error![]const u8 {
    return ctx.entity_linkage.get(target) orelse
        invalidGraphFacts(ctx.diagnostic, @src(), "missing-application-target");
}

/// Register the physical boundary selected by the callable's graph fact.
/// `foreign_home` is residence, not C origin: a local `@ffi` declaration has
/// no foreign home, while an Idol relation imported from another home does.
/// Keeping both cases here prevents every call shape from rebuilding that
/// distinction independently.
fn ensureTargetExtern(
    ctx: *LowerCtx,
    target: semantic_graph.id,
    callee: []const u8,
) Error!void {
    if (ctx.graph.callableLinkage(target)) |linkage| {
        if (linkage.exposure == .c_import) {
            if (linkage.origin != .c or !std.mem.eql(u8, linkage.symbol, callee)) {
                return invalidGraphFacts(ctx.diagnostic, @src(), "application-link-symbol");
            }
            try ensureExtern(ctx, "c", linkage.symbol, linkage.symbol);
            return;
        }
    } else if (ctx.graph.requiresCallableLinkage()) {
        return invalidGraphFacts(ctx.diagnostic, @src(), "missing-callable-linkage");
    }
    if (ctx.graph.foreignHome(target)) |foreign_home| {
        try ensureExtern(ctx, foreign_home, callee, callee);
    }
}

fn checkedRecordForApplication(
    ctx: *LowerCtx,
    application: *const semantic_graph.ApplicationFact,
) Error!?dnir.RecordDesc {
    if (recordForApplicationResult(ctx, application)) |record| return record;
    const descriptor = try publishedDescriptor(ctx, application);
    if (recordForDescriptor(ctx.records, descriptor, ctx.graph)) |record| return record;
    const results = ctx.graph.applicationResults(application.application) orelse return null;
    if (results.len == 1) {
        const result_node = ctx.graph.get(results[0]) orelse return null;
        if (result_node.descriptor) |result_desc| {
            if (recordForDescriptor(ctx.records, result_desc, ctx.graph)) |record| return record;
        }
    }
    return null;
}

fn lowerCheckedRecordCall(
    ctx: *LowerCtx,
    application: *const semantic_graph.ApplicationFact,
    record: dnir.RecordDesc,
    consumption: types.ReturnConsumption,
) Error!dnir.Value {
    bindOccurrence(ctx.diagnostic, ctx.graph, application.application);
    const relation = try applicationRelation(ctx, application);
    const target = try applicationTarget(ctx, application);
    const callee = try linkageForTarget(ctx, target);
    try ensureTargetExtern(ctx, target, callee);
    const result = try checkedApplicationResult(ctx, application);
    var operand_storage: [max_direct_scalar_args]CheckedScalarOperand = undefined;
    const operands = try checkedScalarOperands(ctx, application, &operand_storage, true);
    var slot_storage: [max_direct_scalar_args]StagedSlot = undefined;
    const slots = try evaluateCheckedScalarOperands(ctx, application, operands, &slot_storage);
    const realization_start: u32 = @intCast(ctx.instrs.items.len);
    try stageCheckedScalarOperands(ctx, slots);
    const descriptor = try publishedDescriptor(ctx, application);
    if (consumption == .discard) {
        try ctx.emit(.{
            .op = .call_direct,
            .relation = relation,
            .application = application.application,
            .value = result,
            .subject = ctx.graph.applicationSubject(application.application),
            .target = target,
            .realization_start = realization_start,
            .callee = callee,
            .record = record.name,
            .field = "",
            .ty = descriptor,
        });
        return .void;
    }
    const rec_slot = ctx.freshTemp();
    const anon = try std.fmt.allocPrint(ctx.alloc, "__rec{d}", .{rec_slot});
    defer ctx.alloc.free(anon);
    try ctx.emit(.{
        .op = .call_direct,
        .relation = relation,
        .application = application.application,
        .value = result,
        .subject = ctx.graph.applicationSubject(application.application),
        .target = target,
        .realization_start = realization_start,
        .result = rec_slot,
        .callee = callee,
        .record = record.name,
        .field = anon,
        .ty = descriptor,
    });
    try ctx.emit(.{ .op = .init_record, .result = rec_slot, .record = record.name, .field = anon });
    for (record.fields, 0..) |fname, fi| {
        const fk = try std.fmt.allocPrint(ctx.alloc, "{s}.{s}", .{ anon, fname });
        defer ctx.alloc.free(fk);
        if (ctx.locals.contains(fk)) continue;
        const fslot = ctx.freshTemp();
        try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, fk), fslot);
        if (fi < record.kinds.len) switch (record.kinds[fi]) {
            .str => try ctx.str_slots.put(ctx.alloc, fslot, {}),
            .f64 => try ctx.f64_slots.put(ctx.alloc, fslot, {}),
            .i64 => {},
        };
    }
    return .{ .temp = rec_slot };
}

fn lowerCheckedRecordCallAssign(
    ctx: *LowerCtx,
    name: []const u8,
    application: *const semantic_graph.ApplicationFact,
    record: dnir.RecordDesc,
    _call_value: *const Expr,
) Error!void {
    _ = _call_value;
    bindOccurrence(ctx.diagnostic, ctx.graph, application.application);
    const result_members = ctx.graph.applicationResults(application.application) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "application-result-pack");
    const demand = try checkedApplicationConsumption(ctx, application, result_members, .single);
    if (demand != .single) {
        return invalidGraphFacts(ctx.diagnostic, @src(), "application-result-consumption");
    }
    const relation = try applicationRelation(ctx, application);
    const target = try applicationTarget(ctx, application);
    const callee = try linkageForTarget(ctx, target);
    try ensureTargetExtern(ctx, target, callee);
    const result = try checkedApplicationResult(ctx, application);
    // THE BINDING NEEDS A NAME, NOT A VALUE. Everything downstream that has
    // to recognise `name` as a record region -- `loadFieldFromOpaquePath`,
    // `recordLocalDesc` -- asks whether the name is bound at all; the slot
    // itself is never stored to, because the record lives in the frame region
    // `call_direct` fills below. Minting it is what lets `a.b.c` resolve
    // against the region instead of bailing.
    if (ctx.locals.get(name) == null) {
        const slot = ctx.freshTemp();
        try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, name), slot);
    }
    var operand_storage: [max_direct_scalar_args]CheckedScalarOperand = undefined;
    // THE SUBJECT IS AN OPERAND LIKE ANY OTHER, and the graph publishes it in
    // position 0. Excluding it here on the theory that "the projection subject
    // is the assignee" dropped the FIRST ARGUMENT of every plain call:
    // `t: tok = mk(5)` reached `mk` with x0 never written, so `mk` read argc.
    // Measured on examples/native_differential/canon4_descriptor_in_record.id,
    // which answered 3 instead of 7. Every other checked-call consumer
    // (`lowerCheckedRecordCall`, `lowerCheckedScalarCall`) projects the subject,
    // and the result side of a call has no reason to differ from the rest.
    const operands = try checkedScalarOperands(ctx, application, &operand_storage, true);
    var slot_storage: [max_direct_scalar_args]StagedSlot = undefined;
    const slots = try evaluateCheckedScalarOperands(ctx, application, operands, &slot_storage);
    const realization_start: u32 = @intCast(ctx.instrs.items.len);
    try stageCheckedScalarOperands(ctx, slots);
    const descriptor = try publishedDescriptor(ctx, application);
    try ctx.emit(.{
        .op = .call_direct,
        .relation = relation,
        .application = application.application,
        .value = result,
        .subject = ctx.graph.applicationSubject(application.application),
        .target = target,
        .realization_start = realization_start,
        .callee = callee,
        .record = record.name,
        .field = name,
        .ty = descriptor,
    });
    // AND NOTHING ELSE. The `call_direct` above already carries `.record` and
    // `.field`, and that pair IS the realization: the backend answers it with
    // `assignRecordFromAbiRegs(ins.field, rec)` for a register return and with
    // the x8 buffer for an indirect one. A following `init_record` on the same
    // `.record`/`.field` re-runs that copy after the caller-save registers have
    // been restored, so it writes call debris over a result that already landed.
    //
    // MINTING `name.field` LOCALS IS THE SAME ERROR STATED AS STORAGE. Those
    // slots are never stored to -- the fields live in the frame region -- but
    // `lowerField` checks `ctx.locals` FIRST, so every later `v.a` resolved to
    // a slot holding nothing and the backend answered `DNB007 local N has no
    // register`. Leaving the keys unminted sends `v.a` to
    // `loadFieldFromOpaquePath`, which emits the `load_field` that reads the
    // region the call actually filled.
}

fn lowerRecordCallAssign(ctx: *LowerCtx, name: []const u8, callee: []const u8, args: []const *ast.Expr, rec_name: []const u8) Error!void {
    // Marshal through scalarCallLhs like every other call path. Lowering only
    // `args[0]` meant a record-returning call silently dropped every later
    // argument: `scan_one(src, pos)` reached the callee with `pos` never
    // written, so it read whatever the caller happened to leave in x1.
    const arg0 = try scalarCallLhs(ctx, args, callee);
    try ctx.emit(.{ .op = .call_direct, .callee = callee, .lhs = arg0, .record = rec_name, .field = name });
    const rec_slot = ctx.freshTemp();
    try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, name), rec_slot);
    try ctx.emit(.{ .op = .init_record, .result = rec_slot, .record = rec_name, .field = name });
}

fn tryAssignRecordCallFromExportMap(ctx: *LowerCtx, name: []const u8, value: *const ast.Expr) Error!bool {
    if (ctx.require_graph_facts) return false;
    const export_name = try qualifiedExportNameFromExpr(ctx.alloc, value) orelse return false;
    defer ctx.alloc.free(export_name);
    const rec_name = ctx.func_record_returns.get(export_name) orelse return false;
    const args = switch (value.*) {
        .call => |c| c.args,
        .method_call => |m| m.args,
        else => return false,
    };
    try lowerRecordCallAssign(ctx, name, export_name, args, rec_name);
    return true;
}

// ---------------------------------------------------------------------------
// REPRESENTATION IS A DECISION, AND SIZE IS NOT THE FACT THAT DECIDES IT.
//
// `select_chain_max` used to be the whole decision, and it produced a 43x cliff
// between two programs that differ only in how many literals were written:
//
//     t = (1 … 32) ; t(2)   ->    4 instructions
//     t = (1 … 33) ; t(2)   ->  174 instructions      same answer, the literal 2
//
// Both answers were fully determined before the program ran — constant contents,
// constant index, no writes, no escape — and one of them was computed at run time
// out of frame memory anyway. Extent is a fact about how to REALIZE a table that
// must exist; it says nothing about whether one must exist at all. That question
// is answered below, from the uses, and its answer holds at every extent.
//
// What is asked here is deliberately narrow and entirely local: does the rest of
// this function ever do anything to this name other than read it at a
// compile-time index? Anything else at all — a write, a bare mention, an
// unrecognized construct — declines. Declining costs speed; being wrong costs the
// answer, and this tree has already paid that twice (materialization re-run per
// loop iteration, and two representations live in one function). So the walker
// below has NO permissive default: an expression kind it does not model returns
// `.opaque_use` whether or not it mentions the name.
// ---------------------------------------------------------------------------

/// How a function body uses one bound name, worst case. Ordered: a later variant
/// subsumes an earlier one.
const TableUse = enum {
    /// Never mentioned after the binding.
    none,
    /// Only ever `t(k)` with `k` a compile-time integer.
    const_read,
    /// Also read at an index only known at run time.
    dyn_read,
    /// Written, rebound, shadowed, passed on, or used in a shape not modeled
    /// here. NOTHING may be assumed about the table.
    opaque_use,
};

fn worseUse(a: TableUse, b: TableUse) TableUse {
    return if (@backingInt(b) > @backingInt(a)) b else a;
}

/// `k` as a compile-time integer, for an index expression. Literals only — a
/// name resolved through `const_ints` is NOT accepted, because that map records
/// a name's last literal binding and is never invalidated by a later
/// non-literal assignment, so it would answer for a variable that has since
/// moved. A wrong element is a wrong answer that still compiles.
fn constIndexOf(graph: ?*const semantic_graph.SemanticGraph, require_graph_facts: bool, key: *const ast.Expr) ?i64 {
    if (require_graph_facts) return if (graph) |g| g.exactI64OfExpr(key) else null;
    return ast.intLiteralValue(key);
}

fn tableUseInExpr(graph: ?*const semantic_graph.SemanticGraph, require_graph_facts: bool, expr: *const ast.Expr, name: []const u8) TableUse {
    return switch (expr.*) {
        .nil, .true_lit, .false_lit, .int_lit, .float_lit, .quoted, .vararg => .none,
        .semantic, .semantic_scope => .none,
        .name => |n| if (std.mem.eql(u8, n.ident, name)) .opaque_use else .none,
        .index => |ix| blk: {
            // The READ face. `t(k)` and `t[k]` are the same node by the time
            // lowering sees them (`table_apply.zig` canonicalizes the call form),
            // so this one arm covers both spellings.
            const in_key = tableUseInExpr(graph, require_graph_facts, ix.key, name);
            if (ix.obj.* == .name and std.mem.eql(u8, ix.obj.name.ident, name)) {
                const here: TableUse = if (constIndexOf(graph, require_graph_facts, ix.key) != null) .const_read else .dyn_read;
                break :blk worseUse(here, in_key);
            }
            break :blk worseUse(tableUseInExpr(graph, require_graph_facts, ix.obj, name), in_key);
        },
        .field => |f| tableUseInExpr(graph, require_graph_facts, f.obj, name),
        .call => |c| blk: {
            var u = tableUseInExpr(graph, require_graph_facts, c.func, name);
            for (c.args) |a| u = worseUse(u, tableUseInExpr(graph, require_graph_facts, a, name));
            break :blk u;
        },
        .method_call => |m| blk: {
            // COLLECTION-RELATION-ONE. `xs:any(p)` is NOT an opaque mention of
            // `xs`: it reads each element at a FIXED position, writes none,
            // rebinds nothing and lets nothing escape — which is exactly the
            // `const_read` verdict `t(1)`, `t(2)`, … would earn written out.
            //
            // WITHOUT THIS ARM THE STRONGER RELATION IS THE SLOWER ONE.
            // Measured before it existed: the flag-and-scan loop this relation
            // replaces folded to **2 instructions** while `xs:any(…)` emitted
            // **65**, because the bare receiver read as `.opaque_use` and
            // materialized all six elements into registers. That is HPLS §2
            // exactly — a true fact making the best realization worse — and
            // §3's negative abstraction tax says the richer form owes the
            // cheaper code, not the same code.
            if (collection_relation.shapeOf(expr)) |shape| {
                if (shape.subject.* == .name and
                    std.mem.eql(u8, shape.subject.name.ident, name))
                {
                    break :blk worseUse(.const_read, tableUseInExpr(graph, require_graph_facts, shape.body, name));
                }
            }
            var u = tableUseInExpr(graph, require_graph_facts, m.obj, name);
            for (m.args) |a| u = worseUse(u, tableUseInExpr(graph, require_graph_facts, a, name));
            break :blk u;
        },
        .binop => |b| worseUse(tableUseInExpr(graph, require_graph_facts, b.lhs, name), tableUseInExpr(graph, require_graph_facts, b.rhs, name)),
        .unop => |u| tableUseInExpr(graph, require_graph_facts, u.operand, name),
        .try_expr => |x| tableUseInExpr(graph, require_graph_facts, x.operand, name),
        .unwrap_expr => |x| tableUseInExpr(graph, require_graph_facts, x.operand, name),
        .await_expr => |x| tableUseInExpr(graph, require_graph_facts, x.operand, name),
        .quote => |q| tableUseInExpr(graph, require_graph_facts, q.expr, name),
        .unquote => |q| tableUseInExpr(graph, require_graph_facts, q.expr, name),
        .contains_expr => |c| worseUse(tableUseInExpr(graph, require_graph_facts, c.lhs, name), tableUseInExpr(graph, require_graph_facts, c.rhs, name)),
        .if_expr => |ie| worseUse(
            tableUseInExpr(graph, require_graph_facts, ie.cond, name),
            worseUse(tableUseInExpr(graph, require_graph_facts, ie.then_expr, name), tableUseInExpr(graph, require_graph_facts, ie.else_expr, name)),
        ),
        .sequence => |s| blk: {
            var u: TableUse = .none;
            for (s.exprs) |e| u = worseUse(u, tableUseInExpr(graph, require_graph_facts, e, name));
            break :blk u;
        },
        .range => |r| blk: {
            var u = worseUse(tableUseInExpr(graph, require_graph_facts, r.start, name), tableUseInExpr(graph, require_graph_facts, r.end, name));
            if (r.step) |st| u = worseUse(u, tableUseInExpr(graph, require_graph_facts, st, name));
            break :blk u;
        },
        .macro_call => |mc| blk: {
            var u: TableUse = .none;
            for (mc.args) |a| u = worseUse(u, tableUseInExpr(graph, require_graph_facts, a, name));
            break :blk u;
        },
        .table => |t| blk: {
            var u: TableUse = .none;
            for (t.fields) |fld| {
                u = worseUse(u, switch (fld) {
                    .positional => |v| tableUseInExpr(graph, require_graph_facts, v, name),
                    .named => |nf| tableUseInExpr(graph, require_graph_facts, nf.val, name),
                    .semantic => |sf| tableUseInExpr(graph, require_graph_facts, sf.val, name),
                    .spread => |sp| tableUseInExpr(graph, require_graph_facts, sp, name),
                    .indexed => |ix| worseUse(tableUseInExpr(graph, require_graph_facts, ix.key, name), tableUseInExpr(graph, require_graph_facts, ix.val, name)),
                });
            }
            break :blk u;
        },
        .match_expr => |m| blk: {
            var u = tableUseInExpr(graph, require_graph_facts, m.scrutinee, name);
            for (m.arms) |arm| {
                if (arm.guard) |g| u = worseUse(u, tableUseInExpr(graph, require_graph_facts, g, name));
                // A pattern that BINDS this name shadows the table from here on.
                if (patternBinds(arm.pattern, name)) break :blk .opaque_use;
                u = worseUse(u, tableUseInBlock(graph, require_graph_facts, &arm.body, name, m.scrutinee));
            }
            break :blk u;
        },
        // `func_expr` and `list_comp` introduce their own scope and their own
        // capture rules. Neither is modeled, so neither is assumed about.
        .func_expr, .list_comp => .opaque_use,
    };
}

fn patternBinds(pat: ast.Pattern, name: []const u8) bool {
    return switch (pat) {
        .binding => |b| std.mem.eql(u8, b.name, name),
        .rest => |r| std.mem.eql(u8, r, name),
        .variant => |v| blk: {
            const payload = v.payload orelse break :blk false;
            for (payload) |p| if (patternBinds(p, name)) break :blk true;
            break :blk false;
        },
        .table_destr => |entries| blk: {
            for (entries) |e| if (patternBinds(e.pat, name)) break :blk true;
            break :blk false;
        },
        .array_destr => |pats| blk: {
            for (pats) |p| if (patternBinds(p, name)) break :blk true;
            break :blk false;
        },
        .literal, .wildcard => false,
    };
}

/// An assignment TARGET naming this table is a WRITE, whatever its shape:
/// `t = …` rebinds it and `t(k) = …` mutates it. Either way the initializer's
/// literals stop being the whole truth.
fn targetWrites(target: *const ast.Expr, name: []const u8) bool {
    return switch (target.*) {
        .name => |n| std.mem.eql(u8, n.ident, name),
        .index => |ix| targetWrites(ix.obj, name),
        .field => |f| targetWrites(f.obj, name),
        else => true,
    };
}

/// `bound` is the initializer expression of the binding being judged. That one
/// occurrence is THE binding and is not a use of it; every other binding of the
/// same name — a second declaration, a reassignment, a loop variable, a pattern
/// capture — replaces the table and is `.opaque_use`. Identity is by POINTER,
/// not by name, so "the binding" cannot be confused with a later one.
fn tableUseInBlock(graph: ?*const semantic_graph.SemanticGraph, require_graph_facts: bool, block: *const ast.Block, name: []const u8, bound: *const ast.Expr) TableUse {
    var u: TableUse = .none;
    for (block.stmts) |*s| {
        u = worseUse(u, tableUseInStmt(graph, require_graph_facts, s, name, bound));
        if (u == .opaque_use) return u;
    }
    if (block.tail_expr) |t| u = worseUse(u, tableUseInExpr(graph, require_graph_facts, t, name));
    return u;
}

/// What a whole-body scan learned about the bindings of one name.
///
/// `writes` counts BINDINGS, not mentions: a read cannot change what a name
/// holds, and refusing on reads would leave the fact unusable — `s:len()` is
/// itself a read. `opaque` is the honest third answer for a statement shape
/// this scan does not model, which is neither "bound here" nor "not bound
/// here" and must not be read as either.
const TextBind = struct {
    writes: u32 = 0,
    literal: ?[]const u8 = null,
    opaque_bind: bool = false,

    fn note(self: *TextBind, init: ?*const ast.Expr) void {
        self.writes += 1;
        self.literal = if (init) |e| quotedLiteralBytes(e) else null;
    }
};

fn textBindInBlock(block: *const ast.Block, name: []const u8, out: *TextBind) void {
    for (block.stmts) |*st| textBindInStmt(st, name, out);
}

fn textBindInStmt(stmt: *const ast.Stmt, name: []const u8, out: *TextBind) void {
    switch (stmt.*) {
        .local_decl => |d| for (d.names, 0..) |n, i| {
            if (!std.mem.eql(u8, n.ident, name)) continue;
            out.note(if (i < d.inits.len) d.inits[i] else null);
        },
        .global_decl => |d| for (d.names, 0..) |n, i| {
            if (!std.mem.eql(u8, n.ident, name)) continue;
            out.note(if (i < d.inits.len) d.inits[i] else null);
        },
        .const_decl => |d| if (std.mem.eql(u8, d.ident, name)) out.note(d.val),
        .assign => |a| for (a.targets, 0..) |t, i| {
            if (t.* != .name) continue;
            if (!std.mem.eql(u8, t.name.ident, name)) continue;
            out.note(if (i < a.values.len) a.values[i] else null);
        },
        .do_block => |d| textBindInBlock(&d.body, name, out),
        .while_loop => |w| textBindInBlock(&w.body, name, out),
        .repeat_loop => |r| textBindInBlock(&r.body, name, out),
        .if_stmt => |f| {
            if (f.binding) |b| if (std.mem.eql(u8, b.name, name)) out.note(b.expr);
            textBindInBlock(&f.then, name, out);
            for (f.elseifs) |ei| textBindInBlock(&ei.body, name, out);
            if (f.else_body) |eb| textBindInBlock(&eb, name, out);
        },
        // A LOOP VARIABLE IS BOUND ONCE PER TRIP, and never to a literal this
        // scan can read. Counting it as a binding is what keeps `for s = …`
        // from inheriting an outer `s = "abc"`.
        .num_for => |n| {
            if (std.mem.eql(u8, n.var_name, name)) out.note(null);
            textBindInBlock(&n.body, name, out);
        },
        .gen_for => |g| {
            for (g.vars) |v| if (std.mem.eql(u8, v, name)) out.note(null);
            textBindInBlock(&g.body, name, out);
        },
        // Statement shapes that bind nothing at this scope.
        .call_stmt,
        .expr_stmt,
        .ret,
        .brk,
        .cont,
        .goto_stmt,
        .label_stmt,
        .cinclude,
        .directive,
        => {},
        // EVERYTHING ELSE IS `opaque`, AND THAT IS THE POINT. A nested
        // relation, a match arm, a `try`/`defer` body or a definition form may
        // bind this name in a way the arms above do not describe, and an
        // unmodeled shape read as "no binding" is exactly how a determined fact
        // becomes a wrong answer. The scan says so instead of guessing.
        else => out.opaque_bind = true,
    }
}

/// The byte length of `expr` when the program already determines every byte of
/// it — `null` when it does not, and the length must be measured at run time.
///
/// THIS IS THE FACT THAT WAS MISSING. `:len()` lowered unconditionally to
/// `str_len`, which is a SCAN TO THE FIRST NUL in both realizations
/// (`native_backend` inline loop, `wasm_backend` `helperStrlen`). For a
/// literal that is not a length at all, it is a C representation detail
/// answering a semantic question: `"a\0b":len()` measured 1 on the direct
/// backend and 1 on Wasm — agreeing, and both wrong, where Lua 5.4 §3.4.7 and
/// `docs/spec/text.md` say 3. Nothing about the source was unknown; the length
/// was simply never carried.
///
/// A literal answers for itself. A NAME answers only when the body binds it
/// EXACTLY ONCE, to a literal, and the name is not an operand — one binding is
/// what makes the fact hold at every reachable read, including inside a loop
/// and on both sides of a branch. Two bindings mean the answer depends on which
/// one ran, so there is no fact, and the scan is what MEASURES that rather than
/// assuming it. This is the same safety `noteConstTable` takes from
/// `tableUseInBlock`, narrowed to the one question a length needs.
/// THE BYTES A QUOTED LITERAL CARRIES, ASKED IN ONE PLACE.
///
/// Two consumers need the same fact — `determinedTextLen` needs its EXTENT and
/// `TextBind.note` needs the payload itself — and each spelled its own tag
/// test for it. `gate/token/read.sh` counts exactly that form and caps
/// it, because a consumer reaching a quoted node through an equality test on
/// the tag is invisible to the switch-arm census GAP-145 reports (and the
/// census counts the spelling, so this sentence does not write it): `planConcat` was
/// written that way and folded every quoted part into a printf format string
/// without asking which face it had.
///
/// This reads EXTENT AND PAYLOAD, which are face-independent. `law.text.byte`
/// gives cardinality and layout to a byte sequence exactly as to text; the two
/// faces differ in what the octets MEAN, and nothing here decides that. The
/// face question has its own producer — `types.quotedLiteralType`, asked
/// through `graphByteSequenceConst` / `exprIsByteSequence` — and no consumer
/// may answer it from this tag.
fn quotedLiteralBytes(expr: *const ast.Expr) ?[]const u8 {
    if (expr.* != .quoted) return null;
    return expr.quoted.val;
}

fn determinedTextLen(ctx: *LowerCtx, expr: *const ast.Expr) ?i64 {
    if (quotedLiteralBytes(expr)) |bytes| return @intCast(bytes.len);
    if (expr.* != .name) return null;
    const name = expr.name.ident;
    const slot = ctx.locals.get(name) orelse {
        // NO LOCAL OF THIS NAME, so the module binding is what the name reaches.
        // `ModuleConsts.strs` is already gated on `moduleConstIsStable`, which
        // is the same one-binding proof the body scan below performs — it
        // counts every write in the module INCLUDING the ones inside relation
        // bodies — so an entry here is a determined value by construction.
        const bytes = ctx.module_consts.strs.get(name) orelse return null;
        return @intCast(bytes.len);
    };
    if (slot < ctx.param_slots) return null;
    // NO ENCLOSING BLOCK MEANS THE MODULE ENTRY, AND ITS SLOTS ARE THE MODULE'S
    // OWN BINDINGS. `root` (the file-scope process entry) builds its context
    // without a `body`
    // (there are only two `LowerCtx` constructions in this file, and it is the
    // one that omits it), so the one-binding scan below had nothing to walk and
    // this returned `null` for EVERY module-scope name. That is a missing
    // measurement read as a missing fact, and it is the whole reason
    // `examples/table/str/nul.id` — `s = "a\0b"` bound AND measured at file
    // scope — still answered 1 on both realizations after the relation-body
    // face was repaired: `s` has a module slot, so the lookup above found one
    // and fell into this arm instead of reaching the module-const arm that
    // already held the right answer.
    //
    // The module binding has its OWN one-write proof and it is the STRONGER of
    // the two. `ModuleConsts.strs` is gated on `moduleConstIsStable`, which
    // counts every write to the name in the module INCLUDING the ones inside
    // relation bodies; `textBindInBlock` sees only the block handed to it. So
    // asking the module fact here is not a widening — a name a relation
    // rebinds never entered that map, and a name bound twice at file scope
    // never entered it either.
    const body = ctx.body orelse {
        const bytes = ctx.module_consts.strs.get(name) orelse return null;
        return @intCast(bytes.len);
    };
    var found: TextBind = .{};
    textBindInBlock(body, name, &found);
    if (found.opaque_bind or found.writes != 1) return null;
    const bytes = found.literal orelse return null;
    return @intCast(bytes.len);
}

/// Uses contributed by a name/value binding pair. `.none` for the one pair that
/// IS this binding; `.opaque_use` for any other pair that binds the name.
fn bindingPairUse(
    graph: ?*const semantic_graph.SemanticGraph,
    require_graph_facts: bool,
    n: []const u8,
    init: ?*const ast.Expr,
    name: []const u8,
    bound: *const ast.Expr,
) TableUse {
    const init_use: TableUse = if (init) |e| tableUseInExpr(graph, require_graph_facts, e, name) else .none;
    if (!std.mem.eql(u8, n, name)) return init_use;
    if (init) |e| if (e == bound) return .none;
    return .opaque_use;
}

fn tableUseInStmt(graph: ?*const semantic_graph.SemanticGraph, require_graph_facts: bool, stmt: *const ast.Stmt, name: []const u8, bound: *const ast.Expr) TableUse {
    return switch (stmt.*) {
        .local_decl => |d| blk: {
            var u: TableUse = .none;
            for (d.names, 0..) |n, i| {
                const init: ?*const ast.Expr = if (i < d.inits.len) d.inits[i] else null;
                u = worseUse(u, bindingPairUse(graph, require_graph_facts, n.ident, init, name, bound));
            }
            // An initializer with no name of its own is still evaluated.
            if (d.inits.len > d.names.len) {
                for (d.inits[d.names.len..]) |e| u = worseUse(u, tableUseInExpr(graph, require_graph_facts, e, name));
            }
            break :blk u;
        },
        .const_decl => |d| blk: {
            if (std.mem.eql(u8, d.ident, name)) break :blk .opaque_use;
            break :blk tableUseInExpr(graph, require_graph_facts, d.val, name);
        },
        .global_decl => |d| blk: {
            var u: TableUse = .none;
            for (d.names, 0..) |n, i| {
                const init: ?*const ast.Expr = if (i < d.inits.len) d.inits[i] else null;
                u = worseUse(u, bindingPairUse(graph, require_graph_facts, n.ident, init, name, bound));
            }
            if (d.inits.len > d.names.len) {
                for (d.inits[d.names.len..]) |e| u = worseUse(u, tableUseInExpr(graph, require_graph_facts, e, name));
            }
            break :blk u;
        },
        .assign => |a| blk: {
            var u: TableUse = .none;
            for (a.targets, 0..) |t, i| {
                const val: ?*const ast.Expr = if (i < a.values.len) a.values[i] else null;
                if (t.* == .name) {
                    u = worseUse(u, bindingPairUse(graph, require_graph_facts, t.name.ident, val, name, bound));
                    continue;
                }
                // `t(k) = …` / `t.f = …` mutate the table in place.
                if (targetWrites(t, name)) break :blk .opaque_use;
                u = worseUse(u, tableUseInExpr(graph, require_graph_facts, t, name));
                if (val) |v| u = worseUse(u, tableUseInExpr(graph, require_graph_facts, v, name));
            }
            if (a.values.len > a.targets.len) {
                for (a.values[a.targets.len..]) |e| u = worseUse(u, tableUseInExpr(graph, require_graph_facts, e, name));
            }
            break :blk u;
        },
        .call_stmt => |c| tableUseInExpr(graph, require_graph_facts, c.expr, name),
        .expr_stmt => |c| tableUseInExpr(graph, require_graph_facts, c.expr, name),
        .do_block => |d| tableUseInBlock(graph, require_graph_facts, &d.body, name, bound),
        .while_loop => |w| worseUse(tableUseInExpr(graph, require_graph_facts, w.cond, name), tableUseInBlock(graph, require_graph_facts, &w.body, name, bound)),
        .repeat_loop => |r| worseUse(tableUseInBlock(graph, require_graph_facts, &r.body, name, bound), tableUseInExpr(graph, require_graph_facts, r.cond, name)),
        .if_stmt => |f| blk: {
            var u: TableUse = .none;
            if (f.binding) |b| {
                if (std.mem.eql(u8, b.name, name)) break :blk .opaque_use;
                u = worseUse(u, tableUseInExpr(graph, require_graph_facts, b.expr, name));
            }
            u = worseUse(u, tableUseInExpr(graph, require_graph_facts, f.cond, name));
            u = worseUse(u, tableUseInBlock(graph, require_graph_facts, &f.then, name, bound));
            for (f.elseifs) |ei| {
                u = worseUse(u, tableUseInExpr(graph, require_graph_facts, ei.cond, name));
                u = worseUse(u, tableUseInBlock(graph, require_graph_facts, &ei.body, name, bound));
            }
            if (f.else_body) |eb| u = worseUse(u, tableUseInBlock(graph, require_graph_facts, &eb, name, bound));
            break :blk u;
        },
        .num_for => |n| blk: {
            if (std.mem.eql(u8, n.var_name, name)) break :blk .opaque_use;
            var u = worseUse(tableUseInExpr(graph, require_graph_facts, n.start, name), tableUseInExpr(graph, require_graph_facts, n.stop, name));
            if (n.step) |st| u = worseUse(u, tableUseInExpr(graph, require_graph_facts, st, name));
            break :blk worseUse(u, tableUseInBlock(graph, require_graph_facts, &n.body, name, bound));
        },
        .gen_for => |g| blk: {
            for (g.vars) |v| if (std.mem.eql(u8, v, name)) break :blk .opaque_use;
            var u: TableUse = .none;
            for (g.iters) |e| u = worseUse(u, tableUseInExpr(graph, require_graph_facts, e, name));
            break :blk worseUse(u, tableUseInBlock(graph, require_graph_facts, &g.body, name, bound));
        },
        .ret => |r| blk: {
            var u: TableUse = .none;
            for (r.vals) |e| u = worseUse(u, tableUseInExpr(graph, require_graph_facts, e, name));
            break :blk u;
        },
        .brk, .cont, .goto_stmt, .label_stmt => .none,
        // A FUNCTION DECLARATION IS A BLOCK LIKE ANY OTHER. Leaving it
        // unmodeled meant `else => .opaque_use` fired for every module that
        // declares one — which is every real program — so no module-level table
        // could ever be judged constant, however it was used. The walk descends
        // instead, with the two ways a declaration can take the name away:
        .func_decl => |fd| blk: {
            // The declaration binds its own path; if that head IS the table's
            // name the table is replaced.
            if (fd.path.len > 0 and std.mem.eql(u8, fd.path[0], name)) break :blk .opaque_use;
            // A parameter of the same name shadows the module binding for the
            // whole body, so nothing inside is a use of THIS table.
            for (fd.func.params) |prm| {
                if (std.mem.eql(u8, prm.name, name)) break :blk .none;
            }
            if (fd.func.vararg_name) |vn| {
                if (std.mem.eql(u8, vn, name)) break :blk .none;
            }
            break :blk tableUseInBlock(graph, require_graph_facts, &fd.func.body, name, bound);
        },
        // Same rule as the expression walker: an unmodeled statement is not
        // evidence of absence.
        else => .opaque_use,
    };
}

/// Every element as a compile-time integer, or null.
///
/// Integers only. A float table would need the same treatment on the f64 side,
/// and a `.f64` slot and an `.i64` immediate are different representations —
/// mixing them is exactly the confusion that produced this tree's other
/// wrong-answer regression, so the float case is DECLINED here rather than
/// approximated.
fn constTableValues(ctx: *LowerCtx, table: *const ast.Expr) Error!?[]i64 {
    if (table.* != .table) return null;
    var n: usize = 0;
    for (table.table.fields) |fld| {
        if (fld != .positional) return null;
        if (constIndexOf(ctx.graph, ctx.require_graph_facts, fld.positional) == null) return null;
        n += 1;
    }
    if (n == 0) return null;
    const out = try ctx.alloc.alloc(i64, n);
    var i: usize = 0;
    for (table.table.fields) |fld| {
        out[i] = constIndexOf(ctx.graph, ctx.require_graph_facts, fld.positional).?;
        i += 1;
    }
    return out;
}

/// Decide, AT THE BINDING, what is known about `name`, and record it.
///
/// Returns the use verdict so the caller can also decide whether to emit any
/// storage at all. The decision is taken here and nowhere else: an access site
/// is routinely inside a loop, and a representation chosen there re-runs its
/// setup per iteration — which is how a previous attempt at this silently
/// restored tables to their initial values every trip.
fn noteConstTable(ctx: *LowerCtx, name: []const u8, table: *const ast.Expr) Error!TableUse {
    const body = ctx.body orelse return .opaque_use;
    const use = tableUseInBlock(ctx.graph, ctx.require_graph_facts, body, name, table);
    if (use == .opaque_use) return use;
    const values = (try constTableValues(ctx, table)) orelse return .opaque_use;
    errdefer ctx.alloc.free(values);
    // A name bound twice in one body is `.opaque_use` above, so this cannot
    // overwrite a live entry.
    const key = try ctx.alloc.dupe(u8, name);
    errdefer ctx.alloc.free(key);
    try ctx.const_tables.put(ctx.alloc, key, values);
    return use;
}

/// Decide, AT THE BINDING, what is known about `name`'s numeric value, and record it.
/// Follows the `noteConstTable` pattern: the whole body is scanned; exactly one
/// binding and no unmodeled statement shape, and the binding must be the
/// top-level statement now being lowered. The initializer is evaluated by
/// `comptime_eval` (the producer) with already-recorded constants in scope, so
/// transitive constants (`y = x + 0.2` after `x = 0.1`) resolve. A `: f64`/`: f32`
/// annotation projects through `applyFloatContract` at record time -- the
/// annotation is the sole projection site; unannotated keeps the exact decimal.
/// Anything not provably a constant numeric is not recorded (fail closed).
fn noteConstNum(
    ctx: *LowerCtx,
    stmt: *const ast.Stmt,
    name: []const u8,
    init: *const ast.Expr,
    typ: ast.TypeExpr,
) Error!void {
    if (ctx.module_root) return;
    const body = ctx.body orelse return;
    // The binding must be a top-level statement of the body being lowered: a
    // conditional or loop-carried binding does not dominate its uses.
    var is_top_level = false;
    for (body.stmts) |*s| if (s == stmt) {
        is_top_level = true;
        break;
    };
    if (!is_top_level) return;
    // Exactly one binding in the whole body, and no statement shape the scan
    // does not model (which might bind the name unseen).
    var tb: TextBind = .{};
    textBindInBlock(body, name, &tb);
    if (tb.writes != 1 or tb.opaque_bind) return;
    // A module global of the same spelling is not this local.
    if (ctx.module_globals.types.contains(name)) return;
    // Evaluate with the producer. Module constants first, then already-recorded
    // function constants (transitivity); the local shadows on collision.
    var scope: std.StringHashMapUnmanaged(comptime_eval.Value) = .empty;
    defer scope.deinit(ctx.alloc);
    var mit = ctx.module_consts.nums.iterator();
    while (mit.next()) |e| scope.put(ctx.alloc, e.key_ptr.*, e.value_ptr.*) catch return;
    var cit = ctx.const_nums.iterator();
    while (cit.next()) |e| scope.put(ctx.alloc, e.key_ptr.*, e.value_ptr.*) catch return;
    const scopes = [_]std.StringHashMapUnmanaged(comptime_eval.Value){scope};
    const opts = comptime_eval.Options{ .step_limit = 10_000, .alloc = ctx.alloc };
    const v = comptime_eval.evalWithBindings(init, .{ .scopes = &scopes }, opts) catch return;
    switch (v) {
        .decimal, .float, .int => {},
        else => return,
    }
    // THE SOLE PROJECTION SITE. A stated float type projects the value here;
    // unannotated (`.inferred`) keeps the exact decimal.
    const contracted = comptime_eval.Evaluator.applyFloatContract(
        v,
        comptime_eval.Evaluator.floatContractOfType(typ),
    );
    switch (contracted) {
        .decimal, .float, .int => {},
        else => return,
    }
    const key = try ctx.alloc.dupe(u8, name);
    errdefer ctx.alloc.free(key);
    // Cannot overwrite: the scan proved exactly one binding.
    try ctx.const_nums.put(ctx.alloc, key, contracted);
}

/// `t(k)` where `t` was proved determined and `k` is compile-time — the element,
/// as an immediate, at any extent.
///
/// A constant index OUTSIDE the extent returns an error rather than a value.
/// Tables are 1-indexed, so `t(0)` is out of range as surely as `t(len + 1)` is,
/// and both are refused at compile time. That refusal is not new — a
/// register-exploded table already refused it by failing to find the element's
/// local — but it now holds at every width, where the memory-backed path used to
/// emit an unguarded load of whatever lay next to the region.
fn constTableRead(ctx: *LowerCtx, expr: *const ast.Expr) Error!?dnir.Value {
    if (expr.* != .index) return null;
    const ix = expr.index;
    if (ix.obj.* != .name) return null;
    const values = ctx.const_tables.get(ix.obj.name.ident) orelse return null;
    const k = constIndexOf(ctx.graph, ctx.require_graph_facts, ix.key) orelse return null;
    if (k < 1 or k > @as(i64, @intCast(values.len))) return bail(ctx.diagnostic, @src());
    return dnir.Value{ .i64 = values[@intCast(k - 1)] };
}

/// Bind `t.len`. The length of a positional table is static in every
/// realization, so it is a foldable constant whichever way the elements go —
/// including the realization that emits no elements.
fn bindTableLen(ctx: *LowerCtx, name: []const u8, len: i64) Error!void {
    const len_key = try std.fmt.allocPrint(ctx.alloc, "{s}.len", .{name});
    const len_slot = ctx.freshTemp();
    try ctx.locals.put(ctx.alloc, len_key, len_slot);
    try ctx.emit(.{ .op = .store_local, .result = len_slot, .lhs = .{ .i64 = len }, .ty = .any });
    try ctx.table_lens.put(ctx.alloc, len_slot, len);
}

/// Record `name` as a table whose every element is text.
///
/// The verdict is taken AT THE BINDING for the same reason `noteConstTable`'s
/// is: a read site is routinely inside a loop, and the answer must not depend
/// on which of the three storage paths the binding chose. `tableUseInBlock`
/// supplies the safety — a table that is written, rebound, shadowed or passed
/// on is `.opaque_use`, and nothing may be assumed about what a later read of
/// it holds.
fn noteStrTable(ctx: *LowerCtx, name: []const u8, table: *const ast.Expr) Error!void {
    const body = ctx.body orelse return;
    if (table.* != .table or table.table.fields.len == 0) return;
    for (table.table.fields) |fld| {
        if (fld != .positional) return;
        if (!exprIsStr(ctx, fld.positional)) return;
    }
    if (@backingInt(tableUseInBlock(ctx.graph, ctx.require_graph_facts, body, name, table)) > @backingInt(TableUse.dyn_read)) return;
    const key = try ctx.alloc.dupe(u8, name);
    errdefer ctx.alloc.free(key);
    try ctx.str_tables.put(ctx.alloc, key, {});
}

/// `t = { 10, 20, 30 }` — a positional table with a statically known length.
///
/// Elements become one local per slot, keyed `t.1`, `t.2`, … exactly as record
/// fields are. That makes constant indexing (`t[2]`) a compile-time slot lookup
/// with no memory traffic at all — the element lives in a register.
///
/// Dynamic indexing (`t[i]`) is deliberately NOT handled here: it needs a real
/// base pointer and a computed offset, which is the native table-lowering
/// milestone. Constant indexing is the slice that fits the proven subset today.
fn lowerPositionalTableAssign(ctx: *LowerCtx, name: []const u8, table: *const ast.Expr) Error!void {
    if (table.* != .table) return bail(ctx.diagnostic, @src());
    try noteStrTable(ctx, name, table);
    const use = try noteConstTable(ctx, name, table);
    if (@backingInt(use) <= @backingInt(TableUse.const_read)) {
        // DETERMINED, and read only at compile-time indices: the table itself is
        // not a thing this function needs. Bind the length (still a foldable
        // constant, so `#t` costs nothing) and emit no elements at all — every
        // read is answered by `constTableRead`. This is the branch that makes the
        // width irrelevant, because it is taken at 4 elements and at 4096.
        try bindTableLen(ctx, name, @intCast(ctx.const_tables.get(name).?.len));
        return;
    }
    if (ctx.tables_in_memory) return lowerPositionalTableIntoMemory(ctx, name, table);
    const t_slot = ctx.freshTemp();
    try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, name), t_slot);
    var idx: usize = 1;
    for (table.table.fields) |fld| {
        const val = switch (fld) {
            .positional => |v| v,
            else => return bail(ctx.diagnostic, @src()),
        };
        const v = try lowerExpr(ctx, val);
        const eslot = ctx.freshTemp();
        const key = try std.fmt.allocPrint(ctx.alloc, "{s}.{d}", .{ name, idx });
        try ctx.locals.put(ctx.alloc, key, eslot);
        const store_ty: RT = if (exprIsF64(ctx, val)) .f64 else .any;
        if (store_ty == .f64) try ctx.f64_slots.put(ctx.alloc, eslot, {});
        try ctx.emit(.{ .op = .store_local, .result = eslot, .lhs = v, .ty = store_ty });
        idx += 1;
    }
    // Length as a foldable constant, so `#t` can resolve without memory.
    const len_key = try std.fmt.allocPrint(ctx.alloc, "{s}.len", .{name});
    const len_slot = ctx.freshTemp();
    try ctx.locals.put(ctx.alloc, len_key, len_slot);
    try ctx.emit(.{ .op = .store_local, .result = len_slot, .lhs = .{ .i64 = @intCast(idx - 1) }, .ty = .any });
    try ctx.table_lens.put(ctx.alloc, len_slot, @intCast(idx - 1));

    // Wider than the select chain pays for: move it to frame memory NOW, at the
    // binding, so every access lowers to one scaled load/store.
    //
    // It has to happen here rather than at the first dynamic access, because
    // materialization emits `alloc_slots` plus a copy from the element
    // registers, and an access site is routinely inside a loop — emitting it
    // there re-runs the copy every iteration and silently restores the table to
    // its initial value, discarding all prior writes. That is exactly what a
    // first attempt did: orders 17+ stopped bailing and started returning wrong
    // answers. The binding executes once, so this placement cannot.
}

/// The same binding, built straight into frame memory.
///
/// Going through the element registers first and copying afterwards (what
/// `materializeTableSlots` does for a table that only later turns out to need a
/// base pointer) costs one live register per element. At the widths this path
/// exists to serve that is hundreds of them, and the backend correctly refused
/// with DNB003 register pressure. Here the element value is stored to its slot
/// and dropped, so a table of any width costs a constant number of registers.
fn lowerPositionalTableIntoMemory(ctx: *LowerCtx, name: []const u8, table: *const ast.Expr) Error!void {
    var len: i64 = 0;
    for (table.table.fields) |fld| {
        if (fld != .positional) return bail(ctx.diagnostic, @src());
        len += 1;
    }
    if (len <= 0 or len > 4096) return bail(ctx.diagnostic, @src());

    const base = ctx.freshTemp();
    try ctx.emit(.{ .op = .alloc_slots, .result = base, .lhs = .{ .i64 = len } });

    var i: i64 = 1;
    for (table.table.fields) |fld| {
        const v = try lowerExpr(ctx, fld.positional);
        try ctx.emit(.{
            .op = .store_index,
            .ty = .i64,
            .lhs = .{ .temp = base },
            .rhs = .{ .i64 = i },
            .third = v,
        });
        i += 1;
    }

    // Bound after the initializers, so an element expression naming the table
    // resolves to whatever it meant before this binding rather than to the
    // half-filled region being built here.
    try ctx.ptr_slots.put(ctx.alloc, base, {});
    try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, name), base);

    // `#t` still folds to a constant; the length never needs memory.
    const len_key = try std.fmt.allocPrint(ctx.alloc, "{s}.len", .{name});
    const len_slot = ctx.freshTemp();
    try ctx.locals.put(ctx.alloc, len_key, len_slot);
    try ctx.emit(.{ .op = .store_local, .result = len_slot, .lhs = .{ .i64 = len }, .ty = .any });
    try ctx.table_lens.put(ctx.alloc, len_slot, len);
}

/// gap[063] — `abort()` when a dynamic index leaves a register-exploded table's
/// range, instead of silently doing nothing.
///
/// A positional table lowered to registers has a FIXED capacity; an Idol table
/// GROWS. The select-chain below matched no slot for an out-of-range index and
/// simply fell through, so `t = { 0 }` followed by `t[i] = i` for i in 1..3 kept
/// only the first write and the program printed 1 where the C oracle printed 6 —
/// a wrong answer, reported as `ok compile`, exit 0. Nine ordinary lines.
///
/// The trap does not make the program work; it makes the limit OBSERVABLE. A
/// program that stays inside the capacity — every fixture that motivated the
/// select-chain does — never reaches it, and pays two compares. The real repair
/// is a growable native table, which is a representation change, not a patch
/// here; until then the choice is between a loud stop and a quiet lie.
///
/// Emitted for the STORE and for the dynamic READ, because the read has the same
/// defect from the other side: an out-of-range read answered 0 where the table
/// has no such element at all.
/// `test:assert(cond, msg)` and `test:equal(a, b, msg)` — the test world's
/// relations, lowered to a real trap.
///
/// An assertion that only type-checks is not an assertion. These become a
/// branch and an `abort`, the same shape the index bounds trap already uses, so
/// a failing assertion stops the process rather than being decoration. The
/// message operand is checked for arity and is not otherwise realized here —
/// there is no output channel in this subset to carry it.
fn lowerTestRelation(ctx: *LowerCtx, method: []const u8, args: []const *const ast.Expr) Error!?dnir.Value {
    const cond: dnir.Value = blk: {
        if (std.mem.eql(u8, method, "assert")) {
            if (args.len < 1) return bail(ctx.diagnostic, @src());
            break :blk try lowerExpr(ctx, args[0]);
        }
        if (std.mem.eql(u8, method, "refute")) {
            if (args.len < 1) return bail(ctx.diagnostic, @src());
            const v = try lowerExpr(ctx, args[0]);
            const t = ctx.freshTemp();
            try ctx.emit(.{ .op = .binop, .result = t, .binop = .eq, .lhs = v, .rhs = .{ .i64 = 0 } });
            break :blk .{ .temp = t };
        }
        if (std.mem.eql(u8, method, "equal") or std.mem.eql(u8, method, "differs")) {
            if (args.len < 2) return bail(ctx.diagnostic, @src());
            const a = try lowerExpr(ctx, args[0]);
            const b = try lowerExpr(ctx, args[1]);
            const t = ctx.freshTemp();
            const op: dnir.BinOpTag = if (std.mem.eql(u8, method, "equal")) .eq else .neq;
            try ctx.emit(.{ .op = .binop, .result = t, .binop = op, .lhs = a, .rhs = b });
            break :blk .{ .temp = t };
        }
        return null;
    };
    try ensureExtern(ctx, "os", "abort", "abort");
    const bad = ctx.instrs.items.len;
    try ctx.emit(.{ .op = .br, .lhs = cond, .branch_target = 0, .branch_condition = .when_false });
    const skip = ctx.instrs.items.len;
    try ctx.emit(.{ .op = .br, .branch_target = 0 });
    const trap: u32 = @intCast(ctx.instrs.items.len);
    ctx.instrs.items[bad].branch_target = trap;
    try ctx.emit(.{ .op = .call_extern, .callee = "abort" });
    ctx.instrs.items[skip].branch_target = @intCast(ctx.instrs.items.len);
    return .void;
}

/// Marks a DNIR `hw_unary` as a TERMINATING TRAP rather than a scalar bit
/// intrinsic. `native.zig` reads the same constant and expands it to an
/// inline instruction sequence that raises SIGABRT.
///
/// TRAP, DON'T CALL. This used to be `call_extern abort`, and the cost of that
/// was not the two words at the trap site — it was everything the word CALL
/// means to the rest of the backend:
///
///   1. `dnirFunctionHasCall` counts `call_extern`, so a never-taken bounds
///      check made the whole function "a function with a call".
///   2. `gate_spill_all_locals = body_has_call`, so EVERY local lost its
///      register home and became a stack slot reloaded per use.
///   3. `dnirNeedsCalleeSave` followed, dragging in the full x19–x28
///      save/restore block a leaf never needs.
///   4. `spill_reserve` opened an unconditional ~8 KB stack pit.
///   5. The `bl` itself needed `emitSaveCallerRegs` around it — nine stores and
///      nine loads guarding registers across a call that never returns.
///
/// Measured on `s += t(i)` over an eight-element table: 142 instructions, one
/// dynamic import, against 2 for the same loop with no table at all.
///
/// A trap is not a call. It does not return, so nothing needs preserving across
/// it; it does not use x30, so nothing needs a frame; and it resolves no symbol,
/// so the artifact keeps no import. The four gates above all key off
/// `call_extern` and none of them fire.
///
/// It rides `hw_unary` + `.field` because a trap is not expressible in
/// `native/ir.zig`'s `Op` set and that file is not this pass's to change. The
/// convention is not invented here: `mov_arg` already discriminates its
/// variadic-tail form with `.field = "vararg"`, and the vector reduction above
/// uses the same seam. `.hw` stays `.none`, so `intrinsicOfOp`,
/// `functionHardwareTier` and `moduleHardwareTier` all read exactly what they
/// read before — a trap is not a hardware intrinsic and must not raise a
/// module's reported tier. `.result` is null, so `definition` establishes no
/// slot, which is right: control never leaves this instruction.
pub const trap_abort_tag = "trap.abort";

/// The one place a trap is emitted. Both trap sites — the index bounds check and
/// a failed `test:assert` — mean the same thing (stop the process, do not
/// return), so they emit the same instruction rather than two spellings of it.
fn emitTrap(ctx: *LowerCtx) Error!void {
    try ctx.emit(.{ .op = .hw_unary, .hw = .none, .field = trap_abort_tag });
}

/// Static element count of a positional table bound in this function, or null
/// when the extent is not known here — which is exactly the case for a `ptr`
/// PARAMETER, where the table was bound in some other function and only its base
/// address crossed the boundary. No extent, no guard: a check against a length
/// this function does not have would be a guess.
fn staticTableLen(ctx: *const LowerCtx, name: []const u8) ?i64 {
    var buf: [512]u8 = undefined;
    const len_key = std.fmt.bufPrint(&buf, "{s}.len", .{name}) catch return null;
    const len_slot = ctx.locals.get(len_key) orelse return null;
    return ctx.table_lens.get(len_slot);
}

/// GAP-185: is this place's authority statically fixed — the zero-cost rung?
/// Reads the per-place plans `lower.collectStaticPlaces` populated on the
/// graph. When true, the compiler's own proof (unique, nonescape, readonly,
/// exact determinacy) covers spatial safety and the runtime bounds check
/// can be elided.
fn placeAuthorityIsStatic(ctx: *const LowerCtx, name: []const u8) bool {
    const set = ctx.graph.static_places orelse return false;
    return set.contains(name);
}

/// The index to use for a MEMORY-BACKED access, with the range decided first.
///
/// The register-exploded representation has always refused a statically
/// out-of-range index (there is no element local to name) and trapped a dynamic
/// one (gap[063]). The memory-backed representation, which the same table falls
/// into purely by being wider, did NEITHER: `t(0)` on a 40-element table read the
/// word below the region and answered with it, and `t(41)` read the word above.
/// Same program, same index, same table — a different answer decided by how many
/// literals were written. That is the size threshold showing up as a CORRECTNESS
/// difference rather than a speed one, and it is the reason the two paths are
/// brought level here.
///
///   constant, in range   — nothing emitted; the extent already proved it.
///   constant, out of range — REFUSED at compile time, as the narrow path does.
///   dynamic              — the bounds trap, as the narrow path does.
///
/// Affordable now precisely because the trap stopped being a call: before
/// `trap_abort_tag` this guard would have set `body_has_call` on every function
/// that touches a wide table and cost each one its entire register allocation,
/// which is why "check the wide path too" was not a small change until now.
fn guardedTableIndex(ctx: *LowerCtx, table_name: []const u8, key_expr: *const ast.Expr) Error!dnir.Value {
    const len = staticTableLen(ctx, table_name) orelse return try lowerExpr(ctx, key_expr);
    if (ast.intLiteralValue(key_expr)) |k| {
        if (k < 1 or k > len) return bail(ctx.diagnostic, @src());
        return .{ .i64 = k };
    }
    const idx_slot = ctx.freshTemp();
    const raw = try lowerExpr(ctx, key_expr);
    try ctx.emit(.{ .op = .store_local, .result = idx_slot, .lhs = raw, .ty = .any });
    // GAP-185: elide the bounds check when the place's authority is
    // statically fixed — the zero-cost rung. The compiler's own proof
    // (unique, nonescape, readonly, exact determinacy) covers spatial
    // safety, so no runtime enforcement is needed.
    if (!placeAuthorityIsStatic(ctx, table_name))
        try emitIndexBoundsTrap(ctx, idx_slot, len);
    return .{ .local = idx_slot };
}

/// `1 <= i <= len`, as ONE instruction for the backend to expand.
///
/// It used to be two `binop` comparisons and three `br`s, which the backend
/// fused into five machine instructions on the path that is taken plus two
/// hoisted constants. Written that way the range test was FOUR DNIR values wide
/// — two comparison temps and two immediates — and the register allocator paid
/// for all of them inside the loop that reads the table.
///
/// The pair of bounds is not two facts. It is one range, and one UNSIGNED
/// compare of `i - 1` against `len - 1` decides it, because `i <= 0` wraps to
/// the top of the unsigned range and fails the same test `i > len` fails. That
/// expansion belongs to the backend (`emitIndexBoundsCheck`), because unsigned
/// comparison has no `dnir.BinOpTag` and inventing one would put a second,
/// nearly-identical comparison family into every consumer of DNIR for the sake
/// of one call site.
///
/// The tag convention is the one `trap_abort_tag` already established: a
/// `hw_unary` with `.hw = .none` and a `.field` the backend matches. `.result`
/// is null — this instruction defines no value, it only decides whether control
/// continues.
pub const index_bounds_tag = "index.bounds";

/// Widest extent whose `len - 1` still fits the compare's 12-bit immediate.
/// Past it the fused form would need a register for the limit and would stop
/// being one instruction, so the portable two-comparison expansion below is
/// used instead — it is correct at every extent and is what every table used
/// before this seam existed.
const fused_bounds_max: i64 = 4096;

fn emitIndexBoundsTrap(ctx: *LowerCtx, idx_slot: u32, len: i64) Error!void {
    if (len >= 1 and len <= fused_bounds_max) {
        try ctx.emit(.{
            .op = .hw_unary,
            .hw = .none,
            .field = index_bounds_tag,
            .lhs = .{ .local = idx_slot },
            .rhs = .{ .i64 = len },
        });
        return;
    }

    const lo = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = lo, .binop = .geq, .lhs = .{ .local = idx_slot }, .rhs = .{ .i64 = 1 } });
    const lo_bad = ctx.instrs.items.len;
    try ctx.emit(.{ .op = .br, .lhs = .{ .temp = lo }, .branch_target = 0, .branch_condition = .when_false });

    const hi = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = hi, .binop = .leq, .lhs = .{ .local = idx_slot }, .rhs = .{ .i64 = len } });
    const hi_bad = ctx.instrs.items.len;
    try ctx.emit(.{ .op = .br, .lhs = .{ .temp = hi }, .branch_target = 0, .branch_condition = .when_false });

    const skip = ctx.instrs.items.len;
    try ctx.emit(.{ .op = .br, .branch_target = 0 });

    const trap: u32 = @intCast(ctx.instrs.items.len);
    ctx.instrs.items[lo_bad].branch_target = trap;
    ctx.instrs.items[hi_bad].branch_target = trap;
    try emitTrap(ctx);
    ctx.instrs.items[skip].branch_target = @intCast(ctx.instrs.items.len);
}

/// `t[k] = v` on a positional table.
///
/// The mirror of `lowerDynamicIndex`. A constant index stores straight into the
/// element's own local. A non-constant index becomes a select-chain of stores —
/// `if k == 1 { t.1 = v }  if k == 2 { t.2 = v }  …` — which needs no memory,
/// because the elements are registers. Together with dynamic reads this makes a
/// fixed-size table genuinely *mutable*, which is what a bounded symbol table
/// needs: declare into a slot, look it up later.
///
/// An out-of-range index TRAPS — see `emitIndexBoundsTrap`. It used to store
/// nowhere, which is gap[063].
fn lowerIndexAssignTarget(
    ctx: *LowerCtx,
    obj: *const ast.Expr,
    key_expr: *const ast.Expr,
    value: *const ast.Expr,
) Error!void {
    if (obj.* != .name) return bail(ctx.diagnostic, @src());
    const table_name = obj.name.ident;
    const table_slot = ctx.locals.get(table_name) orelse return bail(ctx.diagnostic, @src());

    // HASH-TABLE PATH. `t = {}` binds a `*HashTable`; every store goes through
    // `duo_hash_store(t, key_str, value_i64)`. The key is taken as a string
    // expression — `key_expr` MUST lower to a `str`-typed register for the
    // call to match the runtime's `const char *` argument. Today the only
    // table kind this branch serves is the empty literal; the same gate would
    // accept any future `t = {a = "k" → v}` form once the parser admits it.
    if (ctx.hash_slots.contains(table_slot)) {
        try ensureExtern(ctx, "table", "store", "duo_hash_store");
        const key_val = try lowerExpr(ctx, key_expr);
        const v = try lowerExprCons(ctx, value, .single);
        try ctx.emit(.{ .op = .mov_arg, .result = 0, .lhs = .{ .local = table_slot } });
        try ctx.emit(.{ .op = .mov_arg, .result = 1, .lhs = key_val });
        try ctx.emit(.{ .op = .mov_arg, .result = 2, .lhs = v });
        try ctx.emit(.{ .op = .call_extern, .callee = "duo_hash_store", .ty = .any });
        return;
    }

    // Memory-backed table: a real scaled store, so writes through a shared base
    // are visible to every function holding it.
    if (ptrSlotOf(ctx, obj)) |base| {
        const idx = try guardedTableIndex(ctx, table_name, key_expr);
        const v = try lowerExprCons(ctx, value, .single);
        try ctx.emit(.{
            .op = .store_index,
            .ty = .i64,
            .lhs = .{ .local = base },
            .rhs = idx,
            .third = v,
        });
        return;
    }

    if (ast.intLiteralValue(key_expr)) |n| {
        const key = try std.fmt.allocPrint(ctx.alloc, "{s}.{d}", .{ table_name, n });
        defer ctx.alloc.free(key);
        const slot = ctx.locals.get(key) orelse return bail(ctx.diagnostic, @src());
        const v = try lowerExprCons(ctx, value, .single);
        try ctx.emit(.{ .op = .store_local, .result = slot, .lhs = v, .ty = .any });
        return;
    }

    const len_key = try std.fmt.allocPrint(ctx.alloc, "{s}.len", .{table_name});
    defer ctx.alloc.free(len_key);
    const len_slot = ctx.locals.get(len_key) orelse return bail(ctx.diagnostic, @src());
    const len = ctx.table_lens.get(len_slot) orelse return bail(ctx.diagnostic, @src());
    // A table wider than this is materialized into memory at its BINDING, so it
    // reaches the `ptrSlotOf` path above and never arrives here.
    if (len == 0 or len > select_chain_max) return bail(ctx.diagnostic, @src());

    // Evaluate index and value once, before any store, so a select-chain cannot
    // re-run side effects per candidate slot.
    const idx_slot = ctx.freshTemp();
    try ctx.emit(.{ .op = .store_local, .result = idx_slot, .lhs = try lowerExpr(ctx, key_expr), .ty = .any });
    // GAP-185: elide the bounds check when the place's authority is statically fixed.
    if (!placeAuthorityIsStatic(ctx, table_name))
        try emitIndexBoundsTrap(ctx, idx_slot, len);
    const val_slot = ctx.freshTemp();
    try ctx.emit(.{ .op = .store_local, .result = val_slot, .lhs = try lowerExprCons(ctx, value, .single), .ty = .any });

    var i: i64 = 1;
    while (i <= len) : (i += 1) {
        const elem_key = try std.fmt.allocPrint(ctx.alloc, "{s}.{d}", .{ table_name, i });
        defer ctx.alloc.free(elem_key);
        const elem_slot = ctx.locals.get(elem_key) orelse return bail(ctx.diagnostic, @src());

        const cmp = ctx.freshTemp();
        try ctx.emit(.{
            .op = .binop,
            .result = cmp,
            .binop = .eq,
            .lhs = .{ .local = idx_slot },
            .rhs = .{ .i64 = i },
        });
        const skip = ctx.instrs.items.len;
        try ctx.emit(.{ .op = .br, .lhs = .{ .temp = cmp }, .branch_target = 0, .branch_condition = .when_false });
        try ctx.emit(.{ .op = .store_local, .result = elem_slot, .lhs = .{ .local = val_slot }, .ty = .any });
        ctx.instrs.items[skip].branch_target = @intCast(ctx.instrs.items.len);
    }
}

/// `t[i]` where `i` is not a compile-time constant.
///
/// The elements of a positional table live in registers, not memory, so there is
/// no base pointer to offset from. For a table of statically known length the
/// correct lowering is a select over the element slots:
///
///     S = 0;  if i == 1 { S = t.1 }  if i == 2 { S = t.2 }  …  S
///
/// That is O(n) compares, which is the right trade for the small fixed-size
/// tables a compiler actually uses — and it needs no memory traffic at all.
/// An out-of-range index TRAPS (gap[063]); it used to yield 0, which reads as
/// "a missing positional entry" and is indistinguishable from a stored zero.
///
/// A genuinely dynamic, growable table still needs base-pointer addressing;
/// this handles the fixed-length case, which is what fits in registers.
fn lowerDynamicIndex(ctx: *LowerCtx, table_name: []const u8, key_expr: *const ast.Expr) Error!dnir.Value {
    const table_slot = ctx.locals.get(table_name);

    // HASH-TABLE LOAD. `t = {}` lookup, mirroring `lowerIndexAssignTarget`'s
    // store branch: register `duo_hash_load(t, key_str)` and read its i64
    // return. Missing keys return 0, which `.nil` also lowers to, so the
    // `t[k] != nil` check shape used by the agreement test stays honest.
    if (table_slot) |slot| if (ctx.hash_slots.contains(slot)) {
        try ensureExtern(ctx, "table", "load", "duo_hash_load");
        const key_val = try lowerExpr(ctx, key_expr);
        const out_slot = ctx.freshTemp();
        try ctx.emit(.{ .op = .mov_arg, .result = 0, .lhs = .{ .local = slot } });
        try ctx.emit(.{ .op = .mov_arg, .result = 1, .lhs = key_val });
        try ctx.emit(.{ .op = .call_extern, .result = out_slot, .callee = "duo_hash_load", .ty = .any });
        return .{ .local = out_slot };
    };

    const len_key = try std.fmt.allocPrint(ctx.alloc, "{s}.len", .{table_name});
    defer ctx.alloc.free(len_key);
    const len: i64 = if (ctx.locals.get(len_key)) |len_slot|
        ctx.table_lens.get(len_slot) orelse return bail(ctx.diagnostic, @src())
    else
        ctx.module_consts.ints.get(len_key) orelse return bail(ctx.diagnostic, @src());
    const is_module_table = ctx.locals.get(len_key) == null;
    // The local path bails above `select_chain_max` because a wide LOCAL table
    // is supposed to materialize into memory at its binding — and the read path
    // would only see it via `ptrSlotOf` above, not here. Module-level positional
    // tables are different: their elements are literals already living in
    // `module_consts.strs` / `module_consts.ints`, the select chain lowers each
    // element as an immediate, and there is no `__DATA` word that COULD hold a
    // base pointer — so the cap would block a path the table has to walk.
    if (len == 0) return bail(ctx.diagnostic, @src());
    if (!is_module_table and len > select_chain_max) return bail(ctx.diagnostic, @src());

    const idx_slot = ctx.freshTemp();
    try ctx.emit(.{ .op = .store_local, .result = idx_slot, .lhs = try lowerExpr(ctx, key_expr), .ty = .any });
    // THE RANGE DECISION IS THIS CHAIN'S TOTALITY, NOT AN ENFORCEMENT MECHANISM,
    // so the GAP-185 static-place elision (`placeAuthorityIsStatic`) is not
    // consulted here and the trap is unconditional.
    //
    // Two separate reasons, and either alone settles it.
    //
    // 1. The chain has no out-of-range BEHAVIOUR to protect — it has an
    //    out-of-range ANSWER. No compare matches, `out_slot` keeps the zero it
    //    is initialized with below, and the marking two lines further down
    //    hands that zero to consumers AS TEXT. Eliding a memory access's
    //    check trades a fault for an unchecked access; eliding this one trades
    //    a fault for a wrong value, and a null pointer classified as a string
    //    is exactly the failure this gap exists around.
    //
    // 2. The plan being consumed says the opposite of what the emission is
    //    doing. `static` requires `determinacy == .exact` — every access to
    //    the place statically determined — and reaching this function means
    //    the index is NOT a literal (`lowerExprCons`'s `.index` arm takes the
    //    constant path first). So an emission that is itself a runtime-indexed
    //    access would be discharging its range decision against a proof that
    //    no runtime-indexed access exists. Measured: when the census sees the
    //    read, the place is `.bounded` and no plan is offered — the elision
    //    can only ever fire when the two passes disagree about the same read,
    //    which is the drift class this gap has already paid for three times.
    //
    // The same shape stands unrepaired at the memory-backed read
    // (`guardedTableIndex`) and the select-chain WRITE above; both are outside
    // this gap's subject and are recorded in `gaps/GAP-204.md` for their owner.
    try emitIndexBoundsTrap(ctx, idx_slot, len);

    const out_slot = ctx.freshTemp();
    try ctx.emit(.{ .op = .store_local, .result = out_slot, .lhs = .{ .i64 = 0 }, .ty = .any });
    // The select chain returns a SLOT, not an expression, so `holds` is the
    // only thing a consumer that never sees the AST node can ask. It has to
    // agree with `exprIsStr`'s `.index` arm or the two classifiers disagree on
    // one read — which is the shape that printed a pointer.
    if (ctx.str_tables.contains(table_name) or ctx.module_consts.str_tables.contains(table_name))
        try ctx.str_slots.put(ctx.alloc, out_slot, {});

    var i: i64 = 1;
    while (i <= len) : (i += 1) {
        const elem_key = try std.fmt.allocPrint(ctx.alloc, "{s}.{d}", .{ table_name, i });
        defer ctx.alloc.free(elem_key);
        // Local slot when bound in a function; module constant when bound at
        // module level. Both spell the key `"{s}.{d}"`; only storage differs.
        const elem_val: dnir.Value = if (ctx.locals.get(elem_key)) |elem_slot|
            .{ .local = elem_slot }
        else if (ctx.module_consts.strs.get(elem_key)) |sv|
            .{ .str = sv }
        else if (ctx.module_consts.ints.get(elem_key)) |iv|
            .{ .i64 = iv }
        else
            return bail(ctx.diagnostic, @src());

        const cmp = ctx.freshTemp();
        try ctx.emit(.{
            .op = .binop,
            .result = cmp,
            .binop = .eq,
            .lhs = .{ .local = idx_slot },
            .rhs = .{ .i64 = i },
        });
        const skip = ctx.instrs.items.len;
        try ctx.emit(.{ .op = .br, .lhs = .{ .temp = cmp }, .branch_target = 0, .branch_condition = .when_false });
        try ctx.emit(.{ .op = .store_local, .result = out_slot, .lhs = elem_val, .ty = .any });
        ctx.instrs.items[skip].branch_target = @intCast(ctx.instrs.items.len);
    }
    return .{ .local = out_slot };
}

/// True when every field of a table literal is positional.
fn tableIsPositional(table: *const ast.Expr) bool {
    if (table.* != .table) return false;
    if (table.table.fields.len == 0) return false;
    for (table.table.fields) |fld| {
        if (fld != .positional) return false;
    }
    return true;
}

fn lowerRecordLiteralAssign(ctx: *LowerCtx, name: []const u8, table: *const ast.Expr) Error!void {
    if (table.* != .table) return bail(ctx.diagnostic, @src());
    // AN EMPTY LITERAL `{}` BINDS A RUNTIME HASH TABLE. There are no fields
    // to lower into element slots, so the record-literal path below has
    // nothing to emit — and the positional-table path correctly refused at
    // `len == 0` because a select-chain over zero entries is no chain at
    // all. `agreement.id` needs the runtime form because the literal IS the
    // table: every subsequent `t[k] = v` and `t[k]` is the point of the test,
    // and a literal-vs-built-key agreement has to land on the same hash
    // bucket whichever side wrote it. The `*HashTable` is registered as a
    // `hash_slot` (not a positional `ptr_slot`) so `lowerIndexAssignTarget`
    // and `lowerDynamicIndex` know to route through `duo_hash_store`/`_load`
    // instead of the integer select-chain.
    if (table.table.fields.len == 0) {
        try ensureExtern(ctx, "table", "new", "duo_hash_new");
        const hslot = ctx.freshTemp();
        try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, name), hslot);
        try ctx.hash_slots.put(ctx.alloc, hslot, {});
        try ctx.emit(.{ .op = .call_extern, .result = hslot, .callee = "duo_hash_new", .ty = .any });
        return;
    }
    // A TABLE WHOSE FIELDS ARE `__DATA` WORDS BINDS NO MARKER SLOT. The marker
    // exists so `isRecordLocalName` and the whole-value paths can see that the
    // name is a bound record — but those paths then read the fields out of
    // `ctx.locals`, and for this table they are not there. Binding it anyway
    // would leave a register nothing writes standing in for the table. The
    // fields are still emitted below; only the whole-value face is withheld,
    // and `lowerExpr`'s `.name` arm refuses it by name.
    if (!moduleFieldStorageBase(ctx, name)) {
        const prior = ctx.locals.get(name);
        const rec_slot = ctx.freshTemp();
        try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, name), rec_slot);
        try lowerRecordLiteralFields(ctx, name, table);
        const rec_name = inferRecordNameFromTable(ctx.records, table) orelse "";
        try ctx.emit(.{ .op = .init_record, .result = rec_slot, .record = rec_name });
        if (ctx.require_graph_facts and !ctx.graph.gateTransportModule()) if (prior) |slot| {
            if (ctx.directory.contains(slot)) {
                const value = ctx.graph.valueByAst(table) orelse return invalidGraphFacts(ctx.diagnostic, @src(), "record-initializer-value");
                const node = ctx.graph.get(value) orelse return invalidGraphFacts(ctx.diagnostic, @src(), "record-initializer-value");
                const binding = ctx.graph.get(node.scope orelse return invalidGraphFacts(ctx.diagnostic, @src(), "record-initializer-binding")) orelse return invalidGraphFacts(ctx.diagnostic, @src(), "record-initializer-binding");
                if (binding.scope != ctx.function or !std.mem.eql(u8, binding.name orelse return invalidGraphFacts(ctx.diagnostic, @src(), "record-initializer-binding"), name))
                    return invalidGraphFacts(ctx.diagnostic, @src(), "record-initializer-binding");
                const shape = ctx.graph.descriptorShape(value, 0) orelse return invalidGraphFacts(ctx.diagnostic, @src(), "record-initializer-shape");
                const actual = for (ctx.records) |record| {
                    if (record.semantic_shape == shape) break record;
                } else return invalidGraphFacts(ctx.diagnostic, @src(), "record-initializer-shape");
                const required = recordLocalDesc(ctx, name) orelse return invalidGraphFacts(ctx.diagnostic, @src(), "record-initializer-shape");
                if (!Record.fits(actual, required)) return invalidGraphFacts(ctx.diagnostic, @src(), "record-initializer-carrier");
                _ = try ctx.resident(name, value, actual);
            }
        };
        return;
    }
    try lowerRecordLiteralFields(ctx, name, table);
}

/// Write one local per field under `prefix`, recursing through nested records.
///
/// Explosion keys a field as `"<prefix>.<field>"`, and a field whose value is
/// itself a record literal simply extends the prefix: `o = { i = { x = 40 } }`
/// stores `o.i.x`. Before this, the inner `{ x = 40 }` was handed to
/// `lowerExpr`, which has no `.table` arm, so a record holding a record refused
/// the whole module.
///
/// The recursion carries no depth limit because the key is what bounds it — a
/// record type cannot contain itself by value, so the nesting is as finite as
/// the type declarations that produced it.
///
/// Field order comes from the LITERAL here, which is safe only because these
/// are keyed locals rather than ABI slots: `o.y` names the same storage no
/// matter where `y` was written. A record crossing a function boundary takes
/// its order from the DESCRIPTOR instead — that is `recordFieldOrder`'s job,
/// not this one, and conflating the two is the field-ordering miscompile this
/// backend has already had twice.
fn copyPrefixedLocalsFromRecordRef(
    ctx: *LowerCtx,
    dest_prefix: []const u8,
    src_base: []const u8,
) Error!void {
    var src_buf: [256]u8 = undefined;
    const src_pat = std.fmt.bufPrint(&src_buf, "{s}.", .{src_base}) catch return bail(ctx.diagnostic, @src());
    var it = ctx.locals.iterator();
    while (it.next()) |entry| {
        const key = entry.key_ptr.*;
        if (!std.mem.startsWith(u8, key, src_pat)) continue;
        const suffix = key[src_pat.len..];
        const dest_key = try std.fmt.allocPrint(ctx.alloc, "{s}.{s}", .{ dest_prefix, suffix });
        defer ctx.alloc.free(dest_key);
        const src_slot = entry.value_ptr.*;
        if (ctx.locals.get(dest_key)) |dest_slot| {
            try ctx.emit(.{ .op = .store_local, .result = dest_slot, .lhs = .{ .local = src_slot }, .ty = .any });
        } else {
            const slot = ctx.freshTemp();
            try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, dest_key), slot);
            try ctx.emit(.{ .op = .store_local, .result = slot, .lhs = .{ .local = src_slot }, .ty = .any });
        }
    }
    if (ctx.locals.get(dest_prefix) == null) {
        const marker = try ctx.alloc.dupe(u8, dest_prefix);
        const sub_slot = ctx.freshTemp();
        try ctx.locals.put(ctx.alloc, marker, sub_slot);
        try ctx.emit(.{ .op = .init_record, .result = sub_slot, .record = "" });
    }
}

fn lowerRecordLiteralFields(ctx: *LowerCtx, prefix: []const u8, table: *const ast.Expr) Error!void {
    if (table.* != .table) return bail(ctx.diagnostic, @src());
    for (table.table.fields) |fld| {
        const nf = switch (fld) {
            .named => |n| n,
            else => return bail(ctx.diagnostic, @src()),
        };
        const fk = try std.fmt.allocPrint(ctx.alloc, "{s}.{s}", .{ prefix, nf.key });
        if (nf.val.* == .table) {
            // A nested record owns no storage of its own — only its leaves do.
            // The marker slot exists so `isRecordLocalName` and the field-key
            // lookups can still see that `o.i` is a bound record name.
            const sub_slot = ctx.freshTemp();
            try ctx.locals.put(ctx.alloc, fk, sub_slot);
            try lowerRecordLiteralFields(ctx, fk, nf.val);
            const sub_name = inferRecordNameFromTable(ctx.records, nf.val) orelse "";
            try ctx.emit(.{ .op = .init_record, .result = sub_slot, .record = sub_name });
            continue;
        } else if (nf.val.* == .name) {
            const reference = blk: {
                if (!ctx.require_graph_facts or ctx.graph.gateTransportModule()) break :blk true;
                const value = ctx.graph.valueByAst(nf.val) orelse
                    return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-initializer-value");
                switch (ctx.graph.valueOrigin(value)) {
                    .one => {},
                    .none, .unknown => return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-initializer-origin"),
                }
                const node = ctx.graph.get(value) orelse
                    return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-initializer-value");
                const descriptor = node.descriptor orelse
                    return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-initializer-descriptor");
                if (types.scalarFieldCell(descriptor) != null) break :blk false;
                if (descriptor == .table_type or descriptor == .@"struct") break :blk true;
                return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-initializer-carrier");
            };
            if (reference) {
                try copyPrefixedLocalsFromRecordRef(ctx, fk, nf.val.name.ident);
                continue;
            }
        }
        // THE LITERAL IS THE FIELD'S FIRST WRITE. When the field owns a
        // `__DATA` word, that write is what puts its initial content there —
        // this pass publishes no load-time image for a field key, so the store
        // emitted here is the whole of the initialization. Minting a local
        // beside the word instead would leave module scope reading a register
        // and every relation reading a zero.
        // The base is the OUTERMOST segment: `o.i.x` belongs to the binding
        // `o`, so a body that declares its own `o` owns the whole chain.
        const base = prefix[0 .. std.mem.indexOfScalar(u8, prefix, '.') orelse prefix.len];
        if (moduleFieldWord(ctx, base, fk)) |pair| {
            const gty = pair[0];
            const storage_key = pair[1];
            const gv = try lowerExpr(ctx, nf.val);
            try ctx.emit(.{
                .op = .store_global,
                .field = storage_key,
                .lhs = gv,
                .ty = gty,
            });
            ctx.alloc.free(fk);
            continue;
        }
        const v = try lowerExpr(ctx, nf.val);
        const fslot = ctx.freshTemp();
        try ctx.locals.put(ctx.alloc, fk, fslot);
        // A FIELD IS A PLACE AND ITS DESCRIPTOR APPLIES HERE — the literal
        // that creates the storage is a write like any later `r.f = …`, and
        // registering the width now is what makes every one of those later
        // writes find it: `lowerFieldAssignTarget` reads `narrow_slots` off
        // the slot exactly as `lowerAssign` does for a narrow local.
        const declared = fieldWidth(ctx, table, nf.key);
        if (declared) |width| try ctx.narrow_slots.put(ctx.alloc, fslot, width);
        const store_ty: RT = if (exprIsF64(ctx, nf.val)) .f64 else (declared orelse .any);
        if (store_ty == .f64) try ctx.f64_slots.put(ctx.alloc, fslot, {});
        if (exprIsStr(ctx, nf.val)) try ctx.str_slots.put(ctx.alloc, fslot, {});
        try ctx.emit(.{ .op = .store_local, .result = fslot, .lhs = v, .ty = store_ty });
    }
}

/// Match a table literal's named fields to a module record descriptor.
/// The declared narrow width of `field` in the record `table` is a literal of,
/// or null when the record is unknown, the field is absent, or the field is
/// full-width.
///
/// FAILS CLOSED, and the failure is the pre-existing behaviour rather than a
/// new refusal: an unrecognised literal answers null and the store stays
/// `.any`, which is exactly what every field store did before.
fn fieldWidth(ctx: *LowerCtx, table: *const ast.Expr, field: []const u8) ?RT {
    for (ctx.records) |rec| {
        if (!tableMatchesRecord(table, rec)) continue;
        if (rec.widths.len != rec.fields.len) return null;
        for (rec.fields, 0..) |name, i| {
            if (std.mem.eql(u8, name, field)) return rec.widths[i];
        }
        return null;
    }
    return null;
}

fn inferRecordNameFromTable(records: []const dnir.RecordDesc, table: *const ast.Expr) ?[]const u8 {
    if (table.* != .table) return null;
    for (records) |rec| {
        if (tableMatchesRecord(table, rec)) return rec.name;
    }
    return null;
}

fn tableMatchesRecord(table: *const ast.Expr, rec: dnir.RecordDesc) bool {
    if (table.* != .table) return false;
    if (table.table.fields.len != rec.fields.len) return false;
    for (rec.fields) |fname| {
        var found = false;
        for (table.table.fields) |fld| {
            const nf = switch (fld) {
                .named => |n| n,
                else => return false,
            };
            if (std.mem.eql(u8, nf.key, fname)) {
                found = true;
                break;
            }
        }
        if (!found) return false;
    }
    return true;
}

/// Lower inline table literal as a temp record value for call arguments.
fn lowerInlineRecordArg(ctx: *LowerCtx, table: *const ast.Expr, rec_name: []const u8) Error!dnir.Value {
    if (table.* != .table) return bail(ctx.diagnostic, @src());
    const rec_slot = ctx.freshTemp();
    const anon = try std.fmt.allocPrint(ctx.alloc, "__rec{d}", .{rec_slot});
    defer ctx.alloc.free(anon);
    for (table.table.fields) |fld| {
        const nf = switch (fld) {
            .named => |n| n,
            else => return bail(ctx.diagnostic, @src()),
        };
        const v = try lowerExpr(ctx, nf.val);
        const fslot = ctx.freshTemp();
        const fk = try std.fmt.allocPrint(ctx.alloc, "{s}.{s}", .{ anon, nf.key });
        try ctx.locals.put(ctx.alloc, fk, fslot);
        const store_ty: RT = if (exprIsF64(ctx, nf.val)) .f64 else .any;
        if (store_ty == .f64) try ctx.f64_slots.put(ctx.alloc, fslot, {});
        try ctx.emit(.{ .op = .store_local, .result = fslot, .lhs = v, .ty = store_ty });
    }
    try ctx.emit(.{ .op = .init_record, .result = rec_slot, .record = rec_name });
    return .{ .temp = rec_slot };
}

fn recordLocalDesc(ctx: *LowerCtx, name: []const u8) ?dnir.RecordDesc {
    if (ctx.locals.contains(name)) {
        if (ctx.param_record_types.get(name)) |rec_name| {
            for (ctx.records) |rec| {
                if (std.mem.eql(u8, rec.name, rec_name)) return rec;
            }
            if (findRecordByNominal(ctx.records, rec_name, ctx.graph)) |rec| return rec;
        }
    }
    for (ctx.records) |rec| {
        if (rec.fields.len == 0) continue;
        if (recordFieldsPresent(ctx, name, rec)) return rec;
    }
    return null;
}

fn materializeRecordBase(ctx: *LowerCtx, name: []const u8) Error!u32 {
    if (ctx.locals.get(name)) |s| {
        if (ctx.ptr_slots.contains(s)) return s;
    }
    const rec = recordLocalDesc(ctx, name) orelse return bail(ctx.diagnostic, @src());
    const count: i64 = @intCast(rec.fields.len);
    const base = ctx.freshTemp();
    try ctx.emit(.{ .op = .alloc_slots, .result = base, .lhs = .{ .i64 = count } });
    for (rec.fields, rec.kinds, 0..) |fname, kind, i| {
        const t = ctx.freshTemp();
        try ctx.emit(.{
            .op = .load_field,
            .result = t,
            .req_alias = name,
            .field = fname,
        });
        const ty: RT = switch (kind) {
            .str => .str,
            .f64 => .f64,
            .i64 => .any,
        };
        try ctx.emit(.{
            .op = .store_index,
            .ty = ty,
            .lhs = .{ .temp = base },
            .rhs = .{ .i64 = @intCast(i + 1) },
            .third = .{ .temp = t },
        });
    }
    try ctx.ptr_slots.put(ctx.alloc, base, {});
    try ctx.locals.put(ctx.alloc, try ctx.alloc.dupe(u8, name), base);
    return base;
}

fn lowerOpaqueRecordLocalArg(ctx: *LowerCtx, expr: *const ast.Expr) Error!?dnir.Value {
    if (expr.* != .name) return null;
    if (recordLocalDesc(ctx, expr.name.ident) == null) return null;
    return .{ .local = try materializeRecordBase(ctx, expr.name.ident) };
}

fn recordFieldsPresent(ctx: *LowerCtx, name: []const u8, rec: dnir.RecordDesc) bool {
    if (rec.fields.len == 0) return false;
    for (rec.fields) |fname| {
        const key = std.fmt.allocPrint(ctx.alloc, "{s}.{s}", .{ name, fname }) catch return false;
        defer ctx.alloc.free(key);
        if (ctx.locals.get(key) == null) return false;
    }
    return true;
}

fn emitF64RecordFieldsFromName(ctx: *LowerCtx, name: []const u8, slot: *u32) Error!bool {
    for (ctx.records) |rec| {
        var all_f64 = rec.fields.len > 0;
        for (rec.kinds) |k| {
            if (k != .f64) all_f64 = false;
        }
        if (!all_f64 or !recordFieldsPresent(ctx, name, rec)) continue;
        for (rec.fields) |fname| {
            const key = try std.fmt.allocPrint(ctx.alloc, "{s}.{s}", .{ name, fname });
            const field_slot = ctx.locals.get(key) orelse return bail(ctx.diagnostic, @src());
            ctx.alloc.free(key);
            try ctx.emit(.{ .op = .fp_mov_arg, .result = slot.*, .lhs = .{ .local = field_slot } });
            slot.* += 1;
            if (slot.* > 8) return bail(ctx.diagnostic, @src());
        }
        return true;
    }
    return false;
}

/// Does this name refer to a local of the function's RETURN record type?
/// Checked by the presence of its first exploded field slot, which is the same
/// evidence `lowerRecordReturn` then relies on — so the dispatch cannot admit
/// a shape the arm would refuse.
fn isRecordLocalName(ctx: *LowerCtx, e: *const ast.Expr) bool {
    if (e.* != .name) return false;
    const rec_name = ctx.ret_record orelse return false;
    const rec = findRecordName(ctx.records, .{ .named = rec_name }) orelse return false;
    if (rec.fields.len == 0) return false;
    if (Record.locate(ctx, e.name.ident) != null) {
        const actual = recordLocalDesc(ctx, e.name.ident) orelse return false;
        return std.mem.eql(u8, actual.name, rec.name);
    }
    var buf: [256]u8 = undefined;
    const key = std.fmt.bufPrint(&buf, "{s}.{s}", .{ e.name.ident, rec.fields[0] }) catch return false;
    return ctx.locals.get(key) != null;
}

fn lowerRecordReturn(ctx: *LowerCtx, table: *const ast.Expr) Error!void {
    const rec_name = ctx.ret_record orelse return bail(ctx.diagnostic, @src());
    const rec = findRecordName(ctx.records, .{ .named = rec_name }) orelse return bail(ctx.diagnostic, @src());
    const count: u32 = @intCast(rec.fields.len);
    if (count == 0 or count > max_record_fields) return bail(ctx.diagnostic, @src());

    // `return r` where `r` is a record-typed LOCAL rather than a literal.
    //
    // A record local is stored EXPLODED — one local per field, keyed
    // "name.field" — and those slots already hold the values (reading `r.a`
    // works). They only need gathering in DESCRIPTOR order, the same order the
    // literal path below is careful to use.
    if (table.* == .name) {
        const base = table.name.ident;
        const nvals = try ctx.alloc.alloc(dnir.Value, count);
        errdefer ctx.alloc.free(nvals);
        if (Record.locate(ctx, base)) |record_base| {
            if (ctx.directory.contains(record_base)) return invalidGraphFacts(ctx.diagnostic, @src(), "record-result-residency-unproved");
            for (rec.fields, 0..) |fname, i| {
                const projected = Record.project(rec, fname) orelse
                    return invalidGraphFacts(ctx.diagnostic, @src(), "record-field-projection");
                const slot = ctx.freshTemp();
                try ctx.emit(.{
                    .op = .load_index,
                    .ty = projected.ty,
                    .result = slot,
                    .lhs = .{ .local = record_base },
                    .rhs = .{ .i64 = projected.index },
                });
                nvals[i] = .{ .temp = slot };
            }
        } else for (rec.fields, 0..) |fname, i| {
            const key = try std.fmt.allocPrint(ctx.alloc, "{s}.{s}", .{ base, fname });
            defer ctx.alloc.free(key);
            const slot = ctx.locals.get(key) orelse return bailNamed(ctx.diagnostic, @src(), "local-slot-missing", fname);
            nvals[i] = .{ .local = slot };
        }
        try ctx.emit(.{
            .op = .ret_record,
            .record = rec_name,
            .lhs = nvals[0],
            .rhs = if (count > 1) nvals[1] else .void,
            .third = if (count > 2) nvals[2] else .void,
            .vals = nvals,
            .result = count,
        });
        return;
    }
    if (table.* != .table) return bail(ctx.diagnostic, @src());

    // Order by the DESCRIPTOR, not by the literal.
    //
    // The consumer reads field i out of ABI slot i (or buffer offset i*8), and
    // the descriptor is the only thing that agrees with it. Walking the
    // literal's own order instead meant `return { c = 3, a = 1, b = 2 }` for
    // `@{ a, b, c }` shipped 3 in the slot the caller reads as `a`. Every
    // literal that happened to be written in declaration order hid it.
    const vals = try ctx.alloc.alloc(dnir.Value, count);
    errdefer ctx.alloc.free(vals);
    var seen = try ctx.alloc.alloc(bool, count);
    defer ctx.alloc.free(seen);
    @memset(seen, false);
    for (table.table.fields) |fld| {
        const nf = switch (fld) {
            .named => |n| n,
            else => return bail(ctx.diagnostic, @src()),
        };
        if (fieldIndexIn(rec, nf.key)) |idx| {
            if (seen[idx]) return bailNamed(ctx.diagnostic, @src(), "record-field-duplicate", nf.key);
            vals[idx] = try lowerExpr(ctx, nf.val);
            seen[idx] = true;
        } else if (nf.val.* == .table) {
            try lowerNestedRecordTableFields(ctx, rec, nf.key, nf.val, vals, seen);
        } else if (nf.val.* == .name) {
            try lowerNestedRecordFromLocal(ctx, rec, nf.key, nf.val.name.ident, vals, seen);
        } else if (nf.val.* == .field) {
            try lowerNestedRecordFromFieldRef(ctx, rec, nf.key, nf.val, vals, seen);
        } else {
            return bailNamed(ctx.diagnostic, @src(), "record-field-value-not-lowered", nf.key);
        }
    }
    // A partially-written buffer is the exact failure this convention has to
    // rule out: the caller reads all `count` slots either way, so an omitted
    // field is caller-visible garbage rather than a missing value.
    for (seen, 0..) |s, i| {
        if (!s) return bailWith(ctx.diagnostic, @src(), rec.fields[i]);
    }

    try ctx.emit(.{
        .op = .ret_record,
        .record = rec_name,
        .lhs = vals[0],
        .rhs = if (count > 1) vals[1] else .void,
        .third = if (count > 2) vals[2] else .void,
        .vals = vals,
        .result = count,
    });
}

fn lowerNestedRecordFromLocal(
    ctx: *LowerCtx,
    rec: dnir.RecordDesc,
    prefix: []const u8,
    base: []const u8,
    vals: []dnir.Value,
    seen: []bool,
) Error!void {
    var prefix_buf: [256]u8 = undefined;
    const prefix_pat = std.fmt.bufPrint(&prefix_buf, "{s}.", .{prefix}) catch return bail(ctx.diagnostic, @src());
    for (rec.fields, 0..) |fname, idx| {
        if (!std.mem.startsWith(u8, fname, prefix_pat)) continue;
        const suffix = fname[prefix_pat.len..];
        const local_key = try std.fmt.allocPrint(ctx.alloc, "{s}.{s}", .{ base, suffix });
        defer ctx.alloc.free(local_key);
        const slot = ctx.locals.get(local_key) orelse return bailNamed(ctx.diagnostic, @src(), "local-slot-missing", local_key);
        if (seen[idx]) return bailNamed(ctx.diagnostic, @src(), "record-field-duplicate", fname);
        vals[idx] = .{ .local = slot };
        seen[idx] = true;
    }
}

fn lowerNestedRecordTableFields(
    ctx: *LowerCtx,
    rec: dnir.RecordDesc,
    prefix: []const u8,
    table_expr: *const ast.Expr,
    vals: []dnir.Value,
    seen: []bool,
) Error!void {
    if (table_expr.* != .table) return bail(ctx.diagnostic, @src());
    for (table_expr.table.fields) |sub| {
        const sn = switch (sub) {
            .named => |n| n,
            else => return bail(ctx.diagnostic, @src()),
        };
        var buf: [512]u8 = undefined;
        const flat_name = std.fmt.bufPrint(&buf, "{s}.{s}", .{ prefix, sn.key }) catch return bail(ctx.diagnostic, @src());
        if (fieldIndexIn(rec, flat_name)) |idx| {
            if (seen[idx]) return bailWith(ctx.diagnostic, @src(), flat_name);
            vals[idx] = try lowerExpr(ctx, sn.val);
            seen[idx] = true;
        } else if (sn.val.* == .table) {
            try lowerNestedRecordTableFields(ctx, rec, flat_name, sn.val, vals, seen);
        } else if (sn.val.* == .name) {
            try lowerNestedRecordFromLocal(ctx, rec, flat_name, sn.val.name.ident, vals, seen);
        } else if (sn.val.* == .field) {
            try lowerNestedRecordFromFieldRef(ctx, rec, flat_name, sn.val, vals, seen);
        } else {
            return bailWith(ctx.diagnostic, @src(), flat_name);
        }
    }
}

fn fieldIndexIn(rec: dnir.RecordDesc, name: []const u8) ?usize {
    for (rec.fields, 0..) |f, i| {
        if (std.mem.eql(u8, f, name)) return i;
    }
    return null;
}

fn recordFieldRootName(expr: *const ast.Expr) ?[]const u8 {
    return switch (expr.*) {
        .name => |n| n.ident,
        .field => |f| recordFieldRootName(f.obj),
        else => null,
    };
}

fn loadFieldFromOpaquePath(ctx: *LowerCtx, path: []const u8) Error!?dnir.Value {
    const dot = std.mem.indexOfScalar(u8, path, '.') orelse return null;
    const obj_name = path[0..dot];
    if (ctx.locals.get(obj_name) == null and ctx.param_record_types.get(obj_name) == null) return null;
    const field = path[dot + 1 ..];
    const t = ctx.freshTemp();
    try ctx.emit(.{
        .op = .load_field,
        .result = t,
        .req_alias = try ctx.alloc.dupe(u8, obj_name),
        .field = try ctx.alloc.dupe(u8, field),
    });
    return .{ .temp = t };
}

fn lowerNestedRecordFromFieldRef(
    ctx: *LowerCtx,
    rec: dnir.RecordDesc,
    prefix: []const u8,
    base_expr: *const ast.Expr,
    vals: []dnir.Value,
    seen: []bool,
) Error!void {
    const obj_name = recordFieldRootName(base_expr) orelse return bail(ctx.diagnostic, @src());
    var base_path: std.ArrayList(u8) = .empty;
    defer base_path.deinit(ctx.alloc);
    if (!try flattenNames(ctx.alloc, base_expr, &base_path)) return bail(ctx.diagnostic, @src());
    var prefix_buf: [512]u8 = undefined;
    const prefix_pat = std.fmt.bufPrint(&prefix_buf, "{s}.", .{prefix}) catch return bail(ctx.diagnostic, @src());
    for (rec.fields, 0..) |fname, idx| {
        if (!std.mem.startsWith(u8, fname, prefix_pat)) continue;
        if (seen[idx]) return bailNamed(ctx.diagnostic, @src(), "record-field-duplicate", fname);
        const suffix = fname[prefix_pat.len..];
        const local_key = try std.fmt.allocPrint(ctx.alloc, "{s}.{s}", .{ base_path.items, suffix });
        defer ctx.alloc.free(local_key);
        if (ctx.locals.get(local_key)) |slot| {
            vals[idx] = .{ .local = slot };
        } else {
            const t = ctx.freshTemp();
            try ctx.emit(.{ .op = .load_field, .result = t, .req_alias = obj_name, .field = fname });
            vals[idx] = .{ .temp = t };
        }
        seen[idx] = true;
    }
}

fn callFieldSuffixFromExpr(
    ctx: *LowerCtx,
    expr: *const ast.Expr,
) Error!?struct { call: *const ast.Expr, suffix: []const u8 } {
    var parts: std.ArrayList([]const u8) = .empty;
    defer parts.deinit(ctx.alloc);
    var cur: *const ast.Expr = expr;
    while (cur.* == .field) {
        try parts.append(ctx.alloc, cur.field.field);
        cur = cur.field.obj;
    }
    if (cur.* != .call and cur.* != .method_call or parts.items.len == 0) return null;
    var suffix: std.ArrayList(u8) = .empty;
    defer suffix.deinit(ctx.alloc);
    var i: usize = parts.items.len;
    while (i > 0) {
        i -= 1;
        if (suffix.items.len > 0) try suffix.append(ctx.alloc, '.');
        try suffix.appendSlice(ctx.alloc, parts.items[i]);
    }
    return .{ .call = cur, .suffix = try ctx.alloc.dupe(u8, suffix.items) };
}

fn lowerCallRecordFieldProjection(
    ctx: *LowerCtx,
    call_expr: *const ast.Expr,
    field_name: []const u8,
) Error!?dnir.Value {
    if (!ctx.require_graph_facts) return null;
    const application = ctx.occurrences.get(call_expr) orelse return null;
    const record = try checkedRecordForApplication(ctx, application) orelse return null;
    const tmp_slot = ctx.freshTemp();
    const tmp = try std.fmt.allocPrint(ctx.alloc, "__rf{d}", .{tmp_slot});
    // Keep `tmp` alive until `internInstrStrings` copies `.field` / `.req_alias`.
    try lowerCheckedRecordCallAssign(ctx, tmp, application, record, call_expr);
    const fk = try std.fmt.allocPrint(ctx.alloc, "{s}.{s}", .{ tmp, field_name });
    if (ctx.locals.get(fk)) |slot| return .{ .local = slot };
    if (try loadFieldFromOpaquePath(ctx, fk)) |v| return v;
    return null;
}

fn lowerExpr(ctx: *LowerCtx, expr: *const ast.Expr) Error!dnir.Value {
    return lowerExprCons(ctx, expr, .single);
}

/// The module-scope place a name denotes HERE, when the graph ruled that it
/// has no runtime location at all.
///
/// BINDING ORDER IS THE WHOLE SAFETY ARGUMENT, and it is the same order the
/// `.name` arm below already states: a local, a parameter or a WRITTEN module
/// global is a NAME THAT IS TAKEN, and only a name nothing else has taken can
/// still mean a place. Every existing resolution path therefore wins over this
/// one, so no program that lowers today reaches it.
fn absentModulePlace(ctx: *LowerCtx, name: []const u8) ?*const place.Place {
    if (ctx.graph.placeCount() == 0) return null;
    if (ctx.locals.contains(name)) return null;
    if (ctx.module_globals.has(name)) return null;
    const p = ctx.graph.placeNamed(name) orelse return null;
    if (place.residencyRefusal(p) != .none) return null;
    return p;
}

/// `t[k]` on a module-scope collection whose place residency is `.absent` —
/// the element, as an immediate, with no storage anywhere.
///
/// `t(k)` DOES NOT REACH HERE AND MUST NOT. `law.md` §5 gives indexing to `[]`
/// and says of `()`: "it is ordinary application. It never means table
/// indexing." `placeFold` no longer offers a `.call` arm; see the ruling
/// there.
fn placeElement(ctx: *LowerCtx, name: []const u8, key: *const Expr) ?dnir.Value {
    const p = absentModulePlace(ctx, name) orelse return null;
    if (p.shape != .collection) return null;
    if (p.facts.contents_known != .yes) return null;
    const init = p.init orelse return null;
    if (init.* != .table) return null;
    const fields = init.table.fields;
    // CONSTANT INDEX — the per-access half, separate from the place-wide
    // determinacy `residencyRefusal` already checked. A key that is not a
    // literal is a genuinely COMPUTED projection and keeps its runtime
    // access; only a determined one may be answered as an immediate.
    const k = ast.intLiteralValue(key) orelse return null;
    // TABLES ARE 1-INDEXED. `t(0)` is out of range as surely as `t(len + 1)`,
    // and folding either to `fields[k - 1]` is the wrong-answer class this
    // whole ruling exists to avoid.
    if (k < 1 or k > @as(i64, @intCast(fields.len))) return null;
    const f = fields[@intCast(k - 1)];
    if (f != .positional) return null;
    const v = ast.intLiteralValue(f.positional) orelse return null;
    return dnir.Value{ .i64 = v };
}

/// PLACE RESIDENCY, CONSUMED — the fact `place.zig` produces reaching emitted
/// machine code, for the ONE face `law.md` §5 gives to projection.
///
/// A module-scope binding that nothing writes, aliases, escapes or indexes at a
/// runtime offset has NO RUNTIME LOCATION: every read of it IS its initializer.
/// Measured on this tree before this existed, `global k = 7` and
/// `global t = (10, 20, 30)` were both outside the direct backend subset —
/// `DNB001 … missing: k` and `DNB001 … missing: graph-dnir-unsupported` — so
/// the fold is not a cheaper path to an answer the compiler already had.
///
/// WHY IT IS NOT A FOURTH NAME-KEYED TABLE. `place.residencyRefusal` names ten
/// distinct reasons, is three-valued so `unknown` never reads as `no`, and is
/// read from the SAME array `observation.zig` and `eqspace.zig` read. Deleting
/// any one of its clauses re-admits a candidate the others forbid.
///
/// It is a PLACE consumer and nothing else. It answers a projection through a
/// location; it does not answer a bare name's VALUE — `law.md` §6 separates
/// those (`value != place`) and the arm that crossed the line is gone.
fn placeFold(ctx: *LowerCtx, expr: *const Expr) ?dnir.Value {
    switch (expr.*) {
        // `[]` IS THE ONLY FACE THAT REACHES HERE.
        //
        // Two arms were deleted, and each was a rival authority, not a
        // duplicate:
        //
        //   `.name` READ A VALUE OFF A PLACE ROW. It answered a bare module
        //   scalar by reaching into `p.init` — the initializer AST hanging off
        //   the place census — and returning it as an immediate. `law.md` §6
        //   is explicit twice over: "value != place", "binding != place", and
        //   "Scalars … are not places merely because a compiler implementation
        //   stores them." An unwritten, unaliased, non-escaping module scalar
        //   therefore has NO place, and the row `place.zig`'s over-approximating
        //   AST census mints for it is not a licence to answer its value. The
        //   value producer owns that answer; this consumer asking the place
        //   census for it was a second authority over one fact.
        //
        //   `.call` FOLDED `t(k)` AS AN INDEX. `law.md` §5: "`()` is ordinary
        //   application. It never means table indexing." `place.zig` already
        //   rules this way in its own walk — its `.call` arm reads the callee
        //   and the operands and comments "it is never an index", and
        //   `test "place: an ordinary call is not an indexed read"` pins
        //   `readCount() == 0` and `escape == unknown` for `s(2)`. This arm
        //   disagreed with that ruling from the consumer side, so the two
        //   producers answered one question two ways.
        //
        //   THE ARM WAS NOT SAFE BECAUSE IT WAS UNREACHABLE. It was shadowed:
        //   naming a collection as a callee drives `place.zig` to publish
        //   `escape:"unknown"`, `residencyRefusal` then refuses, and
        //   `absentModulePlace` returns null — so the wrong answer was withheld
        //   by a DIFFERENT producer's conservatism rather than by this fold's
        //   own guard, which admitted it. A guard that permits a wrong answer
        //   and relies on someone upstream to never ask is fail-open with a
        //   witness. `gate/callfold.sh` is the control.
        //
        // The whole justification the deleted arms carried cited "§18
        // residency" and "§19 constant index" — sections of a retired edition
        // of the source law. Current `law.md` ends at §17, and its §6 place
        // clause is the ruling above.
        .index => |ix| {
            if (ix.obj.* != .name) return null;
            return placeElement(ctx, ix.obj.name.ident, ix.key);
        },
        else => return null,
    }
}

const AggregateAccessStep = struct {
    application: *const semantic_graph.ApplicationFact,
    subject: semantic_graph.id,
    key: semantic_graph.id,
    result: semantic_graph.id,
    extent: i64,
    result_descriptor: RT,
};

fn collectAggregateAccessPath(
    ctx: *LowerCtx,
    application: *const semantic_graph.ApplicationFact,
    steps: *std.ArrayListUnmanaged(AggregateAccessStep),
    seen: *std.AutoHashMapUnmanaged(semantic_graph.id, void),
) Error!void {
    const fact = ctx.graph.aggregateAccess(application.application) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-access-fact");
    const entry = try seen.getOrPut(ctx.alloc, fact.application);
    if (entry.found_existing) return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-access-cycle");

    const subject = ctx.graph.applicationSubject(fact.application) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-access-subject");
    if (ctx.graph.aggregateProducer(subject)) |producer| {
        const parent = ctx.graph.aggregateAccess(producer) orelse
            return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-access-producer");
        try collectAggregateAccessPath(ctx, parent, steps, seen);
    }
    const operands = ctx.graph.applicationArguments(fact.application) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-operand-pack");
    const results = ctx.graph.applicationResults(fact.application) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-result-pack");
    if (operands.len != 1 or results.len != 1)
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-access-pack-arity");
    const subject_node = ctx.graph.get(subject) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-access-subject");
    const descriptor = subject_node.descriptor orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-access-descriptor");
    if (descriptor != .array or descriptor.array.size == null)
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-access-descriptor");
    const result_node = ctx.graph.get(results[0]) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-result-member");
    const result_descriptor = result_node.descriptor orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-result-descriptor");
    if (!result_descriptor.eql(descriptor.array.elem.*))
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-result-descriptor");
    try steps.append(ctx.alloc, .{
        .application = fact,
        .subject = subject,
        .key = operands[0],
        .result = results[0],
        .extent = @intCast(descriptor.array.size.?),
        .result_descriptor = result_descriptor,
    });
}

fn aggregateLeafCount(descriptor: RT) ?i64 {
    var current = descriptor;
    var count: u64 = 1;
    while (current == .array) {
        const extent = current.array.size orelse return null;
        count = std.math.mul(u64, count, extent) catch return null;
        current = current.array.elem.*;
    }
    if (current != .i64 or count == 0 or count > std.math.maxInt(i64)) return null;
    return @intCast(count);
}

fn aggregateBase(ctx: *LowerCtx, root_aggregate: semantic_graph.id) Error!u32 {
    if (ctx.aggregate_bases.get(root_aggregate)) |base| return base;
    if (!immutableAggregate(ctx.graph, root_aggregate))
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-static-place");
    const node = ctx.graph.get(root_aggregate) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-root");
    const descriptor = node.descriptor orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-root-descriptor");
    const words = aggregateLeafCount(descriptor) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-root-descriptor");
    const base = ctx.freshTemp();
    try ctx.emit(.{
        .op = .alloc_slots,
        .result = base,
        .lhs = .{ .i64 = words },
        .aggregate = root_aggregate,
        .ty = .i64,
    });
    try ctx.aggregate_bases.put(ctx.alloc, root_aggregate, base);
    return base;
}

fn setAggregateLineage(
    ctx: *LowerCtx,
    step: AggregateAccessStep,
    start: u32,
    instruction: *dnir.Instr,
) Error!void {
    instruction.relation = ctx.graph.applicationRelation(step.application.application) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-access-relation");
    instruction.application = step.application.application;
    instruction.value = step.result;
    instruction.subject = step.subject;
    instruction.target = ctx.graph.applicationTarget(step.application.application) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-access-target");
    instruction.realization_start = start;
    instruction.ty = step.result_descriptor;
}

fn aggregateKey(ctx: *LowerCtx, step: AggregateAccessStep) Error!dnir.Value {
    if (ctx.graph.exactI64(step.key)) |constant| {
        if (constant < 1 or constant > step.extent) return bailWith(ctx.diagnostic, @src(), "aggregate-index-bounds");
        return .{ .i64 = constant };
    }
    const expression = ctx.graph.valueExpression(step.key) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-key-provenance");
    const raw = try lowerExpr(ctx, expression);
    const slot = ctx.freshTemp();
    try ctx.emit(.{ .op = .store_local, .result = slot, .lhs = raw, .ty = .i64 });
    try emitIndexBoundsTrap(ctx, slot, step.extent);
    return .{ .local = slot };
}

/// THE PROJECTION'S RESULT IDENTITY ALREADY CARRIES THE ANSWER.
///
/// `liftAggregateAccess` publishes the selected member's exact content onto the
/// projection's OWN RESULT VALUE when the subject aggregate's contents and the
/// key are both already known. That is the whole chain the graph exists to
/// carry — value known, projection published, result identity published — and
/// until this consumer existed the realization ignored it and re-derived the
/// same answer at run time with `alloc_slots`, index arithmetic and a
/// `load_index` against a static table.
///
/// THE LICENCE IS NOT NEW. It is `immutableNestedAggregateRoot`, the exact
/// predicate that already licenses the dense-table realization this replaces:
/// one binding, no write, no alias, no escape, contents known. Nothing weaker
/// is assumed, and no second store decides — every input here is read from the
/// graph.
///
/// EVERY STEP STILL EMITS EXACTLY ONE INSTRUCTION carrying its own application
/// lineage, so `validateDnirApplications` counts the same realizations it
/// counted before. The instructions merely stop touching memory. Returning
/// `null` leaves the loading realization in place unchanged.
fn foldAggregateAccess(
    ctx: *LowerCtx,
    steps: []const AggregateAccessStep,
    root_aggregate: semantic_graph.id,
    consumption: types.ReturnConsumption,
) Error!?dnir.Value {
    const leaf = steps[steps.len - 1];
    if (leaf.result_descriptor != .i64) return null;
    const content = ctx.graph.exactI64(leaf.result) orelse return null;
    // `immutableAggregate` IS the nested predicate minus the "elements are
    // themselves aggregates" clause, which is a shape question and not a
    // safety one. A flat root that is bound once, never written, never
    // aliased and never escaped is exactly as safe to answer from as a
    // nested one; only the LOADING realization needs the nesting, because
    // only it needs a dense table.
    if (!immutableAggregate(ctx.graph, root_aggregate)) return null;
    // A step whose key the graph does not know exactly cannot have produced an
    // exact result, so this loop is a CONSISTENCY CHECK on the producer, not a
    // second derivation of the answer. Disagreement refuses.
    for (steps) |step| {
        const key = ctx.graph.exactI64(step.key) orelse return null;
        if (key < 1 or key > step.extent)
            return bailWith(ctx.diagnostic, @src(), "aggregate-index-bounds");
    }
    // NOTHING IS EMITTED. Each step's application is recorded as realized
    // NOWHERE, which is what actually happened: the answer was already a fact.
    // An earlier draft emitted one dead `store_local` per step purely so the
    // realization count would balance, and measured `xs[1] > 2` at four
    // instructions against the rival AST walk's two — the accounting invariant
    // paying for itself in machine text. Absence is stated instead.
    for (steps) |step| {
        try ctx.absent_applications.append(ctx.alloc, step.application.application);
    }
    return if (consumption == .discard) .void else dnir.Value{ .i64 = content };
}

fn lowerAggregateAccess(
    ctx: *LowerCtx,
    application: *const semantic_graph.ApplicationFact,
    consumption: types.ReturnConsumption,
) Error!dnir.Value {
    var steps: std.ArrayListUnmanaged(AggregateAccessStep) = .empty;
    defer steps.deinit(ctx.alloc);
    var seen: std.AutoHashMapUnmanaged(semantic_graph.id, void) = .empty;
    defer seen.deinit(ctx.alloc);
    try collectAggregateAccessPath(ctx, application, &steps, &seen);
    if (steps.items.len == 0)
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-access-depth");
    const root_aggregate = steps.items[0].subject;
    if (ctx.graph.aggregateProducer(root_aggregate) != null)
        return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-access-root");
    // A one-step flat projection keeps one explicit constant instruction so
    // its application, result value, and machine realization remain directly
    // queryable. Nested chains may still disappear as a proved transformation;
    // their ordered absent-application witnesses are validated once for every
    // backend by `realization_validate.aggregateSchedule`.
    if (steps.items.len > 1) {
        if (try foldAggregateAccess(ctx, steps.items, root_aggregate, consumption)) |folded| return folded;
    }

    var prefix: dnir.Value = .void;
    for (steps.items, 0..) |step, i| {
        const start: u32 = @intCast(ctx.instrs.items.len);
        const key = try aggregateKey(ctx, step);
        const last = i + 1 == steps.items.len;
        if (last) {
            if (step.result_descriptor != .i64)
                return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-leaf-descriptor");
            // Exact member content is already the graph result. No dense
            // object or indexed load is observable for this application. The
            // graph-linked constant is the realization row: it preserves the
            // application -> result -> machine lineage even though selection
            // deleted the aggregate object and indexed load.
            if (steps.items.len == 1) {
                if (ctx.graph.exactI64(step.result)) |content| {
                    const result = ctx.freshTemp();
                    var instruction: dnir.Instr = .{
                        .op = .@"const",
                        .result = result,
                        .lhs = .{ .i64 = content },
                        .ty = .i64,
                    };
                    try setAggregateLineage(ctx, step, start, &instruction);
                    try ctx.emit(instruction);
                    return if (consumption == .discard) .void else .{ .temp = result };
                }
            }

            const base = try aggregateBase(ctx, root_aggregate);
            var offset = key;
            if (i != 0) {
                const biased = ctx.freshTemp();
                try ctx.emit(.{ .op = .binop, .result = biased, .binop = .sub, .lhs = prefix, .rhs = .{ .i64 = 1 } });
                const scaled = ctx.freshTemp();
                try ctx.emit(.{ .op = .binop, .result = scaled, .binop = .mul, .lhs = .{ .temp = biased }, .rhs = .{ .i64 = step.extent } });
                const combined = ctx.freshTemp();
                try ctx.emit(.{ .op = .binop, .result = combined, .binop = .add, .lhs = .{ .temp = scaled }, .rhs = key });
                offset = .{ .temp = combined };
            }
            const result = ctx.freshTemp();
            var instruction: dnir.Instr = .{
                .op = .load_index,
                .result = result,
                .lhs = .{ .temp = base },
                .rhs = offset,
                .ty = .i64,
            };
            try setAggregateLineage(ctx, step, start, &instruction);
            try ctx.emit(instruction);
            return if (consumption == .discard) .void else .{ .temp = result };
        }
        if (i == 0) {
            const slot = ctx.freshTemp();
            var instruction: dnir.Instr = .{
                .op = .store_local,
                .result = slot,
                .lhs = key,
            };
            try setAggregateLineage(ctx, step, start, &instruction);
            try ctx.emit(instruction);
            prefix = .{ .local = slot };
            continue;
        }

        const biased = ctx.freshTemp();
        try ctx.emit(.{ .op = .binop, .result = biased, .binop = .sub, .lhs = prefix, .rhs = .{ .i64 = 1 } });
        const scaled = ctx.freshTemp();
        try ctx.emit(.{ .op = .binop, .result = scaled, .binop = .mul, .lhs = .{ .temp = biased }, .rhs = .{ .i64 = step.extent } });
        const offset = ctx.freshTemp();
        try ctx.emit(.{ .op = .binop, .result = offset, .binop = .add, .lhs = .{ .temp = scaled }, .rhs = key });

        const slot = ctx.freshTemp();
        var instruction: dnir.Instr = .{
            .op = .store_local,
            .result = slot,
            .lhs = .{ .temp = offset },
        };
        try setAggregateLineage(ctx, step, start, &instruction);
        try ctx.emit(instruction);
        prefix = .{ .local = slot };
    }
    return invalidGraphFacts(ctx.diagnostic, @src(), "aggregate-access-result");
}


/// Collect the semantic-graph application IDs for every call expression
/// within `expr` (including `expr` itself if it is a call).
///
/// When summary propagation folds an expression to a constant, the calls
/// inside it are realized NOWHERE. Each must be recorded in
/// `ctx.summary_folded` — the lowering's own statement of summary-folded
/// absence that realization validation consumes. Without this, the
/// realization-count check fails because the graph still has the
/// application but the DNIR has no instruction for it.
fn collectFoldedCallApplications(
    ctx: *LowerCtx,
    expr: *const ast.Expr,
    out: *std.ArrayListUnmanaged(semantic_graph.id),
) void {
    // If this expression is itself a call, record its application.
    switch (expr.*) {
        .call, .method_call => {
            if (ctx.occurrences.id(expr)) |app_id| {
                out.append(ctx.alloc, app_id) catch {};
            }
        },
        else => {},
    }
    // Recurse into sub-expressions that may contain calls.
    // Modeled on `exprHasCall` — same coverage.
    switch (expr.*) {
        .call => |c| {
            collectFoldedCallApplications(ctx, c.func, out);
            for (c.args) |arg| collectFoldedCallApplications(ctx, arg, out);
        },
        .method_call => |m| {
            collectFoldedCallApplications(ctx, m.obj, out);
            for (m.args) |arg| collectFoldedCallApplications(ctx, arg, out);
        },
        .index => |x| {
            collectFoldedCallApplications(ctx, x.obj, out);
            collectFoldedCallApplications(ctx, x.key, out);
        },
        .field => |x| collectFoldedCallApplications(ctx, x.obj, out),
        .binop => |b| {
            collectFoldedCallApplications(ctx, b.lhs, out);
            collectFoldedCallApplications(ctx, b.rhs, out);
        },
        .unop => |u| collectFoldedCallApplications(ctx, u.operand, out),
        .if_expr => |ie| {
            collectFoldedCallApplications(ctx, ie.cond, out);
            collectFoldedCallApplications(ctx, ie.then_expr, out);
            collectFoldedCallApplications(ctx, ie.else_expr, out);
        },
        .try_expr => |x| collectFoldedCallApplications(ctx, x.operand, out),
        .unwrap_expr => |x| collectFoldedCallApplications(ctx, x.operand, out),
        .await_expr => |x| collectFoldedCallApplications(ctx, x.operand, out),
        .contains_expr => |x| {
            collectFoldedCallApplications(ctx, x.lhs, out);
            collectFoldedCallApplications(ctx, x.rhs, out);
        },
        .sequence => |s| {
            for (s.exprs) |e| collectFoldedCallApplications(ctx, e, out);
        },
        .range => |r| {
            collectFoldedCallApplications(ctx, r.start, out);
            collectFoldedCallApplications(ctx, r.end, out);
            if (r.step) |st| collectFoldedCallApplications(ctx, st, out);
        },
        .quote => |q| collectFoldedCallApplications(ctx, q.expr, out),
        .unquote => |u| collectFoldedCallApplications(ctx, u.expr, out),
        else => {},
    }
}

/// Record a summary-folded application exactly once. summaryConstInt
/// folds eagerly while probing a condition constConditionTruth may not
/// decide; when it bails, normal lowering re-folds the same call and records
/// it again. The validator requires exactly-once, so the second recording is
/// a no-op. Dedupe is per function list, so a genuine cross-function
/// double-record still fails validation.
fn recordSummaryFolded(ctx: *LowerCtx, app_id: semantic_graph.id) void {
    for (ctx.summary_folded.items) |existing| {
        if (existing == app_id) return;
    }
    ctx.summary_folded.append(ctx.alloc, app_id) catch {};
}

/// Try to fold a binop where operands contain summary-foldable calls.
/// Folds each operand via the summary (if it's a call) or via foldValueExpr,
/// then computes the binop on the constants. Returns null if any operand
/// can't be folded or the operator isn't supported.
fn tryFoldBinopWithSummary(
    cache: *summary.Cache,
    ctx: *LowerCtx,
    caller: semantic_graph.id,
    expr: *const Expr,
) ?i64 {
    if (expr.* != .binop) return null;
    const b = expr.binop;
    
    // Fold lhs: try summary first for calls, fall back to authoritative folder.
    const lhs_val: ?i64 = blk: {
        if (b.lhs.* == .call) {
            if (summary.foldCallSite(cache, ctx.graph, caller, b.lhs)) |k| {
                break :blk k;
            }
        }
        if (b.lhs.* == .int_lit) {
            break :blk b.lhs.int_lit.val;
        }
        break :blk comptime_eval.foldValueExpr(ctx.alloc, ctx.graph, caller, b.lhs);
    };
    const lhs = lhs_val orelse return null;
    
    // Fold rhs: try summary first for calls, fall back to authoritative folder.
    const rhs_val: ?i64 = blk: {
        if (b.rhs.* == .call) {
            if (summary.foldCallSite(cache, ctx.graph, caller, b.rhs)) |k| {
                break :blk k;
            }
        }
        if (b.rhs.* == .int_lit) {
            break :blk b.rhs.int_lit.val;
        }
        break :blk comptime_eval.foldValueExpr(ctx.alloc, ctx.graph, caller, b.rhs);
    };
    const rhs = rhs_val orelse return null;
    
    // Compute the binop
    return switch (b.op) {
        .add => lhs +% rhs,
        .sub => lhs -% rhs,
        .mul => lhs *% rhs,
        // Division is FLOORED, the settled law; minInt / -1 and division
        // by zero refuse exactly like comptime.zig and foldConstBinop.
        .div => if (rhs == 0 or (rhs == -1 and lhs == std.math.minInt(i64)))
            null
        else
            @divFloor(lhs, rhs),
        .mod => if (rhs == 0 or (rhs == -1 and lhs == std.math.minInt(i64)))
            null
        else
            @mod(lhs, rhs),
        .eq => if (lhs == rhs) @as(i64, 1) else @as(i64, 0),
        .neq => if (lhs != rhs) @as(i64, 1) else @as(i64, 0),
        .lt => if (lhs < rhs) @as(i64, 1) else @as(i64, 0),
        .leq => if (lhs <= rhs) @as(i64, 1) else @as(i64, 0),
        .gt => if (lhs > rhs) @as(i64, 1) else @as(i64, 0),
        .geq => if (lhs >= rhs) @as(i64, 1) else @as(i64, 0),
        else => null,
    };
}

fn lowerExprCons(
    ctx: *LowerCtx,
    expr: *const Expr,
    consumption: types.ReturnConsumption,
) Error!dnir.Value {
    // THE GRAPH FIRST WHEN THE GRAPH PUBLISHED SOMETHING. `placeFold` answers
    // a module-scope collection read by RE-READING the initializer AST
    // (`placeElement` → `intLiteralStep`), and it used to run first. Once the
    // projection publishes an application, letting the AST walk answer would
    // leave that application realized NOWHERE and `native_backend` would refuse
    // the module for a dropped realization — the rival authority converting a
    // published fact into a refusal. Where the graph published nothing,
    // `placeFold` still answers exactly as before.
    // A PLACE ACCESS IS NOT AN APPLICATION. `t[2]` on a module-scope collection
    // reads a location; the graph could not tell that from a relation call
    // because it had no places, which is why the refusal below fired on it.
    if (ctx.occurrences.id(expr)) |occurrence| {
        if (ctx.graph.application(occurrence)) |application| {
            if (ctx.graph.aggregateAccess(application.application) != null)
                return lowerAggregateAccess(ctx, application, consumption);
        }
        if (ctx.graph.isAggregateAccessApplication(occurrence))
            return refuseApplication(ctx.diagnostic, ctx.graph, @src(), "aggregate-access-fact", occurrence);
    }
    if (placeFold(ctx, expr)) |folded| return folded;
    // SUMMARY PROPAGATION: answer pure constant calls from the retained
    // summary, before the graph or the backend ever sees a call. A folded
    // call materializes no `bl`, no argument marshaling, no result slot.
    // `foldCallSite` needs only the summary, not the callee body.
    //
    // ACCOUNTING: a folded call is realized NOWHERE. Its application ID
    // must be recorded in `ctx.absent_applications` — the lowering's own
    // statement of absence that `validateDnirApplications` consumes.
    // Without this, the realization-count check fails.
    if (ctx.summary_cache) |cache| {
        if (expr.* == .call) {
            if (summary.foldCallSite(cache, ctx.graph, ctx.function, expr)) |k| {
                var folded: std.ArrayListUnmanaged(semantic_graph.id) = .empty;
                collectFoldedCallApplications(ctx, expr, &folded);
                for (folded.items) |app_id| {
                    recordSummaryFolded(ctx, app_id);
                }
                folded.deinit(ctx.alloc);
                return .{ .i64 = k };
            }
        }
        // Expressions containing calls (e.g. `sum45(0) == 45`): the
        // authoritative folder answers if the whole thing is constant.
        // Guarded by exprHasCall so pure arithmetic never pays for it.
        if (exprHasCall(expr)) {
            if (ctx.function) |caller| {
                // First try the authoritative folder.
                if (comptime_eval.foldValueExpr(ctx.alloc, ctx.graph, caller, expr)) |k| {
                    var folded: std.ArrayListUnmanaged(semantic_graph.id) = .empty;
                    collectFoldedCallApplications(ctx, expr, &folded);
                    for (folded.items) |app_id| {
                        recordSummaryFolded(ctx, app_id);
                    }
                    folded.deinit(ctx.alloc);
                    return .{ .i64 = k };
                }
                // If that fails, try summary-aware binop folding: fold any
                // calls in the operands via the summary, then compute the op.
                if (tryFoldBinopWithSummary(cache, ctx, caller, expr)) |k| {
                    var folded: std.ArrayListUnmanaged(semantic_graph.id) = .empty;
                    collectFoldedCallApplications(ctx, expr, &folded);
                    for (folded.items) |app_id| {
                        recordSummaryFolded(ctx, app_id);
                    }
                    folded.deinit(ctx.alloc);
                    return .{ .i64 = k };
                }
            }
        }
    }
    if (applicationNeedsGraphOccurrence(ctx, expr)) {
        return refuseMissingApplication(ctx, @src(), expr);
    }
    return switch (expr.*) {
        .nil => .{ .i64 = 0 },
        .int_lit => |i| .{ .i64 = i.val },
        .float_lit => |fl| .{ .f64 = fl.val },
        .true_lit => .{ .i64 = 1 },
        .false_lit => .{ .i64 = 0 },
        .quoted => |s| .{ .str = s.val }, // both faces share this carrier; see gaps/GAP-145.md
        // AN INJECTED WORLD ADDS REACH; IT NEVER TAKES A NAME.
        //
        // The world test used to run BEFORE `ctx.locals`, so any program that
        // bound `io`, `os` or `std` got the world DESCRIPTOR — whose address is
        // what a `.str` value carries — returned in place of its own value:
        //
        //     io: i64 = 5 ; io                 direct 56, C 5
        //     io: i64 = 5 ; io + 0             direct 64, C 5   (tracks layout)
        //     f: i64 = (io: i64) io + 1 ; f(4) direct 121, C 5
        //     zz: i64 = 5 ; zz                 direct 5,  C 5   (control)
        //
        // Compiled clean, ran, and answered a pointer. Sema resolves these
        // correctly — the two backends disagreeing is what localized it here.
        // Binding order is the whole fix: a local, a parameter or a module
        // constant is a NAME THAT IS TAKEN, and only a free name can still mean
        // the world. `tryLowerRelationEdgeCall` already asks the question this
        // way (`if (ctx.locals.contains("os")) return null;`).
        .name => |n| blk: {
            // A FUSED BODY RELATION'S RESULT NAME, standing for a literal
            // element. Asked FIRST because it is an active shadow: it is
            // non-empty only inside one collection relation's body, and inside
            // it the name means the element and nothing else.
            if (ctx.fused_literals.get(n.ident)) |element| break :blk dnir.Value{ .i64 = element };
            if (ctx.locals.get(n.ident)) |slot| break :blk dnir.Value{ .local = slot };
            // A TABLE WHOSE FIELDS ARE STORAGE HAS NO WHOLE-VALUE FACE HERE.
            //
            // The fields live in `__DATA` words; the table itself is not a value
            // this pass can produce. Answering with the record-marker slot that
            // `lowerRecordLiteralAssign` used to bind would hand `f(M)` a
            // register nothing ever wrote — garbage, at exit 0, which is the
            // class this whole change exists to avoid. So the marker is not
            // bound at all for such a table (see `lowerRecordLiteralAssign`) and
            // the read refuses here, AFTER `ctx.locals`: a parameter or local
            // spelled `M` is a different binding and still wins.
            if (moduleFieldStorageBase(ctx, n.ident))
                return bailWith(ctx.diagnostic, @src(), "table-value-field-storage");
            // A WRITTEN module-scope binding is READ FROM ITS STORAGE, never
            // folded. `ctx.locals` still wins: a parameter or local of the same
            // name shadows the global, exactly as it shadows the world below.
            if (ctx.module_globals.types.get(n.ident)) |ty| {
                const t = ctx.freshTemp();
                try ctx.emit(.{ .op = .load_global, .result = t, .field = n.ident, .ty = ty });
                if (ty == .str) try ctx.str_slots.put(ctx.alloc, t, {});
                break :blk dnir.Value{ .temp = t };
            }
            if (ctx.module_consts.ints.get(n.ident)) |mv| break :blk dnir.Value{ .i64 = mv };
            if (ctx.module_consts.strs.get(n.ident)) |sv| break :blk dnir.Value{ .str = sv };
            if (std.mem.eql(u8, n.ident, "io") or std.mem.eql(u8, n.ident, "os") or
                std.mem.eql(u8, n.ident, "std"))
            {
                break :blk dnir.Value{ .str = n.ident };
            }
            return bailNamed(ctx.diagnostic, @src(), "unresolved-name", n.ident);
        },
        .binop => |b| if (b.op == .@"and" or b.op == .@"or")
            try lowerShortCircuit(ctx, b.op, b.lhs, b.rhs)
        else
            try lowerBinop(ctx, b.op, b.lhs, b.rhs),
        .if_expr => |ie| try lowerIfExpr(ctx, ie),
        .unop => |u| blk: {
            if (u.op == .neg and u.operand.* == .int_lit) {
                // A negation with no i64 is not a constant this realizer can
                // hold; it falls through to the ordinary refusal rather than
                // being folded to a number nobody wrote.
                if (ast.negatedIntLiteral(u.operand.int_lit.val)) |v|
                    break :blk dnir.Value{ .i64 = v };
            }
            // `#s` on a known `str` is C `strlen` — a plain libc call, no
            // dynamic length probe and no boxed value. Any other `#` operand
            // needs the dynamic runtime and stays outside the direct subset.
            if (u.op == .len and exprIsStr(ctx, u.operand)) {
                const arg = try lowerExpr(ctx, u.operand);
                try ensureExtern(ctx, "string", "len", "strlen");
                const t = ctx.freshTemp();
                try ctx.emit(.{ .op = .call_extern, .result = t, .callee = "strlen", .lhs = arg });
                break :blk dnir.Value{ .temp = t };
            }
            if (u.op == .not) {
                const operand = try lowerExpr(ctx, u.operand);
                const t = ctx.freshTemp();
                try ctx.emit(.{
                    .op = .binop,
                    .result = t,
                    .binop = .eq,
                    .lhs = operand,
                    .rhs = .{ .i64 = 0 },
                    .ty = .any,
                });
                break :blk dnir.Value{ .temp = t };
            }
            // PREFIX `~` — bitwise NOT. `~x == x ^ -1` over the FULL i64
            // domain, with no range, sign or known-bits fact required, so the
            // capability is expressed in the tag set DNIR already has rather
            // than by adding a unary tag that every consumer would have to
            // learn. `native_backend.constBinopRealization` recognises the
            // `-1` operand and selects the single instruction AArch64 has for
            // it (`mvn`, i.e. `orn xd, xzr, xn`), so this costs one
            // instruction, not a materialised constant plus an `eor`.
            //
            // An integral operand is REQUIRED. `~` on text or on an f64 has no
            // meaning this backend can realize, and `exprIsIntegral` already
            // excludes both; refusing here keeps the wrong answer from being
            // computed on a bit pattern that is an address or a mantissa.
            if (u.op == .bnot and exprIsIntegral(ctx, u.operand)) {
                const operand = try lowerExpr(ctx, u.operand);
                const t = ctx.freshTemp();
                try ctx.emit(.{
                    .op = .binop,
                    .result = t,
                    .binop = .bxor,
                    .lhs = operand,
                    .rhs = .{ .i64 = -1 },
                    // The SAME width the infix spelling `x ~ -1` would get:
                    // `binopResultWidth(.bxor, x, -1)` joins `uint32` with the
                    // literal's `int32` to `uint32`, and `bxor` refits unless
                    // BOTH sides are canonical at that width — which `-1` is
                    // not. Anything else stays 64-bit, where `~` is the plain
                    // complement.
                    .ty = if (exprCRank(ctx, u.operand) == .uint32) RT.u32 else RT.any,
                });
                break :blk dnir.Value{ .temp = t };
            }
            // `@(expr)` / `expr@{ stage = compile }` — EVALUATION UNDER THE
            // COMPILE-STAGE WORLD. When that world holds a value for the
            // operand, the value is what the program contains; there is no
            // residual operation to realize. When it does not, the refusal
            // NAMES the world question rather than the token, because
            // "compile-nontable" told the author about the compiler's precheck
            // and nothing about their program.
            if (u.op == .compile) {
                if (compileStageAbsentWorld(ctx, u.operand)) |drawn| return bailNamed(ctx.diagnostic, @src(), "compile-stage-absent", drawn);
                if (compileStageValue(u.operand)) |v| break :blk v;
                // The module-scoped fold: `@(tri(100))` where `tri` is a
                // sibling relation. See `compileStageValueInModule` for the
                // contract and the retired precheck's narrower rule.
                if (compileStageValueInModule(ctx.alloc, ctx.module_consts, u.operand)) |v| break :blk v;
                return bailWith(ctx.diagnostic, @src(), "compile-stage-absent");
            }
            return bailNamed(ctx.diagnostic, @src(), "unop-not-lowered", @tagName(u.op));
        },
        .index => |ix| blk: {
            if (argv(ix.obj)) {
                try ensureExtern(ctx, "os", "args", "idol_os_arg");
                const i = try lowerExpr(ctx, ix.key);
                const ty = osResult("args");
                if (consumption == .discard) {
                    try ctx.emit(.{ .op = .call_extern, .callee = "idol_os_arg", .lhs = i, .ty = ty });
                    break :blk .void;
                }
                const t = ctx.freshTemp();
                try ctx.emit(.{ .op = .call_extern, .result = t, .callee = "idol_os_arg", .lhs = i, .ty = ty });
                break :blk .{ .temp = t };
            }
            if (env(ix.obj)) {
                try ensureExtern(ctx, "os", "env", "getenv");
                const k = try lowerExpr(ctx, ix.key);
                const ty = osResult("env");
                if (consumption == .discard) {
                    try ctx.emit(.{ .op = .call_extern, .callee = "getenv", .lhs = k, .ty = ty });
                    break :blk .void;
                }
                const t = ctx.freshTemp();
                try ctx.emit(.{ .op = .call_extern, .result = t, .callee = "getenv", .lhs = k, .ty = ty });
                break :blk .{ .temp = t };
            }
            // `t[2]` on a positional table resolves to the element's own local,
            // so a constant index costs nothing at runtime. A non-constant index
            // needs a base pointer and computed offset — the native table
            // milestone — and is refused rather than mis-lowered.
            // §2: `s[i]` IS the byte, 0-based — there is no string
            // library, only a string descriptor. This is the CANONICAL byte
            // access, and it did not lower while the deny-listed
            // `string.byte(s, i)` did. Sixth instance of that pattern this
            // session, after string.byte, s:byte, @{…}, mem and math.
            //
            // The index is emitted as `i + 1` because the backend's byte load
            // computes `base + (idx - 1)` for string.byte's 1-based convention.
            // Normalizing here keeps ONE origin in the backend rather than
            // giving it a second — the same decision the byte STORE required,
            // where two origins on one opcode would be a wrong address.
            // A DETERMINED table read at a compile-time index is its element,
            // whatever the table's extent and whatever realization the rest of
            // the function forced on it. Checked first, so the answer does not
            // depend on which of the three storage paths below would have run.
            if (try constTableRead(ctx, expr)) |v| break :blk v;
            if (exprIsStr(ctx, ix.obj)) {
                const sbase = try lowerExpr(ctx, ix.obj);
                const raw = try lowerExpr(ctx, ix.key);
                const one = ctx.freshTemp();
                try ctx.emit(.{ .op = .binop, .result = one, .binop = .add, .lhs = raw, .rhs = .{ .i64 = 1 } });
                const t = ctx.freshTemp();
                try ctx.emit(.{ .op = .load_index, .result = t, .lhs = sbase, .rhs = .{ .temp = one } });
                break :blk dnir.Value{ .temp = t };
            }
            if (ix.obj.* != .name) return bail(ctx.diagnostic, @src());
            // A memory-backed table indexes for real: one scaled load, constant
            // or not. This is the path that makes a shared token array work.
            if (ptrSlotOf(ctx, ix.obj)) |base| {
                const idx = try guardedTableIndex(ctx, ix.obj.name.ident, ix.key);
                const t = ctx.freshTemp();
                try ctx.emit(.{
                    .op = .load_index,
                    .ty = .i64,
                    .result = t,
                    .lhs = .{ .local = base },
                    .rhs = idx,
                });
                break :blk dnir.Value{ .temp = t };
            }
            // A string-literal index on a named-field table is field access by
            // another spelling. `t["name"]` and `t.name` denote one semantic
            // operation; routing through the field lowering preserves the
            // descriptor instead of collapsing to `.any` in the dynamic path.
            if (ix.key.* == .quoted) {
                var field_expr = ast.Expr{ .field = .{
                    .loc = ix.key.quoted.loc,
                    .obj = ix.obj,
                    .field = ix.key.quoted.val,
                } };
                break :blk try lowerField(ctx, &field_expr);
            }
            const n = ast.intLiteralValue(ix.key) orelse
                break :blk try lowerDynamicIndex(ctx, ix.obj.name.ident, ix.key);
            const key = try std.fmt.allocPrint(ctx.alloc, "{s}.{d}", .{ ix.obj.name.ident, n });
            defer ctx.alloc.free(key);
            if (ctx.locals.get(key)) |slot|
                break :blk dnir.Value{ .local = slot };
            // Module-level constant table elements
            if (ctx.module_consts.strs.get(key)) |sv|
                break :blk dnir.Value{ .str = sv };
            if (ctx.module_consts.ints.get(key)) |iv|
                break :blk dnir.Value{ .i64 = iv };
            return bail(ctx.diagnostic, @src());
        },
        .call => try lowerCall(ctx, expr, consumption),
        .method_call => try lowerSubjectCall(ctx, expr, consumption),
        .field => try lowerField(ctx, expr),
        .macro_call => |mc| {
            if (dnir_hardware.parseIntrinsic(mc.name)) |hw| {
                return try lowerHwIntrinsic(ctx, hw, mc.args);
            }
            return bail(ctx.diagnostic, @src());
        },
        else => bailNamed(ctx.diagnostic, @src(), "expression-not-lowered", @tagName(expr.*)),
    };
}

/// Normalize the canonical receiver face `a:m(x)` into the call form the rest
/// of this file already lowers.
///
/// ONE EDGE: `a:m(x)` and `m(a, x)` are the same edge written from the two ends
/// — declaration spelling versus call spelling. Rather than teach every arm
/// below about receivers, the face is rewritten once here and every existing
/// lowering applies unchanged. Without it, `.method_call` fell into the `else`
/// bail, so the spelling the canon mandates everywhere (rule 6, FACE-CALL) was
/// the one shape that could not lower natively — `s:byte(1)` bailed while
/// `string.byte(s, 1)`, which the deny list forbids, lowered to an indexed load.
///
/// String primitives rebuild the `string.m(a, …)` field form specifically,
/// because their lowering is an indexed load / length scan keyed on that
/// shape, not a call to a symbol that exists.
fn faceAsCall(ctx: *LowerCtx, expr: *const ast.Expr) Error!*const ast.Expr {
    const mc = expr.method_call;
    const args = try ctx.alloc.alloc(*ast.Expr, mc.args.len + 1);
    args[0] = mc.obj;
    @memcpy(args[1..], mc.args);

    const func = try ctx.alloc.create(ast.Expr);
    const string_method =
        std.mem.eql(u8, mc.method, "sub") or
        std.mem.eql(u8, mc.method, "match") or
        std.mem.eql(u8, mc.method, "byte") or
        std.mem.eql(u8, mc.method, "len");
    if (exprIsStr(ctx, mc.obj) or string_method) {
        const recv = try ctx.alloc.create(ast.Expr);
        recv.* = .{ .name = .{ .loc = mc.loc, .ident = "string" } };
        func.* = .{ .field = .{ .loc = mc.loc, .obj = recv, .field = mc.method } };
    } else if (subject_home.homeOfWithReceiver(mc.method, exprIsStr(ctx, mc.obj))) |owner| {
        // The subject-first face rebuilt as `home.relation(subject, …)`, the
        // same node the operation-first face builds. One edge, two spellings.
        const recv = try ctx.alloc.create(ast.Expr);
        recv.* = .{ .name = .{ .loc = mc.loc, .ident = subject_home.homeName(owner) } };
        func.* = .{ .field = .{ .loc = mc.loc, .obj = recv, .field = mc.method } };
    } else {
        func.* = .{ .name = .{ .loc = mc.loc, .ident = mc.method } };
    }

    const call = try ctx.alloc.create(ast.Expr);
    call.* = .{ .call = .{ .loc = mc.loc, .func = func, .args = args } };
    return call;
}

fn applicationResultIs(
    ctx: *const LowerCtx,
    expr: *const Expr,
    expected: std.meta.Tag(types.ResolvedType),
) bool {
    const descriptor = applicationFirstResultDescriptor(ctx, expr) orelse return false;
    return std.meta.activeTag(descriptor) == expected;
}

fn applicationFirstResultDescriptor(ctx: *const LowerCtx, expr: *const Expr) ?types.ResolvedType {
    const application = ctx.occurrences.get(expr) orelse return null;
    const results = ctx.graph.applicationResults(application.application) orelse return null;
    if (results.len == 0) return null;
    return (ctx.graph.get(results[0]) orelse return null).descriptor;
}

fn applicationDescriptor(ctx: *const LowerCtx, expr: *const Expr) ?types.ResolvedType {
    const application = ctx.occurrences.get(expr) orelse return null;
    return ctx.graph.applicationDescriptor(application.application);
}

fn publishedDescriptor(
    ctx: *const LowerCtx,
    application: *const semantic_graph.ApplicationFact,
) Error!types.ResolvedType {
    return ctx.graph.applicationDescriptor(application.application) orelse
        invalidGraphFacts(ctx.diagnostic, @src(), "application-result-descriptor");
}

const CheckedScalarOperand = struct {
    value: semantic_graph.id,
    expression: *Expr,
    descriptor: types.ResolvedType,
    /// Exact binding edge published by the graph for a name operand. Absence is
    /// lawful only for a derived/literal operand; an unresolved name is not a
    /// request for realization to repeat lexical lookup from its spelling.
    binding: ?semantic_graph.id,
};

fn exprBinopDepth(expr: *const ast.Expr) usize {
    return switch (expr.*) {
        .binop => |b| 1 + @max(exprBinopDepth(b.lhs), exprBinopDepth(b.rhs)),
        else => 0,
    };
}

fn nameIsCurrentParam(ctx: *const LowerCtx, name: []const u8) bool {
    const slot = ctx.locals.get(name) orelse return false;
    for (ctx.self_param_slots) |param_slot| {
        if (param_slot == slot) return true;
    }
    return false;
}

fn checkedOperandAdmitsDirectGp(ctx: *const LowerCtx, expr: *const Expr) bool {
    if (ctx.occurrences.get(expr) != null) return true;
    return switch (expr.*) {
        .int_lit, .true_lit, .false_lit, .float_lit => true,
        .binop => exprBinopDepth(expr) <= 1,
        .name => |n| nameIsCurrentParam(ctx, n.ident),
        else => false,
    };
}

/// The record an operand NAMES, when that name's fields are already resident in
/// exploded slots — or null when the operand is not one.
///
/// THIS ASKS `scalarRecordForName`, IT DOES NOT RE-DERIVE IT. That function is
/// already the authority on "this name is a record stored as one local per
/// field", and the unchecked call path has expanded record arguments through it
/// for as long as it has existed (`emitScalarCallArgs`). A second predicate
/// here would be a second opinion about the same fact, and the two ends of a
/// call disagreeing about how many registers a record occupies is a wrong
/// ANSWER rather than a refusal — both sides still compile.
fn homogeneousF64Record(rec: dnir.RecordDesc) bool {
    if (rec.fields.len == 0 or rec.kinds.len != rec.fields.len) return false;
    for (rec.kinds) |k| {
        if (k != .f64) return false;
    }
    return true;
}

/// Record operand selected from graph-published descriptor/shape facts.
fn recordForGraphOperand(ctx: *const LowerCtx, value: semantic_graph.id) ?dnir.RecordDesc {
    if (ctx.graph.descriptorShape(value, 0)) |shape| {
        for (ctx.records) |rec| {
            // THE ARGUMENT BUDGET, NOT THE REGISTER FILE. This is an OPERAND
            // question — "are this record's fields resident so the call can
            // spend them" — and an operand's general-purpose budget is
            // `max_direct_scalar_args`: eight registers plus the eight stack
            // slots the outgoing block carries. Bounding it at the register
            // file made a nine-field record operand invisible here, so the
            // caller fell through to the opaque-handle arm and asked the
            // backend for a `v.a` that the exploded form never gave a region.
            if (rec.semantic_shape == shape and !homogeneousF64Record(rec) and
                rec.fields.len > 0 and rec.fields.len <= max_direct_scalar_args and
                checkedRecordResultSupported(rec))
            {
                return rec;
            }
        }
    }
    const node = ctx.graph.get(value) orelse return null;
    const descriptor = node.descriptor orelse return null;
    const rec = recordForDescriptor(ctx.records, descriptor, ctx.graph) orelse return null;
    if (homogeneousF64Record(rec) or rec.fields.len > max_direct_scalar_args) return null;
    return rec;
}

fn operandRecordStorage(ctx: *LowerCtx, operand: CheckedScalarOperand) ?dnir.RecordDesc {
    return recordForGraphOperand(ctx, operand.value);
}

/// Does this operand name a record AT ALL — including one whose fields the
/// argument registers cannot carry?
///
/// THIS IS A DIFFERENT FACT FROM `operandRecordStorage`, NOT A SECOND OPINION
/// ABOUT IT, and the difference is exactly the set that must still be REFUSED.
/// An f64 record is the live case: its fields are resident under the same
/// "name.field" keys, but `scalarRecordForName` declines it because the
/// homogeneous-float aggregate is a different ABI. Without this the name falls
/// through to the scalar path, which stages the record's OWN slot — a slot that
/// never holds a value — and the backend reports `DNB007 local 0 has no
/// register` instead of naming the operand law. Measured: that is precisely
/// what happened when this predicate was deleted rather than narrowed.
fn operandNamesRecord(ctx: *LowerCtx, expr: *const Expr) bool {
    if (expr.* != .name) return false;
    for (ctx.records) |rec| {
        if (!homogeneousF64Record(rec)) continue;
        if (recordFieldsPresent(ctx, expr.name.ident, rec)) return true;
    }
    return false;
}

fn checkedScalarFieldProjection(
    ctx: *const LowerCtx,
    expr: *const Expr,
) ?types.ResolvedType {
    if (expr.* != .field or expr.field.obj.* != .name) return null;
    var buf: [512]u8 = undefined;
    const fk = std.fmt.bufPrint(&buf, "{s}.{s}", .{ expr.field.obj.name.ident, expr.field.field }) catch return null;
    if (ctx.locals.get(fk)) |slot| {
        if (ctx.str_slots.contains(slot)) return .str;
        if (ctx.f64_slots.contains(slot)) return .f64;
        if (ctx.bool_slots.contains(slot)) return .bool;
        if (ctx.ptr_slots.contains(slot)) return physical_pointer;
        if (ctx.narrow_slots.get(slot)) |ty| return ty;
        return .any;
    }
    if (recordFieldKindForParam(ctx, expr.field.obj.name.ident, expr.field.field)) |kind| {
        return switch (kind) {
            .str => .str,
            .f64 => .f64,
            .i64 => .any,
        };
    }
    return null;
}

fn checkedScalarOperand(
    ctx: *const LowerCtx,
    value: semantic_graph.id,
) Error!CheckedScalarOperand {
    const node = ctx.graph.get(value) orelse return invalidGraphFacts(ctx.diagnostic, @src(), "application-value");
    const descriptor = node.descriptor orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-descriptor");
    const raw = node.ast_ref orelse return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-provenance");
    const expression: *Expr = @ptrCast(@alignCast(raw));
    const binding: ?semantic_graph.id = switch (expression.*) {
        .name => switch (ctx.graph.valueOrigin(value)) {
            .one => |exact| exact,
            .unknown, .none => return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-binding"),
        },
        else => switch (ctx.graph.valueOrigin(value)) {
            .none => null,
            .unknown, .one => return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-binding"),
        },
    };
    if (expression.* == .table) {
        return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-abi");
    }
    var effective = descriptor;
    switch (descriptor) {
        .i32, .i64, .bool, .str, .f64, .pointer, .any => {},
        .enum_type => |e| {
            for (e.variants) |v| {
                if (v.payload != null) return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-abi");
            }
        },
        .@"struct" => {
            if (checkedScalarFieldProjection(ctx, expression)) |field_ty| {
                effective = field_ty;
            } else if (expression.* == .name) {
                if (ctx.locals.get(expression.name.ident)) |_| {
                    effective = .any;
                } else if (recordForDescriptor(ctx.records, descriptor, ctx.graph)) |rec| {
                    // THE SHAPE IS ADMITTED AGAINST THE ARGUMENT BUDGET, and
                    // that budget is `max_direct_scalar_args` — the eight
                    // argument registers plus the eight stack slots a record's
                    // exploded fields ride exactly as scalar operands do. See
                    // `functionEligibleReason`; these two must name the same
                    // number or a call the callee accepts is refused here.
                    if (rec.fields.len == 0 or rec.fields.len > max_direct_scalar_args) {
                        return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-abi");
                    }
                    effective = .any;
                } else {
                    effective = .any;
                }
            } else if (recordForDescriptor(ctx.records, descriptor, ctx.graph)) |rec| {
                // Same budget as the `.name` arm above, for the same reason: a
                // record operand FORWARDED from an enclosing relation's own
                // record parameter reaches here (its fields are resident as
                // `p.field` locals, so `ctx.locals.get("p")` misses), and
                // bounding it at the register file refused `outer(p) ->
                // inner(p)` for any record the callee would have accepted.
                if (rec.fields.len == 0 or rec.fields.len > max_direct_scalar_args) {
                    return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-abi");
                }
                if (expression.* == .field) {
                    effective = checkedScalarFieldProjection(ctx, expression) orelse .any;
                }
            } else if (expression.* == .field) {
                effective = checkedScalarFieldProjection(ctx, expression) orelse .any;
            } else {
                return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-abi");
            }
        },
        .table_type => {
            // A local table binding (`lx: lexer = …`) crosses home as one opaque
            // pointer operand — same treatment struct locals already get above.
            if (expression.* == .name and
                (ctx.locals.get(expression.name.ident) != null or
                    (ctx.graph.descriptorShape(value, 0) != null and recordForGraphOperand(ctx, value) != null)))
            {
                effective = .any;
            } else {
                return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-abi");
            }
        },
        else => return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-abi"),
    }
    return .{
        .value = value,
        .expression = expression,
        .descriptor = effective,
        .binding = binding,
    };
}

fn checkedOperandName(ctx: *const LowerCtx, operand: *const CheckedScalarOperand) Error![]const u8 {
    const binding = operand.binding orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-binding");
    const node = ctx.graph.get(binding) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-binding");
    return node.name orelse invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-binding");
}

fn checkedScalarResult(diagnostic: *Diagnostic, descriptor: types.ResolvedType) Error!void {
    switch (descriptor) {
        .i8,
        .i16,
        .i32,
        .i64,
        .u8,
        .u16,
        .u32,
        .u64,
        .f32,
        .f64,
        .bool,
        .str,
        .pointer,
        .void,
        .any,
        .nil,
        => {},
        .@"struct" => |s| {
            if (types.nominalRepr(s.name)) |nr| {
                if (types.nominalReprAdmissible(nr)) return;
            }
            return invalidGraphFacts(diagnostic, @src(), "application-result-abi");
        },
        else => return invalidGraphFacts(diagnostic, @src(), "application-result-abi"),
    }
}

/// Project the semantic subject, when present, followed by position-ordered
/// arguments. Subject absence stays absence; it is not reconstructed as
/// argument zero for operation-first source faces.
fn checkedScalarOperands(
    ctx: *LowerCtx,
    application: *const semantic_graph.ApplicationFact,
    storage: *[max_direct_scalar_args]CheckedScalarOperand,
    include_subject: bool,
) Error![]const CheckedScalarOperand {
    var count: usize = 0;
    if (include_subject) {
        if (ctx.graph.applicationSubject(application.application)) |subject| {
            storage[count] = try checkedScalarOperand(ctx, subject);
            count += 1;
        }
    }
    const arguments = ctx.graph.applicationArguments(application.application) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "application-argument-pack");
    for (arguments) |argument| {
        if (count >= storage.len) return invalidGraphFacts(ctx.diagnostic, @src(), "application-argument-pack");
        storage[count] = try checkedScalarOperand(ctx, argument);
        count += 1;
    }
    return storage[0..count];
}

fn checkedApplicationResult(
    ctx: *const LowerCtx,
    application: *const semantic_graph.ApplicationFact,
) Error!semantic_graph.id {
    const results = ctx.graph.applicationResults(application.application) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "application-result-pack");
    if (results.len != 1) return invalidGraphFacts(ctx.diagnostic, @src(), "application-result-pack");
    return results[0];
}

fn checkedGpPackResultType(
    ctx: *const LowerCtx,
    value: semantic_graph.id,
) Error!RT {
    const descriptor = (ctx.graph.get(value) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "application-result-member")).descriptor orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "application-result-descriptor");
    return switch (descriptor) {
        .i8,
        .i16,
        .i32,
        .i64,
        .u8,
        .u16,
        .u32,
        .u64,
        .bool,
        .str,
        .pointer,
        => descriptor,
        else => invalidGraphFacts(ctx.diagnostic, @src(), "application-result-abi"),
    };
}

/// The current value of one checked module binding, through semantic identity:
///
///     use value -> binding -> initializer value -> exact_i64
///                              \\-> module place stability
///
/// This is the first `ModuleConsts.ints` deletion domain. The caller already
/// holds the exact binding id published on the application operand, so a name
/// lookup here would be a rival semantic decision. A producer-domain row that
/// is missing or damaged refuses; a binding that is lawfully mutable is
/// realized through its exact physical module word inside this decision.
const BindingI64Decision = union(enum) {
    /// This operand is outside the bounded binding-initializer producer domain.
    unvisited,
    /// The graph selected the value; no later name-based semantic fallback is
    /// permitted. The physical value may be an immediate or an exact load.
    value: dnir.Value,
};

fn checkedBindingI64(
    ctx: *LowerCtx,
    operand: *const CheckedScalarOperand,
) Error!BindingI64Decision {
    if (operand.descriptor != .i64) return .unvisited;
    const binding = operand.binding orelse return .unvisited;
    // The binding-initializer producer domain covers module-root bindings
    // only (see the doc comment above): an initializer row is a statement
    // about module place stability. A branch- or function-local binding is
    // outside the domain no matter how the candidate census classified it --
    // an assignment inside a branch deliberately marks the row refused -- so
    // it answers unvisited and lowers through the normal local path.
    // Refusing here was DNB011: a call argument resolving to a binding
    // assigned inside an if/while body was rejected as damaged graph facts
    // ("binding-initializer") when it was merely out of domain. A missing
    // node falls through to the query below, preserving the old refusal.
    if (ctx.graph.get(binding)) |binding_node| {
        if (binding_node.scope != ctx.graph.module_root) return .unvisited;
    }
    const initialization = switch (ctx.graph.bindingInitialization(binding)) {
        .unvisited => return .unvisited,
        .invalid => return invalidGraphFacts(ctx.diagnostic, @src(), "binding-initializer"),
        .known => |fact| fact,
    };
    const p = ctx.graph.modulePlace(initialization.place) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "binding-initializer-place");
    if (p.shape != .scalar or p.region != .module or p.init == null)
        return invalidGraphFacts(ctx.diagnostic, @src(), "binding-initializer-place");

    // Unknown is not false and not permission to use the initializer. These
    // are the exact f9 scalar-place facts whose absence formerly forced every
    // consumer to run a new assignment census.
    if (p.facts.mutation == .unknown or
        p.facts.immutability == .unknown or
        p.facts.contents_known == .unknown or
        p.facts.determinacy == .unknown or
        p.facts.alias == .unknown)
    {
        return invalidGraphFacts(ctx.diagnostic, @src(), "binding-initializer-place");
    }
    const initializer_current = p.facts.mutation == .no and
        p.facts.immutability == .yes and
        p.facts.contents_known == .yes and
        p.facts.determinacy == .exact and
        p.facts.alias == .no;
    const one_binding = switch (p.bindCount()) {
        .exact => |count| count == 1,
        .bounded, .unknown => return invalidGraphFacts(
            ctx.diagnostic,
            @src(),
            "binding-initializer-place",
        ),
    };
    if (initializer_current and one_binding) {
        // `escape` is deliberately not a blocker. f9 defines a module scalar
        // as escaped when a relation body names it; this very checked operand
        // is such a read. Scalar reads copy the ring element, and immutability
        // plus known contents proves every such copy equals the initializer.
        const exact = ctx.graph.exactI64(initialization.value) orelse
            return invalidGraphFacts(ctx.diagnostic, @src(), "binding-initializer-value");
        return .{ .value = .{ .i64 = exact } };
    }

    // A known non-current initializer must use the one physical module word.
    // Returning `null` here used to fall through to `ModuleConsts.ints`, which
    // converted a graph-known runtime value back into the initializer merely
    // because the spelling remained in a legacy map. Missing storage therefore
    // refuses; it is not permission to reconstruct another semantic answer.
    const name = try checkedOperandName(ctx, operand);
    const ty = ctx.module_globals.types.get(name) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "binding-initializer-storage");
    if (ty != .i64)
        return invalidGraphFacts(ctx.diagnostic, @src(), "binding-initializer-storage");
    const temp = ctx.freshTemp();
    try ctx.emit(.{ .op = .load_global, .result = temp, .field = name, .ty = ty });
    return .{ .value = .{ .temp = temp } };
}

/// ONE PHYSICAL ARGUMENT SLOT, AND THE SEMANTIC LINEAGE IT REALIZES.
///
/// THE GENERAL LAW: one semantic value realizes as 0..N physical components,
/// and which operand — through which projection — a given component realizes is
/// a FACT ITS PRODUCER KNOWS AND MUST CARRY FORWARD. It is not recoverable
/// downstream: a consumer holds a physical slot index and a semantic operand
/// array, and nothing lawfully relates the two.
///
/// This producer used to answer with a bare slot COUNT, and four consumers
/// reconstructed "the operand behind slot i" as `operands[i]` — correct only
/// while every operand realizes as exactly one slot, and out of bounds the
/// moment one realizes as two. GAP-208: `add(p, q)` over `pt: { x: i64, y: i64 }`
/// stages four field slots from two semantic operands and read `operands[4]` of
/// a two-element slice. Clamping to `operands.len` would have staged two of the
/// four values and exchanged a hard panic for a wrong answer, which is worse.
///
/// The same missing correspondence is what scalar replacement, ABI synthesis,
/// result-pack specialization, SIMD packing, foreign aggregates and debugger
/// reconstruction each need. None of them wants "how many registers"; each
/// wants "slot 1 IS operand `p` projected through `y`, and it carries `y`'s
/// descriptor, not `pt`'s".
///
/// So the count is DELETED rather than fixed. There is no longer a number a
/// consumer could index the wrong array by: the producer answers with the
/// physical slots themselves, each naming its own operand and projection.
const StagedSlot = struct {
    /// The semantic operand this slot realizes a component of. Points into the
    /// caller's `operand_storage`, which outlives every use.
    operand: *const CheckedScalarOperand,
    /// WHICH component of that operand. The field name when this slot realizes
    /// a projection; EMPTY when this slot realizes the operand entire. Empty
    /// and "the operand has no fields" are different facts and stay different.
    projection: []const u8,
    /// What THIS SLOT carries: the projected field's descriptor for a
    /// component, the operand's own descriptor for a whole-operand slot. An
    /// aggregate's descriptor never stands in for a field's.
    descriptor: types.ResolvedType,
    value: dnir.Value,
};

fn evaluateCheckedScalarOperands(
    ctx: *LowerCtx,
    application: *const semantic_graph.ApplicationFact,
    operands: []const CheckedScalarOperand,
    storage: *[max_direct_scalar_args]StagedSlot,
) Error![]const StagedSlot {
    const parameters = blk: {
        if (!ctx.require_graph_facts or ctx.graph.gateTransportModule()) break :blk null;
        const layouts = ctx.signature orelse break :blk null;
        const target = ctx.graph.applicationTarget(application.application) orelse
            return invalidGraphFacts(ctx.diagnostic, @src(), "application-target");
        const layout = layouts.get(target) orelse break :blk null;
        var aggregate = false;
        for (layout.params) |parameter| if (parameter.record != null) {
            aggregate = true;
        };
        if (!aggregate) break :blk null;
        if (layout.params.len != operands.len)
            return invalidGraphFacts(ctx.diagnostic, @src(), "application-parameter-pack");
        break :blk layout.params;
    };
    var fp_count: usize = 0;
    var count: usize = 0;
    for (operands, 0..) |*operand, operand_index| {
        const demand: ?dnir.Param = if (parameters) |params| params[operand_index] else null;
        const carrier = blk: {
            const params = parameters orelse break :blk null;
            const name = params[operand_index].record orelse break :blk null;
            const required = findRecordName(ctx.records, .{ .named = name }) orelse
                return invalidGraphFacts(ctx.diagnostic, @src(), "record-parameter-carrier");
            const node = ctx.graph.get(operand.value) orelse break :blk null;
            const descriptor = node.descriptor orelse break :blk null;
            const actual = actual: {
                if (ctx.graph.descriptorShape(operand.value, 0)) |shape| {
                    for (ctx.records) |candidate| {
                        if (candidate.semantic_shape == shape) break :actual candidate;
                    }
                    break :blk null;
                }
                if (descriptor != .@"struct") break :blk null;
                break :actual recordForDescriptor(ctx.records, descriptor, ctx.graph) orelse break :blk null;
            };
            if (!Record.fits(actual, required))
                return invalidGraphFacts(ctx.diagnostic, @src(), "record-parameter-carrier-mismatch");
            break :blk .{ .required = required, .actual = actual };
        };
        const required: ?dnir.RecordDesc = if (carrier) |records| records.required else null;
        if (demand) |parameter| {
            if (parameter.record != null and parameter.ty.eql(physical_pointer)) {
                if (count >= storage.len)
                    return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-abi");
                const records = carrier orelse
                    return invalidGraphFacts(ctx.diagnostic, @src(), "record-parameter-carrier");
                if (operand.expression.* != .name)
                    return invalidGraphFacts(ctx.diagnostic, @src(), "record-parameter-place-unproved");
                const base = try Record.materialize(ctx, operand, records.actual, records.required);
                storage[count] = .{
                    .operand = operand,
                    .projection = "",
                    .descriptor = physical_pointer,
                    .value = .{ .local = base },
                };
                count += 1;
                continue;
            }
        }
        // ONE SEMANTIC VALUE, A CONSUMER-DIRECTED REALIZATION. A record operand
        // is not materialized into an aggregate and it is not given an address:
        // this consumer wants scalar fields in registers, so the fields are what
        // crosses. Nothing is stored, nothing is copied, and no struct exists.
        //
        // The fields are ALREADY resident, one local per field, keyed
        // "name.field" — the same storage `p.a` reads and the same storage
        // `lowerRecordReturn` gathers from for `return p`. So this arm adds no
        // representation; it spends the one that is already there.
        //
        // DESCRIPTOR ORDER IS THE CONTRACT, and it is the same order the callee
        // homes its parameter from (`rec.fields`, one register each). The two
        // ends read the same list, which is why they cannot drift.
        if (required orelse operandRecordStorage(ctx, operand.*)) |rec| {
            // THE GENERAL-PURPOSE ARGUMENT BUDGET IS THE BOUND, and it is the
            // same bound the CALLEE applies when it homes the parameter
            // (`functionEligibleReason` admits a record parameter up to
            // `max_direct_scalar_args`, because a record field is a
            // general-purpose word and takes the same stack-argument extension
            // a scalar operand takes). Stating it here in the same terms is
            // what keeps a record that the callee would refuse from being
            // staged by the caller as if it fit.
            //
            // The physical extension is `stageCheckedScalarOperands` emitting
            // `mov_arg` at slot >= 8 and `native_backend` flushing those slots
            // to the outgoing argument area; neither cares that the word came
            // from a record field rather than from a scalar operand.
            if (count + rec.fields.len <= max_direct_scalar_args) {
                for (rec.fields, 0..) |fname, fi| {
                    // EVERY FIELD OF AN EXPANDED RECORD IS A GENERAL-PURPOSE
                    // SLOT, AND THAT IS THE CALLEE'S OWN ACCOUNTING, not a
                    // caller-side convention: `functionEligible` admits a
                    // record parameter by adding `r.fields.len` to `gp_slots`
                    // and refuses the all-f64 record outright, so a record that
                    // reaches here has every field homed out of x0..x7.
                    //
                    // A MIXED record — `{ x: i64, y: f64 }` — is the one shape
                    // where naming the field's real descriptor and staging by
                    // it disagree: the descriptor rule below would put `y` in
                    // v0 while the callee reads it from x1. Both ends still
                    // compile, so the disagreement is a wrong ANSWER. Refuse it
                    // by name instead. Nothing regresses: a mixed record has two
                    // or more fields by construction, and every record operand
                    // of two or more fields panicked here before this producer
                    // carried per-slot lineage at all.
                    const kind: dnir.FieldKind = if (fi < rec.kinds.len) rec.kinds[fi] else .i64;
                    if (kind == .f64) {
                        return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-abi");
                    }
                    const name = try checkedOperandName(ctx, operand);
                    const descriptor: RT = switch (kind) {
                        .str => .str,
                        .i64 => .i64,
                        .f64 => unreachable,
                    };
                    const value: dnir.Value = if (Record.locate(ctx, name) != null)
                        (try Record.load(ctx, name, fname)) orelse
                            return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-abi")
                    else blk: {
                        const key = try std.fmt.allocPrint(ctx.alloc, "{s}.{s}", .{ name, fname });
                        defer ctx.alloc.free(key);
                        const slot = ctx.locals.get(key) orelse
                            return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-abi");
                        break :blk .{ .local = slot };
                    };
                    storage[count] = .{
                        .operand = operand,
                        .projection = fname,
                        .descriptor = descriptor,
                        .value = value,
                    };
                    count += 1;
                }
                continue;
            }
            return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-abi");
        }
        // A RECORD-DESCRIPTOR OPERAND WITH NO RESIDENT FIELDS IS REFUSED BY
        // NAME, never lowered as if it were a scalar. `checkedScalarOperand`
        // admits a record whose SHAPE fits the argument registers; whether its
        // fields are actually resident is a different fact, and only the
        // storage above can answer it. A record produced straight into a call
        // (`take(mk(1))`) has a backend record region rather than exploded
        // locals, so it lands here — refused, with the operand law named.
        if (operand.descriptor == .@"struct") {
            if (operand.expression.* == .name) {
                // THE PHYSICAL BOUND BELONGS TO THE PHYSICAL INDEX. This arm
                // wrote `storage[count]` with no bound at all, which was
                // unreachable only because a record operand used to panic in
                // the caller before enough slots could accumulate to matter.
                if (count >= storage.len) {
                    return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-abi");
                }
                if (try lowerOpaqueRecordLocalArg(ctx, operand.expression)) |materialized| {
                    storage[count] = wholeOperandSlot(operand, materialized);
                    count += 1;
                    continue;
                }
            }
            return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-abi");
        }
        // AND A RECORD THE ARGUMENT REGISTERS CANNOT CARRY IS STILL REFUSED BY
        // NAME — an f64 record is the live case. Its fields are resident, so it
        // looks like the expandable case from every angle except the one that
        // matters: it is a homogeneous float aggregate with a different ABI.
        // Falling through would stage the record's own slot, which holds no
        // value.
        if (operandNamesRecord(ctx, operand.expression)) {
            return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-abi");
        }
        if (count >= storage.len) {
            return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-abi");
        }
        switch (try checkedBindingI64(ctx, operand)) {
            .unvisited => {},
            .value => |value| {
                storage[count] = wholeOperandSlot(operand, value);
                count += 1;
                continue;
            },
        }
        if (try lowerOpaqueRecordLocalArg(ctx, operand.expression)) |materialized| {
            storage[count] = wholeOperandSlot(operand, materialized);
            count += 1;
            continue;
        }
        storage[count] = wholeOperandSlot(operand, try lowerExprCons(ctx, operand.expression, .single));
        if (operand.descriptor == .f64) fp_count += 1;
        count += 1;
    }
    // Only the eight FP argument registers (v0..v7) are marshaled; wide integer
    // relations get the stack-arg extension, floating-point ones do not.
    if (fp_count == count and count > 8) {
        return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-abi");
    }
    return storage[0..count];
}

/// A slot that realizes its operand ENTIRE — no projection, and the operand's
/// own descriptor is what crosses.
fn wholeOperandSlot(operand: *const CheckedScalarOperand, value: dnir.Value) StagedSlot {
    return .{
        .operand = operand,
        .projection = "",
        .descriptor = operand.descriptor,
        .value = value,
    };
}

/// EVERY SLOT IS ITS OWN. The register file follows the descriptor of what the
/// SLOT carries, which for a record component is the field's and not the
/// aggregate's. This loop no longer walks a semantic array in physical order,
/// so there is nothing left for a slot count to be wrong about.
fn stageCheckedScalarOperands(ctx: *LowerCtx, slots: []const StagedSlot) Error!void {
    var gp: u32 = 0;
    var fp: u32 = 0;
    for (slots) |slot| {
        if (slot.descriptor == .f64) {
            if (fp >= 8) return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-abi");
            try ctx.emit(.{ .op = .fp_mov_arg, .result = fp, .lhs = slot.value });
            fp += 1;
        } else {
            if (gp >= max_direct_scalar_args) return invalidGraphFacts(ctx.diagnostic, @src(), "application-operand-abi");
            try ctx.emit(.{ .op = .mov_arg, .result = gp, .lhs = slot.value });
            gp += 1;
        }
    }
}

/// Realize an ordered graph result pack directly in ABI result registers.
/// `demanded` is a prefix because binding adjustment preserves Lua/Idol pack
/// order; undemanded members retain their ABI positions but gain no DNIR temp.
fn lowerCheckedPackCall(
    ctx: *LowerCtx,
    application: *const semantic_graph.ApplicationFact,
    demanded: usize,
    out_temps: *[max_reg_record_fields]?u32,
) Error!void {
    bindOccurrence(ctx.diagnostic, ctx.graph, application.application);
    const results = ctx.graph.applicationResults(application.application) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "application-result-pack");
    if (results.len <= 1 or results.len > max_reg_record_fields or demanded > results.len) {
        return invalidGraphFacts(ctx.diagnostic, @src(), "application-result-abi");
    }
    const target = try applicationTarget(ctx, application);
    const relation = try applicationRelation(ctx, application);
    const callee = try linkageForTarget(ctx, target);
    try ensureTargetExtern(ctx, target, callee);

    var operand_storage: [max_direct_scalar_args]CheckedScalarOperand = undefined;
    const operands = try checkedScalarOperands(ctx, application, &operand_storage, true);
    var slot_storage: [max_direct_scalar_args]StagedSlot = undefined;
    const slots = try evaluateCheckedScalarOperands(ctx, application, operands, &slot_storage);
    const first_ty = try checkedGpPackResultType(ctx, results[0]);
    // THE FAST PATH WANTS ONE SLOT THAT REALIZES ITS OPERAND ENTIRE, and now it
    // asks for exactly that. `operands.len == 1 and staged.count == 1` stood
    // here: two counts from two different spaces, agreeing by arithmetic about a
    // correspondence neither of them carried. `projection.len == 0` is the fact
    // itself — a one-field record also yields one slot, but that slot is a
    // PROJECTION of the operand and its record has no value of its own to hand
    // to `call_direct.lhs`.
    const direct_gp = slots.len == 1 and slots[0].projection.len == 0 and
        slots[0].operand.descriptor == .i64 and first_ty == .i64 and
        checkedOperandAdmitsDirectGp(ctx, slots[0].operand.expression);
    const realization_start: u32 = @intCast(ctx.instrs.items.len);
    if (!direct_gp) try stageCheckedScalarOperands(ctx, slots);

    const projected = try ctx.alloc.alloc(dnir.PackResult, results.len);
    errdefer ctx.alloc.free(projected);
    @memset(out_temps, null);
    for (results, 0..) |value, i| {
        const descriptor = try checkedGpPackResultType(ctx, value);
        const temp = if (i < demanded) ctx.freshTemp() else null;
        out_temps[i] = temp;
        projected[i] = .{ .value = value, .temp = temp, .ty = descriptor };
    }
    try ctx.emit(.{
        .op = .call_direct,
        .relation = relation,
        .application = application.application,
        // `value` remains the first member for the compact lineage row. The
        // application id names the authoritative entire result pack, and
        // `pack_results` proves every ordered member against it.
        .value = results[0],
        .subject = ctx.graph.applicationSubject(application.application),
        .target = target,
        .realization_start = realization_start,
        .callee = callee,
        .lhs = if (direct_gp) slots[0].value else .void,
        .ty = try publishedDescriptor(ctx, application),
        .pack_results = projected,
    });
}

/// Realize one checked scalar application. Source call orientation has already
/// disappeared: relation, subject role, ordered operands, result and occurrence
/// all come from the graph. Physical linkage resolves from the target entity id
/// through the module linkage map — never from relation node names here.
fn lowerCheckedScalarCall(
    ctx: *LowerCtx,
    application: *const semantic_graph.ApplicationFact,
    consumption: types.ReturnConsumption,
) Error!dnir.Value {
    const result_members = ctx.graph.applicationResults(application.application) orelse
        return invalidGraphFacts(ctx.diagnostic, @src(), "application-result-pack");
    const graph_consumption = try checkedApplicationConsumption(
        ctx,
        application,
        result_members,
        consumption,
    );
    if (result_members.len > 1) {
        var temps: [max_reg_record_fields]?u32 = @splat(null);
        const demanded: usize = if (consumption == .discard) 0 else if (consumption == .single) 1 else return invalidGraphFacts(ctx.diagnostic, @src(), "application-result-consumption");
        try lowerCheckedPackCall(ctx, application, demanded, &temps);
        return if (temps[0]) |temp| .{ .temp = temp } else .void;
    }
    bindOccurrence(ctx.diagnostic, ctx.graph, application.application);
    const relation = try applicationRelation(ctx, application);
    const target = try applicationTarget(ctx, application);
    const callee = try linkageForTarget(ctx, target);
    // A CROSS-HOME CALL IS A RELOCATION, NOT A BRANCH. Nothing in this module
    // defines the symbol, so `patchCalls` would find it neither among the
    // defined symbols nor among the externs and report DNB007 `undefined
    // symbol` — the correct observation with no way to act on it. Registering
    // the extern here is the only place that knows the target is foreign.
    try ensureTargetExtern(ctx, target, callee);
    const descriptor = try publishedDescriptor(ctx, application);
    if (try checkedRecordForApplication(ctx, application)) |record| {
        return try lowerCheckedRecordCall(ctx, application, record, graph_consumption);
    }
    try checkedScalarResult(ctx.diagnostic, descriptor);

    var operand_storage: [max_direct_scalar_args]CheckedScalarOperand = undefined;
    const operands = try checkedScalarOperands(ctx, application, &operand_storage, true);
    var slot_storage: [max_direct_scalar_args]StagedSlot = undefined;
    const slots = try evaluateCheckedScalarOperands(ctx, application, operands, &slot_storage);
    const realization_start: u32 = @intCast(ctx.instrs.items.len);
    // Admit only the fixed-width integer contract with byte-equivalence proof.
    // Other general-register descriptors remain staged until their result and
    // operand laws have the same focused control.
    //
    // ONE SLOT, AND THAT SLOT REALIZES ITS OPERAND ENTIRE. The fast path hands
    // a single value straight to `call_direct.lhs` and skips staging, so it
    // needs a slot that IS its operand — not merely a slot count that happens
    // to equal one. A one-field record also stages one slot, and that slot is a
    // projection whose record has no value of its own to hand over.
    const direct_gp = slots.len == 1 and
        slots[0].projection.len == 0 and
        slots[0].operand.descriptor == .i64 and
        descriptor == .i64 and
        checkedOperandAdmitsDirectGp(ctx, slots[0].operand.expression);
    // A record operand is STAGED AS ITS FIELDS by `evaluateCheckedScalarOperands`
    // above, which refuses by name anything it could not expand. The loop that
    // stood here refused EVERY record equally — including the ones the argument
    // registers already hold perfectly well, and which the unchecked path had
    // been passing that way all along.
    //
    // A scalar local passed as an operand (`word(before)` where `before` is a
    // body binding) is safe for the same reason a record field is: any body
    // containing a call spills all GP locals to the stack frame
    // (`planGpStackLocals`, gate_spill_all_locals = body_has_call), so the
    // operand load/reload survives the call's caller-saved clobber.
    if (!direct_gp) try stageCheckedScalarOperands(ctx, slots);
    const has_result = graph_consumption != .discard and descriptor != .void;
    const result = if (has_result) ctx.freshTemp() else null;
    const value = try checkedApplicationResult(ctx, application);
    try ctx.emit(.{
        .op = .call_direct,
        .relation = relation,
        .application = application.application,
        .value = value,
        .subject = ctx.graph.applicationSubject(application.application),
        .target = target,
        .realization_start = realization_start,
        .result = result,
        .callee = callee,
        .lhs = if (direct_gp) slots[0].value else .void,
        .ty = descriptor,
    });
    return if (result) |temp| .{ .temp = temp } else .void;
}

/// `os.args` — the root-projected argument table, not a call.
fn argv(expr: *const ast.Expr) bool {
    if (expr.* != .field) return false;
    const f = expr.field;
    return f.obj.* == .name and
        std.mem.eql(u8, f.obj.name.ident, "os") and
        std.mem.eql(u8, f.field, "args");
}

/// The `os` world's member edge an anchored node names, or null.
///
/// THE ROSTER IS ASKED, NOT RESTATED — the same shape `isCMember` already uses
/// for the `c` world's roster in this file. Which extern a member lowers to is
/// this file's business; what the member RESULTS IN is the world's, and it is
/// declared in `subject_home.os_dot_members`, which `codegen.expr_type` reads
/// for the very same row. A literal `.str` here and a literal `.str` there
/// would be two authorities on one fact — and they were, and they disagreed:
/// this file gave `arg(i)` `.ty = .str` while the type side answered `any`, so
/// `arg(1):len()` could not resolve a receiver whose realization was already
/// text.
fn osMemberOf(expr: *const ast.Expr) ?subject_home.OsMember {
    if (expr.* != .field) return null;
    const f = expr.field;
    if (f.obj.* != .name) return null;
    if (!std.mem.eql(u8, f.obj.name.ident, "os")) return null;
    return subject_home.osDotMember(f.field);
}

/// The declared result of an `os` member edge, by name. `.any` where the roster
/// declares nothing, which is the honest answer and not a claim.
fn osResult(name: []const u8) RT {
    const m = subject_home.osDotMember(name) orelse return .any;
    return m.result;
}

/// `os.env` — the root-projected environment table, not `getenv` / `os.env()`.
fn env(expr: *const ast.Expr) bool {
    if (expr.* != .field) return false;
    const f = expr.field;
    return f.obj.* == .name and
        std.mem.eql(u8, f.obj.name.ident, "os") and
        std.mem.eql(u8, f.field, "env");
}

/// The KEY of an environment projection used as an assignment TARGET, or null.
///
/// The environment is a PLACE, not only a value, so `env(k)` has to be writable
/// as well as readable. All three spellings that name the same edge reach here:
///
///     env("K")     = v     application of the `env` relation; `os` is injected,
///                          so the anchor adds nothing (only reachable once sema
///                          admits bare `env`)
///     os.env("K")  = v     lawful where the anchor genuinely disambiguates
///     os.env["K"]  = v     computed projection of the `os.env` pack
///
/// A LOCAL named `env` or `os` shadows the projection. That guard is not
/// hypothetical: legacy sources written under the retired ruling that `a[i]`
/// canonicalizes to `a(i)` spell a positional-table store as `env(k) = v` too,
/// and without the check such a local table store would be silently rewritten
/// into a `setenv` call. Under the current law `[]` is computed projection and
/// `()` is ordinary application, so the `.call` arm below is the RELATION face
/// and the `.index` arm is the PACK face; neither is a canonicalization of the
/// other.
fn envPlaceKey(ctx: *const LowerCtx, expr: *const ast.Expr) ?*const ast.Expr {
    switch (expr.*) {
        .index => |ix| {
            if (!env(ix.obj)) return null;
            if (ctx.locals.contains("os")) return null;
            return ix.key;
        },
        .call => |c| {
            if (c.args.len != 1) return null;
            if (env(c.func)) return if (ctx.locals.contains("os")) null else c.args[0];
            if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "env")) {
                return if (ctx.locals.contains("env")) null else c.args[0];
            }
            return null;
        },
        else => return null,
    }
}

/// `env(k) = v` — POSIX `setenv(k, v, 1)`.
///
/// `setenv` and not `putenv`: `putenv` takes one `"K=V"` string, which would
/// mean building and OWNING a concatenation at run time, and it installs the
/// caller's buffer rather than copying it.
///
/// The overwrite flag is 1, so a write always takes effect. Nothing here treats
/// the empty string specially — `env("K") = ""` sets `K` to the empty value and
/// does NOT remove it. That matters: the READ side currently cannot distinguish
/// absent from empty (both answer `""`, the §17 fake-nil identity written up in
/// idol-native/docs/env-identity.md), and if the write side collapsed the two as
/// well, the distinction would be unrecoverable rather than merely unobservable.
/// REMOVAL is `unsetenv`, a different edge, and is deliberately not spelled as
/// an assignment of `""` here.
fn lowerEnvStore(ctx: *LowerCtx, key_expr: *const ast.Expr, value: *const ast.Expr) Error!void {
    const k = try lowerExprCons(ctx, key_expr, .single);
    const v = try lowerExprCons(ctx, value, .single);
    try ensureExtern(ctx, "os", "setenv", "setenv");
    try ctx.emit(.{ .op = .mov_arg, .result = 0, .lhs = k });
    try ctx.emit(.{ .op = .mov_arg, .result = 1, .lhs = v });
    try ctx.emit(.{ .op = .mov_arg, .result = 2, .lhs = .{ .i64 = 1 } });
    try ctx.emit(.{ .op = .call_extern, .callee = "setenv", .ty = .i64 });
}

/// `env:remove(k)` — POSIX `unsetenv(k)`. THE REMOVAL EDGE.
///
/// `lowerEnvStore` above states that removal is `unsetenv`, "a different edge,
/// and is deliberately not spelled as an assignment". It had nowhere to point;
/// this is where. The distinction is observable and not stylistic:
///
///     env("K") = ""        K is PRESENT and empty      setenv(K, "", 1)
///     env:remove("K")      K is ABSENT                 unsetenv(K)
///
/// Collapsing them onto `env("K") = nil` would destroy the one distinction the
/// read face already cannot express (the §17 fake-nil identity written up in
/// idol-native/docs/env-identity.md), so the assignment spelling is REFUSED in
/// sema and names this edge in its diagnostic rather than being lowered here.
///
/// `unsetenv` returns int and the result is discarded, exactly as the `setenv`
/// store's is: a store is a statement, not a value.
fn lowerEnvRemove(ctx: *LowerCtx, key_expr: *const ast.Expr) Error!dnir.Value {
    const k = try lowerExprCons(ctx, key_expr, .single);
    try ensureExtern(ctx, "os", "unsetenv", "unsetenv");
    try ctx.emit(.{ .op = .mov_arg, .result = 0, .lhs = k });
    try ctx.emit(.{ .op = .call_extern, .callee = "unsetenv", .ty = .i64 });
    return .void;
}

/// `os.cwd` — the root-projected working directory, not `getcwd` / `os.cwd()`.
fn cwd(expr: *const ast.Expr) bool {
    if (expr.* != .field) return false;
    const f = expr.field;
    return f.obj.* == .name and
        std.mem.eql(u8, f.obj.name.ident, "os") and
        std.mem.eql(u8, f.field, "cwd");
}

fn lowerStdinRead(
    ctx: *LowerCtx,
    consumption: types.ReturnConsumption,
) Error!dnir.Value {
    _ = consumption;
    try ensureExtern(ctx, "stdin", "read", "idol_io_read_stdin");
    const t = ctx.freshTemp();
    try ctx.emit(.{ .op = .call_extern, .result = t, .callee = "idol_io_read_stdin", .ty = .str });
    return .{ .temp = t };
}

/// `stdin:line()` — one newline-delimited message for a persistent server loop.
/// End of input is the empty string, not a null sentinel (GAP-155).
fn lowerStdinLine(
    ctx: *LowerCtx,
    consumption: types.ReturnConsumption,
) Error!dnir.Value {
    _ = consumption;
    try ensureExtern(ctx, "stdin", "line", "idol_io_read_line");
    const t = ctx.freshTemp();
    try ctx.emit(.{ .op = .call_extern, .result = t, .callee = "idol_io_read_line", .ty = .str });
    return .{ .temp = t };
}

fn lowerSubjectRead(
    ctx: *LowerCtx,
    expr: *const Expr,
    consumption: types.ReturnConsumption,
) Error!dnir.Value {
    _ = consumption;
    const subject = try lowerExpr(ctx, expr.method_call.obj);
    try ensureExtern(ctx, "idol", "read", "idol_io_read_path");
    try ctx.emit(.{ .op = .mov_arg, .result = 0, .lhs = subject });
    const t = ctx.freshTemp();
    try ctx.emit(.{ .op = .call_extern, .result = t, .callee = "idol_io_read_path", .ty = .str });
    return .{ .temp = t };
}

/// Subject-first `hay:has(needle)` — lowers the held subject and needle directly
/// to a bootstrap extern. No `string.*`, `std.*`, or operation-first rewrite.
fn lowerSubjectHas(
    ctx: *LowerCtx,
    expr: *const Expr,
    consumption: types.ReturnConsumption,
) Error!dnir.Value {
    const mc = expr.method_call;
    if (mc.args.len != 1) return bail(ctx.diagnostic, @src());
    const hay = try lowerExpr(ctx, mc.obj);
    const needle = try lowerExpr(ctx, mc.args[0]);
    try ensureExtern(ctx, "idol", "has", "idol_str_has");
    try ctx.emit(.{ .op = .mov_arg, .result = 0, .lhs = hay });
    try ctx.emit(.{ .op = .mov_arg, .result = 1, .lhs = needle });
    if (consumption == .discard) {
        try ctx.emit(.{ .op = .call_extern, .callee = "idol_str_has", .ty = .i64 });
        return .void;
    }
    const t = ctx.freshTemp();
    try ctx.emit(.{ .op = .call_extern, .result = t, .callee = "idol_str_has", .ty = .i64 });
    return .{ .temp = t };
}

fn lowerSubjectFind(
    ctx: *LowerCtx,
    expr: *const Expr,
    consumption: types.ReturnConsumption,
) Error!dnir.Value {
    const mc = expr.method_call;
    if (mc.args.len != 3) return bail(ctx.diagnostic, @src());
    const hay = try lowerExpr(ctx, mc.obj);
    const needle = try lowerExpr(ctx, mc.args[0]);
    const start = try lowerExpr(ctx, mc.args[1]);
    const plain = try lowerExpr(ctx, mc.args[2]);
    try ensureExtern(ctx, "idol", "find", "idol_str_find");
    try ctx.emit(.{ .op = .mov_arg, .result = 0, .lhs = hay });
    try ctx.emit(.{ .op = .mov_arg, .result = 1, .lhs = needle });
    try ctx.emit(.{ .op = .mov_arg, .result = 2, .lhs = start });
    try ctx.emit(.{ .op = .mov_arg, .result = 3, .lhs = plain });
    if (consumption == .discard) {
        try ctx.emit(.{ .op = .call_extern, .callee = "idol_str_find", .ty = .i64 });
        return .void;
    }
    const t = ctx.freshTemp();
    try ctx.emit(.{ .op = .call_extern, .result = t, .callee = "idol_str_find", .ty = .i64 });
    return .{ .temp = t };
}

/// `s:rep(n)` — string repeat, lowercase-n variant. Returns a HEAP-OWNED
/// buffer of `s` repeated `n` times. Mirrors `duo_str_rep`'s C ABI
/// (`char *rep(const char *s, int64_t n)`); the emission here is the
/// direct backend's lowered shape; the runtime shim ships `duo_str_rep`.
fn lowerSubjectRep(
    ctx: *LowerCtx,
    expr: *const Expr,
    consumption: types.ReturnConsumption,
) Error!dnir.Value {
    const mc = expr.method_call;
    if (mc.args.len != 1) return bail(ctx.diagnostic, @src());
    const subject = try lowerExpr(ctx, mc.obj);
    const n = try lowerExpr(ctx, mc.args[0]);
    try ensureExtern(ctx, "str", "rep", "duo_str_rep");
    try ctx.emit(.{ .op = .mov_arg, .result = 0, .lhs = subject });
    try ctx.emit(.{ .op = .mov_arg, .result = 1, .lhs = n });
    if (consumption == .discard) {
        try ctx.emit(.{ .op = .call_extern, .callee = "duo_str_rep", .ty = .str });
        return .void;
    }
    const t = ctx.freshTemp();
    try ctx.emit(.{ .op = .call_extern, .result = t, .callee = "duo_str_rep", .ty = .str });
    try ctx.str_slots.put(ctx.alloc, t, {});
    return .{ .temp = t };
}

fn lowerSubjectTail(
    ctx: *LowerCtx,
    expr: *const Expr,
    consumption: types.ReturnConsumption,
) Error!dnir.Value {
    const subject = try lowerExpr(ctx, expr.method_call.obj);
    if (consumption == .discard) {
        try ctx.emit(.{ .op = .call_direct, .callee = "tail", .lhs = subject });
        return .void;
    }
    const t = ctx.freshTemp();
    try ctx.emit(.{ .op = .call_direct, .result = t, .callee = "tail", .lhs = subject });
    return .{ .temp = t };
}

/// COLLECTION-RELATION-ONE — realize `xs:any(p)` as ONE iteration application.
///
/// Answers null when `expr` is not a collection application, so every existing
/// path below is untouched.
///
/// THE QUESTION REACHES REALIZATION INTACT, which is the whole point of having
/// separate relation words (`subject-section-one.md` §4). `any` is EXISTENTIAL,
/// so the emitted shape leaves at the FIRST WITNESS and the elements after it
/// are never examined. An `any` built as `filter` then a non-empty test would
/// answer the same and be a different program.
///
/// THREE REALIZATIONS, ONE QUESTION, chosen from facts already in hand and
/// none of them an iterator:
///
///   extent 0            no iteration at all — the answer is `false`, and the
///                       emitted form is a constant. `protocol-projection-one.md`
///                       §3's "or **nothing**".
///   register-exploded   a SHORT-CIRCUIT CHAIN over the element slots. No loop,
///                       no induction variable, no bounds check, no memory
///                       traffic — the elements are already in slots, so asking
///                       the question costs one predicate and one branch each
///                       until one answers yes.
///   memory-backed       an indexed scan whose body branches OUT of the loop on
///                       the first witness. The early exit is emitted from the
///                       QUESTION; nothing has to rediscover it from a flag.
///
/// Iterator object 0, protocol object 0, vtable 0, indirect dispatch 0,
/// closure 0 — §6's pins, and they hold BY CONSTRUCTION here rather than by
/// later elimination: the body relation is an expression lowered in place with
/// its one result name bound to the element, and no value is ever built for it.
fn lowerCollectionRelation(ctx: *LowerCtx, expr: *const Expr) Error!?dnir.Value {
    const shape = collection_relation.shapeOf(expr) orelse return null;
    // IT NEVER TAKES THE NAME. If the graph resolved this application to a
    // relation, the program declared its own `any` and that declaration owns
    // every call to it — the same rule `worldSubject` follows for `stdout` and
    // `table_apply` follows for `arg`. Both were defects first: a user relation
    // named `arg` silently became an argument read and answered 0 instead of
    // 42, with no diagnostic anywhere. Sema declines the same case for the same
    // reason, and this is the half that matters, because here the wrong answer
    // would COMPILE.
    if (ctx.occurrences.get(expr)) |occurrence| {
        if (ctx.graph.applicationRelation(occurrence.application) != null) return null;
    }
    return switch (shape.question) {
        .any => try lowerAnyRelation(ctx, shape),
    };
}

/// Bind the body relation's single result name to `slot` for the duration of
/// one predicate lowering, and give the name back exactly as it was found.
///
/// A SHADOW, NOT A SCOPE. `subject-section-one.md` §1 requires the body
/// relation to create "no lexical binding, no scope mutation, no implicit
/// identifier" — so an outer `x` must still be an outer `x` after the
/// application, and the check that proves it is `gate/any.id`'s shadow row.
const ResultName = struct {
    ctx: *LowerCtx,
    name: []const u8,
    /// What the name meant OUTSIDE, so it can mean that again afterwards.
    previous: ?u32,
    shadowed_slot: bool = false,
    shadowed_literal: bool = false,

    fn bind(ctx: *LowerCtx, name: []const u8) ResultName {
        return .{ .ctx = ctx, .name = name, .previous = ctx.locals.get(name) };
    }

    /// The element lives in a slot — the loaded or exploded realizations.
    ///
    /// `put` on a key already present keeps the stored key and replaces only
    /// the value, so re-pointing the name at the next element allocates
    /// nothing after the first.
    fn point(self: *ResultName, slot: u32) Error!void {
        if (self.shadowed_slot or self.previous != null) {
            try self.ctx.locals.put(self.ctx.alloc, self.name, slot);
        } else {
            try self.ctx.locals.put(self.ctx.alloc, try self.ctx.alloc.dupe(u8, self.name), slot);
        }
        self.shadowed_slot = true;
    }

    /// The element IS a literal — the determined realization, where the folder
    /// must see an immediate rather than a slot that happens to hold one.
    fn pointLiteral(self: *ResultName, element: i64) Error!void {
        if (self.shadowed_literal) {
            try self.ctx.fused_literals.put(self.ctx.alloc, self.name, element);
        } else {
            try self.ctx.fused_literals.put(self.ctx.alloc, try self.ctx.alloc.dupe(u8, self.name), element);
        }
        self.shadowed_literal = true;
    }

    fn release(self: *ResultName) void {
        if (self.shadowed_literal) {
            if (self.ctx.fused_literals.fetchRemove(self.name)) |entry| self.ctx.alloc.free(entry.key);
            self.shadowed_literal = false;
        }
        if (!self.shadowed_slot) return;
        self.shadowed_slot = false;
        if (self.previous) |slot| {
            self.ctx.locals.put(self.ctx.alloc, self.name, slot) catch {};
            return;
        }
        if (self.ctx.locals.fetchRemove(self.name)) |entry| self.ctx.alloc.free(entry.key);
    }
};

/// EXTENT ZERO IS A FACT, AND `staticTableLen` CANNOT CARRY IT.
///
/// A zero-element positional literal is not `tableIsPositional` (that predicate
/// requires at least one field), so it binds through the record path and no
/// `<name>.len` slot is ever created — `staticTableLen` then answers null, which
/// is the same null a `ptr` PARAMETER answers, and those two are opposite
/// facts. One means "the extent is zero"; the other means "the extent is not
/// known here". Reading the first as the second refuses a question with a
/// trivial answer; reading the second as the first would answer `false` about a
/// table this function has never seen the size of. So the empty binding is
/// identified from the source that stated it, and nothing else is assumed.
fn boundEmptyTable(ctx: *const LowerCtx, name: []const u8) bool {
    const body = ctx.body orelse return false;
    for (body.stmts) |stmt| {
        switch (stmt) {
            .local_decl => |decl| {
                for (decl.names, 0..) |local, i| {
                    if (!std.mem.eql(u8, local.ident, name)) continue;
                    if (i >= decl.inits.len) return false;
                    const init = decl.inits[i];
                    return init.* == .table and init.table.fields.len == 0;
                }
            },
            else => {},
        }
    }
    return false;
}

/// The body relation, EVALUATED, with its result name standing for `element`.
///
/// Deliberately tiny and deliberately conservative — it answers null for
/// everything it is not certain about, and a null anywhere means the relation
/// is realized as a scan instead. Three exclusions are the interesting ones,
/// and each is a place a second opinion would become a WRONG ANSWER rather than
/// a refusal:
///
///   * `ctx.const_ints` is NOT consulted. Its own doc comment says it records a
///     name's last literal binding and is never invalidated by a later
///     non-literal assignment — fine for a loop step read at the binding, fatal
///     for a predicate read anywhere in a body.
///   * `/`, `//` and `%` are NOT folded. `docs/rulings.md` settles them as
///     FLOORED, the backend inherited truncating behaviour from `msub`, and a
///     folder that picked either would be a second definition of an operator
///     whose first definition is still being repaired.
///   * `and` / `or` are NOT folded. They are value-selecting in the Lua law
///     this language descends from, and `0` is TRUTHY there while this
///     backend's branches treat it as false. That disagreement is a live
///     question, not something to answer inside a folder.
fn foldBodyRelation(ctx: *const LowerCtx, expr: *const ast.Expr, name: []const u8, element: i64) ?i64 {
    const truth = struct {
        fn of(b: bool) i64 {
            return if (b) 1 else 0;
        }
    }.of;
    switch (expr.*) {
        .int_lit => |lit| return lit.val,
        .true_lit => return 1,
        .false_lit => return 0,
        .name => |n| {
            if (std.mem.eql(u8, n.ident, name)) return element;
            if (ctx.module_consts.ints.get(n.ident)) |value| return value;
            return null;
        },
        .unop => |u| {
            const operand = foldBodyRelation(ctx, u.operand, name, element) orelse return null;
            return switch (u.op) {
                .neg => -%operand,
                .not => truth(operand == 0),
                .bnot => ~operand,
                else => null,
            };
        },
        .binop => |b| {
            const lhs = foldBodyRelation(ctx, b.lhs, name, element) orelse return null;
            const rhs = foldBodyRelation(ctx, b.rhs, name, element) orelse return null;
            return switch (b.op) {
                .add => lhs +% rhs,
                .sub => lhs -% rhs,
                .mul => lhs *% rhs,
                .band => lhs & rhs,
                .bor => lhs | rhs,
                .bxor => lhs ^ rhs,
                .eq => truth(lhs == rhs),
                .neq => truth(lhs != rhs),
                .lt => truth(lhs < rhs),
                .gt => truth(lhs > rhs),
                .leq => truth(lhs <= rhs),
                .geq => truth(lhs >= rhs),
                else => null,
            };
        },
        else => return null,
    }
}

fn lowerAnyRelation(ctx: *LowerCtx, shape: collection_relation.Shape) Error!dnir.Value {
    if (shape.subject.* != .name) return bail(ctx.diagnostic, @src());
    const source = shape.subject.name.ident;
    const extent = staticTableLen(ctx, source) orelse
        (if (boundEmptyTable(ctx, source)) @as(i64, 0) else return bail(ctx.diagnostic, @src()));

    // TERMINATION, stated as a fact rather than discovered by running: a known
    // extent bounds the scan, and an extent of zero bounds it at zero. An
    // existential over an EMPTY source is FALSE, and the answer is an immediate
    // — no slot, no scan, no source. `protocol-projection-one.md` §3's last
    // realization, "or **nothing**", reached from the extent alone.
    if (extent <= 0) return .{ .i64 = 0 };

    // DETERMINED SOURCE — every element is a compile-time literal, nothing
    // writes the name and nothing lets it escape (`noteConstTable`'s verdict,
    // not this pass's opinion). Then the question has a compile-time ANSWER
    // whenever the body relation is one this folder is certain of, and the
    // whole iteration is an immediate: no table, no loop, no branch.
    //
    // THIS IS WHAT MAKES THE STRONGER RELATION THE CHEAPER ONE. `xs:any(…)`
    // states existence; the flag-and-scan loop it replaces states "scan and
    // mutate a flag", and the compiler has to rediscover the question from the
    // loop before it can do this. Same answer, and the relation form gets there
    // without the rediscovery.
    const determined: ?[]const i64 = ctx.const_tables.get(source);
    if (determined) |values| {
        var settled = true;
        var witness = false;
        for (values) |element| {
            const verdict = foldBodyRelation(ctx, shape.body, shape.param, element) orelse {
                settled = false;
                break;
            };
            if (verdict != 0) {
                witness = true;
                break;
            }
        }
        if (settled) return .{ .i64 = if (witness) 1 else 0 };
    }

    const answer = ctx.freshTemp();
    try ctx.emit(.{ .op = .store_local, .result = answer, .lhs = .{ .i64 = 0 }, .ty = .i64 });

    var witnesses: std.ArrayListUnmanaged(usize) = .empty;
    defer witnesses.deinit(ctx.alloc);

    var result_name = ResultName.bind(ctx, shape.param);
    defer result_name.release();

    // The source is determined but the body relation is not foldable — a
    // capture, a call, an operator this pass refuses to define. The elements
    // are still literals, so the chain is emitted against IMMEDIATES and the
    // table is never materialized.
    if (determined) |values| {
        for (values) |element| {
            try result_name.pointLiteral(element);
            const verdict = try lowerExpr(ctx, shape.body);
            const rejected = ctx.instrs.items.len;
            try ctx.emit(.{ .op = .br, .lhs = verdict, .branch_target = 0, .branch_condition = .when_false });
            try ctx.emit(.{ .op = .store_local, .result = answer, .lhs = .{ .i64 = 1 }, .ty = .i64 });
            try witnesses.append(ctx.alloc, ctx.instrs.items.len);
            try ctx.emit(.{ .op = .br, .branch_target = 0 });
            ctx.instrs.items[rejected].branch_target = @intCast(ctx.instrs.items.len);
        }
        const done: u32 = @intCast(ctx.instrs.items.len);
        for (witnesses.items) |index| ctx.instrs.items[index].branch_target = done;
        return .{ .local = answer };
    }

    if (ptrSlotOf(ctx, shape.subject)) |base| {
        // MEMORY-BACKED: one scan, one scaled load per step, and a branch out
        // of the loop the moment the predicate answers yes. The index is this
        // pass's own induction variable and is in range by construction, so no
        // bounds guard is emitted — `guardedTableIndex` exists for indexes the
        // SOURCE supplies, and this one has no source.
        const step = ctx.freshTemp();
        try ctx.emit(.{ .op = .store_local, .result = step, .lhs = .{ .i64 = 1 }, .ty = .i64 });

        const head: u32 = @intCast(ctx.instrs.items.len);
        const in_range = ctx.freshTemp();
        try ctx.emit(.{
            .op = .binop,
            .result = in_range,
            .binop = .leq,
            .lhs = .{ .local = step },
            .rhs = .{ .i64 = extent },
        });
        const exhausted = ctx.instrs.items.len;
        try ctx.emit(.{ .op = .br, .lhs = .{ .temp = in_range }, .branch_target = 0, .branch_condition = .when_false });

        const loaded = ctx.freshTemp();
        try ctx.emit(.{
            .op = .load_index,
            .ty = .i64,
            .result = loaded,
            .lhs = .{ .local = base },
            .rhs = .{ .local = step },
        });
        const element = ctx.freshTemp();
        try ctx.emit(.{ .op = .store_local, .result = element, .lhs = .{ .temp = loaded }, .ty = .i64 });
        try result_name.point(element);

        const verdict = try lowerExpr(ctx, shape.body);
        const rejected = ctx.instrs.items.len;
        try ctx.emit(.{ .op = .br, .lhs = verdict, .branch_target = 0, .branch_condition = .when_false });
        try ctx.emit(.{ .op = .store_local, .result = answer, .lhs = .{ .i64 = 1 }, .ty = .i64 });
        try witnesses.append(ctx.alloc, ctx.instrs.items.len);
        try ctx.emit(.{ .op = .br, .branch_target = 0 });

        ctx.instrs.items[rejected].branch_target = @intCast(ctx.instrs.items.len);
        const next = ctx.freshTemp();
        try ctx.emit(.{
            .op = .binop,
            .result = next,
            .binop = .add,
            .lhs = .{ .local = step },
            .rhs = .{ .i64 = 1 },
        });
        try ctx.emit(.{ .op = .store_local, .result = step, .lhs = .{ .temp = next }, .ty = .i64 });
        try ctx.emit(.{ .op = .br, .branch_target = head });

        const done: u32 = @intCast(ctx.instrs.items.len);
        ctx.instrs.items[exhausted].branch_target = done;
        for (witnesses.items) |index| ctx.instrs.items[index].branch_target = done;
        return .{ .local = answer };
    }

    // REGISTER-EXPLODED: the elements are already in slots, so there is nothing
    // to load and nothing to index. The chain short-circuits, which is the same
    // early exit the loop above emits, reached without a loop existing.
    if (extent > select_chain_max) return bail(ctx.diagnostic, @src());
    var index: i64 = 1;
    while (index <= extent) : (index += 1) {
        const element_key = try std.fmt.allocPrint(ctx.alloc, "{s}.{d}", .{ source, index });
        defer ctx.alloc.free(element_key);
        const element = ctx.locals.get(element_key) orelse return bail(ctx.diagnostic, @src());
        try result_name.point(element);

        const verdict = try lowerExpr(ctx, shape.body);
        const rejected = ctx.instrs.items.len;
        try ctx.emit(.{ .op = .br, .lhs = verdict, .branch_target = 0, .branch_condition = .when_false });
        try ctx.emit(.{ .op = .store_local, .result = answer, .lhs = .{ .i64 = 1 }, .ty = .i64 });
        try witnesses.append(ctx.alloc, ctx.instrs.items.len);
        try ctx.emit(.{ .op = .br, .branch_target = 0 });
        ctx.instrs.items[rejected].branch_target = @intCast(ctx.instrs.items.len);
    }
    const done: u32 = @intCast(ctx.instrs.items.len);
    for (witnesses.items) |i| ctx.instrs.items[i].branch_target = done;
    return .{ .local = answer };
}

fn lowerSubjectCall(
    ctx: *LowerCtx,
    expr: *const Expr,
    consumption: types.ReturnConsumption,
) Error!dnir.Value {
    if (try lowerCollectionRelation(ctx, expr)) |value| return value;
    // The test world's relations become a real trap rather than a call into a
    // module that does not exist at runtime. Gated on the SUBJECT being `test`,
    // so a user relation named `assert` on any other subject is untouched.
    if (expr.* == .method_call and expr.method_call.obj.* == .name and
        std.mem.eql(u8, expr.method_call.obj.name.ident, "test"))
    {
        if (try lowerTestRelation(ctx, expr.method_call.method, expr.method_call.args)) |v| return v;
    }
    // THE ENVIRONMENT'S REMOVAL EDGE, asked before the graph-fact path for the
    // same reason the test world's relations are: it is a WORLD projection, not
    // an application of a relation the graph can see. `table_apply` has already
    // converged `env:remove(k)` onto the anchored subject `os.env`, so exactly
    // one shape arrives here — and the bare face reaches this only where the
    // program does not bind `env`, which that pass decides.
    if (expr.* == .method_call and env(expr.method_call.obj) and
        std.mem.eql(u8, expr.method_call.method, "remove") and
        expr.method_call.args.len == 1 and !ctx.locals.contains("os"))
    {
        return lowerEnvRemove(ctx, expr.method_call.args[0]);
    }
    if (ctx.occurrences.get(expr)) |application| {
        if (ctx.require_graph_facts and !ctx.graph.isBootstrapApplicationNode(application.application)) {
            if (ctx.graph.applicationSubject(application.application) == null) {
                bindOccurrence(ctx.diagnostic, ctx.graph, application.application);
                return invalidGraphFacts(ctx.diagnostic, @src(), "application-subject");
            }
            // BYPASS: f64:from(x) is a special form, not a checked call.
            const is_from_tn = expr.* == .method_call and std.mem.eql(u8, expr.method_call.method, "from");
            if (!is_from_tn) {
            return lowerCheckedScalarCall(ctx, application, consumption);
            }
        }
    }
    if (expr.* == .method_call) {
        const mc = expr.method_call;
        if (try tryLowerSubjectRelationEdgeCall(ctx, expr, consumption)) |value| return value;
        if (mc.obj.* == .name and std.mem.eql(u8, mc.obj.name.ident, "stdin") and
            std.mem.eql(u8, mc.method, "read") and mc.args.len == 0)
        {
            return lowerStdinRead(ctx, consumption);
        }
        if (mc.obj.* == .name and std.mem.eql(u8, mc.obj.name.ident, "stdin") and
            std.mem.eql(u8, mc.method, "line") and mc.args.len == 0)
        {
            return lowerStdinLine(ctx, consumption);
        }
        if (mc.obj.* == .name and std.mem.eql(u8, mc.obj.name.ident, "stdout") and
            std.mem.eql(u8, mc.method, "write") and mc.args.len == 1)
        {
            return lowerWrite(ctx, mc.args);
        }
        if (subject_home.streamRelation(mc.method)) {
            const is_stdout = mc.obj.* == .name and std.mem.eql(u8, mc.obj.name.ident, "stdout");
            if (stdioProjectedStream(ctx, mc.obj) != null and
                !(std.mem.eql(u8, mc.method, "write") and mc.args.len == 1))
            {
                return bail(ctx.diagnostic, @src());
            }
            if (std.mem.eql(u8, mc.method, "write") and mc.args.len == 1 and !is_stdout) {
                return lowerStreamWrite(ctx, mc.obj, mc.args[0]);
            }
            if (std.mem.eql(u8, mc.method, "close") and mc.args.len == 0) {
                return lowerStreamClose(ctx, mc.obj);
            }
        }
        if (std.mem.eql(u8, mc.method, "read") and mc.args.len == 0 and exprIsStr(ctx, mc.obj)) {
            return lowerSubjectRead(ctx, expr, consumption);
        }
        if (!ctx.require_graph_facts and mc.args.len == 1) {
            if (ctx.relation_edges.get(mc.method)) |sym| {
                const args = [_]*ast.Expr{ mc.obj, mc.args[0] };
                return try lowerNamedDirectCall(ctx, sym, &args, consumption);
            }
        }
        if (std.mem.eql(u8, mc.method, "len") and mc.args.len == 0) {
            // A positional table's length is its tracked descriptor, not a
            // string scan. `t:len()` where `t` is a table answers the element
            // count; routing it through `str_len` was a descriptor loss.
            if (mc.obj.* == .name and nameIsPositionalTable(ctx, mc.obj.name.ident)) {
                const len_key = try std.fmt.allocPrint(ctx.alloc, "{s}.len", .{mc.obj.name.ident});
                defer ctx.alloc.free(len_key);
                if (ctx.locals.get(len_key)) |len_slot| {
                    if (ctx.table_lens.get(len_slot)) |n| {
                        if (consumption == .discard) return .void;
                        return .{ .i64 = n };
                    }
                }
            }
            // THE LENGTH IS CARRIED WHEN THE PROGRAM ALREADY DETERMINES IT.
            // `str_len` is a scan to the first NUL in both realizations, so a
            // determined value must never reach it: `"a\0b":len()` answered 1
            // on direct and 1 on Wasm — agreement, and both wrong.
            if (determinedTextLen(ctx, mc.obj)) |n| {
                if (consumption == .discard) return .void;
                return .{ .i64 = n };
            }
            const base = try lowerExpr(ctx, mc.obj);
            if (consumption == .discard) {
                try ctx.emit(.{ .op = .str_len, .lhs = base });
                return .void;
            }
            const t = ctx.freshTemp();
            try ctx.emit(.{ .op = .str_len, .result = t, .lhs = base });
            return .{ .temp = t };
        }
        if (std.mem.eql(u8, mc.method, "has") and mc.args.len == 1) {
            return lowerSubjectHas(ctx, expr, consumption);
        }
        if (std.mem.eql(u8, mc.method, "find") and mc.args.len == 3) {
            return lowerSubjectFind(ctx, expr, consumption);
        }
        if (std.mem.eql(u8, mc.method, "rep") and mc.args.len == 1 and exprIsStr(ctx, mc.obj)) {
            return lowerSubjectRep(ctx, expr, consumption);
        }
        if (std.mem.eql(u8, mc.method, "tail") and mc.args.len == 0 and exprIsStr(ctx, mc.obj)) {
            // IT NEVER TAKES THE NAME — the rule `lowerCollectionRelation`
            // follows for `any` and `worldSubject` for `stdout`: if the graph
            // resolved this application to a declared relation, that
            // declaration owns the call. Measured on gate/idiom.id: its own
            // `tail` relation was stolen here by the builtin's bare
            // `call_direct "tail"` — no lineage, and the callee would collide
            // with the module's mangled symbol at link. The declared case
            // takes the checked call with the ORIGINAL occurrence, because the
            // generic fall-through synthesizes a fresh expr the occurrence map
            // has never seen.
            if (ctx.occurrences.get(expr)) |occurrence| {
                if (ctx.graph.applicationRelation(occurrence.application) != null) {
                    return lowerCheckedScalarCall(ctx, occurrence, consumption);
                }
            }
            return lowerSubjectTail(ctx, expr, consumption);
        }
        if (std.mem.eql(u8, mc.method, "to") and mc.args.len == 1) {
            if (mc.args[0].* == .name) {
                const target = mc.args[0].name.ident;
                if (std.mem.eql(u8, target, "f64") or std.mem.eql(u8, target, "i64")) {
                    if (exprIsIntegral(ctx, mc.obj) or exprIsF64(ctx, mc.obj)) {
                        return lowerNumericConvert(ctx, mc.obj, target, consumption);
                    }
                }
            }
        }
        if (std.mem.eql(u8, mc.method, "from") and mc.args.len == 1) {
            if (mc.obj.* == .name) {
                const target = mc.obj.name.ident;
                if (std.mem.eql(u8, target, "f64") or std.mem.eql(u8, target, "i64")) {
                    return lowerNumericConvert(ctx, mc.args[0], target, consumption);
                }
            }
        }
        if (std.mem.eql(u8, mc.method, "to") and mc.args.len == 1 and ctx.graph.bootstrapApplicationExpr(expr)) {
            return lowerSubjectTo(ctx, mc.obj, mc.args[0], consumption);
        }
        // String descriptor primitives are bootstrap lowering rules, not
        // declared ordinary relations yet. Admit them before graph-fact bail
        // so gate transport can run on direct without Lua/C bridges.
        if (exprIsStr(ctx, mc.obj) or
            (std.mem.eql(u8, mc.method, "sub") and mc.args.len >= 1 and mc.args.len <= 2 and
                exprIsStr(ctx, mc.obj)))
        {
            return lowerCall(ctx, try faceAsCall(ctx, expr), consumption);
        }
        if (ctx.graph.bootstrapApplicationExpr(expr)) {
            return lowerCall(ctx, try faceAsCall(ctx, expr), consumption);
        }
    }
    return refuseMissingApplication(ctx, @src(), expr);
}

/// Whether any part of `expr` involves f64. `exprIsF64` only inspects the node
/// itself; short-circuit lowering needs to know about the whole subtree, since
/// `length2(p) == 25` is an integer-valued comparison over f64 operands.
fn exprTouchesF64(ctx: *LowerCtx, expr: *const ast.Expr) bool {
    if (exprIsF64(ctx, expr)) return true;
    return switch (expr.*) {
        .float_lit => true,
        .binop => |b| exprTouchesF64(ctx, b.lhs) or exprTouchesF64(ctx, b.rhs),
        .unop => |u| exprTouchesF64(ctx, u.operand),
        .call => |c| blk: {
            if (c.func.* == .name and functionResultIs(ctx, c.func.name.ident, .f64)) break :blk true;
            for (c.args) |a| {
                if (exprTouchesF64(ctx, a)) break :blk true;
            }
            break :blk false;
        },
        // Either arm of an expression-if can carry the float, and both are
        // reachable — so the whole expression touches f64 if either does.
        .if_expr => |ie| exprTouchesF64(ctx, ie.cond) or
            exprTouchesF64(ctx, ie.then_expr) or exprTouchesF64(ctx, ie.else_expr),
        else => false,
    };
}

/// `and` / `or` with real short-circuit semantics.
///
/// These had no arm in `lowerBinop`, so every function containing one fell back
/// to the AST backend — which lacks `#s`, `string.byte` and record lowering. A
/// tokenizer's `while i <= n and is_space(string.byte(src, i)) == 1` therefore
/// could never lower natively, and short-circuit is not optional there: without
/// it the guarded `string.byte` reads past the end of the string.
///
/// Both forms funnel through one slot so the result is a single value:
///
///   and:  S = lhs;  if !S goto END;  S = rhs;  END:
///   or:   S = lhs;  if !S goto RHS;  goto END;  RHS: S = rhs;  END:
///
/// `or` uses a false-polarity branch followed by an unconditional branch.
fn lowerShortCircuit(ctx: *LowerCtx, op: ast.BinOp, lhs: *const ast.Expr, rhs: *const ast.Expr) Error!dnir.Value {
    // Integer contexts only. When an operand's subtree touches f64 — an f64
    // kernel call, a float literal, an f64 slot — the AST backend already lowers
    // the whole `cond and a or b` ternary correctly against f64 records, and
    // taking it over here regressed WP-04. Refusing keeps that fallback.
    if (exprTouchesF64(ctx, lhs) or exprTouchesF64(ctx, rhs)) return bail(ctx.diagnostic, @src());

    const slot = ctx.freshTemp();
    try ctx.emit(.{ .op = .store_local, .result = slot, .lhs = try lowerExpr(ctx, lhs), .ty = .any });

    const test_idx = ctx.instrs.items.len;
    try ctx.emit(.{ .op = .br, .lhs = .{ .local = slot }, .branch_target = 0, .branch_condition = .when_false });

    if (op == .@"and") {
        try ctx.emit(.{ .op = .store_local, .result = slot, .lhs = try lowerExpr(ctx, rhs), .ty = .any });
        ctx.instrs.items[test_idx].branch_target = @intCast(ctx.instrs.items.len);
        return .{ .local = slot };
    }

    const skip_idx = ctx.instrs.items.len;
    try ctx.emit(.{ .op = .br, .branch_target = 0 });
    ctx.instrs.items[test_idx].branch_target = @intCast(ctx.instrs.items.len);
    try ctx.emit(.{ .op = .store_local, .result = slot, .lhs = try lowerExpr(ctx, rhs), .ty = .any });
    ctx.instrs.items[skip_idx].branch_target = @intCast(ctx.instrs.items.len);
    return .{ .local = slot };
}

/// `k = if n > 3 10 else 20` — §6's expression-if, which IS the ternary.
///
/// Same single-slot shape `lowerShortCircuit` uses, and for the same reason:
/// the result has to be ONE value, so both arms store into one slot and the
/// slot is the answer.
///
///   if !cond goto ELSE;  S = then;  goto END;  ELSE: S = else;  END:
///
/// f64 is refused rather than guessed, exactly as short-circuit refuses it: the
/// slot is stored `.any`, and an f64 arm through an integer slot is a wrong
/// number, not a bail. The AST backend already lowers the f64 ternary.
fn lowerIfExpr(ctx: *LowerCtx, ie: *const ast.IfExpr) Error!dnir.Value {
    if (exprTouchesF64(ctx, ie.cond) or
        exprTouchesF64(ctx, ie.then_expr) or
        exprTouchesF64(ctx, ie.else_expr)) return bailWith(ctx.diagnostic, @src(), "if-expr-f64");

    // CONSTANT CONDITION ELIMINATION. If the condition folded to a constant
    // (via summary propagation or comptime eval), the branch vanishes: we
    // lower only the taken arm. This is what makes `if sum45(0)==45` disappear.
    const cond_const = try lowerExpr(ctx, ie.cond);
    if (cond_const == .i64) {
        if (cond_const.i64 != 0) {
            // True: take the then-branch, else-branch is dead.
            return try lowerExpr(ctx, ie.then_expr);
        } else {
            // False: take the else-branch, then-branch is dead.
            return try lowerExpr(ctx, ie.else_expr);
        }
    }

    const slot = ctx.freshTemp();
    const cond = cond_const;
    const test_idx = ctx.instrs.items.len;
    try ctx.emit(.{ .op = .br, .lhs = cond, .branch_target = 0, .branch_condition = .when_false });

    try ctx.emit(.{ .op = .store_local, .result = slot, .lhs = try lowerExpr(ctx, ie.then_expr), .ty = .any });
    const skip_idx = ctx.instrs.items.len;
    try ctx.emit(.{ .op = .br, .branch_target = 0 });

    ctx.instrs.items[test_idx].branch_target = @intCast(ctx.instrs.items.len);
    try ctx.emit(.{ .op = .store_local, .result = slot, .lhs = try lowerExpr(ctx, ie.else_expr), .ty = .any });
    ctx.instrs.items[skip_idx].branch_target = @intCast(ctx.instrs.items.len);

    // The slot inherits the arms' TYPE, not just their value. Without this a
    // `if c "a" else "b"` lands in an untyped slot and every consumer
    // downstream — `..`, `#s`, `s[i]` — reads the pointer as an integer.
    if (exprIsStr(ctx, ie.then_expr) and exprIsStr(ctx, ie.else_expr))
        try ctx.str_slots.put(ctx.alloc, slot, {});
    if (exprIsBoolish(ctx, ie.then_expr) and exprIsBoolish(ctx, ie.else_expr))
        try ctx.bool_slots.put(ctx.alloc, slot, {});
    return .{ .local = slot };
}

/// A `..` chain read as a printf FORMAT plus the arguments it consumes.
///
/// Both consumers of a chain — `print`, and a chain in value position — need
/// exactly this, and they need to AGREE on it: two renderers for "how does an
/// operand become text" is two chances to disagree with each other and with the
/// C backend.
const ConcatPlan = struct {
    /// The literal parts with `%` doubled and each hole replaced by its
    /// conversion. Owned by `ctx.alloc`.
    fmt: []const u8,
    /// The same text with NO conversions, valid only when `holes.len == 0`.
    literal: []const u8,
    /// Expressions whose values are staged in the variadic tail.
    /// Owned by `ctx.alloc`.
    holes: []const *const ast.Expr,
};

/// Read a flattened `..` chain as a format string, or answer null when a part
/// is a shape this cannot render. Null is not a failure — the caller decides
/// whether that is a bail or a fallback.
fn planConcat(ctx: *LowerCtx, parts: []const *const ast.Expr, newline: bool) Error!?ConcatPlan {
    var fmt: std.ArrayListUnmanaged(u8) = .empty;
    defer fmt.deinit(ctx.alloc);
    var literal: std.ArrayListUnmanaged(u8) = .empty;
    defer literal.deinit(ctx.alloc);
    var holes: std.ArrayListUnmanaged(*const ast.Expr) = .empty;
    errdefer holes.deinit(ctx.alloc);

    for (parts) |p| {
        if (p.* == .quoted) {
            // THE QUOTE FACE DECIDES WHETHER THIS IS FORMAT TEXT AT ALL
            // (GAP-145 `law.text.byte`). This branch folded the bytes of EVERY
            // quoted part straight into the format string, so a byte-sequence
            // literal became text here without anything having said so — and
            // it is reached BEFORE `lowerBinop`'s guard, because
            // `lowerPrintFormat` runs first for a print argument. One fact,
            // two answers, decided by whether the operand had a name:
            //
            //     print('abc' .. "Z")              -> abcZ    (folded here)
            //     x = 'abc' .. "Z" ; print(x)      -> refused (lowerBinop)
            //
            // Declining is the same verdict the named spelling already gets;
            // both callers of `planConcat` turn a null into their own bail.
            if (exprIsByteSequence(ctx, p)) return null;
            try literal.appendSlice(ctx.alloc, p.quoted.val);
            // A `%` in the program's own text is TEXT. Left alone it reads the
            // following byte as a conversion and prints an argument that was
            // never passed — a wrong answer produced by a correct-looking
            // literal.
            for (p.quoted.val) |ch| {
                if (ch == '%') try fmt.append(ctx.alloc, '%');
                try fmt.append(ctx.alloc, ch);
            }
            continue;
        }
        if (exprIsStr(ctx, p)) {
            try fmt.appendSlice(ctx.alloc, "%s");
        } else {
            // One classification per hole: the class carries the render, so
            // a second descent (via `concatOperandOk`) cannot disagree with
            // the first. `.str` is unreachable here — `exprIsStr` above
            // answered false — and `.other` (bool, byte sequence) refuses.
            const class = concatOperandClass(ctx, p);
            if (class == .f64) {
                // `%.17g` is the language's f64 text rendering — the
                // conversion `duo_str_from_f64` uses to mirror `lua_to_str`
                // exactly (codegen.zig), so an interpolated f64 reads what
                // `tostring` of the same value answers. `%lld` here would
                // print the double's bits as an integer: the plausible
                // wrong answer the old f64 refusal existed to prevent.
                try fmt.appendSlice(ctx.alloc, "%.17g");
            } else if (class == .integral) {
                try fmt.appendSlice(ctx.alloc, "%lld");
            } else return null;
        }
        try holes.append(ctx.alloc, p);
    }
    if (newline) {
        try fmt.append(ctx.alloc, '\n');
        try literal.append(ctx.alloc, '\n');
    }
    return .{
        .fmt = try ctx.alloc.dupe(u8, fmt.items),
        .literal = try ctx.alloc.dupe(u8, literal.items),
        .holes = try holes.toOwnedSlice(ctx.alloc),
    };
}

/// Stage a plan's holes in the variadic tail. Emitted immediately before the
/// call that reads them.
fn stageConcatHoles(ctx: *LowerCtx, vals: []const dnir.Value) Error!void {
    for (vals, 0..) |v, i| {
        try ctx.emit(.{ .op = .mov_arg, .result = @intCast(i), .field = "vararg", .lhs = v });
    }
}

/// A `..` chain in VALUE position — `s = "a={a}"` — as one buffer.
///
/// The chain used to lower pairwise: strlen, strlen, malloc, strcpy, strcat per
/// `..`, with every intermediate buffer live across every later call. Three
/// holes is 26 values live at once against 19 allocatable registers, and the
/// backend leaks one more per result-less call, so the ladder ASSEMBLED and
/// then answered wrong — `a .. "-" .. b .. "-" .. c` printed the right text and
/// exited 240, and a three-hole interpolation segfaulted. Measuring the chain
/// once and filling it once removes the pressure instead of budgeting for it:
/// live values drop to one per hole, and those ride the variadic tail, which
/// Apple's ARM64 ABI passes in memory rather than in registers.
///
/// MEASURE, THEN FILL — the buffer is the size of the answer.
///
/// It used to be `malloc(4096)` and `snprintf(buf, 4096, …)`, one fixed
/// capacity for every chain in every program, and that is three defects in one
/// line:
///
///   1. IT TRUNCATED AT 4095 BYTES, silently. Measured at the boundary: a
///      4094-byte chain agreed with `--backend=c`, a 4096-byte chain produced
///      4095 bytes where C produced 4096, and an 8192-byte chain produced 4095
///      where C produced 8192. Exit 0 both times, `ok compile` both times. Two
///      backends, one source, DIFFERENT ANSWERS — which is strictly worse than
///      a bug, because neither side reports anything.
///   2. IT ALLOCATED 4 KB PER EVALUATION regardless of the answer's size, so a
///      loop concatenating short strings grew RSS by 4 KB an iteration.
///   3. It made the cost of a chain independent of its length, which hid both.
///
/// C's `snprintf` answers question 1 itself: called with a null destination and
/// a zero size it WRITES NOTHING and RETURNS THE LENGTH THE RESULT NEEDS. So
/// the sequence is measure, allocate exactly that many bytes plus the NUL, fill.
/// No cap, so nothing to exceed and nothing to refuse; the allocation is the
/// size of the string, so a short chain costs a short buffer.
///
/// THE HOLES ARE LOWERED ONCE and staged twice. That distinction is the whole
/// safety of the second call: `vals` holds already-computed DNIR values, and
/// `stageConcatHoles` only moves them into the variadic tail, so an operand
/// carrying an effect still runs exactly once. An earlier attempt at this shape
/// was abandoned after `print(p)` segfaulted on a register that held snprintf's
/// integer return instead of the malloc pointer; the boundary and byte
/// comparisons below are what makes the difference between then and now
/// checkable rather than remembered.
fn lowerConcatChain(ctx: *LowerCtx, lhs: *const ast.Expr, rhs: *const ast.Expr) Error!dnir.Value {
    var parts: std.ArrayListUnmanaged(*const ast.Expr) = .empty;
    defer parts.deinit(ctx.alloc);
    try flattenConcat(ctx.alloc, lhs, &parts);
    try flattenConcat(ctx.alloc, rhs, &parts);

    const plan = (try planConcat(ctx, parts.items, false)) orelse return bailWith(ctx.diagnostic, @src(), "concat");
    // Every part was a literal, so the chain IS its own answer — determined at
    // compile time, and it must not reach the allocator at all.
    if (plan.holes.len == 0) return .{ .str = plan.literal };

    try ensureExtern(ctx, "mem", "alloc", "malloc");
    try ensureExtern(ctx, "mem", "grow", "realloc");
    try ensureExtern(ctx, "string", "format", "snprintf");

    // THE VARIADIC TAIL IS EIGHT SLOTS ON THIS ABI, and a register file is not
    // a list. One chain wider than that — `gate/architecture.id` builds
    // 76-hole census lines — used to refuse at the backend's `pending_varargs`
    // bound, and the first chunked answer refused again with every hole
    // lowered UP FRONT: 76 temps live at once is more names than the machine
    // has registers, and the holes' values are not needed simultaneously —
    // only EIGHT at a time, one chunk's worth, ever are.
    //
    // So the chain is rendered as a running buffer grown per chunk: lower a
    // chunk's holes, measure them, grow the buffer to fit, fill at the write
    // offset. Across chunks exactly TWO values stay live — the buffer and the
    // byte count — and an eight-hole chain compiles to exactly the
    // instructions it did before via `lowerConcatSingle`.
    const vararg_slots = 8;
    if (plan.holes.len <= vararg_slots) {
        const vals = try ctx.alloc.alloc(dnir.Value, plan.holes.len);
        defer ctx.alloc.free(vals);
        for (plan.holes, 0..) |h, i| vals[i] = try lowerExpr(ctx, h);
        return try lowerConcatSingle(ctx, plan.fmt, vals);
    }

    // Split the FORMAT by chunk boundaries. A chunk's format is the literal
    // run between its first and last hole plus the hole conversions, so the
    // chunks concatenate to the whole format with no bytes dropped or doubled.
    var chunks: std.ArrayListUnmanaged(ChunkPlan) = .empty;
    defer chunks.deinit(ctx.alloc);
    {
        var hole_idx: usize = 0;
        var fmt_pos: usize = 0;
        while (hole_idx < plan.holes.len) {
            const take = @min(vararg_slots, plan.holes.len - hole_idx);
            const chunk = try planChunk(ctx, plan.fmt, fmt_pos, hole_idx, take, plan.holes.len);
            try chunks.append(ctx.alloc, chunk);
            fmt_pos = chunk.fmt_end;
            hole_idx += take;
        }
    }

    // One byte so `realloc` always holds a real pointer, and the running
    // written count starts at zero. THE BUFFER AND THE COUNT ARE LOCALS, NOT
    // TEMPS. They live across chunks, across the snprintf/realloc CALLS that
    // marshal staged arguments, and across each other's redefinition — a
    // register name would have to survive every one of those handoffs, and a
    // name the release paths orphan is not a value (GAP-148). A `.local` slot
    // has a frame home the backend reloads from, so a stale register name
    // falls through to the authoritative copy instead of feeding `realloc`
    // its own size as its pointer — the exact miscompile that aborted the
    // architecture gate before this. Call results still land in a TEMP first
    // and reach the slot only through `store_local`, the same shape
    // `lowerRuntimeNumFor` uses for its loop counters.
    const buf = ctx.freshTemp();
    const seeded = ctx.freshTemp();
    try ctx.emit(.{ .op = .call_extern, .result = seeded, .callee = "malloc", .lhs = .{ .i64 = 1 } });
    try ctx.emit(.{ .op = .store_local, .result = buf, .lhs = .{ .temp = seeded }, .ty = .any });
    const written = ctx.freshTemp();
    try ctx.emit(.{ .op = .store_local, .result = written, .lhs = .{ .i64 = 0 }, .ty = .i64 });

    for (chunks.items) |chunk| {
        // Lower THIS chunk's holes now — the only moment their values exist.
        const vals = try ctx.alloc.alloc(dnir.Value, chunk.hole_count);
        defer ctx.alloc.free(vals);
        for (plan.holes[chunk.hole_start .. chunk.hole_start + chunk.hole_count], 0..) |h, i|
            vals[i] = try lowerExpr(ctx, h);

        // MEASURE: `snprintf(NULL, 0, fmt, …)` answers the byte count.
        try ctx.emit(.{ .op = .mov_arg, .result = 0, .lhs = .{ .i64 = 0 } });
        try ctx.emit(.{ .op = .mov_arg, .result = 1, .lhs = .{ .i64 = 0 } });
        try ctx.emit(.{ .op = .mov_arg, .result = 2, .lhs = .{ .str = chunk.fmt } });
        try stageConcatHoles(ctx, vals);
        const need = ctx.freshTemp();
        try ctx.emit(.{ .op = .call_extern, .result = need, .callee = "snprintf", .ty = .i64 });

        // The chunk needs its bytes plus one NUL; the buffer must hold
        // everything written so far plus that.
        const remain = try binopTemp(ctx, .add, .{ .temp = need }, .{ .i64 = 1 });
        const newsize = try binopTemp(ctx, .add, .{ .local = written }, .{ .temp = remain });

        // buf = realloc(buf, newsize) — the grown pointer reaches the slot
        // through `store_local`, never straight off the call.
        try ctx.emit(.{ .op = .mov_arg, .result = 0, .lhs = .{ .local = buf } });
        try ctx.emit(.{ .op = .mov_arg, .result = 1, .lhs = .{ .temp = newsize } });
        const grown = ctx.freshTemp();
        try ctx.emit(.{ .op = .call_extern, .result = grown, .callee = "realloc" });
        try ctx.emit(.{ .op = .store_local, .result = buf, .lhs = .{ .temp = grown }, .ty = .any });

        // FILL at the write offset; `remain` is exactly the room left.
        const dst = try binopTemp(ctx, .add, .{ .local = buf }, .{ .local = written });
        try ctx.emit(.{ .op = .mov_arg, .result = 0, .lhs = .{ .temp = dst } });
        try ctx.emit(.{ .op = .mov_arg, .result = 1, .lhs = .{ .temp = remain } });
        try ctx.emit(.{ .op = .mov_arg, .result = 2, .lhs = .{ .str = chunk.fmt } });
        try stageConcatHoles(ctx, vals);
        const filled = ctx.freshTemp();
        try ctx.emit(.{ .op = .call_extern, .result = filled, .callee = "snprintf", .ty = .i64 });

        // written += filled — a binop answers in a temp; the slot takes it
        // through `store_local`, exactly as the loop counters do.
        const wsum = try binopTemp(ctx, .add, .{ .local = written }, .{ .temp = filled });
        try ctx.emit(.{ .op = .store_local, .result = written, .lhs = .{ .temp = wsum }, .ty = .i64 });
    }
    try ctx.str_slots.put(ctx.alloc, buf, {});
    return .{ .local = buf };
}

/// One chunk of an over-wide concat chain: the format slice this chunk renders
/// and the holes it consumes. `fmt_end` is the offset in the WHOLE format just
/// past this chunk's last conversion, which is where the next chunk begins.
const ChunkPlan = struct {
    fmt: []const u8,
    fmt_end: usize,
    hole_start: usize,
    hole_count: usize,
};

/// Split `fmt[fmt_pos..]` so the chunk holds exactly `take` hole conversions.
///
/// Conversions are exactly `%s` and `%lld` — `planConcat` is the only producer
/// of this string, and it doubles every literal `%` first, so a conversion is
/// every `%` that is not the first of a `%%` pair.
fn planChunk(ctx: *LowerCtx, fmt: []const u8, fmt_pos: usize, hole_start: usize, take: usize, total_holes: usize) Error!ChunkPlan {
    var i = fmt_pos;
    var seen: usize = 0;
    var end = fmt.len;
    while (i < fmt.len) {
        if (fmt[i] == '%') {
            if (i + 1 < fmt.len and fmt[i + 1] == '%') {
                i += 2;
                continue;
            }
            seen += 1;
            if (seen == take) {
                // Past this conversion: `%s` is 2 bytes, `%lld` is 4.
                end = i + (if (fmt[i + 1] == 'l') @as(usize, 4) else 2);
                if (hole_start + take == total_holes) end = fmt.len;
                break;
            }
        }
        i += 1;
    }
    return .{
        .fmt = try ctx.alloc.dupe(u8, fmt[fmt_pos..end]),
        .fmt_end = end,
        .hole_start = hole_start,
        .hole_count = take,
    };
}

fn binopTemp(ctx: *LowerCtx, op: dnir.BinOpTag, lhs: dnir.Value, rhs: dnir.Value) Error!u32 {
    const t = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = t, .binop = op, .lhs = lhs, .rhs = rhs });
    return t;
}

/// The pre-chunk shape, unchanged, for every chain that fits the tail once.
fn lowerConcatSingle(ctx: *LowerCtx, fmt: []const u8, vals: []const dnir.Value) Error!dnir.Value {
    // MEASURE: `snprintf(NULL, 0, fmt, …)` writes nothing and answers the
    // length. This is the C standard's own answer to "how big is it", not an
    // estimate this pass invents.
    try ctx.emit(.{ .op = .mov_arg, .result = 0, .lhs = .{ .i64 = 0 } });
    try ctx.emit(.{ .op = .mov_arg, .result = 1, .lhs = .{ .i64 = 0 } });
    try ctx.emit(.{ .op = .mov_arg, .result = 2, .lhs = .{ .str = fmt } });
    try stageConcatHoles(ctx, vals);
    const need = ctx.freshTemp();
    try ctx.emit(.{ .op = .call_extern, .result = need, .callee = "snprintf", .ty = .i64 });

    // One more byte for the NUL `snprintf` excludes from its answer.
    const size = try binopTemp(ctx, .add, .{ .temp = need }, .{ .i64 = 1 });

    const buf = ctx.freshTemp();
    try ctx.emit(.{ .op = .call_extern, .result = buf, .callee = "malloc", .lhs = .{ .temp = size } });

    // FILL: the same format and the same already-lowered holes, into a buffer
    // that cannot be too small because it was measured from them.
    try ctx.emit(.{ .op = .mov_arg, .result = 0, .lhs = .{ .temp = buf } });
    try ctx.emit(.{ .op = .mov_arg, .result = 1, .lhs = .{ .temp = size } });
    try ctx.emit(.{ .op = .mov_arg, .result = 2, .lhs = .{ .str = fmt } });
    try stageConcatHoles(ctx, vals);
    try ctx.emit(.{ .op = .call_extern, .callee = "snprintf" });
    try ctx.str_slots.put(ctx.alloc, buf, {});
    return .{ .temp = buf };
}

fn lowerStrCompare(ctx: *LowerCtx, op: ast.BinOp, lhs: *const ast.Expr, rhs: *const ast.Expr) Error!dnir.Value {
    const l = try lowerExpr(ctx, lhs);
    const r = try lowerExpr(ctx, rhs);
    try ensureExtern(ctx, "libc", "strcmp", "strcmp");
    try ctx.emit(.{ .op = .mov_arg, .result = 0, .lhs = l });
    try ctx.emit(.{ .op = .mov_arg, .result = 1, .lhs = r });
    const cmp = ctx.freshTemp();
    try ctx.emit(.{ .op = .call_extern, .result = cmp, .callee = "strcmp", .ty = .i64 });
    const t = ctx.freshTemp();
    try ctx.emit(.{
        .op = .binop,
        .result = t,
        .binop = switch (op) {
            .eq => .eq,
            .neq => .neq,
            .lt => .lt,
            .gt => .gt,
            .leq => .leq,
            .geq => .geq,
            else => return bailNamed(ctx.diagnostic, @src(), "cmp-not-lowered", @tagName(op)),
        },
        .lhs = .{ .temp = cmp },
        .rhs = .{ .i64 = 0 },
        .ty = .any,
    });
    return .{ .temp = t };
}

/// The C rank of an already-lowered operand's SOURCE expression.
///
/// Conservative in one direction only: anything this pass cannot type answers
/// `.int64`, which never asks for a refit. A missing refit leaves today's
/// behaviour; a spurious one would be a NEW wrong answer, so the unknown case
/// has to fall on the side that changes nothing.
///
/// Known gap, recorded rather than guessed: a CALL answers `.int64` even when
/// the callee is declared `i32`, so `u32_expr + i32_call()` is not wrapped
/// where C would wrap it. Closing it needs the callee's declared return at this
/// site; `u32` returns are already ineligible for this backend, so the gap is
/// exactly one shape wide.
fn exprCRank(ctx: *LowerCtx, e: *const ast.Expr) CRank {
    return switch (e.*) {
        .int_lit => |i| if (i.val >= std.math.minInt(i32) and i.val <= std.math.maxInt(i32))
            .int32
        else
            .int64,
        .true_lit, .false_lit => .int32,
        .name => |n| blk: {
            const slot = ctx.locals.get(n.ident) orelse break :blk .int64;
            const declared = ctx.narrow_slots.get(slot) orelse break :blk .int64;
            break :blk crankOfNarrow(declared);
        },
        .unop => |u| switch (u.op) {
            .neg, .bnot => exprCRank(ctx, u.operand),
            .not => .int32,
            else => .int64,
        },
        .binop => |b| switch (b.op) {
            // `--backend=c` emits `((int64_t)(x)) << k` and
            // `lua_imod_i64((int64_t)(a), (int64_t)(b))` — the operands are
            // WIDENED before the operation, so the result is not narrow and
            // must not be refitted. Measured: `a << 4` on a `u32` holding
            // 4294967295 prints 68719476720 under both backends today.
            .lshift, .rshift, .div, .idiv, .mod, .pow => .int64,
            .eq, .neq, .lt, .gt, .leq, .geq, .@"and", .@"or", .contains => .int32,
            .add, .sub, .mul, .band, .bor, .bxor => crankJoin(
                exprCRank(ctx, b.lhs),
                exprCRank(ctx, b.rhs),
            ),
            else => .int64,
        },
        else => .int64,
    };
}

/// The declared width an operation's RESULT carries, or `.any` when it carries
/// none. Only `unsigned int` earns one — see `CRank`.
fn binopResultWidth(ctx: *LowerCtx, op: ast.BinOp, lhs: *const ast.Expr, rhs: *const ast.Expr) RT {
    switch (op) {
        .add, .sub, .mul, .band, .bor, .bxor => {},
        else => return .any,
    }
    const l = exprCRank(ctx, lhs);
    const r = exprCRank(ctx, rhs);
    if (crankJoin(l, r) != .uint32) return .any;
    // BITWISE OPS THAT CANNOT LEAVE THE WIDTH ARE NOT REFITTED, and this is a
    // proof rather than a tolerance. A `.uint32` operand is canonical — its top
    // 32 bits are zero — so:
    //   AND needs only ONE canonical operand: it cannot set a bit that operand
    //   does not have.
    //   OR and XOR need BOTH: a sign-extended negative on the other side would
    //   otherwise leak its high bits through.
    // Everything else (add, sub, mul) carries out of bit 31 and must be refit.
    switch (op) {
        .band => return .any,
        .bor, .bxor => if (l == .uint32 and r == .uint32) return .any,
        else => {},
    }
    return .u32;
}

/// A store's refit SUBSUMES the refit of the instruction that produced its
/// value, when that producer is the instruction immediately before it and both
/// refit to the same width.
///
/// This is what keeps the repair free on the shape it exists for. `h = h * K`
/// on a `u32` lowers to `binop mul -> t` then `store_local h <- t`; refitting
/// both emits two `ubfx` where the store's alone is enough, and on
/// `tools/wasm/bench/hash.id` that is three extra instructions per iteration
/// across 200 million iterations.
///
/// SINGLE-CONSUMER IS BY CONSTRUCTION, not by search: `t` was allocated by the
/// expression just lowered and handed straight to this store, so no earlier
/// instruction can name it and no later one exists yet. The two positional
/// checks below (producer is at `len-2`, its result is exactly what the store
/// reads) are the whole precondition.
fn subsumeProducerRefit(ctx: *LowerCtx) void {
    const items = ctx.instrs.items;
    if (items.len < 2) return;
    const store = items[items.len - 1];
    if (store.op != .store_local) return;
    if (store.lhs != .temp) return;
    const want = narrowFit(store.ty) orelse return;
    const producer = &items[items.len - 2];
    if (producer.op != .binop) return;
    const result = producer.result orelse return;
    if (result != store.lhs.temp) return;

    // WHICH SIDE ABSORBS THE OTHER IS A REALIZATION QUESTION, AND AT 32
    // UNSIGNED BITS THE PRODUCER WINS.
    //
    // A store's refit is an INSTRUCTION — `ubfx xd, xs, #0, #32` — and it sits
    // on the recurrence of every loop that carries a `u32`. A producer's refit
    // at that width is not an instruction at all: `native_backend.wForm32`
    // selects the 32-bit destination form, whose zero-extension IS the
    // narrowing. So handing the width to the PRODUCER deletes the chain node
    // and leaves the store an ordinary register move, which this machine
    // renames away (`docs/dependence-height.md` §1.2, measured at -0.016 cyc).
    //
    // Measured on `tools/wasm/bench/hash2b.id`, the single largest consumer of
    // cycles in this corpus: 9.09 -> 6.04 cycles per iteration, same answer.
    //
    // Only at 32 unsigned bits, and only for the operations whose low half is
    // a function of the operands' low halves — see `lowThirtyTwoExact`. `u8`,
    // `u16` and every signed width keep the store-side refit below, because
    // their narrowing is a real mask or a real sign extension and no
    // destination form performs it for free.
    if (want.bits == 32 and !want.signed and lowThirtyTwoExact(producer.binop) and
        (producer.ty == .any or producer.ty == .u32))
    {
        producer.ty = .u32;
        items[items.len - 1].ty = .any;
        return;
    }

    // Otherwise the store absorbs the producer's, which is what this function
    // was written for: refitting both emits two `ubfx` where the store's alone
    // is enough.
    const have = narrowFit(producer.ty) orelse return;
    if (have.bits != want.bits or have.signed != want.signed) return;
    producer.ty = .any;
}

/// Refit a lowered value to a declared width, folding when it is a literal.
///
/// The register form is a `store_local` into a fresh slot, which the backend
/// realizes as exactly one extend instruction — the same instruction any other
/// refit emits, through the same code path, so there is one origin for the
/// machine behaviour and not two.
fn refitValue(ctx: *LowerCtx, v: dnir.Value, ty: RT) Error!dnir.Value {
    if (narrowFit(ty) == null) return v;
    switch (v) {
        .i64 => |n| return .{ .i64 = narrowFitConst(n, ty) },
        .void, .f64, .str, .record => return v,
        else => {},
    }
    const t = ctx.freshTemp();
    try ctx.emit(.{ .op = .store_local, .result = t, .lhs = v, .ty = ty });
    return .{ .temp = t };
}

/// `IDOL_FLOOR_FIXUP_ALWAYS=1` — THE SEVERING CONTROL. Set it and no divisor is
/// ever reported non-negative, so every division emits the general eight
/// instruction correction exactly as this compiler did before this pass
/// existed.
fn floorFixupForced() bool {
    return std.c.getenv("IDOL_FLOOR_FIXUP_ALWAYS") != null;
}

/// law §62 — `x / y` and `x % y` where `y` is zero AT RUN TIME.
///
/// AArch64 `sdiv` does not fault: it answers 0. That is a property of the chip,
/// not a decision this language made, and §62 requires division by zero to be
/// DEFINED and DETERMINISTIC. Measured before this guard, one source and two
/// answers — `--backend direct` printed `0` and `--backend=c` printed
/// `9218868437227405312` (the bits of +inf) — with exit 0 and no message on
/// either. A value that changes with the target is not a definition.
///
/// The literal-zero divisor is settled earlier and elsewhere: `sema.zig`'s
/// `check_literal_zero_divisor` refuses it with a diagnostic, because there is
/// nothing to guard when the divisor IS zero. What reaches here is the case the
/// compiler cannot decide, and `soundness.md` names the handling for exactly
/// that: "realization selects an explicit guard whose failure is a semantic
/// case". The guard is the same shape `emitIndexBoundsTrap` already uses — a
/// compare, a branch and `abort` — so the two runtime faults this backend can
/// raise are one mechanism, not two.
///
/// Cost is one `cmp` and one conditional branch per division whose divisor is
/// not a nonzero constant. A constant nonzero divisor — every `/ 2`, `/ 8`,
/// `% 10` in the corpus — pays nothing at all.
/// THE SLOT A CONDITION PROVES NON-ZERO, or null.
///
/// Exactly `x != 0` and `0 != x`, where `x` names a local. Deliberately not
/// `x > 0` or `x < 0`: those prove non-zero too, but they are not what a
/// division guard's redundancy came from and admitting them would widen the
/// rule past the evidence that justifies it. Nothing here inspects the
/// LOWERED condition — a lowered comparison is a temp holding a boolean, and
/// the operand identity this needs is only in the source expression.
fn nonZeroSlotOfCondition(ctx: *const LowerCtx, cond: *const ast.Expr) ?u32 {
    const b = switch (cond.*) {
        .binop => |bb| bb,
        else => return null,
    };
    if (b.op != .neq) return null;
    const named: *const ast.Expr, const other: *const ast.Expr =
        if (b.lhs.* == .name) .{ b.lhs, b.rhs } else if (b.rhs.* == .name) .{ b.rhs, b.lhs } else return null;
    const zero = ast.intLiteralValue(other) orelse return null;
    if (zero != 0) return null;
    // A name that is shadowed by a fused body literal, or that is not a local
    // at all, has no slot to key the fact on.
    if (ctx.fused_literals.contains(named.name.ident)) return null;
    if (ctx.const_ints.contains(named.name.ident)) return null;
    return ctx.locals.get(named.name.ident);
}

/// `IDOL_DIVZERO_GUARD_ALWAYS=1` — THE SEVERING CONTROL for the elimination
/// above. Set it and every division emits its guard again, exactly as this
/// compiler did before `nonzero_slots` existed, so the two arms differ in this
/// one decision and in nothing else. It is read per call rather than cached
/// because the cost is one `getenv` per division in a compiler that is not the
/// thing being measured.
fn divisorGuardForced() bool {
    return std.c.getenv("IDOL_DIVZERO_GUARD_ALWAYS") != null;
}

fn emitDivisorZeroTrap(ctx: *LowerCtx, divisor: dnir.Value) Error!void {
    if (divisor == .i64 and divisor.i64 != 0) return;

    // ALREADY DECIDED. A dominating `while d != 0`, or a guard this pass
    // emitted earlier in the same straight-line region, has settled it; the
    // trap below would compare the same register against the same zero and
    // could not fire. Deleting it removes a compare, a branch, a second branch
    // over the trap, and the six-word `abort` block that was laid out INLINE
    // between the loop header and the loop body.
    if (divisor == .local and !divisorGuardForced()) {
        if (ctx.nonzero_slots.contains(divisor.local)) return;
    }

    const ok = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = ok, .binop = .neq, .lhs = divisor, .rhs = .{ .i64 = 0 } });
    const bad = ctx.instrs.items.len;
    try ctx.emit(.{ .op = .br, .lhs = .{ .temp = ok }, .branch_target = 0, .branch_condition = .when_false });

    const skip = ctx.instrs.items.len;
    try ctx.emit(.{ .op = .br, .branch_target = 0 });

    ctx.instrs.items[bad].branch_target = @intCast(ctx.instrs.items.len);
    try emitTrap(ctx);
    ctx.instrs.items[skip].branch_target = @intCast(ctx.instrs.items.len);
}

/// THE ONE PLACE A SOURCE RELATION MEETS ITS DNIR TAG. `null` is a relation
/// with no tag — an application, a runtime helper, a shape this substrate does
/// not realize as a binop — and the caller refuses it.
///
/// It is `pub` and it is NAMED because the two enums it joins sit on opposite
/// sides of the layering firewall, so the divisor-nonzero obligation cannot be
/// one declaration: `BinOpTag.requiresNonzeroDivisor` states it over the tag for the
/// realization consumers, `demand_projection.Law.divisor_nonzero` states it
/// over the relation for the meaning consumers, and this projection is what
/// lets `tests.zig` prove the two agree instead of assuming it. That test is
/// the machinery this defect lacked — the guard list and the tag set drifted
/// apart with nothing running that could notice.
pub fn binopTagOf(op: ast.BinOp) ?dnir.BinOpTag {
    return switch (op) {
        .add => .add,
        .sub => .sub,
        .mul => .mul,
        .div => .div,
        // `//` KEEPS ITS OWN IDENTITY. This read `.div, .idiv => .div`, which
        // is where floor division was lost: the two operators became one tag
        // and the backend then emitted `sdiv` for both. `(0-7) // 10` answered
        // 0; the law answers -1. HPLS §92 — the host may not define relation
        // law — and §4: the optimizer uses the LAW, so the tag has to be able
        // to carry it. Splitting them is also what dropped `//`'s divisor
        // guard, because that guard was keyed on the tag set this switch
        // produces rather than on the obligation itself.
        .idiv => .idiv,
        .mod => .mod,
        .eq => .eq,
        .neq => .neq,
        .lt => .lt,
        .gt => .gt,
        .leq => .leq,
        .geq => .geq,
        .band => .band,
        .bor => .bor,
        .bxor => .bxor,
        .lshift => .shl,
        .rshift => .shr,
        else => null,
    };
}

/// Decide a comparison on the exact values its operands name.
///
/// 0.1 names one tenth; the f64 nearest it does not. Ordinary lowering
/// commits every float literal to f64 before comparing, so 0.1 + 0.2 == 0.3
/// answered 0 on every backend -- the exact fact was discarded before
/// emission and the backends correctly executed binary floating-point
/// arithmetic on the roundings. Deciding the comparison on the values the
/// spellings name restores the answer the source states, under each binding's
/// own contract. Fail-closed: any operand the producer cannot value leaves
/// the comparison on the ordinary path. Strict exactness, never a tolerance:
/// 0.1 + 1e-19 == 0.1 stays false.
/// THE COMPARISON FOLD, ANSWERED BY THE ONE PRODUCER. lowerBinop asks
/// comptime_eval -- the same evaluator that folds relation bodies -- to decide
/// a comparison over the stable module numeric bindings. The values arrive in
/// the producer's carrier with each binding's float contract already applied,
/// so `fa: f64 = 0.1` compares as the f64 nearest one tenth while unqualified
/// `ma = 0.1` compares as one tenth exactly. A name the read would not answer
/// from the module binding (fused literal, stored global, or a shadowing
/// local) declines the fold; anything the producer cannot evaluate declines
/// too, and the ordinary runtime path below runs unchanged.
fn foldNumericComparison(ctx: *LowerCtx, op: ast.BinOp, lhs: *const ast.Expr, rhs: *const ast.Expr) ?bool {
    switch (op) {
        .eq, .neq, .lt, .gt, .leq, .geq => {},
        else => return null,
    }
    if (comparisonNameShadowed(ctx, lhs) or comparisonNameShadowed(ctx, rhs)) return null;
    var scope: std.StringHashMapUnmanaged(comptime_eval.Value) = .empty;
    defer scope.deinit(ctx.alloc);
    var it = ctx.module_consts.nums.iterator();
    while (it.next()) |e| scope.put(ctx.alloc, e.key_ptr.*, e.value_ptr.*) catch return null;
    // Function-body constants recorded by `noteConstNum` shadow module
    // bindings of the same spelling: the local is what the read answers.
    var cit = ctx.const_nums.iterator();
    while (cit.next()) |e| scope.put(ctx.alloc, e.key_ptr.*, e.value_ptr.*) catch return null;
    const scopes = [_]std.StringHashMapUnmanaged(comptime_eval.Value){scope};
    const opts = comptime_eval.Options{ .step_limit = 10_000, .alloc = ctx.alloc };
    const l = comptime_eval.evalWithBindings(lhs, .{ .scopes = &scopes }, opts) catch return null;
    const r = comptime_eval.evalWithBindings(rhs, .{ .scopes = &scopes }, opts) catch return null;
    return comptime_eval.compareValues(op, l, r) catch return null;
}

/// True when any name inside the expression would NOT read a provably constant
/// numeric at this lowering point: a fused literal, a stored module global, or --
/// inside a relation body -- a shadowing local that `noteConstNum` did not prove
/// constant. A name in `const_nums` is provably constant, so the fold may answer.
fn comparisonNameShadowed(ctx: *LowerCtx, expr: *const ast.Expr) bool {
    switch (expr.*) {
        .name => |nm| {
            const n = nm.ident;
            if (ctx.const_nums.contains(n)) return false;
            if (ctx.fused_literals.contains(n)) return true;
            if (ctx.module_globals.types.contains(n)) return true;
            if (!ctx.module_root and ctx.locals.contains(n)) return true;
            return false;
        },
        .binop => |b| return comparisonNameShadowed(ctx, b.lhs) or comparisonNameShadowed(ctx, b.rhs),
        .unop => |u| return comparisonNameShadowed(ctx, u.operand),
        else => return false,
    }
}

fn lowerBinop(ctx: *LowerCtx, op: ast.BinOp, lhs: *const ast.Expr, rhs: *const ast.Expr) Error!dnir.Value {
    // Numeric comparison fold, answered by the one producer. Decides the
    // comparison on the stable numeric values the operand spellings name --
    // module constants and function-body constants proved by `noteConstNum`;
    // declines (null) for anything else and the ordinary f64 path below runs
    // unchanged.
    if (foldNumericComparison(ctx, op, lhs, rhs)) |truth| return .{ .i64 = if (truth) 1 else 0 };
    if (op == .concat and concatOperandOk(ctx, lhs) and concatOperandOk(ctx, rhs) and
        (exprIsStr(ctx, lhs) or exprIsStr(ctx, rhs)))
    {
        return try lowerConcatChain(ctx, lhs, rhs);
    }
    const str_cmp = switch (op) {
        .eq, .neq, .lt, .gt, .leq, .geq => exprIsStr(ctx, lhs) and exprIsStr(ctx, rhs),
        else => false,
    };
    if (str_cmp) return try lowerStrCompare(ctx, op, lhs, rhs);
    const f64_op = exprIsF64(ctx, lhs) or exprIsF64(ctx, rhs);
    // Selected BEFORE either operand is lowered: an unsupported operator has to
    // refuse without having emitted the operands' instructions, which is what
    // the struct-literal field order used to guarantee.
    const tag: dnir.BinOpTag = binopTagOf(op) orelse {
        if (@import("builtin").mode == .debug) {
            switch (lhs.*) {
                .name => |n| std.debug.print("lowerBinop refuse op={s} lhs=name:{s} rhs_kind={s}\n", .{ @tagName(op), n.ident, @tagName(rhs.*) }),
                else => switch (rhs.*) {
                    .quoted => |qv| std.debug.print("lowerBinop refuse op={s} lhs_kind={s} rhs=quoted:{s} graphTextConst(rhs)={}\n", .{ @tagName(op), @tagName(lhs.*), qv.val[0..@min(qv.val.len, 60)], graphTextConst(ctx.graph, rhs) }),
                    else => std.debug.print("lowerBinop refuse op={s} lhs_kind={s} rhs_kind={s}\n", .{ @tagName(op), @tagName(lhs.*), @tagName(rhs.*) }),
                },
            }
        }
        return bailNamed(ctx.diagnostic, @src(), "binop-not-lowered", @tagName(op));
    };
    // PROVED XOR IDIOM. `x + y - 2*(x&y)` is exactly `x ^ y`
    // (bit-vector identity: `x + y = (x^y) + 2*(x&y)`), so the whole
    // subtraction is one `eor`. Checked before either operand is lowered:
    // on a match the `add`/`mul`/`band` are not emitted at all --
    // ~9 instructions become one. `IDOL_XORIDIOM_OFF=1` severs it.
    if (op == .sub and !f64_op and !xorIdiomOff()) {
        if (ast.xorIdiomOperands(lhs, rhs)) |ops| {
            const a = try lowerExpr(ctx, ops.a);
            const b = try lowerExpr(ctx, ops.b);
            const t = ctx.freshTemp();
            try ctx.emit(.{
                .op = .binop,
                .result = t,
                .binop = .bxor,
                .lhs = a,
                .rhs = b,
                .ty = binopResultWidth(ctx, .bxor, ops.a, ops.b),
            });
            return .{ .temp = t };
        }
    }
    var cse_key: ?CseKey = null;
    var a = try lowerExpr(ctx, lhs);
    var b = try lowerExpr(ctx, rhs);
    // WHICH RELATIONS OWE A NON-ZERO DIVISOR IS NOT DECIDED HERE. This line
    // used to read `tag == .div or tag == .mod` — a hand-kept operator list,
    // at the emission site, over the DNIR enum — and that is the whole defect.
    // `//` used to LOWER to `.div`, so the list covered it by accident; when
    // `//` was given its own tag so it could carry floor law, the list was not
    // updated with it. Floor division then reached a bare `sdiv`, which on
    // AArch64 ANSWERS 0 rather than faulting, so an opaque runtime zero divisor
    // through `//` returned 0 and exited 0 while `/` and `%` on the SAME
    // divisor aborted. `BinOpTag.requiresNonzeroDivisor` is the one obligation the three
    // share, stated beside the tags whose relation law it belongs to; every
    // realization consumer asks it and none of them keeps a list.
    //
    // Integer division only. IEEE-754 DEFINES `x / 0.0` as ±inf and §62 lists
    // infinities among the defined outcomes, so the float path has an answer
    // already and must not be given a fault instead. The OPERANDS decide that,
    // not the obligation — which is why this reads the operands separately and
    // does not fold the float case into the law.
    if (!f64_op and tag.requiresNonzeroDivisor()) try emitDivisorZeroTrap(ctx, b);
    var result_ty: RT = if (f64_op) .f64 else .any;
    if (!f64_op) {
        if (unsignedComparison(ctx, op, lhs, rhs)) |conv| {
            // C converts BOTH operands to the common type before comparing, so
            // `a < -1` on a `uint32_t` is `a < 4294967295u` — true — and the
            // 64-bit signed compare this backend emits answers false. Refit the
            // operand that is not already canonical at the common width and the
            // existing signed compare then gives C's answer, with no new
            // condition codes to get backwards.
            if (conv.fit_lhs) a = try refitValue(ctx, a, conv.ty);
            if (conv.fit_rhs) b = try refitValue(ctx, b, conv.ty);
        } else {
            result_ty = binopResultWidth(ctx, op, lhs, rhs);
        }
    }
    // BLOCK-SCOPED VALUE NUMBERING. The lookup runs after the operands are
    // lowered and the trap is emitted: lowering an operand may itself
    // invalidate (a call in an operand clears the table), and the trap is
    // emitted unconditionally — only the arithmetic is shared, never the
    // guard. On a hit the earlier temp is reused and nothing is emitted.
    if (cseAdmits(tag, f64_op, b)) {
        if (cseOperand(a)) |ca| {
            if (cseOperand(b)) |cb| {
                const key = CseKey{ .op = tag, .lhs = ca, .rhs = cb, .f64 = f64_op };
                if (ctx.cse.get(key)) |hit| return hit;
                cse_key = key;
            }
        }
    }
    const t = ctx.freshTemp();
    try ctx.emit(.{
        .op = .binop,
        .result = t,
        .binop = tag,
        .lhs = a,
        .rhs = b,
        .ty = result_ty,
        // The divisor's sign is asked of the SOURCE expression, not of the
        // lowered value: a `dnir.Value` is a slot or an immediate and carries
        // no derivation, while the published fact is keyed on places.
        .divisor = divisorSign(ctx, f64_op, tag, rhs),
        .dividend = dividendSign(ctx, f64_op, tag, lhs),
    });
    if (cse_key) |key| try ctx.cse.put(ctx.alloc, key, .{ .temp = t });
    return .{ .temp = t };
}

/// WHY THE DIVISOR OF THIS OPERATION IS NON-NEGATIVE — as a reference back into
/// the graph, never as a bare `true`.
///
/// `.binding` is the reversible case and the one to prefer: the divisor IS a
/// bound name, so the instruction carries the exact graph entity of its
/// binding and `graph.nonNegativeWidth` gives the width back. A backend
/// reading it can recover the fact, its producer and its width; a backend
/// reading a boolean could recover nothing.
///
/// `.derived` is the compact encoding for a divisor that is not a bare name —
/// a literal, or arithmetic over bound names. Its reversal is stated rather
/// than carried: `graph.nonNegativeWidthOfExpr` over the same `ranges` column
/// and the same divisor expression answers it again. Both ends of that
/// reversal are graph-owned; what the instruction saves is the walk.
///
/// THE DERIVATION IS NOT PERFORMED HERE. This is a BACKEND unit and the
/// derivation is SEMA's; `gate/layering.sh` refuses the edge, and it is right
/// to — a backend re-deriving meaning at emission time is how two places come
/// to decide the same thing and disagree.
fn divisorSign(
    ctx: *LowerCtx,
    f64_op: bool,
    tag: dnir.BinOpTag,
    rhs: *const ast.Expr,
) dnir.DivisorSign {
    if (f64_op) return .unknown;
    if (tag != .idiv and tag != .mod) return .unknown;
    if (floorFixupForced()) return .unknown;
    const relation = ctx.function orelse return .unknown;
    if (rhs.* == .name) {
        const subject = ctx.graph.bindingNamedIn(relation, rhs.name.ident) orelse return .unknown;
        if (ctx.graph.nonNegativeWidth(subject) == null) return .unknown;
        return .{ .binding = subject };
    }
    const width = ctx.graph.nonNegativeWidthOfExpr(relation, rhs) orelse return .unknown;
    return .{ .derived = width };
}

/// WHY THE DIVIDEND OF THIS OPERATION IS NON-NEGATIVE — the mirror of
/// `divisorSign`, asked of the dividend's source expression. Only the
/// truncating `.div` with a constant power-of-two divisor consumes it: a
/// non-negative dividend needs no bias correction, so the backend emits one
/// `lsr` instead of the four-instruction bias+asr. The derivation stays in
/// sema for the same reason as `divisorSign`'s: `gate/layering.sh` refuses
/// the edge, and a backend re-deriving meaning at emission time is how two
/// places come to decide the same thing and disagree.
///
/// IDOL_DIVIDEND_NONNEG_OFF=1 -- THE SEVERING CONTROL for the dividend
/// fact. Set it and no dividend is ever reported non-negative, so every
/// x / 2^a emits the bias-corrected sequence exactly as this compiler did
/// before the dividend fact existed. The producer still publishes its
/// column; only the lowering's question is severed, which is what makes
/// the control a valid consumer-off test: the producer alone changes
/// nothing observable.
fn dividendNonnegOff() bool {
    return std.c.getenv("IDOL_DIVIDEND_NONNEG_OFF") != null;
}

/// IDOL_XORIDIOM_OFF=1 -- THE SEVERING CONTROL for the XOR-idiom lowering
/// (`x + y - 2*(x&y)` to one `eor`). Set it and the idiom never fires, so
/// every site emits exactly as this compiler did before the rule existed:
/// the add/mul/band/sub sequence. The range producer's `xor_idiom` arm is a
/// separate question with its own control (`IDOL_DIVIDEND_NONNEG_OFF` severs
/// the division consumer); severing here changes nothing the producer
/// publishes.
fn xorIdiomOff() bool {
    return std.c.getenv("IDOL_XORIDIOM_OFF") != null;
}

/// IDOL_RANGE_WITNESS=1 -- dump the dividend witness for every proved dividend.
/// Each line names the producer rule and its premises, so every firing of the
/// unsigned-division realization carries a queryable account of why the
/// dividend was believed non-negative.
fn rangeWitnessDump() bool {
    return std.c.getenv("IDOL_RANGE_WITNESS") != null;
}

/// Print the witness for a proved dividend. `subject` is set for the
/// `.binding` face (premise: the published RangeFact); otherwise `relation`
/// and `lhs` identify the derived expression whose witness is queried.
fn dumpDividendWitness(ctx: *LowerCtx, subject: ?semantic_graph.id, relation: ?semantic_graph.id, lhs: *const ast.Expr) void {
    if (subject) |sub| {
        const node = ctx.graph.get(sub) orelse return;
        const name = node.name orelse "?";
        const w = ctx.graph.nonNegativeWidth(sub) orelse return;
        std.debug.print("range-witness binding '{s}' width={d} rule=bound\n", .{ name, w });
        return;
    }
    const rel = relation orelse return;
    const wit = ctx.graph.rangeWitnessOfExpr(ctx.alloc, rel, lhs) catch return orelse return;
    std.debug.print("range-witness expr width={d} rule={s} premises=", .{ wit.width, @tagName(wit.rule) });
    for (wit.premises, 0..) |prem, i| {
        if (i > 0) std.debug.print(",", .{});
        switch (prem) {
            .bound => |b| std.debug.print("bound:{s}(w{d})", .{ b.name, b.width }),
            .literal => |v| std.debug.print("lit:{d}", .{v}),
            .sub => |sw| std.debug.print("sub(w{d},{s})", .{ sw.width, @tagName(sw.rule) }),
        }
    }
    std.debug.print("\n", .{});
}
fn dividendSign(
    ctx: *LowerCtx,
    f64_op: bool,
    tag: dnir.BinOpTag,
    lhs: *const ast.Expr,
) dnir.DivisorSign {
    if (dividendNonnegOff()) return .unknown;
    if (f64_op) return .unknown;
    if (tag != .div) return .unknown;
    const relation = ctx.function orelse return dividendSignModule(ctx, lhs);
    // At module scope the lowerer sets a non-callable relation id; the module
    // column answers there.
    if (!ctx.graph.callable(relation)) return dividendSignModule(ctx, lhs);
    if (lhs.* == .name) {
        const subject = ctx.graph.bindingNamedIn(relation, lhs.name.ident) orelse return .unknown;
        if (ctx.graph.nonNegativeWidth(subject) == null) return .unknown;
        if (rangeWitnessDump()) dumpDividendWitness(ctx, subject, null, lhs);
        return .{ .binding = subject };
    }
    const width = ctx.graph.nonNegativeWidthOfExpr(relation, lhs) orelse return .unknown;
    if (rangeWitnessDump()) dumpDividendWitness(ctx, null, relation, lhs);
    return .{ .derived = width };
}

/// Module-scope dividend: no relation exists, so the module column answers
/// through `nonNegativeWidthOfExprModule`. The relation path above is unchanged.
fn dividendSignModule(ctx: *LowerCtx, lhs: *const ast.Expr) dnir.DivisorSign {
    const width = ctx.graph.nonNegativeWidthOfExprModule(lhs) orelse return .unknown;
    if (rangeWitnessDump()) {
        // Module scope has no relation; the witness is queried against the
        // module root's column.
        const mod_root = ctx.graph.module_root orelse return .{ .derived = width };
        dumpDividendWitness(ctx, null, mod_root, lhs);
    }
    return .{ .derived = width };
}

const UnsignedComparison = struct { ty: RT, fit_lhs: bool, fit_rhs: bool };

/// A comparison whose C common type is `unsigned int`, and which of its
/// operands is not already canonical at that width.
///
/// A `.uint32` operand IS canonical by construction: it is either a `u32`
/// binding (every store refits) or a `u32`-ranked arithmetic result (every such
/// result refits, and `band` is proven not to need one). So only the `.int32`
/// side — a literal, an `i32`/`u8`/`i16` binding, a boolean — can carry bits
/// the comparison must drop.
fn unsignedComparison(
    ctx: *LowerCtx,
    op: ast.BinOp,
    lhs: *const ast.Expr,
    rhs: *const ast.Expr,
) ?UnsignedComparison {
    switch (op) {
        .eq, .neq, .lt, .gt, .leq, .geq => {},
        else => return null,
    }
    const l = exprCRank(ctx, lhs);
    const r = exprCRank(ctx, rhs);
    if (crankJoin(l, r) != .uint32) return null;
    return .{ .ty = .u32, .fit_lhs = l != .uint32, .fit_rhs = r != .uint32 };
}

/// FP argument staging was UNSAFE until the backend stopped homing f64 values in
/// the staging registers, and this is the note left where the guard used to be.
///
/// d0-d7 are both the f64 argument registers and the staging registers, and the
/// backend homed f64 params and locals there, so `p: f64 = 9.0; one(2.0)`
/// destroyed p's home and `two(4.0, p)` swapped two registers through each other
/// and passed (4.0, 4.0). This pass cannot see home assignments, so it could not
/// order the moves; it refused the shapes it could not prove safe instead.
///
/// `allocFpReg` now allocates from d16-d30 and parameters are copied out of
/// d0-d7 on entry whenever the body can call — the same move the integer side
/// has always made out of x0-x7 into x9+. Values and staging no longer share
/// registers, so the hazard is gone at its source and the refusal is retired.
/// Whether this callee takes at least one argument in v0..v7.
fn calleeWantsFpSlots(ctx: *LowerCtx, callee: ?[]const u8) bool {
    const name = callee orelse return false;
    const slots = ctx.fp_params.get(name) orelse return false;
    for (slots) |is_fp| {
        if (is_fp) return true;
    }
    return false;
}

fn emitScalarCallArgs(ctx: *LowerCtx, args: []const *ast.Expr, callee: ?[]const u8) Error!void {
    if (args.len == 0) return;
    if (args.len > max_direct_scalar_args) return bail(ctx.diagnostic, @src());

    // Two phases, deliberately. `mov_arg` writes x0..x7, and evaluating a later
    // argument may itself contain a call that clobbers them: in
    // `sum2(sq(5), sq(4))` argument 0 was parked in x0 and then destroyed by the
    // call for argument 1, so both arguments arrived as sq(4). Evaluate every
    // argument first (into temps/locals, which live in the caller-saved range and
    // survive calls), then marshal them all.
    //
    // A record argument contributes one slot per field, so the slot count is not
    // the argument count.
    var values: [max_direct_scalar_args]dnir.Value = undefined;
    var count: u32 = 0;
    for (args) |arg| {
        if (arg.* == .name) {
            if (scalarRecordForName(ctx, arg.name.ident)) |rec| {
                for (rec.fields) |fname| {
                    if (count >= 8) return bail(ctx.diagnostic, @src());
                    const key = try std.fmt.allocPrint(ctx.alloc, "{s}.{s}", .{ arg.name.ident, fname });
                    defer ctx.alloc.free(key);
                    const field_slot = ctx.locals.get(key) orelse return bail(ctx.diagnostic, @src());
                    values[count] = .{ .local = field_slot };
                    count += 1;
                }
                continue;
            }
            // A positional table argument is passed as one base address. It has
            // to be materialized into frame memory first — the elements are
            // registers until something needs a pointer to them.
            if (nameIsPositionalTable(ctx, arg.name.ident)) {
                if (count >= 8) return bail(ctx.diagnostic, @src());
                values[count] = .{ .local = try materializeTableSlots(ctx, arg.name.ident) };
                count += 1;
                continue;
            }
            if (recordLocalDesc(ctx, arg.name.ident)) |_| {
                if (count >= 8) return bail(ctx.diagnostic, @src());
                values[count] = .{ .local = try materializeRecordBase(ctx, arg.name.ident) };
                count += 1;
                continue;
            }
        }
        if (count >= max_direct_scalar_args) return bail(ctx.diagnostic, @src());
        values[count] = try lowerExpr(ctx, arg);
        count += 1;
    }
    // GAP-056: place each slot in the register FILE its callee reads from.
    // AAPCS64 numbers the two files independently, so they get independent
    // cursors: `f(a: i64, b: f64, c: i64)` is x0, d0, x1.
    const fp_slots: []const bool = if (callee) |name|
        ctx.fp_params.get(name) orelse &.{}
    else
        &.{};
    var gp: u32 = 0;
    var fp: u32 = 0;
    var i: u32 = 0;
    while (i < count) : (i += 1) {
        if (i < fp_slots.len and fp_slots[i]) {
            // Only v0..v7 are marshaled; there is no FP stack-arg extension.
            if (fp >= 8) return bail(ctx.diagnostic, @src());
            try ctx.emit(.{ .op = .fp_mov_arg, .result = fp, .lhs = values[i] });
            fp += 1;
        } else {
            try ctx.emit(.{ .op = .mov_arg, .result = gp, .lhs = values[i] });
            gp += 1;
        }
    }
}

/// The scalar record whose fields are all bound as `name.field` locals, if any.
/// Records are stored exploded — one local per field — so "passing a record"
/// means passing its fields in consecutive argument slots, the same convention
/// the f64 kernel path already uses.
fn scalarRecordForName(ctx: *LowerCtx, name: []const u8) ?dnir.RecordDesc {
    _ = ctx;
    _ = name;
    return null;
}

fn scalarCallLhs(ctx: *LowerCtx, args: []const *ast.Expr, callee: ?[]const u8) Error!dnir.Value {
    if (args.len == 0) return .void;
    // GAP-056, one-argument form. A lone argument is normally handed back as the
    // call's `.lhs`, which the backend stages in x0 — right for an integer,
    // wrong for a double. `p1(x: f64): i64` was as broken as the two-argument
    // case and would have survived a fix aimed only at the loop below.
    if (calleeWantsFpSlots(ctx, callee)) {
        try emitScalarCallArgs(ctx, args, callee);
        return .void;
    }
    if (args.len == 1) {
        const arg = args[0];
        if (arg.* == .table) {
            if (inferRecordNameFromTable(ctx.records, arg)) |rec_name| {
                return try lowerInlineRecordArg(ctx, arg, rec_name);
            }
        }
        // A lone record argument still expands to several slots, so it needs the
        // multi-slot path rather than the single-value one.
        if (arg.* == .name and scalarRecordForName(ctx, arg.name.ident) != null) {
            try emitScalarCallArgs(ctx, args, callee);
            return .void;
        }
        // A lone table argument is passed as its base address, which means
        // materializing the register-exploded elements into frame memory first.
        // `lowerExpr` would hand back the table's own slot, which never holds a
        // value — the elements live in `a.1`, `a.2`, … — so the backend reported
        // it as an undefined name.
        if (arg.* == .name and nameIsPositionalTable(ctx, arg.name.ident)) {
            return .{ .local = try materializeTableSlots(ctx, arg.name.ident) };
        }
        if (try lowerOpaqueRecordLocalArg(ctx, arg)) |materialized| return materialized;
        return try lowerExpr(ctx, arg);
    }
    try emitScalarCallArgs(ctx, args, callee);
    return .void;
}

/// Whether `expr` is provably an integer, which is the constant the `"%lld"`
/// emitter below assumes. It is a POSITIVE test on purpose: "not f64 and not
/// str" accepted a table base and a pointer, and `to(str)` on either printed
/// the ADDRESS in decimal — a plausible-looking string with no relation to the
/// value. Anything this cannot prove declines to the general path.
fn exprIsIntegral(ctx: *LowerCtx, expr: *const ast.Expr) bool {
    // A concat is NEVER integral — the `.binop` arm below already answers
    // false for it — and this guard must run BEFORE the `exprIsStr` preamble
    // because that call re-descends the whole chain. Together with
    // `concatOperandClass`, one descent per concat level is what keeps a
    // 20-hole chain linear instead of exponential.
    if (expr.* == .binop and expr.binop.op == .concat) return false;
    if (exprTouchesF64(ctx, expr)) return false;
    if (exprIsStr(ctx, expr)) return false;
    if (applicationFirstResultDescriptor(ctx, expr)) |descriptor| return descriptor.is_integer();
    return switch (expr.*) {
        .int_lit, .true_lit, .false_lit => true,
        // `#s` is a length and `s[i]` is a byte — both integers.
        .unop => |u| if (u.op == .len)
            exprIsStr(ctx, u.operand)
        else
            exprIsIntegral(ctx, u.operand),
        .binop => |b| b.op != .concat and
            exprIsIntegral(ctx, b.lhs) and exprIsIntegral(ctx, b.rhs),
        .index => true,
        // A plain call to a function that returns neither str nor f64 nor a
        // record. `exprTouchesF64` above already excluded the float kernels.
        .call => |cc| cc.func.* == .name and
            !functionResultIs(ctx, cc.func.name.ident, .str) and
            !ctx.func_record_returns.contains(cc.func.name.ident),
        .name => |n| blk: {
            switch (graphNameDescriptor(ctx, expr)) {
                .known => |descriptor| break :blk descriptor.is_integer(),
                .unknown, .unvisited => {},
            }
            const slot = ctx.locals.get(n.ident) orelse {
                // A module-level constant is not a local, so the elimination
                // tail below can never see it — the same residency gap
                // `exprIsStr`'s `.name` arm already paid for. The VALUE arm
                // folds `n` through `module_consts.ints` (see the `.name`
                // lowering arm), so the type answer has to follow the value:
                // without this, `cap={vocab_cap}` lowered fine and the concat
                // predicate still refused the whole chain.
                if (ctx.module_globals.types.get(n.ident)) |ty| break :blk ty.is_integer();
                break :blk ctx.module_consts.ints.contains(n.ident);
            };
            // This tail is the one place in predicate that answers by
            // ELIMINATION, against the doc comment above it. Every face it does
            // not name is admitted as an integer, so a face ADDED anywhere else
            // in the compiler becomes a wrong answer here by default — which is
            // exactly how the byte sequence arrived (GAP-207).
            break :blk !ctx.f64_slots.contains(slot) and
                !ctx.str_slots.contains(slot) and
                !ctx.ptr_slots.contains(slot) and
                !ctx.byteseq_slots.contains(slot) and
                !nameIsPositionalTable(ctx, n.ident);
        },
        .if_expr => |ie| exprIsIntegral(ctx, ie.then_expr) and exprIsIntegral(ctx, ie.else_expr),
        .method_call => |mc| blk: {
            if (std.mem.eql(u8, mc.method, "len") and mc.args.len == 0)
                break :blk exprIsStr(ctx, mc.obj);
            if (std.mem.eql(u8, mc.method, "byte") and mc.args.len >= 1 and mc.args.len <= 2)
                break :blk exprIsStr(ctx, mc.obj);
            break :blk false;
        },
        else => false,
    };
}

/// THE f64->i64 conversion law, total. Truncation toward zero; NaN
/// answers 0; out-of-range saturates the way the hardware does:
/// positive (including +inf) answers INT64_MAX, negative (including
/// -inf) answers INT64_MIN. This is exactly what ARM64 fcvtzs
/// computes — measured against the instruction itself — and the
/// constant folder must answer identically: Zig `@intFromFloat` is
/// undefined on nonfinite/out-of-range inputs, so a folder that calls
/// it directly is not a law but a host accident. One law, two
/// realizations — the folder here and the `.conv` instruction the
/// dynamic arm emits.
fn foldF64ToI64(x: f64) i64 {
    if (std.math.isNan(x)) return 0;
    const two63: f64 = 9.223372036854776e18;
    if (x >= two63) return std.math.maxInt(i64);
    if (x < -two63) return std.math.minInt(i64);
    return @intFromFloat(@trunc(x));
}

/// Numeric type conversion for `:to` and `:from`.
/// `x:to(f64)` converts numeric x to f64; `f64:from(x)` does the same.
/// Pure value conversion, not bootstrap-gated.
fn lowerNumericConvert(
    ctx: *LowerCtx,
    value_expr: *const ast.Expr,
    target_name: []const u8,
    consumption: types.ReturnConsumption,
) Error!dnir.Value {
    const v = try lowerExpr(ctx, value_expr);
    if (std.mem.eql(u8, target_name, "f64")) {
        switch (v) {
            .i64 => |n| {
                if (consumption == .discard) return .void;
                return dnir.Value{ .f64 = @floatFromInt(n) };
            },
            .f64 => {
                if (consumption == .discard) return .void;
                return v;
            },
            else => {
                if (consumption == .discard) return .void;
                // A dynamic i64->f64 is a conversion, not an addition:
                // the old `v + 0.0` binop only converted by accident,
                // on its way to an fadd the law never asked for.
                if (exprIsIntegral(ctx, value_expr)) {
                    const t = ctx.freshTemp();
                    try ctx.emit(.{ .op = .conv, .result = t, .lhs = v, .ty = .f64 });
                    return dnir.Value{ .temp = t };
                }
                const t = try binopTemp(ctx, .add, v, .{ .f64 = 0.0 });
                return dnir.Value{ .temp = t };
            },
        }
    }
    if (std.mem.eql(u8, target_name, "i64")) {
        switch (v) {
            .f64 => |x| {
                if (consumption == .discard) return .void;
                return dnir.Value{ .i64 = foldF64ToI64(x) };
            },
            .i64 => {
                if (consumption == .discard) return .void;
                return v;
            },
            else => {
                if (consumption == .discard) return .void;
                // A dynamic f64->i64 must CONVERT (fcvtzs). Returning
                // the f64 temp unchanged left the consumer's crossFile
                // fmov to move the BITS into a GP register: a silent
                // wrong answer (2.7 -> 4613262278296967578). Non-f64
                // subjects keep the old shape; they are not numeric
                // conversions and must not reach the converter.
                if (exprIsF64(ctx, value_expr)) {
                    const t = ctx.freshTemp();
                    try ctx.emit(.{ .op = .conv, .result = t, .lhs = v, .ty = .i64 });
                    return dnir.Value{ .temp = t };
                }
                return v;
            },
        }
    }
    return invalidGraphFacts(ctx.diagnostic, @src(), "unsupported-conversion");
}

/// `value:to(i64)` — bootstrap text-to-integer edge for gate transport scripts.
fn lowerSubjectTo(
    ctx: *LowerCtx,
    subject: *const ast.Expr,
    target: *const ast.Expr,
    consumption: types.ReturnConsumption,
) Error!dnir.Value {
    if (target.* != .name) {
        return invalidGraphFacts(ctx.diagnostic, @src(), "unsupported-conversion");
    }
    if (std.mem.eql(u8, target.name.ident, "i64")) {
        // THE SUBJECT MUST BE TEXT, and this arm did not ask. `duo_str_to_i64`
        // takes a `const char*` (`src/idol_str_bootstrap.c`), so a non-text
        // subject is DEREFERENCED AS AN ADDRESS: `x = 42 ; x:to(i64)` built,
        // linked, and SEGFAULTED (exit 139, reproduced 3 of 3 — measured in
        // idol-native/docs/edge-canon.md §2.6).
        //
        // The `str` arm below is the template: it refuses a subject it cannot
        // prove integral, for exactly this reason and with exactly this
        // diagnostic. The two arms of one conversion table disagreed about
        // whether checking the subject was their job, and the arm that did not
        // check is the one that produced undefined behaviour rather than a
        // refusal. A conversion that cannot be performed must be REFUSED, not
        // emitted and left to the loader.
        if (!exprIsStr(ctx, subject)) {
            return invalidGraphFacts(ctx.diagnostic, @src(), "unsupported-conversion");
        }
        const s = try lowerExpr(ctx, subject);
        try ensureExtern(ctx, "compat", "str", "duo_str_to_i64");
        if (consumption == .discard) {
            try ctx.emit(.{ .op = .call_extern, .callee = "duo_str_to_i64", .lhs = s, .ty = .i64 });
            return .void;
        }
        const t = ctx.freshTemp();
        try ctx.emit(.{ .op = .call_extern, .result = t, .callee = "duo_str_to_i64", .lhs = s, .ty = .i64 });
        return .{ .temp = t };
    }
    // THE OTHER HALF OF THE SAME EDGE. `str -> i64` was here and `str -> f64`
    // was nowhere, in either spelling, so a lexer could scan a well-formed
    // float literal and had no way to say what it was worth —
    // `lib/compiler/lexer.id` refuses on exactly this, at its ONE `to(f64)`.
    //
    // The subject check is the `i64` arm's, for the reason that arm records at
    // length: `duo_str_to_f64` takes a `const char*`, so a non-text subject is
    // DEREFERENCED AS AN ADDRESS. A conversion that cannot be performed is
    // refused, never emitted and left to the loader.
    if (std.mem.eql(u8, target.name.ident, "f64")) {
        if (!exprIsStr(ctx, subject)) {
            return invalidGraphFacts(ctx.diagnostic, @src(), "unsupported-conversion");
        }
        const s = try lowerExpr(ctx, subject);
        try ensureExtern(ctx, "compat", "str", "duo_str_to_f64");
        if (consumption == .discard) {
            try ctx.emit(.{ .op = .call_extern, .callee = "duo_str_to_f64", .lhs = s, .ty = .f64 });
            return .void;
        }
        const t = ctx.freshTemp();
        try ctx.emit(.{ .op = .call_extern, .result = t, .callee = "duo_str_to_f64", .lhs = s, .ty = .f64 });
        return .{ .temp = t };
    }
    if (std.mem.eql(u8, target.name.ident, "str")) {
        if (!exprIsIntegral(ctx, subject)) {
            return invalidGraphFacts(ctx.diagnostic, @src(), "unsupported-conversion");
        }
        const n = try lowerExpr(ctx, subject);
        const buf = try emitIntToStr(ctx, n);
        if (consumption == .discard) return .void;
        return .{ .temp = buf };
    }
    return invalidGraphFacts(ctx.diagnostic, @src(), "unsupported-conversion");
}

/// `mem.load(T)(p)` / `mem.store(T)(p,v)` — extract the type tag from the
/// type-descriptor argument so the backend can emit the right-width load/store.
fn lowerMemType(ctx: *LowerCtx, type_expr: *const ast.Expr) ?RT {
    _ = ctx;
    if (type_expr.* == .name) {
        const name = type_expr.name.ident;
        if (std.mem.eql(u8, name, "f64")) return .f64;
        if (std.mem.eql(u8, name, "f32")) return .f32;
        if (std.mem.eql(u8, name, "i64")) return .i64;
        if (std.mem.eql(u8, name, "u64")) return .i64;
        if (std.mem.eql(u8, name, "i32") or std.mem.eql(u8, name, "u32")) return .i64;
        if (std.mem.eql(u8, name, "i8") or std.mem.eql(u8, name, "u8")) return .any;
    }
    // `"f64"` / `"f32"` — quoted-string type spelling used by the engine.
    if (type_expr.* == .quoted) {
        const lit = type_expr.quoted.val;
        if (std.mem.eql(u8, lit, "f64")) return .f64;
        if (std.mem.eql(u8, lit, "f32")) return .f32;
        if (std.mem.eql(u8, lit, "i64")) return .i64;
        if (std.mem.eql(u8, lit, "u64")) return .i64;
        if (std.mem.eql(u8, lit, "i32") or std.mem.eql(u8, lit, "u32")) return .i64;
        if (std.mem.eql(u8, lit, "i8") or std.mem.eql(u8, lit, "u8")) return .any;
    }
    return null;
}

/// A CALLER'S BYTE OFFSET AS THE BACKEND'S 1-BASED ELEMENT INDEX.
///
/// `load_index`/`store_index` at `.ty = .i64` address `base + (idx - 1) * 8`;
/// the `mem` faces take a 0-based BYTE offset, the same one `codegen.zig`
/// spells `(uint8_t*)p + off`. Both conversions therefore have to happen — the
/// scale down by 8 and the 1-based bias — and they have to happen in ONE place,
/// because the read and the write of the same buffer disagreeing about its
/// origin is exactly the defect this helper was extracted to end.
fn lowerScaledElementIndex(ctx: *LowerCtx, off_expr: *const ast.Expr) Error!dnir.Value {
    if (off_expr.* == .binop) {
        const b = off_expr.binop;
        if (b.op == .mul) {
            if (b.rhs.* == .int_lit and b.rhs.int_lit.val == 8) {
                const base = try lowerExpr(ctx, b.lhs);
                const idx = ctx.freshTemp();
                try ctx.emit(.{ .op = .binop, .result = idx, .binop = .add, .lhs = base, .rhs = .{ .i64 = 1 } });
                return .{ .temp = idx };
            }
            if (b.lhs.* == .int_lit and b.lhs.int_lit.val == 8) {
                const base = try lowerExpr(ctx, b.rhs);
                const idx = ctx.freshTemp();
                try ctx.emit(.{ .op = .binop, .result = idx, .binop = .add, .lhs = base, .rhs = .{ .i64 = 1 } });
                return .{ .temp = idx };
            }
        }
        if (b.op == .lshift) {
            if (b.rhs.* == .int_lit and b.rhs.int_lit.val == 3) {
                const base = try lowerExpr(ctx, b.lhs);
                const idx = ctx.freshTemp();
                try ctx.emit(.{ .op = .binop, .result = idx, .binop = .add, .lhs = base, .rhs = .{ .i64 = 1 } });
                return .{ .temp = idx };
            }
        }
    }
    const off = try lowerExpr(ctx, off_expr);
    const scaled = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = scaled, .binop = .div, .lhs = off, .rhs = .{ .i64 = 8 } });
    const idx = ctx.freshTemp();
    try ctx.emit(.{ .op = .binop, .result = idx, .binop = .add, .lhs = .{ .temp = scaled }, .rhs = .{ .i64 = 1 } });
    return .{ .temp = idx };
}

/// `to(str)(n)` — integer to decimal text. malloc(24) + snprintf(buf, 24,
/// "%lld", n): three named arguments in x0..x2 and the value in the VARIADIC
/// TAIL, which on Apple ARM64 travels on the stack.
fn lowerToStr(ctx: *LowerCtx, c: anytype) Error!?dnir.Value {
    if (c.args.len != 1) return null;
    if (c.func.* != .call) return null;
    const inner = c.func.call;
    if (inner.func.* != .name or !std.mem.eql(u8, inner.func.name.ident, "to")) return null;
    if (inner.args.len != 1 or inner.args[0].* != .name) return null;
    if (!std.mem.eql(u8, inner.args[0].name.ident, "str")) return null;
    // Decline rather than mis-lower. `"%lld"` is a constant this emitter
    // ASSUMES, and it held for exactly one argument shape: `to(str)(1.5)`
    // printed 4378777232 and `to(str)("hi")` printed 4343729785 — both the
    // operand's ADDRESS, both indistinguishable from a real answer.
    if (!exprIsIntegral(ctx, c.args[0])) return null;

    const n = try lowerExpr(ctx, c.args[0]);
    return .{ .temp = try emitIntToStr(ctx, n) };
}

/// Render an already-lowered INTEGER value as decimal text, and answer the temp
/// holding the buffer.
///
/// Shared by `to(str)(n)` and by `..`, on purpose: two emitters for "number to
/// decimal" is two chances to disagree with the C backend, and the caller is
/// responsible for having proved the value is an integer — `"%lld"` is a
/// constant this assumes and cannot check from a register.
fn emitIntToStr(ctx: *LowerCtx, n: dnir.Value) Error!u32 {
    try ensureExtern(ctx, "mem", "alloc", "malloc");
    try ensureExtern(ctx, "string", "format", "snprintf");
    const buf = ctx.freshTemp();
    try ctx.emit(.{ .op = .call_extern, .result = buf, .callee = "malloc", .lhs = .{ .i64 = 24 } });
    try ctx.emit(.{ .op = .mov_arg, .result = 0, .lhs = .{ .temp = buf } });
    try ctx.emit(.{ .op = .mov_arg, .result = 1, .lhs = .{ .i64 = 24 } });
    try ctx.emit(.{ .op = .mov_arg, .result = 2, .lhs = .{ .str = "%lld" } });
    // `n` is past snprintf's last NAMED parameter, so it is a VARIADIC-tail
    // argument. Apple's ARM64 ABI passes that tail on the stack, not in x3;
    // `.field = "vararg"` tells the backend to stage it there. Staging it as
    // an ordinary fourth register argument assembles to textbook-correct code
    // and still prints a pointer, because snprintf never reads x3.
    try ctx.emit(.{ .op = .mov_arg, .result = 0, .field = "vararg", .lhs = n });
    try ctx.emit(.{ .op = .call_extern, .callee = "snprintf" });
    return buf;
}

/// `a.b.c` -> "a.b.c" into `out`. False for anything not a pure name chain.
fn flattenNames(alloc: std.mem.Allocator, e: *const ast.Expr, out: *std.ArrayList(u8)) !bool {
    switch (e.*) {
        .name => |n| {
            try out.appendSlice(alloc, n.ident);
            return true;
        },
        .field => |fl| {
            if (!try flattenNames(alloc, fl.obj, out)) return false;
            try out.append(alloc, '.');
            try out.appendSlice(alloc, fl.field);
            return true;
        },
        else => return false,
    }
}

fn lowerNamedDirectCall(
    ctx: *LowerCtx,
    callee: []const u8,
    args: []const *ast.Expr,
    consumption: types.ReturnConsumption,
) Error!dnir.Value {
    const discard = consumption == .discard;
    try emitScalarCallArgs(ctx, args, callee);
    if (discard) {
        try ctx.emit(.{ .op = .call_direct, .callee = callee, .lhs = .void });
        return .void;
    }
    const t = ctx.freshTemp();
    try ctx.emit(.{ .op = .call_direct, .result = t, .callee = callee, .lhs = .void });
    return .{ .temp = t };
}

fn tryLowerRelationEdgeCall(
    ctx: *LowerCtx,
    expr: *const ast.Expr,
    consumption: types.ReturnConsumption,
) Error!?dnir.Value {
    if (ctx.require_graph_facts) return null;
    if (expr.* != .call) return null;
    const c = expr.call;
    if (c.func.* != .call) return null;
    const inner = c.func.call;
    if (inner.func.* != .name or inner.args.len != 1 or c.args.len != 1) return null;
    const sym = ctx.relation_edges.get(inner.func.name.ident) orelse return null;
    const args = [_]*ast.Expr{ inner.args[0], c.args[0] };
    return try lowerNamedDirectCall(ctx, sym, &args, consumption);
}

/// Subject-first relation edge — `path:len(min)` fuses to `len__path(path, min)`.
fn tryLowerSubjectRelationEdgeCall(
    ctx: *LowerCtx,
    expr: *const ast.Expr,
    consumption: types.ReturnConsumption,
) Error!?dnir.Value {
    if (ctx.require_graph_facts) return null;
    if (expr.* != .method_call) return null;
    const mc = expr.method_call;
    const sym = ctx.relation_edges.get(mc.method) orelse return null;
    if (mc.args.len != 1) return null;
    const args = [_]*ast.Expr{ mc.obj, mc.args[0] };
    return try lowerNamedDirectCall(ctx, sym, &args, consumption);
}

/// `print(v)` spelled as host egress — the same node `stdout:write(v)` reaches.
///
/// This is a SHAPE test, never an identity. It is consulted only to decide
/// which of two available lowerings wins, and THE PUBLISHED APPLICATION FACT
/// ALWAYS WINS: `native_bootstrap` recognizes this shape in every module now,
/// so a module that declares its own `print` relation would otherwise have its
/// call answered with host output — one relation silently swapped for another,
/// which is the class that passes `idol check`.
fn hostEgressCall(expr: *const ast.Expr) bool {
    if (expr.* != .call) return false;
    const c = expr.call;
    if (c.func.* != .name) return false;
    return std.mem.eql(u8, c.func.name.ident, "print");
}

fn lowerCall(ctx: *LowerCtx, expr: *const ast.Expr, consumption: types.ReturnConsumption) Error!dnir.Value {
    if (expr.* != .call) return bail(ctx.diagnostic, @src());
    if (ctx.occurrences.get(expr)) |application| {
        if (ctx.require_graph_facts and
            (hostEgressCall(expr) or !ctx.graph.isBootstrapApplicationNode(application.application)))
        {
            return lowerCheckedScalarCall(ctx, application, consumption);
        }
    }
    if (ctx.require_graph_facts and !ctx.graph.bootstrapApplicationExpr(expr)) {
        return refuseMissingApplication(ctx, @src(), expr);
    }
    const c = expr.call;
    if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "write") and c.args.len == 2) {
        return lowerStreamWrite(ctx, c.args[0], c.args[1]);
    }
    if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "close") and c.args.len == 1) {
        return lowerStreamClose(ctx, c.args[0]);
    }
    if (try tryLowerRelationEdgeCall(ctx, expr, consumption)) |value| return value;
    const discard = consumption == .discard;
    if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "gatecap") and c.args.len == 1) {
        const arg = try lowerExpr(ctx, c.args[0]);
        try ensureExtern(ctx, "gate", "cap", "idol_process_capture");
        const t = ctx.freshTemp();
        try ctx.emit(.{ .op = .call_extern, .result = t, .callee = "idol_process_capture", .lhs = arg, .ty = .str });
        return .{ .temp = t };
    }
    if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "incarnation") and c.args.len == 0) {
        try ensureExtern(ctx, "os", "incarnation", "idol_incarnation");
        const t = ctx.freshTemp();
        try ctx.emit(.{ .op = .call_extern, .result = t, .callee = "idol_incarnation", .ty = .str });
        return .{ .temp = t };
    }
    if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "execap") and c.args.len == 3) {
        const eprog = try lowerExprCons(ctx, c.args[0], .single);
        const eargs = try lowerExprCons(ctx, c.args[1], .single);
        const einput = try lowerExprCons(ctx, c.args[2], .single);
        try ensureExtern(ctx, "process", "execap", "idol_process_execap");
        try ctx.emit(.{ .op = .mov_arg, .result = 0, .lhs = eprog });
        try ctx.emit(.{ .op = .mov_arg, .result = 1, .lhs = eargs });
        try ctx.emit(.{ .op = .mov_arg, .result = 2, .lhs = einput });
        const t = ctx.freshTemp();
        try ctx.emit(.{ .op = .call_extern, .result = t, .callee = "idol_process_execap", .ty = .str });
        return .{ .temp = t };
    }
    if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "procrun") and c.args.len == 3) {
        const eprog = try lowerExprCons(ctx, c.args[0], .single);
        const eargs = try lowerExprCons(ctx, c.args[1], .single);
        const einput = try lowerExprCons(ctx, c.args[2], .single);
        try ensureExtern(ctx, "process", "procrun", "idol_process_procrun");
        try ctx.emit(.{ .op = .mov_arg, .result = 0, .lhs = eprog });
        try ctx.emit(.{ .op = .mov_arg, .result = 1, .lhs = eargs });
        try ctx.emit(.{ .op = .mov_arg, .result = 2, .lhs = einput });
        const t = ctx.freshTemp();
        try ctx.emit(.{ .op = .call_extern, .result = t, .callee = "idol_process_procrun", .ty = .str });
        return .{ .temp = t };
    }
    if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "monotime") and c.args.len == 0) {
        try ensureExtern(ctx, "os", "monotime", "idol_os_monotime");
        const t = ctx.freshTemp();
        try ctx.emit(.{ .op = .call_extern, .result = t, .callee = "idol_os_monotime", .ty = .i64 });
        return .{ .temp = t };
    }
    if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "filesize") and c.args.len == 1) {
        const epath = try lowerExprCons(ctx, c.args[0], .single);
        try ensureExtern(ctx, "os", "filesize", "idol_os_filesize");
        try ctx.emit(.{ .op = .mov_arg, .result = 0, .lhs = epath });
        const t = ctx.freshTemp();
        try ctx.emit(.{ .op = .call_extern, .result = t, .callee = "idol_os_filesize", .ty = .i64 });
        return .{ .temp = t };
    }
    if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "sha256file") and c.args.len == 1) {
        const epath = try lowerExprCons(ctx, c.args[0], .single);
        try ensureExtern(ctx, "os", "sha256file", "idol_os_sha256file");
        try ctx.emit(.{ .op = .mov_arg, .result = 0, .lhs = epath });
        const t = ctx.freshTemp();
        try ctx.emit(.{ .op = .call_extern, .result = t, .callee = "idol_os_sha256file", .ty = .str });
        return .{ .temp = t };
    }

    if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "__as") and c.args.len == 2) {
        if (c.args[0].* != .quoted) return invalidGraphFacts(ctx.diagnostic, @src(), "as-target-not-type");
        const target = c.args[0].quoted.val;
        // The legacy magic spellings route to the same producer law as
        // the canonical :to/:from faces: one law, every spelling.
        if (std.mem.eql(u8, target, "f64") or std.mem.eql(u8, target, "i64")) {
            return lowerNumericConvert(ctx, c.args[1], target, consumption);
        }
        return try lowerExpr(ctx, c.args[1]);
    }

    // `tostring(n)` — the runtime/global-call spelling. Canonical Idol has no
    // such binding; it is a seeded global in `seedGlobalNames` so `scope.lookup`
    // finds it, but it has no application fact, so `ctx.occurrences.get` returns
    // null and the graph-facts guard below refuses it as `missing-application-id`.
    // Recognizing it here bypasses the graph path for this one builtin and
    // delegates to `emitIntToStr`, which is shared with `to(str)(n)` — the
    // canonical Idol spelling this is an alias for.
    if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "tostring") and
        c.args.len == 1)
    {
        if (exprIsIntegral(ctx, c.args[0])) {
            const n = try lowerExpr(ctx, c.args[0]);
            return .{ .temp = try emitIntToStr(ctx, n) };
        }
        // Non-integral operand: fall through to lowerToStr which handles the
        // null return (not a to(str) call, returns null), and the graph-facts
        // guard will refuse with "missing-application-id" for the same reason.
    }
    if (try lowerToStr(ctx, c)) |v| return v;
    if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "to") and c.args.len == 2) {
        return lowerSubjectTo(ctx, c.args[0], c.args[1], consumption);
    }
    // `to(T)(x)` FOR EVERY OTHER T. `lowerToStr` above answers the one target
    // it was written for and declines the rest by returning null, which left
    // the curried face with no route to the conversion table `x:to(T)` and
    // `to(x, T)` both already reach. Three spellings of one edge, and only two
    // of them arrived — so the same conversion refused or answered depending on
    // how it was written, which is the capability tax §10.2 forbids.
    if (c.args.len == 1 and c.func.* == .call) {
        const inner = c.func.call;
        if (inner.func.* == .name and std.mem.eql(u8, inner.func.name.ident, "to") and
            inner.args.len == 1 and inner.args[0].* == .name)
        {
            return lowerSubjectTo(ctx, c.args[0], inner.args[0], consumption);
        }
    }
    // `mem.load(T)(p)` / `mem.store(T)(p, v)` — the CURRIED spelling the engine
    // uses.  A curried call `f(a)(b)` is a `.call` whose `func` is another
    // `.call`, NOT a `.field`, so the field handler below never sees it.  This
    // must live HERE (inside `lowerCall`, before `.field` is checked) and must
    // check the inner call's `.name` spelling, not a projected fact.
    //
    // Three spellings:
    //
    // Spelling A — flat `mem.load(T, p)` / `mem.store(T, p, v)`:
    //   c.func.* == .call
    //   c.func.call.func.* == .name "mem"
    //   c.func.call.args[0].* == .name "load" / "store"
    //   c.args[0].* == pointer (fb)
    //   c.args[1].* == type ("f64")  [c.args[2] == value for store]
    //
    // Spelling B — curried `mem.load(T)(p)`:
    //   c.func.* == .method_call  (the outer `(p)` wraps the method call)
    //   c.func.method_call.obj.* == .name "mem"
    //   c.func.method_call.method == "load"
    //   c.func.method_call.args[0].* == .name "f64"
    //   c.args[0].* == pointer (fb)
    //
    // Spelling C — curried `mem.store(T)(p, v)`:
    //   c.func.* == .method_call
    //   c.func.method_call.method == "store"
    //   c.func.method_call.args[0].* == .name "f64"
    //   c.args[0].* == pointer (fb)
    //   c.args[1].* == value (3.14)
    //
    // Pointer-first args: the engine's flat `mem.load(T, p)` has type at
    // c.args[0] and pointer at c.args[1]; the canonical sema order is
    // pointer-first, so swap when lowering to load_index.
    if (c.func.* == .call and c.args.len >= 2) {
        const inner = c.func.call;
        // Spelling A: inner.func is `.name` `mem`
        if (inner.func.* == .name and std.mem.eql(u8, inner.func.name.ident, "mem") and
            inner.args.len == 1 and inner.args[0].* == .name)
        {
            const op = inner.args[0].name.ident;
            if (std.mem.eql(u8, op, "load") and c.args.len == 2) {
                const ptr = try lowerExpr(ctx, c.args[0]);
                const t = ctx.freshTemp();
                const ty: RT = lowerMemType(ctx, c.args[1]) orelse .i64;
                try ctx.emit(.{ .op = .load_index, .result = t, .ty = ty, .lhs = ptr, .rhs = .{ .i64 = 1 } });
                return .{ .temp = t };
            }
            if (std.mem.eql(u8, op, "store") and c.args.len == 3) {
                const ptr = try lowerExpr(ctx, c.args[0]);
                const val = try lowerExpr(ctx, c.args[1]);
                const ty: RT = lowerMemType(ctx, c.args[2]) orelse .i64;
                try ctx.emit(.{ .op = .store_index, .ty = ty, .lhs = ptr, .rhs = .{ .i64 = 1 }, .third = val });
                return .void;
