test "dnir_lower: pointer descriptors cross checked applications" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const source =
        \\make: *u8 = (size: i64)
        \\    mem.alloc(size)
        \\pass: *u8 = (value: *u8)
        \\    value
        \\poke: i64 = (value: *u8)
        \\    mem.write_byte(value, 3, 77)
        \\    0
        \\main: i64 = ()
        \\    first: *u8 = make(8)
        \\    second: *u8 = pass(first)
        \\    mem.zero(second, 8)
        \\    ignored = poke(second)
        \\    answer = mem.read_byte(first, 3)
        \\    mem.free(first)
        \\    answer + ignored
    ;
    var lexer = @import("../lexer.zig").Lexer.init(source, "pointer-transport.id");
    var parser = @import("../parser.zig").Parser.init(&lexer, alloc);
    parser.idol_mode = true;
    var module = try parser.parse_module();
    var checked = @import("../sema.zig").Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    try checked.check_module(&module);
    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    _ = try graph.liftModuleWithCheckedCalls(&module, &checked, "pointer-transport.id");

    var diagnostic: Diagnostic = .{};
    const lowered = try lowerModuleWithGraphObserved(alloc, &module, &graph, &diagnostic);
    defer dnir.deinitModule(alloc, lowered);

    var pointer_returns: usize = 0;
    var pointer_parameters: usize = 0;
    var pointer_applications: usize = 0;
    for (lowered.functions) |function| {
        if (function.ret == .pointer) pointer_returns += 1;
        for (function.params) |parameter| {
            if (parameter.ty == .pointer) pointer_parameters += 1;
        }
        for (function.blocks) |block| {
            for (block.instrs) |instruction| {
                if (instruction.application != null and instruction.ty == .pointer) {
                    pointer_applications += 1;
                    try std.testing.expect(instruction.ty.eql(
                        graph.applicationDescriptor(instruction.application.?).?,
                    ));
                }
            }
        }
    }
    try std.testing.expectEqual(@as(usize, 2), pointer_returns);
    try std.testing.expectEqual(@as(usize, 2), pointer_parameters);
    try std.testing.expectEqual(@as(usize, 2), pointer_applications);

    // Damage control: the operand descriptor is the authority. If it no longer
    // says pointer, physical lowering must refuse rather than infer an address
    // from the source annotation or the register that happens to carry it.
    var pass_application: ?semantic_graph.id = null;
    for (graph.application_facts.items) |fact| {
        const relation = graph.applicationRelation(fact.application) orelse continue;
        const name = (graph.get(relation) orelse continue).name orelse continue;
        if (std.mem.eql(u8, name, "pass")) pass_application = fact.application;
    }
    const application = pass_application orelse return error.TestExpectedEqual;
    // SLOT-ROLE-ONE: `pass(first)` promotes `first` to the subject slot, so the
    // pointer travels as the subject, not an ordinary operand.
    const subject = graph.applicationSubject(application) orelse return error.TestExpectedEqual;
    try std.testing.expectEqual(@as(usize, 0), graph.applicationArguments(application).?.len);
    graph.nodes.items[subject].descriptor = .nil;
    diagnostic.reset();
    try std.testing.expectError(
        error.GraphFactsInvalid,
        lowerModuleWithGraphObserved(alloc, &module, &graph, &diagnostic),
    );
    try std.testing.expectEqualStrings("application-operand-abi", diagnostic.note().?);
}

test "dnir_lower: graph result pack crosses one checked application" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const source =
        \\pair(n: i64): (i64, i64)
        \\    return n, n + 1
        \\main: i64 = ()
        \\    a, b = pair(40)
        \\    a + b
    ;
    var lexer = @import("../lexer.zig").Lexer.init(source, "result-pack.id");
    var parser = @import("../parser.zig").Parser.init(&lexer, alloc);
    parser.idol_mode = true;
    var module = try parser.parse_module();
    var checked = @import("../sema.zig").Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    try checked.check_module(&module);
    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    _ = try graph.liftModuleWithCheckedCalls(&module, &checked, "result-pack.id");

    var diagnostic: Diagnostic = .{};
    const lowered = try lowerModuleWithGraphObserved(alloc, &module, &graph, &diagnostic);
    defer dnir.deinitModule(alloc, lowered);
    const application = graph.applications()[0];
    const results = graph.applicationResults(application.application) orelse
        return error.TestExpectedEqual;
    try std.testing.expectEqual(@as(usize, 2), results.len);

    var saw_return = false;
    var saw_call = false;
    for (lowered.functions) |function| {
        if (std.mem.indexOf(u8, function.name, "pair") != null) {
            try std.testing.expectEqual(@as(usize, 2), function.ret_pack.len);
            for (function.blocks[0].instrs) |instruction| {
                if (instruction.op == .ret_pack) {
                    saw_return = true;
                    try std.testing.expectEqual(@as(usize, 2), instruction.vals.len);
                }
            }
        }
        for (function.blocks[0].instrs) |instruction| {
            if (instruction.application != application.application) continue;
            saw_call = true;
            try std.testing.expectEqual(@as(usize, 2), instruction.pack_results.len);
            try std.testing.expect(instruction.result == null);
            for (instruction.pack_results, results) |projected, result| {
                try std.testing.expectEqual(result, projected.value);
                try std.testing.expect(projected.temp != null);
                try std.testing.expect(projected.ty.eql(graph.get(result).?.descriptor.?));
            }
        }
    }
    try std.testing.expect(saw_return);
    try std.testing.expect(saw_call);
    try std.testing.expect(dnir.moduleIsNativeDirectReady(lowered));

    // Damage control: a floating member belongs to the FP result file, which
    // this GP realization does not implement. Changing the graph fact must turn
    // the lowering red instead of silently reading x1 as if it were d1.
    const saved = graph.nodes.items[results[1]].descriptor;
    graph.nodes.items[results[1]].descriptor = .f64;
    defer graph.nodes.items[results[1]].descriptor = saved;
    diagnostic.reset();
    try std.testing.expectError(
        error.GraphFactsInvalid,
        lowerModuleWithGraphObserved(alloc, &module, &graph, &diagnostic),
    );
    try std.testing.expectEqualStrings("application-result-abi", diagnostic.note().?);
}

test "dnir_lower: checked module operand consumes graph binding edge" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const source =
        \\total: i64 = 3
        \\total = total + 4
        \\take: i64 = (value: i64)
        \\    value
        \\main: i64 = ()
        \\    take(total)
    ;
    var lexer = @import("../lexer.zig").Lexer.init(source, "module-operand.id");
    var parser = @import("../parser.zig").Parser.init(&lexer, alloc);
    parser.idol_mode = true;
    var module = try parser.parse_module();
    var checked = @import("../sema.zig").Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    try checked.check_module(&module);
    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    _ = try graph.liftModuleWithCheckedCalls(&module, &checked, "module-operand.id");

    var diagnostic: Diagnostic = .{};
    const lowered = try lowerModuleWithGraphObserved(alloc, &module, &graph, &diagnostic);
    defer dnir.deinitModule(alloc, lowered);

    var take_application: ?semantic_graph.id = null;
    for (graph.applications()) |application| {
        const relation = graph.applicationRelation(application.application) orelse continue;
        const name = (graph.get(relation) orelse continue).name orelse continue;
        if (std.mem.eql(u8, name, "take")) take_application = application.application;
    }
    const application = take_application orelse return error.TestExpectedEqual;
    const subject = graph.applicationSubject(application) orelse return error.TestExpectedEqual;
    try std.testing.expect(graph.valueOrigin(subject) == .one);

    // Damage control: the realization must consume the exact value -> binding
    // edge. Removing it turns the same checked program into a named refusal;
    // the source spelling and ModuleGlobals map are still present and may not
    // reconstruct the missing semantic identity.
    var damaged = false;
    for (graph.edges.items) |*edge| {
        if (edge.from != subject or edge.kind != .binding) continue;
        edge.kind = .provenance;
        damaged = true;
        break;
    }
    try std.testing.expect(damaged);
    diagnostic.reset();
    try std.testing.expectError(
        error.GraphFactsInvalid,
        lowerModuleWithGraphObserved(alloc, &module, &graph, &diagnostic),
    );
    try std.testing.expectEqualStrings("application-operand-binding", diagnostic.note().?);
}

test "dnir_lower: immutable module integer operand consumes binding initializer fact" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const source =
        \\const fixed: i64 = 41
        \\moving: i64 = 1
        \\moving = 2
        \\take: i64 = (value: i64)
        \\    value
        \\readfixed: i64 = ()
        \\    take(fixed)
        \\readmoving: i64 = ()
        \\    take(moving)
        \\readliteral: i64 = ()
        \\    take(7)
    ;
    var lexer = @import("../lexer.zig").Lexer.init(source, "binding-initializer.id");
    var parser = @import("../parser.zig").Parser.init(&lexer, alloc);
    parser.idol_mode = true;
    var module = try parser.parse_module();
    var checked = @import("../sema.zig").Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    try checked.check_module(&module);
    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    const module_id = try graph.liftModuleWithCheckedCalls(
        &module,
        &checked,
        "binding-initializer.id",
    );

    const fixed_binding = graph.resolveInHome(module_id, "fixed", .local) orelse
        return error.TestExpectedEqual;
    const moving_binding = graph.resolveInHome(module_id, "moving", .local) orelse
        return error.TestExpectedEqual;
    const fixed_initialization = switch (graph.bindingInitialization(fixed_binding)) {
        .known => |fact| fact,
        .unvisited, .invalid => return error.TestExpectedEqual,
    };
    const moving_initialization = switch (graph.bindingInitialization(moving_binding)) {
        .known => |fact| fact,
        .unvisited, .invalid => return error.TestExpectedEqual,
    };
    try std.testing.expectEqual(@as(i64, 41), graph.exactI64(fixed_initialization.value).?);
    try std.testing.expectEqual(@as(i64, 1), graph.exactI64(moving_initialization.value).?);
    try std.testing.expectEqual(
        place.Tri.yes,
        graph.modulePlace(moving_initialization.place).?.facts.mutation,
    );

    var diagnostic: Diagnostic = .{};
    const lowered = try lowerModuleWithGraphObserved(alloc, &module, &graph, &diagnostic);
    defer dnir.deinitModule(alloc, lowered);
    var fixed_argument: ?dnir.Value = null;
    var moving_argument: ?dnir.Value = null;
    for (lowered.functions) |function| {
        const destination = if (std.mem.endsWith(u8, function.name, "__readfixed"))
            &fixed_argument
        else if (std.mem.endsWith(u8, function.name, "__readmoving"))
            &moving_argument
        else
            continue;
        for (function.blocks[0].instrs) |instruction| {
            if (instruction.op == .mov_arg and instruction.result == 0) {
                destination.* = instruction.lhs;
                break;
            }
        }
    }
    try std.testing.expect(std.meta.eql(dnir.Value{ .i64 = 41 }, fixed_argument.?));
    // Mutation/current-value is a place decision. The initialization row still
    // exists, but the operand must arrive from storage rather than as `1`.
    try std.testing.expect(switch (moving_argument.?) {
        .i64 => false,
        else => true,
    });

    // Decision-changing damage control. ModuleConsts still contains the source
    // spelling `fixed -> 41`; changing only graph-owned exact content must
    // change the staged DNIR immediate, proving this checked-operand path never
    // consults that rival map.
    const exact_row = graph.exact_i64_rows.get(fixed_initialization.value) orelse
        return error.TestExpectedEqual;
    const saved_content = graph.exact_i64_facts.items[exact_row].content;
    graph.exact_i64_facts.items[exact_row].content = 99;
    const changed = try lowerModuleWithGraphObserved(alloc, &module, &graph, &diagnostic);
    defer dnir.deinitModule(alloc, changed);
    var changed_argument: ?dnir.Value = null;
    for (changed.functions) |function| {
        if (!std.mem.endsWith(u8, function.name, "__readfixed")) continue;
        for (function.blocks[0].instrs) |instruction| {
            if (instruction.op == .mov_arg and instruction.result == 0) {
                changed_argument = instruction.lhs;
                break;
            }
        }
    }
    try std.testing.expect(std.meta.eql(dnir.Value{ .i64 = 99 }, changed_argument.?));
    graph.exact_i64_facts.items[exact_row].content = saved_content;

    // Missing claimed row is damage, not an invitation to rediscover 41 by
    // name. The candidate bit remains as the producer-domain certificate.
    const removed = graph.binding_initialization_rows.fetchRemove(fixed_binding) orelse
        return error.TestExpectedEqual;
    diagnostic.reset();
    try std.testing.expectError(
        error.GraphFactsInvalid,
        lowerModuleWithGraphObserved(alloc, &module, &graph, &diagnostic),
    );
    try std.testing.expectEqualStrings("binding-initializer", diagnostic.note().?);
    try graph.binding_initialization_rows.putNoClobber(alloc, removed.key, removed.value);

    // An unrelated exact value cannot impersonate the initializer. This is a
    // real exact-i64 application operand rather than an invalid node kind; the
    // query's module-root scope check must reject it before realization.
    const init_row = graph.binding_initialization_rows.get(fixed_binding).?;
    const saved_value = graph.binding_initializations.items[init_row].value;
    var unrelated_exact_value: ?semantic_graph.id = null;
    for (graph.exact_i64_facts.items) |fact| {
        if (fact.content != 7) continue;
        const node = graph.get(fact.value) orelse continue;
        if (node.kind != .value or node.scope == module_id) continue;
        unrelated_exact_value = fact.value;
        break;
    }
    graph.binding_initializations.items[init_row].value = unrelated_exact_value orelse
        return error.TestExpectedEqual;
    diagnostic.reset();
    try std.testing.expectError(
        error.GraphFactsInvalid,
        lowerModuleWithGraphObserved(alloc, &module, &graph, &diagnostic),
    );
    try std.testing.expectEqualStrings("binding-initializer", diagnostic.note().?);
    graph.binding_initializations.items[init_row].value = saved_value;

    // Unknown stability is also a refusal. A consumer may not collapse it to
    // immutable merely because both initializer content and source name exist.
    const fixed_place = @constCast(graph.modulePlace(fixed_initialization.place).?);
    const saved_mutation = fixed_place.facts.mutation;
    fixed_place.facts.mutation = .unknown;
    diagnostic.reset();
    try std.testing.expectError(
        error.GraphFactsInvalid,
        lowerModuleWithGraphObserved(alloc, &module, &graph, &diagnostic),
    );
    try std.testing.expectEqualStrings("binding-initializer-place", diagnostic.note().?);
    fixed_place.facts.mutation = saved_mutation;

    // A graph-known runtime binding cannot fall through to the legacy
    // `ModuleConsts.ints` entry for the same spelling. `fixed` deliberately
    // has no physical module word, so damaging only its stability to a known
    // mutable state must refuse at the storage boundary instead of staging 41.
    const saved_immutability = fixed_place.facts.immutability;
    fixed_place.facts.immutability = .no;
    diagnostic.reset();
    try std.testing.expectError(
        error.GraphFactsInvalid,
        lowerModuleWithGraphObserved(alloc, &module, &graph, &diagnostic),
    );
    try std.testing.expectEqualStrings("binding-initializer-storage", diagnostic.note().?);
    fixed_place.facts.immutability = saved_immutability;
}

test "dnir_lower: interpolation consumes nested graph value descriptor" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const source =
        \\t: i64 = 0
        \\t = t + 5
        \\stdout:write("{t}\\n")
    ;
    var lexer = @import("../lexer.zig").Lexer.init(source, "module-interpolation.id");
    var parser = @import("../parser.zig").Parser.init(&lexer, alloc);
    parser.idol_mode = true;
    var module = try parser.parse_module();
    var checked = @import("../sema.zig").Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    try checked.check_module(&module);
    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    _ = try graph.liftModuleWithCheckedCalls(&module, &checked, "module-interpolation.id");

    var diagnostic: Diagnostic = .{};
    const lowered = try lowerModuleWithGraphObserved(alloc, &module, &graph, &diagnostic);
    dnir.deinitModule(alloc, lowered);

    var interpolation_value: ?semantic_graph.id = null;
    for (graph.nodes.items, 0..) |node, coordinate| {
        if (node.kind != .value or node.ast_ref == null) continue;
        const expression: *const Expr = @ptrCast(@alignCast(node.ast_ref.?));
        if (expression.* != .name or !std.mem.eql(u8, expression.name.ident, "t")) continue;
        interpolation_value = @intCast(coordinate);
    }
    const value = interpolation_value orelse return error.TestExpectedEqual;
    var damaged = false;
    if (graph.get(value) != null) {
        graph.nodes.items[value].descriptor = .bool;
        damaged = true;
    }
    try std.testing.expect(damaged);
    diagnostic.reset();
    try std.testing.expectError(
        error.UnsupportedConstruct,
        lowerModuleWithGraphObserved(alloc, &module, &graph, &diagnostic),
    );
    try std.testing.expectEqualStrings("binop-not-lowered:concat", diagnostic.note().?);
}

