test "dnir_lower: trailing compound field assign returns updated field slot" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const src =
        \\Vec: { x: i32 }
        \\bump = (v: Vec, amt: i32): i32
        \\    v.x += amt
        \\end
    ;
    var lex = @import("../lexer.zig").Lexer.init(src, "field.id");
    var parser = @import("../parser.zig").Parser.init(&lex, alloc);
    parser.idol_mode = true;
    const mod = try parser.parse_module();
    const m = try lowerModule(alloc, &mod);
    const f = m.functions[0];
    // "The updated field slot" is whatever slot the compound assignment STORED
    // into — under the exploded-record model a one-field record parameter owns
    // slot 0, so the old proxy for it (`local != 0 and local != 1`) named a slot
    // that cannot exist here and failed on a correct lowering. Compare the ret
    // against the store instead; that is the property, and it cannot pass by
    // accident.
    var ret_count: usize = 0;
    var ret_slot: ?u32 = null;
    var store_slot: ?u32 = null;
    for (f.blocks) |b| {
        for (b.instrs) |ins| {
            if (ins.op == .store_local) store_slot = ins.result;
            if (ins.op != .ret) continue;
            ret_count += 1;
            if (ins.lhs == .local) ret_slot = ins.lhs.local;
        }
    }
    try std.testing.expectEqual(@as(usize, 1), ret_count);
    try std.testing.expect(store_slot != null);
    try std.testing.expectEqual(store_slot.?, ret_slot orelse return error.RetIsNotALocal);
}

test "dnir_lower: if binding assigns before branch" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const src =
        \\get(): i64
        \\    5
        \\end
        \\main(): i64
        \\    if v = get() v > 0
        \\        v
        \\    else
        \\        0
        \\    end
        \\end
    ;
    var lex = @import("../lexer.zig").Lexer.init(src, "ifbind.id");
    var parser = @import("../parser.zig").Parser.init(&lex, alloc);
    parser.idol_mode = true;
    const mod = try parser.parse_module();
    const m = try lowerModule(alloc, &mod);
    var saw_get_call = false;
    var saw_v_store = false;
    var br_after_store = false;
    for (m.functions) |f| {
        if (!std.mem.eql(u8, f.name, "main")) continue;
        for (f.blocks) |b| {
            var i: usize = 0;
            while (i < b.instrs.len) : (i += 1) {
                const ins = b.instrs[i];
                if (ins.op == .call_direct and std.mem.eql(u8, ins.callee, "get")) saw_get_call = true;
                if (ins.op == .store_local and ins.result != null) saw_v_store = true;
                if (saw_v_store and ins.op == .br and ins.branch_condition != .unconditional) br_after_store = true;
            }
        }
    }
    try std.testing.expect(saw_get_call);
    try std.testing.expect(saw_v_store);
    try std.testing.expect(br_after_store);
}

test "dnir_lower: ret_record carries every field in DESCRIPTOR order" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    // The literal is written OUT of declaration order on purpose. The consumer
    // reads field i from ABI slot i (or buffer offset i*8), so the descriptor
    // is the only ordering that agrees with it; walking the literal's own order
    // shipped `c`'s value in the slot the caller reads as `a`.
    const src =
        \\rec: { a: i64, b: i64, c: i64, d: i64, e: i64 }
        \\mk(): rec
        \\    return { c = 30, e = 50, a = 10, d = 40, b = 20 }
        \\end
        \\main(): i64
        \\    0
        \\end
    ;
    var lex = @import("../lexer.zig").Lexer.init(src, "retorder.id");
    var parser = @import("../parser.zig").Parser.init(&lex, alloc);
    parser.idol_mode = true;
    const mod = try parser.parse_module();
    const m = try lowerModule(alloc, &mod);

    var saw = false;
    for (m.functions) |f| {
        for (f.blocks) |b| {
            for (b.instrs) |ins| {
                if (ins.op != .ret_record) continue;
                saw = true;
                // One entry per DECLARED field, not per written field.
                try std.testing.expectEqual(@as(usize, 5), ins.vals.len);
                const want = [_]i64{ 10, 20, 30, 40, 50 };
                for (ins.vals, want) |v, w| {
                    try std.testing.expectEqual(w, v.i64);
                }
            }
        }
    }
    try std.testing.expect(saw);
}

test "dnir_lower: a record parameter's fields ride the general-purpose argument budget, not the register file" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const wide = "big: { a: i64, b: i64, c: i64, d: i64, e: i64, f: i64, g: i64, h: i64, i: i64 }\n";
    const lit = "{ a = 1, b = 2, c = 3, d = 4, e = 5, f = 6, g = 7, h = 8, i = 9 }";

    // Nine fields RETURNED: the x8 indirect-result convention covers it.
    {
        const src = wide ++ "mk(): big\n    return " ++ lit ++ "\nend\nmain(): i64\n    0\nend\n";
        var lex = @import("../lexer.zig").Lexer.init(src, "wideret.id");
        var parser = @import("../parser.zig").Parser.init(&lex, alloc);
        parser.idol_mode = true;
        const mod = try parser.parse_module();
        const m = try lowerModule(alloc, &mod);
        try std.testing.expectEqual(@as(usize, 2), m.functions.len);
    }

    // Nine fields PASSED. This asserted a REFUSAL, on the stated ground that "a
    // record parameter is homed from the argument registers only; its fields
    // are never stacked". The second half was never true of the mechanism: a
    // record field is exploded into one general-purpose word per slot, the
    // caller's `mov_arg` routes slot >= 8 into the outgoing argument block, and
    // the callee prologue's `slot_cursor` — which counts exploded fields, not
    // parameters — homes slot >= 8 out of the incoming frame. Only this
    // predicate stood between the two ends.
    {
        const src = wide ++ "take(v: big): i64\n    return v.a\nend\nmain(): i64\n    0\nend\n";
        var lex = @import("../lexer.zig").Lexer.init(src, "wideparam.id");
        var parser = @import("../parser.zig").Parser.init(&lex, alloc);
        parser.idol_mode = true;
        const mod = try parser.parse_module();
        const m = try lowerModule(alloc, &mod);
        try std.testing.expectEqual(@as(usize, 2), m.functions.len);
    }

    // SIXTEEN is the budget and it is the SCALAR budget, deliberately: eight
    // argument registers plus the eight stack slots the backend's outgoing
    // block carries. A record field spends one of those exactly as an `i64`
    // operand does, so the two cannot be different numbers.
    {
        const sixteen = "wide16: { a: i64, b: i64, c: i64, d: i64, e: i64, f: i64, g: i64, h: i64, " ++
            "i: i64, j: i64, k: i64, l: i64, m: i64, n: i64, o: i64, p: i64 }\n";
        const src = sixteen ++ "take(v: wide16): i64\n    return v.p\nend\nmain(): i64\n    0\nend\n";
        var lex = @import("../lexer.zig").Lexer.init(src, "wide16param.id");
        var parser = @import("../parser.zig").Parser.init(&lex, alloc);
        parser.idol_mode = true;
        const mod = try parser.parse_module();
        const m = try lowerModule(alloc, &mod);
        try std.testing.expectEqual(@as(usize, 2), m.functions.len);
    }

    // SEVENTEEN still refuses, and the refusal still NAMES the limit rather
    // than reporting a bare "unsupported". Past sixteen the seventeenth word
    // has nowhere physical to go — `pending_varargs` is eight slots — so this
    // is the mechanism's edge and not a policy.
    {
        const seventeen = "wide17: { a: i64, b: i64, c: i64, d: i64, e: i64, f: i64, g: i64, h: i64, " ++
            "i: i64, j: i64, k: i64, l: i64, m: i64, n: i64, o: i64, p: i64, q: i64 }\n";
        const src = seventeen ++ "take(v: wide17): i64\n    return v.q\nend\nmain(): i64\n    0\nend\n";
        var lex = @import("../lexer.zig").Lexer.init(src, "wide17param.id");
        var parser = @import("../parser.zig").Parser.init(&lex, alloc);
        parser.idol_mode = true;
        const mod = try parser.parse_module();
        try std.testing.expectError(error.UnsupportedConstruct, lowerModule(alloc, &mod));

        const fd = for (mod.body.stmts) |*st| {
            if (st.* == .func_decl and std.mem.eql(u8, st.func_decl.path[0], "take")) break &st.func_decl;
        } else return error.TestUnexpectedResult;
        var graph = semantic_graph.SemanticGraph.init(alloc);
        defer graph.deinit();
        _ = try graph.liftModuleWithCalls(&mod, "wide17param.id");
        var records: std.ArrayList(dnir.RecordDesc) = .empty;
        defer records.deinit(alloc);
        try collectRecordsFromGraph(alloc, &records, &graph);
        try collectRecordsFromModuleAliases(alloc, &records, &mod);
        const reason = functionEligibleReason(fd, records.items, &graph, &mod) orelse
            return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings(
            "record-parameter-overflows-16-gp-slots",
            reason,
        );
    }
}

test "dnir_lower: inferred parameter crosses checked applications as the existing any carrier" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    for ([_][]const u8{ "", ": any" }) |annotation| {
        for ([_]i64{ 7, 13 }) |value| {
            const source = try std.fmt.allocPrint(
                alloc,
                "identity = (value{s}) value\nmain = () identity({d})\n",
                .{ annotation, value },
            );
            var graph = semantic_graph.SemanticGraph.init(alloc);
            defer graph.deinit();
            const module = try lowerTestSourceWithGraph(alloc, source, "parameter-carrier.id", &graph);
            defer dnir.deinitModule(alloc, module);
            const identity = for (module.functions) |function| {
                if (std.mem.eql(u8, function.name, "idol_parameter_carrier__identity")) break function;
            } else return error.TestUnexpectedResult;
            try std.testing.expectEqual(@as(usize, 1), identity.params.len);
            try std.testing.expect(identity.params[0].ty == .any);
            var direct = false;
            var folded = false;
            var applications: usize = 0;
            for (identity.blocks) |block| for (block.instrs) |instruction| {
                if (instruction.op == .ret and instruction.lhs == .local and instruction.lhs.local == 0)
                    direct = true;
            };
            for (graph.application_facts.items) |fact| {
                const relation = graph.applicationRelation(fact.application) orelse continue;
                if (relation != identity.id) continue;
                const subject = graph.applicationSubject(fact.application) orelse return error.TestUnexpectedResult;
                try std.testing.expectEqual(@as(?i64, value), graph.exactI64(subject));
                applications += 1;
            }
            for (module.functions) |function| for (function.blocks) |block| for (block.instrs) |instruction| {
                if (instruction.op == .ret and instruction.lhs == .i64 and instruction.lhs.i64 == value)
                    folded = true;
            };
            try std.testing.expectEqual(@as(usize, 1), applications);
            try std.testing.expect(direct and folded);
        }
    }
}

test "dnir_lower: inferred parameter keeps the shared carrier slot limit and unsupported annotations refused" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
