            defer parameters.deinit(alloc);
            for (0..count) |index| {
                const parameter = try std.fmt.allocPrint(alloc, "{s}p{d}{s}", .{ if (index == 0) "" else ", ", index, annotation });
                try parameters.appendSlice(alloc, parameter);
            }
            const source = try std.fmt.allocPrint(alloc, "take = ({s}) p0\n", .{parameters.items});
            var lexer = @import("../lexer.zig").Lexer.init(source, "parameter-budget.id");
            var parser = @import("../parser.zig").Parser.init(&lexer, alloc);
            parser.idol_mode = true;
            const module = try parser.parse_module();
            var graph = semantic_graph.SemanticGraph.init(alloc);
            defer graph.deinit();
            _ = try graph.liftModuleWithCalls(&module, "parameter-budget.id");
            const declaration = &module.body.stmts[0].func_decl;
            const reason = functionEligibleReason(declaration, &.{}, &graph, &module);
            if (count == 16) {
                try std.testing.expect(reason == null);
            } else {
                try std.testing.expectEqualStrings("more-than-16-gp-arguments", reason orelse return error.TestUnexpectedResult);
            }
        }
    }
    for ([_][]const u8{ "?i64", "[i64]" }) |annotation| {
        const source = try std.fmt.allocPrint(alloc, "take = (value: {s}) value\n", .{annotation});
        var lexer = @import("../lexer.zig").Lexer.init(source, "parameter-refusal.id");
        var parser = @import("../parser.zig").Parser.init(&lexer, alloc);
        parser.idol_mode = true;
        const module = try parser.parse_module();
        var graph = semantic_graph.SemanticGraph.init(alloc);
        defer graph.deinit();
        _ = try graph.liftModuleWithCalls(&module, "parameter-refusal.id");
        const declaration = &module.body.stmts[0].func_decl;
        const reason = functionEligibleReason(declaration, &.{}, &graph, &module) orelse return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings("parameter-type-unsupported", reason);
    }
}

test "dnir_lower: inferred parameter and explicit any refuse floating or unknown operand descriptors" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    for ([_][]const u8{ "", ": any" }) |annotation| {
        const source = try std.fmt.allocPrint(
            alloc,
            "identity = (value{s}) value\nmain = (keep) identity(7)\n" ++
                "floating: f64 = (value: f64) value\nother: f64 = () floating(7.5)\n",
            .{annotation},
        );
        var lexer = @import("../lexer.zig").Lexer.init(source, "parameter-descriptor.id");
        var parser = @import("../parser.zig").Parser.init(&lexer, alloc);
        parser.idol_mode = true;
        var module = try parser.parse_module();
        var checked = @import("../sema.zig").Sema.init(alloc);
        defer checked.deinit();
        checked.idol_mode = true;
        try checked.check_module(&module);
        var graph = semantic_graph.SemanticGraph.init(alloc);
        defer graph.deinit();
        _ = try graph.liftModuleWithCheckedCalls(&module, &checked, "parameter-descriptor.id");
        const target = graph.relationForDeclaration(&module.body.stmts[0].func_decl).?;
        const application = for (graph.application_facts.items) |fact| {
            if (graph.applicationTarget(fact.application) == target) break fact.application;
        } else return error.TestUnexpectedResult;
        const subject = graph.applicationSubject(application).?;
        const lowered = try lowerModuleWithGraph(alloc, &module, &graph);
        defer dnir.deinitModule(alloc, lowered);
        var element: RT = .i64;
        const unsupported = [_]?RT{
            .f32,
            .f64,
            .any,
            null,
            .v8i32,
            .{ .table_type = .{ .fields = &.{} } },
            .{ .option = &element },
            .{ .array = .{ .elem = &element, .size = 2 } },
        };
        for (unsupported) |descriptor| {
            graph.nodes.items[subject].descriptor = descriptor;
            var diagnostic: Diagnostic = .{};
            try std.testing.expectError(error.GraphFactsInvalid, lowerModuleWithGraphObserved(alloc, &module, &graph, &diagnostic));
            const expected = if (descriptor == null)
                "missing-application-id"
            else if (descriptor.? == .any)
                "any-parameter-operand-unknown"
            else if (descriptor.?.is_float())
                "any-parameter-fp-operand"
            else
                "any-parameter-operand-abi";
            try std.testing.expectEqualStrings(expected, diagnostic.note().?);
        }
        var declarations: std.AutoHashMapUnmanaged(*const ast.FuncDecl, semantic_graph.id) = .empty;
        defer declarations.deinit(alloc);
        try declarations.put(alloc, &module.body.stmts[0].func_decl, target);
        graph.nodes.items[subject].descriptor = .i64;
        var diagnostic: Diagnostic = .{};
        try Parameter.admit(alloc, &graph, &declarations, &diagnostic);
        graph.nodes.items[subject].descriptor = .{ .pointer = &element };
        try Parameter.admit(alloc, &graph, &declarations, &diagnostic);
        graph.nodes.items[subject].descriptor = .f64;
        const linkage = graph.callable_linkage_rows.get(target).?;
        graph.callable_linkages.items[linkage].origin = .c;
        graph.callable_linkages.items[linkage].exposure = .c_import;
        try Parameter.admit(alloc, &graph, &declarations, &diagnostic);
    }
}

test "dnir_lower: runtime floor divisor preserves the integer zero trap" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    {
        const src =
            \\floor: i64 = (n: i64, d: i64)
            \\    n // d
        ;
        var lex = @import("../lexer.zig").Lexer.init(src, "floorzero.id");
        var parser = @import("../parser.zig").Parser.init(&lex, alloc);
        parser.idol_mode = true;
        const mod = try parser.parse_module();
        const lowered = try lowerModule(alloc, &mod);

        var saw_floor = false;
        var saw_floor_guard = false;
        var saw_floor_trap = false;
        for (lowered.functions) |function| for (function.blocks) |block| for (block.instrs) |instruction| {
            if (instruction.op == .binop and instruction.binop == .idiv) saw_floor = true;
            if (instruction.op == .binop and instruction.binop == .neq and
                instruction.rhs == .i64 and instruction.rhs.i64 == 0)
            {
                saw_floor_guard = true;
            }
            if (instruction.op == .hw_unary and std.mem.eql(u8, instruction.field, trap_abort_tag)) {
                saw_floor_trap = true;
            }
        };
        try std.testing.expect(saw_floor and saw_floor_guard and saw_floor_trap);
    }

    {
        const src =
            \\half: i64 = (n: i64)
            \\    n // 2
        ;
        var lex = @import("../lexer.zig").Lexer.init(src, "half.id");
        var parser = @import("../parser.zig").Parser.init(&lex, alloc);
        parser.idol_mode = true;
        const mod = try parser.parse_module();
        const lowered = try lowerModule(alloc, &mod);

        var saw_half = false;
        var saw_half_trap = false;
        for (lowered.functions) |function| for (function.blocks) |block| for (block.instrs) |instruction| {
            if (instruction.op == .binop and instruction.binop == .idiv) saw_half = true;
            if (instruction.op == .hw_unary and std.mem.eql(u8, instruction.field, trap_abort_tag)) {
                saw_half_trap = true;
            }
        };
        try std.testing.expect(saw_half and !saw_half_trap);
    }
}

test "dnir_lower: logical shift width does not license a negative floor divisor" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    // `-1 >> 1` is the logical value INT64_MAX. Adding one wraps to
    // INT64_MIN, so this divisor is not non-negative and must keep the general
    // floored correction. This is the exact edge that a twice-subtracted shift
    // width incorrectly admitted.
    {
        const src =
            \\answer: i64 = ()
            \\    x: i64 = -1
            \\    d: i64 = (x >> 1) + 1
            \\    1 // d
        ;
        var lex = @import("../lexer.zig").Lexer.init(src, "floor-shift-boundary.id");
        var parser = @import("../parser.zig").Parser.init(&lex, alloc);
        parser.idol_mode = true;
        const mod = try parser.parse_module();
        const lowered = try lowerModule(alloc, &mod);

        var saw_floor = false;
        for (lowered.functions) |function| for (function.blocks) |block| for (block.instrs) |instruction| {
            if (instruction.op != .binop or instruction.binop != .idiv) continue;
            saw_floor = true;
            try std.testing.expect(!instruction.divisor.proved());
        };
        try std.testing.expect(saw_floor);
    }

    // The repair is not a wholesale disable. A positive constant divisor
    // still bounds `%`, the following `+ 1` remains below 2^63, and the floor
    // application therefore keeps its cheaper non-negative-divisor form.
    {
        const src =
            \\answer: i64 = ()
            \\    x: i64 = -1
            \\    d: i64 = (x % 100) + 1
            \\    1 // d
        ;
        var lex = @import("../lexer.zig").Lexer.init(src, "floor-positive-bound.id");
        var parser = @import("../parser.zig").Parser.init(&lex, alloc);
        parser.idol_mode = true;
        const mod = try parser.parse_module();
        const lowered = try lowerModule(alloc, &mod);

        var saw_floor = false;
        for (lowered.functions) |function| for (function.blocks) |block| for (block.instrs) |instruction| {
            if (instruction.op != .binop or instruction.binop != .idiv) continue;
            saw_floor = true;
            try std.testing.expect(instruction.divisor.proved());
        };
        try std.testing.expect(saw_floor);
    }
}

test "dnir_lower: a global byte-sequence literal keeps its element descriptor" {
    // GAP-145 (`law.text.byte`): the global's place descriptor comes from the
    // producer quote identity, not from the fact that a quoted face was written.
    // A single-quoted literal is a byte sequence; collapsing it to `.str` makes
    // the global observe the retired unified string identity.
    const loc = @import("../lexer.zig").Loc{ .line = 1, .col = 1, .file = "quote.id" };

    const bytes = Expr{ .quoted = .{ .loc = loc, .val = "ab", .quote = .bytes } };
    const bytes_ty = typeOfGlobal(.inferred, &bytes);
    try std.testing.expect(bytes_ty == .array);
    try std.testing.expect(bytes_ty.array.elem.* == .u8);

    // The text faces keep text; the byte face is the only divergence.
    for ([_]ast.Quote{ .text, .compat_text, .compat_long, .host }) |q| {
        const text = Expr{ .quoted = .{ .loc = loc, .val = "ab", .quote = q } };
        try std.testing.expect(typeOfGlobal(.inferred, &text) == .str);
    }
}

test "dnir_lower: checked quote classification fails closed on damaged graph descriptor" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const source =
        \\entry: str = ()
        \\    "left" .. "right"
    ;
    var lexer = @import("../lexer.zig").Lexer.init(source, "quote-damage.id");
    var parser = @import("../parser.zig").Parser.init(&lexer, alloc);
    parser.idol_mode = true;
    var module = try parser.parse_module();
    var checked = @import("../sema.zig").Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    try checked.check_module(&module);
    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    _ = try graph.liftModuleWithCheckedCalls(&module, &checked, "quote-damage.id");

    // Positive control: the checked producer-to-consumer path accepts the
    // ordinary text concat before the fact is damaged.
    const baseline = try lowerModuleWithGraph(alloc, &module, &graph);
    defer dnir.deinitModule(alloc, baseline);

    const tail = module.body.stmts[0].func_decl.func.body.tail_expr orelse
        return error.TestExpectedEqual;
    try std.testing.expect(tail.* == .binop and tail.binop.op == .concat);
    const left = tail.binop.lhs;
    const value = graph.sourceQuoteValue(left) orelse return error.TestExpectedEqual;
    try std.testing.expect(graph.get(value).?.descriptor.? == .str);

    // Damage control: only the graph descriptor changes. The AST remains a
    // double-quoted face, so the retired `.quoted => true` fallback would keep
    // this green. The graph consumer must instead refuse the inconsistent
    // operand before any DNIR or machine realization is published.
    const saved = graph.nodes.items[value].descriptor;
    graph.nodes.items[value].descriptor = .i64;
    defer graph.nodes.items[value].descriptor = saved;
    var diagnostic: Diagnostic = .{};
    try std.testing.expectError(
        error.UnsupportedConstruct,
        lowerModuleWithGraphObserved(alloc, &module, &graph, &diagnostic),
    );
    try std.testing.expectEqualStrings("binop-not-lowered:concat", diagnostic.note().?);
}

test "dnir_lower: the quote face has ONE producer, and its reach is total over module bindings" {
    // DELETION WITNESS, MADE EXECUTABLE.
    //
    // `quotedIsModuleTextConst` reads `expr.quoted.quote` off the AST. That is
    // a SECOND authority on text-vs-bytes beside `semantic_graph`'s
    // `publishSourceQuote`, and `law.md` §1 forbids a downstream phase
    // reconstructing from syntax a fact a producer already published. GAP-207
    // measured what a disagreement in this exact space costs: three ASLR'd
    // pointers rendered through `%lld`, compile 0, run 0, no diagnostic.
    //
    // `collectModuleConsts` was moved to the graph (`graphTextConst`). The AST
    // reader survives at exactly ONE call site — `moduleConstTableKind` — and
    // only because that verdict's other caller is `codegen.zig:3722`, and
    // `codegen.zig` imports `semantic_graph.zig` ZERO times.
    //
    // DELETION CONDITION, checked here and not asserted in prose:
    //   1. the two authorities AGREE on every module-binding literal, and
    //   2. the graph's reach is TOTAL over them — every such literal HAS a fact.
    // (2) is the half that was false at `b64dc075`: `publishSourceQuote` was
    // reachable only from `addApplicationValue`, so a literal that was not an
    // application operand published nothing, and this file's own test
    // `semantic_graph: lifted quoted literals publish source quote facts`
    // asserted 2 and found 0.
    //
    // When `codegen.zig` can ask the graph, delete `quotedIsModuleTextConst`,
    // route `moduleConstTableKind` through `graphTextConst`, and delete this
    // test's clause (1) with it — clause (2) stays, because it is the reach the
    // consumer depends on.
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const src =
        \\t: str = "hi"
        \\b = 'b'
        \\const c = "cc"
        \\global names = { "alpha", "beta" }
        \\entry: str = ()
        \\    local inner = 'z'
        \\    t
    ;
    var lex = @import("../lexer.zig").Lexer.init(src, "quotewitness.id");
    var parser = @import("../parser.zig").Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var mod = try parser.parse_module();
    var checked = @import("../sema.zig").Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    try checked.check_module(&mod);
    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    _ = try graph.liftModuleWithCheckedCalls(&mod, &checked, "quotewitness.id");

    const Seen = struct {
        var literals: usize = 0;
        fn check(g: *const semantic_graph.SemanticGraph, e: *const Expr) !void {
            switch (e.*) {
                .quoted => {
                    literals += 1;
                    // (2) REACH IS TOTAL: the producer published for this literal.
                    try std.testing.expect(g.sourceQuoteValue(e) != null);
                    // (1) THE TWO AUTHORITIES AGREE.
                    try std.testing.expectEqual(quotedIsModuleTextConst(e), graphTextConst(g, e));
                },
                .table => |tbl| for (tbl.fields) |f| switch (f) {
                    .positional => |p| try check(g, p),
                    .named => |n| try check(g, n.val),
                    else => {},
                },
                else => {},
            }
        }
    };
    for (mod.body.stmts) |*stmt| switch (stmt.*) {
        .local_decl => |ld| for (ld.inits) |seed| try Seen.check(&graph, seed),
        .const_decl => |cd| try Seen.check(&graph, cd.val),
        .global_decl => |gd| for (gd.inits) |seed| try Seen.check(&graph, seed),
        .assign => |as| for (as.values) |v| try Seen.check(&graph, v),
        else => {},
    };
    // A POSITIVE CONTROL FOR THE ZERO. Without this the whole test passes on a
    // fixture the walk never reached, which is how a witness rots.
    try std.testing.expect(Seen.literals >= 5);

    // AND THE BYTE FACE IS STILL DISTINGUISHED. If the graph ever answered
    // "text" for `b = 'b'`, clauses (1) and (2) would both still hold and the
    // fact would be worthless.
    var text_faces: usize = 0;
    var byte_faces: usize = 0;
    for (graph.source_quote_facts.items) |fact| switch (fact.quote) {
        .bytes => byte_faces += 1,
        else => text_faces += 1,
    };
    try std.testing.expect(byte_faces >= 2);
    try std.testing.expect(text_faces >= 4);
}

test "dnir_lower: module positional integer tables require graph facts" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const src =
        \\global xs = { 10, 20 }
        \\main: i64 = ()
        \\    0
    ;
    var lex = @import("../lexer.zig").Lexer.init(src, "module_const_table_graph.id");
    var parser = @import("../parser.zig").Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var mod = try parser.parse_module();

    // Positive control: after the producer runs, the graph-backed verdict
    // recognizes the positional integer table.
    var checked = @import("../sema.zig").Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    // The graph lift consumes checked callable-linkage facts.  This test is a
    // graph-fact control, so run the authoritative Sema producer rather than
    // relying on the former permissive lift to reconstruct a relation.
    try checked.check_module(&mod);
    _ = try graph.liftModuleWithCheckedCalls(&mod, &checked, "module_const_table_graph.id");
    const table = switch (mod.body.stmts[0]) {
        .global_decl => |d| d.inits[0],
        else => return error.UnexpectedStatement,
    };
    try std.testing.expectEqual(ModuleTableKind.int, moduleConstTableKindGraph(&graph, true, &mod, "xs", table));

    // Mutating the source tree cannot change the graph-owned content fact.
    table.table.fields[0].positional.int_lit.val = 99;
    try std.testing.expectEqual(ModuleTableKind.int, moduleConstTableKindGraph(&graph, true, &mod, "xs", table));
    try std.testing.expectEqual(@as(?i64, 10), graph.exactI64OfExpr(table.table.fields[0].positional));

    // Negative control: a graph that was never given the literal facts must
    // fail closed, rather than re-reading the AST and admitting the table.
    var missing = semantic_graph.SemanticGraph.init(alloc);
    defer missing.deinit();
    try std.testing.expectEqual(@as(?ModuleTableKind, null), moduleConstTableKindGraph(&missing, true, &mod, "xs", table));
}

/// GAP-204 constant-index control rig. a93930e6 gave `lowerExprCons`'
/// constant-index arm a module-const fallback
/// (`module_consts.strs/ints.get("{s}.{d}")`) with NO read-site verdict
/// check: safety rests entirely on `collectModuleConsts` recording only what
/// the shared `moduleConstTableKindGraph` verdict admits. This rig measures
/// that contract at the exact map the fallback reads.
///
/// The source is parsed without a graft: the positional text elements must
/// reach sema, graph lift, the shared verdict and collection as one chain.
const Gap204ConstIndex = struct {
    mod: ast.Module,
    graph: semantic_graph.SemanticGraph,
    consts: ModuleConsts,
    table: *const Expr,
    verdict: ?ModuleTableKind,
};

fn gap204CollectConstIndex(alloc: std.mem.Allocator, src: []const u8) !Gap204ConstIndex {
    var lex = @import("../lexer.zig").Lexer.init(src, "gap204_const_index.id");
    var parser = @import("../parser.zig").Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var mod = try parser.parse_module();
    var table: ?*const Expr = null;
    for (mod.body.stmts) |*stmt| {
        if (stmt.* != .global_decl) continue;
        const gd = stmt.global_decl;
        if (gd.names.len != 1 or gd.inits.len != 1) continue;
        if (!std.mem.eql(u8, gd.names[0].ident, "strs")) continue;
        if (gd.inits[0].* != .table) continue;
        const fields = gd.inits[0].table.fields;
        if (fields.len != 2) continue;
        const first = if (fields[0] == .positional) fields[0].positional else continue;
        const second = if (fields[1] == .positional) fields[1].positional else continue;
        if (first.* != .quoted or second.* != .quoted) continue;
        if (first.quoted.quote != .text or second.quoted.quote != .text) continue;
        table = gd.inits[0];
    }
    const bound = table orelse return error.Gap204StrsTableMissing;
    var checked = @import("../sema.zig").Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    try checked.check_module(&mod);
    var graph = semantic_graph.SemanticGraph.init(alloc);
    errdefer graph.deinit();
    _ = try graph.liftModuleWithCheckedCalls(&mod, &checked, "gap204_const_index.id");
    const verdict = moduleConstTableKindGraph(&graph, true, &mod, "strs", bound);
    var consts = try collectModuleConsts(alloc, &mod, &graph, true);
    errdefer consts.deinit(alloc);
    return .{ .mod = mod, .graph = graph, .consts = consts, .table = bound, .verdict = verdict };
}

/// Lower one constant-index read `strs[idx]` through the real `lowerExprCons`
/// `.index` arm — the exact a93930e6 fallback lines — with a hand-built read
/// node, which carries no graph occurrence and therefore reaches the fallback
/// rather than the aggregate path. Returns the answered value, or the refusal
/// when the table was never recorded.
fn gap204ConstIndexRead(
    alloc: std.mem.Allocator,
    graph: *const semantic_graph.SemanticGraph,
    consts: *const ModuleConsts,
    idx: i64,
) !dnir.Value {
    const l: @import("../source_cursor.zig").Loc = .{ .file = "gap204_const_index.id", .line = 1, .col = 1 };
    var obj: Expr = .{ .name = .{ .loc = l, .ident = "strs" } };
    var key: Expr = .{ .int_lit = .{ .loc = l, .val = idx } };
    const read: Expr = .{ .index = .{ .loc = l, .obj = &obj, .key = &key } };
    var diagnostic: Diagnostic = .{};
    var occurrences = try OccurrenceBridge.init(alloc, graph, &diagnostic);
    defer occurrences.deinit();
    var externs: std.ArrayList(dnir.Extern) = .empty;
    defer externs.deinit(alloc);
    var func_record_returns: std.StringHashMapUnmanaged([]const u8) = .empty;
    defer func_record_returns.deinit(alloc);
    var entity_linkage: std.AutoHashMapUnmanaged(semantic_graph.id, []const u8) = .empty;
    defer entity_linkage.deinit(alloc);
    var ctx: LowerCtx = .{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .records = &.{},
        .graph = graph,
        .occurrences = &occurrences,
        .require_graph_facts = true,
        .externs = &externs,
        .func_record_returns = &func_record_returns,
        .entity_linkage = &entity_linkage,
        .module_consts = consts,
    };
    defer ctx.deinit();
    return lowerExprCons(&ctx, &read, .single);
}

test "dnir_lower: GAP-204 constant-index read answers recorded text, refuses written/rebound tables" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const clean_src =
        \\global strs = { "alpha", "beta" }
        \\main: i64 = ()
        \\    0
    ;
    // POSITIVE: the shared verdict admits the untouched table, the recording
    // holds both elements under the exact keys the fallback spells, and the
    // read answers the recorded literal — twice, identically.
    {
        var rig = try gap204CollectConstIndex(alloc, clean_src);
        defer rig.graph.deinit();
        defer rig.consts.deinit(alloc);
        try std.testing.expectEqual(ModuleTableKind.text, rig.verdict);
        try std.testing.expectEqualStrings("alpha", rig.consts.strs.get("strs.1").?);
        try std.testing.expectEqualStrings("beta", rig.consts.strs.get("strs.2").?);
        try std.testing.expectEqual(@as(?i64, 2), rig.consts.ints.get("strs.len"));
        try std.testing.expect(rig.consts.str_tables.contains("strs"));
        const first = try gap204ConstIndexRead(alloc, &rig.graph, &rig.consts, 2);
        try std.testing.expect(first == .str);
        try std.testing.expectEqualStrings("beta", first.str);
        // Determinism re-check: an independent collection and an independent
        // read answer the same literal, so no run answers stale or blank.
        var rig2 = try gap204CollectConstIndex(alloc, clean_src);
        defer rig2.graph.deinit();
        defer rig2.consts.deinit(alloc);
        const second = try gap204ConstIndexRead(alloc, &rig2.graph, &rig2.consts, 2);
        try std.testing.expect(second == .str);
        try std.testing.expectEqualStrings(first.str, second.str);
    }
    // NEGATIVE (write): `strs[1] = "changed"` is an integer-indexed write, so
    // the binding-stability count cannot see it — the shared verdict must.
    // Nothing is recorded, so the constant-index read refuses instead of
    // answering the original element.
    {
        const write_src =
            \\global strs = { "alpha", "beta" }
            \\strs[1] = "changed"
            \\main: i64 = ()
            \\    0
        ;
        var rig = try gap204CollectConstIndex(alloc, write_src);
        defer rig.graph.deinit();
        defer rig.consts.deinit(alloc);
        try std.testing.expectEqual(@as(?ModuleTableKind, null), rig.verdict);
        try std.testing.expect(rig.consts.strs.get("strs.1") == null);
        try std.testing.expect(rig.consts.strs.get("strs.2") == null);
        try std.testing.expect(!rig.consts.str_tables.contains("strs"));
        try std.testing.expectError(error.UnsupportedConstruct, gap204ConstIndexRead(alloc, &rig.graph, &rig.consts, 2));
    }
    // NEGATIVE (rebound): a second binding replaces the table, so the
    // stability count already skips it and the verdict agrees. The read
    // refuses rather than answering either generation's element.
    {
        const rebound_src =
            \\global strs = { "alpha", "beta" }
            \\strs = { "x", "y" }
            \\main: i64 = ()
            \\    0
        ;
        var rig = try gap204CollectConstIndex(alloc, rebound_src);
        defer rig.graph.deinit();
        defer rig.consts.deinit(alloc);
        try std.testing.expectEqual(@as(?ModuleTableKind, null), rig.verdict);
        try std.testing.expect(rig.consts.strs.get("strs.1") == null);
        try std.testing.expect(rig.consts.strs.get("strs.2") == null);
        try std.testing.expect(!rig.consts.str_tables.contains("strs"));
        try std.testing.expectError(error.UnsupportedConstruct, gap204ConstIndexRead(alloc, &rig.graph, &rig.consts, 2));
    }
}

test "dnir_lower: GAP-204 out-of-range constant index refuses the admitted text table" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const clean_src =
        \\global strs = { "alpha", "beta" }
        \\main: i64 = ()
        \\    0
    ;
    var rig = try gap204CollectConstIndex(alloc, clean_src);
    defer rig.graph.deinit();
    defer rig.consts.deinit(alloc);
    // The table IS admitted — verdict and both elements recorded — so this
    // measures the fallback's missing-key arm, not the unrecorded-table
    // refusal the constant-index negative controls already pin.
    try std.testing.expectEqual(ModuleTableKind.text, rig.verdict);
    try std.testing.expectEqualStrings("beta", rig.consts.strs.get("strs.2").?);
    // Tables are 1-indexed: 0 and len + 1 name no recorded key, so the read
    // bails instead of answering a neighbour element or a blank. The
    // compile-time analog of the unguarded-load refusal `constTableRead`
    // already pins for register-exploded tables.
    try std.testing.expectError(error.UnsupportedConstruct, gap204ConstIndexRead(alloc, &rig.graph, &rig.consts, 0));
    try std.testing.expectError(error.UnsupportedConstruct, gap204ConstIndexRead(alloc, &rig.graph, &rig.consts, 3));
}

test "dnir_lower: a module const of INT_MIN lowers instead of crashing the compiler" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    // THE REPORTED P0-A DEFECT, verbatim. `collectModuleConsts` read this
    // binding through `intLiteralStep`, whose `-u.operand.int_lit.val` was bare
    // host negation, and `idol run` died with
    //
    //     thread N panic: integer overflow
    //     src/dnir_lower.zig:5970:42: in intLiteralStep
    //                 break :blk -u.operand.int_lit.val;
    //
    // on a program whose only unusual feature is a valid i64 constant.
    const src =
        \\floor = -9223372036854775808
        \\near = -9223372036854775807
        \\main: i64 = ()
        \\    if floor < near return 0
        \\    1
    ;
    var lex = @import("../lexer.zig").Lexer.init(src, "floor.id");
    var parser = @import("../parser.zig").Parser.init(&lex, alloc);
    parser.idol_mode = true;
    const mod = try parser.parse_module();
    _ = try lowerModule(alloc, &mod);

    // The recorded constant is the exact value the source wrote, so the fold
    // that reads it cannot silently disagree with the program.
    const bound = switch (mod.body.stmts[0]) {
        .local_decl => |d| d.inits[0],
        .const_decl => |d| d.val,
        .global_decl => |d| d.inits[0],
        .assign => |a| a.values[0],
        else => return error.UnexpectedStatement,
    };
    try std.testing.expectEqual(@as(?i64, std.math.minInt(i64)), ast.intLiteralValue(bound));
}

test "dnir_lower: same-spelled local shadows module storage by binding" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const src =
        \\ring: i64 = 0
        \\set: i64 = ()
        \\    ring = 7
        \\    0
        \\shadow: i64 = ()
        \\    ring: i64 = 5
        \\    ring
        \\main: i64 = ()
        \\    shadow()
        \\    set()
        \\    ring
    ;
    var lex = @import("../lexer.zig").Lexer.init(src, "gap228-shadow.id");
    var parser = @import("../parser.zig").Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var module = try parser.parse_module();
    var checked = @import("../sema.zig").Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    try checked.check_module(&module);
    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    _ = try graph.liftModuleWithCheckedCalls(&module, &checked, "gap228-shadow.id");
    var diagnostic: Diagnostic = .{};
    const lowered = try lowerModuleWithGraphObserved(alloc, &module, &graph, &diagnostic);
    defer dnir.deinitModule(alloc, lowered);

    var saw_shadow = false;
    var saw_local_store = false;
    var saw_wrong_global_store = false;
    var saw_main_global_read = false;
    for (lowered.functions) |function| {
        if (!std.mem.eql(u8, function.name, "main")) {
            saw_shadow = true;
            var function_has_local = false;
            var function_has_global_ring = false;
            for (function.blocks) |block| for (block.instrs) |instruction| {
                if (instruction.op == .store_local) function_has_local = true;
                if (instruction.op == .store_global and
                    std.mem.eql(u8, instruction.field, "ring")) function_has_global_ring = true;
            };
            if (function_has_local) {
                saw_local_store = true;
                saw_wrong_global_store = function_has_global_ring;
            }
        }
        if (std.mem.eql(u8, function.name, "main")) {
            for (function.blocks) |block| for (block.instrs) |instruction| {
                if (instruction.op == .load_global and
                    std.mem.eql(u8, instruction.field, "ring")) saw_main_global_read = true;
            };
        }
    }
    try std.testing.expect(saw_shadow);
    try std.testing.expect(saw_local_store);
    try std.testing.expect(!saw_wrong_global_store);
    // Negative control: the module binding remains real storage for a caller
    // after the local shadow's scope ends.
    try std.testing.expect(saw_main_global_read);
}

test "dnir_lower: a module write below a closed shadow block reaches the module word" {
    // gap[228], the extent half. The graph adjudicates this program exactly:
    // its `mutations` column names the MODULE binding, written by `deep`,
    // because the inner declaration's roster entry is gone by the time
    // `ring = 2` is lifted (`liftBindingsInBlock`). The lowering's `ctx.locals`
    // had no such extent, so the leaked shadow slot captured the write and the
    // module word kept its initializer — measured on `--backend=wasm`: the
    // program answered 0 where the answer is 2.
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const src =
        \\ring: i64 = 0
        \\deep: i64 = ()
        \\    if ring > 100
        \\        ring: i64 = 5
        \\        return ring
        \\    ring = 2
        \\    3
        \\main: i64 = ()
        \\    deep()
        \\    ring
    ;
    var lex = @import("../lexer.zig").Lexer.init(src, "gap228-extent.id");
    var parser = @import("../parser.zig").Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var module = try parser.parse_module();
    var checked = @import("../sema.zig").Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    try checked.check_module(&module);
    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    _ = try graph.liftModuleWithCheckedCalls(&module, &checked, "gap228-extent.id");
    var diagnostic: Diagnostic = .{};
    const lowered = try lowerModuleWithGraphObserved(alloc, &module, &graph, &diagnostic);
    defer dnir.deinitModule(alloc, lowered);

    var saw_deep = false;
    var deep_writes_module_word = false;
    var saw_main_global_read = false;
    for (lowered.functions) |function| {
        if (std.mem.eql(u8, function.name, "main")) {
            for (function.blocks) |block| for (block.instrs) |instruction| {
                if (instruction.op == .load_global and
                    std.mem.eql(u8, instruction.field, "ring")) saw_main_global_read = true;
            };
            continue;
        }
        saw_deep = true;
        for (function.blocks) |block| for (block.instrs) |instruction| {
            if (instruction.op == .store_global and
                std.mem.eql(u8, instruction.field, "ring")) deep_writes_module_word = true;
        };
    }
    try std.testing.expect(saw_deep);
    // The write below the closed block is the module write the graph already
    // published; a leaked shadow slot swallowing it is the recorded defect.
    try std.testing.expect(deep_writes_module_word);
    try std.testing.expect(saw_main_global_read);
}

test "fieldindex: module field write reaches the index consumer" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const src =
        \\M = { x = 1 }
        \\bump: i64 = ()
        \\    M.x = 2
        \\    0
        \\main: i64 = ()
        \\    bump()
        \\    M.x
    ;
    var lex = @import("../lexer.zig").Lexer.init(src, "gap219-index-hit.id");
    var parser = @import("../parser.zig").Parser.init(&lex, alloc);
    parser.idol_mode = true;
    var module = try parser.parse_module();
    var owner: ?*const ast.Stmt = null;
    for (module.body.stmts) |*st| {
        if (st.* != .assign) continue;
        if (st.assign.targets.len != 1) continue;
        if (st.assign.targets[0].* != .name) continue;
        if (!std.mem.eql(u8, st.assign.targets[0].name.ident, "M")) continue;
        owner = st;
    }
    const o = owner orelse return error.TestUnexpectedResult;
    try std.testing.expect(try moduleHasFieldWrite(alloc, &module.body, o, "M"));
}

