test "fieldindex: production existence refuses a drifted authority set" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const first = [_]fieldindex.Write{
        .{ .owner = 0, .name = "M", .field = "x", .kind = 0, .shadowed = false },
    };
    const second = [_]fieldindex.Write{
        .{ .owner = 0, .name = "M", .field = "y", .kind = 0, .shadowed = false },
    };
    try std.testing.expect(try fieldWriteExists(alloc, &first, "M", "x"));
    try std.testing.expect(!try fieldWriteExists(alloc, &second, "M", "x"));
    try std.testing.expect(!try fieldWriteExists(alloc, &[_]fieldindex.Write{}, "M", "x"));
    var index = try fieldindex.build(alloc, &first);
    defer index.deinit(alloc);
    if (fieldindex.hasWrite(&index, &second, 0, "M", "x")) |_| {
        return error.TestUnexpectedResult;
    } else |e| {
        try std.testing.expectEqual(fieldindex.FieldError.StaleIndex, e);
    }
}

/// One module, lifted the way `lowerModuleFromGraph`'s callers lift it, so a
/// test asks the same graph the compiler asks — places included.
fn testLiftedGlobals(
    alloc: std.mem.Allocator,
    graph: *semantic_graph.SemanticGraph,
    mod: *ast.Module,
    src: []const u8,
    file: []const u8,
) !ModuleGlobals {
    var lex = @import("../lexer.zig").Lexer.init(src, file);
    var parser = @import("../parser.zig").Parser.init(&lex, alloc);
    parser.idol_mode = true;
    mod.* = try parser.parse_module();
    var checked = @import("../sema.zig").Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    try checked.check_module(mod);
    _ = try graph.liftModuleWithCheckedCalls(mod, &checked, file);
    return collectModuleGlobals(alloc, mod, graph);
}

test "dnir_lower: a module collection §18 rules absent takes no __DATA word" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    // THE DEFECT, VERBATIM. `global k = 7` lowered and answered; the collection
    // beside it — as constant as the scalar, element for element — was refused
    // `DNB001 lowerModuleFromGraph() — global-init-not-constant:t`, because
    // `ModuleGlobals` registered ONE i64 word for a THREE-element binding and
    // `constGlobalInit` then had no word-sized value to compute. The refusal's
    // name was not its reason: nothing about `(10, 20, 30)` is non-constant.
    const src =
        \\global t = (10, 20, 30)
        \\global k = 7
        \\main: i64 = ()
        \\    t[2] + k
    ;
    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    var mod: ast.Module = undefined;
    var globals = try testLiftedGlobals(alloc, &graph, &mod, src, "absent_collection.id");
    defer globals.deinit(alloc);

    // No word, so no load-time value is owed and the module is not refused.
    try std.testing.expect(!globals.has("t"));
    // The scalar beside it is untouched: a module scalar IS one word.
    try std.testing.expect(globals.has("k"));

    // AND THE CENSUS IS THE REASON, not the spelling. `residencyRefusal` is the
    // published proof that the aggregate needs no location anywhere; the
    // storage decision consumes exactly that fact.
    const p = graph.placeNamed("t") orelse return error.MissingPlace;
    try std.testing.expectEqual(place.Shape.collection, p.shape);
    try std.testing.expectEqual(place.Refusal.none, place.residencyRefusal(p));
    try std.testing.expectEqual(place.Residency.absent, place.ruledResidency(p));
}

test "dnir_lower: a written module aggregate keeps its word and stays refused" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    // THE NEGATIVE CONTROL FOR THE ABOVE, and the containment `05882930`
    // landed. A relation writes `M.A`, so `M` is not absent, keeps its word,
    // and every read of it must still fail closed rather than answer the stale
    // literal 3. Admitting this shape is the wrong-answer class the whole
    // residency route exists to avoid.
    const src =
        \\global mm = { a = 3 }
        \\bump: i64 = ()
        \\    mm.a = 9
        \\    mm.a
        \\main: i64 = ()
        \\    mm.a
    ;
    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    var mod: ast.Module = undefined;
    var globals = try testLiftedGlobals(alloc, &graph, &mod, src, "written_aggregate.id");
    defer globals.deinit(alloc);

    try std.testing.expect(globals.has("mm"));
    const p = graph.placeNamed("mm") orelse return error.MissingPlace;
    try std.testing.expect(place.residencyRefusal(p) != .none);
    try std.testing.expectEqual(place.Residency.static, place.ruledResidency(p));
}

// A RUNTIME INDEX INTO A KNOWN TABLE FOLDS, AND IT FOLDS OFF THE GRAPH.
//
// The measured gap this pins: `while i <= 4 : s += t[i]` over a table whose
// contents AND index range are both compile-time known cost 30 machine
// instructions, while the identical loop with the table removed cost 2. The
// fold recognizer had been keyed on the retired `t(i)` application face;
// `comptime.foldRelationBody` refused ANY body carrying a published aggregate
// projection, so the canonical `t[i]` face lost the fold entirely.
//
// FOUR ROWS, AND THE LAST TWO ARE THE POINT.
//
//   * the loop folds — one `ret 10` and no dense table, which is the
//     two-instruction machine floor `gate/collapse.sh` pins at 2;
//   * a WRITTEN table does not fold, and keeps its `load_index`;
//   * an OUT-OF-RANGE trip count does not fold, because the running program
//     would have trapped and a fold that answers is a different program;
//   * the initializer EXPRESSION is poisoned to `.nil` with the graph facts
//     intact and the fold still answers 10. That is the whole reason the
//     admission exists: `Evaluator.eval`'s `.index` arm reads `exactI64` off
//     the member VALUE, so the source table is provenance and never the
//     second authority on its own contents.
test "dnir_lower: a runtime index into a determined table folds from graph facts" {
    const Lexer = @import("../lexer.zig").Lexer;
    const Parser = @import("../parser.zig").Parser;
    const Sema = @import("../sema.zig").Sema;
    const table_apply = @import("../table_apply.zig");

    const Case = struct {
        name: []const u8,
        source: []const u8,
        folds: bool,
        answer: i64,
    };
    const cases = [_]Case{
        .{
            .name = "determined.id",
            .folds = true,
            .answer = 10,
            .source =
            \\main: i64 = ()
            \\    t = (1, 2, 3, 4, 5, 6, 7, 8)
            \\    s = 0
            \\    i = 1
            \\    while i <= 4
            \\        s += t[i]
            \\        i += 1
            \\    s
            ,
        },
        .{
            // Duplicates everywhere but slot 1, so an off-by-one index answers
            // 30 and the correct read answers 22. A fold that is fast and
            // wrong is visible in the CONSTANT, not only in the count.
            .name = "offbyone.id",
            .folds = true,
            .answer = 22,
            .source =
            \\main: i64 = ()
            \\    t = (1, 7, 7, 7, 9, 7, 7, 7)
            \\    s = 0
            \\    i = 1
            \\    while i <= 4
            \\        s += t[i]
            \\        i += 1
            \\    s
            ,
        },
        .{
            .name = "written.id",
            .folds = false,
            .answer = 0,
            .source =
            \\main: i64 = ()
            \\    t: [4]i64 = {1, 2, 3, 4}
            \\    t[2] = 50
            \\    s = 0
            \\    i = 1
            \\    while i <= 4
            \\        s += t[i]
            \\        i += 1
            \\    s
            ,
        },
        .{
            .name = "outofrange.id",
            .folds = false,
            .answer = 0,
            .source =
            \\main: i64 = ()
            \\    t = (1, 2, 3)
            \\    s = 0
            \\    i = 1
            \\    while i <= 5
            \\        s += t[i]
            \\        i += 1
            \\    s
            ,
        },
    };

    for (cases) |case| {
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const alloc = arena.allocator();

        var lexer = Lexer.init(case.source, case.name);
        var parser = Parser.init(&lexer, alloc);
        parser.idol_mode = true;
        var module = try parser.parse_module();
        var checked = Sema.init(alloc);
        defer checked.deinit();
        checked.idol_mode = true;
        try checked.check_module(&module);
        table_apply.normalizeModule(alloc, &module, &checked.type_map);

        var graph = semantic_graph.SemanticGraph.init(alloc);
        defer graph.deinit();
        _ = try graph.liftModuleWithCheckedCalls(&module, &checked, module.file);

        var access: ?*const semantic_graph.ApplicationFact = null;
        for (graph.applications()) |application| {
            if (graph.aggregateAccess(application.application)) |fact| access = fact;
        }
        // The folding rows must have a published projection — that is the fact
        // the admission is keyed on. A refusing row need not: `written.id`'s
        // table is mutated, and the graph declines to publish the access at
        // all rather than publishing one this fold would have to re-check.
        if (case.folds) try std.testing.expect(access != null);

        const lowered = try lowerModuleWithGraph(alloc, &module, &graph);
        defer dnir.deinitModule(alloc, lowered);

        var entry: ?dnir.Function = null;
        for (lowered.functions) |function| {
            if (std.mem.eql(u8, function.name, "main")) entry = function;
        }
        const main_fn = entry orelse return error.TestExpectedEqual;

        if (!case.folds) {
            try std.testing.expect(!main_fn.folded_to_constant);
            var saw_load = false;
            for (main_fn.blocks) |block| {
                for (block.instrs) |instruction| {
                    if (instruction.op == .load_index) saw_load = true;
                }
            }
            try std.testing.expect(saw_load);
            continue;
        }

        // THE FOLDED FORM, not merely the answer: one instruction, a `ret`
        // carrying the constant, and no dense table left behind for a reader
        // that no longer exists.
        try std.testing.expect(main_fn.folded_to_constant);
        try std.testing.expectEqual(@as(usize, 1), main_fn.blocks.len);
        try std.testing.expectEqual(@as(usize, 1), main_fn.blocks[0].instrs.len);
        try std.testing.expectEqual(dnir.Op.ret, main_fn.blocks[0].instrs[0].op);
        try std.testing.expectEqual(dnir.Value{ .i64 = case.answer }, main_fn.blocks[0].instrs[0].lhs);
        try std.testing.expectEqual(@as(usize, 0), lowered.dense_tables.len);

        // THE GRAPH IS THE AUTHORITY ON THE CONTENTS. Poison the initializer
        // expression, keep every graph fact, and require the same constant.
        var table: ?semantic_graph.id = null;
        var row: usize = 0;
        while (row < graph.aggregateCount()) : (row += 1) {
            const aggregate_fact = graph.aggregateAt(row) orelse continue;
            if (!graph.aggregateIsSoleImmutableBinding(aggregate_fact.aggregate)) continue;
            try std.testing.expect(table == null);
            table = aggregate_fact.aggregate;
        }
        const aggregate = table orelse return error.TestExpectedEqual;
        const initializer = @constCast(graph.valueExpression(aggregate) orelse
            return error.TestExpectedEqual);
        const saved = initializer.*;
        initializer.* = .{ .nil = saved.loc() };
        const relowered = try lowerModuleWithGraph(alloc, &module, &graph);
        defer dnir.deinitModule(alloc, relowered);
        initializer.* = saved;

        var relowered_entry: ?dnir.Function = null;
        for (relowered.functions) |function| {
            if (std.mem.eql(u8, function.name, "main")) relowered_entry = function;
        }
        const relowered_main = relowered_entry orelse return error.TestExpectedEqual;
        try std.testing.expect(relowered_main.folded_to_constant);
        try std.testing.expectEqual(@as(usize, 1), relowered_main.blocks[0].instrs.len);
        try std.testing.expectEqual(
            dnir.Value{ .i64 = case.answer },
            relowered_main.blocks[0].instrs[0].lhs,
        );
    }
}

// ════════════════════════════════════════════════════════════════════════════
// GAP-221 — THE GUARD'S PREMISE, MEASURED.
//
// `moduleFieldWord` admits the module's field word only when
// `graph.bindingNamedIn(relation, base)` yields a binding whose scope IS
// `graph.module_root`. THOSE TWO CONDITIONS CANNOT BOTH HOLD.
// `bindingNamedIn` skips every node whose `enclosingCallable` is not the
// relation it was asked about, and a module-scope binding's enclosing callable
// is the module — so the query answers null for the module's binding and
// answers a relation-scoped binding for a shadow. The guard declines in both
// cases, and a module table field's `__DATA` word is therefore unreachable
// from every relation body, including the one that genuinely wrote it.
//
// MEASURED THROUGH THE LUA FACE ON PURPOSE. The `.id` acceptance run cannot be
// obtained while the grammar is mid-transfer: at 2954038e nothing parsed at all
// (no typed binding, no descriptor, no subject relation), and at 29d77ed0 a
// module carrying MORE THAN ONE RELATION still does not, which is every fixture
// this gap owns (GAP-145). The lift is the same lift for both faces and this
// question is asked of the lift's output, so the face the source wore does not
// enter it — which is why this measurement held unchanged across both heads
// while the grammar moved under it.
test "dnir_lower: GAP-221 a module field base is unresolvable from a relation body" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const src =
        \\M = { x = 1 }
        \\
        \\function poke()
        \\  M.x = 7
        \\  return M.x
        \\end
        \\
        \\function bump(M)
        \\  M.x = 99
        \\  return M.x
        \\end
    ;
    var lex = @import("../lexer.zig").Lexer.init(src, "gap221.lua");
    var parser = @import("../parser.zig").Parser.init(&lex, alloc);
    const module = try parser.parse_module();

    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    const mod_id = try graph.liftModule(&module, "gap221.lua");

    const poke = graph.resolveInHome(mod_id, "poke", .func) orelse
        return error.TestExpectedEqual;
    const bump = graph.resolveInHome(mod_id, "bump", .func) orelse
        return error.TestExpectedEqual;

    // THE CONTROL. `bump`'s `M` is its own parameter, so the query resolves it
    // and its scope is not the module's. The guard declines, and declining is
    // RIGHT here: the shadow's write is not the module's.
    const shadow = graph.bindingNamedIn(bump, "M") orelse
        return error.TestExpectedEqual;
    try std.testing.expect(graph.get(shadow).?.scope != graph.module_root);

    // THE DEFECT. `poke` declares no `M` at all, so its `M.x = 7` is a write to
    // the MODULE's binding — and the query has nothing to answer with, so the
    // guard declines the very word that write owns. The two arms are the same
    // `orelse return null`, which is why one repair produced both answers.
    try std.testing.expect(graph.bindingNamedIn(poke, "M") == null);
}

/// GAP-204 runtime-index control rig. The gap's ACCEPTANCE CRITERION is a
/// runtime index — `strs[i]` must answer the recorded element, and a written or
/// rebound table must refuse — and until now only the CONSTANT-index arm was
/// pinned (`lowerExprCons`'s `module_consts` fallback). This rig measures the
/// other arm: `lowerDynamicIndex`'s select chain over `module_consts`, which is
/// the path that printed a pointer in every experiment recorded in the gap.
///
/// Three facts, because the chain's correctness rests on all three and each has
/// its own failure:
///
///   - the elements it selects are the recorded ones, in index order;
///   - the result SLOT's `str` marking agrees with `exprIsStr` on the SAME
///     node — the disagreement `lowerDynamicIndex`'s own comment names;
///   - the range decision survives, because the chain's out-of-range answer is
///     the zero it initialized, marked as text.
///
/// `gap204CollectConstIndex` parses the positional text elements directly, so
/// this also pins the complete source-to-runtime-index lowering chain.
const Gap204DynRead = struct {
    /// The lowered read, or null when lowering refused it.
    value: ?dnir.Value,
    /// `emitIndexBoundsTrap`'s extent operand, or null when no trap was emitted.
    trap_len: ?i64,
    /// Whether the result slot was published as holding text.
    str_marked: bool,
    /// `exprIsStr` on the same `.index` node — the second classifier.
    expr_is_str: bool,
    /// Every `.str` operand stored into a slot by the chain, in emission order.
    selected: []const []const u8,
};

/// Collect the module, optionally publish a static place plan naming the table,
/// then lower `strs[i]` — a NAME key, so `ast.intLiteralValue` declines and the
/// read reaches the select chain.
///
/// `static_plan` is written straight onto the graph rather than produced by
/// running the census through `lower.collectStaticPlaces`: this file is the
/// BACKEND, and importing the enforcement selector to manufacture a fact it
/// consumes is the layering the gate forbids (`gate/layering.rules`). The
/// consumer contract is what needs pinning anyway — the chain's range decision
/// must not depend on this fact whatever produced it — and the producer-side
/// measurement (a watched runtime read leaves the place `.bounded`, so no plan
/// is offered) is recorded in `gaps/GAP-204.md` with the probe that took it.
fn gap204DynRead(alloc: std.mem.Allocator, src: []const u8, static_plan: bool) !Gap204DynRead {
    var rig = try gap204CollectConstIndex(alloc, src);
    defer rig.graph.deinit();
    defer rig.consts.deinit(alloc);

    if (static_plan) {
        var plans: std.StringHashMapUnmanaged(void) = .empty;
        try plans.put(alloc, "strs", {});
        rig.graph.static_places = plans;
    }

    const l: @import("../source_cursor.zig").Loc = .{ .file = "gap204_dyn_index.id", .line = 1, .col = 1 };
    var obj: Expr = .{ .name = .{ .loc = l, .ident = "strs" } };
    var key: Expr = .{ .name = .{ .loc = l, .ident = "i" } };
    const read: Expr = .{ .index = .{ .loc = l, .obj = &obj, .key = &key } };
    var diagnostic: Diagnostic = .{};
    var occurrences = try OccurrenceBridge.init(alloc, &rig.graph, &diagnostic);
    defer occurrences.deinit();
    var externs: std.ArrayList(dnir.Extern) = .empty;
    defer externs.deinit(alloc);
    var func_record_returns: std.StringHashMapUnmanaged([]const u8) = .empty;
    defer func_record_returns.deinit(alloc);
    var entity_linkage: std.AutoHashMapUnmanaged(semantic_graph.id, []const u8) = .empty;
    defer entity_linkage.deinit(alloc);
    var ctx: LowerCtx = .{
        .alloc = alloc,
        .diagnostic = &diagnostic,
        .records = &.{},
        .graph = &rig.graph,
        .occurrences = &occurrences,
        .require_graph_facts = true,
        .externs = &externs,
        .func_record_returns = &func_record_returns,
        .entity_linkage = &entity_linkage,
        .module_consts = &rig.consts,
    };
    defer ctx.deinit();
    const expr_is_str = exprIsStr(&ctx, &read);
    const value: ?dnir.Value = lowerExprCons(&ctx, &read, .single) catch null;

    var trap_len: ?i64 = null;
    var selected: std.ArrayList([]const u8) = .empty;
    for (ctx.instrs.items) |instruction| {
        if (instruction.op == .hw_unary and std.mem.eql(u8, instruction.field, index_bounds_tag))
            trap_len = instruction.rhs.i64;
        if (instruction.op == .store_local and instruction.lhs == .str)
            try selected.append(alloc, try alloc.dupe(u8, instruction.lhs.str));
    }
    const str_marked = if (value) |v| switch (v) {
        .local => |slot| ctx.str_slots.contains(slot),
        else => false,
    } else false;
    return .{
        .value = value,
        .trap_len = trap_len,
        .str_marked = str_marked,
        .expr_is_str = expr_is_str,
        .selected = try selected.toOwnedSlice(alloc),
    };
}

test "dnir_lower: GAP-204 the runtime-index select chain selects recorded text and keeps its range decision" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    // POSITIVE, with no plan published — the ordinary case. Both recorded
    // elements reach the chain in index order, the two classifiers agree that
    // the read holds text, and the range decision is emitted over the recorded
    // extent.
    {
        const rig = try gap204DynRead(alloc,
            \\global strs = { "alpha", "beta" }
            \\i = 2
            \\main: i64 = ()
            \\    stdout:write(strs[i])
            \\    0
        , false);
        try std.testing.expect(rig.value != null);
        try std.testing.expect(rig.value.? == .local);
        try std.testing.expect(rig.str_marked);
        try std.testing.expect(rig.expr_is_str);
        try std.testing.expectEqual(@as(?i64, 2), rig.trap_len);
        try std.testing.expectEqual(@as(usize, 2), rig.selected.len);
        try std.testing.expectEqualStrings("alpha", rig.selected[0]);
        try std.testing.expectEqualStrings("beta", rig.selected[1]);

        // Determinism: an independent collection and an independent lowering
        // select the same elements in the same order, so no run answers stale.
        const again = try gap204DynRead(alloc,
            \\global strs = { "alpha", "beta" }
            \\i = 2
            \\main: i64 = ()
            \\    stdout:write(strs[i])
            \\    0
        , false);
        try std.testing.expectEqual(rig.selected.len, again.selected.len);
        for (rig.selected, again.selected) |first, second|
            try std.testing.expectEqualStrings(first, second);
        try std.testing.expectEqual(rig.trap_len, again.trap_len);
    }

    // THE STATIC-PLAN CONTROL, and the reason the elision is gone. A plan
    // naming this table is published on the graph and the chain is still
    // emitted for a runtime index. Before the repair this combination emitted
    // NO range decision, and the chain's answer for an index outside `1..len`
    // was the zero it initialized, published as text.
    //
    // The producer can reach this combination: measured with a throwaway probe
    // over the real `lower.collectStaticPlaces`, a module whose only read of
    // `strs` the census does not walk leaves the place `determinacy=.exact`
    // and IS offered the plan, while a module whose runtime read the census
    // does walk leaves it `.bounded` and is not. That measurement is recorded
    // in `gaps/GAP-204.md`; it cannot be re-taken here, because a backend may
    // not import the enforcement selector to build the fact it consumes.
    {
        const rig = try gap204DynRead(alloc,
            \\global strs = { "alpha", "beta" }
            \\i = 2
            \\main: i64 = ()
            \\    0
        , true);
        try std.testing.expect(rig.str_marked);
        try std.testing.expectEqual(@as(?i64, 2), rig.trap_len);
    }

    // NEGATIVE (write): an integer-indexed write means nothing is recorded, so
    // the chain has no length and no elements and the read refuses instead of
    // selecting the original generation. `exprIsStr` refuses the same node, so
    // no consumer treats the refused read as text either. Both negatives run
    // WITH a plan published, so the refusal is the recording's, not something
    // the plan's absence happened to produce.
    {
        const rig = try gap204DynRead(alloc,
            \\global strs = { "alpha", "beta" }
            \\strs[1] = "changed"
            \\i = 2
            \\main: i64 = ()
            \\    stdout:write(strs[i])
            \\    0
        , true);
        try std.testing.expect(rig.value == null);
        try std.testing.expect(!rig.expr_is_str);
        try std.testing.expectEqual(@as(?i64, null), rig.trap_len);
        try std.testing.expectEqual(@as(usize, 0), rig.selected.len);
    }

    // NEGATIVE (rebound): a second binding replaces the table, so neither
    // generation may be assumed and the chain refuses rather than selecting
    // either one.
    {
        const rig = try gap204DynRead(alloc,
            \\global strs = { "alpha", "beta" }
            \\strs = { "x", "y" }
            \\i = 2
            \\main: i64 = ()
            \\    stdout:write(strs[i])
            \\    0
        , true);
        try std.testing.expect(rig.value == null);
        try std.testing.expect(!rig.expr_is_str);
        try std.testing.expectEqual(@as(?i64, null), rig.trap_len);
        try std.testing.expectEqual(@as(usize, 0), rig.selected.len);
    }
}

test "dnir_lower: GAP-204 module lowering carries a positional text read into the relation" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const alloc = arena.allocator();
    const source =
        \\global strs = { "alpha", "beta", "gamma" }
        \\i = 2
        \\main: i64 = ()
        \\    stdout:write(strs[i])
        \\    0
    ;
    var lexer = @import("../lexer.zig").Lexer.init(source, "gap204_module.id");
    var parser = @import("../parser.zig").Parser.init(&lexer, alloc);
    parser.idol_mode = true;
    var module = try parser.parse_module();
    var checked = @import("../sema.zig").Sema.init(alloc);
    defer checked.deinit();
    checked.idol_mode = true;
    try checked.check_module(&module);
    var graph = semantic_graph.SemanticGraph.init(alloc);
    defer graph.deinit();
    _ = try graph.liftModuleWithCheckedCalls(&module, &checked, module.file);

    var diagnostic: Diagnostic = .{};
    const lowered = try lowerModuleWithGraphObserved(alloc, &module, &graph, &diagnostic);
    defer dnir.deinitModule(alloc, lowered);

    var relation: ?*const dnir.Function = null;
    for (lowered.functions) |*function| {
        if (std.mem.eql(u8, function.name, "main")) relation = function;
    }
    const main = relation orelse return error.TestExpectedEqual;
    var extent: ?i64 = null;
    var selected: std.ArrayListUnmanaged([]const u8) = .empty;
    for (main.blocks) |block| {
        for (block.instrs) |instruction| {
            if (instruction.op == .hw_unary and
                std.mem.eql(u8, instruction.field, index_bounds_tag))
                extent = instruction.rhs.i64;
            if (instruction.op == .store_local and instruction.lhs == .str)
                try selected.append(alloc, instruction.lhs.str);
        }
    }
    try std.testing.expectEqual(@as(?i64, 3), extent);
    try std.testing.expectEqual(@as(usize, 3), selected.items.len);
    try std.testing.expectEqualStrings("alpha", selected.items[0]);
    try std.testing.expectEqualStrings("beta", selected.items[1]);
    try std.testing.expectEqualStrings("gamma", selected.items[2]);
}

test "dnir_lower: record parameters refuse unproved carriers" {
    const sources = [_][]const u8{
        "record: {code: i64}\nread = (value: record): i64 value.code\nmain: i64 = ()\n    item = {code = 7}\n    copy, item.code = item, \"changed\"\n    read(copy)\n",
        "record: {code: i64}\nread = (value: record): i64 value.code\nmain: i64 = ()\n    item = {code = 7}\n    peer = item\n    copy, peer.code = item, \"changed\"\n    read(copy)\n",
        "record: {code: i64}\nread = (value: record): i64 value.code\nmain: i64 = () read(7)\n",
        "record: {code: i64}\nread = (value: record): i64 value.code\nmain: i64 = ()\n    item = {code = \"changed\"}\n    read(item)\n",
    };
    for (sources) |source| {
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const alloc = arena.allocator();
        var graph = semantic_graph.SemanticGraph.init(alloc);
        defer graph.deinit();
        try std.testing.expectError(error.GraphFactsInvalid, lowerTestSourceWithGraph(alloc, source, "record-carrier.id", &graph));
    }
}

